    try:
        from scapy.layers.dhcp import BOOTP, DHCP
        HAVE_DHCP = True
    except ImportError:
        HAVE_DHCP = False
    try:
        conf.verb = 0
    except AttributeError:
        pass
    HAVE_SCAPY = True


