# ---- High-contrast variants (Section 22 accessibility) ---------------------
# Generated from the same canonical palette so every widget that themes for
# Light/Dark themes for High Contrast too, and switching between any two
# palettes is lossless (verified by a test: every palette is one-to-one).
def _hex_rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def _rgb_hex(r, g, b):
    return "#%02x%02x%02x" % (max(0, min(255, int(r))),
                              max(0, min(255, int(g))),
                              max(0, min(255, int(b))))


def _hex_lum(h):
    r, g, b = (c / 255.0 for c in _hex_rgb(h))
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def _hex_mix(h, target, t):
    a, b = _hex_rgb(h), _hex_rgb(target)
    return _rgb_hex(*(a[i] + (b[i] - a[i]) * t for i in range(3)))


def _build_hc_palettes():
    used = set(LIGHT_TO_DARK_HEX) | set(LIGHT_TO_DARK_HEX.values())
    light_hc, dark_hc = {}, {}

    def unique(h):
        r, g, b = _hex_rgb(h)
        while h in used:
            b = (b + 1) % 256
            h = _rgb_hex(r, g, b)
        used.add(h)
        return h

    borders = {"#cfd6e0": ("#4a5260", "#9aa3b2"),
               "#e0e2e8": ("#4a5260", "#8a93a3")}
    for canon, dk in LIGHT_TO_DARK_HEX.items():
        lum = _hex_lum(canon)
        if canon in borders:
            light_hc[canon] = unique(borders[canon][0])
            dark_hc[canon] = unique(borders[canon][1])
        elif lum > 0.75:                      # surfaces
            light_hc[canon] = canon           # identity: already max contrast
            dark_hc[canon] = unique(_hex_mix(dk, "#000000", 0.65))
        else:                                 # text and accent colours
            light_hc[canon] = unique(_hex_mix(canon, "#000000", 0.5))
            dark_hc[canon] = unique(_hex_mix(dk, "#ffffff", 0.55))
    return light_hc, dark_hc


HC_LIGHT_HEX, HC_DARK_HEX = _build_hc_palettes()
PALETTES = {"Light": {}, "Dark": LIGHT_TO_DARK_HEX,
            "Light HC": HC_LIGHT_HEX, "Dark HC": HC_DARK_HEX}

# any known palette colour -> its canonical (light) colour
_CANON = {}
for _pname, _tbl in PALETTES.items():
    for _canon, _val in _tbl.items():
        if _val != _canon:
            _CANON[_val] = _canon


# 5.1.2 M8: the interface scale. px(n) is a size in pixels at 100 %;
# fixed window sizes and widths go through it.
UI_SCALE = [1.0]


def px(n):
    return int(round(n * UI_SCALE[0]))


def px_geo(geo):
    """'560x620' (or '560x620+10+20') at the interface scale."""
    m = re.match(r"^(\d+)x(\d+)(.*)$", str(geo))
    if not m or UI_SCALE[0] == 1.0:
        return geo
    return f"{px(int(m.group(1)))}x{px(int(m.group(2)))}{m.group(3)}"


def enable_dpi_awareness():
    """Windows only, before the first window: draw at the real resolution
    (system-aware; Tk 8.6 can't re-scale per monitor). Any failure keeps
    today's behaviour. → True when the call worked."""
    if not IS_WINDOWS or not FEATURES.get("dpi", True):
        return False
    try:
        import ctypes
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(1)
            return True
        except (AttributeError, OSError):
            ctypes.windll.user32.SetProcessDPIAware()
            return True
    except Exception:                               # noqa: BLE001
        LOG.debug("DPI awareness", exc_info=True)
        return False


UI_SCALE_CHOICES = ("Automatic", "100 %", "125 %", "150 %", "200 %")


def apply_ui_scale(root, choice="Automatic"):
    """Automatic: the screen's own DPI (Windows after the DPI call; most
    Linux desktops); a percentage: that, also for text (tk scaling) —
    which helps a desktop that reports the wrong DPI."""
    try:
        auto = float(root.winfo_fpixels("1i")) / 96.0
    except (tk.TclError, ValueError):
        auto = 1.0
    m = re.match(r"^(\d+)\s*%$", str(choice or ""))
    if m:
        scale = int(m.group(1)) / 100.0
        with contextlib.suppress(tk.TclError):
            root.tk.call("tk", "scaling", scale * 96.0 / 72.0)
    else:
        scale = auto
    UI_SCALE[0] = max(1.0, min(3.0, scale))
    with contextlib.suppress(NameError):
        Charts.forget_fonts()
    return UI_SCALE[0]


_SYSTEM_THEME = []


def system_theme():
    """Light or Dark as the operating system is set (read once)."""
    if _SYSTEM_THEME:
        return _SYSTEM_THEME[0]
    dark = False
    try:
        if IS_WINDOWS:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                r"Software\Microsoft\Windows\CurrentVersion"
                                r"\Themes\Personalize") as k:
                dark = winreg.QueryValueEx(k, "AppsUseLightTheme")[0] == 0
        elif IS_MAC:
            r = subprocess.run(["defaults", "read", "-g",
                                "AppleInterfaceStyle"], capture_output=True,
                               text=True, timeout=3)
            dark = "dark" in (r.stdout or "").lower()
        else:
            r = subprocess.run(["gsettings", "get",
                                "org.gnome.desktop.interface",
                                "color-scheme"], capture_output=True,
                               text=True, timeout=3)
            dark = "dark" in (r.stdout or "").lower()
    except Exception as e:                          # noqa: BLE001
        LOG.debug("system theme unknown, using Light: %s", e)
        dark = False
    _SYSTEM_THEME.append("Dark" if dark else "Light")
    return _SYSTEM_THEME[0]


def resolve_theme(name):
    return system_theme() if name == "System" else (name or "Light")


def palette_name(theme, high_contrast, cvd=None):
    """Light/Dark, + " HC", + " deutan|protan|tritan" (colour-blind)."""
    theme = resolve_theme(theme)
    cvd = CVD_STATE["mode"] if cvd is None else cvd
    return f"{theme}{' HC' if high_contrast else ''}" + \
        (f" {cvd}" if cvd else "")


def _theme_variant(base, palette):
    """Derive a theme-token dict for `palette` from an existing one."""
    table = PALETTES[palette]
    out = {}
    for k, v in base.items():
        canon = _CANON.get(v, v)
        if canon in table:
            out[k] = table[canon]
        elif palette.startswith("Dark") and palette.endswith("HC"):
            out[k] = _hex_mix(v, "#000000", 0.65) if _hex_lum(v) < 0.2 \
                else _hex_mix(v, "#ffffff", 0.55)
        elif palette == "Light HC":
            out[k] = _hex_mix(v, "#000000", 0.5) if _hex_lum(v) < 0.6 else v
        else:
            out[k] = v
    return out


THEMES = {
    "Light": THEME_LIGHT, "Dark": THEME_DARK,
    "Light HC": _theme_variant(THEME_LIGHT, "Light HC"),
    "Dark HC": _theme_variant(THEME_DARK, "Dark HC"),
}
# accents used for selection/focus must stay readable in every palette
THEMES["Light HC"]["accent"] = "#0a246a"
THEMES["Dark HC"]["accent"] = "#ffd400"
THEMES["Light HC"]["focus"] = "#0a246a"
THEMES["Dark HC"]["focus"] = "#ffd400"
THEMES["Light HC"]["line_hi"] = "#0a246a"
THEMES["Dark HC"]["line_hi"] = "#ffd400"
THEMES["Dark HC"]["grid"] = "#4a5260"
THEMES["Light HC"]["grid"] = "#9aa3b2"

# ---- Colour-blind modes (Settings → Accessibility) --------------------------
# The three most common kinds of colour blindness. Each mode recolours the
# meaning-carrying colours (good / warning / danger, charts, confidence,
# the map) so they stay distinct for that kind of vision; surfaces and
# greys are unchanged. Every status also keeps its icon and word, so colour
# is never the only signal. The chosen triples were picked by simulating
# each kind of vision (Machado et al. 2009) — a self-test re-checks them.
CVD_LABELS = {"Off": "",
              "Red-green — deuteranopia (most common)": "deutan",
              "Red-green — protanopia": "protan",
              "Blue-yellow — tritanopia": "tritan"}
CVD_STATE = {"mode": ""}
CVD_TRIPLES = {
    # (mode, dark): good, warn, danger
    ("deutan", False): ("#1e74ae", "#a36a00", "#760a31"),
    ("deutan", True): ("#1aacff", "#ffb81a", "#f15a91"),
    ("protan", False): ("#1e74ae", "#a36a00", "#80001c"),
    ("protan", True): ("#4dbfff", "#eee12a", "#f56c56"),
    ("tritan", False): ("#1e8385", "#805800", "#cc002c"),
    ("tritan", True): ("#4dffce", "#c8b45a", "#ff4d73"),
}
# canonical (light) colours that carry a meaning → which role they play
CVD_ROLES = {"#0b6b3a": "good", "#8a5a00": "warn", "#8a1a08": "danger",
             "#a01a08": "danger", "#a05608": "warn", "#e07b00": "warn"}
# Machado, Oliveira & Fernandes (2009), severity 1.0, linear RGB
CVD_MATRICES = {
    "protan": ((0.152286, 1.052583, -0.204868),
               (0.114503, 0.786281, 0.099216),
               (-0.003882, -0.048116, 1.051998)),
    "deutan": ((0.367322, 0.860646, -0.227968),
               (0.280085, 0.672501, 0.047413),
               (-0.011820, 0.042940, 0.968881)),
    "tritan": ((1.255528, -0.076749, -0.178779),
               (-0.078411, 0.930809, 0.147602),
               (0.004733, 0.691367, 0.303900)),
}


def _srgb_lin(c):
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


def cvd_lab(hexcol, mode=""):
    """CIE Lab of a colour as seen with `mode` colour vision ("" = normal)."""
    r, g, b = (_srgb_lin(c / 255.0) for c in _hex_rgb(hexcol))
    if mode:
        m = CVD_MATRICES[mode]
        r, g, b = (max(0.0, min(1.0, m[i][0] * r + m[i][1] * g +
                                m[i][2] * b)) for i in range(3))
    x = (0.4124 * r + 0.3576 * g + 0.1805 * b) / 0.95047
    y = 0.2126 * r + 0.7152 * g + 0.0722 * b
    z = (0.0193 * r + 0.1192 * g + 0.9505 * b) / 1.08883

    def f(t):
        return t ** (1 / 3) if t > 0.008856 else 7.787 * t + 16 / 116
    return 116 * f(y) - 16, 500 * (f(x) - f(y)), 200 * (f(y) - f(z))


def cvd_delta(a, b, mode=""):
    # math.dist is Python 3.8+; MiniWireshark runs on 3.7
    return math.sqrt(sum((p - q) ** 2 for p, q in zip(
        cvd_lab(a, mode), cvd_lab(b, mode))))


def wcag_contrast(a, b):
    def lum(h):
        r, g, bb = (_srgb_lin(c / 255.0) for c in _hex_rgb(h))
        return 0.2126 * r + 0.7152 * g + 0.0722 * bb
    la, lb = sorted((lum(a), lum(b)), reverse=True)
    return (la + 0.05) / (lb + 0.05)


def _cvd_shift(hexcol, mode, dark):
    """Move a saturated colour's hue to the mode's safe colour for its
    role (green → good, red → danger, amber → warn), keeping lightness."""
    import colorsys
    r, g, b = (c / 255.0 for c in _hex_rgb(hexcol))
    h, l_, s = colorsys.rgb_to_hls(r, g, b)
    if s < 0.25 or l_ < 0.06 or l_ > 0.97:
        return hexcol
    deg = h * 360
    role = "good" if 75 <= deg < 170 else "danger" if (
        deg >= 340 or deg < 15) else "warn" if 15 <= deg < 60 else ""
    if not role:
        return hexcol
    tgt = CVD_TRIPLES[(mode, dark)][("good", "warn", "danger").index(role)]
    th, _tl, ts = colorsys.rgb_to_hls(*(c / 255.0 for c in _hex_rgb(tgt)))
    r, g, b = colorsys.hls_to_rgb(th, l_, max(ts * 0.9, min(s, ts)))
    return _rgb_hex(r * 255, g * 255, b * 255)


def _build_cvd_palettes():
    taken = {}                       # palette value → canonical colour
    for tbl in PALETTES.values():
        for canon, val in tbl.items():
            taken.setdefault(val, canon)
    for canon in LIGHT_TO_DARK_HEX:
        taken.setdefault(canon, canon)

    def unique(h, canon):
        r, g, b = _hex_rgb(h)
        while taken.get(h, canon) != canon:
            b = (b + 1) % 256
            h = _rgb_hex(r, g, b)
        taken[h] = canon
        return h
    for base in ("Light", "Dark", "Light HC", "Dark HC"):
        dark = base.startswith("Dark")
        for mode in ("deutan", "protan", "tritan"):
            src = PALETTES[base]
            tbl = {}
            primary = ("#0b6b3a", "#8a5a00", "#8a1a08")   # the token colours
            for canon in sorted(LIGHT_TO_DARK_HEX,
                                key=lambda c: c not in primary):
                role = CVD_ROLES.get(canon)
                if role:
                    val = CVD_TRIPLES[(mode, dark)][
                        ("good", "warn", "danger").index(role)]
                else:
                    val = _cvd_shift(src.get(canon, canon), mode, dark)
                tbl[canon] = unique(val, canon)
            name = f"{base} {mode}"
            PALETTES[name] = tbl
            for canon, val in tbl.items():
                if val != canon:
                    _CANON[val] = canon
            out = {}
            for k, v in THEMES[base].items():
                c = _CANON.get(v, v)
                out[k] = tbl.get(c) or _cvd_shift(v, mode, dark)
            for tok, canon in (("good_fg", "#0b6b3a"), ("warn_fg", "#8a5a00"),
                               ("danger_fg", "#8a1a08")):
                out[tok] = tbl[canon]
            THEMES[name] = out


_build_cvd_palettes()


def set_colorblind_mode(label_or_code):
    code = CVD_LABELS.get(label_or_code, label_or_code or "")
    CVD_STATE["mode"] = code if code in ("deutan", "protan",
                                         "tritan") else ""
    return CVD_STATE["mode"]



@functools.lru_cache(maxsize=65536)
def _is_private_cached(ip):
    try:
        a = ipaddress.ip_address(ip)
    except ValueError:
        return False
    return any(a.version == n.version and a in n for n in PRIVATE_NETS)


def is_private_ip(ip):
    """Memoised: called several times per packet (busy networks repeat the
    same few hundred addresses endlessly)."""
    if not ip or not isinstance(ip, str):
        return False
    return _is_private_cached(ip)


def _human_bytes(n):
    n = float(n or 0)
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024
    return f"{n:.1f} GB"


@functools.lru_cache(maxsize=65536)
def _is_public_cached(ip):
    try:
        a = ipaddress.ip_address(ip)
    except ValueError:
        return False
    return not a.is_private and not a.is_multicast and not a.is_loopback \
        and not a.is_link_local and not a.is_reserved and \
        not a.is_unspecified


def is_public_ip(ip):
    if not ip or not isinstance(ip, str):
        return False
    return _is_public_cached(ip)


def _int_to_ip(n):
    try:
        return _socket.inet_ntoa(struct.pack("!I", int(n) & 0xffffffff))
    except Exception:
        return "0.0.0.0"


def local_subnet_for(iface, my_ip):
    """Best-effort: the directly-connected IPv4 subnet for this interface,
    so the active scan only ever touches your own local Wi-Fi/LAN — never
    anything beyond your router."""
    if not my_ip:
        return None
    iface_name = str(getattr(iface, "name", iface) or "")
    try:
        for entry in conf.route.routes:
            try:
                net, mask, gw, rif, addr = entry[0], entry[1], entry[2], \
                    entry[3], entry[4]
            except Exception:
                continue
            if addr != my_ip or not net:
                continue
            if gw not in ("0.0.0.0", "", "*", None):
                continue
            r_name = str(getattr(rif, "name", rif) or "")
            if iface_name and r_name != iface_name:
                continue
            try:
                return ipaddress.ip_network(
                    f"{_int_to_ip(net)}/{_int_to_ip(mask)}", strict=False)
            except Exception:
                continue
    except Exception as e:                           # noqa: BLE001
        LOG.debug("route table unreadable: %s", e)
    # 5.3.4 (LG-08): no "/24" guess: on a /28 hotel or a /30 link it swept
    # addresses outside your network. Unknown subnet, no ARP sweep
    return None


_UNSAFE_TEXT = re.compile(
    "[\x00-\x08\x0b-\x1f\x7f-\x9f\u200b-\u200f\u202a-\u202e"
    "\u2060-\u2064\u2066-\u2069\ufeff\ufff9-\ufffb]")


def sanitize_text(value, limit=200):
    """Make a string that came off the network (or out of a file) safe to
    show: strips control characters and the invisible bidirectional
    overrides that can make 'evil.com' look like 'moc.live', folds tabs and
    newlines to spaces and caps the length. Applied where untrusted names
    enter the program (decoder, session/label loading)."""
    if value is None:
        return ""
    if not isinstance(value, str):
        if isinstance(value, bytes):
            value = value.decode("utf-8", "replace")
        else:
            value = str(value)
    if value.isprintable() and len(value) <= limit:
        return value
    value = value.replace("\t", " ").replace("\r", " ").replace("\n", " ")
    value = _UNSAFE_TEXT.sub("", value)
    return value[:limit]


def _name_bytes(raw):
    if raw is None:
        return ""
    if isinstance(raw, bytes):
        # 5.3.4 (QA-08): names travel as UTF-8 ("café-laptop"); idna is
        # only for xn-- labels, latin-1 only for bytes that aren't UTF-8
        try:
            out = raw.decode("utf-8")
        except UnicodeError:
            out = raw.decode("latin-1")
        if out.isascii() and "xn--" in out.lower():
            with contextlib.suppress(UnicodeError, ValueError):
                out = raw.decode("idna")
        return sanitize_text(out.rstrip("."), 255)
    return sanitize_text(str(raw).rstrip("."), 255)


# NS, MD, MF, CNAME, PTR, DNAME: rdata that is a domain name
_DNS_NAME_TYPES = (2, 3, 4, 5, 12, 39)
# record types scapy parses into their own classes (DNSRRMX, DNSRRSOA,
# DNSRRSRV, DNSRROPT, DNSRRHTTPS…), which _iter_rrs() doesn't yield; the
# fast decoder skips them too, so both decoders show the same answers
_DNS_SKIPPED_TYPES = frozenset((6, 13, 15, 33, 35, 41, 43, 46, 47, 48, 50,
                                51, 64, 65, 250, 32769))


def _iter_rrs(rr):
    """Yield each DNSRR record from a DNS answer/ns/ar field. Handles both
    how current scapy represents it (a plain list of DNSRR) and the older
    linked '.payload' chain, so this keeps working across scapy versions."""
    if rr is None:
        return
    if isinstance(rr, (list, tuple)):
        for item in rr:
            if isinstance(item, DNSRR):
                yield item
        return
    while rr is not None and isinstance(rr, DNSRR):
        yield rr
        nxt = rr.payload
        rr = nxt if isinstance(nxt, DNSRR) else None


def _rdata_ip(rr):
    """The plain IP string for an A/AAAA record, however this scapy
    version represents it: a ready-made string (current scapy's
    IPField/IP6Field) or raw bytes (older scapy)."""
    rd = rr.rdata
    if rr.type == 1:
        if isinstance(rd, str):
            return rd
        if isinstance(rd, bytes) and len(rd) == 4:
            return ".".join(str(b) for b in rd)
    elif rr.type == 28:
        if isinstance(rd, str):
            return rd
        if isinstance(rd, bytes) and len(rd) == 16:
            return ":".join(f"{(rd[i] << 8) | rd[i + 1]:x}"
                            for i in range(0, 16, 2))
    return None


def _rdata_str(rr):
    return sanitize_text(_rdata_str_raw(rr), 255)


def _rdata_str_raw(rr):
    rd = rr.rdata
    if isinstance(rd, str):
        return rd.rstrip(".")
    if isinstance(rd, bytes):
        if rr.type in _DNS_NAME_TYPES:   # a name: decode it like any other
            return _name_bytes(rd)
        if rr.type == 1 and len(rd) == 4:
            return ".".join(str(b) for b in rd)
        if rr.type == 28 and len(rd) == 16:
            return ":".join(f"{(rd[i] << 8) | rd[i + 1]:x}"
                            for i in range(0, 16, 2))
        try:
            return rd.decode("utf-8", "ignore").rstrip(".")
        except Exception:
            return rd.hex()
    if isinstance(rd, (list, tuple)):  # e.g. TXT records
        return " ".join(p.decode("utf-8", "ignore") if isinstance(p, bytes)
                        else str(p) for p in rd)
    return str(rd)


def mac_vendor(mac):
    """Manufacturer for a MAC: the downloaded vendor list first, then
    scapy's bundled one. Randomized (private) MACs have no vendor."""
    if not mac or is_randomized_mac(mac):
        return ""
    db = DATA.get("oui") if DATA is not None else None
    if db is not None:
        v = db.lookup(mac)
        if v:
            return v
    try:
        m = mac.lower().replace("-", ":")
        v = conf.manufdb._get_manuf(m)
        if v and v.lower() != m:
            return v
    except (AttributeError, KeyError, TypeError, ValueError):
        pass
    return ""


def guess_device_type(hostname, vendor, ip, gateway_ip, my_ips):
    h = (hostname or "").lower()
    v = (vendor or "").lower()
    if gateway_ip and ip == gateway_ip:
        return "router"
    if ip in my_ips:
        return "this-pc"
    checks = [
        (("iphone", "ipad", "android", "galaxy", "pixel", "phone"),
         "phone"),
        (("ipad", "tablet", "tab"), "tablet"),
        (("macbook", "imac", "mac-", "desktop", "laptop", "pc-",
          "windows", "linux"), "computer"),
        (("printer", "hp-", "canon", "epson", "brother"), "printer"),
        (("tv", "roku", "chromecast", "appletv", "firetv", "bravia",
          "samsung-tv", "smarttv"), "tv"),
        (("xbox", "playstation", "ps4", "ps5", "nintendo", "switch"),
         "console"),
        (("echo", "alexa", "homepod", "google-home", "speaker"), "speaker"),
        (("cam", "camera", "nest", "ring", "wyze"), "camera"),
        (("espressif", "tuya", "sonoff", "shelly", "smart"),
         "iot"),
    ]
    for keys, kind in checks:
        if any(k in h for k in keys):
            return kind
    # vendor fallback
    if any(x in v for x in ("apple",)):
        return "phone"
    if any(x in v for x in ("samsung", "huawei", "xiaomi", "oneplus",
                            "oppo", "vivo", "motorola")):
        return "phone"
    if any(x in v for x in ("intel", "dell", "hp inc", "lenovo",
                            "asus", "acer", "toshiba", "micro-star",
                            "gigabyte")):
        return "computer"
    if any(x in v for x in ("brother", "canon", "epson", "hewlett")):
        return "printer"
    if any(x in v for x in ("sony", "lg electronics", "tcl", "vizio",
                            "roku", "amazon")):
        return "tv"
    if any(x in v for x in ("espressif", "tuya", "sonoff", "shelly",
                            "raspberr", "arduino")):
        return "iot"
    return "unknown"



