# ============================================================================
#  5.  Protocol decoder
#
#  Turns a scapy packet into one plain dict. It runs on the decode worker
#  thread, never touches Tk, and never decrypts anything: for encrypted
#  traffic it only reads what is visible on the wire (e.g. the TLS
#  ClientHello's server name), and it says "Likely … (by port)" whenever a
#  label comes from a port number rather than from the payload itself.
# ============================================================================
TLS_VERSIONS = {0x0300: "SSL 3.0", 0x0301: "TLS 1.0", 0x0302: "TLS 1.1",
                0x0303: "TLS 1.2", 0x0304: "TLS 1.3"}


def parse_tls_hello(rec):
    """Parse a TLS handshake record (ClientHello or ServerHello). Returns a
    dict with whatever was visible: sni, version, alpn, ech, kind.
    Tolerates truncation (returns what it got)."""
    out = {"kind": "", "sni": "", "version": "", "alpn": [], "ech": False}
    try:
        if len(rec) < 6 or rec[0] != 0x16 or rec[1] != 0x03:
            return None
        hs_type = rec[5]
        if hs_type not in (1, 2):
            return None
        out["kind"] = "client" if hs_type == 1 else "server"
        pos = 9
        legacy = struct.unpack(">H", rec[pos:pos + 2])[0]
        out["version"] = TLS_VERSIONS.get(legacy, "")
        pos += 2 + 32                                     # version + random
        sid_len = rec[pos]
        pos += 1 + sid_len
        if hs_type == 1:
            cs_len = struct.unpack(">H", rec[pos:pos + 2])[0]
            pos += 2 + cs_len
            cm_len = rec[pos]
            pos += 1 + cm_len
        else:
            pos += 2 + 1                                  # cipher + method
        if pos + 2 > len(rec):
            return out
        ext_len = struct.unpack(">H", rec[pos:pos + 2])[0]
        pos += 2
        end = min(pos + ext_len, len(rec))
        while pos + 4 <= end:
            et, el = struct.unpack(">HH", rec[pos:pos + 4])
            pos += 4
            body = rec[pos:pos + el]
            if et == 0 and len(body) >= 5:                # server_name
                nl = struct.unpack(">H", body[3:5])[0]
                host = body[5:5 + nl].decode("ascii", "ignore")
                if host and re.match(r"^[A-Za-z0-9._-]+$", host):
                    out["sni"] = host.lower()
            elif et == 16 and len(body) >= 2:             # ALPN
                p = 2
                while p < len(body):
                    ln = body[p]
                    out["alpn"].append(body[p + 1:p + 1 + ln].decode(
                        "ascii", "ignore"))
                    p += 1 + ln
            elif et == 43 and body:                       # supported_versions
                if hs_type == 1:
                    vers = [struct.unpack(">H", body[i:i + 2])[0]
                            for i in range(1, 1 + body[0], 2)
                            if i + 2 <= len(body)]
                    if 0x0304 in vers:
                        out["version"] = "TLS 1.3"
                elif len(body) >= 2:
                    out["version"] = TLS_VERSIONS.get(
                        struct.unpack(">H", body[:2])[0], out["version"])
            elif et == 0xfe0d:                            # ECH
                out["ech"] = True
            pos += el
    except (IndexError, struct.error):
        pass
    return out


def _try_tls_sni(load):
    """Backward-compatible helper: SNI from a single segment, or None."""
    r = parse_tls_hello(load)
    return (r or {}).get("sni") or None


class TlsReassembler:
    """Modern ClientHellos (post-quantum key shares, many extensions) are
    often larger than one TCP segment, and browsers randomise extension
    order, so the server name can sit in the *second* segment. This keeps a
    tiny, bounded, short-lived buffer per connection to stitch the first
    handshake record back together. Nothing else is buffered."""

    MAX_ENTRIES = 1024
    MAX_RECORD = 16384 + 5
    TTL = 4.0

    def __init__(self):
        self.buf = OrderedDict()
        self.quic = QuicInitialReader()      # HTTP/3 first packets

    def feed(self, key, seq, payload, ts):
        if not payload:
            return None
        if payload[0] == 0x16 and len(payload) >= 6 and payload[1] == 0x03 \
                and payload[5] in (1, 2):
            need = struct.unpack(">H", payload[3:5])[0] + 5
            if need > self.MAX_RECORD:
                return payload
            if len(payload) >= need:
                self.buf.pop(key, None)
                return payload
            self.buf[key] = [bytearray(payload), (seq + len(payload))
                             & 0xffffffff, need, ts]
            self._trim(ts)
            return None
        ent = self.buf.get(key)
        if ent is None:
            return None
        if seq != ent[1]:
            if ((seq - ent[1]) & 0xffffffff) > 0x7fffffff:
                return None                   # old retransmission: ignore
            self.buf.pop(key, None)           # gap: give up on this one
            return bytes(ent[0])
        ent[0].extend(payload)
        ent[1] = (seq + len(payload)) & 0xffffffff
        if len(ent[0]) >= ent[2] or len(ent[0]) > self.MAX_RECORD:
            self.buf.pop(key, None)
            return bytes(ent[0])
        return None

    def _trim(self, now):
        while len(self.buf) > self.MAX_ENTRIES:
            self.buf.popitem(last=False)
        for k in list(self.buf)[:32]:
            if now - self.buf[k][3] > self.TTL:
                self.buf.pop(k, None)


def mdns_service_hint(name):
    """Guess a device kind from an mDNS service-type string, e.g.
    '_googlecast._tcp.local.' -> 'tv'. Empty string if no match."""
    n = (name or "").lower()
    for key, kind in MDNS_SERVICE_HINTS:
        if key in n:
            return kind
    return ""


_SERVICE_RE = re.compile(r"(_[a-z0-9-]+\._(?:tcp|udp))", re.I)


def _decode_dns(d, kind):
    """scapy DNS layer → (text, learns, hint, info), via the shared
    summary so the fast decoder behaves identically."""
    qname, qtype = "", 0
    if d.qd is not None and getattr(d, "qdcount", 1):
        try:
            q = d.qd[0] if isinstance(d.qd, (list, tuple)) else d.qd
        except (IndexError, TypeError):
            q = None
        if q is not None:
            qname = _name_bytes(getattr(q, "qname", b""))
            qtype = getattr(q, "qtype", 0) or 0
    records = []
    if int(d.qr or 0):
        rrs = list(_iter_rrs(d.an))
        if kind == "mDNS":
            rrs += list(_iter_rrs(getattr(d, "ar", None)))
        for rr in rrs:
            if int(rr.type) in _DNS_SKIPPED_TYPES:   # older scapy
                continue
            rd = rr.rdata
            txt = []
            if rr.type == 16:
                txt = list(rd) if isinstance(rd, (list, tuple)) else [rd]
            records.append((_name_bytes(getattr(rr, "rrname", b"")),
                            int(rr.type), _rdata_ip(rr), _rdata_str(rr),
                            txt))
    return dns_summary(kind, qname, qtype, int(getattr(d, "id", 0) or 0),
                       int(d.qr or 0), int(d.rcode or 0), records)


def dns_summary(kind, qname, qtype, qid, qr, rcode, records):
    """Shared DNS interpretation. records: (rrname, type, ip_or_None,
    rdata_text, txt_parts) for the answer section (+ additional records
    for mDNS). Returns (text, learns, hint, info)."""
    learns = []
    hint = ""
    info = {"id": qid, "qr": qr, "qname": qname, "qtype": qtype,
            "rcode": rcode, "answers": [], "services": [], "names": [],
            "txt": {}, "hostnames": []}
    if kind == "mDNS":
        hint = mdns_service_hint(qname)
        m = _SERVICE_RE.search(qname or "")
        if m and qr == 0:
            info["services"].append(m.group(1).lower())
    if qr == 0:
        return (f"Looking up {qname}" if qname else "DNS query"), learns, \
            hint, info
    answers, cname = [], ""
    for rrname, rtype, ip, rstr, txt in records:
        if kind == "mDNS":
            if not hint:
                hint = mdns_service_hint(rrname)
            m = _SERVICE_RE.search(rrname)
            if m:
                svc = m.group(1).lower()
                if svc not in info["services"]:
                    info["services"].append(svc)
                inst = rrname.split("._", 1)[0]
                if rtype == 16 and inst and not inst.startswith("_"):
                    info["names"].append(inst)
            if rtype == 12:                                 # PTR → instance
                inst = rstr.split("._", 1)[0]
                if inst and not inst.startswith("_") and \
                        "._" in rstr and inst not in info["names"]:
                    info["names"].append(inst)
            if rtype == 16:                                 # TXT
                for part in txt:
                    s = sanitize_text(part, 120)
                    if "=" in s:
                        k, _, v = s.partition("=")
                        if k.lower() in ("model", "md", "am", "ty", "fn",
                                         "usb_mdl", "product", "rpmd"):
                            info["txt"][k.lower()] = v[:60]
        if rtype == 5:
            cname = rstr
            continue
        if ip:
            answers.append(ip)
            if kind == "mDNS":
                if rrname:
                    learns.append((ip, rrname))
                    info["hostnames"].append(rrname)
            elif qname:
                learns.append((ip, qname))
                if cname:
                    learns.append((ip, cname))
        elif rtype not in (1, 28, 12, 16, 33, 47):
            answers.append(f"{DNS_TYPES.get(rtype, rtype)}={rstr[:60]}")
    info["answers"] = [a for a in answers if "=" not in a][:32]
    info["names"] = info["names"][:8]
    info["hostnames"] = info["hostnames"][:8]
    head = qname or (info["names"][0] if info["names"] else "?")
    if kind == "mDNS" and info["services"] and not answers:
        return (f"Announced: {head} ({', '.join(info['services'][:3])})",
                learns, hint, info)
    if answers:
        shown = ", ".join(answers[:3])
        if len(answers) > 3:
            shown += f" +{len(answers) - 3}"
        return f"{head} → {shown}", learns, hint, info
    if rcode == 3:
        return f"{head} → does not exist", learns, hint, info
    if rcode == 2:
        return f"{head} → server failure", learns, hint, info
    return f"{head} → no answer", learns, hint, info


def _decode_dhcp(pkt):
    bootp = pkt[BOOTP]
    yiaddr = getattr(bootp, "yiaddr", "") or ""
    try:
        chaddr = bytes(bootp.chaddr)[:6]
    except (TypeError, ValueError):
        chaddr = b""
    return dhcp_from_options(pkt[DHCP].options, yiaddr, chaddr)


def dhcp_from_options(options, yiaddr, chaddr_bytes):
    """Shared by the scapy decoder and the fast wire decoder. `options` is
    a list of tuples (code-or-scapy-name, value, ...)."""
    learns = []
    info = {"msgtype": None, "hostname": "", "vendor_class": "",
            "requested_ip": "", "lease_time": None, "server_id": "",
            "router": "", "dns_servers": [], "param_list": "",
            "client_id": ""}
    msg = "DHCP"
    for opt in options:
        if opt == "end":        # scapy reads on past it; what follows is
            break               # padding, or garbage (5.3.4 S12)
        if not isinstance(opt, tuple) or len(opt) < 2:
            continue
        code, val = opt[0], opt[1]
        try:
            if code in (53, "message-type"):
                info["msgtype"] = int(val)
                msg = DHCP_MSG.get(int(val), str(val))
            elif code in (12, "hostname"):
                info["hostname"] = sanitize_text(val, 64).strip()
            elif code in (60, "vendor_class_id"):
                info["vendor_class"] = sanitize_text(val, 60)
            elif code in (50, "requested_addr"):
                info["requested_ip"] = str(val)
            elif code in (51, "lease_time"):
                info["lease_time"] = int(val)
            elif code in (54, "server_id"):
                info["server_id"] = str(val)
            elif code in (3, "router"):
                info["router"] = str(val)
            elif code in (6, "name_server"):
                info["dns_servers"] = [str(v) for v in opt[1:]][:8]
            elif code in (55, "param_req_list"):
                info["param_list"] = ",".join(str(x) for x in val)[:80] \
                    if isinstance(val, (list, tuple, bytes)) \
                    else str(val)[:80]
            elif code in (61, "client_id"):
                if isinstance(val, bytes):
                    info["client_id"] = val[:32].hex()
                else:
                    info["client_id"] = sanitize_text(val, 64)
        except (TypeError, ValueError):
            continue
    yiaddr = yiaddr if isinstance(yiaddr, str) else ""
    if yiaddr == "0.0.0.0":
        yiaddr = ""
    chaddr = ""
    raw = bytes(chaddr_bytes or b"")[:6]
    if len(raw) == 6 and any(raw):
        chaddr = ":".join(f"{b:02x}" for b in raw)
    if info["hostname"] and yiaddr:
        learns.append((yiaddr, info["hostname"]))
    parts = [msg]
    if info["hostname"]:
        parts.append(f"as “{info['hostname']}”")
    if yiaddr:
        parts.append(f"got {yiaddr}")
    if info["lease_time"]:
        parts.append(f"for {human_duration(info['lease_time'])}")
    info.update({"yiaddr": yiaddr, "client_mac": chaddr})
    return "DHCP", "DHCP", " ".join(parts), learns, info


def _ssdp_hint(text):
    t = (text or "").lower()
    for key, kind in SSDP_HINTS:
        if key in t:
            return kind
    return ""


def _decode_ssdp(load):
    """Parse an SSDP (UPnP discovery) datagram into a friendly line, a
    device-type hint and the headers that help identify the device."""
    try:
        text = load.decode("utf-8", "ignore")
    except (AttributeError, UnicodeError):
        return "Device announcement (SSDP)", "", {}
    lines = text.split("\r\n")
    first = (lines[0] if lines else "").strip()
    headers = {}
    for line in lines[1:]:
        if ":" in line:
            k, _, v = line.partition(":")
            headers[k.strip().upper()] = v.strip()
    server = headers.get("SERVER", "")
    st = headers.get("ST", headers.get("NT", ""))
    server, st = sanitize_text(server, 120), sanitize_text(st, 120)
    info = {"server": server, "st": st,
            "search": first.startswith("M-SEARCH"),
            "friendly": sanitize_text(headers.get("X-FRIENDLY-NAME", ""),
                                      60)}
    hint = _ssdp_hint(server + " " + st)
    if info["search"]:
        return "Looking for other devices on the network (SSDP)", hint, info
    label = server or st or "Device announcement"
    return f"Announced itself: {label}", hint, info


def _try_nbns(load):
    if len(load) < 12:
        return None
    try:
        pos = 12
        ll = load[pos]
        pos += 1
        raw = load[pos:pos + ll]
        nm = ""
        for i in range(0, len(raw) - 1, 2):
            c = ((raw[i] - 0x41) << 4) | (raw[i + 1] - 0x41)
            if 32 <= c < 127:
                nm += chr(c)
        return nm.strip() or None
    except (IndexError, TypeError):
        return None


def _port_service(sport, dport):
    """Plain-English service for a port pair, preferring the well-known
    (lower / server-side) port."""
    for p in sorted((dport or 0, sport or 0)):
        if p and p in PORT_SERVICES:
            return PORT_SERVICES[p], p
    return "", None


def _tcp_app_from_payload(load, sport, dport):
    """Recognise a few cleartext/handshake banners. Returns (proto, text)."""
    head = load[:16]
    if head.startswith(b"SSH-"):
        ver = load.split(b"\r\n", 1)[0][:40].decode("ascii", "ignore")
        return "SSH", f"Remote terminal (SSH) handshake: {ver}"
    if 21 in (sport, dport) and (head[:4] in (b"220 ", b"220-", b"USER",
                                              b"PASS", b"230 ", b"331 ")):
        return "FTP", "File transfer (FTP, not encrypted)"
    if 23 in (sport, dport):
        return "TELNET", "Remote terminal (Telnet, not encrypted)"
    if len(load) > 8 and load[4:8] in (b"\xfeSMB", b"\xffSMB", b"\xfdSMB"):
        return "SMB", "Windows file sharing (SMB)"
    if 3389 in (sport, dport) and head[:2] == b"\x03\x00":
        return "RDP", "Remote desktop (RDP)"
    if 1883 in (sport, dport):
        return "MQTT", "Smart home messaging (MQTT, not encrypted)"
    if head.startswith(b"RTSP/") or b"rtsp://" in load[:64]:
        return "RTSP", "Streaming video control (RTSP)"
    if head.startswith(b"SIP/2.0") or re.match(rb"^(INVITE|REGISTER) sip:",
                                                load[:24]):
        return "SIP", "Internet calling (SIP)"
    if 25 in (sport, dport) or 587 in (sport, dport):
        if head[:4] in (b"220 ", b"EHLO", b"HELO", b"250-", b"250 "):
            return "SMTP", "Sending email (SMTP)"
    if 143 in (sport, dport) and (head[:4] == b"* OK" or b" LOGIN" in head):
        return "IMAP", "Checking email (IMAP, not encrypted)"
    if 110 in (sport, dport) and (head[:3] == b"+OK" or head[:4] == b"USER"):
        return "POP3", "Checking email (POP3, not encrypted)"
    return "", ""


def _l4_payload(pkt, l4):
    """The transport payload as raw bytes, whatever scapy dissected it into
    (NTP, NBNS… layers) and without Ethernet padding."""
    try:
        data = bytes(l4.payload)
    except Exception:                                # noqa: BLE001
        return b""
    # 5.3.4 (S12): cut where the IP packet ends. Not at a Padding layer:
    # a layer with its own length (NBT, DNS over TCP…) makes one too, and
    # that one is payload
    ip = l4.underlayer
    while ip is not None and type(ip).__name__ not in ("IP", "IPv6"):
        ip = ip.underlayer
    total = getattr(ip, "len" if type(ip).__name__ == "IP" else "plen",
                    None)
    if total is not None:
        try:
            cut = len(bytes(ip)) - (int(total) if type(ip).__name__ == "IP"
                                    else 40 + int(total))
        except Exception:                            # noqa: BLE001
            cut = 0
        if 0 < cut <= len(data):
            data = data[:-cut]
    return data


def _new_decoded(pkt):
    return {"proto": "?", "tag": "OTHER", "text": "",
            "src": "", "dst": "", "src_ip": "", "dst_ip": "",
            "src_mac": "", "dst_mac": "", "ttl": "", "ttl_int": 0,
            "sport": None, "dport": None, "ipver": 0, "transport": "",
            "tcp_flags": None, "seq": None, "ack": None, "win": None,
            "payload_len": 0,
            "dns_names": [], "doh_hint": "", "plain_dns": False,
            "type_hint": "", "dhcp_msgtype": None, "arp_op": None,
            "dhcp_yiaddr": "", "dhcp_hostname": "", "dhcp_client_mac": "",
            "dhcp": None, "dns": None, "tls": None, "nd": None,
            "ssdp": None, "mdns": None, "http_host": "", "lldp": None,
            "service": "", "service_port": None, "app_conf": "",
            "encrypted": "unknown", "cleartext": "",
            "multicast": False, "l2_bcast": False,
            "learns": [], "pkt": pkt,
            "time": float(getattr(pkt, "time", time.time())),
            # the wire length: rebuilding (len(pkt)) can drop bytes scapy
            # did not keep, e.g. after an ICMP extension
            "length": len(pkt.original) if getattr(pkt, "original", None)
            else len(pkt)}


def decode_packet(pkt, gateway_ip="", my_ips=(), reasm=None):
    d = _new_decoded(pkt)

    if pkt.haslayer(Ether):
        e = pkt[Ether]
        d["src_mac"], d["dst_mac"] = (e.src or "").lower(), \
            (e.dst or "").lower()
        d["l2_bcast"] = d["dst_mac"] == "ff:ff:ff:ff:ff:ff"
        if d["dst_mac"] and not is_unicast_mac(d["dst_mac"]):
            d["multicast"] = True
    if type(pkt).__name__ in ("Ether", "Dot3"):
        try:
            raw0 = bytes(pkt)
            info = l2_discovery(raw0)
        except (struct.error, IndexError, ValueError):
            info = None
        if info:
            if not d["src_mac"]:
                d["dst_mac"], d["src_mac"] = _mac(raw0[0:6]), \
                    _mac(raw0[6:12])
                d["multicast"] = bool(raw0[0] & 1)
            return _label_l2_discovery(d, info)

    if pkt.haslayer(ARP):
        a = pkt[ARP]

        def sf(v):
            # malformed ARP (odd hardware/protocol lengths) gives bytes
            return v if isinstance(v, str) else ""
        psrc, pdst = sf(a.psrc), sf(a.pdst)
        hwsrc, hwdst = sf(a.hwsrc).lower(), sf(a.hwdst).lower()
        if (psrc and ip_obj(psrc) is None) or (pdst and ip_obj(pdst) is None):
            psrc = pdst = ""
        d["src_ip"], d["dst_ip"] = psrc, pdst
        d["src_mac"], d["dst_mac"] = hwsrc, hwdst
        d["proto"], d["tag"], d["transport"] = "ARP", "ARP", "ARP"
        d["arp_op"] = int(a.op) if isinstance(a.op, int) else 0
        if not (psrc and hwsrc):
            d["arp_op"] = 0
        if d["arp_op"] == 1:
            if psrc == pdst:
                d["text"] = f"{psrc} announced itself (gratuitous ARP)"
            else:
                d["text"] = f"Who has {pdst}? Tell {psrc}"
        elif d["arp_op"] == 2:
            d["text"] = f"{psrc} is at {hwsrc}"
        else:
            d["text"] = f"ARP op={a.op}"
        d["src"] = psrc or hwsrc
        d["dst"] = pdst or hwdst
        d["ipver"] = 4
        return d

    ipl = None
    if pkt.haslayer(IP):
        ipl = pkt[IP]
        d["src_ip"], d["dst_ip"] = ipl.src, ipl.dst
        d["ttl"] = str(ipl.ttl)
        d["ttl_int"] = int(ipl.ttl or 0)
        d["ipver"] = 4
    elif HAVE_IPV6 and pkt.haslayer(IPv6):
        ipl = pkt[IPv6]
        d["src_ip"], d["dst_ip"] = ipl.src, ipl.dst
        d["ttl"] = str(getattr(ipl, "hlim", ""))
        d["ttl_int"] = int(getattr(ipl, "hlim", 0) or 0)
        d["ipver"] = 6
    if d["dst_ip"] and is_multicast_or_broadcast(d["dst_ip"]):
        d["multicast"] = True

    # --- TCP
    if pkt.haslayer(TCP):
        t = pkt[TCP]
        d["sport"], d["dport"] = int(t.sport), int(t.dport)
        d["transport"] = "TCP"
        d["proto"], d["tag"] = "TCP", "TCP"
        flags = int(t.flags)
        d["tcp_flags"] = flags
        d["seq"] = int(t.seq)
        d["ack"] = int(t.ack)
        d["win"] = int(t.window)
        names = [n for b, n in ((0x01, "FIN"), (0x02, "SYN"), (0x04, "RST"),
                                (0x08, "PSH"), (0x10, "ACK"), (0x20, "URG"))
                 if flags & b]
        svc, sport_ = _port_service(t.sport, t.dport)
        d["service"], d["service_port"] = svc, sport_
        if svc:
            d["text"] = f"{svc} ({','.join(names) or 'data'})"
            d["app_conf"] = "Likely (by port)"
        else:
            d["text"] = f"Connecting ({','.join(names) or 'data'})"
        if sport_ in ENCRYPTED_PORTS:
            d["encrypted"] = "likely"

        if pkt.haslayer(DNS) and 53 in (t.sport, t.dport):
            text, learns, hint, info = _decode_dns(pkt[DNS], "DNS")
            info["transport"] = "TCP"
            d.update({"proto": "DNS", "tag": "DNS", "text": text + " (TCP)",
                      "dns": info, "app_conf": "Observed"})
            d["learns"].extend(learns)
            d["plain_dns"] = t.dport == 53
            d["encrypted"] = "no"
        else:
            load = _l4_payload(pkt, t)
            d["payload_len"] = len(load)
            if load:
                _decode_tcp_payload(d, load, reasm)
            if not d["cleartext"] and d["payload_len"] and \
                    sport_ in CLEARTEXT_PORTS:
                d["cleartext"] = CLEARTEXT_PORTS[sport_]
                d["encrypted"] = "no"

    # --- UDP
    elif pkt.haslayer(UDP):
        u = pkt[UDP]
        d["sport"], d["dport"] = int(u.sport), int(u.dport)
        d["transport"] = "UDP"
        ports = (u.sport, u.dport)
        load = _l4_payload(pkt, u)
        if u.len and int(u.len) >= 8:
            load = load[:int(u.len) - 8]
            d["payload_len"] = int(u.len) - 8
        else:
            d["payload_len"] = len(load)
        dns_layer = pkt[DNS] if pkt.haslayer(DNS) else None
        if dns_layer is None and load and len(load) >= 12 and \
                any(p in (53, 5353, 5355) for p in ports):
            try:                  # scapy dissects LLMNR as its own layer
                dns_layer = DNS(load)
            except Exception:                        # noqa: BLE001
                dns_layer = None
        if dns_layer is not None and \
                any(p in (53, 5353, 5355) for p in ports):
            name = "DNS"
            if 5353 in ports:
                name = "mDNS"
            elif 5355 in ports:
                name = "LLMNR"
            if u.dport == 53:
                d["plain_dns"] = True
            text, learns, hint, info = _decode_dns(dns_layer, name)
            info["transport"] = "UDP"
            d.update({"proto": name, "tag": name, "text": text,
                      "app_conf": "Observed", "encrypted": "no"})
            if name == "mDNS":
                d["mdns"] = info
            else:
                d["dns"] = info
            d["learns"].extend(learns)
            if hint:
                d["type_hint"] = hint
        elif HAVE_DHCP and pkt.haslayer(BOOTP) and pkt.haslayer(DHCP) and \
                any(p in (67, 68) for p in ports):
            p, t2, text, learns, info = _decode_dhcp(pkt)
            d.update({"proto": p, "tag": t2, "text": text, "dhcp": info,
                      "app_conf": "Observed"})
            d["learns"].extend(learns)
            d["dhcp_msgtype"] = info["msgtype"]
            d["dhcp_yiaddr"] = info["yiaddr"]
            d["dhcp_hostname"] = info["hostname"]
            d["dhcp_client_mac"] = info["client_mac"]
        elif any(p in (546, 547) for p in ports) and load:
            mt = load[0]
            d.update({"proto": "DHCPv6", "tag": "DHCPv6",
                      "text": "IPv6 address setup: " +
                      DHCPV6_MSG.get(mt, f"message {mt}"),
                      "app_conf": "Observed"})
        elif 137 in ports and load:
            d["proto"], d["tag"] = "NBNS", "NBNS"
            nm = _try_nbns(load)
            if nm and d["src_ip"] and u.sport == 137 and len(load) > 12 and \
                    load[2] & 0x80:
                d["text"] = f"{nm} is at {d['src_ip']} (Windows name)"
                d["learns"].append((d["src_ip"], nm))
            else:
                d["text"] = f"Local name lookup{(': ' + nm) if nm else ''}"
            d["app_conf"] = "Observed"
        elif 1900 in ports and load:
            text, hint, info = _decode_ssdp(load)
            d.update({"proto": "SSDP", "tag": "SSDP", "text": text,
                      "ssdp": info, "app_conf": "Observed"})
            if hint:
                d["type_hint"] = hint
        elif 123 in ports and len(load) >= 48:
            mode = load[0] & 0x07
            d.update({"proto": "NTP", "tag": "NTP",
                      "text": "Checking the time (NTP " +
                      {3: "request", 4: "reply"}.get(mode, "message") + ")",
                      "app_conf": "Observed", "encrypted": "no"})
        elif 443 in ports and load and (load[0] & 0x80):
            _quic_label(d, bytes(load), reasm, getattr(pkt, "time", 0.0))
        elif 443 in ports and load:
            d.update({"proto": "QUIC", "tag": "QUIC",
                      "text": "Secure web connection (fast, encrypted)",
                      "app_conf": "Likely (by port)", "encrypted": "yes"})
        else:
            svc, sp = _port_service(u.sport, u.dport)
            d["service"], d["service_port"] = svc, sp
            d["proto"], d["tag"] = "UDP", "UDP"
            if sp in PORT_APP:
                d["proto"] = d["tag"] = PORT_APP[sp]
            d["text"] = (f"{svc} ({d['payload_len']} bytes)" if svc
                         else f"Quick message ({d['payload_len']} bytes)")
            d["app_conf"] = "Likely (by port)" if svc else ""
            if sp in VPN_PORTS:
                d["encrypted"] = "yes"
            elif sp in CLEARTEXT_PORTS:
                d["cleartext"] = CLEARTEXT_PORTS[sp]
                d["encrypted"] = "no"

    elif pkt.haslayer(ICMP):
        c = pkt[ICMP]
        d["proto"], d["tag"], d["transport"] = "ICMP", "ICMP", "ICMP"
        d["sport"], d["dport"] = int(c.type), int(getattr(c, "code", 0) or 0)
        d["text"] = {0: "Ping reply", 3: "Destination unreachable",
                     8: "Ping request", 11: "Time exceeded",
                     5: "Redirect (router suggests another path)"}.get(
                         c.type, f"ICMP type {c.type}")
    elif HAVE_IPV6 and ipl is not None and d["ipver"] == 6 and \
            _decode_icmpv6(d, pkt):
        pass
    elif ipl is not None and d["ipver"] == 4 and int(ipl.proto) == 2:
        d.update({"proto": "IGMP", "tag": "IGMP", "transport": "IGMP",
                  "text": "Joining/leaving a multicast group (IGMP)"})
    else:
        ll = pkt.lastlayer()
        d["proto"] = _ip_proto_name(ipl) or (ll.name if ll else "?")
        if d["proto"] and not d["text"]:
            d["text"] = f"{d['proto']} frame"

    d["src"] = d["src_ip"] or d["src_mac"]
    d["dst"] = d["dst_ip"] or d["dst_mac"]
    return d


def _ip_proto_name(ipl):
    """'ESP', 'GRE'… for the IP protocol (after any IPv6 extension
    headers), as the fast decoder names it; whatever scapy dissected the
    payload into ('NON_ESP', 'Raw'…) says less."""
    if ipl is None:
        return None
    nh = getattr(ipl, "proto", None)
    if nh is None:
        nh = _ipv6_upper(ipl)[0]
    try:
        return _IPPROTO_NAMES.get(int(nh))
    except (TypeError, ValueError):
        return None


def _ipv6_upper(ipl):
    """(next header, layer) after an IPv6 header's extension headers."""
    nh, ly = getattr(ipl, "nh", None), ipl.payload
    while type(ly).__name__.startswith("IPv6ExtHdr"):
        nh, ly = getattr(ly, "nh", None), ly.payload
    return nh, ly


def _decode_tcp_payload(d, load, reasm):
    # plain HTTP?
    if load[:4] in (b"GET ", b"POST", b"HEAD", b"PUT ", b"DELE",
                    b"OPTI", b"PATC", b"CONN") or load[:5] == b"HTTP/":
        try:
            head = load[:2048].decode("latin-1")
        except UnicodeError:
            head = ""
        line = head.split("\r\n", 1)[0]
        m = re.search(r"\r\nHost:\s*([^\r\n]+)", head, re.I)
        host = m.group(1).strip().lower()[:120] if m else ""
        if host and not re.match(r"^[a-z0-9._:\[\]-]+$", host):
            host = ""                     # not a hostname: don't trust it
        if line:
            d["proto"], d["tag"] = "HTTP", "HTTP"
            d["app_conf"] = "Observed"
            if line.startswith("CONNECT"):
                d["text"] = f"Proxy tunnel request: {line[:100]}"
                d["encrypted"] = "unknown"
            else:
                d["text"] = "Unsecured web request: " + \
                    hide_credentials(line)[:110]
                if host:
                    d["text"] += f"  (Host: {host})"
                d["encrypted"] = "no"
                d["cleartext"] = "HTTP"
            if host and not line.startswith("HTTP/"):
                d["http_host"] = host.split(":")[0]
                d["dns_names"].append(d["http_host"])
                if d["dst_ip"]:
                    d["learns"].append((d["dst_ip"], d["http_host"]))
        return
    rec = None
    if reasm is not None and d["seq"] is not None:
        key = (d["src_ip"], d["sport"], d["dst_ip"], d["dport"])
        rec = reasm.feed(key, d["seq"], load, d["time"])
    elif load[:1] == b"\x16":
        rec = load
    if rec:
        info = parse_tls_hello(rec)
        if info and info.get("kind"):
            d["tls"] = info
            d["proto"], d["tag"] = "TLS", "TLS"
            d["encrypted"] = "yes"
            d["app_conf"] = "Observed"
            sni = info.get("sni", "")
            if info["kind"] == "client":
                if sni:
                    d["text"] = f"Secure connection to {sni}"
                    if info.get("ech"):
                        d["text"] += " (Encrypted Client Hello — the real " \
                                     "site may be hidden behind this name)"
                    d["dns_names"].append(sni)
                    d["learns"].append((d["dst_ip"], sni))
                    hint = doh_name(sni)
                    if hint:
                        d["doh_hint"] = hint
                else:
                    d["text"] = "Secure connection (site name not visible)"
                if 853 in (d["sport"], d["dport"]):
                    d["proto"] = d["tag"] = "DoT"
                    d["doh_hint"] = d["doh_hint"] or "DNS-over-TLS"
            else:
                d["text"] = f"Secure connection accepted " \
                            f"({info.get('version') or 'TLS'})"
            return
    if d["transport"] == "TCP" and load[:1] == b"\x17" and \
            load[1:2] == b"\x03":
        d["proto"], d["tag"] = "TLS", "TLS"
        d["encrypted"] = "yes"
        d["text"] = "Encrypted data (TLS)"
        d["app_conf"] = "Observed"
        return
    proto, text = _tcp_app_from_payload(load, d["sport"], d["dport"])
    if proto:
        d["proto"] = d["tag"] = proto
        d["text"] = text
        d["app_conf"] = "Observed"
        if proto in ("FTP", "TELNET", "IMAP", "POP3", "MQTT"):
            d["encrypted"] = "no"
            d["cleartext"] = proto
        elif proto in ("SSH", "RDP"):
            d["encrypted"] = "yes"


def _decode_icmpv6(d, pkt):
    """IPv6 control traffic: Neighbor Discovery (how IPv6 devices find each
    other and their router), pings and errors. Returns True if handled."""
    nh, top = _ipv6_upper(pkt[IPv6])
    if type(top).__name__ in ("ICMPv6DestUnreach", "ICMPv6PacketTooBig",
                              "ICMPv6TimeExceeded", "ICMPv6ParamProblem"):
        # 5.3.4 (S12): an error quotes the packet that failed (a ping, a
        # DNS query, an NS…): label the error, not what it quotes
        d.update({"proto": "ICMPv6", "tag": "ICMPv6", "transport": "ICMPv6",
                  "text": _ICMP6_NAMES.get(int(top.type), top.name)})
        if int(top.type) == 1:
            d.update({"text": "Destination unreachable (IPv6)", "sport": 1,
                      "dport": 0})
        return True
    nd = None
    if pkt.haslayer(ICMPv6ND_RA):
        ra = pkt[ICMPv6ND_RA]
        prefixes = []
        opt = pkt.getlayer(ICMPv6NDOptPrefixInfo)
        i = 1
        while opt is not None and i < 8:
            prefixes.append(f"{opt.prefix}/{opt.prefixlen}")
            i += 1
            opt = pkt.getlayer(ICMPv6NDOptPrefixInfo, i)
        mac = ""
        if pkt.haslayer(ICMPv6NDOptSrcLLAddr):
            mac = (pkt[ICMPv6NDOptSrcLLAddr].lladdr or "").lower()
        nd = {"kind": "RA", "target": d["src_ip"], "mac": mac or d["src_mac"],
              "prefixes": prefixes,
              "lifetime": int(getattr(ra, "routerlifetime", 0) or 0)}
        d["text"] = "Router announcement (IPv6)" + (
            f" — network {', '.join(prefixes)}" if prefixes else "")
    elif pkt.haslayer(ICMPv6ND_RS):
        nd = {"kind": "RS", "target": "", "mac": d["src_mac"], "prefixes": []}
        d["text"] = "Looking for an IPv6 router (Router Solicitation)"
    elif pkt.haslayer(ICMPv6ND_NS):
        ns = pkt[ICMPv6ND_NS]
        mac = ""
        if pkt.haslayer(ICMPv6NDOptSrcLLAddr):
            mac = (pkt[ICMPv6NDOptSrcLLAddr].lladdr or "").lower()
        nd = {"kind": "NS", "target": str(ns.tgt), "mac": mac,
              "prefixes": [], "dad": d["src_ip"] == "::"}
        d["text"] = (f"Checking nobody else uses {ns.tgt} (duplicate check)"
                     if nd["dad"] else f"Who has {ns.tgt}? (IPv6)")
    elif pkt.haslayer(ICMPv6ND_NA):
        na = pkt[ICMPv6ND_NA]
        mac = ""
        if pkt.haslayer(ICMPv6NDOptDstLLAddr):
            mac = (pkt[ICMPv6NDOptDstLLAddr].lladdr or "").lower()
        nd = {"kind": "NA", "target": str(na.tgt), "mac": mac or d["src_mac"],
              "prefixes": [], "router": bool(getattr(na, "R", 0))}
        d["text"] = f"{na.tgt} is at {nd['mac'] or '?'} (IPv6)"
    if nd is not None:
        d.update({"proto": "NDP", "tag": "NDP", "transport": "ICMPv6",
                  "nd": nd, "app_conf": "Observed"})
        return True
    if pkt.haslayer(ICMPv6EchoRequest):
        d.update({"proto": "ICMPv6", "tag": "ICMPv6", "transport": "ICMPv6",
                  "text": "Ping request (IPv6)", "sport": 128, "dport": 0})
        return True
    if pkt.haslayer(ICMPv6EchoReply):
        d.update({"proto": "ICMPv6", "tag": "ICMPv6", "transport": "ICMPv6",
                  "text": "Ping reply (IPv6)", "sport": 129, "dport": 0})
        return True
    if pkt.haslayer(ICMPv6DestUnreach):
        d.update({"proto": "ICMPv6", "tag": "ICMPv6", "transport": "ICMPv6",
                  "text": "Destination unreachable (IPv6)", "sport": 1,
                  "dport": 0})
        return True
    # by the type byte, as the fast decoder does: scapy leaves a short
    # message as Raw, and trailing bytes make the last layer Raw too
    t = None
    if type(top).__name__.startswith("ICMPv6"):
        t = int(getattr(top, "type", -1))
    elif nh == 58 and isinstance(top, Raw) and top.load:
        t = top.load[0]
    if t in _MLD_TYPES or t in _ICMP6_NAMES:
        d.update({"proto": "ICMPv6", "tag": "ICMPv6", "transport": "ICMPv6",
                  "text": "Multicast group membership report (IPv6)"
                  if t in _MLD_TYPES else _ICMP6_NAMES[t]})
        return True
    ll = pkt.lastlayer()
    name = ll.name if ll else ""
    if "ICMPv6" in name or "MLD" in name:
        d.update({"proto": "ICMPv6", "tag": "ICMPv6", "transport": "ICMPv6",
                  "text": ("Multicast group membership report (IPv6)"
                           if "MLD" in name or "Listener" in name
                           else name)})
        return True
    return False


# ============================================================================
#  5b.  Fast wire decoder
#
#  A struct-based decoder for the frames that make up nearly all real
#  traffic (Ethernet/VLAN, ARP, IPv4/IPv6, TCP, UDP, ICMP/ICMPv6 incl.
#  neighbour discovery, DNS/mDNS/LLMNR, DHCP, SSDP, NBNS, NTP, QUIC, TLS and
#  HTTP). It produces exactly the same dict as decode_packet() — a
#  differential self-test replays the scenario through both and compares
#  them field by field — at roughly 15–20× the speed, and it never builds a
#  scapy object. Anything it doesn't understand is handed to the scapy
#  decoder, so coverage never shrinks. The packet object for the detail
#  view is built lazily from the raw bytes (packet_object()).
# ============================================================================
_U16 = struct.Struct(">H")
_U32 = struct.Struct(">I")
_TCP_FLAG_NAMES = ((0x01, "FIN"), (0x02, "SYN"), (0x04, "RST"),
                   (0x08, "PSH"), (0x10, "ACK"), (0x20, "URG"))
_ETHER_NAMES = {0x88cc: "LLDP", 0x888e: "EAPOL", 0x8863: "PPPoE",
                0x8864: "PPPoE", 0x88e1: "HomePlug AV", 0x893a: "IEEE 1905",
                0x8899: "Realtek", 0x88b5: "Experimental", 0x22f0: "AVTP",
                0x88f7: "PTP", 0x9000: "Loopback"}
_IPPROTO_NAMES = {47: "GRE", 50: "ESP", 51: "AH", 89: "OSPF", 132: "SCTP",
                  103: "PIM", 112: "VRRP", 41: "IPv6-in-IPv4", 4: "IP-in-IP"}
_ICMP4_TEXT = {0: "Ping reply", 3: "Destination unreachable",
               8: "Ping request", 11: "Time exceeded",
               5: "Redirect (router suggests another path)"}
_ICMP6_NAMES = {2: "ICMPv6 Packet Too Big", 3: "ICMPv6 Time Exceeded",
                4: "ICMPv6 Parameter Problem", 137: "ICMPv6 ND Redirect",
                139: "ICMPv6 Node Information Query",
                140: "ICMPv6 Node Information Reply"}
_MLD_TYPES = (130, 131, 132, 143)


class NeedDeepParse(Exception):
    """The fast decoder declines this frame; use the scapy decoder."""


def _mac(b):
    return "%02x:%02x:%02x:%02x:%02x:%02x" % tuple(b[:6])


def _ip4(b):
    return "%d.%d.%d.%d" % (b[0], b[1], b[2], b[3])


def _ip6(b):
    # the system's inet_ntop, as scapy formats addresses ('::ffff:1.2.3.4',
    # where ipaddress before Python 3.13 gives '::ffff:102:304')
    try:
        return _socket.inet_ntop(_socket.AF_INET6, bytes(b[:16]))
    except (AttributeError, OSError, ValueError):
        pass
    try:
        return str(ipaddress.IPv6Address(bytes(b[:16])))
    except (ValueError, ipaddress.AddressValueError):
        return ""


def _wire_name(buf, pos, depth=0):
    """DNS name at `pos` (with compression). Returns (name, next_pos)."""
    labels = []
    jumped = False
    nxt = pos
    hops = 0
    n = len(buf)
    while True:
        if pos >= n:
            raise ValueError("name past end")
        ln = buf[pos]
        if ln == 0:
            pos += 1
            break
        if ln & 0xC0 == 0xC0:
            if pos + 1 >= n:
                raise ValueError("bad pointer")
            ptr = ((ln & 0x3F) << 8) | buf[pos + 1]
            if not jumped:
                nxt = pos + 2
            jumped = True
            hops += 1
            if hops > 32 or ptr >= n:
                raise ValueError("pointer loop")
            pos = ptr
            continue
        if ln & 0xC0:
            raise ValueError("bad label")
        pos += 1
        labels.append(bytes(buf[pos:pos + ln]))
        pos += ln
        if len(labels) > 64:
            raise ValueError("too many labels")
    raw = b".".join(labels)
    return _name_bytes(raw), (nxt if jumped else pos)


def _wire_rdata_name(buf, start, end):
    """A name in a record's rdata, read as scapy reads it: within the
    rdata, and stopping quietly (keeping what it has) at a cut-short label,
    a bad pointer or a pointer loop instead of failing."""
    s, pos, labels, seen = buf[start:end], 0, [], []
    while pos < len(s):
        ln = s[pos]
        pos += 1
        if ln & 0xC0:
            if pos >= len(s) or len(seen) >= 20:
                break
            ptr = ((ln & 0x3F) << 8) | s[pos]
            if ptr in seen:
                break
            seen.append(ptr)
            s, pos = buf, ptr
        elif ln:
            labels.append(bytes(s[pos:pos + ln]))
            pos += ln
        else:
            break
    return _name_bytes(b".".join(labels))


def wire_dns(buf, kind):
    """DNS message bytes → (text, learns, hint, info) via dns_summary()."""
    if len(buf) < 12:
        raise ValueError("short DNS header")
    qid, flags, qd, an, ns, ar = struct.unpack_from(">HHHHHH", buf, 0)
    qr = (flags >> 15) & 1
    rcode = flags & 0x0F
    pos = 12
    qname, qtype = "", 0
    for i in range(min(qd, 16)):
        name, pos = _wire_name(buf, pos)
        if pos + 4 > len(buf):
            raise ValueError("short question")
        t = _U16.unpack_from(buf, pos)[0]
        pos += 4
        if i == 0:
            qname, qtype = name, t
    records = []
    if qr:
        for i in range(min(an + ns + ar, 200)):
            if pos >= len(buf):
                break
            rrname, pos = _wire_name(buf, pos)
            if pos + 10 > len(buf):
                break
            rtype, _rclass, _ttl, rdlen = struct.unpack_from(">HHIH", buf,
                                                             pos)
            pos += 10
            rdata = buf[pos:pos + rdlen]
            rstart = pos
            pos += rdlen
            in_an = i < an
            in_ar = i >= an + ns
            if not (in_an or (kind == "mDNS" and in_ar)) or \
                    rtype in _DNS_SKIPPED_TYPES:
                continue
            ip, rstr, txt = None, "", []
            # like scapy, an address is the first 4/16 bytes of the rdata
            if rtype == 1 and len(rdata) >= 4:
                ip = rstr = _ip4(rdata)
            elif rtype == 28 and len(rdata) >= 16:
                ip = rstr = _ip6(rdata)
            elif rtype in _DNS_NAME_TYPES:
                rstr = _wire_rdata_name(buf, rstart, rstart + rdlen)
            elif rtype == 16:
                p = 0
                while p < len(rdata):
                    ln = rdata[p]
                    txt.append(bytes(rdata[p + 1:p + 1 + ln]))
                    p += 1 + ln
                rstr = sanitize_text(" ".join(
                    t.decode("utf-8", "ignore") for t in txt), 255)
            else:
                rstr = sanitize_text(bytes(rdata).decode(
                    "utf-8", "ignore").rstrip("."), 255)
            records.append((rrname, rtype, ip, rstr, txt))
    return dns_summary(kind, qname, qtype, qid, qr, rcode, records)


def _wire_dhcp(load):
    """BOOTP/DHCP payload → dhcp_from_options() result."""
    if len(load) < 240 or load[236:240] != b"\x63\x82\x53\x63":
        raise NeedDeepParse("not DHCP")
    yiaddr = _ip4(load[16:20])
    chaddr = bytes(load[28:34])
    opts = []
    p = 240
    n = len(load)
    while p < n:
        code = load[p]
        if code == 255:
            break
        if code == 0:
            p += 1
            continue
        if p + 1 >= n or p + 2 + load[p + 1] > n:
            break                       # cut short: scapy drops it too
        ln = load[p + 1]
        val = bytes(load[p + 2:p + 2 + ln])
        p += 2 + ln
        if (code == 53 and not ln) or \
                (code in (50, 54, 3, 6, 51) and (not ln or ln % 4)):
            # scapy can't parse it and keeps no option after it
            raise NeedDeepParse("odd dhcp option")
        if code in (53,) and ln >= 1:
            opts.append((53, val[0]))
        elif code in (12, 60, 61):
            opts.append((code, val))
        elif code in (50, 54, 3) and ln >= 4:
            opts.append((code, _ip4(val)))
        elif code == 51 and ln >= 4:
            opts.append((51, _U32.unpack_from(val)[0]))
        elif code == 6 and ln >= 4:
            opts.append(tuple([6] + [_ip4(val[i:i + 4])
                                     for i in range(0, ln - ln % 4, 4)]))
        elif code == 55:
            opts.append((55, list(val)))
    return dhcp_from_options(opts, yiaddr, chaddr)


# ============================================================================
#  5c.  QUIC Initial packets — the site name a browser sends in its first
#       HTTP/3 packet
#
#  A QUIC client's first packet is encrypted with keys anyone can derive from
#  the packet itself (RFC 9001 §5.2: the salt is public and the connection
#  ID is on the wire). It is protection against accidents, not privacy, and
#  every network middlebox may read it. Nothing else of QUIC is readable, and
#  nothing here is "decrypting a connection": once the handshake moves on,
#  real secret keys take over. The name is labelled as read from the first
#  packet; Encrypted Client Hello (ECH) is detected and said out loud.
#
#  Uses the `cryptography` package when present (fast, checks the
#  authentication tag); otherwise a small pure-Python AES-128 + GHASH (also
#  checks the tag). Budgeted so a flood of fake Initials can't eat the CPU.
# ============================================================================
QUIC_V1 = 0x00000001
QUIC_V2 = 0x6b3343cf
QUIC_SALTS = {
    QUIC_V1: bytes.fromhex("38762cf7f55934b34d179ae6a4c80cadccbb7f0a"),
    QUIC_V2: bytes.fromhex("0dede3def700a6db819381be6e269dcbf9bd2ed9"),
}
QUIC_LABELS = {QUIC_V1: (b"quic key", b"quic iv", b"quic hp"),
               QUIC_V2: (b"quicv2 key", b"quicv2 iv", b"quicv2 hp")}
QUIC_INITIAL_TYPE = {QUIC_V1: 0, QUIC_V2: 1}


def _hkdf_extract(salt, ikm):
    import hmac
    return hmac.new(salt, ikm, hashlib.sha256).digest()


def _hkdf_expand_label(secret, label, length, context=b""):
    import hmac
    full = b"tls13 " + label
    info = struct.pack(">H", length) + bytes([len(full)]) + full + \
        bytes([len(context)]) + context
    out, t, i = b"", b"", 1
    while len(out) < length:
        t = hmac.new(secret, t + info + bytes([i]), hashlib.sha256).digest()
        out += t
        i += 1
    return out[:length]


def quic_initial_keys(dcid, version=QUIC_V1, side="client"):
    """(key, iv, hp) of the Initial packets of one side (RFC 9001 §5.2,
    RFC 9369 §3.3.1 for v2)."""
    initial = _hkdf_extract(QUIC_SALTS[version], dcid)
    secret = _hkdf_expand_label(initial, b"client in" if side == "client"
                                else b"server in", 32)
    lk, li, lh = QUIC_LABELS[version]
    return (_hkdf_expand_label(secret, lk, 16),
            _hkdf_expand_label(secret, li, 12),
            _hkdf_expand_label(secret, lh, 16))


# ---- AES-128 (encrypt direction only: header mask and CTR keystream) -------
def _aes_tables():
    sbox = [0] * 256
    p = q = 1
    while True:                      # generate the S-box (FIPS-197 §5.1.1)
        p = p ^ ((p << 1) & 0xff) ^ (0x1b if p & 0x80 else 0)
        q ^= q << 1
        q ^= q << 2
        q ^= q << 4
        q &= 0xff
        if q & 0x80:
            q ^= 0x09
        x = q ^ ((q << 1) | (q >> 7)) & 0xff ^ ((q << 2) | (q >> 6)) & 0xff \
            ^ ((q << 3) | (q >> 5)) & 0xff ^ ((q << 4) | (q >> 4)) & 0xff
        sbox[p] = (x ^ 0x63) & 0xff
        if p == 1:
            break
    sbox[0] = 0x63

    def xt(a):
        return ((a << 1) ^ 0x1b) & 0xff if a & 0x80 else a << 1
    t0 = []
    for i in range(256):
        s = sbox[i]
        s2 = xt(s)
        s3 = s2 ^ s
        t0.append((s2 << 24) | (s << 16) | (s << 8) | s3)
    t1 = [((v >> 8) | (v << 24)) & 0xffffffff for v in t0]
    t2 = [((v >> 16) | (v << 16)) & 0xffffffff for v in t0]
    t3 = [((v >> 24) | (v << 8)) & 0xffffffff for v in t0]
    return sbox, t0, t1, t2, t3


_AES = None


def _aes_expand(key):
    global _AES
    if _AES is None:
        _AES = _aes_tables()
    sbox = _AES[0]
    w = list(struct.unpack(">4I", key))
    rcon = 1
    for i in range(4, 44):
        t = w[i - 1]
        if i % 4 == 0:
            t = ((t << 8) | (t >> 24)) & 0xffffffff
            t = (sbox[t >> 24] << 24) | (sbox[(t >> 16) & 0xff] << 16) | \
                (sbox[(t >> 8) & 0xff] << 8) | sbox[t & 0xff]
            t ^= rcon << 24
            rcon = ((rcon << 1) ^ 0x1b) & 0xff if rcon & 0x80 else rcon << 1
        w.append(w[i - 4] ^ t)
    return w


def _aes_block(w, block):
    sbox, t0, t1, t2, t3 = _AES
    s0, s1, s2, s3 = struct.unpack(">4I", block)
    s0 ^= w[0]
    s1 ^= w[1]
    s2 ^= w[2]
    s3 ^= w[3]
    k = 4
    for _ in range(9):
        a0 = t0[s0 >> 24] ^ t1[(s1 >> 16) & 0xff] ^ t2[(s2 >> 8) & 0xff] ^ \
            t3[s3 & 0xff] ^ w[k]
        a1 = t0[s1 >> 24] ^ t1[(s2 >> 16) & 0xff] ^ t2[(s3 >> 8) & 0xff] ^ \
            t3[s0 & 0xff] ^ w[k + 1]
        a2 = t0[s2 >> 24] ^ t1[(s3 >> 16) & 0xff] ^ t2[(s0 >> 8) & 0xff] ^ \
            t3[s1 & 0xff] ^ w[k + 2]
        a3 = t0[s3 >> 24] ^ t1[(s0 >> 16) & 0xff] ^ t2[(s1 >> 8) & 0xff] ^ \
            t3[s2 & 0xff] ^ w[k + 3]
        s0, s1, s2, s3 = a0, a1, a2, a3
        k += 4
    o0 = ((sbox[s0 >> 24] << 24) | (sbox[(s1 >> 16) & 0xff] << 16) |
          (sbox[(s2 >> 8) & 0xff] << 8) | sbox[s3 & 0xff]) ^ w[40]
    o1 = ((sbox[s1 >> 24] << 24) | (sbox[(s2 >> 16) & 0xff] << 16) |
          (sbox[(s3 >> 8) & 0xff] << 8) | sbox[s0 & 0xff]) ^ w[41]
    o2 = ((sbox[s2 >> 24] << 24) | (sbox[(s3 >> 16) & 0xff] << 16) |
          (sbox[(s0 >> 8) & 0xff] << 8) | sbox[s1 & 0xff]) ^ w[42]
    o3 = ((sbox[s3 >> 24] << 24) | (sbox[(s0 >> 16) & 0xff] << 16) |
          (sbox[(s1 >> 8) & 0xff] << 8) | sbox[s2 & 0xff]) ^ w[43]
    return struct.pack(">4I", o0, o1, o2, o3)


def aes128_ecb_encrypt(key, block):
    """One AES-128 block (pure Python; used when `cryptography` is not
    installed)."""
    return _aes_block(_aes_expand(key), block)


def _gf128_mul(x, y):
    r = 0xE1000000000000000000000000000000
    z, v = 0, y
    for i in range(127, -1, -1):
        if (x >> i) & 1:
            z ^= v
        v = (v >> 1) ^ r if v & 1 else v >> 1
    return z


def _ghash(h, aad, ct):
    hx = int.from_bytes(h, "big")
    x = 0
    for data in (aad, ct):
        for i in range(0, len(data), 16):
            blk = data[i:i + 16].ljust(16, b"\x00")
            x = _gf128_mul(x ^ int.from_bytes(blk, "big"), hx)
    x = _gf128_mul(x ^ ((len(aad) * 8) << 64 | len(ct) * 8), hx)
    return x.to_bytes(16, "big")


def _aes_gcm_py(key, nonce, data, aad, decrypt=True):
    """AES-128-GCM with a 96-bit nonce, pure Python. decrypt=True: `data`
    is ciphertext‖tag → plaintext or None on a bad tag."""
    w = _aes_expand(key)
    h = _aes_block(w, b"\x00" * 16)
    j0 = nonce + b"\x00\x00\x00\x01"
    if decrypt:
        if len(data) < 16:
            return None
        ct, tag = data[:-16], data[-16:]
    else:
        ct = None
    src = ct if decrypt else data
    out = bytearray(len(src))
    ctr = 2
    for i in range(0, len(src), 16):
        ks = _aes_block(w, nonce + struct.pack(">I", ctr))
        ctr += 1
        chunk = src[i:i + 16]
        for j, b in enumerate(chunk):
            out[i + j] = b ^ ks[j]
    cipher = ct if decrypt else bytes(out)
    s = _ghash(h, aad, cipher)
    ek = _aes_block(w, j0)
    tag_calc = bytes(a ^ b for a, b in zip(s, ek))
    if decrypt:
        import hmac
        return bytes(out) if hmac.compare_digest(tag_calc, tag) else None
    return bytes(out) + tag_calc


_QUIC_CRYPTO = None


def _quic_crypto():
    """(ecb(key, block), gcm_open(key, nonce, data, aad)) — the fast
    `cryptography` versions when installed, else pure Python."""
    global _QUIC_CRYPTO
    if _QUIC_CRYPTO is not None:
        return _QUIC_CRYPTO
    try:
        from cryptography.hazmat.primitives.ciphers import (Cipher,
                                                            algorithms,
                                                            modes)
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        from cryptography.exceptions import InvalidTag

        def ecb(key, block):
            enc = Cipher(algorithms.AES(key), modes.ECB()).encryptor()
            return enc.update(block) + enc.finalize()

        def gcm_open(key, nonce, data, aad):
            try:
                return AESGCM(key).decrypt(nonce, data, aad)
            except InvalidTag:
                return None
        _QUIC_CRYPTO = (ecb, gcm_open, "cryptography")
    except Exception as e:                           # noqa: BLE001
        LOG.debug("QUIC decryption uses pure Python: %s", e)
        _QUIC_CRYPTO = (aes128_ecb_encrypt,
                        lambda k, n, d, a: _aes_gcm_py(k, n, d, a, True),
                        "pure Python")
    return _QUIC_CRYPTO


def quic_varint(buf, pos):
    if pos >= len(buf):
        raise ValueError("varint past end")
    first = buf[pos]
    n = 1 << (first >> 6)
    if pos + n > len(buf):
        raise ValueError("short varint")
    v = first & 0x3f
    for i in range(1, n):
        v = (v << 8) | buf[pos + i]
    return v, pos + n


def quic_long_header(buf):
    """Parse a long-header packet's clear part. → dict or None."""
    if len(buf) < 7 or not buf[0] & 0x80:
        return None
    version = struct.unpack_from(">I", buf, 1)[0]
    pos = 5
    dl = buf[pos]
    pos += 1
    if dl > 20 or pos + dl >= len(buf):
        return None
    dcid = bytes(buf[pos:pos + dl])
    pos += dl
    sl = buf[pos]
    pos += 1
    if sl > 20 or pos + sl > len(buf):
        return None
    scid = bytes(buf[pos:pos + sl])
    pos += sl
    ptype = (buf[0] >> 4) & 0x03
    out = {"version": version, "dcid": dcid, "scid": scid, "type": ptype,
           "token": b"", "pn_offset": 0, "length": 0, "end": len(buf)}
    if version not in QUIC_SALTS or ptype != QUIC_INITIAL_TYPE[version]:
        return out
    tl, pos = quic_varint(buf, pos)
    out["token"] = bytes(buf[pos:pos + tl])
    pos += tl
    ln, pos = quic_varint(buf, pos)
    out["pn_offset"] = pos
    out["length"] = ln
    out["end"] = min(len(buf), pos + ln)
    out["initial"] = True
    return out


def quic_decrypt_initial(buf, side="client"):
    """Remove header protection and decrypt one Initial packet (the first
    packet in `buf`). → (header dict, plaintext frames) or (hdr, None)."""
    hdr = quic_long_header(buf)
    if not hdr or not hdr.get("initial"):
        return hdr, None
    ecb, gcm_open, _impl = _quic_crypto()
    key, iv, hp = quic_initial_keys(hdr["dcid"], hdr["version"], side)
    pn_off = hdr["pn_offset"]
    if pn_off + 4 + 16 > hdr["end"]:
        return hdr, None
    sample = bytes(buf[pn_off + 4:pn_off + 20])
    mask = ecb(hp, sample)
    first = buf[0] ^ (mask[0] & 0x0f)
    pn_len = (first & 0x03) + 1
    pn_bytes = bytes(b ^ m for b, m in zip(buf[pn_off:pn_off + pn_len],
                                           mask[1:1 + pn_len]))
    pn = int.from_bytes(pn_bytes, "big")
    aad = bytes([first]) + bytes(buf[1:pn_off]) + pn_bytes
    nonce = bytes(a ^ b for a, b in zip(iv, pn.to_bytes(12, "big")))
    payload = bytes(buf[pn_off + pn_len:hdr["end"]])
    plain = gcm_open(key, nonce, payload, aad)
    hdr["pn"] = pn
    return hdr, plain


def quic_crypto_frames(plain):
    """CRYPTO frame pieces [(offset, bytes)] from an Initial packet's
    frames. Raises ValueError on frames an Initial may not carry."""
    out = []
    pos, n = 0, len(plain)
    while pos < n:
        ft = plain[pos]
        if ft == 0x00:                                # PADDING
            pos += 1
        elif ft == 0x01:                              # PING
            pos += 1
        elif ft in (0x02, 0x03):                      # ACK
            pos += 1
            _largest, pos = quic_varint(plain, pos)
            _delay, pos = quic_varint(plain, pos)
            count, pos = quic_varint(plain, pos)
            _first, pos = quic_varint(plain, pos)
            for _ in range(min(count, 256)):
                _g, pos = quic_varint(plain, pos)
                _l, pos = quic_varint(plain, pos)
            if ft == 0x03:
                for _ in range(3):
                    _e, pos = quic_varint(plain, pos)
        elif ft == 0x06:                              # CRYPTO
            off, pos = quic_varint(plain, pos + 1)
            ln, pos = quic_varint(plain, pos)
            if pos + ln > n:
                raise ValueError("short crypto frame")
            out.append((off, plain[pos:pos + ln]))
            pos += ln
        elif ft in (0x1c, 0x1d):                      # CONNECTION_CLOSE
            break
        else:
            raise ValueError(f"frame {ft:#x} not allowed in Initial")
    return out


class QuicInitialReader:
    """Stitches a ClientHello split over several Initial packets (modern
    browsers send post-quantum key shares, so it often needs two) and
    reads the server name. Bounded: 512 connections, 64 KiB each, 5 s;
    at most `budget` packets decrypted per second."""

    MAX_ENTRIES = 512
    MAX_BYTES = 65536
    TTL = 5.0

    def __init__(self, budget=None):
        self.buf = OrderedDict()
        self.done = OrderedDict()
        if budget is None:          # the pure-Python fallback is ~35× slower
            budget = 300 if _quic_crypto()[2] == "cryptography" else 40
        self.budget = budget
        self._window = [0.0, 0]
        self.decrypted = self.failed = self.skipped = 0

    def _allowed(self, ts):
        w = self._window
        if ts - w[0] >= 1.0 or ts < w[0]:
            w[0], w[1] = ts, 0
        if w[1] >= self.budget:
            self.skipped += 1
            return False
        w[1] += 1
        return True

    def feed(self, key, datagram, ts):
        """→ parse_tls_hello() dict once the ClientHello is complete
        (with "via": "quic"), else None."""
        try:
            hdr = quic_long_header(datagram)
        except (ValueError, IndexError, struct.error):  # QA-10: cut short
            return None
        if not hdr or not hdr.get("initial"):
            return None
        ck = (key, hdr["dcid"])
        if ck in self.done:
            return None                       # retransmission: already read
        if not self._allowed(ts):
            return None
        try:
            hdr, plain = quic_decrypt_initial(datagram)
            frames = quic_crypto_frames(plain) if plain else None
        except (ValueError, IndexError, struct.error):
            frames = None
        if frames is None:
            self.failed += 1
            return None
        self.decrypted += 1
        ent = self.buf.get(ck)
        if ent is None:
            ent = self.buf[ck] = {"hs": bytearray(), "parts": {}, "ts": ts}
            self._trim(ts)
        for off, data in frames:
            if off < self.MAX_BYTES:
                self._add(ent, off, data)
        hs = bytes(ent["hs"])
        if len(hs) < 4:
            return None
        if hs[0] != 1:                        # not a ClientHello
            self.buf.pop(ck, None)
            return None
        need = 4 + int.from_bytes(hs[1:4], "big")
        if len(hs) < need and len(hs) < self.MAX_BYTES:
            return None
        self.buf.pop(ck, None)
        self.done[ck] = ts
        while len(self.done) > 4 * self.MAX_ENTRIES:
            self.done.popitem(last=False)
        body = hs[:min(need, 16384)]
        rec = b"\x16\x03\x01" + struct.pack(">H", len(body)) + body
        info = parse_tls_hello(rec)
        if not info or info.get("kind") != "client":
            return None
        info["via"] = "quic"
        info["quic_version"] = "v2" if hdr["version"] == QUIC_V2 else "v1"
        return info

    MAX_PIECES = 64

    @classmethod
    def _add(cls, ent, off, data):
        """5.3.4 (QA-04): keep the stitched prefix and only the pieces
        that come after a gap (at most MAX_PIECES), so each packet costs
        its own size instead of re-walking every piece seen so far."""
        hs, parts = ent["hs"], ent["parts"]
        if off > len(hs):
            if len(parts) < cls.MAX_PIECES or off in parts:
                parts[off] = data
            return
        if off + len(data) > len(hs):
            hs += data[len(hs) - off:]
        while parts:
            nxt = next((o for o in parts if o <= len(hs)), None)
            if nxt is None:
                return
            d = parts.pop(nxt)
            if nxt + len(d) > len(hs):
                hs += d[len(hs) - nxt:]

    def _trim(self, ts):
        while len(self.buf) > self.MAX_ENTRIES:
            self.buf.popitem(last=False)
        for k in list(self.buf):
            if ts - self.buf[k]["ts"] > self.TTL:
                self.buf.pop(k, None)
            else:
                break


def quic_build_initial(dcid, scid, crypto, pn=0, version=QUIC_V1,
                       crypto_offset=0, pad_to=1200, frames=None):
    """Build a client Initial packet (tests, demo data and the self-test).
    `crypto` = ClientHello bytes (no record header) placed at
    `crypto_offset`; `frames` = raw frame bytes to use instead."""
    if frames is None:
        frames = b"\x06" + _quic_varint_enc(crypto_offset) + \
            _quic_varint_enc(len(crypto)) + crypto
    key, iv, hp = quic_initial_keys(dcid, version)
    pn_len = 4
    first = 0xc0 | (QUIC_INITIAL_TYPE[version] << 4) | (pn_len - 1)
    head = bytes([first]) + struct.pack(">I", version) + bytes([len(dcid)]) \
        + dcid + bytes([len(scid)]) + scid + _quic_varint_enc(0)
    overhead = len(head) + 2 + pn_len + 16
    if overhead + len(frames) < pad_to:
        frames = frames + b"\x00" * (pad_to - overhead - len(frames))
    length = pn_len + len(frames) + 16
    head += struct.pack(">H", 0x4000 | length)
    pn_bytes = pn.to_bytes(pn_len, "big")
    aad = head + pn_bytes
    nonce = bytes(a ^ b for a, b in zip(iv, pn.to_bytes(12, "big")))
    sealed = _aes_gcm_py(key, nonce, frames, aad, decrypt=False)
    pkt = bytearray(aad + sealed)
    pn_off = len(head)
    ecb = _quic_crypto()[0]
    mask = ecb(hp, bytes(pkt[pn_off + 4:pn_off + 20]))
    pkt[0] ^= mask[0] & 0x0f
    for i in range(pn_len):
        pkt[pn_off + i] ^= mask[1 + i]
    return bytes(pkt)


def _quic_varint_enc(v):
    if v < 0x40:
        return bytes([v])
    if v < 0x4000:
        return struct.pack(">H", 0x4000 | v)
    if v < 0x40000000:
        return struct.pack(">I", 0x80000000 | v)
    return struct.pack(">Q", 0xC000000000000000 | v)


def tls_client_hello(sni, alpn=("h3",), ech=False, pad_ext=0):
    """A minimal TLS 1.3 ClientHello handshake message (no record header)
    for tests and demo data."""
    def ext(t, body):
        return struct.pack(">HH", t, len(body)) + body
    name = sni.encode()
    exts = ext(0, struct.pack(">HBH", len(name) + 3, 0, len(name)) + name)
    al = b"".join(bytes([len(a)]) + a.encode() for a in alpn)
    exts += ext(16, struct.pack(">H", len(al)) + al)
    exts += ext(43, b"\x02\x03\x04")
    if ech:
        exts += ext(0xfe0d, b"\x00" * 32)
    if pad_ext:
        exts += ext(21, b"\x00" * pad_ext)
    body = b"\x03\x03" + bytes(32) + b"\x00" + b"\x00\x02\x13\x01" + \
        b"\x01\x00" + struct.pack(">H", len(exts)) + exts
    return b"\x01" + len(body).to_bytes(3, "big") + body


QUIC_NAMES = {"enabled": True}       # Settings → Privacy can turn it off


def _quic_label(d, load, reasm, ts):
    """Shared by both decoders: label a QUIC datagram and, for a client's
    first packets, read the site name from the ClientHello."""
    d.update({"proto": "QUIC", "tag": "QUIC",
              "text": "Secure web connection (QUIC — the site name "
                      "is encrypted)",
              "app_conf": "Observed", "encrypted": "yes",
              "service": "Secure web browsing (QUIC)"})
    reader = getattr(reasm, "quic", None)
    if reader is None or not QUIC_NAMES["enabled"] or d["dport"] != 443:
        return
    info = reader.feed((d["src_ip"], d["sport"], d["dst_ip"]), load,
                       float(ts))
    if not info:
        return
    d["tls"] = info
    sni = info.get("sni", "")
    if sni:
        d["text"] = (f"Secure connection to {sni} (HTTP/3 — the name was "
                     f"read from the connection's first packet)")
        if info.get("ech"):
            d["text"] += (" (Encrypted Client Hello — the real site may be "
                          "hidden behind this name)")
        d["dns_names"].append(sni)
        if d["dst_ip"]:
            d["learns"].append((d["dst_ip"], sni))
        hint = doh_name(sni)
        if hint:
            d["doh_hint"] = hint
    else:
        d["text"] = "Secure connection (HTTP/3 — site name not visible)"


def packet_object(d):
    """The scapy packet for a decoded row (built on demand, then cached)."""
    pkt = d.get("pkt")
    if pkt is not None:
        return pkt
    raw = d.get("raw")
    if raw is None or Ether is None:
        return None
    lt = d.get("linktype", 1)
    try:
        cls = Ether if lt == 1 else (conf.l2types.get(lt) or Raw)
        pkt = cls(raw)
    except Exception:                                # noqa: BLE001
        pkt = Raw(raw)
    pkt.time = d.get("time", 0.0)
    d["pkt"] = pkt
    return pkt


# ---- LLDP and CDP: the switch tells this computer which port it is on ------
LLDP_CAPS = ((0x04, "switch"), (0x08, "Wi-Fi access point"),
             (0x10, "router"), (0x20, "phone"), (0x02, "repeater"),
             (0x40, "cable modem"), (0x80, "station"), (0x01, "other"))
CDP_CAPS = ((0x08, "switch"), (0x01, "router"), (0x02, "bridge"),
            (0x10, "host"), (0x80, "phone"), (0x40, "repeater"),
            (0x200, "two-port MAC relay"))
CDP_SNAP = b"\xaa\xaa\x03\x00\x00\x0c\x20\x00"


def _disc_text(b, limit=120):
    return sanitize_text(bytes(b).decode("utf-8", "replace"), limit)


def _lldp_id(sub, data, port=False):
    if (sub == 4 and not port or sub == 3 and port) and len(data) == 6:
        return _mac(data)
    if (sub == 5 and not port or sub == 4 and port) and len(data) >= 5 \
            and data[0] == 1:
        return _ip4(data[1:5])
    return _disc_text(data)


def parse_lldp(buf):
    """LLDP (IEEE 802.1AB) TLVs → plain facts. Tolerates truncation."""
    out = {"proto": "LLDP", "chassis": "", "port": "", "port_desc": "",
           "system": "", "descr": "", "caps": [], "mgmt": "", "vlan": None,
           "ttl": None}
    pos, n = 0, len(buf)
    while pos + 2 <= n:
        hdr = struct.unpack_from(">H", buf, pos)[0]
        t, ln = hdr >> 9, hdr & 0x1ff
        pos += 2
        v = buf[pos:pos + ln]
        pos += ln
        if t == 0:
            break
        if t == 1 and len(v) >= 2:
            out["chassis"] = _lldp_id(v[0], v[1:])
        elif t == 2 and len(v) >= 2:
            out["port"] = _lldp_id(v[0], v[1:], port=True)
        elif t == 3 and len(v) >= 2:
            out["ttl"] = struct.unpack(">H", v[:2])[0]
        elif t == 4:
            out["port_desc"] = _disc_text(v)
        elif t == 5:
            out["system"] = _disc_text(v)
        elif t == 6:
            out["descr"] = _disc_text(v, 200)
        elif t == 7 and len(v) >= 4:
            en = struct.unpack(">H", v[2:4])[0]
            out["caps"] = [nm for bit, nm in LLDP_CAPS if en & bit]
        elif t == 8 and len(v) >= 2 and not out["mgmt"]:
            alen, sub = v[0], v[1]
            addr = v[2:1 + alen]
            if sub == 1 and len(addr) == 4:
                out["mgmt"] = _ip4(addr)
            elif sub == 2 and len(addr) == 16:
                out["mgmt"] = _ip6(addr)
        elif t == 127 and len(v) >= 6 and v[:3] == b"\x00\x80\xc2" and \
                v[3] == 1:
            out["vlan"] = struct.unpack(">H", v[4:6])[0]
    return out if (out["chassis"] or out["system"]) else None


def parse_cdp(buf):
    """Cisco Discovery Protocol (after the SNAP header) → plain facts."""
    out = {"proto": "CDP", "chassis": "", "port": "", "port_desc": "",
           "system": "", "descr": "", "caps": [], "mgmt": "", "vlan": None,
           "ttl": None, "platform": ""}
    if len(buf) < 4:
        return None
    out["ttl"] = buf[1]
    pos, n = 4, len(buf)
    while pos + 4 <= n:
        t, ln = struct.unpack_from(">HH", buf, pos)
        if ln < 4:
            break
        v = buf[pos + 4:pos + ln]
        pos += ln
        if t == 0x01:
            out["system"] = out["chassis"] = _disc_text(v)
        elif t in (0x02, 0x16) and len(v) >= 4 and not out["mgmt"]:
            p = 4
            for _ in range(min(8, struct.unpack(">I", v[:4])[0])):
                if p + 2 > len(v):
                    break
                ptype, plen = v[p], v[p + 1]
                proto = v[p + 2:p + 2 + plen]
                p += 2 + plen
                if p + 2 > len(v):
                    break
                alen = struct.unpack(">H", v[p:p + 2])[0]
                addr = v[p + 2:p + 2 + alen]
                p += 2 + alen
                if ptype == 1 and proto == b"\xcc" and len(addr) == 4:
                    out["mgmt"] = _ip4(addr)
                    break
        elif t == 0x03:
            out["port"] = _disc_text(v)
        elif t == 0x04 and len(v) >= 4:
            en = struct.unpack(">I", v[:4])[0]
            out["caps"] = [nm for bit, nm in CDP_CAPS if en & bit]
        elif t == 0x05:
            out["descr"] = _disc_text(v, 200)
        elif t == 0x06:
            out["platform"] = _disc_text(v)
        elif t == 0x0a and len(v) >= 2:
            out["vlan"] = struct.unpack(">H", v[:2])[0]
    return out if out["system"] else None


def l2_discovery(raw):
    """LLDP or CDP facts from a raw Ethernet frame, else None."""
    if len(raw) < 22:
        return None
    et = struct.unpack_from(">H", raw, 12)[0]
    if et == 0x88cc:
        return parse_lldp(raw[14:])
    if et < 0x0600 and raw[14:22] == CDP_SNAP:
        return parse_cdp(raw[22:])
    return None


def _label_l2_discovery(d, info):
    d["proto"] = d["tag"] = info["proto"]
    d["lldp"] = info
    d["app_conf"] = "Observed"
    d["encrypted"] = "no"
    d["src"], d["dst"] = d["src_mac"], d["dst_mac"]
    name = info["system"] or info["chassis"]
    what = ", ".join(info["caps"][:2]) or "network device"
    port = info["port_desc"] or info["port"]
    d["text"] = (f"{what.capitalize()} “{name}” says this link is its port "
                 f"{port or '?'}" + (f" (VLAN {info['vlan']})"
                                     if info["vlan"] else "") +
                 f" — {info['proto']}")
    return d


def _fast_new(raw, ts, lt):
    return {"proto": "?", "tag": "OTHER", "text": "",
            "src": "", "dst": "", "src_ip": "", "dst_ip": "",
            "src_mac": "", "dst_mac": "", "ttl": "", "ttl_int": 0,
            "sport": None, "dport": None, "ipver": 0, "transport": "",
            "tcp_flags": None, "seq": None, "ack": None, "win": None,
            "payload_len": 0,
            "dns_names": [], "doh_hint": "", "plain_dns": False,
            "type_hint": "", "dhcp_msgtype": None, "arp_op": None,
            "dhcp_yiaddr": "", "dhcp_hostname": "", "dhcp_client_mac": "",
            "dhcp": None, "dns": None, "tls": None, "nd": None,
            "ssdp": None, "mdns": None, "http_host": "", "lldp": None,
            "service": "", "service_port": None, "app_conf": "",
            "encrypted": "unknown", "cleartext": "",
            "multicast": False, "l2_bcast": False,
            "learns": [], "pkt": None, "raw": raw, "linktype": lt,
            "time": ts, "length": len(raw)}


def fast_decode(raw, ts, lt=1, reasm=None, gateway_ip="", my_ips=()):
    """Raw frame bytes → decoded dict (same shape as decode_packet()).
    Falls back to the scapy decoder when it declines the frame."""
    try:
        return _fast_decode(raw, ts, lt, reasm)
    except (NeedDeepParse, struct.error, IndexError, ValueError, TypeError):
        pass
    if Ether is None:
        return _row_from_dissection(raw, ts, lt)
    try:
        cls = Ether if lt == 1 else (conf.l2types.get(lt) or Raw)
        pkt = cls(raw)
    except Exception:                                # noqa: BLE001
        pkt = Raw(raw)
    pkt.time = ts
    try:
        d = decode_packet(pkt, gateway_ip, my_ips, reasm)
    except Exception as e:                           # noqa: BLE001
        d = _fast_new(raw, ts, lt)
        d["text"] = f"Undecodable frame ({type(e).__name__})"
        d["pkt"] = pkt
        return d
    d["time"] = ts
    d["raw"] = raw
    d["linktype"] = lt
    return d


def _row_from_dissection(raw, ts, lt):
    """A basic row from MiniWireshark's own dissector, for frames the fast
    path declines when scapy is not available (limited mode)."""
    d = _fast_new(raw, ts, lt)
    dis = dissect(raw, lt)
    d["src_ip"] = dis.get("ip.src") or dis.get("ipv6.src") or ""
    d["dst_ip"] = dis.get("ip.dst") or dis.get("ipv6.dst") or ""
    d["src"], d["dst"] = d["src_ip"], d["dst_ip"]
    d["src_mac"] = dis.get("eth.src") or dis.get("sll.src.eth") or ""
    d["dst_mac"] = dis.get("eth.dst") or ""
    for t in ("tcp", "udp"):
        if dis.get(f"{t}.srcport") is not None:
            d["sport"], d["dport"] = dis.get(f"{t}.srcport"), \
                dis.get(f"{t}.dstport")
            d["transport"] = t.upper()
    top = next((n for n in reversed(dis.nodes)
                if n.key not in ("frame", "data", "text")), None)
    name = {"ip": "IPv4", "ipv6": "IPv6", "eth": "Ethernet", "sll": "Linux",
            "vlan": "VLAN"}.get(top.key, top.key.upper()) if top else "?"
    d["proto"], d["tag"] = name, name if name in (
        "TCP", "UDP", "DNS", "ARP", "ICMP", "DHCP", "TLS", "QUIC",
        "HTTP") else "OTHER"
    d["ipver"] = 4 if dis.get("ip.src") else 6 if dis.get("ipv6.src") \
        else 0
    d["text"] = (top.title if top else "Frame") + " (basic decode)"
    return d


def _fast_decode(raw, ts, lt, reasm):
    d = _fast_new(raw, ts, lt)
    n = len(raw)
    if lt == 1:
        if n < 14:
            raise NeedDeepParse("runt")
        dst, src = raw[0:6], raw[6:12]
        d["dst_mac"], d["src_mac"] = _mac(dst), _mac(src)
        d["l2_bcast"] = dst == b"\xff\xff\xff\xff\xff\xff"
        if dst[0] & 1 or dst == b"\x00\x00\x00\x00\x00\x00":
            d["multicast"] = True
        et = _U16.unpack_from(raw, 12)[0]
        off = 14
        vlans = 0
        while et in (0x8100, 0x88a8) and vlans < 2:   # (scapy: not 0x9100)
            if n < off + 4:
                raise NeedDeepParse("vlan")
            et = _U16.unpack_from(raw, off + 2)[0]
            off += 4
            vlans += 1
        if et < 0x0600:
            if raw[14:22] == CDP_SNAP:
                info = parse_cdp(raw[22:])
                if info:
                    return _label_l2_discovery(d, info)
            raise NeedDeepParse("802.3/LLC")
    elif lt == 113:                                   # Linux cooked v1
        if n < 16:
            raise NeedDeepParse("runt")
        et, off = _U16.unpack_from(raw, 14)[0], 16
    elif lt == 276:                                   # Linux cooked v2
        if n < 20:
            raise NeedDeepParse("runt")
        et, off = _U16.unpack_from(raw, 0)[0], 20
    elif lt in (101, 12, 14, 228, 229):               # raw IP
        if not n:
            raise NeedDeepParse("empty")
        v = raw[0] >> 4
        et, off = (0x0800 if v == 4 else 0x86DD if v == 6 else 0), 0
        if not et:
            raise NeedDeepParse("raw ip")
    elif lt == 0:                                     # BSD loopback
        if n < 4:
            raise NeedDeepParse("runt")
        fam = struct.unpack_from("<I", raw, 0)[0]
        et, off = (0x0800 if fam == 2 else 0x86DD if fam in (24, 28, 30)
                   else 0), 4
        if not et:
            raise NeedDeepParse("loopback family")
    else:
        raise NeedDeepParse(f"linktype {lt}")

    if et == 0x0806:
        return _fast_arp(d, raw, off)
    if et == 0x88cc:
        info = parse_lldp(raw[off:])
        if info:
            return _label_l2_discovery(d, info)
    if et == 0x0800:
        return _fast_ipv4(d, raw, off, reasm)
    if et == 0x86DD:
        return _fast_ipv6(d, raw, off, reasm)
    name = _ETHER_NAMES.get(et)
    if name is None:
        raise NeedDeepParse(f"ethertype {et:#x}")
    d["proto"] = name
    d["text"] = f"{name} frame"
    d["src"], d["dst"] = d["src_mac"], d["dst_mac"]
    return d


def _fast_arp(d, raw, off):
    if len(raw) < off + 28:
        raise NeedDeepParse("short arp")
    htype, ptype, hlen, plen, op = struct.unpack_from(">HHBBH", raw, off)
    if htype != 1 or ptype != 0x0800 or hlen != 6 or plen != 4:
        raise NeedDeepParse("unusual arp")
    hwsrc = _mac(raw[off + 8:off + 14])
    psrc = _ip4(raw[off + 14:off + 18])
    hwdst = _mac(raw[off + 18:off + 24])
    pdst = _ip4(raw[off + 24:off + 28])
    d["src_ip"], d["dst_ip"] = psrc, pdst
    d["src_mac"], d["dst_mac"] = hwsrc, hwdst
    d["proto"], d["tag"], d["transport"] = "ARP", "ARP", "ARP"
    d["arp_op"] = op
    if op == 1:
        if psrc == pdst:
            d["text"] = f"{psrc} announced itself (gratuitous ARP)"
        else:
            d["text"] = f"Who has {pdst}? Tell {psrc}"
    elif op == 2:
        d["text"] = f"{psrc} is at {hwsrc}"
    else:
        d["text"] = f"ARP op={op}"
    d["src"] = psrc or hwsrc
    d["dst"] = pdst or hwdst
    d["ipver"] = 4
    return d


def _fast_ipv4(d, raw, off, reasm):
    n = len(raw)
    if n < off + 20:
        raise NeedDeepParse("short ipv4")
    vihl = raw[off]
    ihl = (vihl & 0x0F) * 4
    if vihl >> 4 != 4 or ihl < 20 or n < off + ihl:
        raise NeedDeepParse("bad ipv4 header")
    total = _U16.unpack_from(raw, off + 2)[0]
    frag = _U16.unpack_from(raw, off + 6)[0]
    ttl, proto = raw[off + 8], raw[off + 9]
    src, dst = _ip4(raw[off + 12:off + 16]), _ip4(raw[off + 16:off + 20])
    d["src_ip"], d["dst_ip"] = src, dst
    d["ttl"], d["ttl_int"], d["ipver"] = str(ttl), ttl, 4
    if is_multicast_or_broadcast(dst):
        d["multicast"] = True
    if frag & 0x1FFF or frag & 0x2000:
        raise NeedDeepParse("fragment")
    end = off + total if ihl <= total and off + total <= n else n
    l4 = off + ihl
    return _fast_l4(d, raw, proto, l4, end, reasm, 4)


def _fast_ipv6(d, raw, off, reasm):
    n = len(raw)
    if n < off + 40:
        raise NeedDeepParse("short ipv6")
    if raw[off] >> 4 != 6:
        raise NeedDeepParse("bad ipv6")
    plen = _U16.unpack_from(raw, off + 4)[0]
    nh, hlim = raw[off + 6], raw[off + 7]
    src, dst = _ip6(raw[off + 8:off + 24]), _ip6(raw[off + 24:off + 40])
    d["src_ip"], d["dst_ip"] = src, dst
    d["ttl"], d["ttl_int"], d["ipver"] = str(hlim), hlim, 6
    if is_multicast_or_broadcast(dst):
        d["multicast"] = True
    end = off + 40 + plen if off + 40 + plen <= n else n
    p = off + 40
    hops = 0
    while nh in (0, 43, 60) and hops < 6:
        if p + 2 > end:
            raise NeedDeepParse("short extension header")
        nh, hl = raw[p], (raw[p + 1] + 1) * 8
        p += hl
        hops += 1
    if nh == 44:
        raise NeedDeepParse("ipv6 fragment")
    return _fast_l4(d, raw, nh, p, end, reasm, 6)


def _fast_l4(d, raw, proto, p, end, reasm, ipver):
    if proto == 6:
        return _fast_tcp(d, raw, p, end, reasm)
    if proto == 17:
        return _fast_udp(d, raw, p, end, reasm)
    if proto == 1 and ipver == 4:
        # (scapy leaves a timestamp/address-mask message cut short as Raw)
        if end - p < 8 or \
                end - p < {13: 20, 14: 20, 17: 12, 18: 12}.get(raw[p], 8):
            raise NeedDeepParse("short icmp")
        t, code = raw[p], raw[p + 1]
        d["proto"], d["tag"], d["transport"] = "ICMP", "ICMP", "ICMP"
        d["sport"], d["dport"] = t, code
        d["text"] = _ICMP4_TEXT.get(t, f"ICMP type {t}")
        return _fast_done(d)
    if proto == 58 and ipver == 6:
        return _fast_icmpv6(d, raw, p, end)
    if proto == 2 and ipver == 4:
        d.update({"proto": "IGMP", "tag": "IGMP", "transport": "IGMP",
                  "text": "Joining/leaving a multicast group (IGMP)"})
        return _fast_done(d)
    name = _IPPROTO_NAMES.get(proto)
    if name is None or proto in (4, 41, 47):
        # tunnels: scapy decodes the inner packet
        raise NeedDeepParse(f"ip proto {proto}")
    d["proto"] = name
    d["text"] = f"{name} frame"
    return _fast_done(d)


def _fast_done(d):
    d["src"] = d["src_ip"] or d["src_mac"]
    d["dst"] = d["dst_ip"] or d["dst_mac"]
    return d


def _fast_tcp(d, raw, p, end, reasm):
    if end - p < 20:
        raise NeedDeepParse("short tcp")
    sport, dport, seq = struct.unpack_from(">HHI", raw, p)
    dataofs = (raw[p + 12] >> 4) * 4
    flags = raw[p + 13] | ((raw[p + 12] & 1) << 8)
    if dataofs < 20 or p + dataofs > end:
        raise NeedDeepParse("bad tcp header")
    d["sport"], d["dport"] = sport, dport
    d["transport"] = "TCP"
    d["proto"], d["tag"] = "TCP", "TCP"
    d["tcp_flags"] = flags
    d["seq"] = seq
    d["ack"], d["win"] = struct.unpack_from(">I", raw, p + 8)[0], \
        struct.unpack_from(">H", raw, p + 14)[0]
    names = [nm for b, nm in _TCP_FLAG_NAMES if flags & b]
    svc, sport_ = _port_service(sport, dport)
    d["service"], d["service_port"] = svc, sport_
    if svc:
        d["text"] = f"{svc} ({','.join(names) or 'data'})"
        d["app_conf"] = "Likely (by port)"
    else:
        d["text"] = f"Connecting ({','.join(names) or 'data'})"
    if sport_ in ENCRYPTED_PORTS:
        d["encrypted"] = "likely"
    load = raw[p + dataofs:end]
    # scapy takes DNS over TCP only when the length prefix fits the segment
    if 53 in (sport, dport) and len(load) > 2 and \
            14 <= _U16.unpack_from(load, 0)[0] <= len(load):
        try:
            text, learns, hint, info = wire_dns(load[2:], "DNS")
        except ValueError:
            raise NeedDeepParse("odd dns/tcp")
        info["transport"] = "TCP"
        d.update({"proto": "DNS", "tag": "DNS", "text": text + " (TCP)",
                  "dns": info, "app_conf": "Observed"})
        d["learns"].extend(learns)
        d["plain_dns"] = dport == 53
        d["encrypted"] = "no"
        return _fast_done(d)
    d["payload_len"] = len(load)
    if load:
        _decode_tcp_payload(d, bytes(load), reasm)
    if not d["cleartext"] and d["payload_len"] and \
            sport_ in CLEARTEXT_PORTS:
        d["cleartext"] = CLEARTEXT_PORTS[sport_]
        d["encrypted"] = "no"
    return _fast_done(d)


def _fast_udp(d, raw, p, end, reasm=None):
    if end - p < 8:
        raise NeedDeepParse("short udp")
    sport, dport, ulen = struct.unpack_from(">HHH", raw, p)
    d["sport"], d["dport"] = sport, dport
    d["transport"] = "UDP"
    ports = (sport, dport)
    if ulen < 8:
        raise NeedDeepParse("bad udp length")    # scapy's own reading
    load = bytes(raw[p + 8:end][:ulen - 8])
    d["payload_len"] = ulen - 8
    if (53 in ports or 5353 in ports or 5355 in ports) and len(load) >= 12:
        name = "mDNS" if 5353 in ports else "LLMNR" if 5355 in ports \
            else "DNS"
        try:
            text, learns, hint, info = wire_dns(load, name)
        except ValueError:
            raise NeedDeepParse("odd dns")
        if dport == 53:
            d["plain_dns"] = True
        info["transport"] = "UDP"
        d.update({"proto": name, "tag": name, "text": text,
                  "app_conf": "Observed", "encrypted": "no"})
        if name == "mDNS":
            d["mdns"] = info
        else:
            d["dns"] = info
        d["learns"].extend(learns)
        if hint:
            d["type_hint"] = hint
    elif ports in ((68, 67), (67, 68), (67, 67)) and len(load) >= 240:
        pr, t2, text, learns, info = _wire_dhcp(load)
        d.update({"proto": pr, "tag": t2, "text": text, "dhcp": info,
                  "app_conf": "Observed"})
        d["learns"].extend(learns)
        d["dhcp_msgtype"] = info["msgtype"]
        d["dhcp_yiaddr"] = info["yiaddr"]
        d["dhcp_hostname"] = info["hostname"]
        d["dhcp_client_mac"] = info["client_mac"]
    elif (546 in ports or 547 in ports) and load:
        mt = load[0]
        d.update({"proto": "DHCPv6", "tag": "DHCPv6",
                  "text": "IPv6 address setup: " +
                  DHCPV6_MSG.get(mt, f"message {mt}"),
                  "app_conf": "Observed"})
    elif 137 in ports and load:
        d["proto"], d["tag"] = "NBNS", "NBNS"
        nm = _try_nbns(load)
        if nm and d["src_ip"] and sport == 137 and len(load) > 12 and \
                load[2] & 0x80:
            d["text"] = f"{nm} is at {d['src_ip']} (Windows name)"
            d["learns"].append((d["src_ip"], nm))
        else:
            d["text"] = f"Local name lookup{(': ' + nm) if nm else ''}"
        d["app_conf"] = "Observed"
    elif 1900 in ports and load:
        text, hint, info = _decode_ssdp(load)
        d.update({"proto": "SSDP", "tag": "SSDP", "text": text,
                  "ssdp": info, "app_conf": "Observed"})
        if hint:
            d["type_hint"] = hint
    elif 123 in ports and len(load) >= 48:
        mode = load[0] & 0x07
        d.update({"proto": "NTP", "tag": "NTP",
                  "text": "Checking the time (NTP " +
                  {3: "request", 4: "reply"}.get(mode, "message") + ")",
                  "app_conf": "Observed", "encrypted": "no"})
    elif 443 in ports and load and (load[0] & 0x80):
        _quic_label(d, load, reasm, d["time"])
    elif 443 in ports and load:
        d.update({"proto": "QUIC", "tag": "QUIC",
                  "text": "Secure web connection (fast, encrypted)",
                  "app_conf": "Likely (by port)", "encrypted": "yes"})
    else:
        svc, sp = _port_service(sport, dport)
        d["service"], d["service_port"] = svc, sp
        d["proto"], d["tag"] = "UDP", "UDP"
        if sp in PORT_APP:
            d["proto"] = d["tag"] = PORT_APP[sp]
        d["text"] = (f"{svc} ({d['payload_len']} bytes)" if svc
                     else f"Quick message ({d['payload_len']} bytes)")
        d["app_conf"] = "Likely (by port)" if svc else ""
        if sp in VPN_PORTS:
            d["encrypted"] = "yes"
        elif sp in CLEARTEXT_PORTS:
            d["cleartext"] = CLEARTEXT_PORTS[sp]
            d["encrypted"] = "no"
    return _fast_done(d)


def _nd_options(raw, p, end):
    """ICMPv6 ND options → dict of first src/dst lladdr + prefix list."""
    out = {"src": "", "dst": "", "prefixes": []}
    hops = 0
    while p + 2 <= end and hops < 16:
        t, ln = raw[p], raw[p + 1] * 8
        if ln == 0 or p + ln > end:
            break
        body = raw[p:p + ln]
        if t == 1 and ln >= 8 and not out["src"]:
            out["src"] = _mac(body[2:8])
        elif t == 2 and ln >= 8 and not out["dst"]:
            out["dst"] = _mac(body[2:8])
        elif t == 3 and ln >= 32 and len(out["prefixes"]) < 7:
            out["prefixes"].append(f"{_ip6(body[16:32])}/{body[2]}")
        p += ln
        hops += 1
    return out


def _fast_icmpv6(d, raw, p, end):
    if end - p < 8:
        raise NeedDeepParse("short icmpv6")
    t = raw[p]
    nd = None
    if t == 134 and end - p >= 16:
        opts = _nd_options(raw, p + 16, end)
        nd = {"kind": "RA", "target": d["src_ip"],
              "mac": opts["src"] or d["src_mac"],
              "prefixes": opts["prefixes"],
              "lifetime": _U16.unpack_from(raw, p + 6)[0]}
        d["text"] = "Router announcement (IPv6)" + (
            f" — network {', '.join(opts['prefixes'])}"
            if opts["prefixes"] else "")
    elif t == 133:
        nd = {"kind": "RS", "target": "", "mac": d["src_mac"],
              "prefixes": []}
        d["text"] = "Looking for an IPv6 router (Router Solicitation)"
    elif t == 135 and end - p >= 24:
        tgt = _ip6(raw[p + 8:p + 24])
        opts = _nd_options(raw, p + 24, end)
        nd = {"kind": "NS", "target": tgt, "mac": opts["src"],
              "prefixes": [], "dad": d["src_ip"] == "::"}
        d["text"] = (f"Checking nobody else uses {tgt} (duplicate check)"
                     if nd["dad"] else f"Who has {tgt}? (IPv6)")
    elif t == 136 and end - p >= 24:
        tgt = _ip6(raw[p + 8:p + 24])
        opts = _nd_options(raw, p + 24, end)
        mac = opts["dst"] or d["src_mac"]
        nd = {"kind": "NA", "target": tgt, "mac": mac, "prefixes": [],
              "router": bool(raw[p + 4] & 0x80)}
        d["text"] = f"{tgt} is at {mac or '?'} (IPv6)"
    if nd is not None:
        d.update({"proto": "NDP", "tag": "NDP", "transport": "ICMPv6",
                  "nd": nd, "app_conf": "Observed"})
        return _fast_done(d)
    base = {"proto": "ICMPv6", "tag": "ICMPv6", "transport": "ICMPv6"}
    if t == 128:
        d.update(base, text="Ping request (IPv6)", sport=128, dport=0)
    elif t == 129:
        d.update(base, text="Ping reply (IPv6)", sport=129, dport=0)
    elif t == 1:
        d.update(base, text="Destination unreachable (IPv6)", sport=1,
                 dport=0)
    elif t in _MLD_TYPES:
        d.update(base, text="Multicast group membership report (IPv6)")
    elif t in _ICMP6_NAMES:
        d.update(base, text=_ICMP6_NAMES[t])
    else:
        raise NeedDeepParse(f"icmpv6 type {t}")
    return _fast_done(d)


# ============================================================================
#  6.  Capture workers
#
#  The capture callback only enqueues (it must stay extremely cheap); a
#  decode thread turns packets into dicts; the GUI thread runs analysis in
#  time-boxed batches. Every queue is bounded. When analysis falls behind,
#  capture keeps going and the overflow is counted and shown honestly as
#  "dropped analysis" rather than freezing the window.
# ============================================================================


def probe_l2_socket():
    for mod_name, cls_name in (
            ("scapy.arch.pcapdnet", "L2pcapListenSocket"),
            ("scapy.arch.windows", "L2pcapListenSocket"),
            ("scapy.arch.libpcap", "L2pcapListenSocket"),
            ("scapy.arch.linux", "L2ListenSocket"),
            ("scapy.arch.bsd", "L2ListenSocket")):
        try:
            mod = importlib.import_module(mod_name)
            cls = getattr(mod, cls_name, None)
            if cls is None:
                continue
            params = set(inspect.signature(cls.__init__).parameters)
            return {"snaplen": "snaplen" in params,
                    "promisc": "promisc" in params,
                    "found": f"{mod_name}.{cls_name}"}
        except Exception:                            # noqa: BLE001
            continue
    return {"snaplen": False, "promisc": False, "found": None}


def build_sniffer(iface, prn, bpf, promisc=True):
    """Start an AsyncSniffer, trying the richest options first and falling
    back gracefully on older scapy/backends."""
    p = probe_l2_socket()
    if p["snaplen"] and p["promisc"]:
        variants = [{"promisc": promisc, "snaplen": 262144},
                    {"promisc": promisc}, {}]
    elif p["promisc"]:
        variants = [{"promisc": promisc}, {}]
    else:
        variants = [{}]
    base = {"iface": iface, "prn": prn, "store": False}
    if bpf:
        base["filter"] = bpf
    last = None
    refused = False
    i = 0
    while i < len(variants):
        extra = variants[i]
        i += 1
        try:
            s = AsyncSniffer(**dict(base, **extra))
            s.start()
        except Exception as e:                       # noqa: BLE001
            last = e
        else:
            time.sleep(0.45)
            if getattr(s, "exception", None) is None:
                if refused:
                    s.mw_promisc_refused = True
                return s, None
            last = s.exception
            with contextlib.suppress(Exception):
                s.stop()
        if promisc and p["promisc"] and not refused and \
                refused_promisc(last):
            # 5.2.3: some (mostly Wi-Fi) cards refuse to watch all
            # traffic; "{}" would ask for promiscuous mode again
            refused = True
            variants, i = [{"promisc": False}], 0
    return None, last


def refused_promisc(exc):
    """True when a card refused promiscuous mode (Npcap: "failed to set
    hardware filter to promiscuous mode")."""
    return exc is not None and "promisc" in str(exc).lower()


class NameCache:
    """IP → name learned from DNS answers, TLS SNI, DHCP, mDNS, NBNS and
    reverse DNS. `sources` remembers where each name came from so a guess
    from reverse DNS never outranks what a device announced itself."""

    def __init__(self):
        self.ip_to_name = {}
        self.sources = {}
        self.domain_to_ips = defaultdict(set)
        self.lock = threading.Lock()
        self.version = 0

    def learn(self, ip, name, source="dns"):
        if not ip or not name:
            return False
        name = str(name).strip().rstrip(".")
        if not name:
            return False
        with self.lock:
            if self.ip_to_name.get(ip) == name:
                return False
            if self.sources.get(ip) in ("dhcp", "mdns", "nbns") and \
                    source == "rdns":
                return False
            self.ip_to_name[ip] = name
            self.sources[ip] = source
            ips = self.domain_to_ips[name.lower()]
            ips.add(ip)
            if len(ips) > 64:
                ips.pop()
            if len(self.ip_to_name) > 50000:
                for k in list(self.ip_to_name)[:5000]:
                    self.ip_to_name.pop(k, None)
                    self.sources.pop(k, None)
            self.version += 1
            return True

    def forget(self, ip):
        with self.lock:
            if self.ip_to_name.pop(ip, None) is not None:
                self.sources.pop(ip, None)
                self.version += 1

    def get(self, ip):
        return self.ip_to_name.get(ip, "")

    def source(self, ip):
        return self.sources.get(ip, "")


class ReverseDNS:
    """Background reverse-DNS for *local* addresses only. Results expire
    (addresses get reused), lookups are deduplicated, and the queue is
    bounded so a busy network can't pile up thousands of lookups."""

    TTL = 1800

    def __init__(self, cache, workers=3):
        self.cache = cache
        self.pending, self.done = set(), {}
        self.lock = threading.Lock()
        self.q = queue.Queue(maxsize=512)
        self.delay = 0.0              # raised by the performance governor
        self._stop = False
        for i in range(workers):
            threading.Thread(target=self._worker, daemon=True,
                             name=f"rdns-{i}").start()

    def lookup(self, ip):
        if not ip or ":" in ip or not is_private_ip(ip):
            return
        now = time.time()
        with self.lock:
            if ip in self.pending:
                return
            if now - self.done.get(ip, 0) < self.TTL:
                return
            self.pending.add(ip)
        try:
            self.q.put_nowait(ip)
        except queue.Full:
            with self.lock:
                self.pending.discard(ip)

    def stop(self):
        self._stop = True
        for _ in range(4):
            with contextlib.suppress(queue.Full):
                self.q.put_nowait(None)

    def _worker(self):
        while not self._stop:
            ip = self.q.get()
            if ip is None:
                return
            if self.delay:
                time.sleep(self.delay)
            name = ""
            try:
                outbound("rdns", "dns-ptr", "your DNS server",
                         f"name of {ip}")
                name = _socket.gethostbyaddr(ip)[0]
            except (OSError, UnicodeError):
                name = ""
            with self.lock:
                self.pending.discard(ip)
                self.done[ip] = time.time()
                if len(self.done) > 20000:
                    self.done.clear()
            if name and name != ip:
                self.cache.learn(ip, name, source="rdns")


_LEARN_SOURCE = {"mDNS": "mdns", "DHCP": "dhcp", "NBNS": "nbns",
                 "TLS": "sni", "HTTP": "sni", "DoT": "sni"}


def learn_names_from(cache, d):
    """Feed the IP→name cache from one decoded packet (any thread)."""
    src = _LEARN_SOURCE.get(d["proto"], "dns")
    for ip, name in d["learns"]:
        if src == "dns" and d["proto"] != "LLMNR" and is_private_ip(ip):
            # 5.2.3 (B-15): a DNS answer pointing a name at a local
            # address says nothing about that device (a Pi-hole answers
            # its own address for every blocked ad server and became
            # "ads.doubleclick.net"); its own names come from DHCP, mDNS,
            # NBNS and reverse lookups
            continue
        cache.learn(ip, name, source=src)


class LanScanner(threading.Thread):
    """Quietly nudges devices on your own local Wi-Fi/LAN to speak up, so
    idle/quiet devices show up too — not just the ones already talking.

    This never touches anything beyond your local subnet and never probes
    ports or services: it only sends the same three kinds of harmless,
    standard "is anyone there?" broadcasts that phones, printers, smart
    TVs and file-sharing apps send all the time (ARP, mDNS, SSDP). Every
    reply is picked up by the normal capture pipeline like any other
    packet — this thread only sends, it never needs to listen itself.
    """

    def __init__(self, iface, my_ip, allowed=None):
        super().__init__(daemon=True, name="lan-discovery")
        self.iface = iface
        self.my_ip = my_ip
        self.stop_flag = False
        # 5.3.4 (LG-08): asked before every sweep (the network may have
        # changed under a running capture)
        self.allowed = allowed or (lambda: True)
        self.subnet = local_subnet_for(iface, my_ip) if my_ip else None
        self.sweeps = 0
        self.last_sweep = 0.0
        self.errors = 0
        self.last_error = ""

    def _note_error(self, e):
        self.errors += 1
        self.last_error = f"{type(e).__name__}: {e}"
        if self.errors <= 5:
            LOG.info("LAN discovery send failed: %s", self.last_error)

    def run(self):
        # give the capture socket a moment to fully come up first
        for _ in range(10):
            if self.stop_flag:
                return
            time.sleep(0.2)
        while not self.stop_flag:
            try:
                self._sweep()
            except Exception as e:                   # noqa: BLE001
                self._note_error(e)
            waited = 0.0
            while waited < SCAN_INTERVAL:
                if self.stop_flag:
                    return
                time.sleep(0.2)
                waited += 0.2

    def _sweep(self):
        if not self.allowed():
            return
        self.sweeps += 1
        self.last_sweep = time.time()
        self._arp_sweep()
        self._mdns_browse()
        self._ssdp_search()

    def _arp_sweep(self):
        if not self.subnet or not self.my_ip:
            return
        if self.subnet.num_addresses > SCAN_MAX_HOSTS:
            return
        try:
            hosts = [str(h) for h in self.subnet.hosts() if str(h) != self.my_ip]
        except ValueError:
            return
        if not hosts:
            return
        try:
            pkts = [Ether(dst="ff:ff:ff:ff:ff:ff") / ARP(pdst=h) for h in hosts]
            outbound("lan_scan", "arp", f"{len(hosts)} addresses in "
                     f"{self.subnet}", "who-has (one per address)",
                     count=len(pkts))
            sendp(pkts, iface=self.iface, inter=0.003, verbose=False)
        except Exception as e:                       # noqa: BLE001
            self._note_error(e)

    def _mdns_browse(self):
        if not self.my_ip:
            return
        try:
            pkt = (Ether(dst="01:00:5e:00:00:fb") /
                   IP(dst="224.0.0.251", src=self.my_ip) /
                   UDP(sport=5353, dport=5353) /
                   DNS(rd=0, qd=DNSQR(qname="_services._dns-sd._udp.local.",
                                      qtype="PTR")))
            outbound("lan_scan", "mdns", "224.0.0.251 (local only)",
                     "which services are here?")
            sendp(pkt, iface=self.iface, verbose=False)
        except Exception as e:                       # noqa: BLE001
            self._note_error(e)

    def _ssdp_search(self):
        if not self.my_ip:
            return
        try:
            msg = ("M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\n"
                   'MAN: "ssdp:discover"\r\nMX: 2\r\nST: ssdp:all\r\n\r\n')
            pkt = (Ether(dst="01:00:5e:7f:ff:fa") /
                   IP(dst="239.255.255.250", src=self.my_ip) /
                   UDP(sport=random.randint(20000, 60000), dport=1900) /
                   Raw(load=msg.encode()))
            outbound("lan_scan", "ssdp", "239.255.255.250 (local only)",
                     "M-SEARCH ssdp:all")
            sendp(pkt, iface=self.iface, verbose=False)
        except Exception as e:                       # noqa: BLE001
            self._note_error(e)


def _iface_ip(iface):
    """Best-effort local IPv4 address for the chosen interface."""
    try:
        return get_if_addr(iface)
    except Exception as e:                           # noqa: BLE001
        LOG.debug("interface address (%s), retrying by name: %s", iface, e)
    try:
        return get_if_addr(getattr(iface, "name", iface))
    except Exception as e:                           # noqa: BLE001
        LOG.debug("interface address (%s): %s", iface, e)
    return ""




def _iface_ipv4(iface):
    ip = str(getattr(iface, "ip", "") or "")
    if not ip:
        ip = _iface_ip(iface) if get_if_addr else ""
    return "" if ip in ("0.0.0.0", "") else ip


def _iface_is_up(iface):
    """True/False when we can tell, None when we can't."""
    ps = OPTIONAL_MODULES.get("psutil")
    if ps is not None:
        try:
            stats = ps.net_if_stats()
            for nm in (iface_name(iface), iface_desc(iface)):
                if nm in stats:
                    return bool(stats[nm].isup)
        except Exception as e:                       # noqa: BLE001
            LOG.debug("interface state via psutil: %s", e)
    flags = getattr(iface, "flags", None)
    if flags is not None and not IS_WINDOWS:
        txt = str(flags)
        if "UP" in txt:
            return True
        return False
    return None


def score_interfaces(default_iface_name="", gateway_ip=""):
    """Score every adapter so the automatic choice is explainable.
    Returns a list of dicts sorted best-first:
    {iface, name, label, score, reasons, ip, vpn, virtual, up}."""
    out = []
    try:
        ifaces = list(conf.ifaces.values())
    except Exception as e:                           # noqa: BLE001
        LOG.warning("adapter list unreadable: %s", e)
        ifaces = []
    for iface in ifaces:
        name, desc = iface_name(iface), iface_desc(iface)
        ip = _iface_ipv4(iface)
        vpn, virt = is_vpn_iface(iface), is_virtual_iface(iface)
        up = _iface_is_up(iface)
        score, reasons = 0, []
        is_default = bool(default_iface_name) and \
            name == default_iface_name
        if is_default:
            score += 50
            reasons.append("it carries your default Internet route")
        if ip and not ip.startswith("169.254.") and not ip.startswith("127."):
            score += 20
            reasons.append(f"it has a usable address ({ip})")
        elif ip.startswith("169.254."):
            score -= 20
            reasons.append("it only has a self-assigned address (no DHCP)")
        else:
            score -= 40
            reasons.append("it has no IPv4 address")
        if ip and gateway_ip:
            with contextlib.suppress(ValueError):
                if ipaddress.ip_address(gateway_ip) in \
                        ipaddress.ip_network(f"{ip}/24", strict=False):
                    score += 10
                    reasons.append("your router is on the same network")
        low = (name + " " + desc).lower()
        if "loopback" in low or name in ("lo", "lo0") or ip.startswith("127."):
            score -= 100
            reasons.append("it is the loopback (internal) adapter")
        elif vpn:
            if is_default:
                reasons.append("it is a VPN/tunnel adapter (and your traffic "
                               "currently goes through it)")
            else:
                score -= 25
                reasons.append("it looks like a VPN/tunnel adapter")
        elif virt:
            score -= 30
            reasons.append("it looks like a virtual/host-only adapter")
        if "bluetooth" in low:
            score -= 30
            reasons.append("it is a Bluetooth network adapter")
        if up is False:
            score -= 50
            reasons.append("it is disconnected")
        elif up is True:
            score += 5
        label = desc if desc and desc != name else name
        if len(label) > 70:
            label = label[:67] + "..."
        out.append({"iface": iface, "name": name, "label": label,
                    "score": score, "reasons": reasons, "ip": ip,
                    "vpn": vpn, "virtual": virt, "up": up,
                    "default": is_default})
    out.sort(key=lambda r: -r["score"])
    return out


def explain_choice(rec):
    if not rec:
        return ""
    return "Picked because " + explain_reasons(rec)


def explain_reasons(rec):
    """The reasons part of explain_choice(), each reason translated."""
    if not rec:
        return ""
    good = [r for r in rec["reasons"] if not r.startswith(("it has no",
                                                           "it looks",
                                                           "it is the",
                                                           "it is dis",
                                                           "it only"))]
    return ", ".join(translate_text(r) for r in good) if good else \
        translate_text("it was the best of the available cards")


def system_dns_servers():
    """Best-effort list of the DNS servers this computer is configured to
    use (read from the OS; no network traffic)."""
    servers = []
    try:
        if IS_WINDOWS:
            r = subprocess.run(
                ["powershell", "-NoProfile", "-NonInteractive", "-Command",
                 "Get-DnsClientServerAddress -AddressFamily IPv4 | "
                 "Select-Object -ExpandProperty ServerAddresses"],
                capture_output=True, text=True, timeout=20,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            servers = [ln.strip() for ln in r.stdout.splitlines()
                       if re.match(r"^\d+\.\d+\.\d+\.\d+$", ln.strip())]
        elif IS_MAC:
            r = subprocess.run(["scutil", "--dns"], capture_output=True,
                               text=True, timeout=10)
            servers = re.findall(r"nameserver\[\d+\]\s*:\s*([0-9a-f.:]+)",
                                 r.stdout)
        else:
            for path in ("/run/systemd/resolve/resolv.conf",
                         "/etc/resolv.conf"):
                if os.path.exists(path):
                    with open(path, encoding="ascii", errors="replace") as f:
                        servers = re.findall(r"^\s*nameserver\s+(\S+)",
                                             f.read(), re.M)
                    if servers and servers != ["127.0.0.53"]:
                        break
    except (OSError, subprocess.SubprocessError):
        pass
    seen, out = set(), []
    for s in servers:
        if s not in seen:
            seen.add(s)
            out.append(s)
    return out[:6]


class NetworkWatcher(threading.Thread):
    """Notices the things that silently break a capture: the adapter
    vanishing, Wi-Fi reconnecting with a new address, the router changing,
    or the computer waking from sleep. Posts snapshots; never touches Tk."""

    def __init__(self, on_snapshot, interval=15.0):
        super().__init__(daemon=True, name="network-watcher")
        self.on_snapshot = on_snapshot
        self.interval = interval
        self.stop_flag = False
        self._wall = time.time()
        self._mono = time.monotonic()

    def run(self):
        n = 0
        while not self.stop_flag:
            slept = 0.0
            while slept < self.interval and not self.stop_flag:
                time.sleep(0.5)
                slept += 0.5
            if self.stop_flag:
                return
            wall, mono = time.time(), time.monotonic()
            resumed = (wall - self._wall) - (mono - self._mono) > 20 or \
                (wall - self._wall) > self.interval + 60
            since = self._wall
            self._wall, self._mono = wall, mono
            snap = {"resumed": resumed, "time": wall, "since": since}
            try:
                n += 1
                if n % 2 == 0 or resumed:
                    with contextlib.suppress(Exception):
                        conf.ifaces.reload()
                with contextlib.suppress(Exception):
                    conf.route.resync()
                iface, my_ip, gw = conf.route.route("0.0.0.0")
                snap.update({"default_iface": iface_name(iface),
                             "my_ip": my_ip if my_ip != "0.0.0.0" else "",
                             "gateway": gw if gw != "0.0.0.0" else "",
                             "ifaces": [iface_name(i)
                                        for i in conf.ifaces.values()]})
            except Exception as e:                   # noqa: BLE001
                snap["error"] = str(e)
            try:
                self.on_snapshot(snap)
            except Exception:                        # noqa: BLE001
                LOG.exception("network watcher callback")


def build_dns_query(name, qid):
    hdr = struct.pack(">HHHHHH", qid, 0x0100, 1, 0, 0, 0)
    q = b"".join(bytes([len(p)]) + p.encode("ascii")
                 for p in name.strip(".").split(".")) + b"\x00"
    return hdr + q + struct.pack(">HH", 1, 1)


class HealthProber(threading.Thread):
    """Conservative, transparent active health checks. Only runs when the
    app allows it (never in Quiet Mode, never while viewing saved/offline/
    demo data). Uses ordinary sockets: a TCP connect to the router (a
    refusal still proves it's reachable), a TCP connect to one well-known
    Internet address, and one DNS query to the system's DNS server."""

    def __init__(self, on_result, get_params):
        super().__init__(daemon=True, name="health-prober")
        self.on_result = on_result
        self.get_params = get_params      # () -> dict or None (not allowed)
        self.stop_flag = False
        self.run_now = threading.Event()

    def run(self):
        while not self.stop_flag:
            params = self.get_params()
            if params:
                try:
                    self.on_result(self.check(params))
                except Exception:                    # noqa: BLE001
                    LOG.exception("health probe")
            interval = (params or {}).get("interval", 30)
            self.run_now.wait(timeout=max(10, interval))
            self.run_now.clear()

    @staticmethod
    def _tcp_rtt(host, port, timeout=2.0, feature="health"):
        outbound(feature, "tcp", f"{host}:{port}", "connect, then close")
        t0 = time.perf_counter()
        s = _socket.socket(_socket.AF_INET6 if ":" in host
                           else _socket.AF_INET, _socket.SOCK_STREAM)
        s.settimeout(timeout)
        try:
            s.connect((host, port))
            ok = True
        except ConnectionRefusedError:
            ok = True                       # it answered — reachable
        except OSError:
            ok = False
        finally:
            with contextlib.suppress(OSError):
                s.close()
        return ok, (time.perf_counter() - t0) * 1000.0

    @staticmethod
    def _dns_rtt(server, name="www.example.com", timeout=2.5,
                 feature="health"):
        outbound(feature, "dns", f"{server}:53", f"look up {name}")
        qid = random.randint(1, 65535)
        s = _socket.socket(_socket.AF_INET6 if ":" in server
                           else _socket.AF_INET, _socket.SOCK_DGRAM)
        s.settimeout(timeout)
        t0 = time.perf_counter()
        try:
            s.sendto(build_dns_query(name, qid), (server, 53))
            while True:
                data, _ = s.recvfrom(2048)
                if len(data) >= 4 and struct.unpack(">H", data[:2])[0] == qid:
                    rcode = data[3] & 0x0F
                    return rcode in (0, 3), \
                        (time.perf_counter() - t0) * 1000.0, rcode
        except OSError:
            return False, None, None
        finally:
            with contextlib.suppress(OSError):
                s.close()

    def check(self, p):
        try:
            return self._check(p)
        except OutboundBlocked:
            return {"time": time.time(), "probes": [], "blocked": True}

    def _check(self, p):
        res = {"time": time.time(), "probes": []}
        gw = p.get("gateway")
        if gw:
            best = (False, None)
            for port in (53, 80, 443):
                ok, rtt = self._tcp_rtt(gw, port, timeout=1.5)
                res["probes"].append((gw, port))
                if ok:
                    best = (True, rtt)
                    break
            res["gateway_ok"], res["gateway_ms"] = best
        target = p.get("internet_target") or "1.1.1.1:443"
        host, _, port = target.rpartition(":")
        try:
            ok, rtt = self._tcp_rtt(host, int(port), timeout=3.0)
        except ValueError:
            ok, rtt = False, None
        res["probes"].append((host, int(port) if port.isdigit() else 0))
        res["internet_ok"], res["internet_ms"] = ok, (rtt if ok else None)
        dns = p.get("dns_server")
        if dns:
            ok, rtt, rcode = self._dns_rtt(dns)
            res["probes"].append((dns, 53))
            res["dns_ok"], res["dns_ms"], res["dns_server"] = ok, rtt, dns
        return res


# ============================================================================
#  6b.  Capture pipeline v2
#
#  capture thread ──raw bytes──▶ RawRing ──▶ AnalysisWorker ──▶ model
#                                              (decode off the GUI,
#                                               ingest under GuiGate)
#  Capture threads never parse: they append (bytes, time, linktype,
#  generation) and go straight back to the socket, so a busy network can't
#  starve them. One analysis worker decodes (fast_decode) and feeds the
#  NetworkModel. The model is shared with the Tk thread, so both take the
#  GuiGate — a re-entrant lock that every Tk callback holds automatically
#  (it wraps tkinter's CallWrapper) and that modal dialogs release while
#  they wait. The worker holds it for at most ~25 ms at a time, so the
#  window stays responsive. Drops can only happen at the ring, are counted
#  per cause and are shown in the status bar and Diagnostics.
# ============================================================================
_FAST_SWITCH_USERS = set()
_FAST_SWITCH_LOCK = threading.Lock()
_NORMAL_SWITCH = [None]


def fast_switch(who, on, interval=0.001):
    """While `who` (the analysis worker, a background job) has work,
    Python hands the interpreter to another thread every 1 ms instead of
    every 5 ms: each Tk callback waits for the interpreter, and against a
    busy thread one redraw of many callbacks waited 5 ms per callback. The
    default comes back when nobody needs it."""
    with _FAST_SWITCH_LOCK:
        if _NORMAL_SWITCH[0] is None:
            _NORMAL_SWITCH[0] = sys.getswitchinterval()
        if on:
            _FAST_SWITCH_USERS.add(who)
        else:
            _FAST_SWITCH_USERS.discard(who)
        want = interval if _FAST_SWITCH_USERS else _NORMAL_SWITCH[0]
        if abs(sys.getswitchinterval() - want) > 1e-6:
            sys.setswitchinterval(want)
        _windows_timer(bool(_FAST_SWITCH_USERS))


_WIN_TIMER = [False]


def _windows_timer(fine):
    """5.2.3 (B-06): Windows rounds short waits (the 1-3 ms hand-offs
    between the analysis thread and the window) up to its 15.6 ms timer
    tick. While somebody needs fast switching the timer runs at 1 ms
    (timeBeginPeriod), and is given back as soon as nobody does."""
    if not IS_WINDOWS or fine == _WIN_TIMER[0] or \
            (fine and not FEATURES.get("win_timer", True)):
        return
    try:
        winmm = ctypes.WinDLL("winmm")
        (winmm.timeBeginPeriod if fine else winmm.timeEndPeriod)(1)
        _WIN_TIMER[0] = fine
    except (OSError, AttributeError):
        pass


_GC_NORMAL = [None]


def busy_gc(on, gen2=50):
    """While packets pour in, the cycle collector's full pass (over every
    device, connection and website: 110-160 ms at 1,000 devices, holding
    the interpreter) runs a fifth as often; normal again when idle. Garbage
    that is not in a cycle is freed at once either way."""
    if not FEATURES.get("gc_freeze", True):
        return
    if _GC_NORMAL[0] is None:
        _GC_NORMAL[0] = gc.get_threshold()
    t0, t1, t2 = _GC_NORMAL[0]
    gc.set_threshold(t0, t1, max(t2, gen2) if on else t2)


class GuiGate:
    """Re-entrant lock with the ability to step out of a nested hold
    completely (for modal waits) and step back in afterwards.

    Fair handoff (5.1.2): a lock released and taken straight back by the
    analysis thread does not let a waiting Tk callback in (Python locks
    are not fair), and the window froze for up to 0.6 s while a large file
    was read. Tk callbacks now say they are waiting (`enter_tk`), and the
    analysis thread, between its slices, waits until the window has had
    its turn (`yield_to_tk`), for at most 50 ms."""

    def __init__(self):
        self._lock = threading.RLock()
        self._owner = None
        self._count = 0
        self.wait_ms = 0.0            # time the worker spent waiting
        self.tk_waiting = 0           # Tk callbacks waiting to enter
        self.tk_entries = 0           # Tk callbacks that got in
        self.yield_ms = 0.0           # time the worker gave way to Tk
        self._yielding = False
        self._cv = threading.Condition(threading.Lock())
        self._tk_ident = None
        self.tk_last = 0.0            # when a Tk callback last left

    def enter_tk(self):
        """The Tk thread's way in: announce, take the gate, wake a worker
        that is giving way. Only the Tk thread writes these counters."""
        self.tk_waiting += 1
        try:
            self.acquire()
        finally:
            self.tk_waiting -= 1
        self.tk_entries += 1
        self._tk_ident = threading.get_ident()
        if self._yielding:
            with self._cv:
                self._cv.notify_all()

    def leave_tk(self):
        self.tk_last = time.perf_counter()
        self.release()

    BURST_S = 0.03
    QUIET_S = 0.003

    def yield_to_tk(self, seen, limit=0.05):
        """Called by a worker right after releasing the gate. `seen` is
        tk_entries read while it still held the gate. If a Tk callback is
        waiting, wait (at most `limit` s) until one has entered; then let
        the rest of that burst of callbacks run too (at most BURST_S): one
        Tk update runs several callbacks, each of which used to wait for a
        whole worker slice, and the window froze for 0.2-0.3 s while a
        large file was read."""
        if not FEATURES.get("fair_gate", True) or self.tk_waiting <= 0:
            time.sleep(0)
            return 0.0
        t0 = time.perf_counter()
        deadline = t0 + limit
        with self._cv:
            self._yielding = True
            try:
                while self.tk_entries == seen and self.tk_waiting > 0:
                    left = deadline - time.perf_counter()
                    if left <= 0:
                        break
                    self._cv.wait(left)
                if self.tk_entries != seen:
                    end = time.perf_counter() + self.BURST_S
                    while True:
                        now = time.perf_counter()
                        if now >= end:
                            break
                        if not (self.tk_waiting > 0 or
                                (self._owner is not None and
                                 self._owner == self._tk_ident) or
                                now - self.tk_last < self.QUIET_S):
                            break
                        self._cv.wait(0.002)
            finally:
                self._yielding = False
        spent = time.perf_counter() - t0
        self.yield_ms += spent * 1000
        return spent

    def acquire(self):
        self._lock.acquire()
        self._owner = threading.get_ident()
        self._count += 1

    def release(self):
        self._count -= 1
        if self._count == 0:
            self._owner = None
        self._lock.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, *exc):
        self.release()
        return False

    def held(self):
        return self._owner == threading.get_ident()

    def release_all(self):
        if self._owner != threading.get_ident():
            return 0
        n = self._count
        for _ in range(n):
            self.release()
        return n

    def reacquire(self, n):
        for _ in range(n):
            self.acquire()


# Internal switches for the 5.1.2 work. Each risky new subsystem has one, so
# Safe Mode (or a developer) can fall back to exactly the 5.0.2 behaviour.
FEATURES = {
    "fair_gate": True,       # the analysis thread hands the gate to Tk (M1)
    "chunked": True,         # tables refill in short slices after a swap (M2)
    "gc_freeze": True,       # startup objects leave the cycle collector (M2)
    "sticky_sort": True,     # tables keep their sort and columns (M3)
    "tab_groups": True,      # tabs in four groups, new order (M4)
    "state_line": True,      # one truthful state line, not two banners (M4)
    "answer_cards": True,    # three answers on the Dashboard (M6)
    "dpi": True,             # Windows draws sharp text at 125 %+ (M8)
    "warm_start": True,      # the window is built behind the loading screen
    "win_timer": True,       # 1 ms Windows timer while busy (5.2.3, B-06)
    "ready_panel": True,     # "Ready?" lines in the Welcome Center (5.3.4)
    "story_mode": True,      # the Timeline tells what changed by day (M7)
}


def release_freed_memory():
    """5.2.3 (B-23): after a big model is replaced, glibc keeps the freed
    pages (50-120 MB that looked like a leak after reloading a session);
    malloc_trim hands them back. Linux with glibc only; a no-op
    elsewhere."""
    if not sys.platform.startswith("linux"):
        return False
    try:
        import ctypes
        import ctypes.util
        name = ctypes.util.find_library("c") or "libc.so.6"
        return bool(ctypes.CDLL(name).malloc_trim(0))
    except (OSError, AttributeError):
        return False


def freeze_startup_objects():
    """Once the window is built: the module, its tables and the window's
    widgets live as long as the program, so the cycle collector stops
    re-scanning them (gc.freeze). Its full passes, which hold the GIL and
    freeze the window, then cover only the network data: 135,000 fewer
    objects each time. A frozen object that dies later is still freed by
    reference counting; only a cycle among such objects would stay (the
    startup screen's few, once)."""
    if FEATURES.get("gc_freeze", True) and hasattr(gc, "freeze"):
        with contextlib.suppress(Exception):
            gc.collect()
            gc.freeze()


def callback_name(cw):
    """Readable name of the Python function behind a Tk callback wrapper
    (an after() callback is wrapped in a closure; name what it calls)."""
    f = getattr(cw, "func", cw)
    name = getattr(f, "__qualname__", None) or repr(f)
    if name.endswith("callit") and getattr(f, "__closure__", None):
        for cell in f.__closure__:
            try:
                v = cell.cell_contents
            except ValueError:
                continue
            q = getattr(v, "__qualname__", "")
            if callable(v) and q and not q.endswith("callit"):
                f, name = v, "after:" + q
                break
    if name.endswith("<lambda>"):
        code = getattr(f, "__code__", None)
        if code is not None:
            name += f"@{code.co_firstlineno}"
    return name


class PerfProbe:
    """How long every Tk callback waited for the GuiGate and how long it
    worked. Off by default: then the only cost is one list read per
    callback. Turned on by MW_PERF=1, by --bench-gui, or by perf_start().

    Callbacks run on the Tk thread only, so no lock is needed; nested
    callbacks (update() inside a callback) are recorded on their own and
    their time is also part of the outer one."""

    SLOW = 0.040                       # seconds: recorded with its name
    EDGES = (0.005, 0.010, 0.020, 0.040, 0.100, 0.250, 1.0)

    def __init__(self, keep_seconds=60.0):
        self.keep = keep_seconds
        self.reset()

    def reset(self):
        self.n = 0
        self.work = self.wait = 0.0
        self.max_work = (0.0, "")
        self.max_wait = (0.0, "")
        self.max_total = (0.0, "")
        self.hist = [0] * (len(self.EDGES) + 1)
        self.totals = deque(maxlen=50000)
        self.slow = deque(maxlen=2000)  # (wall, phase, name, work, wait)
        self.phase = ""

    def record(self, cw, t0, t1, t2):
        wait, work = t1 - t0, t2 - t1
        total = wait + work
        self.n += 1
        self.wait += wait
        self.work += work
        self.totals.append(total)
        for i, edge in enumerate(self.EDGES):
            if total < edge:
                self.hist[i] += 1
                break
        else:
            self.hist[-1] += 1
        if total < self.SLOW:
            return
        name = callback_name(cw)
        if work > self.max_work[0]:
            self.max_work = (work, name)
        if wait > self.max_wait[0]:
            self.max_wait = (wait, name)
        if total > self.max_total[0]:
            self.max_total = (total, name)
        now = time.time()
        self.slow.append((now, self.phase, name, work, wait))
        while self.slow and now - self.slow[0][0] > self.keep and \
                len(self.slow) > 200:
            self.slow.popleft()

    def percentile(self, p):
        if not self.totals:
            return 0.0
        xs = sorted(self.totals)
        return xs[min(len(xs) - 1, int(len(xs) * p))]

    def summary(self):
        """Plain numbers in milliseconds."""
        return {"callbacks": self.n,
                "p50_ms": round(self.percentile(0.50) * 1000, 1),
                "p95_ms": round(self.percentile(0.95) * 1000, 1),
                "p99_ms": round(self.percentile(0.99) * 1000, 1),
                "max_ms": round(self.max_total[0] * 1000, 1),
                "max_name": self.max_total[1],
                "max_work_ms": round(self.max_work[0] * 1000, 1),
                "max_work_name": self.max_work[1],
                "max_wait_ms": round(self.max_wait[0] * 1000, 1),
                "max_wait_name": self.max_wait[1],
                "over_100ms": sum(self.hist[5:]),
                "over_250ms": sum(self.hist[6:])}

    def slow_lines(self, limit=40):
        """The slowest recent callbacks, for the debug bundle."""
        rows = sorted(self.slow, key=lambda r: -(r[3] + r[4]))[:limit]
        return [f"{time.strftime('%H:%M:%S', time.localtime(w))} "
                f"{(wk + wt) * 1000:7.1f} ms (work {wk * 1000:.1f}, "
                f"waiting for the gate {wt * 1000:.1f})  {name}"
                f"{'  [' + ph + ']' if ph else ''}"
                for w, ph, name, wk, wt in rows]


PERF = [None]          # the active PerfProbe, or None (the usual case)


