def classify_capture_fault(exc):
    """→ (kind, title, fix, retry, original). Maps OS and libpcap errors
    to a fault the user can act on; the original text is always kept."""
    if exc is None:
        kind = "unknown"
        orig = ""
    else:
        orig = f"{type(exc).__name__}: {exc}" if not isinstance(exc, str) \
            else exc
        low = orig.lower()
        errno_ = getattr(exc, "errno", None)
        if isinstance(exc, PermissionError) or errno_ in (1, 13) or any(
                w in low for w in ("permission", "operation not permitted",
                                   "access is denied", "access denied",
                                   "requires root", "administrator")):
            kind = "permission"
        elif any(w in low for w in ("npcap", "winpcap", "wpcap",
                                    "libpcap not", "no libpcap",
                                    "packet.dll")):
            kind = "driver"
        elif "promisc" in low or "error opening adapter" in low:
            # 5.2.3: checked before "filter" ("failed to set hardware
            # filter to promiscuous mode" is not a bad capture filter) and
            # before "adapter" (Npcap's "Error opening adapter … (20)/(50)"
            # means this card can't be opened, not that it went away)
            kind = "wrong_adapter"
        elif any(w in low for w in ("syntax error", "filter", "bpf",
                                    "illegal token", "parse error in")):
            kind = "bad_filter"
        elif "resumed from sleep" in low:
            kind = "sleep"
        elif errno_ in (19, 6, 100, 50) or any(
                w in low for w in ("disappeared", "no such device",
                                   "network is down", "device not",
                                   "adapter went away", "interface went down",
                                   "enxio", "enodev", "restart failed")):
            kind = "adapter_gone"
        elif any(w in low for w in ("no such interface", "not found",
                                    "invalid interface", "unknown interface",
                                    "not supported on this interface")):
            kind = "wrong_adapter"
        elif errno_ == 105 or any(w in low for w in ("no buffer space",
                                                     "overflow",
                                                     "enobufs")):
            kind = "overflow"
        elif isinstance(exc, (struct.error, ValueError, IndexError)):
            kind = "parse"
        else:
            kind = "unknown"
    title, fix, retry = CAPTURE_FAULTS[kind]
    return kind, title, fix, retry, orig


PACKET_STATISTICS = 6          # linux/if_packet.h
SOL_PACKET = 263


class KernelCounters:
    """Packets the operating system dropped before MiniWireshark could
    read them. Linux reports them for raw sockets (and resets the
    counter on every read, so they are summed here); other capture
    methods report nothing, which is shown as "not reported", never as
    zero."""

    def __init__(self):
        self.received = 0
        self.dropped = 0
        self.supported = None      # None = not asked yet

    def poll(self, source):
        sock = getattr(source, "sock", None)
        fd_obj = getattr(sock, "ins", None) or sock
        if fd_obj is None or not hasattr(fd_obj, "getsockopt") or \
                not sys.platform.startswith("linux"):
            if self.supported is None:
                self.supported = False
            return False
        try:
            raw = fd_obj.getsockopt(SOL_PACKET, PACKET_STATISTICS, 8)
            got, drops = struct.unpack("II", raw[:8])
        except (OSError, struct.error, AttributeError, TypeError,
                ValueError):
            if self.supported is None:
                self.supported = False
            return False
        self.supported = True
        self.received += got
        self.dropped += drops
        return True

    def text(self):
        if not self.supported:
            return "not reported by this capture method"
        return f"{self.dropped:,}"


class PipelineWatchdog:
    """Checks every few seconds that each stage moved while it had work:
    capture → raw ring → analysis → window. A stage that holds work for
    10 s without progress is reported once (and again if it recovers and
    sticks again). The worker thread checks the watchdog's own heartbeat,
    so a frozen window is noticed too."""

    LIMIT = 10.0

    def __init__(self):
        self.last = {}            # stage -> (value, since)
        self.stuck = {}           # stage -> seconds stuck (reported)
        self.beat = time.monotonic()
        self.reports = deque(maxlen=50)

    def check(self, now, stages):
        """stages: {name: (progress_counter, has_work)} → list of newly
        stuck stage names."""
        self.beat = now
        new = []
        for name, (value, has_work) in stages.items():
            prev = self.last.get(name)
            if prev is None or value != prev[0] or not has_work:
                self.last[name] = (value, now)
                if name in self.stuck and (prev is None or
                                           value != prev[0] or
                                           not has_work):
                    self.stuck.pop(name, None)
                    self.reports.append((now, name, "moving again"))
                continue
            held = now - prev[1]
            if held >= self.LIMIT and name not in self.stuck:
                self.stuck[name] = held
                self.reports.append((now, name, f"stuck {held:.0f} s"))
                new.append(name)
            elif name in self.stuck:
                self.stuck[name] = held
        return new

    def window_frozen(self, now=None):
        """Seconds since the window last ran the watchdog (0 if fine)."""
        lag = (now or time.monotonic()) - self.beat
        return lag if lag > self.LIMIT else 0.0

    def text(self):
        if not self.stuck:
            return "all stages moving"
        return "; ".join(f"{k} stuck {v:.0f} s" for k, v in
                         sorted(self.stuck.items()))


STAGE_NAMES = {"capture": "capture → raw ring",
               "analysis": "analysis (raw ring → model)",
               "window": "window (rows → Packets tab)"}


def pipeline_coverage(ring, worker, kernel, rows_not_shown=0, gaps=()):
    """Every packet in exactly one bucket, with what is unknown said
    plainly. → dict."""
    st = ring.stats()
    analysed = worker.decoded if worker else 0
    errors = worker.errors if worker else 0
    stale = worker.stale if worker else 0
    in_flight = st["queued"]
    out = {"received": st["accepted"] + st["dropped"],
           "accepted": st["accepted"],
           "analysed": analysed, "decode_errors": errors,
           "dropped_app": st["dropped"], "stale": stale,
           "in_flight": in_flight, "rows_not_shown": rows_not_shown,
           "kernel_dropped": kernel.dropped if kernel and kernel.supported
           else None,
           "gaps": len(gaps),
           "gap_seconds": sum(max(0.0, e - s) for s, e, _r in gaps)}
    return out


def coverage_summary(cov):
    """One honest sentence for the coverage card."""
    lost = cov["dropped_app"] + (cov["kernel_dropped"] or 0)
    parts = []
    if cov["dropped_app"]:
        parts.append(f"{cov['dropped_app']:,} dropped because analysis "
                     f"fell behind")
    if cov["kernel_dropped"]:
        parts.append(f"{cov['kernel_dropped']:,} dropped by the operating "
                     f"system")
    if cov["gaps"]:
        parts.append(f"{cov['gaps']} capture gap(s), "
                     f"{human_duration(cov['gap_seconds'])} in total")
    if not parts:
        txt = f"Every packet received was analysed ({cov['analysed']:,})"
        if cov["kernel_dropped"] is None and cov["received"]:
            txt += "; the operating system's own drops are not reported " \
                   "by this capture method"
        return txt, (LV_OBSERVED if cov["kernel_dropped"] is not None
                     else LV_INFERRED)
    return ("Not everything: " + ", ".join(parts),
            LV_UNKNOWN if lost or cov["gaps"] else LV_INFERRED)


class AnalysisWorker(threading.Thread):
    """The only thread that feeds packets into the model."""

    BATCH = 1500
    SLICE = 0.025                 # max seconds per hold of the GuiGate

    def __init__(self, app, gate=None):
        super().__init__(daemon=True, name="analysis")
        self.app = app
        self.gate = gate or GUI_GATE
        self.reasm = TlsReassembler()
        self.stop_flag = False
        self.decoded = 0
        self.errors = 0
        self.stale = 0             # frames from a previous data source
        self.last_error = ""
        self.beat = time.monotonic()
        self.busy = False
        self.deep = 0              # frames the fast path handed to scapy
        self.window_frozen = 0.0   # seconds the Tk thread missed its checks

    def reset(self):
        """New session: fresh reassembly state and counters."""
        self.reasm = TlsReassembler()
        self.decoded = self.errors = self.stale = self.deep = 0
        self.last_error = ""

    # While packets are being analysed, Python hands the interpreter to
    # another thread every 1 ms instead of every 5 ms, so the window gets
    # its turn sooner (S1 import freeze 385 -> about 220 ms, same import
    # time). Back to the default after 1 s without work, so an idle window
    # does not pay for the extra switching.
    FAST_SWITCH = 0.001

    def _switch_interval(self, busy, now):
        if not FEATURES.get("fair_gate", True):
            return
        if busy:
            self._last_work = now
            if not self._fast:
                fast_switch("analysis", True, self.FAST_SWITCH)
                busy_gc(True)
                self._fast = True
        elif self._fast and now - self._last_work > 1.0:
            fast_switch("analysis", False)
            busy_gc(False)
            self._fast = False

    def run(self):
        ring = self.app.ring
        self._fast, self._last_work = False, 0.0
        while not self.stop_flag:
            self.beat = now = time.monotonic()
            wd = getattr(self.app, "watchdog", None)
            if wd is not None:
                frozen = wd.window_frozen(now)
                if frozen and not self.window_frozen:
                    LOG.warning("the window has not run its checks for "
                                "%.0f s", frozen)
                self.window_frozen = frozen
            batch = ring.drain(self.BATCH, timeout=0.02)
            self._switch_interval(bool(batch), now)
            if not batch:
                self.busy = False
                continue
            self.busy = True
            try:
                self._process(batch)
            except Exception as e:                   # noqa: BLE001
                self.errors += 1
                self.last_error = f"{type(e).__name__}: {e}"
                if self.errors <= 20:
                    LOG.exception("analysis batch")
        self.busy = False
        if self._fast:
            fast_switch("analysis", False)
            busy_gc(False)

    def _process(self, batch):
        app = self.app
        gen = app.gen
        model = app.model
        deep = getattr(app, "deep", None)
        if deep is not None:
            try:
                app.sync_deep()        # mode switches happen only here
            except Exception:                        # noqa: BLE001
                LOG.exception("deep analysis setup")
            if not deep.active():
                deep = None
        gw, my_ips = model.gateway_ip, model.my_ips
        decoded = []
        for raw, ts, lt, g in batch:
            if g != gen:
                self.stale += 1
                continue
            try:
                d = fast_decode(raw, ts, lt, self.reasm, gw, my_ips)
            except Exception as e:                   # noqa: BLE001
                self.errors += 1
                if self.errors <= 20:
                    self.last_error = f"{type(e).__name__}: {e}"
                    LOG.debug("decode error: %s", self.last_error)
                continue
            if d.get("pkt") is not None:
                self.deep += 1
            decoded.append(d)
        if not decoded:
            return
        i = 0
        while i < len(decoded):
            t_wait = time.perf_counter()
            with self.gate:
                self.gate.wait_ms += (time.perf_counter() - t_wait) * 1000
                if app.gen != gen or app.model is not model:
                    self.stale += len(decoded) - i
                    return
                t0 = time.perf_counter()
                start = i
                while i < len(decoded):
                    d = decoded[i]
                    i += 1
                    app.count += 1
                    d["no"] = app.count
                    learn_names_from(model.cache, d)
                    try:
                        model.ingest(d)
                    except Exception:                # noqa: BLE001
                        app._analysis_errors += 1
                        if app._analysis_errors <= 5:
                            LOG.exception("analysis error")
                    if deep is not None:
                        deep.offer(d, d["no"])
                    if time.perf_counter() - t0 > self.SLICE:
                        break
                rows = decoded[start:i]
                app.all_rows.extend(rows)
                app.pending_rows.extend(rows)
                self.decoded += len(rows)
                app.on_rows_analysed(rows)
                seen = self.gate.tk_entries
            # let a waiting Tk callback in before the next slice (a bare
            # sleep(0) did not: the lock was taken straight back)
            self.gate.yield_to_tk(seen)


def _layer2num(cls):
    try:
        return int(conf.l2types.layer2num.get(cls, 1))
    except (AttributeError, TypeError, ValueError):
        return 1


class RawCapture(threading.Thread):
    """Live capture straight from a layer-2 socket: no scapy packet is
    built in the capture thread, just bytes + timestamp."""

    def __init__(self, iface, bpf, promisc, sink):
        super().__init__(daemon=True, name="capture")
        self.iface = iface
        self.bpf = bpf
        self.promisc = promisc
        self.sink = sink
        self.stop_flag = False
        self.running = False
        self.exception = None
        self.received = 0
        self.started = threading.Event()
        # rc.11: set once the first wait for a packet has ended (a packet,
        # 20 ms of quiet, or an error), so the start need not sleep 0.2 s
        self.first_cycle = threading.Event()
        self.sock = None
        self.kind = "raw socket"
        self.promisc_refused = False

    def _open(self):
        kwargs = {"iface": self.iface}
        if self.bpf:
            kwargs["filter"] = self.bpf
        last = None
        tries = [{"promisc": self.promisc}, {}]
        while tries:
            extra = tries.pop(0)
            try:
                return conf.L2listen(**dict(kwargs, **extra))
            except TypeError as e:
                last = e
            except Exception as e:                   # noqa: BLE001
                if not self.promisc or self.promisc_refused or \
                        not refused_promisc(e):
                    raise
                # 5.2.3: the card refuses promiscuous mode; watch this
                # computer's own traffic instead of not watching at all
                LOG.info("%s refused promiscuous mode (%s); capturing "
                         "without it", self.iface, e)
                self.promisc_refused = True
                last = e
                tries = [{"promisc": False}]
        raise last or RuntimeError("could not open capture socket")

    def run(self):
        try:
            self.sock = self._open()
        except Exception as e:                       # noqa: BLE001
            self.exception = e
            self.started.set()
            self.first_cycle.set()
            return
        self.running = True
        self.started.set()
        sock = self.sock
        lt_cache = {}
        select = getattr(type(sock), "select", None)
        first = self.first_cycle
        try:
            while not self.stop_flag:
                if select is not None:
                    ready = select([sock], 0.25 if first.is_set() else 0.02)
                    if not ready:
                        first.set()
                        continue
                r = sock.recv_raw(65535)
                first.set()
                if not r:
                    continue
                cls, raw, ts = r[0], r[1], r[2] if len(r) > 2 else None
                if raw is None:
                    continue
                lt = lt_cache.get(cls)
                if lt is None:
                    lt = lt_cache[cls] = _layer2num(cls)
                self.received += 1
                self.sink(raw, float(ts) if ts else time.time(), lt)
        except Exception as e:                       # noqa: BLE001
            if not self.stop_flag:
                self.exception = e
        finally:
            self.running = False
            first.set()
            with contextlib.suppress(Exception):
                sock.close()

    def stop(self):
        self.stop_flag = True
        if self.is_alive():
            self.join(timeout=1.5)


class SnifferCapture:
    """Fallback: scapy's AsyncSniffer (slower, builds packet objects) for
    backends without raw receive. Same interface as RawCapture."""

    kind = "scapy sniffer"

    def __init__(self, sniffer):
        self.sniffer = sniffer
        self.received = 0

    @property
    def running(self):
        return getattr(self.sniffer, "running", True)

    @property
    def exception(self):
        return getattr(self.sniffer, "exception", None)

    @property
    def promisc_refused(self):
        return bool(getattr(self.sniffer, "mw_promisc_refused", False))

    def stop(self):
        with contextlib.suppress(Exception):
            self.sniffer.stop()

    def is_alive(self):
        return self.running


def start_capture_source(iface, bpf, promisc, sink):
    """Raw socket first, AsyncSniffer as fallback. Returns (source, err)."""
    rc = RawCapture(iface, bpf, promisc, sink)
    rc.start()
    rc.started.wait(3.0)
    # was a fixed 0.2 s sleep on the window's thread (the freeze when
    # watching starts, 0.7 s after the window opens): now until the first
    # wait for a packet ends, 0.2 s at most (sockets without select)
    rc.first_cycle.wait(0.2)        # an error is stored before it is set
    if rc.exception is None and rc.is_alive():
        return rc, None
    err = rc.exception
    rc.stop_flag = True
    LOG.info("raw capture unavailable (%s); trying the scapy sniffer", err)
    counter = {"n": 0}

    def prn(pkt):
        counter["n"] += 1
        sink(bytes(pkt), float(getattr(pkt, "time", time.time())),
             _layer2num(type(pkt)))
    sn, err2 = build_sniffer(iface, prn, bpf, promisc)
    if sn is None:
        return None, err2 or err
    return SnifferCapture(sn), None


def probe_capture_sources(candidates, bpf, promisc, sink,
                          cancelled=lambda: False):
    """Try (label, iface) pairs in order → (source, last_error, label).
    Each card that refuses can take ~1.5 s (Windows), so callers run this
    off the Tk thread (5.2.3)."""
    err = None
    for lbl, iface in candidates:
        if cancelled():
            break
        src, err = start_capture_source(iface, bpf, promisc, sink)
        if src is not None:
            if cancelled():
                with contextlib.suppress(Exception):
                    src.stop()
                return None, None, None
            return src, None, lbl
        LOG.info("capture failed on %s: %s", lbl, err)
    return None, err, None


# ---- capture files (stdlib reader for pcap and pcapng) ----------------------
def iter_raw_capture(path):
    """Yield (raw_bytes, timestamp, linktype) from a .pcap or .pcapng
    file without scapy. Raises ValueError for unknown formats."""
    with open(path, "rb") as f:
        head = f.read(4)
        if len(head) < 4:
            raise ValueError("file is empty")
        if head == b"\x0a\x0d\x0d\x0a":
            yield from _iter_pcapng(f, head)
            return
        magic_le = struct.unpack("<I", head)[0]
        magics = {0xa1b2c3d4: ("<", 1e-6), 0xd4c3b2a1: (">", 1e-6),
                  0xa1b23c4d: ("<", 1e-9), 0x4d3cb2a1: (">", 1e-9)}
        if magic_le not in magics:
            raise ValueError("not a pcap/pcapng file")
        end, scale = magics[magic_le]
        rest = f.read(20)
        if len(rest) < 20:
            raise ValueError("truncated pcap header")
        _vmaj, _vmin, _tz, _sig, _snap, lt = struct.unpack(end + "HHiIII",
                                                           rest)
        lt &= 0x0FFFFFFF
        rec = struct.Struct(end + "IIII")
        while True:
            h = f.read(16)
            if len(h) < 16:
                return
            sec, frac, incl, _orig = rec.unpack(h)
            if incl > 262144 * 4:
                raise ValueError("corrupt record length")
            data = f.read(incl)
            if len(data) < incl:
                return
            yield data, sec + frac * scale, lt


def _iter_pcapng(f, first):
    end = "<"
    ifaces = []                   # (linktype, ts_scale)
    last_ts = 0.0
    block_type = first
    while True:
        if block_type is None:
            block_type = f.read(4)
            if len(block_type) < 4:
                return
        lenb = f.read(4)
        if len(lenb) < 4:
            return
        if block_type == b"\x0a\x0d\x0d\x0a":
            bom = f.read(4)
            # 5.3.4 (QA-02): an unknown byte-order magic or a section
            # length outside the limits every other block has is damage,
            # not "0 packets"
            if bom == b"\x4d\x3c\x2b\x1a":
                end = "<"
            elif bom == b"\x1a\x2b\x3c\x4d":
                end = ">"
            else:
                raise ValueError("corrupt pcapng section header")
            blen = struct.unpack(end + "I", lenb)[0]
            if blen < 28 or blen > 64 * 1024 * 1024 or blen % 4:
                raise ValueError("corrupt pcapng section header")
            body = f.read(blen - 12)
            ifaces = []
            block_type = None
            continue
        btype = struct.unpack(end + "I", block_type)[0]
        blen = struct.unpack(end + "I", lenb)[0]
        if blen < 12 or blen > 64 * 1024 * 1024:
            raise ValueError("corrupt pcapng block")
        body = f.read(blen - 8)
        if len(body) < blen - 8:
            return
        body = body[:-4]
        block_type = None
        if btype == 1 and len(body) >= 8:              # interface description
            lt = struct.unpack_from(end + "H", body, 0)[0]
            scale = 1e-6
            p = 8
            while p + 4 <= len(body):
                code, ln = struct.unpack_from(end + "HH", body, p)
                if code == 0:
                    break
                if p + 4 + ln > len(body):        # QA-01: cut-off option
                    break
                if code == 9 and ln >= 1:
                    v = body[p + 4]
                    scale = (2 ** -(v & 0x7F)) if v & 0x80 else 10 ** -v
                p += 4 + ln + ((4 - ln % 4) % 4)
            ifaces.append((lt, scale))
        elif btype == 6 and len(body) >= 20:           # enhanced packet
            iid, hi, lo, cap, _orig = struct.unpack_from(end + "IIIII", body,
                                                         0)
            lt, scale = ifaces[iid] if iid < len(ifaces) else (1, 1e-6)
            ts = _sane_ts(((hi << 32) | lo) * scale, last_ts)
            last_ts = ts
            yield bytes(body[20:20 + cap]), ts, lt
        elif btype == 3 and len(body) >= 4:            # simple packet
            lt, _s = ifaces[0] if ifaces else (1, 1e-6)
            orig = struct.unpack_from(end + "I", body, 0)[0]
            yield bytes(body[4:4 + orig]), last_ts, lt
        elif btype == 2 and len(body) >= 20:           # obsolete packet
            iid = struct.unpack_from(end + "H", body, 0)[0]
            hi, lo, cap = struct.unpack_from(end + "III", body, 4)
            lt, scale = ifaces[iid] if iid < len(ifaces) else (1, 1e-6)
            ts = _sane_ts(((hi << 32) | lo) * scale, last_ts)
            last_ts = ts
            yield bytes(body[20:20 + cap]), ts, lt


def _sane_ts(ts, last):
    """5.3.4 (QA-03): a corrupt packet time (beyond year 2100 or before
    1970) takes the previous packet's time instead of breaking every clock
    shown for the session."""
    return ts if 0 <= ts < 4102444800 else last


class RawPcapImporter(threading.Thread):
    """Feeds a capture file through the SAME pipeline as live packets
    (lossless: it waits when the ring is full) and can be cancelled."""

    def __init__(self, path, sink, on_progress, on_done):
        super().__init__(daemon=True, name="pcap-import")
        self.path = path
        self.sink = sink              # sink(raw, ts, lt, cancelled) -> bool
        self.on_progress = on_progress
        self.on_done = on_done
        self.cancelled = False
        self.count = 0

    def run(self):
        err = None
        try:
            for raw, ts, lt in iter_raw_capture(self.path):
                if self.cancelled:
                    break
                if not self.sink(raw, ts, lt, lambda: self.cancelled):
                    break
                self.count += 1
                if self.count % 2000 == 0:
                    self.on_progress(self.count)
        except (OSError, ValueError, struct.error) as e:
            err = (f"{e}. The file may be damaged, or it isn't a "
                   "pcap/pcapng capture.")
            LOG.warning("capture import failed: %s", err)
        except Exception as e:                        # noqa: BLE001
            # QA-01: any other reader failure still ends the import with
            # a message instead of a "Reading…" banner forever
            err = (f"{type(e).__name__}. The file may be damaged, or it "
                   "isn't a pcap/pcapng capture.")
            LOG.exception("capture import failed")
        self.on_done(self.count, err, self.cancelled)


# ============================================================================
#  7.  Device identity model
#
#  "Never invent a device": something only becomes a Device because of
#  accumulated LOCAL evidence (a unicast MAC seen on the LAN, an ARP or
#  IPv6 Neighbor Discovery answer, a DHCP lease, an mDNS/SSDP announcement).
#  Websites (domains) and Remote Hosts (public IPs) are entirely separate
#  record types and can never become a Device. Public IPv4 addresses are
#  never attached to a device; global IPv6 addresses only when they sit in
#  a prefix your own network announced.
# ============================================================================
EVIDENCE_WEIGHTS = {
    "mac_local":     40,   # a real (unicast) MAC seen directly on the LAN
    "arp_reply":     25,   # answered "is-at" for its own IP
    "ipv6_nd":       25,   # answered IPv6 Neighbor Discovery for itself
    "dhcp_lease":    25,   # got/renewed a DHCP lease
    "dhcp_client":   20,   # asked the DHCP server for an address itself
    "mdns":          15,   # advertised itself over mDNS/Bonjour
    "ssdp":          15,   # advertised itself over SSDP/UPnP
    "nbns":          10,   # answered a Windows (NetBIOS) name query
    "local_traffic": 10,   # ordinary local traffic
    "oui_match":      5,   # MAC vendor prefix recognized
    "rdns":           2,   # reverse-DNS name only
}
CONFIDENCE_UNCONFIRMED, CONFIDENCE_LOW = "Unconfirmed", "Low"
CONFIDENCE_MEDIUM, CONFIDENCE_HIGH = "Medium", "High"
CONFIDENCE_ORDER = {CONFIDENCE_UNCONFIRMED: 0, CONFIDENCE_LOW: 1,
                    CONFIDENCE_MEDIUM: 2, CONFIDENCE_HIGH: 3}
CONFIDENCE_ICON = {"High": "●●●", "Medium": "●●○",
                   "Low": "●○○", "Unconfirmed": "○○○"}

STATE_ACTIVE, STATE_IDLE, STATE_INACTIVE, STATE_EXPIRED = \
    "ACTIVE", "IDLE", "INACTIVE", "EXPIRED"
STATE_LABEL = {"ACTIVE": "● Active", "IDLE": "◐ Idle",
               "INACTIVE": "○ Offline", "EXPIRED": "✕ Expired"}

EVIDENCE_LABELS = {
    "mac_local": "MAC seen locally", "arp_reply": "ARP reply",
    "ipv6_nd": "IPv6 Neighbor Discovery", "dhcp_lease": "DHCP lease",
    "dhcp_client": "DHCP request", "mdns": "mDNS advertisement",
    "ssdp": "SSDP advertisement", "nbns": "Windows name (NetBIOS)",
    "local_traffic": "Local traffic", "oui_match": "Vendor (OUI) match",
    "rdns": "Reverse DNS",
}
HOSTNAME_PRIORITY = {"user": 5, "dhcp": 4, "mdns": 4, "nbns": 3,
                     "ssdp": 3, "connector": 2, "rdns": 1, "": 0}

# Docker/typical container-bridge / common virtualization NAT ranges — seen
# on the machine MiniWireshark itself runs on, not a separate LAN device.
VIRTUAL_BRIDGE_NETS = [ipaddress.ip_network(n) for n in (
    "172.17.0.0/16", "172.18.0.0/16", "172.19.0.0/16",
    "10.0.75.0/24", "192.168.99.0/24",
)]
LOOPBACK_V4 = ipaddress.ip_network("127.0.0.0/8")


def is_randomized_mac(mac):
    """The U/L (locally-administered) bit is the 2nd-least-significant bit
    of a MAC's first octet. Modern phones/laptops set it for a private,
    per-network, rotating Wi-Fi address — a privacy *feature*, not missing
    data, so it's surfaced as its own evidence-neutral fact."""
    try:
        first = int(mac.split(":")[0], 16)
        return bool(first & 0x02)
    except (ValueError, AttributeError, IndexError):
        return False


def confidence_tier(score):
    if score >= 60:
        return CONFIDENCE_HIGH
    if score >= 30:
        return CONFIDENCE_MEDIUM
    if score >= 10:
        return CONFIDENCE_LOW
    return CONFIDENCE_UNCONFIRMED


@dataclass
class Evidence:
    source: str
    detail: str
    weight: int
    when: float = field(default_factory=time.time)


def _push_bounded(lst, item, limit):
    lst.append(item)
    if len(lst) > limit:
        del lst[:-limit]


@dataclass
class DeviceRecord:
    """A LOCAL device. Keyed by MAC when one is known (the actual L2
    identity), else by a synthetic 'ip:<addr>' key. Only ever created
    from local evidence — never from a remote/public IP or a DNS answer."""
    key: str
    ip: str = ""
    ipv6: set = field(default_factory=set)
    ipv4s: set = field(default_factory=set)
    mac: str = ""
    vendor: str = ""
    hostname: str = ""
    hostname_source: str = ""
    dhcp_hostname: str = ""
    mdns_name: str = ""
    ssdp_name: str = ""
    ssdp_server: str = ""
    model_hint: str = ""
    dhcp_vendor_class: str = ""
    dhcp_params: str = ""
    dhcp_client_id: str = ""
    user_class: str = ""          # the type YOU set (overrides detection)
    type: str = "unknown"
    type_hint: str = ""
    device_class: str = "Unknown"
    class_confidence: str = ""
    class_reasons: list = field(default_factory=list)
    services: set = field(default_factory=set)
    evidence: list = field(default_factory=list)
    score: int = 0
    confidence: str = CONFIDENCE_UNCONFIRMED
    state: str = STATE_ACTIVE
    first_seen: float = field(default_factory=time.time)
    last_seen: float = field(default_factory=time.time)
    last_confirmed: float = field(default_factory=time.time)
    last_active: float = 0.0
    last_arp: float = 0.0
    last_traffic: float = 0.0
    packets: int = 0
    packets_out: int = 0
    packets_in: int = 0
    bytes_up: int = 0          # bytes this device SENT
    bytes_down: int = 0        # bytes this device RECEIVED
    lan_bytes: int = 0
    internet_bytes: int = 0
    protocols: object = field(default_factory=Counter)
    websites: set = field(default_factory=set)
    remote_ips: set = field(default_factory=set)
    alert_ids: list = field(default_factory=list)
    randomized_mac: bool = False
    identity_conflict: str = ""
    pinned_no_merge: bool = False
    never_merge: set = field(default_factory=set)
    lease_ip: str = ""
    lease_start: float = 0.0
    lease_expiry: float = 0.0
    link_local_only: bool = False
    is_virtual: bool = False
    expected: bool = False   # "mark as expected" silences future alerts
    mine: bool = False
    alias: str = ""
    notes: str = ""
    place: str = ""          # 5.1.2: "Kitchen" — yours, like the name
    owner: str = ""          # 5.1.2: "Sam"
    os_ttl: int = 0
    ip_history: list = field(default_factory=list)       # [ip, first, last]
    mac_history: list = field(default_factory=list)      # [mac, first, last]
    dhcp_history: list = field(default_factory=list)     # [ip, when, secs, host]
    hostname_history: list = field(default_factory=list)  # [name, src, when]
    presence: list = field(default_factory=list)         # [start, end|None]
    _rate_hist: list = field(default_factory=list)  # (minute_bucket, count)
    reactivations: list = field(default_factory=list)  # times it came back
    reactivated_now: bool = False
    merge_note: str = ""     # why identities were merged, if they were
    merged_from: list = field(default_factory=list)
    merge_history: list = field(default_factory=list)
    suggested: set = field(default_factory=set)   # keys already suggested
    live: bool = True        # False for records loaded from a saved session
    demo: bool = False
    iface_stats: dict = field(default_factory=dict)  # per-MAC counters
    network_id: str = ""
    _last_conf_tier: str = CONFIDENCE_UNCONFIRMED

    def add_evidence(self, source, detail, when=None):
        w = EVIDENCE_WEIGHTS.get(source, 0)
        ev = Evidence(source, detail, w, when or time.time())
        # keep only the newest example of each source plus a short tail,
        # so a chatty device can't push out its strong evidence
        if self.evidence and self.evidence[-1].source == source:
            self.evidence[-1] = ev
        else:
            self.evidence.append(ev)
        if len(self.evidence) > 60:
            seen, keep = set(), []
            for e in reversed(self.evidence):
                if e.source not in seen or len(keep) < 20:
                    keep.append(e)
                    seen.add(e.source)
            self.evidence = list(reversed(keep))
        self.recompute_score()

    def recompute_score(self):
        seen, total = set(), 0
        for ev in reversed(self.evidence):
            if ev.source in seen:
                continue
            seen.add(ev.source)
            total += ev.weight
        self.score = min(total, 100)
        self.confidence = confidence_tier(self.score)

    def evidence_summary(self):
        sources = []
        seen = set()
        for ev in self.evidence:
            if ev.source not in seen:
                seen.add(ev.source)
                sources.append(EVIDENCE_LABELS.get(ev.source, ev.source))
        return sources

    def confidence_reasons(self):
        latest = {}
        for ev in self.evidence:
            latest[ev.source] = ev
        rows = sorted(latest.values(), key=lambda e: -e.weight)
        return [f"+{e.weight:>2}  {EVIDENCE_LABELS.get(e.source, e.source)}"
                f" — {e.detail}" for e in rows]

    def best_name(self):
        """Most human-friendly announced name: user alias first, then names
        that read like words, and machine-generated ones (BRW0080775…,
        ESP_6A1B2C) last."""
        if self.alias:
            return self.alias
        names = [n for n in (self.hostname, self.mdns_name,
                             self.dhcp_hostname, self.ssdp_name) if n]
        for n in names:
            if not looks_generated(n):
                return n
        return names[0] if names else ""

    def display_name(self):
        n = self.best_name()
        if n:
            return n
        if self.vendor:
            return f"{self.vendor} device"
        return self.ip or self.mac or self.key

    def all_names(self):
        return {n.lower() for n in (self.hostname, self.dhcp_hostname,
                                    self.mdns_name, self.ssdp_name) if n}

    def presence_open(self, when):
        if not self.presence or self.presence[-1][1] is not None:
            _push_bounded(self.presence, [when, None], 60)

    def presence_close(self, when):
        if self.presence and self.presence[-1][1] is None:
            self.presence[-1][1] = max(when, self.presence[-1][0])

    def presence_lines(self, now, limit=8):
        out = []
        prev_end = None
        for start, end in self.presence[-limit:]:
            if prev_end is not None and start - prev_end > 1:
                out.append(f"Offline: {fmt_clock(prev_end)}–"
                           f"{fmt_clock(start)} "
                           f"({human_duration(start - prev_end)})")
            out.append(f"Online:  {fmt_clock(start)}–"
                       f"{'present' if end is None else fmt_clock(end)} "
                       f"({human_duration((end or now) - start)})")
            prev_end = end
        if prev_end is not None:
            out.append(f"Offline since {fmt_clock(prev_end)}")
        return out

    def traffic_baseline_flag(self, now, multiplier=4.0, min_avg=3):
        """'Unusual for this device' — simple same-session baseline: compare
        the current minute's packet count against the trailing average.
        Never claims malice, only deviation from this device's own history."""
        bucket = int(now // 60)
        hist = self._rate_hist
        if not hist or hist[-1][0] != bucket:
            hist.append([bucket, 0])
            if len(hist) > 30:
                del hist[:-30]
        hist[-1][1] += 1
        if len(hist) < 6:
            return False
        past = [c for b, c in hist[:-1]]
        avg = sum(past) / len(past)
        cur = hist[-1][1]
        return avg >= min_avg and cur > avg * multiplier


