def _explain_alerts():
    for kind, (title, _sev) in ALERT_TYPES.items():
        EXPLAIN[("alert", kind)] = (title, ALERT_MEANS.get(kind, ""))


class AlertEngine:
    def __init__(self, config, now_fn=None):
        self.config = config
        self.now = now_fn or time.time
        self.alerts = {}
        self.order = deque()          # newest first
        self._debounce = {}
        self._open = {}            # (kind, subject) -> alert id
        self.suppressed = 0

    def enabled(self, kind):
        return bool(self.config.get(f"alerts.{kind}", True))

    def is_muted(self, kind, device_key, subject):
        muted = self.config.get("alerts.muted_devices", []) or []
        expected = self.config.get("alerts.expected", []) or []
        return (f"{kind}|{device_key}" in muted or
                f"{kind}|{subject}" in expected or
                self.snoozed_until(kind, device_key) > time.time())

    def snoozed_until(self, kind, device_key=""):
        """5.3.4 (IP-001): when a snooze of this alert type (for every
        device, or for this one) ends; 0 when none. Snoozes run on the
        wall clock and end by themselves, unlike a mute."""
        sn = self.config.get("alerts.snoozed", {}) or {}
        if not isinstance(sn, dict):
            return 0.0
        out = 0.0
        for tag in (f"{kind}|*", f"{kind}|{device_key}" if device_key
                    else None):
            with contextlib.suppress(TypeError, ValueError):
                if tag:
                    out = max(out, float(sn.get(tag) or 0))
        return out

    def _add(self, kind, severity, device_key, reason, observed, interp, poss,
             confidence=None, why=None, evidence=None, refs=None,
             subject=None):
        if not self.enabled(kind):
            return None
        subject = subject or device_key
        if self.is_muted(kind, device_key, subject):
            self.suppressed += 1
            return None
        now = self.now()
        # same thing still happening and not acknowledged: update, don't spam
        oid = self._open.get((kind, subject))
        if oid and oid in self.alerts:
            a = self.alerts[oid]
            if not a.acknowledged and now - a.last_seen < 1800:
                a.count += 1
                a.last_seen = now
                a.observed = observed
                rank = {"INFO": 0, "WARNING": 1, "DANGER": 2}
                if rank.get(severity, 0) > rank.get(a.severity, 0):
                    a.severity, a.reason = severity, reason
                    a.interpretation = interp
                    a.confidence = confidence or a.confidence
                if evidence:
                    a.evidence = (a.evidence + list(evidence))[-20:]
                a.updated = True
                return a
        meta_conf, meta_why = ALERT_META.get(kind, ("Medium", ""))
        a = Alert(id=uuid.uuid4().hex[:8], kind=kind, severity=severity,
                  device_key=device_key, reason=reason, observed=observed,
                  interpretation=interp, possible_explanations=poss,
                  when=now, confidence=confidence or meta_conf,
                  why=why or meta_why, subject=subject, first_seen=now,
                  last_seen=now, evidence=list(evidence or [])[:20],
                  refs=dict(refs or {}))
        if device_key and not a.refs.get("device") and \
                not device_key.startswith("ip:"):
            a.refs["device"] = device_key
        self.alerts[a.id] = a
        self.order.appendleft(a.id)
        self._open[(kind, subject)] = a.id
        while len(self.order) > 500:
            old = self.alerts.pop(self.order.pop(), None)
            # 5.2.3 (B-27): forget it as "open" too (the map only grew)
            if old is not None and \
                    self._open.get((old.kind, old.subject)) == old.id:
                del self._open[(old.kind, old.subject)]
        return a

    DEBOUNCE_KEEP = 20000

    def _debounced(self, key, seconds):
        now = self.now()
        last = self._debounce.get(key)
        # 5.3.4 (CO-13): after the clock steps back, `now - last` is
        # negative and the detection stayed silent for the whole step
        if last is not None and 0 <= now - last < seconds:
            return True
        self._debounce[key] = now
        if len(self._debounce) > self.DEBOUNCE_KEEP:
            # 5.2.3 (B-27): keys are per device and address, so this grew
            # for ever; nothing waits longer than a day
            for k in [k for k, t in self._debounce.items()
                      if now - t > 86400]:
                del self._debounce[k]
            if len(self._debounce) > self.DEBOUNCE_KEEP:
                for k in list(itertools.islice(self._debounce,
                                               self.DEBOUNCE_KEEP // 10)):
                    del self._debounce[k]
        return False

    def acknowledge(self, aid):
        a = self.alerts.get(aid)
        if a:
            a.acknowledged = True
        return a

    def counts(self, include_ack=False):
        c = Counter()
        for aid in self.order:
            a = self.alerts.get(aid)
            if a and (include_ack or not a.acknowledged):
                c[a.severity] += 1
        return c

    def new_device(self, dev):
        if dev.expected:
            return None
        return self._add(
            "new_device", "INFO", dev.key,
            f"{dev.display_name()} joined your network",
            f"A device with {dev.confidence.lower()}-confidence identity "
            f"evidence ({', '.join(dev.evidence_summary()) or 'minimal'}) "
            f"appeared.",
            "This is a new local device on your network.",
            "Normal if you just added a device (phone, guest, smart-home "
            "gadget). Worth checking if you don't recognize it.")

    def gateway_change(self, gw_ip, n_macs):
        if self._debounced(f"gw:{gw_ip}", 120):
            return None
        return self._add(
            "gateway_change", "WARNING", f"ip:{gw_ip}",
            "Your router's MAC address changed",
            f"Your gateway ({gw_ip}) has answered ARP from {n_macs} "
            f"different MAC addresses in this session.",
            "The device claiming to be your router is not consistent.",
            "Often normal right after a router reboot or firmware update. "
            "It is also the classic sign of ARP spoofing \u2014 a device "
            "pretending to be your router. If you didn't just restart "
            "your router, investigate.")

    def duplicate_ip(self, ip, n_macs):
        if self._debounced(f"dupip:{ip}", 120):
            return None
        return self._add(
            "duplicate_ip", "WARNING", f"ip:{ip}",
            f"{ip} has answered from more than one device",
            f"{n_macs} different MAC addresses have claimed {ip}.",
            "Two devices currently disagree about who owns this address.",
            "Often harmless \u2014 Wi-Fi privacy MAC rotation or a device "
            "reconnecting and briefly overlapping the old lease. Worth a "
            "look if it keeps happening.")

    def dhcp_anomaly(self, servers):
        if self._debounced("dhcp_anomaly", 300):
            return None
        return self._add(
            "dhcp_anomaly", "WARNING", "",
            "More than one device is handing out IP addresses",
            f"{len(servers)} different DHCP servers seen: "
            f"{', '.join(sorted(servers))}.",
            "Normally only your router does this.",
            "Could be a second router plugged in by mistake, or \u2014 "
            "less commonly \u2014 a rogue DHCP server. If you don't "
            "recognize one of these addresses, unplug that device and "
            "check your network.")

    def rogue_ra(self, mac, who, prefixes, routers):
        if self._debounced(f"rogue_ra:{mac}", 600):
            return None
        return self._add(
            "rogue_ra", "WARNING", mac,
            f"{who} announced itself as an IPv6 router",
            f"An IPv6 Router Advertisement came from {mac}"
            f"{(' for ' + ', '.join(prefixes[:3])) if prefixes else ''}. "
            f"Routers announcing on this network: {', '.join(routers)}.",
            "Devices that accept this announcement may send IPv6 traffic "
            "through that device.",
            "Mesh Wi-Fi nodes, a second router, a phone hotspot or a "
            "virtual-machine host can do this legitimately.",
            evidence=[f"RA from {mac}"] + [f"prefix {p}" for p in
                                           prefixes[:4]],
            subject=f"rogue_ra:{mac}")

    def arp_spoof(self, ip, n_macs, flips, is_gateway, together=0):
        if self._debounced(f"arpspoof:{ip}", 120):
            return None
        who = "Your router's address" if is_gateway else f"The address {ip}"
        return self._add(
            "arp_spoof", "DANGER", f"ip:{ip}",
            f"{who} keeps switching between devices",
            f"{ip} was claimed by {n_macs} different MAC addresses and "
            f"flipped back and forth {flips} times within a minute."
            if flips >= 4 or not together else
            f"{ip} was claimed by {together} different MAC addresses "
            f"answering at the same time (each more than once within "
            f"2 minutes).",
            "Two devices are repeatedly fighting over the same network "
            "address.",
            "A device normally answers for its address consistently. Rapid "
            "flip-flopping is the signature of ARP spoofing \u2014 one "
            "device impersonating another so traffic passes through it. It "
            "can also happen if two devices were accidentally given the "
            "same fixed IP. If this is your router's address, treat it "
            "seriously: disconnect and check the router's device list.")

    def chatty_device(self, dev):
        if self._debounced(f"chatty:{dev.key}", 600):
            return None
        return self._add(
            "chatty_device", "WARNING", dev.key,
            f"{dev.display_name()} is unusually active right now",
            "This device's traffic this minute is well above its own "
            "recent average.",
            "Its behavior changed compared to its own baseline this "
            "session.",
            "Often normal \u2014 a big download, a video call, a software "
            "update. Worth a glance if you don't expect that device to be "
            "busy right now.")

    def unknown_device(self, dev):
        if self._debounced(f"unknown:{dev.key}", 600):
            return None
        return self._add(
            "unknown_device", "WARNING", dev.key,
            f"{dev.display_name()} has very little identifying information",
            f"Only {', '.join(dev.evidence_summary()) or 'minimal'} "
            f"evidence is available for this device.",
            "MiniWireshark can't confidently say what this device is.",
            "Common for devices that stay quiet or use a randomized MAC. "
            "Confidence usually improves the longer it's on the network.")

    def reconnect_cycle(self, dev, n, window_s):
        if self._debounced(f"reconnect:{dev.key}", 600):
            return None
        return self._add(
            "reconnect_cycle", "WARNING", dev.key,
            f"{dev.display_name()} has joined/left {n} times recently",
            f"{n} reconnects in the last {int(window_s / 60)} minutes.",
            "This device is repeatedly reconnecting.",
            "Usually Wi-Fi interference, a weak signal, or a device with "
            "power-saving/roaming quirks \u2014 rarely an attack.")


    # ---- 3.0 detections (all phrased as anomalies) -----------------------
    def dns_server_change(self, dev_name, dev_key, old, new):
        if self._debounced(f"dnschg:{dev_key}:{new}", 1800):
            return None
        return self._add(
            "dns_server_change", "WARNING", dev_key,
            f"{dev_name} switched to a different DNS server",
            f"It had been using {old} for its lookups and is now using "
            f"{new}.",
            "The service that turns website names into addresses changed "
            "for this device.",
            "Common and harmless when a VPN connects, a browser enables "
            "secure DNS, or you change settings. Worth checking if you "
            "didn't change anything, because DNS decides which servers "
            "your device talks to.",
            confidence="Medium",
            why="This device consistently used one DNS server, then moved "
                "to another.",
            evidence=[f"Previous server: {old}", f"New server: {new}"],
            subject=f"{dev_key}|{new}")

    def dns_failures(self, rate, n, servers):
        if self._debounced("dnsfail", 900):
            return None
        return self._add(
            "dns_failures", "WARNING", "",
            "Many website lookups are failing",
            f"{rate:.0%} of the last {n} DNS lookups failed or got no "
            f"answer (servers: {', '.join(servers) or 'unknown'}).",
            "Website names aren't being resolved reliably right now.",
            "Often a temporary problem at your Internet provider or router, "
            "or an ad-blocker deliberately refusing some names.",
            confidence="Medium" if n >= 40 else "Low",
            why="The share of failed lookups is well above normal.",
            subject="dns")

    def dns_slow(self, median_ms, n, server):
        if self._debounced("dnsslow", 1800):
            return None
        return self._add(
            "dns_slow", "WARNING", "",
            "Website lookups are slow",
            f"The typical DNS answer took {median_ms:.0f} ms over the last "
            f"{n} lookups ({server or 'various servers'}).",
            "Pages may feel slow to start loading.",
            "Usually your provider's DNS being slow or a congested "
            "connection; it isn't a security problem.",
            confidence="Medium", why="Median DNS latency exceeded the "
                                     "slow-DNS threshold.",
            subject="dns")

    def dns_multi(self, servers):
        if self._debounced("dnsmulti", 3600):
            return None
        return self._add(
            "dns_multi", "INFO", "",
            f"{len(servers)} different DNS servers are in use",
            f"Lookups went to: {', '.join(sorted(servers)[:8])}.",
            "Devices on your network don't all use the same DNS service.",
            "Normal with VPNs, browsers that use their own secure DNS, or "
            "gadgets with hard-coded DNS. Public DNS services are not "
            "harmful in themselves.",
            confidence="High", why="More than three DNS servers were "
                                   "contacted.",
            subject="dnsmulti")

    def baseline_anomaly(self, dev, feature, value, mean):
        kind = {"bytes_up": "upload_spike", "bytes_down": "download_spike",
                "destinations": "many_destinations",
                "new_conns": "many_connections"}.get(feature)
        if not kind or self._debounced(f"{kind}:{dev.key}", 1800):
            return None
        label = {"bytes_up": ("uploaded", _human_bytes(value),
                              _human_bytes(mean)),
                 "bytes_down": ("downloaded", _human_bytes(value),
                                _human_bytes(mean)),
                 "destinations": ("contacted", f"{int(value)} different "
                                  f"Internet hosts", f"{mean:.0f}"),
                 "new_conns": ("opened", f"{int(value)} new connections",
                               f"{mean:.0f}")}[feature]
        title = ALERT_TYPES[kind][0]
        return self._add(
            kind, ALERT_TYPES[kind][1], dev.key,
            f"{dev.display_name()}: {title.lower()}",
            f"In one minute it {label[0]} {label[1]}; its usual minute is "
            f"about {label[2]}.",
            "This behavior is unusual compared with this device's recent "
            "activity.",
            "Updates, backups, video calls, game downloads and cloud sync "
            "all cause bursts like this. It only matters if the device "
            "shouldn't be doing anything right now.",
            confidence="Medium",
            why="Compared with this device's own learned baseline (not "
                "with other devices).",
            evidence=[f"This minute: {label[1]}", f"Usual: {label[2]}"])

    def tcp_resets(self, dev, n, window_s, top_remote):
        if self._debounced(f"rst:{dev.key}", 1800):
            return None
        return self._add(
            "tcp_resets", "WARNING", dev.key,
            f"{dev.display_name()}: many connections are being reset",
            f"{n} connections were abruptly reset in the last "
            f"{int(window_s / 60)} minutes" +
            (f" (most often with {top_remote})." if top_remote else "."),
            "Connections are being refused or cut off.",
            "Often a service that's down, a firewall/ad-blocker refusing "
            "connections, or a flaky connection. Rarely a security issue.",
            confidence="Medium", why="The reset count crossed the "
                                     "threshold for this window.")

    def new_service(self, dev, service):
        if self._debounced(f"svc:{dev.key}:{service}", 86400):
            return None
        desc = service_description(service)
        return self._add(
            "new_service", "INFO", dev.key,
            f"{dev.display_name()} started advertising “{service}”",
            f"A device I already knew began announcing a new network "
            f"service: {service}." + (f" {desc}" if desc else ""),
            "This device now offers something new on your network.",
            "Normal after enabling sharing, casting or a new app. Worth a "
            "look only if you didn't change anything.",
            confidence="High", why="A known device advertised a service it "
                                   "hadn't advertised before.",
            subject=f"{dev.key}|{service}")

    def cleartext(self, dev_name, dev_key, proto, remote, is_public):
        if self._debounced(f"clear:{dev_key}:{proto}", 3600):
            return None
        sev = "WARNING" if proto in ("TELNET", "FTP", "POP3", "IMAP") and \
            is_public else "INFO"
        return self._add(
            "cleartext", sev, dev_key,
            f"{dev_name} used an unencrypted protocol ({proto})",
            f"Unencrypted {proto} traffic with {remote} was observed.",
            "Anyone on the same network path could read this traffic.",
            "Common for old devices, local printers and some smart-home "
            "gear. It's worth avoiding for anything with a password.",
            confidence="High", why="The protocol was recognised from the "
                                   "traffic itself.",
            subject=f"{dev_key}|{proto}")

    def remote_access(self, dev_name, dev_key, service, how):
        if self._debounced(f"ra:{dev_key}:{service}", 86400):
            return None
        return self._add(
            "remote_access", "WARNING", dev_key,
            f"{dev_name} offers remote access ({service})",
            f"{how}",
            "This device can probably be controlled over the network.",
            "Fine if you set it up (e.g. SSH on a Raspberry Pi, Remote "
            "Desktop on your PC). Make sure it's intended and protected "
            "by a strong password.",
            confidence="Medium", why="A remote-access service was "
                                     "advertised or accepted connections.",
            subject=f"{dev_key}|{service}")

    def new_listener(self, dev_key, program, proto, port, scope):
        # 5.3.4 (CO-13): another program on the same port is news
        if self._debounced(f"ls:{proto}:{port}:{scope}:{program}", 86400):
            return None
        net = scope == "the network"
        return self._add(
            "new_listener", "WARNING" if net else "INFO", dev_key,
            f"A program on this computer started accepting connections: "
            f"{program or 'unknown program'} on {proto} port {port}",
            f"It is reachable from {scope}. Seen in this computer's own "
            f"connection table.",
            "A new service on this computer can be reached by others"
            if net else "A new local-only service on this computer.",
            "Often normal (a game, a file-sharing app, a developer tool). "
            "If you don't recognise the program, close it or check it with "
            "your antivirus.",
            confidence="High", why="The operating system lists it as "
                                   "listening; it wasn't there before.",
            subject=f"{dev_key}|{proto}/{port}")

    def arp_cache_mismatch(self, ip, cache_mac, seen_macs, is_gateway):
        if self._debounced(f"arpc:{ip}:{cache_mac}", 3600):
            return None
        who = "your router" if is_gateway else ip
        return self._add(
            "arp_cache_mismatch", "DANGER" if is_gateway else "WARNING", "",
            f"This computer's ARP cache disagrees about {who}",
            f"This computer has {ip} → {cache_mac}, but on the network "
            f"{ip} answers from {', '.join(sorted(seen_macs)[:3])}.",
            "Another device may be pretending to be "
            + ("your router (ARP spoofing), which lets it see your traffic."
               if is_gateway else "this address."),
            "If it persists, restart the router and this computer's Wi-Fi; "
            "if it comes back, look for an unknown device on the network. "
            "It can also happen right after a router is replaced.",
            confidence="Medium", why="The address-to-hardware mapping this "
                                     "computer uses differs from the one "
                                     "seen in replies on the wire.",
            subject=f"arp|{ip}")

    def reputation(self, dev, ip, port, hits):
        """A device contacted an address a public list names. One list:
        a warning; two independent lists agreeing: stronger. Never a
        verdict — lists go stale and shared hosting is common."""
        if not hits or self._debounced(f"rep:{dev.key}:{ip}", 86400):
            return None
        sources = sorted({h[0] for h in hits})
        two = len(sources) >= 2
        return self._add(
            "reputation", "DANGER" if two else "WARNING", dev.key,
            f"{dev.display_name()} contacted an address on "
            f"{'two public blocklists' if two else 'a public blocklist'}",
            f"It connected to {ip}" + (f" (port {port})" if port else "")
            + f", which is {reputation_text(hits)}.",
            ("Two independent lists name this address, which makes a "
             "mistake less likely." if two else
             "A public list names this address as malicious (for example "
             "a botnet command server or a hijacked network)."),
            "Lists can be out of date, and one address can host many "
            "unrelated sites. Check which program on that device made the "
            "connection; if you don't recognise it, run a malware scan on "
            "that device.",
            confidence="High" if two else "Medium",
            why=f"Matched {', '.join(sources)} on this computer (the "
                f"address was never sent anywhere).",
            refs={"remote": ip}, subject=f"rep|{dev.key}|{ip}")

    def new_country(self, dev, country, remote):
        if self._debounced(f"cc:{dev.key}:{country}", 86400):
            return None
        return self._add(
            "new_country", "INFO", dev.key,
            f"{dev.display_name()} contacted a new country ({country})",
            f"It connected to {remote}, located in {country} (per the "
            f"lookup database), after its usual destinations were learned.",
            "A destination country this device hadn't used this session.",
            "Very often normal: cloud and content services are spread "
            "across many countries. Location databases can also be wrong.",
            confidence="Low", why="New country after the baseline period.",
            subject=f"{dev.key}|{country}")

    def broadcast_storm(self, pps, top):
        if self._debounced("bstorm", 1800):
            return None
        return self._add(
            "broadcast_storm", "WARNING", "",
            "A lot of broadcast/multicast traffic",
            f"About {pps:.0f} broadcast/multicast packets per second" +
            (f", mostly from {top}." if top else "."),
            "The local network is being flooded with 'to everyone' "
            "messages.",
            "Can be a misbehaving gadget, a network loop (a cable plugged "
            "into two switch ports), or heavy discovery traffic.",
            confidence="Medium", why="Broadcast rate stayed above the "
                                     "threshold.",
            subject="bstorm")

    def scan_pattern(self, dev, what, n):
        if self._debounced(f"scan:{dev.key}", 3600):
            return None
        return self._add(
            "scan_pattern", "WARNING", dev.key,
            f"{dev.display_name()} shows a scanning-like pattern",
            f"Within a minute it tried {n} {what}, most without an answer.",
            "This looks like what network-scanning tools do.",
            "Expected if you run a scanner (or IT tools, printers/NAS "
            "discovery) on purpose. Otherwise, check what software the "
            "device runs.",
            confidence="Medium", why="Many distinct connection attempts "
                                     "with few successful replies.")


# ============================================================================
#  This computer's Wi-Fi link (read-only questions to the operating system)
# ============================================================================
def _keychain_quotable(s):
    return isinstance(s, str) and not any(c in s for c in "\r\n\0")


def _keychain_quote(s):
    """One argument for `security -i`: double quotes, with backslash and
    double quote escaped."""
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _one_line_end(text):
    """`text` without its one trailing newline (5.2.3, B-41: rstrip("\\n")
    removed backslashes and the letter n, and kept the newline)."""
    if text.endswith("\r\n"):
        return text[:-2]
    return text[:-1] if text.endswith("\n") else text


def console_decode(data):
    """Bytes from a console program as text. 5.2.3 (B-09): Windows tools
    (netsh, arp) write in the OEM code page, not the ANSI one `text=True`
    uses, so on French, German or Russian Windows the decode failed and
    stopped the network-identity thread. Nothing here can raise."""
    if isinstance(data, str) or data is None:
        return data or ""
    for enc in (("oem",) if IS_WINDOWS else ()) + (
            locale.getpreferredencoding(False) or "utf-8",):
        try:
            return data.decode(enc)
        except (LookupError, UnicodeDecodeError):
            continue
    return data.decode("utf-8", "replace")


def run_console(cmd, timeout=10):
    """subprocess.run for a read-only console tool: no window flashes,
    output decoded with console_decode."""
    r = subprocess.run(cmd, capture_output=True, timeout=timeout,
                       creationflags=getattr(subprocess,
                                             "CREATE_NO_WINDOW", 0))
    r.stdout, r.stderr = console_decode(r.stdout), console_decode(r.stderr)
    return r


def wifi_channel_from_mhz(mhz):
    try:
        f = int(round(float(mhz)))
    except (TypeError, ValueError):
        return None, ""
    if f == 2484:
        return 14, "2.4 GHz"
    if 2412 <= f <= 2472:
        return (f - 2407) // 5, "2.4 GHz"
    if 5150 <= f <= 5895:
        return (f - 5000) // 5, "5 GHz"
    if f == 5935:                    # 6 GHz channel 2 (5.2.3, B-19)
        return 2, "6 GHz"
    if 5955 <= f <= 7125:
        return (f - 5950) // 5, "6 GHz"
    return None, ""


def _num(text):
    try:
        return float(str(text).replace(",", ".").strip())
    except (TypeError, ValueError):
        return None


def parse_netsh_wlan(text, want=""):
    """`netsh wlan show interfaces` (English, French or Spanish Windows).
    `want` = adapter name or description to prefer."""
    blocks, cur = [], {}
    for line in (text or "").splitlines():
        if ":" not in line:
            if cur and not line.strip():
                continue
            continue
        k, _sep, v = line.partition(":")
        k, v = k.strip().lower(), v.strip()
        if k in ("name", "nom", "nombre") and cur.get("name"):
            blocks.append(cur)
            cur = {}
        cur[k] = v
        if k in ("name", "nom", "nombre"):
            cur["name"] = v
    if cur:
        blocks.append(cur)

    def pick(b, *keys):
        for key, val in b.items():
            for k in keys:
                if key.startswith(k):
                    return val
        return ""
    best = None
    for b in blocks:
        state = pick(b, "state", "état", "etat", "estado").lower()
        ok = state.startswith(("connected", "connect", "conectado"))
        desc = pick(b, "description", "descripción", "descripcion")
        if want and (want == b.get("name") or want == desc):
            best = b if ok else best
            if ok:
                break
        if ok and best is None:
            best = b
    if best is None:
        return None
    b = best
    sig = re.search(r"(\d+)\s*%", pick(b, "signal", "señal", "senal"))
    rssi = _num(pick(b, "rssi"))
    pct = int(sig.group(1)) if sig else None
    if rssi is None and pct is not None:
        rssi = pct / 2.0 - 100.0          # Windows' own mapping
    ch = _num(pick(b, "channel", "canal"))
    band = pick(b, "band", "bande", "banda")
    return {"source": "netsh", "iface": b.get("name", ""),
            "ssid": pick(b, "ssid"),
            "bssid": pick(b, "ap bssid", "bssid", "bssid del punto",
                          "bssid du point").lower(),
            "rssi": rssi, "signal_pct": pct,
            "rx_mbps": _num(pick(b, "receive rate", "réception",
                                 "reception", "velocidad de recepción",
                                 "velocidad de recepcion")),
            "tx_mbps": _num(pick(b, "transmit rate", "transmission",
                                 "velocidad de transmisión",
                                 "velocidad de transmision")),
            "channel": int(ch) if ch is not None else None,
            "band": band or ("2.4 GHz" if ch and ch <= 14 else
                             "5 GHz" if ch else ""),
            "standard": pick(b, "radio type", "type de radio",
                             "tipo de radio")}


def parse_iw_link(text, iface=""):
    """`iw dev <iface> link` (Linux)."""
    text = text or ""
    if "Not connected" in text or "Connected to" not in text:
        return None
    m = re.search(r"Connected to ([0-9a-fA-F:]{17})", text)
    out = {"source": "iw", "iface": iface, "ssid": "", "rssi": None,
           "signal_pct": None, "rx_mbps": None, "tx_mbps": None,
           "channel": None, "band": "", "standard": "",
           "bssid": m.group(1).lower() if m else ""}
    for line in text.splitlines():
        k, _s, v = line.strip().partition(":")
        k, v = k.strip().lower(), v.strip()
        if k == "ssid":
            out["ssid"] = v
        elif k == "freq":
            out["channel"], out["band"] = wifi_channel_from_mhz(v)
        elif k == "signal":
            out["rssi"] = _num(v.split()[0]) if v else None
        elif k in ("rx bitrate", "tx bitrate") and v:
            rate = _num(v.split()[0])
            out["rx_mbps" if k.startswith("rx") else "tx_mbps"] = rate
            for std, tag in (("802.11be", "EHT"), ("802.11ax", "HE"),
                             ("802.11ac", "VHT"), ("802.11n", "MCS")):
                if tag in v and not out["standard"]:
                    out["standard"] = std
    return out


def parse_proc_wireless(text, iface=""):
    """/proc/net/wireless (Linux, when `iw` is missing): signal only."""
    for line in (text or "").splitlines()[2:]:
        name, _s, rest = line.partition(":")
        name = name.strip()
        if iface and name != iface:
            continue
        parts = rest.split()
        if len(parts) >= 3:
            level = _num(parts[2].rstrip("."))
            if level is None:
                continue
            if level > 0:                 # some drivers report 0..100
                level = level / 2.0 - 100.0
            return {"source": "/proc/net/wireless", "iface": name,
                    "ssid": "", "bssid": "", "rssi": level,
                    "signal_pct": None, "rx_mbps": None, "tx_mbps": None,
                    "channel": None, "band": "", "standard": ""}
    return None


def parse_macos_airport(text):
    """`system_profiler SPAirPortDataType` (macOS)."""
    text = text or ""
    i = text.find("Current Network Information:")
    if i < 0:
        return None
    block = text[i:].splitlines()[1:]
    out = {"source": "system_profiler", "iface": "", "ssid": "",
           "bssid": "", "rssi": None, "signal_pct": None, "rx_mbps": None,
           "tx_mbps": None, "channel": None, "band": "", "standard": ""}
    if block:
        out["ssid"] = block[0].strip().rstrip(":")
    for line in block[1:30]:
        k, _s, v = line.strip().partition(":")
        k, v = k.strip().lower(), v.strip()
        if not v and k.endswith("information"):
            break
        if k == "signal / noise":
            m = re.match(r"(-?\d+)\s*dBm\s*/\s*(-?\d+)", v)
            if m:
                out["rssi"] = float(m.group(1))
                out["noise"] = float(m.group(2))
        elif k == "channel":
            m = re.match(r"(\d+)\s*\(([\d.]+)\s*GHz", v)
            if m:
                out["channel"] = int(m.group(1))
                out["band"] = f"{m.group(2)} GHz"
        elif k == "transmit rate":
            out["tx_mbps"] = _num(v)
        elif k == "phy mode":
            out["standard"] = v
    return out


def wifi_quality(rssi):
    """→ (health status, word, plain-English explanation)."""
    if rssi is None:
        return "Unknown", "unknown", "Signal strength not reported."
    if rssi >= -60:
        return "Healthy", "excellent", "Strong signal."
    if rssi >= -67:
        return "Healthy", "good", "Good signal."
    if rssi >= -75:
        return "Degraded", "fair", ("Usable, but video calls and big "
                                    "downloads may stutter.")
    return "Needs attention", "weak", ("Weak signal — the most likely cause "
                                       "of slowness. Move closer to the "
                                       "router or remove obstacles.")


# 5.3.4 (BF-002): Windows 11 24H2 answers `netsh wlan show interfaces`
# with a request for the Location permission instead of the reading
WIFI_LOCATION_NOTE = ("Windows hides Wi-Fi details (signal, channel, "
                      "network name) unless Location is allowed for apps. "
                      "MiniWireshark never turns Location on or asks for it.")

MAC_WIFI_NOTE = ("macOS hides the Wi-Fi network name unless Location is "
                 "allowed for this app. MiniWireshark never asks for it.")



def netsh_location_hidden(text):
    t = (text or "").lower()
    if "privacy-location" in t:
        return True
    return bool(re.search(r"locat|locali|ubicaci", t)) and bool(
        re.search(r"permission|autorisation|permiso|privacy|confidential|"
                  r"privacidad", t)) and not re.search(
        r"^\s*(ssid|bssid|state|état|etat|estado)\s*:", t, re.M)


class WifiProbe:
    """Asks the operating system about THIS computer's Wi-Fi link every
    `interval` seconds, in the background. Read-only: nothing is sent on
    the network and no setting is changed."""

    def __init__(self, interval=30):
        self.interval = interval
        self.last = None
        self.at = 0.0
        self.busy = False
        self.error = ""
        self.history = deque(maxlen=240)     # (ts, rssi)
        self.seq = 0
        self.hidden = ""      # why the OS gave no reading (BF-002)

    @staticmethod
    def _cmd(cmd, timeout=10):
        try:
            return run_console(cmd, timeout=timeout).stdout or ""
        except (OSError, subprocess.SubprocessError):
            return ""

    def read(self, iface="", desc=""):
        if IS_WINDOWS:
            text = self._cmd(["netsh", "wlan", "show", "interfaces"])
            self.hidden = WIFI_LOCATION_NOTE if netsh_location_hidden(
                text) else ""
            return None if self.hidden else parse_netsh_wlan(
                text, desc or iface)
        if sys.platform == "darwin":
            got = parse_macos_airport(self._cmd(
                ["system_profiler", "SPAirPortDataType"], 30))
            self.hidden = MAC_WIFI_NOTE if got and mac_ssid_hidden(
                got["ssid"]) else ""
            if self.hidden:
                got["ssid"] = ""
            return got
        names = [iface] if iface and os.path.isdir(
            f"/sys/class/net/{iface}/wireless") else [
            n for n in sorted(os.listdir("/sys/class/net"))
            if os.path.isdir(f"/sys/class/net/{n}/wireless")] \
            if os.path.isdir("/sys/class/net") else []
        for name in names:
            if shutil.which("iw"):
                got = parse_iw_link(self._cmd(["iw", "dev", name, "link"]),
                                    name)
                if got:
                    return got
            try:
                with open("/proc/net/wireless", encoding="utf-8") as f:
                    got = parse_proc_wireless(f.read(), name)
            except OSError:
                got = None
            if got:
                return got
        return None

    def refresh(self, iface="", desc="", force=False):
        if self.busy or (not force and time.time() - self.at <
                         self.interval):
            return False
        self.busy = True
        self.at = time.time()

        def work():
            try:
                got = self.read(iface, desc)
                self.error = ""
            except Exception as e:                   # noqa: BLE001
                got, self.error = None, str(e)
            self.last = got
            if got and got.get("rssi") is not None:
                self.history.append((time.time(), got["rssi"]))
            self.seq += 1
            self.busy = False
        threading.Thread(target=work, daemon=True, name="wifi-probe").start()
        return True

    def summary(self):
        w = self.last
        if not w:
            return None
        status, word, why = wifi_quality(w.get("rssi"))
        parts = []
        if w.get("rssi") is not None:
            parts.append(f"{w['rssi']:.0f} dBm ({word})")
        if w.get("tx_mbps") or w.get("rx_mbps"):
            parts.append(f"link {w.get('rx_mbps') or w.get('tx_mbps'):.0f} "
                         f"Mbit/s")
        if w.get("channel"):
            parts.append(f"channel {w['channel']}"
                         + (f" ({w['band']})" if w.get("band") else ""))
        if w.get("standard"):
            parts.append(w["standard"])
        return status, word, why, ", ".join(parts)


# ============================================================================
#  9b.  This computer: which program owns each connection, which programs
#       accept connections, and what its ARP cache says (all read-only
#       questions to the operating system)
# ============================================================================
def _psutil():
    ps = OPTIONAL_MODULES.get("psutil")
    if ps is None and "psutil" not in OPTIONAL_MODULES:
        try:
            import psutil as ps                       # noqa: F811
        except ImportError:
            ps = None
        OPTIONAL_MODULES["psutil"] = ps
    return ps


class ProcessMap:
    """A snapshot of this computer's connection table: local address and
    port → program. Refreshed in the background every few seconds while
    watching live. Programs the operating system won't name without admin
    rights are shown as such, never guessed."""

    def __init__(self, interval=2.0):
        self.interval = interval
        self.by_local = {}        # (proto, ip, port) → (pid, name)
        self.by_port = {}         # (proto, port) → (pid, name)
        self.listening = {}       # (proto, ip, port) → (pid, name)
        self.names = {}           # pid → name
        self.at = 0.0
        self.busy = False
        self.needs_admin = False
        self.error = ""
        self.available = _psutil() is not None
        self.seq = 0

    def _name(self, ps, pid):
        if not pid:
            return "the operating system"
        n = self.names.get(pid)
        if n is None:
            try:
                n = ps.Process(pid).name()
            except Exception:                        # noqa: BLE001
                n = ""
            if len(self.names) > 5000:
                self.names.clear()
            self.names[pid] = n
        return n

    def _connections(self, ps):
        try:
            return ps.net_connections(kind="inet"), False
        except ps.AccessDenied:
            pass                     # macOS without admin: per process
        out = []
        for p in ps.process_iter(["pid"]):
            try:
                fn = getattr(p, "net_connections", None) or p.connections
                for c in fn(kind="inet"):
                    out.append((c, p.pid))     # per-process rows lack pid
            except Exception:                        # noqa: BLE001
                continue
        return out, True

    def read(self):
        ps = _psutil()
        if ps is None:
            return False
        conns, partial = self._connections(ps)
        by_local, by_port, listening = {}, {}, {}
        unnamed = 0
        # 5.2.3 (B-18): Windows reuses process numbers quickly; a name is
        # kept only while its process number is still in the table, so a
        # new program never inherits a finished one's name
        live = {c[1] if isinstance(c, tuple) and len(c) == 2 and
                not hasattr(c, "laddr") else getattr(c, "pid", None)
                for c in conns}
        for gone in [p for p in self.names if p not in live]:
            del self.names[gone]
        for c in conns:
            pid = None
            if isinstance(c, tuple) and len(c) == 2 and not hasattr(
                    c, "laddr"):
                c, pid = c
            pid = pid if pid is not None else getattr(c, "pid", None)
            la = getattr(c, "laddr", None)
            if not la:
                continue
            proto = "TCP" if getattr(c, "type", 1) == 1 else "UDP"
            ip, port = la[0], la[1]
            name = self._name(ps, pid) if pid else ""
            if pid is None:
                unnamed += 1
            ent = (pid, name)
            by_local[(proto, ip, port)] = ent
            by_port.setdefault((proto, port), ent)
            ra = getattr(c, "raddr", None)
            status = getattr(c, "status", "")
            if (proto == "TCP" and status == "LISTEN") or \
                    (proto == "UDP" and not ra):
                listening[(proto, ip, port)] = ent
        self.by_local, self.by_port, self.listening = by_local, by_port, \
            listening
        self.needs_admin = partial or unnamed > 0
        self.at = time.time()
        self.seq += 1
        return True

    def refresh(self, force=False):
        if not self.available or self.busy or (
                not force and time.time() - self.at < self.interval):
            return False
        self.busy = True

        def work():
            try:
                self.read()
                self.error = ""
            except Exception as e:                   # noqa: BLE001
                self.error = str(e)
            finally:
                self.busy = False
        threading.Thread(target=work, daemon=True, name="process-map").start()
        return True

    def lookup(self, proto, ip, port):
        """→ (pid, name) or None. Name "" = the OS didn't say (admin)."""
        if port is None:
            return None
        ent = self.by_local.get((proto, ip, port))
        if ent is None:
            for any_ip in ("0.0.0.0", "::", ""):
                ent = self.by_local.get((proto, any_ip, port))
                if ent is not None:
                    break
        if ent is None:
            ent = self.by_port.get((proto, port))
        return ent


def program_label(ent):
    if ent is None:
        return ""
    pid, name = ent
    if name:
        return f"{name} (pid {pid})" if pid else name
    return "unknown program (needs admin rights to name it)"


# Ports below the usual ephemeral range count as "services"; an UDP socket
# above it is almost always a client asking something.
LISTEN_EPHEMERAL = 32768


def listening_key(proto, ip, port):
    scope = "this computer only" if ip in ("127.0.0.1", "::1") or \
        str(ip).startswith("127.") else "the network"
    return f"{proto}/{port}/{scope}"


class ListenWatch:
    """Remembers which programs accept connections on this computer and
    reports new ones. The first look only learns (no alerts)."""

    def __init__(self, path):
        self.path = path
        self.known = read_json(path, {}) or {}
        if not isinstance(self.known, dict):
            self.known = {}
        self.learning = not self.known

    def check(self, listening, now=None):
        """→ [(key, proto, ip, port, program, scope)] new since last time."""
        now = now or time.time()
        new = []
        for (proto, ip, port), ent in sorted(listening.items(),
                                             key=lambda kv: str(kv[0])):
            if proto == "UDP" and port >= LISTEN_EPHEMERAL:
                continue
            key = listening_key(proto, ip, port)
            prog = program_label(ent)
            rec = self.known.get(key)
            if rec is None:
                self.known[key] = {"program": prog, "first": now,
                                   "last": now}
                if not self.learning:
                    new.append((key, proto, ip, port, prog,
                                key.rsplit("/", 1)[1]))
            else:
                rec["last"] = now
                if prog and rec.get("program") != prog and \
                        "needs admin" not in prog:
                    # 5.3.4 (CO-13): a different program took over a port
                    # that was seen before: report it, don't just rename
                    old = rec.get("program") or ""
                    rec["program"] = prog
                    if old and "needs admin" not in old and \
                            not self.learning and \
                            re.sub(r" \(pid \d+\)$", "", old) != \
                            re.sub(r" \(pid \d+\)$", "", prog):
                        new.append((key, proto, ip, port, prog,
                                    key.rsplit("/", 1)[1]))
        self.learning = False
        with contextlib.suppress(OSError):
            atomic_write_json(self.path, self.known)
        return new


def parse_proc_arp(text):
    """/proc/net/arp (Linux) → [(ip, mac, iface)]."""
    out = []
    for line in (text or "").splitlines()[1:]:
        parts = line.split()
        if len(parts) >= 6 and parts[2] != "0x0":
            out.append((parts[0], parts[3].lower(), parts[5]))
    return out


def parse_arp_windows(text):
    """`arp -a` (Windows; any language) → [(ip, mac, iface_ip)]."""
    out, iface = [], ""
    for line in (text or "").splitlines():
        m = re.search(r"(\d+\.\d+\.\d+\.\d+)\s+---\s+0x", line)
        if m:
            iface = m.group(1)
            continue
        m = re.match(r"\s*(\d+\.\d+\.\d+\.\d+)\s+([0-9a-fA-F]{2}(?:-[0-9a-fA-F]"
                     r"{2}){5})\s+(\S+)", line)
        if m:
            out.append((m.group(1), m.group(2).replace("-", ":").lower(),
                        iface))
    return out


def parse_arp_bsd(text):
    """`arp -an` (macOS / BSD) → [(ip, mac, iface)]."""
    out = []
    for line in (text or "").splitlines():
        m = re.search(r"\((\d+\.\d+\.\d+\.\d+)\) at ([0-9a-fA-F:]+)"
                      r"(?: on (\S+))?", line)
        if m and "incomplete" not in line:
            mac = ":".join(p.zfill(2) for p in m.group(2).split(":"))
            if len(mac) == 17:
                out.append((m.group(1), mac.lower(), m.group(3) or ""))
    return out


def read_arp_cache():
    """This computer's ARP cache (read-only; nothing is sent)."""
    try:
        if IS_WINDOWS:
            return parse_arp_windows(run_console(["arp", "-a"], 10).stdout)
        if os.path.exists("/proc/net/arp"):
            with open("/proc/net/arp", encoding="utf-8") as f:
                return parse_proc_arp(f.read())
        r = subprocess.run(["arp", "-an"], capture_output=True, text=True,
                           timeout=10)
        return parse_arp_bsd(r.stdout)
    except (OSError, subprocess.SubprocessError):
        return []


# ---- the opt-in router port-forwarding check (UPnP IGD) ---------------------
UPNP_WAN_SERVICES = ("urn:schemas-upnp-org:service:WANIPConnection:2",
                     "urn:schemas-upnp-org:service:WANIPConnection:1",
                     "urn:schemas-upnp-org:service:WANPPPConnection:1")


def upnp_parse_description(xml_text, base_url):
    """Device description → (service type, control URL) of the router's
    WAN connection service, or None."""
    import xml.etree.ElementTree as ET
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return None
    found = {}
    for el in root.iter():
        if el.tag.endswith("service"):
            st = cu = ""
            for ch in el:
                if ch.tag.endswith("serviceType"):
                    st = (ch.text or "").strip()
                elif ch.tag.endswith("controlURL"):
                    cu = (ch.text or "").strip()
            if st and cu:
                found[st] = cu
    for st in UPNP_WAN_SERVICES:
        if st in found:
            return st, urllib.parse.urljoin(base_url, found[st])
    return None


def upnp_soap_body(service, action, args):
    inner = "".join(f"<{k}>{html.escape(str(v))}</{k}>" for k, v in args)
    return ('<?xml version="1.0"?><s:Envelope xmlns:s="http://schemas.'
            'xmlsoap.org/soap/envelope/" s:encodingStyle="http://schemas.'
            'xmlsoap.org/soap/encoding/"><s:Body>'
            f'<u:{action} xmlns:u="{service}">{inner}</u:{action}>'
            '</s:Body></s:Envelope>').encode()


def upnp_parse_mapping(xml_text):
    import xml.etree.ElementTree as ET
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return None
    out = {}
    for el in root.iter():
        tag = el.tag.rsplit("}", 1)[-1]
        if tag.startswith("New"):
            out[tag[3:]] = (el.text or "").strip()
    return out or None


def upnp_audit(gateway_ip, timeout=3.0, port=1900, max_entries=64,
               allowed_hosts=None):
    """Ask the router which ports it forwards from the Internet. Sends:
    one discovery message to the router itself, one request for its
    description, then one request per forwarding rule. Only talks to the
    router's own address. → dict with mappings, or {"error": …}."""
    allowed = set(allowed_hosts or ()) | {gateway_ip}
    s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
    s.settimeout(timeout)
    msg = ("M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\n"
           'MAN: "ssdp:discover"\r\nMX: 2\r\n'
           "ST: urn:schemas-upnp-org:device:InternetGatewayDevice:1\r\n\r\n")
    location = ""
    try:
        outbound("upnp", "ssdp", f"{gateway_ip}:{port}",
                 "is there an Internet gateway here?")
        s.sendto(msg.encode(), (gateway_ip, port))
        t_end = time.time() + timeout
        while time.time() < t_end and not location:
            try:
                data, addr = s.recvfrom(4096)
            except _socket.timeout:
                break
            if addr[0] not in allowed:
                continue
            m = re.search(rb"(?im)^location:\s*(\S+)", data)
            if m:
                location = m.group(1).decode("ascii", "ignore")
    except OutboundBlocked as e:
        return {"error": str(e)}
    except OSError as e:
        return {"error": f"The router didn't answer ({e})."}
    finally:
        s.close()
    if not location:
        return {"error": "The router didn't answer the UPnP question — "
                         "UPnP is probably off, which is the safer "
                         "setting.", "upnp": False}
    host = urllib.parse.urlsplit(location).hostname or ""
    if host not in allowed:
        return {"error": f"The answer pointed to {host}, not your router, so "
                         f"I didn't follow it."}
    try:
        req = urllib.request.Request(location,
                                     headers={"User-Agent": APP_NAME})
        with net_urlopen("upnp", req, timeout, "device description") as r:
            desc = r.read(262144).decode("utf-8", "replace")
    except OSError as e:
        return {"error": f"Couldn't read the router's description ({e})."}
    svc = upnp_parse_description(desc, location)
    if not svc:
        return {"error": "The router speaks UPnP but offers no port "
                         "forwarding service.", "upnp": True, "mappings": []}
    service, control = svc
    if (urllib.parse.urlsplit(control).hostname or "") not in allowed:
        return {"error": "The router's control address isn't on your "
                         "router, so I stopped."}
    mappings = []
    for i in range(max_entries):
        body = upnp_soap_body(service, "GetGenericPortMappingEntry",
                              [("NewPortMappingIndex", i)])
        req = urllib.request.Request(control, data=body, headers={
            "User-Agent": APP_NAME,
            "Content-Type": 'text/xml; charset="utf-8"',
            "SOAPAction": f'"{service}#GetGenericPortMappingEntry"'})
        try:
            with net_urlopen("upnp", req, timeout,
                             f"forwarding rule #{i}") as r:
                text = r.read(65536).decode("utf-8", "replace")
        except urllib.error.HTTPError:
            break                     # 713 SpecifiedArrayIndexInvalid: done
        except OSError as e:
            if not mappings:
                return {"error": f"The router refused the question ({e}).",
                        "upnp": True, "mappings": []}
            break
        mp = upnp_parse_mapping(text)
        if not mp:
            break
        mappings.append(mp)
    return {"upnp": True, "service": service, "mappings": mappings,
            "location": location}



# ============================================================================
#  9d.  Connected helpers (optional, for power users): Pi-hole and AdGuard
#       Home. Read-only: MiniWireshark only ASKS them for their query log
#       and device names. What they say is "Reported" evidence — shown
#       beside what was observed on the wire, never added to it.
# ============================================================================
class CredentialVault:
    """Where connector passwords live: Windows DPAPI, the macOS Keychain,
    the Linux Secret Service (secret-tool), or — when none exists — a file
    only your user account can read. Never in settings, logs or bundles."""

    SERVICE = "MiniWireshark"

    def __init__(self, path=None):
        self.path = path or os.path.join(PATHS.data, "vault.json")
        self.backend = self._pick()

    def _pick(self):
        if IS_WINDOWS:
            return "dpapi"
        if sys.platform == "darwin" and shutil.which("security"):
            return "keychain"
        if shutil.which("secret-tool") and os.environ.get(
                "DBUS_SESSION_BUS_ADDRESS"):
            return "secret-service"
        return "file"

    def describe(self):
        return {"dpapi": "Windows data protection (only your account can "
                         "unlock it)",
                "keychain": "the macOS Keychain",
                "secret-service": "your desktop's keyring",
                "file": "a private file only your user account can read "
                        "(this system has no keyring)"}[self.backend]

    def _file(self):
        d = read_json(self.path, {}) or {}
        return d if isinstance(d, dict) else {}

    def _write_file(self, d):
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        atomic_write_json(self.path, d)
        with contextlib.suppress(OSError):
            os.chmod(self.path, 0o600)

    @staticmethod
    def _dpapi(data, protect=True):
        import ctypes.wintypes as wt

        class BLOB(ctypes.Structure):
            _fields_ = [("cbData", wt.DWORD),
                        ("pbData", ctypes.POINTER(ctypes.c_char))]
        buf = ctypes.create_string_buffer(data, len(data))
        inp = BLOB(len(data), ctypes.cast(buf, ctypes.POINTER(
            ctypes.c_char)))
        out = BLOB()
        fn = ctypes.windll.crypt32.CryptProtectData if protect else \
            ctypes.windll.crypt32.CryptUnprotectData
        ok = fn(ctypes.byref(inp), None, None, None, None, 0,
                ctypes.byref(out))
        if not ok:
            raise OSError("Windows data protection refused")
        try:
            return ctypes.string_at(out.pbData, out.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(out.pbData)

    def set(self, cid, secret):
        register_secret(secret)
        if self.backend == "keychain" and _keychain_quotable(secret) and \
                _keychain_quotable(cid):
            # 5.2.3 (C-01): the command goes to `security -i` on stdin; on
            # the command line any local program could read the secret
            # from the process list while it ran
            cmd = "add-generic-password -U -a {} -s {} -w {}\n".format(
                _keychain_quote(cid), _keychain_quote(self.SERVICE),
                _keychain_quote(secret))
            r = subprocess.run(["security", "-i"], input=cmd.encode(),
                               capture_output=True, timeout=20)
            if r.returncode == 0 and b"error" not in r.stderr.lower():
                # `security -i` can exit 0 when the command inside failed
                # (locked keychain): confirm the item exists (no -w, so
                # the secret is never printed)
                chk = subprocess.run(["security", "find-generic-password",
                                      "-a", cid, "-s", self.SERVICE],
                                     capture_output=True, timeout=20)
                if chk.returncode == 0:
                    return True
        elif self.backend == "secret-service":
            r = subprocess.run(["secret-tool", "store", "--label",
                                f"{self.SERVICE} {cid}", "service",
                                self.SERVICE, "account", cid],
                               input=secret.encode(), capture_output=True,
                               timeout=20)
            if r.returncode == 0:
                return True
        d = self._file()
        if self.backend == "dpapi":
            d[cid] = {"dpapi": base64.b64encode(self._dpapi(
                secret.encode())).decode()}
        else:
            d[cid] = {"plain": base64.b64encode(secret.encode()).decode()}
        self._write_file(d)
        return True

    def get(self, cid):
        val = None
        try:
            if self.backend == "keychain":
                r = subprocess.run(["security", "find-generic-password",
                                    "-a", cid, "-s", self.SERVICE, "-w"],
                                   capture_output=True, text=True,
                                   timeout=20)
                if r.returncode == 0:
                    val = _one_line_end(r.stdout)
            elif self.backend == "secret-service":
                r = subprocess.run(["secret-tool", "lookup", "service",
                                    self.SERVICE, "account", cid],
                                   capture_output=True, text=True,
                                   timeout=20)
                if r.returncode == 0 and r.stdout:
                    val = _one_line_end(r.stdout)
            if val is None:
                ent = self._file().get(cid) or {}
                if "dpapi" in ent and IS_WINDOWS:
                    val = self._dpapi(base64.b64decode(ent["dpapi"]),
                                      protect=False).decode()
                elif "plain" in ent:
                    val = base64.b64decode(ent["plain"]).decode()
        except (OSError, ValueError, subprocess.SubprocessError):
            val = None
        if val:
            register_secret(val)
        return val

    def delete(self, cid):
        with contextlib.suppress(OSError, subprocess.SubprocessError):
            if self.backend == "keychain":
                subprocess.run(["security", "delete-generic-password", "-a",
                                cid, "-s", self.SERVICE], capture_output=True,
                               timeout=20)
            elif self.backend == "secret-service":
                subprocess.run(["secret-tool", "clear", "service",
                                self.SERVICE, "account", cid],
                               capture_output=True, timeout=20)
        d = self._file()
        if d.pop(cid, None) is not None:
            self._write_file(d)


class ConnectorError(Exception):
    def __init__(self, kind, message):
        super().__init__(message)
        self.kind = kind          # auth | tls | network | api | refused


def connector_http(method, url, headers=None, body=None, pin="",
                   verify=True, timeout=10.0):
    """One HTTP(S) request to a helper on your network, through the
    outbound gate. `pin` = the SHA-256 of a self-signed certificate you
    accepted. → (status, headers dict, body bytes)."""
    import http.client
    import ssl
    parts = urllib.parse.urlsplit(url)
    host, port = parts.hostname or "", parts.port
    path = (parts.path or "/") + (("?" + parts.query) if parts.query
                                  else "")
    try:
        outbound("connector", parts.scheme,
                 f"{host}:{port or ''}".rstrip(":"),
                 f"{method} {parts.path or '/'}")
    except OutboundBlocked as e:
        raise ConnectorError("refused", str(e))
    try:
        if parts.scheme == "https":
            ctx = ssl.create_default_context()
            if pin or not verify:
                ctx.check_hostname = False
                ctx.verify_mode = ssl.CERT_NONE
            conn = http.client.HTTPSConnection(host, port or 443,
                                               timeout=timeout, context=ctx)
        else:
            conn = http.client.HTTPConnection(host, port or 80,
                                              timeout=timeout)
        # 5.3.4 (RT-04): the pin is checked right after the handshake,
        # before a byte of the request (the helper's password) is sent
        if parts.scheme == "https" and pin:
            conn.connect()
            der = conn.sock.getpeercert(binary_form=True) or b""
            if hashlib.sha256(der).hexdigest() != pin.lower():
                conn.close()
                raise ConnectorError("tls", "The helper's certificate "
                                            "changed since you accepted it.")
        conn.request(method, path, body=body, headers=dict(
            {"User-Agent": APP_NAME, "Accept": "application/json"},
            **(headers or {})))
        resp = conn.getresponse()
        data = resp.read(16 * 1024 * 1024)
        hdrs = {k.lower(): v for k, v in resp.getheaders()}
        conn.close()
        return resp.status, hdrs, data
    except ssl.SSLCertVerificationError as e:
        why = getattr(e, "verify_message", "") or str(e)
        raise ConnectorError("tls", f"The certificate isn't trusted ({why})."
                                    f" If this is your own Pi-hole/AdGuard "
                                    f"with its built-in certificate, choose "
                                    f"“Trust this certificate”.")
    except ConnectorError:
        raise
    except OutboundBlocked as e:
        raise ConnectorError("refused", str(e))
    except (OSError, http.client.HTTPException) as e:
        raise ConnectorError("network", f"Couldn't reach {host}: {e}")


def connector_cert_fingerprint(url, timeout=8.0):
    """SHA-256 of the certificate a helper presents (for “Trust this
    certificate”)."""
    import ssl
    parts = urllib.parse.urlsplit(url)
    outbound("connector", "tls", parts.hostname or "", "read certificate")
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    with _socket.create_connection((parts.hostname, parts.port or 443),
                                   timeout=timeout) as raw:
        with ctx.wrap_socket(raw, server_hostname=parts.hostname) as tls:
            der = tls.getpeercert(binary_form=True) or b""
    return hashlib.sha256(der).hexdigest()


class Connector:
    kind, title = "", ""
    PATH_HINT = ""

    def __init__(self, spec, vault):
        self.spec = dict(spec)
        self.id = spec["id"]
        self.name = spec.get("name") or self.title
        self.url = spec.get("url", "").rstrip("/")
        self.vault = vault
        self.pin = spec.get("pin", "")
        self.verify = bool(spec.get("verify", True))

    def _get(self, path, headers=None, method="GET", body=None):
        st, hd, data = connector_http(method, self.url + path, headers, body,
                                      self.pin, self.verify)
        return st, hd, data

    @staticmethod
    def _json(data):
        try:
            return json.loads(data.decode("utf-8", "replace") or "null")
        except ValueError:
            raise ConnectorError("api", "The helper answered something that "
                                        "isn't JSON — is this the right "
                                        "address?")

    def test(self):
        raise NotImplementedError

    def fetch(self, since, limit=5000):
        raise NotImplementedError

    def close(self):
        pass


class PiHoleConnector(Connector):
    """Pi-hole v6 REST API: POST /api/auth (password or app password) →
    session ID in the X-FTL-SID header; GET /api/queries and
    /api/network/devices; DELETE /api/auth when done."""

    kind, title = "pihole", "Pi-hole"
    PATH_HINT = "http://pi.hole or https://192.168.1.2"

    def __init__(self, spec, vault):
        super().__init__(spec, vault)
        self.sid = ""
        self.sid_until = 0.0

    def _login(self):
        if self.sid and time.time() < self.sid_until - 30:
            return
        pw = self.vault.get(self.id) or ""
        st, _h, data = self._get("/api/auth", {"Content-Type":
                                               "application/json"}, "POST",
                                 json.dumps({"password": pw}).encode())
        if st == 401:
            raise ConnectorError("auth", "Pi-hole refused the password. Use "
                                         "your Pi-hole password or an app "
                                         "password (Settings → Web "
                                         "interface / API).")
        if st == 404:
            raise ConnectorError("api", "No Pi-hole v6 API at this address "
                                        "(Pi-hole 5 isn't supported).")
        if st >= 400:
            raise ConnectorError("api", f"Pi-hole answered HTTP {st}.")
        sess = (self._json(data) or {}).get("session") or {}
        if not sess.get("valid"):
            raise ConnectorError("auth", "Pi-hole didn't accept the "
                                         "password.")
        self.sid = sess.get("sid") or ""
        if self.sid:
            register_secret(self.sid)
        self.sid_until = time.time() + float(sess.get("validity") or 300)

    def _api(self, path):
        self._login()
        hd = {"X-FTL-SID": self.sid} if self.sid else {}
        st, _h, data = self._get(path, hd)
        if st == 401:
            self.sid = ""
            self._login()
            hd = {"X-FTL-SID": self.sid} if self.sid else {}
            st, _h, data = self._get(path, hd)
        if st >= 400:
            raise ConnectorError("api", f"Pi-hole answered HTTP {st} for "
                                        f"{path.split('?')[0]}.")
        return self._json(data)

    def test(self):
        info = self._api("/api/info/version")
        ver = ""
        with contextlib.suppress(AttributeError, TypeError, KeyError):
            ver = info["version"]["core"]["local"]["version"]
        return f"Connected to Pi-hole {ver}".strip()

    def fetch(self, since, limit=5000):
        out = {"lookups": [], "devices": []}
        until = time.time() + 60
        q = self._api(f"/api/queries?from={int(since)}&until={int(until)}"
                      f"&length={int(limit)}")
        for r in (q or {}).get("queries") or []:
            try:
                ts = float(r.get("time") or 0)
                if ts < since:
                    continue          # "from" is whole seconds on the API
                cl = r.get("client") or {}
                status = str(r.get("status") or "")
                rep = r.get("reply") or {}
                ms = rep.get("time")
                out["lookups"].append({
                    "ts": ts, "client": str(cl.get("ip") or ""),
                    "client_name": str(cl.get("name") or ""),
                    "domain": str(r.get("domain") or "").lower().strip("."),
                    "type": str(r.get("type") or ""),
                    "blocked": status in PIHOLE_BLOCKED,
                    "status": status,
                    "ms": float(ms) * 1000.0 if isinstance(
                        ms, (int, float)) and ms < 60 else None})
            except (TypeError, ValueError, AttributeError):
                continue
        d = self._api("/api/network/devices?max_devices=500&"
                      "max_addresses=8")
        for dev in (d or {}).get("devices") or []:
            ips = [(a.get("ip") or "", a.get("name") or "")
                   for a in dev.get("ips") or [] if isinstance(a, dict)]
            out["devices"].append({
                "mac": str(dev.get("hwaddr") or "").lower(),
                "ips": [i for i, _n in ips if i],
                "names": [n for _i, n in ips if n],
                "vendor": dev.get("macVendor") or "",
                "last": float(dev.get("lastQuery") or 0)})
        return out

    def close(self):
        if self.sid:
            with contextlib.suppress(ConnectorError):
                self._get("/api/auth", {"X-FTL-SID": self.sid}, "DELETE")
            self.sid = ""


PIHOLE_BLOCKED = {"GRAVITY", "REGEX", "DENYLIST", "EXTERNAL_BLOCKED_IP",
                  "EXTERNAL_BLOCKED_NULL", "EXTERNAL_BLOCKED_NXRA",
                  "GRAVITY_CNAME", "REGEX_CNAME", "DENYLIST_CNAME",
                  "SPECIAL_DOMAIN", "DBBUSY", "EXTERNAL_BLOCKED_EDE15"}


class AdGuardConnector(Connector):
    """AdGuard Home (/control API, HTTP Basic auth): GET /control/status,
    /control/querylog and /control/clients."""

    kind, title = "adguard", "AdGuard Home"
    PATH_HINT = "http://192.168.1.2:3000 or https://adguard.home"

    def _auth(self):
        user = self.spec.get("username", "")
        pw = self.vault.get(self.id) or ""
        if not user and not pw:
            return {}
        tok = base64.b64encode(f"{user}:{pw}".encode()).decode()
        register_secret(tok)
        return {"Authorization": "Basic " + tok}

    def _api(self, path):
        st, _h, data = self._get("/control" + path, self._auth())
        if st in (401, 403):
            raise ConnectorError("auth", "AdGuard Home refused the user name "
                                         "or password.")
        if st == 404:
            raise ConnectorError("api", "No AdGuard Home API at this "
                                        "address.")
        if st >= 400:
            raise ConnectorError("api", f"AdGuard Home answered HTTP {st}.")
        return self._json(data)

    def test(self):
        st = self._api("/status") or {}
        return f"Connected to AdGuard Home {st.get('version', '')}".strip()

    @staticmethod
    def _ts(text):
        # "2024-05-01T12:00:00.123456789Z" or with an offset
        m = re.match(r"(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d):(\d\d)(\.\d+)?"
                     r"(Z|[+-]\d\d:\d\d)?", str(text or ""))
        if not m:
            return 0.0
        import calendar
        secs = calendar.timegm(tuple(int(m.group(i)) for i in range(1, 7)))
        frac = float("0" + m.group(7)[:7]) if m.group(7) else 0.0
        tz = m.group(8) or "Z"
        if tz != "Z":
            sign = 1 if tz[0] == "+" else -1
            secs -= sign * (int(tz[1:3]) * 3600 + int(tz[4:6]) * 60)
        return secs + frac

    def fetch(self, since, limit=5000):
        out = {"lookups": [], "devices": []}
        older = ""
        while len(out["lookups"]) < limit:
            q = self._api("/querylog?limit=500" + (
                "&older_than=" + urllib.parse.quote(older) if older else ""))
            rows = (q or {}).get("data") or []
            if not rows:
                break
            stop = False
            for r in rows:
                ts = self._ts(r.get("time"))
                if ts and ts < since:
                    stop = True
                    break
                qn = (r.get("question") or {})
                ci = r.get("client_info") or {}
                reason = str(r.get("reason") or "")
                ms = None
                with contextlib.suppress(TypeError, ValueError):
                    ms = float(r.get("elapsedMs"))
                out["lookups"].append({
                    "ts": ts, "client": str(r.get("client") or ""),
                    "client_name": str(ci.get("name") or ""),
                    "domain": str(qn.get("name") or "").lower().strip("."),
                    "type": str(qn.get("type") or ""),
                    "blocked": reason.startswith("Filtered") and
                    "NotFiltered" not in reason,
                    "status": reason, "ms": ms})
            older = (q or {}).get("oldest") or ""
            if stop or not older or len(rows) < 500:
                break
        with contextlib.suppress(ConnectorError):
            cl = self._api("/clients") or {}
            for c in cl.get("clients") or []:
                ids = [str(x) for x in c.get("ids") or []]
                out["devices"].append({
                    "mac": next((x.lower() for x in ids
                                 if re.match(r"^[0-9a-fA-F:]{17}$", x)), ""),
                    "ips": [x for x in ids if ip_obj(x) is not None],
                    "names": [c.get("name")] if c.get("name") else [],
                    "vendor": "", "last": 0.0})
        return out


CONNECTOR_KINDS = {"pihole": PiHoleConnector, "adguard": AdGuardConnector}


class ConnectorManager:
    """Polls each enabled helper in the background (about once a minute)
    and hands the results to the app on the Tk thread."""

    def __init__(self, specs, vault, deliver, interval=60.0):
        self.vault = vault
        self.deliver = deliver
        self.interval = interval
        self.status = {}
        self.conns = {}
        self.cursor = {}
        self._stop = threading.Event()
        self._wake = threading.Event()
        self._thread = None
        self.update(specs)

    def update(self, specs):
        live = {}
        for sp in specs or []:
            cls = CONNECTOR_KINDS.get(sp.get("kind"))
            if cls is None or not sp.get("id"):
                continue
            old = self.conns.get(sp["id"])
            if old is not None and old.spec == sp:
                live[sp["id"]] = old
                continue
            if old is not None:
                old.close()
            live[sp["id"]] = cls(sp, self.vault)
            self.status.setdefault(sp["id"], {"state": "waiting",
                                              "message": "Not asked yet.",
                                              "last_ok": 0.0, "lookups": 0,
                                              "devices": 0})
        for cid, c in self.conns.items():
            if cid not in live:
                c.close()
                self.status.pop(cid, None)
        self.conns = live
        self._wake.set()

    def start(self):
        if self._thread is None or not self._thread.is_alive():
            self._stop.clear()
            self._thread = threading.Thread(target=self._run, daemon=True,
                                            name="connectors")
            self._thread.start()

    def stop(self):
        self._stop.set()
        self._wake.set()
        for c in list(self.conns.values()):
            c.close()

    def poll_now(self):
        self._wake.set()

    def poll_once(self, cid):
        c = self.conns.get(cid)
        if c is None or not c.spec.get("enabled", True):
            return None
        st = self.status.setdefault(cid, {})
        since = self.cursor.get(cid) or (time.time() - 3600)
        try:
            res = c.fetch(since)
            newest = max((x["ts"] for x in res["lookups"]), default=0.0)
            if newest:
                self.cursor[cid] = newest + 0.000001
            total = st.get("lookups", 0) + len(res["lookups"])
            st.update({"state": "ok", "last_ok": time.time(),
                       "message": f"{total} lookups read so far "
                                  f"(+{len(res['lookups'])} just now); "
                                  f"knows {len(res['devices'])} device "
                                  f"name(s).",
                       "lookups": total,
                       "devices": len(res["devices"])})
            self.deliver(c, res)
            return res
        except ConnectorError as e:
            st.update({"state": e.kind, "message": str(e)})
        except Exception as e:                       # noqa: BLE001
            LOG.exception("connector %s", c.name)
            st.update({"state": "api", "message": f"Unexpected answer: "
                                                  f"{type(e).__name__}"})
        return None

    def _run(self):
        while not self._stop.is_set():
            for cid in list(self.conns):
                if self._stop.is_set():
                    break
                if LEDGER.killed:
                    self.status.setdefault(cid, {}).update(
                        {"state": "refused",
                         "message": "Paused by the kill switch."})
                    continue
                self.poll_once(cid)
            self._wake.wait(self.interval)
            self._wake.clear()


# ---- DNS health / intelligence ---------------------------------------------
# Lookup-time buckets (upper edges, ms) for the per-resolver histogram.
DNS_BUCKETS = (10, 25, 50, 100, 250, 500, 1000, float("inf"))
DNS_BUCKET_LABELS = ("<10", "10–25", "25–50", "50–100", "100–250",
                     "250–500", "0.5–1 s", ">1 s")


def dns_bucket(ms):
    for i, edge in enumerate(DNS_BUCKETS):
        if ms < edge:
            return i
    return len(DNS_BUCKETS) - 1


class DnsTracker:
    """Matches DNS queries to responses (latency), counts failures per
    server, tracks which server each device uses, and notices changes.
    Bounded everywhere."""

    def __init__(self):
        self.servers = {}
        self.pending = OrderedDict()
        self.domains = Counter()
        self.device_servers = defaultdict(Counter)
        self.device_last = {}           # dev_key -> (server, since_ts)
        self.recent = deque(maxlen=400)  # (ts, ok)
        self.latencies = deque(maxlen=200)
        self.slow = deque(maxlen=40)
        self.queries = self.responses = self.nxdomain = self.servfail = 0
        self.timeouts = 0
        self.encrypted_seen = Counter()   # provider/method -> count
        self.dot_flows = 0

    def _srv(self, ip):
        s = self.servers.get(ip)
        if s is None:
            s = self.servers[ip] = {"queries": 0, "responses": 0, "nx": 0,
                                    "servfail": 0, "timeouts": 0,
                                    "lat": deque(maxlen=60), "first": 0.0,
                                    "last": 0.0, "clients": set(),
                                    "hist": [0] * len(DNS_BUCKETS)}
        return s

    def on_query(self, ts, client_ip, server_ip, info, dev_key=""):
        self.queries += 1
        s = self._srv(server_ip)
        s["queries"] += 1
        s["first"] = s["first"] or ts
        s["last"] = ts
        if len(s["clients"]) < 200 and dev_key:
            s["clients"].add(dev_key)
        q = (info.get("qname") or "").lower()
        if q:
            self.domains[q] += 1
            if len(self.domains) > 8000:
                self.domains = Counter(dict(self.domains.most_common(4000)))
        key = (client_ip, server_ip, info.get("id"), q)
        self.pending[key] = (ts, dev_key)
        while len(self.pending) > 4096:
            self.pending.popitem(last=False)
        change = None
        if dev_key:
            c = self.device_servers[dev_key]
            c[server_ip] += 1
            last = self.device_last.get(dev_key)
            if last is None:
                self.device_last[dev_key] = (server_ip, ts, 1)
            elif last[0] == server_ip:
                self.device_last[dev_key] = (server_ip, last[1], last[2] + 1)
            else:
                # a change only counts if the old server was well
                # established and the new one is used consistently
                prev_total = c[last[0]]
                if prev_total >= 20 and c[server_ip] >= 10:
                    change = (last[0], server_ip)
                    self.device_last[dev_key] = (server_ip, ts, 1)
        return change

    def on_response(self, ts, client_ip, server_ip, info):
        self.responses += 1
        s = self._srv(server_ip)
        s["responses"] += 1
        s["last"] = ts
        rc = info.get("rcode", 0)
        if rc == 3:
            self.nxdomain += 1
            s["nx"] += 1
        elif rc == 2:
            self.servfail += 1
            s["servfail"] += 1
        key = (client_ip, server_ip, info.get("id"),
               (info.get("qname") or "").lower())
        ent = self.pending.pop(key, None)
        ok = rc in (0, 3)
        self.recent.append((ts, ok))
        if ent is None:
            return None
        ms = max(0.0, (ts - ent[0]) * 1000.0)
        s["lat"].append(ms)
        s["hist"][dns_bucket(ms)] += 1
        self.latencies.append((ts, ms))
        if ms > 1000:
            self.slow.append((info.get("qname", ""), ms, ts, server_ip))
        return ms

    def expire(self, now, timeout=5.0):
        n = 0
        for key in list(self.pending)[:2048]:
            ts, _dk = self.pending[key]
            if now - ts > timeout:
                self.pending.pop(key, None)
                srv = self.servers.get(key[1])
                if srv:
                    srv["timeouts"] += 1
                self.timeouts += 1
                self.recent.append((ts, False))
                n += 1
            else:
                break
        return n

    def failure_rate(self, now, window=300):
        rows = [ok for ts, ok in self.recent if now - ts <= window]
        if not rows:
            return 0.0, 0
        return 1.0 - (sum(rows) / len(rows)), len(rows)

    def median_latency(self, now=None, window=300):
        vals = [ms for ts, ms in self.latencies
                if now is None or now - ts <= window]
        return (statistics.median(vals), len(vals)) if vals else (None, 0)

    def histogram(self, server=None):
        """Lookup-time counts per DNS_BUCKETS (all servers or one)."""
        out = [0] * len(DNS_BUCKETS)
        for ip, s in self.servers.items():
            if server and ip != server:
                continue
            for i, n in enumerate(s.get("hist") or ()):
                out[i] += n
        return out

    def summary_rows(self):
        out = []
        for ip, s in sorted(self.servers.items(),
                            key=lambda kv: -kv[1]["queries"]):
            lat = statistics.median(s["lat"]) if s["lat"] else None
            out.append((ip, s["queries"], s["responses"], s["nx"],
                        s["servfail"] + s["timeouts"], lat))
        return out

    def to_dict(self):
        return {"servers": {ip: {k: (list(v) if isinstance(v, (deque, set))
                                     else v) for k, v in s.items()}
                            for ip, s in list(self.servers.items())[:50]},
                "top_domains": self.domains.most_common(100),
                "queries": self.queries, "responses": self.responses,
                "nxdomain": self.nxdomain, "servfail": self.servfail,
                "timeouts": self.timeouts,
                "encrypted": dict(self.encrypted_seen)}

    def load(self, d):
        if not isinstance(d, dict):
            return
        for k in ("queries", "responses", "nxdomain", "servfail",
                  "timeouts"):
            setattr(self, k, int(d.get(k, 0) or 0))
        for ip, s in (d.get("servers") or {}).items():
            srv = self._srv(ip)
            for k in ("queries", "responses", "nx", "servfail", "timeouts"):
                srv[k] = int(s.get(k, 0) or 0)
            srv["lat"].extend(float(x) for x in (s.get("lat") or [])[-60:])
            srv["first"] = float(s.get("first") or 0)
            srv["last"] = float(s.get("last") or 0)
            hist = s.get("hist") or []
            if isinstance(hist, list) and len(hist) == len(DNS_BUCKETS):
                srv["hist"] = [int(x or 0) for x in hist]
        for item in d.get("top_domains") or []:
            if isinstance(item, (list, tuple)) and len(item) == 2 and \
                    isinstance(item[0], str):
                self.domains[item[0]] = int(_finite(item[1]))
        self.encrypted_seen.update(_num_map(d.get("encrypted")))


# ---- per-device behavioral baseline -----------------------------------------
class DeviceBaseline:
    """Lightweight statistics (no ML): exponentially-weighted mean/variance
    of per-minute features over this device's ACTIVE minutes, plus its
    usual hours, protocols, services and countries."""

    FEATURES = ("packets", "bytes_up", "bytes_down", "destinations",
                "dns", "new_conns")
    ALPHA = 0.05

    def __init__(self):
        self.n = 0
        self.mean = {f: 0.0 for f in self.FEATURES}
        self.var = {f: 0.0 for f in self.FEATURES}
        self.hours = [0] * 24
        self.protocols = Counter()
        self.services = Counter()
        self.countries = set()
        self.cur_min = None
        self.cur = None
        self.cur_dests = set()

    def _reset_cur(self, minute):
        self.cur_min = minute
        self.cur = {f: 0 for f in self.FEATURES}
        self.cur_dests = set()

    def observe(self, ts, nbytes, direction, remote_ip="", is_dns=False,
                proto="", service_port=None, new_conn=False):
        minute = int(ts // 60)
        finished = None
        if self.cur_min is None:
            self._reset_cur(minute)
        elif minute != self.cur_min:
            finished = self.finish()
            self._reset_cur(minute)
        c = self.cur
        if direction == "sent":
            c["packets"] += 1
            c["bytes_up"] += nbytes
        else:
            c["bytes_down"] += nbytes
        if remote_ip and len(self.cur_dests) < 5000:
            self.cur_dests.add(remote_ip)
        if is_dns:
            c["dns"] += 1
        if new_conn:
            c["new_conns"] += 1
        if proto and len(self.protocols) < 40:
            self.protocols[proto] += 1
        elif proto in self.protocols:
            self.protocols[proto] += 1
        if service_port and (len(self.services) < 40 or
                             service_port in self.services):
            self.services[service_port] += 1
        return finished

    def finish(self):
        """Close the current minute: returns (values, mean, std, n) BEFORE
        updating, so the caller can compare against the old baseline."""
        if self.cur is None:
            return None
        vals = dict(self.cur)
        vals["destinations"] = len(self.cur_dests)
        snapshot = (vals, dict(self.mean),
                    {f: math.sqrt(max(0.0, self.var[f]))
                     for f in self.FEATURES}, self.n)
        self.n += 1
        a = max(self.ALPHA, 1.0 / self.n)
        for f in self.FEATURES:
            x = vals[f]
            diff = x - self.mean[f]
            self.mean[f] += a * diff
            self.var[f] = (1 - a) * (self.var[f] + a * diff * diff)
        with contextlib.suppress(ValueError, OverflowError, OSError):
            self.hours[time.localtime(self.cur_min * 60).tm_hour] += 1
        self.cur = None
        return snapshot

    def to_dict(self):
        return {"n": self.n, "mean": self.mean, "var": self.var,
                "hours": self.hours,
                "protocols": dict(self.protocols.most_common(20)),
                "services": {str(k): v for k, v in
                             self.services.most_common(20)},
                "countries": sorted(self.countries)[:60]}

    @classmethod
    def from_dict(cls, d):
        b = cls()
        with contextlib.suppress(TypeError, ValueError, AttributeError):
            b.n = int(d.get("n", 0))
            for f in cls.FEATURES:
                b.mean[f] = float((d.get("mean") or {}).get(f, 0.0))
                b.var[f] = float((d.get("var") or {}).get(f, 0.0))
            hrs = d.get("hours") or []
            if len(hrs) == 24:
                b.hours = [int(x) for x in hrs]
            b.protocols = _num_map(d.get("protocols"))
            b.services = Counter({int(k): v for k, v in
                                  _num_map(d.get("services")).items()
                                  if str(k).isdigit()})
            b.countries = _str_set(d.get("countries") or [])
        return b

    def usual_hours_text(self):
        if self.n < 30:
            return "still learning"
        top = sorted(range(24), key=lambda h: -self.hours[h])[:4]
        return ", ".join(f"{h:02d}:00" for h in sorted(top))


class BaselineEngine:
    # minimum absolute values per minute before anything is called unusual
    FLOORS = {"bytes_up": 5 * 1024 * 1024, "bytes_down": 50 * 1024 * 1024,
              "destinations": 40, "new_conns": 80}

    def __init__(self, config):
        self.config = config
        self.devices = {}

    def get(self, key):
        b = self.devices.get(key)
        if b is None:
            b = self.devices[key] = DeviceBaseline()
        return b

    def check(self, snapshot):
        """Return [(feature, value, mean)] that look unusual for this
        device. Requires enough history and a big deviation in BOTH ratio
        and standard deviations, plus an absolute floor."""
        if not snapshot:
            return []
        vals, mean, std, n = snapshot
        need = int(self.config.get("alerts.baseline_min_minutes", 15))
        if n < need:
            return []
        mult = float(self.config.get("alerts.chatty_multiplier", 4))
        out = []
        for f, floor in self.FLOORS.items():
            v, m, s = vals.get(f, 0), mean.get(f, 0.0), std.get(f, 0.0)
            if v >= floor and v > m * mult and v > m + 4 * max(s, 1.0):
                out.append((f, v, m))
        return out

    def reset(self):
        self.devices.clear()

    def to_dict(self):
        return {k: b.to_dict() for k, b in list(self.devices.items())[:500]}

    def load(self, d):
        for k, bd in (d or {}).items():
            if isinstance(bd, dict):
                self.devices[k] = DeviceBaseline.from_dict(bd)


class ScanTracker:
    """Per-device sliding minute of connection attempts, to notice
    scanning-like behaviour (many distinct targets, few replies)."""

    def __init__(self):
        self.attempts = defaultdict(deque)   # dev -> (ts, target, port)
        self.replied = defaultdict(set)      # dev -> {(target, port)}

    def attempt(self, dev_key, ts, target, port):
        dq = self.attempts[dev_key]
        dq.append((ts, target, port))
        while dq and ts - dq[0][0] > 60:
            dq.popleft()
        if len(dq) > 3000:
            dq.popleft()

    def reply(self, dev_key, target, port):
        s = self.replied[dev_key]
        s.add((target, port))
        if len(s) > 5000:
            s.clear()

    def evaluate(self, dev_key, port_threshold, host_threshold):
        dq = self.attempts.get(dev_key)
        if not dq:
            return None
        rep = self.replied.get(dev_key, set())
        per_host = defaultdict(set)
        per_port = defaultdict(set)
        for _ts, tgt, port in dq:
            if (tgt, port) in rep:
                continue
            per_host[tgt].add(port)
            per_port[port].add(tgt)
        if per_host:
            tgt, ports = max(per_host.items(), key=lambda kv: len(kv[1]))
            if len(ports) >= port_threshold:
                return (f"different ports on {tgt}", len(ports))
        if per_port:
            port, hosts = max(per_port.items(), key=lambda kv: len(kv[1]))
            if len(hosts) >= host_threshold:
                return (f"different hosts on port {port}", len(hosts))
        return None

    def forget(self, dev_key):
        self.attempts.pop(dev_key, None)
        self.replied.pop(dev_key, None)


# ============================================================================
#  12b.  Evidence levels, observations and lookup correlation
#
#  Observations are facts with a source, a time and (when it came from a
#  packet) the packet number; they are never edited. Everything a view
#  shows is a CLAIM built from them and carries one of five levels:
#
#     ◉ Observed    seen directly in a packet from this device
#     ◈ Reported    told to us by another system (router, Pi-hole…)
#     ◎ Correlated  two separate observations line up (lookup → connect)
#     ◌ Inferred    a reasonable guess with counter-explanations
#     ?  Unknown    nothing either way — never shown as "no"
# ============================================================================
LV_OBSERVED, LV_REPORTED, LV_CORRELATED, LV_INFERRED, LV_UNKNOWN = \
    "observed", "reported", "correlated", "inferred", "unknown"
LEVEL_GLYPH = {LV_OBSERVED: "◉", LV_REPORTED: "◈", LV_CORRELATED: "◎",
               LV_INFERRED: "◌", LV_UNKNOWN: "?"}
LEVEL_WORD = {LV_OBSERVED: "Observed", LV_REPORTED: "Reported",
              LV_CORRELATED: "Correlated", LV_INFERRED: "Inferred",
              LV_UNKNOWN: "Unknown"}
LEVEL_HELP = {
    LV_OBSERVED: "Seen directly in a packet (you can open that packet).",
    LV_REPORTED: "Reported by another system you connected (for example "
                 "your Pi-hole), not seen by this computer itself.",
    LV_CORRELATED: "Two separate observations line up — for example a "
                   "device looked a name up and connected to the answer "
                   "a moment later.",
    LV_INFERRED: "A reasonable guess. It could be wrong; the reasons are "
                 "listed.",
    LV_UNKNOWN: "Nothing seen either way. Not seeing something does not "
                "mean it didn't happen."}


# ---- EXPLAIN (5.1.2 F7): one place for every "what does this mean" ------
# (kind, key) -> (short, long). Used by tooltips, Explain inline, Help and
# search. The self-test fails when an alert type, a device state, a
# confidence word or an evidence level has no entry.
EXPLAIN = {}


def explain(kind, key, long=True):
    e = EXPLAIN.get((kind, key))
    if e is None:
        return ""
    return e[1] if long else e[0]


def _explain_init():
    for lv in (LV_OBSERVED, LV_REPORTED, LV_CORRELATED, LV_INFERRED,
               LV_UNKNOWN):
        EXPLAIN[("level", lv)] = (LEVEL_WORD[lv], LEVEL_HELP[lv])
    EXPLAIN[("confidence", "High")] = (
        "High", "Several independent local signals agree: it sent traffic "
        "of its own and its identity comes from more than one source.")
    EXPLAIN[("confidence", "Medium")] = (
        "Medium", "It sent traffic, but its name or type comes from one "
        "source only.")
    EXPLAIN[("confidence", "Low")] = (
        "Low", "Only a little evidence so far, for example an address seen "
        "in someone else's traffic. More will come as it talks.")
    EXPLAIN[("confidence", "Unconfirmed")] = (
        "Unconfirmed", "Nothing yet proves it is a real device on your "
        "network; it may be a passing address.")
    EXPLAIN[("state", "ACTIVE")] = (
        "Active", "Sent something in the last few minutes.")
    EXPLAIN[("state", "IDLE")] = (
        "Idle", "Still here, but quiet for a couple of minutes (phones and "
        "smart devices sleep a lot).")
    EXPLAIN[("state", "INACTIVE")] = (
        "Offline", "Not heard from for a while. It may be switched off, "
        "asleep, or out of range.")
    EXPLAIN[("state", "EXPIRED")] = (
        "Expired", "Not seen for a long time; kept so you can see its "
        "history.")


_explain_init()
_explain_alerts()


def level_label(level, word=True):
    g = LEVEL_GLYPH.get(level, "?")
    return f"{g} {LEVEL_WORD.get(level, 'Unknown')}" if word else g


