def device_name_source(dev):
    if dev.alias:
        return "user"
    if dev.dhcp_hostname:
        return "dhcp"
    if dev.mdns_name:
        return "mdns"
    if dev.hostname and dev.hostname_source in ("nbns", "rdns", "mdns",
                                                "dhcp", "connector"):
        return dev.hostname_source
    if dev.ssdp_name:
        return "ssdp"
    if dev.vendor or dev.device_class != "Unknown":
        return "vendor"
    return ""


