def _initial_ttl(ttl):
    if ttl <= 0:
        return 0
    if ttl <= 64:
        return 64
    if ttl <= 128:
        return 128
    return 255


class NetworkModel:
    DISCOVERY_SECONDS = 8

    def __init__(self, config, gateway_ip="", my_ips=(), my_macs=(),
                 now_fn=None):
        self.config = config
        self._clock = now_fn
        self.use_packet_clock = False
        self.offline_now = 0.0
        self.gateway_ip = gateway_ip
        self.my_ips = set(my_ips)
        self.my_macs = {m.lower() for m in my_macs if m}
        self.local_nets = []
        self.v6_prefixes = []
        self.cache = NameCache()
        self.registry = DeviceRegistry(gateway_ip, self.my_ips, config,
                                       self.now)
        self.registry.my_macs = self.my_macs
        self.alerts = AlertEngine(config, self.now)
        self.flows = FlowTable(config.get("connections.max_active", 5000),
                               config.get("connections.archive_size", 2000))
        self.metrics = MetricsEngine()
        self.dns = DnsTracker()
        self.baselines = BaselineEngine(config)
        self.scans = ScanTracker()
        self.websites = {}
        self._seen_roots = None          # registrable domains seen (B-24)
        self.remote_hosts = {}
        self.ip_to_domains = {}
        self.timeline = deque(maxlen=3000)
        self.count = 0
        self.dhcp_servers = defaultdict(int)
        self.dhcp_routers = Counter()
        self.dhcp_dns = set()
        self.doh_seen = defaultdict(set)
        self.http_count = 0
        self.http_hosts = Counter()
        self.cleartext_seen = Counter()
        self.bcast_talkers = deque(maxlen=5000)
        self.gw_mac_traffic = Counter()
        self.vpn_bytes = Counter()
        self.vpn = {"iface": "", "endpoint": "", "kind": ""}
        self.resets = defaultdict(deque)
        self.own_probe_targets = {}
        self.health = {}
        self.health_history = deque(maxlen=120)
        self.capture_started = 0.0
        self.epochs = []    # [start, end|None, why started, why ended]
        self.announce_new = True
        self.demo = False
        self._spoof_warned = False
        self._cache_version = -1
        self._classify_dirty = set()
        self._pending_new = []
        # outboxes drained by the GUI
        self.ev_feed = []
        self.ev_timeline = []
        self.ev_alerts = []
        self.ev_banner = []
        self.ev_geo = set()
        self.dirty_devices = set()
        self.dirty_websites = set()
        self.dirty_remotes = set()
        # evidence (section 12b)
        self.correlator = LookupCorrelator()
        self.obs_seq = 0
        self.obs_recent = deque(maxlen=20000)
        self.switch_ports = {}       # (proto, chassis) → what LLDP/CDP said
        self.reported = {}           # helper name → what it reported
        self.flow_starts = OrderedDict()   # (device, remote) → start times
        self.rtt_samples = deque(maxlen=2000)  # (ts, rtt, remote, dev, fid)
        self.obs_by_subject = {}
        self.obs_sink = False          # a history store wants observations
        self.obs_pending = []
        self.res_pending = []
        self.tl_pending = []
        self.tie_pending = set()
        self._pkt_no = None
        self.journal = CorrectionJournal()
        self.network_id = ""
        self.vantage = VantageMeter()

    # ---- evidence ------------------------------------------------------------
    def observe(self, kind, subject, ts, data=None, pkt=None, also=()):
        """Record one immutable observation. `pkt` is the packet number
        that proves it (None for observations not from a packet)."""
        if not subject:
            return None
        if pkt is None:
            pkt = self._pkt_no
        self.obs_seq += 1
        o = (self.obs_seq, ts, kind, subject, data or {}, pkt)
        self.obs_recent.append(o)
        for subj in (subject,) + tuple(also):
            dq = self.obs_by_subject.get(subj)
            if dq is None:
                if len(self.obs_by_subject) > 60000:
                    for k in list(self.obs_by_subject)[:6000]:
                        self.obs_by_subject.pop(k, None)
                dq = self.obs_by_subject[subj] = deque(maxlen=48)
            dq.append(o)
        if self.obs_sink:
            self.obs_pending.append(o)
            if len(self.obs_pending) > 200000:
                del self.obs_pending[:50000]
        return o

    def observations_for(self, subject, kinds=None, limit=48):
        out = [o for o in self.obs_by_subject.get(subject, ())
               if kinds is None or o[2] in kinds]
        return out[-limit:]

    def apply_reported(self, source, res):
        """Fold what a connected helper reported into the model, as
        Reported evidence beside (never added to) what was observed."""
        reg = self.registry
        rep = self.reported.get(source)
        if rep is None:
            rep = self.reported[source] = {
                "lookups": 0, "blocked": 0, "devices": set(),
                "unseen_clients": set(), "named": 0, "last": 0.0,
                "domains": Counter(), "first": 0.0}
        for d in res.get("devices") or []:
            names = [n for n in d.get("names") or [] if n]
            if not names:
                continue
            for ip in d.get("ips") or []:
                if reg.set_hostname(ip, sanitize_text(names[0], 63),
                                    "connector"):
                    rep["named"] += 1
                    break
        for lk in res.get("lookups") or []:
            dom, ip, ts = lk.get("domain", ""), lk.get("client", ""), \
                float(lk.get("ts") or 0)
            if not dom or "." not in dom or not ts:
                continue
            dom = sanitize_text(dom, 253).lower()
            rep["lookups"] += 1
            rep["last"] = max(rep["last"], ts)
            rep["first"] = min(rep["first"] or ts, ts)
            rep["domains"][registrable_domain(dom)] += 1
            if len(rep["domains"]) > 5000:
                rep["domains"] = Counter(dict(rep["domains"].most_common(
                    2500)))
            key = reg.ip_to_key.get(ip)
            dev = reg.by_key.get(reg.resolve(key)) if key else None
            if dev is None:
                if len(rep["unseen_clients"]) < 500 and ip:
                    rep["unseen_clients"].add(ip)
                continue
            rep["devices"].add(dev.key)
            blocked = bool(lk.get("blocked"))
            if blocked:
                rep["blocked"] += 1
            else:
                self.register_website(dom, None, dev, source, ts,
                                      reported=True)
                self.tie(dev.key, dom, AS_REPORTED, ts)
            self.observe("reported", dev.key, ts,
                         {"domain": dom, "source": source,
                          "blocked": blocked},
                         also=() if blocked else ("site:" + dom,))
        return rep

    def tie(self, device, domain, assoc, ts):
        """Tie a device to a website at the strongest level seen so far."""
        if not device or not domain:
            return
        rec = self.websites.get(domain)
        if rec is None:
            return
        t = rec.ties.get(device)
        if t is None:
            if len(rec.ties) >= 400:
                return
            rec.ties[device] = [assoc, ts, ts, 1]
        else:
            t[0] = better_assoc(assoc, t[0])
            t[2] = max(t[2], ts)
            t[3] += 1
        if self.obs_sink:
            self.tie_pending.add((device, domain))
        self.dirty_websites.add(domain)

    # ---- user corrections (undoable) ---------------------------------------
    def _dev(self, key):
        return self.registry.by_key.get(self.registry.resolve(key))

    def correct_rename(self, key, name):
        dev = self._dev(key)
        if dev is None:
            return []
        name = sanitize_text(name or "", 60).strip()
        if name == dev.alias:
            return []
        self._journal("rename", {"key": dev.key, "old": dev.alias,
                                    "new": name})
        dev.alias = name
        if name:
            _push_bounded(dev.hostname_history, [name, "user", self.now()],
                          20)
        self._dirty_dev(dev)
        return [dev.key]

    def correct_flag(self, key, flag, value=None):
        dev = self._dev(key)
        if dev is None or flag not in ("mine", "expected", "pinned_no_merge"):
            return []
        old = bool(getattr(dev, flag))
        new = (not old) if value is None else bool(value)
        if new == old:
            return []
        self._journal("flag", {"key": dev.key, "flag": flag, "old": old,
                                  "new": new})
        setattr(dev, flag, new)
        self._dirty_dev(dev)
        return [dev.key]

    def correct_type(self, key, cls):
        """You say what a device is ("" = let MiniWireshark decide). The
        device's fingerprint is remembered so look-alikes get a
        suggestion."""
        dev = self._dev(key)
        if dev is None or (cls and cls not in DEVICE_CLASSES):
            return []
        if cls == dev.user_class:
            return []
        self._journal("type", {"key": dev.key, "old": dev.user_class,
                                  "new": cls})
        dev.user_class = cls
        if not getattr(self, "demo", False) and dev.live and not dev.demo:
            if cls:
                learned_types().learn(dev, cls)
            else:
                learned_types().forget(dev.key)
        self._classify_dirty.update(self.registry.by_key)  # look-alikes too
        self._classify()
        self._dirty_dev(dev)
        return [dev.key]

    def correct_note(self, key, note):
        dev = self._dev(key)
        if dev is None:
            return []
        note = sanitize_text(note or "", 2000)
        if note == dev.notes:
            return []
        self._journal("note", {"key": dev.key, "old": dev.notes,
                                  "new": note})
        dev.notes = note
        return [dev.key]

    def _journal(self, op, payload):
        """A correction: kept for Undo, and said on the timeline."""
        e = self.journal.add(op, payload)
        key = payload.get("key") or payload.get("a") or ""
        name = (lambda k: (self._dev(k).display_name() if self._dev(k)
                           else str(k).replace("ip:", "")))
        with contextlib.suppress(Exception):
            self.push_timeline("website" if op == "category" else
                               "identity", "INFO",
                               self.journal.you_text(e, name),
                               ("website", payload["domain"])
                               if op == "category" else ("device", key),
                               key)
        return e

    def correct_tags(self, key, place, owner):
        """Where a device is and whose it is (short words, yours)."""
        dev = self._dev(key)
        if dev is None:
            return []
        place = sanitize_text(place or "", 40).strip()
        owner = sanitize_text(owner or "", 40).strip()
        if (place, owner) == (dev.place, dev.owner):
            return []
        self._journal("tag", {"key": dev.key, "old": [dev.place, dev.owner],
                              "new": [place, owner]})
        dev.place, dev.owner = place, owner
        self._dirty_dev(dev)
        return [dev.key]

    def correct_category(self, domain, cat):
        """You say what kind of site a domain is ("" = let MiniWireshark
        decide, "-" = no category). Kept by registrable domain."""
        reg = registrable_domain(domain)
        if not reg or (cat and cat != "-" and
                       cat not in WEBSITE_CATEGORIES):
            return []
        old = CATEGORY_OVERRIDES.get(reg, "")
        if cat == old:
            return []
        self._journal("category", {"domain": reg, "old": old, "new": cat})
        self._set_category(reg, cat)
        return [reg]

    def _set_category(self, reg, cat):
        if cat:
            CATEGORY_OVERRIDES[reg] = cat
        else:
            CATEGORY_OVERRIDES.pop(reg, None)
        with contextlib.suppress(Exception):
            self.config.set("websites.category_overrides",
                            dict(CATEGORY_OVERRIDES))
        for w in list(self.websites.values()):
            if w.registrable != reg and w.domain != reg:
                continue
            c, src = domain_category(w.domain)
            if category_shown(c, src, self.config):
                w.category, w.category_source = c, src
            else:
                w.category = w.category_source = ""
            self.dirty_websites.add(w.domain)

    def correct_merge(self, keep, other, reason="you merged them"):
        reg = self.registry
        keep, other = reg.resolve(keep), reg.resolve(other)
        k = reg.merge(keep, other, auto=False, reason=reason)
        if k is None:
            return []
        self.journal.add("merge", {"keep": k.key, "other": other})
        self.dirty_devices.add(k.key)
        self._classify_dirty.add(k.key)
        self.push_timeline("identity merged", "INFO",
                           f"{k.display_name()}: two identities combined "
                           f"(by you)", ("device", k.key), k.key)
        return [k.key]

    def correct_split(self, keep, index):
        reg = self.registry
        keep = reg.resolve(keep)
        dev = reg.by_key.get(keep)
        if dev is None or not (0 <= index < len(dev.merge_history)):
            return []
        restored = reg.split(keep, index)
        if restored is None:
            return []
        self.journal.add("split", {"keep": keep, "restored": restored.key})
        return self._after_split(keep, restored)

    def _after_split(self, keep, restored):
        self.dirty_devices |= {keep, restored.key}
        self._classify_dirty |= {keep, restored.key}
        self.push_timeline("identity", "INFO",
                           f"Split {restored.display_name()} back out of "
                           f"{self._dev(keep).display_name()}",
                           ("device", keep), keep)
        return [keep, restored.key]

    def correct_never_merge(self, a, b):
        da, db = self._dev(a), self._dev(b)
        if da is None or db is None or da is db:
            return []
        self._journal("never_merge", {"a": da.key, "b": db.key})
        da.never_merge.add(db.key)
        db.never_merge.add(da.key)
        return [da.key, db.key]

    def undo_correction(self, eid=None):
        """Undo one correction (the latest by default). Returns the keys
        of the devices it touched (for saving labels), or []."""
        j = self.journal
        e = j.get(eid) if eid is not None else j.last_undoable()
        if e is None or e["undone"]:
            return []
        p = e["payload"]
        reg = self.registry
        out = []
        if e["op"] == "rename":
            dev = self._dev(p["key"])
            if dev is not None:
                dev.alias = p["old"]
                out = [dev.key]
        elif e["op"] in ("flag",):
            dev = self._dev(p["key"])
            if dev is not None:
                setattr(dev, p["flag"], p["old"])
                out = [dev.key]
        elif e["op"] == "note":
            dev = self._dev(p["key"])
            if dev is not None:
                dev.notes = p["old"]
                out = [dev.key]
        elif e["op"] == "type":
            dev = self._dev(p["key"])
            if dev is not None:
                dev.user_class = p["old"]
                if not getattr(self, "demo", False):
                    if p["old"]:
                        learned_types().learn(dev, p["old"])
                    else:
                        learned_types().forget(dev.key)
                self._classify_dirty.update(self.registry.by_key)
                self._classify()
                out = [dev.key]
        elif e["op"] == "merge":
            keep = reg.resolve(p["keep"])
            dev = reg.by_key.get(keep)
            idx = next((i for i, m in enumerate(dev.merge_history)
                        if m.get("key") == p["other"]), None) \
                if dev is not None else None
            if idx is None:
                return []
            restored = reg.split(keep, idx)
            if restored is None:
                return []
            restored.never_merge.discard(keep)
            dev.never_merge.discard(restored.key)
            out = self._after_split(keep, restored)
        elif e["op"] == "split":
            keep = reg.resolve(p["keep"])
            kd, rd = reg.by_key.get(keep), reg.by_key.get(
                reg.resolve(p["restored"]))
            if kd is None or rd is None:
                return []
            kd.never_merge.discard(rd.key)
            rd.never_merge.discard(kd.key)
            k = reg.merge(kd.key, rd.key, auto=False, reason="undo split")
            if k is None:
                return []
            self.dirty_devices.add(k.key)
            out = [k.key]
        elif e["op"] == "never_merge":
            da, db = self._dev(p["a"]), self._dev(p["b"])
            if da is not None and db is not None:
                da.never_merge.discard(db.key)
                db.never_merge.discard(da.key)
                out = [da.key, db.key]
        elif e["op"] == "tag":
            dev = self._dev(p["key"])
            if dev is not None:
                dev.place, dev.owner = p["old"]
                out = [dev.key]
        elif e["op"] == "category":
            self._set_category(p["domain"], p["old"])
            e["undone"] = True
            with contextlib.suppress(Exception):
                self.push_timeline("website", "INFO",
                                   f"You undid: {self.journal.describe(e)}",
                                   ("website", p["domain"]))
            return []
        e["undone"] = True
        if out:
            with contextlib.suppress(Exception):
                self.push_timeline("identity", "INFO", "You undid: " +
                                   self.journal.describe(
                                       e, lambda k: self._dev(k).display_name()
                                       if self._dev(k) else k),
                                   ("device", out[0]), out[0])
        for k in out:
            self.dirty_devices.add(k)
            self._classify_dirty.add(k)
        return out

    # ---- clock / identity --------------------------------------------------
    def now(self):
        if self.use_packet_clock:
            return self.offline_now or time.time()
        return self._clock() if self._clock else time.time()

    def set_identity(self, gateway_ip=None, my_ips=None, my_macs=None,
                     local_nets=None, v6_prefixes=None):
        if gateway_ip is not None:
            self.gateway_ip = gateway_ip
            self.registry.gateway_ip = gateway_ip
        if my_ips is not None:
            self.my_ips = set(my_ips)
            self.registry.my_ips = self.my_ips
        if my_macs is not None:
            self.my_macs = {m.lower() for m in my_macs if m}
            self.registry.my_macs = self.my_macs
        if local_nets is not None:
            self.local_nets = list(local_nets)
            self.registry.local_nets = self.local_nets
        if v6_prefixes is not None:
            self.v6_prefixes = list(v6_prefixes)
            self.registry.v6_prefixes = self.v6_prefixes

    def is_local(self, ip):
        return bool(ip) and (ip in self.my_ips or
                             self.registry.eligible_ip(ip))

    def in_discovery(self):
        return self.now() - self.capture_started < self.DISCOVERY_SECONDS

    # ---- outbox helpers ----------------------------------------------------
    # ---- capture epochs: stretches of time actually observed -------------
    def epoch_open(self, when, why):
        if self.epochs and self.epochs[-1][1] is None:
            return
        _push_bounded(self.epochs, [when, None, why, ""], 500)

    def epoch_close(self, when, why):
        if self.epochs and self.epochs[-1][1] is None:
            e = self.epochs[-1]
            e[1] = max(when, e[0])
            e[3] = why

    def capture_gaps(self):
        """[(start, end, why)] between observed stretches."""
        out = []
        for a, b in zip(self.epochs, self.epochs[1:]):
            if a[1] is not None and b[0] - a[1] > 1:
                out.append((a[1], b[0], a[3] or "capture was off"))
        return out

    def note_gap(self, start, end, why):
        """Nothing was observed from start to end (the computer slept, the
        capture was restarting...). Close the stretch, end every open
        presence at its last sighting, remember the gap so it does not
        count as devices leaving, and say so on the timeline."""
        if end - start < 1:
            return None
        self.epoch_close(start, why)
        for dev in self.registry.by_key.values():
            if dev.live and dev.presence and dev.presence[-1][1] is None:
                dev.presence_close(min(dev.last_confirmed, start))
        _push_bounded(self.registry.gaps, (start, end), 200)
        entry = self.push_timeline(
            "capture", "WARNING",
            f"Capture gap {fmt_clock(start)} – {fmt_clock(end)} "
            f"({human_duration(end - start)}, {why}): nothing was observed "
            f"in that time")
        self.epoch_open(end, "resumed")
        return entry

    def push_timeline(self, kind, severity, text, ref=None, device=""):
        entry = {"when": self.now(), "kind": kind, "severity": severity,
                 "text": text, "ref": ref, "device": device,
                 "live": not self.use_packet_clock}
        self.timeline.append(entry)
        self.ev_timeline.append(entry)
        if len(self.ev_timeline) > 2000:
            del self.ev_timeline[:-2000]
        if self.obs_sink:
            self.tl_pending.append(entry)
            if len(self.tl_pending) > 20000:
                del self.tl_pending[:5000]
        return entry

    def _alert(self, a):
        if a is None:
            return None
        self.ev_alerts.append(a)
        if not a.updated:
            self.metrics.add("alerts", self.now(), 1)
            ref = ("alert", a.id)
            self.push_timeline("alert", a.severity, a.reason, ref,
                               a.device_key)
        return a

    def feed(self, tag, who, did, when=None):
        self.ev_feed.append({"tag": tag, "who": who, "did": did,
                             "when": when or fmt_clock(self.now())})
        if len(self.ev_feed) > 1500:
            del self.ev_feed[:-1500]

    def banner(self, text, kind="info"):
        self.ev_banner.append((text, kind))

    def _dirty_dev(self, dev):
        if dev is not None:
            self.dirty_devices.add(dev.key)
            self._classify_dirty.add(dev.key)

    # ---- ingest -----------------------------------------------------------
    def _observe_switch(self, d, ts):
        """A switch (or AP / router) announced itself on this link: it
        tells which of ITS ports this computer is plugged into."""
        info = d["lldp"]
        key = (info["proto"], info["chassis"] or info["system"])
        cur = self.switch_ports.get(key)
        rec = dict(info)
        rec.update({"src_mac": d["src_mac"], "last": ts,
                    "first": cur["first"] if cur else ts,
                    "count": (cur["count"] + 1) if cur else 1,
                    "pkt": d.get("no")})
        self.switch_ports[key] = rec
        if cur is None or cur.get("port") != rec["port"] or \
                cur.get("vlan") != rec["vlan"]:
            name = rec["system"] or rec["chassis"]
            port = rec["port_desc"] or rec["port"]
            text = (f"Plugged into {name}, port {port or '?'}"
                    + (f", VLAN {rec['vlan']}" if rec["vlan"] else "")
                    + f" (announced by the switch, {rec['proto']})")
            if cur is not None:
                text = (f"Moved to {name}, port {port or '?'} (was "
                        f"{cur.get('port_desc') or cur.get('port')})")
            self.push_timeline("network", "INFO" if cur is None else
                               "WARNING", text)
        self.observe("lldp", "switch:" + key[1], ts,
                     {"proto": rec["proto"], "port": rec["port"],
                      "system": rec["system"], "vlan": rec["vlan"],
                      "mgmt": rec["mgmt"]})

    def my_device_key(self):
        """The registry key of this computer, or ""."""
        reg = self.registry
        for mac in sorted(self.my_macs):
            k = reg.resolve(mac)
            if k in reg.by_key:
                return k
        for ip in sorted(self.my_ips):
            k = reg.ip_to_key.get(ip)
            if k in reg.by_key:
                return k
        return ""

    def _note_rtt(self, f, ts):
        if f.remote_public:
            self.rtt_samples.append((ts, f.rtt, f.remote_ip, f.device_key,
                                     f.fid))

    def rtt_stats(self, now=None, window=900):
        """Median / 90th percentile handshake round trip (ms) of recent
        Internet connections, and how many samples."""
        now = self.now() if now is None else now
        vals = sorted(r * 1000 for t, r, *_x in self.rtt_samples
                      if now - t <= window)
        if not vals:
            return None, None, 0
        p90 = vals[min(len(vals) - 1, int(len(vals) * 0.9))]
        return statistics.median(vals), p90, len(vals)

    def switch_summary(self, now=None):
        """The freshest LLDP/CDP neighbour, or None."""
        if not self.switch_ports:
            return None
        rec = max(self.switch_ports.values(), key=lambda r: r["last"])
        ttl = rec.get("ttl") or 180
        now = self.now() if now is None else now
        rec = dict(rec)
        rec["fresh"] = now - rec["last"] <= max(ttl, 60) * 1.5
        return rec

    def ingest(self, d):
        """Analyse one decoded packet. Returns the flow id (or None)."""
        ts = d["time"]
        if self.use_packet_clock and ts > self.offline_now:
            self.offline_now = ts
        self.count += 1
        self._pkt_no = d.get("no")
        self.vantage.note(d, self.my_macs, self.my_ips)
        src_ip, dst_ip = d["src_ip"], d["dst_ip"]
        src_local = self.is_local(src_ip)
        dst_local = self.is_local(dst_ip)
        if d["multicast"]:
            direction = "bcast"
        elif src_local and dst_local:
            direction = "lan"
        elif src_local and is_public_ip(dst_ip):
            direction = "up"
        elif dst_local and is_public_ip(src_ip):
            direction = "down"
        elif not src_ip and not dst_ip:
            direction = "lan"
        else:
            direction = "other"
        d["direction"] = direction
        nbytes = d["length"]
        self.metrics.observe_packet(ts, nbytes, direction, d["proto"])
        if direction == "bcast":
            self.metrics.add("bcast_packets", ts, 1)
            self.bcast_talkers.append((ts, d["src_mac"] or src_ip))
        elif direction == "up" and d["dst_mac"]:
            self.gw_mac_traffic[d["dst_mac"]] += nbytes
        elif direction == "down" and d["src_mac"]:
            self.gw_mac_traffic[d["src_mac"]] += nbytes

        src_dev, dst_dev = self._observe_devices(d, src_local, dst_local,
                                                 direction, ts)

        if d["arp_op"] == 2 and src_ip and d["src_mac"]:
            self._observe_arp(src_ip, d["src_mac"], ts)
        elif d["arp_op"] == 1 and src_ip and src_ip == dst_ip and \
                d["src_mac"]:
            self._observe_arp(src_ip, d["src_mac"], ts)   # gratuitous
        if d["dhcp"]:
            self._observe_dhcp(d, ts)
        if d["nd"]:
            self._observe_nd(d, ts)
        if d["mdns"] and src_local:
            self._observe_mdns(d, ts)
        if d["ssdp"] and src_local and not d["ssdp"].get("search"):
            self._observe_ssdp(d, ts)
        if d.get("lldp") and d["src_mac"] not in self.my_macs:
            self._observe_switch(d, ts)
        if d["proto"] == "NBNS" and d["learns"] and src_local:
            for ip, name in d["learns"]:
                if ip == src_ip:
                    dev = self.registry.touch(src_ip, d["src_mac"], "nbns",
                                              f"Answered the Windows name "
                                              f"query for {name}", ts)
                    if dev:
                        self.registry.set_hostname(src_ip, name, "nbns")
                        self._dirty_dev(dev)
                        self.observe("nbns", dev.key, ts, {"name": name})
        if d["dns"]:
            self._observe_dns(d, ts, src_dev, dst_dev)
        if d["doh_hint"] and self.config.get("dns.detect_encrypted_dns",
                                             True):
            self.doh_seen[src_ip].add(d["doh_hint"])
            self.dns.encrypted_seen[d["doh_hint"]] += 1

        if self.registry.moved_ips:
            self._forget_moved_names()
        flow, new_flow = self._observe_flow(d, src_local, dst_local, ts,
                                            src_dev, dst_dev)
        self._observe_websites(d, ts, src_dev, dst_dev, flow, new_flow)
        self._observe_remote(d, ts, direction, src_dev, dst_dev, new_flow)
        if d["cleartext"]:
            self._observe_cleartext(d, src_dev, dst_dev, direction)
        self._baseline_observe(d, ts, src_dev, dst_dev, direction, flow,
                               new_flow)
        self._announce_created()
        self._feed_add(d)
        d["flow_id"] = flow.fid if flow is not None else None
        return d["flow_id"]

    # ---- devices ----------------------------------------------------------
    def _observe_devices(self, d, src_local, dst_local, direction, ts):
        out = [None, None]
        proto, nbytes = d["proto"], d["length"]
        internet = direction in ("up", "down")
        for idx, (ip, mac, local, role) in enumerate(
                ((d["src_ip"], d["src_mac"], src_local, "sent"),
                 (d["dst_ip"], d["dst_mac"], dst_local, "recv"))):
            if role == "recv" and d["multicast"]:
                continue
            if role == "sent" and mac and self.registry.gw_macs:
                lm = mac.lower()      # (review of CO-02) router still alive
                if lm in self.registry.gw_macs:
                    self.registry.gw_heard[lm] = ts
            if ip:
                if not local:
                    continue           # public address: never a device
            elif role == "recv" or not mac:
                continue
            use_mac = mac if is_unicast_mac(mac) else None
            if use_mac and ip and ip != self.gateway_ip and \
                    self._routed_private_v4(ip):
                # routed from elsewhere via the router; 5.2.3 (B-13): also
                # before the router's MAC is known, or the first such
                # packet moved the router device to that address
                use_mac = None
            reg = self.registry
            if use_mac and ip and ip == self.gateway_ip and reg.gw_macs \
                    and use_mac.lower() not in reg.gw_macs and \
                    reg.router_answering(ts, but=use_mac.lower()):
                ip = None     # 5.3.4 (CO-02): not the router's address
            dev = self.registry.note_traffic(ip or None, use_mac, nbytes,
                                             proto, role, internet, ts)
            if dev is None:
                continue
            out[idx] = dev
            self._dirty_dev(dev)
            if role == "sent" and d["ttl_int"] and use_mac:
                dev.os_ttl = max(dev.os_ttl, _initial_ttl(d["ttl_int"]))
            if d["type_hint"] and role == "sent" and not dev.type_hint:
                dev.type_hint = d["type_hint"]
            if internet:
                rip = d["dst_ip"] if role == "sent" else d["src_ip"]
                if rip and len(dev.remote_ips) < 500:
                    dev.remote_ips.add(rip)
            if role == "sent":
                if dev.live and dev.traffic_baseline_flag(
                        ts, float(self.config.get("alerts.chatty_multiplier",
                                                  4)),
                        float(self.config.get("alerts.chatty_min_rate", 3))):
                    a = self._alert(self.alerts.chatty_device(dev))
                    if a and not a.updated:
                        self.push_timeline(
                            "traffic spike", "WARNING",
                            f"{dev.display_name()} is unusually active",
                            ("device", dev.key), dev.key)
            if dev.reactivated_now:
                dev.reactivated_now = False
                window = float(self.config.get(
                    "alerts.reconnect_window_minutes", 30)) * 60
                recent = [t for t in dev.reactivations if ts - t <= window]
                if dev.live:
                    self.push_timeline("device back", "INFO",
                                       f"{dev.display_name()} came back "
                                       f"online", ("device", dev.key),
                                       dev.key)
                if len(recent) >= int(self.config.get(
                        "alerts.reconnect_count", 5)):
                    self._alert(self.alerts.reconnect_cycle(
                        dev, len(recent), window))
        return out[0], out[1]

    def _forget_moved_names(self):
        """An address now belongs to a different device: names learned for
        the previous owner (mDNS, NBNS, reverse DNS…) must not follow the
        address to its new owner."""
        moved, self.registry.moved_ips = self.registry.moved_ips, []
        for ip in moved:
            if self.cache.source(ip) in ("mdns", "nbns", "rdns", "dhcp",
                                         "dns"):
                self.cache.forget(ip)

    def _routed_private_v4(self, ip):
        """A private IPv4 address outside our own subnets arrives through
        the router, so the frame's MAC is the router's, not that host's."""
        a = ip_obj(ip)
        if a is None or a.version != 4:
            return False
        if a.is_link_local:
            return False          # 169.254/16 is never routed: same link
        nets = [n for n in self.local_nets if n.version == 4]
        return bool(nets) and not any(a in n for n in nets)

    def _announce_created(self, flush=False):
        """New devices are announced a few seconds after they appear, so
        the names they announce (DHCP, mDNS) are already known."""
        created = self.registry.created
        if created:
            self.registry.created = []
            due = self.now() + (0 if self.use_packet_clock else 4)
            for key in created:
                dev = self.registry.by_key.get(key)
                if dev is None:
                    continue
                self._dirty_dev(dev)
                if dev.live and self.announce_new and not self.in_discovery():
                    self._pending_new.append((due, key))
        if not self._pending_new:
            return
        now = self.now()
        ready = [k for t, k in self._pending_new if t <= now or flush]
        if not ready:
            return
        self._pending_new = [(t, k) for t, k in self._pending_new
                             if not (t <= now or flush)]
        for key in ready:
            dev = self.registry.by_key.get(key)
            if dev is None:
                continue
            self._classify_dirty.add(key)
            self._classify()
            self.metrics.add("new_devices", self.now(), 1)
            who = self.friendly_who(dev.ip, dev.mac)
            self.feed("device", who, "🆕 joined your network (new device)")
            own = (dev.ip and (dev.ip == self.gateway_ip or
                               dev.ip in self.my_ips)) or \
                (dev.mac and dev.mac in self.my_macs)
            a = None if own else self._alert(self.alerts.new_device(dev))
            if a is None:
                self.push_timeline("new device", "INFO",
                                   f"{dev.display_name()} joined your "
                                   f"network", ("device", dev.key), dev.key)

    def _observe_arp(self, ip, mac, ts):
        dev, conflict = self.registry.note_arp_reply(ip, mac, ts)
        self._dirty_dev(dev)
        if dev is not None:
            self.observe("arp_reply", dev.key, ts, {"ip": ip, "mac": mac})
        flips = self.registry.arp_flip_count(ip)
        both = self.registry.arp_claimants(ip)
        reg = self.registry
        if ip == self.gateway_ip and len(both) == 1 and \
                both[0] in reg.gw_candidates and \
                reg.router_answering(ts, but=both[0]):
            # (review of CO-02) another MAC keeps claiming the router's
            # address while the router is still sending: that is the
            # attack even when the router itself has stopped answering ARP
            both = both + sorted(reg.gw_macs)[:1]
        if flips >= int(self.config.get("alerts.arp_flip_threshold", 4)) \
                or len(both) >= 2:
            a = self._alert(self.alerts.arp_spoof(
                ip, len(self.registry.ip_macs.get(ip, ())), flips,
                ip == self.gateway_ip, together=len(both)))
            if a and not a.updated:
                a.evidence = [f"{t:.0f}: {ip} claimed by {m}" for t, m in
                              list(self.registry.arp_claims.get(ip, ()))[-8:]]
                if ip == self.gateway_ip:
                    self.banner("\U0001F6A8  Your router's address keeps "
                                "flipping between two devices — see the "
                                "Alerts tab.", "bad")
        if not conflict:
            return
        if ip == self.gateway_ip:
            a = self._alert(self.alerts.gateway_change(
                ip, len(self.registry.gw_macs)))
            if a and not a.updated and not self._spoof_warned:
                self._spoof_warned = True
                self.banner("⚠️  Your router's hardware address (MAC) "
                            "changed. That's normal after a router reboot or "
                            "replacement, but worth a look otherwise — "
                            "see Alerts.", "warn")
        else:
            self._alert(self.alerts.duplicate_ip(
                ip, len(self.registry.ip_macs.get(ip, ()))))

    def _observe_dhcp(self, d, ts):
        info = d["dhcp"]
        mt = info.get("msgtype")
        client_mac = info.get("client_mac") or d["src_mac"]
        if mt in (2, 5) and d["src_ip"]:
            server = info.get("server_id") or d["src_ip"]
            if mt in (2, 5):
                self.dhcp_servers[server] += 1
                if len(self.dhcp_servers) > 1:
                    self._alert(self.alerts.dhcp_anomaly(
                        set(self.dhcp_servers)))
            if info.get("router"):
                self.dhcp_routers[info["router"]] += 1
            for s in info.get("dns_servers") or []:
                if len(self.dhcp_dns) < 8:
                    self.dhcp_dns.add(s)
        if mt in (1, 3, 8) and client_mac:
            dev = self.registry.note_dhcp_client(
                client_mac, info.get("hostname", ""),
                info.get("vendor_class", ""), info.get("param_list", ""), ts)
            self._dirty_dev(dev)
            if dev is not None:
                if info.get("client_id"):
                    dev.dhcp_client_id = info["client_id"]
                self.observe("dhcp_request", dev.key, ts,
                             {"hostname": info.get("hostname", ""),
                              "vendor": info.get("vendor_class", ""),
                              "params": info.get("param_list", ""),
                              "client_id": info.get("client_id", "")})
        if mt == 5 and info.get("yiaddr"):            # ACK = a real lease
            existing = self.registry.by_key.get((client_mac or "").lower())
            host = info.get("hostname") or (existing.dhcp_hostname
                                            if existing else "")
            dev, reused = self.registry.note_dhcp_lease(
                info["yiaddr"], client_mac, host, info.get("lease_time"), ts)
            if dev:
                self._dirty_dev(dev)
                self.observe("dhcp_ack", dev.key, ts,
                             {"ip": info["yiaddr"], "lease":
                              info.get("lease_time") or 0,
                              "server": info.get("server_id") or
                              d["src_ip"], "hostname": host})
                self.push_timeline("dhcp lease", "INFO",
                                   f"{dev.display_name()} got address "
                                   f"{info['yiaddr']} from DHCP",
                                   ("device", dev.key), dev.key)

    def _observe_nd(self, d, ts):
        nd = d["nd"]
        kind = nd.get("kind")
        mac = nd.get("mac") or d["src_mac"]
        if kind == "RA":
            # 5.3.4 (CO-01): only the router's own announcement says what
            # is "local", and only a normal LAN size (/48 to /64). One RA
            # from any laptop for 2000::/3 made the whole IPv6 Internet
            # local and gave it to the router device
            from_router = self._is_router_mac(mac)
            for pfx in nd.get("prefixes", []) if from_router else ():
                with contextlib.suppress(ValueError):
                    net = ipaddress.ip_network(pfx, strict=False)
                    if net.version == 6 and net.is_global and \
                            48 <= net.prefixlen <= 64 and \
                            net not in self.v6_prefixes and \
                            len(self.v6_prefixes) < 8:
                        self.v6_prefixes.append(net)
                        self.registry.v6_prefixes = self.v6_prefixes
            known_router = mac in self.registry.ra_routers
            dev = self.registry.note_nd(d["src_ip"], mac, "RA", ts)
            if dev is not None:
                self.observe("ra", dev.key, ts,
                             {"prefixes": nd.get("prefixes", [])[:4]})
            self._check_rogue_ra(mac, dev, nd, known_router)
        elif kind == "NA":
            dev = self.registry.note_nd(nd.get("target"), mac, "NA", ts)
            if dev is not None:
                self.observe("nd", dev.key, ts, {"ip": nd.get("target"),
                                                 "kind": "NA"})
        elif kind == "NS" and not nd.get("dad") and nd.get("mac"):
            dev = self.registry.note_nd(d["src_ip"], nd["mac"], "NS", ts)
        else:
            dev = self.registry.touch(None, d["src_mac"], "local_traffic",
                                      "IPv6 neighbor/router discovery", ts) \
                if d["src_mac"] else None
        self._dirty_dev(dev)

    def _is_router_mac(self, mac):
        """The MAC is the router's (trusted gateway MAC, or the device that
        holds the gateway address); with no IPv4 router known at all, an
        IPv6-only LAN, the first announcer is believed."""
        reg = self.registry
        mac = (mac or "").lower()
        if not mac:
            return False
        if mac in reg.gw_macs:
            return True
        gw_dev = reg.by_key.get(reg.ip_to_key.get(self.gateway_ip, ""))
        if gw_dev is not None and gw_dev.mac:
            return gw_dev.mac == mac
        return not reg.gw_macs and not (reg.ra_routers - {mac})

    def _check_rogue_ra(self, mac, dev, nd, known_router):
        """IPv6 router announcements should come from the router. One from
        another device is worth a (non-alarming) warning. 5.3.4 (CO-01):
        also one with router lifetime 0 when it carries prefixes."""
        if not mac or known_router or (not nd.get("lifetime", 1) and
                                       not nd.get("prefixes")):
            return
        gw_macs = set(self.registry.gw_macs)
        gw_dev = self.registry.by_key.get(
            self.registry.ip_to_key.get(self.gateway_ip, ""))
        if gw_dev is not None and gw_dev.mac:
            gw_macs.add(gw_dev.mac)
        others = self.registry.ra_routers - gw_macs - {mac}
        if mac in gw_macs or (not gw_macs and not others):
            return                # it IS the router, or nothing to compare
        who = dev.display_name() if dev is not None else mac
        a = self._alert(self.alerts.rogue_ra(
            mac, who, nd.get("prefixes", []),
            sorted(self.registry.ra_routers)))
        if a is not None and not a.updated:
            self.push_timeline("rogue router", "WARNING",
                               f"{who} announced itself as an IPv6 router",
                               ("device", mac), mac)

    def _observe_mdns(self, d, ts):
        info = d["mdns"]
        if not info.get("qr"):
            return
        ip, mac = d["src_ip"], d["src_mac"]
        name = info["names"][0] if info.get("names") else ""
        dev = None
        for svc in (info.get("services") or [])[:6]:
            if svc.startswith("_services._dns-sd"):
                continue
            dev, new = self.registry.note_service(ip, mac, "mdns", svc,
                                                  friendly=name, when=ts)
            if dev and new:
                self._service_added(dev, svc, "mDNS")
        if dev is None:
            dev = self.registry.touch(ip, mac, "mdns",
                                      "Answered a local name lookup (mDNS)",
                                      ts)
        if dev is None:
            return
        for h in info.get("hostnames") or []:
            short = h[:-6] if h.lower().endswith(".local") else h
            if short and not dev.mdns_name:
                dev.mdns_name = short
                _push_bounded(dev.hostname_history, [short, "mdns", ts], 20)
        self.observe("mdns", dev.key, ts,
                     {"name": name, "services":
                      [x for x in (info.get("services") or [])[:4]]})
        txt = info.get("txt") or {}
        for k in ("model", "md", "am", "usb_mdl", "ty", "product", "rpmd"):
            if txt.get(k):
                dev.model_hint = txt[k]
                break
        if txt.get("fn") and not dev.mdns_name:
            dev.mdns_name = txt["fn"]
        self._dirty_dev(dev)

    def _observe_ssdp(self, d, ts):
        info = d["ssdp"]
        label = info.get("st") or info.get("server") or "UPnP device"
        dev, new = self.registry.note_service(
            d["src_ip"], d["src_mac"], "ssdp", label[:80],
            friendly=info.get("friendly", ""), when=ts)
        if dev:
            self.observe("ssdp", dev.key, ts, {"label": label[:80],
                                               "server": info.get("server",
                                                                  "")[:80]})
            if info.get("server"):
                dev.ssdp_server = info["server"]
            if new and len(dev.services) > 1:
                self._service_added(dev, label[:60], "SSDP")
            self._dirty_dev(dev)

    def _service_added(self, dev, svc, how):
        if not dev.live:
            return
        old = self.now() - dev.first_seen > 600
        if old:
            self.push_timeline("service", "INFO",
                               f"{dev.display_name()} started advertising "
                               f"{svc}", ("device", dev.key), dev.key)
            self._alert(self.alerts.new_service(dev, svc))
        low = svc.lower()
        if any(k in low for k in REMOTE_ACCESS_MDNS):
            self._alert(self.alerts.remote_access(
                dev.display_name(), dev.key, svc,
                f"It advertises the remote-access service “{svc}” "
                f"over {how}."))

    def _observe_dns(self, d, ts, src_dev, dst_dev):
        info = d["dns"]
        if info.get("qr") == 0 and d["dport"] == 53:
            self.metrics.add("dns_queries", ts, 1)
            key = src_dev.key if src_dev else ""
            if key and info.get("qname"):
                self.observe("dns_query", key, ts,
                             {"domain": info["qname"], "server":
                              d["dst_ip"]})
            change = self.dns.on_query(ts, d["src_ip"], d["dst_ip"], info,
                                       key)
            if change and src_dev and src_dev.live:
                self.push_timeline("dns change", "WARNING",
                                   f"{src_dev.display_name()} now uses DNS "
                                   f"server {change[1]} (was {change[0]})",
                                   ("device", src_dev.key), src_dev.key)
                self._alert(self.alerts.dns_server_change(
                    src_dev.display_name(), src_dev.key, change[0],
                    change[1]))
        elif info.get("qr") == 1 and d["sport"] == 53:
            self.dns.on_response(ts, d["dst_ip"], d["src_ip"], info)

    # ---- flows ------------------------------------------------------------
    def _observe_flow(self, d, src_local, dst_local, ts, src_dev, dst_dev):
        tr = d["transport"]
        if d["multicast"] or tr not in ("TCP", "UDP", "ICMP", "ICMPv6") or \
                not d["src_ip"] or not d["dst_ip"]:
            return None, False
        sip, dip = d["src_ip"], d["dst_ip"]
        sp, dp = (d["sport"] or 0), (d["dport"] or 0)
        if tr in ("ICMP", "ICMPv6"):
            sp = dp = 0
        if src_local and not dst_local:
            out_dir = True
        elif dst_local and not src_local:
            out_dir = False
        elif src_local and dst_local:
            out_dir = (tr, dip, dp, sip, sp) not in self.flows.active
        elif sip in self.my_ips:
            out_dir = True
        elif dip in self.my_ips:
            out_dir = False
        else:
            out_dir = (tr, dip, dp, sip, sp) not in self.flows.active
        if out_dir:
            key = (tr, sip, sp, dip, dp)
            f, new = self.flows.lookup_or_create(key, tr, sip, sp, dip, dp,
                                                 ts)
        else:
            key = (tr, dip, dp, sip, sp)
            f, new = self.flows.lookup_or_create(key, tr, dip, dp, sip, sp,
                                                 ts)
        f.last_seen = max(f.last_seen, ts)
        n = d["length"]
        if out_dir:
            f.packets_out += 1
            f.bytes_out += n
            dev = src_dev
        else:
            f.packets_in += 1
            f.bytes_in += n
            dev = dst_dev
        if dev is not None and not f.device_key:
            f.device_key = dev.key
        if new:
            f.lan = src_local and dst_local
            f.initiator = "local" if out_dir else "remote"
            self.metrics.add("new_connections", ts, 1)
            probe = self.own_probe_targets.get((f.remote_ip, f.remote_port))
            if probe and ts <= probe:
                f.note = "MiniWireshark health check"
            if f.remote_port == 853:
                self.dns.encrypted_seen["DNS-over-TLS (port 853)"] += 1
            doh_ip = doh_ip_name(f.remote_ip) if f.remote_port in (
                443, 853) else None
            if doh_ip and self.config.get("dns.detect_encrypted_dns", True):
                self.dns.encrypted_seen[
                    f"Likely encrypted DNS to {doh_ip}"] += 1
            if tr == "UDP" and f.remote_port in VPN_PORTS:
                f.app = f.app or "VPN"
                f.service = PORT_SERVICES.get(f.remote_port, "VPN tunnel")
        if tr == "TCP" and d["tcp_flags"] is not None:
            fl = d["tcp_flags"]
            if fl & 0x02 and not fl & 0x10:
                f.syn = True
                f.syns += 1
                if f.syn_ts is None:
                    f.syn_ts = ts
                f.initiator = "local" if out_dir else "remote"
                if out_dir and dev is not None:
                    self.scans.attempt(dev.key, ts, f.remote_ip,
                                       f.remote_port)
            elif fl & 0x02 and fl & 0x10:
                if not f.synack and f.syn_ts is not None and f.syns == 1 \
                        and ts >= f.syn_ts and f.initiator == "local":
                    # Karn's rule: a re-sent SYN makes the time ambiguous
                    f.rtt = ts - f.syn_ts
                    self._note_rtt(f, ts)
                f.synack = True
                if not out_dir and f.device_key:
                    self.scans.reply(f.device_key, f.remote_ip,
                                     f.remote_port)
                # whoever sends the SYN-ACK is the server for this port
                if sp in REMOTE_ACCESS_PORTS and src_dev is not None and \
                        src_dev.live:
                    svc = REMOTE_ACCESS_PORTS[sp]
                    self._alert(self.alerts.remote_access(
                        src_dev.display_name(), src_dev.key, svc,
                        f"It accepted a {svc} connection (port {sp}) from "
                        f"{dip}."))
            if fl & 0x01:
                if out_dir:
                    f.fin_out = True
                else:
                    f.fin_in = True
            if fl & 0x04:
                f.rst += 1
                f.rst_by = "local" if out_dir else "remote"
                f.state = "Reset"
                self.metrics.add("tcp_resets", ts, 1)
                if f.device_key:
                    self._note_reset(f, ts)
            elif f.state not in ("Reset",):
                f.state = "Open" if f.synack or f.packets_in else "Opening"
            pl = d["payload_len"]
            if pl:
                if out_dir:
                    f.payload_out += pl
                else:
                    f.payload_in += pl
            elif fl == 0x10 and d.get("ack") is not None:
                # a pure ACK: the same ACK and window again = duplicate
                cur = (d["ack"], d["win"])
                last = f.ack_out if out_dir else f.ack_in
                if last == cur:
                    f.dupacks += 1
                if out_dir:
                    f.ack_out = cur
                else:
                    f.ack_in = cur
            if d.get("win") == 0 and not fl & 0x06:
                f.zero_win += 1
            if d["payload_len"] and d["seq"] is not None:
                end = (d["seq"] + d["payload_len"]) & 0xffffffff
                prev = f.seq_out if out_dir else f.seq_in
                if prev is not None:
                    delta = (end - prev) & 0xffffffff
                    if delta == 0 or delta > 0x7fffffff:
                        f.retrans += 1
                        f.retx_bytes += d["payload_len"]
                    else:
                        prev = end
                else:
                    prev = end
                if out_dir:
                    f.seq_out = prev
                else:
                    f.seq_in = prev
        proto = d["proto"]
        if proto not in ("TCP", "UDP", "?", "") and (
                not f.app or f.app in ("TCP", "UDP", "VPN") or
                d["app_conf"] == "Observed" and f.interp_conf != "Observed"):
            f.app = proto
            f.interp_conf = d["app_conf"] or f.interp_conf
        if not f.service and d["service"]:
            f.service = d["service"]
            if not f.interp_conf:
                f.interp_conf = d["app_conf"] or "Likely (by port)"
        tls = d["tls"]
        if tls:
            if tls.get("version"):
                f.tls_version = tls["version"]
            if tls.get("alpn"):
                f.alpn = ",".join(tls["alpn"][:3])
            if tls.get("sni") and tls.get("kind") == "client":
                f.domain, f.domain_conf = tls["sni"], "Observed"
                f.assoc = AS_CONNECTED
        if d["http_host"]:
            f.domain, f.domain_conf = d["http_host"], "Observed"
            f.assoc = AS_CONNECTED
        if new and f.remote_public and not f.domain:
            self._correlate_flow(f, ts)
        enc = d["encrypted"]
        if enc == "no":
            f.encrypted = "no"
            f.cleartext = d["cleartext"] or f.cleartext
        elif enc == "yes" and f.encrypted != "no":
            f.encrypted = "yes"
        elif enc == "likely" and f.encrypted == "unknown":
            f.encrypted = "likely"
        rec = self.remote_hosts.get(f.remote_ip)
        if rec is not None and (rec.country or rec.asn) and not f.country:
            f.country, f.asn, f.org = rec.country, rec.asn, rec.org
        self.flows.dirty.add(f.fid)
        return f, new

    def _correlate_flow(self, f, ts):
        """Name a new connection from the lookups that preceded it. The
        result is Correlated (its own lookup) or Inferred (someone else's),
        never Observed."""
        dom, kind = self.correlator.match(f.device_key, f.remote_ip, ts)
        if not dom:
            return
        n = len(self.ip_to_domains.get(f.remote_ip) or ())
        if kind in ("own-recent", "own-old"):
            if n <= 3:
                f.assoc = AS_CONNECTED_LOOKUP
                f.domain_conf = "Correlated (its own lookup)"
            else:
                f.assoc = AS_CONNECTED_AMBIG
                f.domain_conf = f"Correlated (one of {n} names)"
        else:
            f.assoc = AS_INFERRED
            f.domain_conf = "Possibly (this address was named earlier)"
        f.domain = dom
        self.tie(f.device_key, dom, f.assoc, ts)

    def _note_reset(self, f, ts):
        dq = self.resets[f.device_key]
        dq.append((ts, f.remote_ip))
        while dq and ts - dq[0][0] > 600:
            dq.popleft()
        thr = int(self.config.get("alerts.reset_threshold", 40))
        if len(dq) >= thr:
            dev = self.registry.by_key.get(f.device_key)
            if dev and dev.live:
                top = Counter(r for _t, r in dq).most_common(1)
                self._alert(self.alerts.tcp_resets(
                    dev, len(dq), 600, top[0][0] if top else ""))

    # ---- websites / remote hosts ---------------------------------------------
    def _observe_websites(self, d, ts, src_dev, dst_dev, flow, new_flow):
        dns = d["dns"]
        if dns and dns.get("qr") == 1 and d["sport"] == 53:
            dkey = dst_dev.key if dst_dev is not None else ""
            qname = (dns.get("qname") or "").lower().strip(".")
            for ip, name in d["learns"]:
                if not (is_public_ip(ip) and name):
                    continue
                rec = self.register_website(name, ip, dst_dev, "DNS", ts)
                lname = name.lower().strip(".")
                self.correlator.note_resolution(dkey, lname, ip, ts)
                if self.obs_sink:
                    self.res_pending.append((ts, dkey, lname, ip))
                if rec is not None and dkey and lname == qname:
                    rec.lookups += 1
                    self.tie(dkey, lname, AS_LOOKUP_ONLY, ts)
                    self.observe("dns_answer", dkey, ts,
                                 {"domain": lname, "ip": ip},
                                 also=("site:" + lname,))
        tls = d["tls"]
        if tls and tls.get("sni") and tls.get("kind") == "client" and \
                is_public_ip(d["dst_ip"]):
            sni = tls["sni"]
            quic = tls.get("via") == "quic"
            self.register_website(sni, d["dst_ip"], src_dev,
                                  "QUIC first packet" if quic else "TLS SNI",
                                  ts, connection=True, encrypted=True)
            self.correlator.note_resolution("", sni, d["dst_ip"], ts)
            if src_dev is not None:
                self.tie(src_dev.key, sni, AS_CONNECTED, ts)
                self.observe("tls_sni", src_dev.key, ts,
                             {"domain": sni, "ip": d["dst_ip"],
                              "flow": flow.fid if flow else None,
                              "ech": bool(tls.get("ech")),
                              "via": "quic" if quic else "tls"},
                             also=("site:" + sni,))
        if d["http_host"] and is_public_ip(d["dst_ip"]):
            host = d["http_host"]
            self.register_website(host, d["dst_ip"], src_dev,
                                  "HTTP Host", ts, connection=True,
                                  encrypted=False)
            self.correlator.note_resolution("", host, d["dst_ip"], ts)
            if src_dev is not None:
                self.tie(src_dev.key, host, AS_CONNECTED, ts)
                self.observe("http_host", src_dev.key, ts,
                             {"domain": host, "ip": d["dst_ip"],
                              "flow": flow.fid if flow else None},
                             also=("site:" + host,))
        if new_flow and flow is not None and flow.device_key and \
                flow.remote_public:
            fk = (flow.device_key, flow.remote_ip)
            q = self.flow_starts.get(fk)
            if q is None:
                if len(self.flow_starts) >= 6000:
                    self.flow_starts.popitem(last=False)
                q = self.flow_starts[fk] = deque(maxlen=64)
            q.append(ts)
            self.observe("flow_start", flow.device_key, ts,
                         {"remote": flow.remote_ip, "port": flow.remote_port,
                          "proto": flow.transport, "flow": flow.fid,
                          "domain": flow.domain, "assoc": flow.assoc},
                         also=(f"flow:{flow.fid}",))
        if flow is not None and flow.domain and flow.remote_public:
            rec = self.websites.get(flow.domain)
            if rec is not None:
                rec.bytes += d["length"]
                if new_flow and flow.domain_conf != "Observed":
                    rec.connections += 1
                self.dirty_websites.add(flow.domain)

    def register_website(self, domain, ip, dev, source, ts=None,
                         connection=False, encrypted=None, reported=False):
        ts = ts or self.now()
        key = domain.lower().strip(".")
        if not key or "." not in key:
            return None
        rec = self.websites.get(key)
        if rec is None:
            reg = registrable_domain(key)
            # 5.2.3 (B-24): was a scan of the last 3,000 websites for every
            # new one (up to 0.2 ms each), and a site first seen more than
            # 3,000 websites ago got a second "First visit"
            roots = self._seen_roots
            if roots is None:
                roots = self._seen_roots = dict.fromkeys(
                    w.registrable for w in self.websites.values())
            new_root = reg not in roots
            if new_root:
                roots[reg] = None
                if len(roots) > 60000:
                    for k in list(itertools.islice(roots, 6000)):
                        del roots[k]
            rec = WebsiteRecord(domain=key, registrable=reg, first_seen=ts,
                                last_seen=ts)
            cat, src = domain_category(key)
            if category_shown(cat, src, self.config):
                rec.category, rec.category_source = cat, src
            self.websites[key] = rec
            if len(self.websites) > 20000:
                for old in sorted(self.websites.values(),
                                  key=lambda w: w.last_seen)[:2000]:
                    self.websites.pop(old.domain, None)
            if new_root and not self.in_discovery() and \
                    not self.use_packet_clock:
                self.push_timeline("website", "INFO",
                                   f"{source} reports a first lookup of "
                                   f"{reg}" if reported else
                                   f"First visit to {reg}",
                                   ("website", key),
                                   dev.key if dev else "")
        if ip:
            if len(rec.resolved_ips) < 64:
                rec.resolved_ips.add(ip)
            names = self.ip_to_domains.get(ip)
            if names is None:
                names = self.ip_to_domains[ip] = OrderedDict()
                if len(self.ip_to_domains) > 60000:
                    for k in list(self.ip_to_domains)[:6000]:
                        self.ip_to_domains.pop(k, None)
            names.pop(key, None)
            names[key] = ts
            while len(names) > 8:
                names.popitem(last=False)
            rh = self.remote_hosts.get(ip)
            if rh is not None:
                if len(rh.domains) < 20:
                    rh.domains.add(key)
                rh.domain = key
                self.dirty_remotes.add(ip)
                if rh.country:
                    rec.countries.add(rh.country)
                if rh.asn:
                    rec.asns.add(rh.asn)
        if dev is not None:
            if len(rec.devices) < 200:
                rec.devices.add(dev.key)
            if len(dev.websites) < 500:
                dev.websites.add(key)
        rec.requests += 1
        if connection:
            rec.connections += 1
            if encrypted is True:
                rec.encrypted += 1
            elif encrypted is False:
                rec.cleartext += 1
        rec.last_seen = max(rec.last_seen, ts)
        rec.sources.add(source)
        if source == "HTTP Host":
            self.http_count += 1
            self.http_hosts[key] += 1
        doh = doh_name(key) if self.config.get(
            "dns.detect_encrypted_dns", True) else None
        if doh:
            self.dns.encrypted_seen[doh] += 1
        self.dirty_websites.add(key)
        return rec

    def _observe_remote(self, d, ts, direction, src_dev, dst_dev, new_flow):
        if direction == "up":
            pub, rport, dev, out = d["dst_ip"], d["dport"], src_dev, True
        elif direction == "down":
            pub, rport, dev, out = d["src_ip"], d["sport"], dst_dev, False
        elif direction == "other":
            if is_public_ip(d["dst_ip"]):
                pub, rport, dev, out = d["dst_ip"], d["dport"], src_dev, True
            elif is_public_ip(d["src_ip"]):
                pub, rport, dev, out = d["src_ip"], d["sport"], dst_dev, False
            else:
                return
        else:
            return
        if not pub:
            return
        rec = self.remote_hosts.get(pub)
        if rec is None:
            rec = RemoteHostRecord(ip=pub, first_seen=ts, last_seen=ts)
            self.remote_hosts[pub] = rec
            self._geo_fill(rec)
            self._reputation_fill(rec)
            if len(self.remote_hosts) > 30000:
                for old in sorted(self.remote_hosts.values(),
                                  key=lambda r: r.last_seen)[:3000]:
                    self.remote_hosts.pop(old.ip, None)
        rec.last_seen = max(rec.last_seen, ts)
        rec.packets += 1
        rec.bytes_total += d["length"]
        if out:
            rec.bytes_out += d["length"]
        else:
            rec.bytes_in += d["length"]
        if rport and len(rec.ports) < 40 and d["transport"] in ("TCP", "UDP"):
            rec.ports.add(rport)
        if d["proto"] and len(rec.protocols) < 20:
            rec.protocols.add(d["proto"])
        if new_flow:
            rec.connections += 1
        if dev is not None:
            if len(rec.devices) < 100 and dev.key not in rec.devices:
                rec.devices.add(dev.key)
                if rec.reputation and dev.live:
                    self._alert(self.alerts.reputation(
                        dev, pub, rport, rec.reputation))
        names = self.ip_to_domains.get(pub)
        if names:
            dom = next(reversed(names))
            rec.domain = dom
            if len(rec.domains) < 20:
                rec.domains.update(names)
        if rport in VPN_PORTS and d["transport"] == "UDP":
            self.vpn_bytes[pub] += d["length"]
        self.dirty_remotes.add(pub)
        if not rec.country:
            self.ev_geo.add(pub)

    def _reputation_fill(self, rec):
        rdb = getattr(self, "_rep_db", None)
        if rdb is None or getattr(self, "_rep_db_gen", -1) != _REP_GEN[0]:
            rdb = self._rep_db = reputation_db()
            self._rep_db_gen = _REP_GEN[0]
        rec.reputation = rdb.lookup(rec.ip) if rdb is not None else []

    def reenrich(self):
        """Re-label this session with the reference data loaded now (after
        a Components Center update) without recapturing. → counts."""
        _REP_GEN[0] += 1
        n = {"vendors": 0, "remote": 0, "reputation": 0, "websites": 0}
        for dev in list(self.registry.by_key.values()):
            if dev.mac and not dev.randomized_mac:
                v = mac_vendor(dev.mac)
                if v and v != dev.vendor:
                    dev.vendor = v
                    dev.add_evidence("oui_match", f"Vendor prefix matches "
                                                  f"{v}", self.now())
                    n["vendors"] += 1
                    self._dirty_dev(dev)
        for rec in list(self.remote_hosts.values()):
            before = (rec.asn, rec.country, len(rec.reputation))
            if not rec.country or rec.geo_source == "offline database":
                rec.country = ""
                self._geo_fill(rec)
            had = {h[0] for h in rec.reputation}
            self._reputation_fill(rec)
            if {h[0] for h in rec.reputation} - had:
                n["reputation"] += 1
                for dk in sorted(rec.devices):
                    dev = self.registry.by_key.get(dk)
                    if dev is not None and dev.live:
                        port = min(rec.ports) if rec.ports else 0
                        self._alert(self.alerts.reputation(
                            dev, rec.ip, port, rec.reputation))
            if (rec.asn, rec.country, len(rec.reputation)) != before:
                n["remote"] += 1
                self.dirty_remotes.add(rec.ip)
        for w in list(self.websites.values()):
            cat, srcname = domain_category(w.domain)
            if (cat or srcname == CAT_YOURS) and \
                    (cat, srcname) != (w.category, w.category_source) \
                    and category_shown(cat, srcname, self.config):
                w.category, w.category_source = cat, srcname
                n["websites"] += 1
                self.dirty_websites.add(w.domain)
        return n

    def _geo_fill(self, rec):
        if not self.config.get("privacy.local_asn_db", False):
            return
        db = DATA.get("asn") if DATA is not None else None
        if db is None:
            return
        hit = db.lookup(rec.ip)
        if hit:
            rec.asn, cc, rec.org = hit
            if cc and not rec.country:
                rec.country = cc
                rec.country_name = COUNTRY_NAMES.get(cc, "")
            rec.geo_source = "offline database"

    def apply_country(self, ip, code, name, provider=""):
        rec = self.remote_hosts.get(ip)
        if rec is None:
            return
        rec.country = code
        rec.country_name = name or COUNTRY_NAMES.get(code, "")
        rec.geo_source = provider
        self.dirty_remotes.add(ip)
        for dk in rec.devices:
            dev = self.registry.by_key.get(dk)
            b = self.baselines.devices.get(dk)
            if dev is None or b is None or not dev.live:
                continue
            if code not in b.countries:
                if b.n >= 30 and len(b.countries) >= 3:
                    self._alert(self.alerts.new_country(
                        dev, rec.country_name or code, ip))
                if len(b.countries) < 80:
                    b.countries.add(code)

    def _observe_cleartext(self, d, src_dev, dst_dev, direction):
        proto = d["cleartext"]
        self.cleartext_seen[proto] += 1
        dev = src_dev or dst_dev
        if dev is None or not dev.live:
            return
        remote = d["dst_ip"] if dev is src_dev else d["src_ip"]
        if proto == "HTTP" and direction != "up":
            return              # plain-web is very common; only flag uploads
        if proto in ("HTTP", "SNMP") and not self.config.get(
                "alerts.flag_http", False):
            return
        self._alert(self.alerts.cleartext(
            dev.display_name(), dev.key, proto, remote,
            is_public_ip(remote)))

    def _baseline_observe(self, d, ts, src_dev, dst_dev, direction, flow,
                          new_flow):
        if direction not in ("up", "down", "lan"):
            return
        for dev, role in ((src_dev, "sent"), (dst_dev, "recv")):
            if dev is None or not dev.live:
                continue
            remote = (d["dst_ip"] if role == "sent" else d["src_ip"]) \
                if direction in ("up", "down") else ""
            b = self.baselines.get(dev.key)
            snap = b.observe(ts, d["length"], role, remote,
                             is_dns=bool(d["dns"]) and role == "sent",
                             proto=d["proto"],
                             service_port=(flow.remote_port if flow and
                                           flow.device_key == dev.key
                                           and new_flow else None),
                             new_conn=bool(new_flow and flow and
                                           flow.device_key == dev.key))
            self._baseline_check(dev, snap)

    def _baseline_check(self, dev, snap):
        for feat, v, m in self.baselines.check(snap):
            a = self._alert(self.alerts.baseline_anomaly(dev, feat, v, m))
            if a is not None and not a.updated and \
                    feat in ("bytes_up", "bytes_down"):
                self._spike_story(dev, a, feat == "bytes_up", v)

    def spike_program(self, dev, upload, since):
        """5.3.4 (IP-022): the program behind this computer's busiest
        connection since `since`, from the name stored on the connection
        when the operating system's table was read (live only). None: not
        this computer, or not live; "": the program isn't known (a short
        connection, no psutil, or no admin rights)."""
        if self.use_packet_clock or not dev or \
                dev.key != self.my_device_key():
            return None
        best, most = None, 0
        recent = list(self.flows.active.values())[-3000:] + \
            list(self.flows.archive)[-500:]
        for f in recent:
            if f.device_key != dev.key or f.last_seen < since:
                continue
            b = f.bytes_out if upload else f.bytes_in
            if b > most:
                best, most = f, b
        return program_short_name(best.process) if best is not None else ""

    def _spike_story(self, dev, a, upload, value):
        """One plain sentence on the Timeline (kept in the history, so the
        story of a past day still names the program): "At 14:02 chrome.exe
        on this computer sent 80.0 MB in one minute"."""
        start = (int(self.now() // 60) - 1) * 60.0
        prog = self.spike_program(dev, upload, start)
        if prog is not None:
            a.refs["program"] = prog or "?"
        text = spike_sentence(hm_clock(start), dev.display_name(), upload,
                              _human_bytes(value), prog is not None,
                              prog or "")
        return self.push_timeline("traffic spike", "INFO", text,
                                  ("device", dev.key), dev.key)

    # ---- friendly feed ------------------------------------------------------
    def friendly_who(self, ip, mac):
        if ip and ip in self.my_ips or (mac and mac in self.my_macs):
            return "💻  This computer"
        if ip and ip == self.gateway_ip:
            return "🌐  Your router"
        dev = self.device_for(ip, mac)
        if dev is not None and dev.alias:
            return f"{DEVICE_ICONS.get(dev.type, '❓')}  {dev.alias}"
        name = self.cache.get(ip) if ip else ""
        kind = dev.type if dev else "unknown"
        icon = DEVICE_ICONS.get(kind, "❓")
        label = (dev.display_name() if dev and (dev.hostname or
                                                 dev.dhcp_hostname or
                                                 dev.mdns_name) else "") or \
            name or (dev.vendor if dev else "") or ip or mac
        if dev is None and ip and is_public_ip(ip):
            return f"☁️  {name or ip}"
        return f"{icon}  {label}" if label else "❓  Unknown device"

    def device_for(self, ip, mac=None):
        key = self.registry.ip_to_key.get(ip) if ip else None
        if key is None and mac:
            key = mac.lower() if mac.lower() in self.registry.by_key else None
        return self.registry.by_key.get(key) if key else None

    def _feed_add(self, d):
        proto = d["proto"]
        if proto in ("TCP", "UDP") and not d["dns_names"]:
            if d["transport"] == "TCP" and d["tcp_flags"] is not None and \
                    d["tcp_flags"] & 0x02 and not d["tcp_flags"] & 0x10 and \
                    d["direction"] == "up":
                svc = d["service"] or "a service"
                who = self.friendly_who(d["src_ip"], d["src_mac"])
                dst = self.ip_to_domains.get(d["dst_ip"])
                tgt = next(reversed(dst)) if dst else d["dst_ip"]
                self.feed("other", who, f"🔗 connecting to {tgt} ({svc})")
            return
        who = self.friendly_who(d["src_ip"], d["src_mac"])
        tag, did = "other", d["text"]
        if proto == "mDNS" and d["mdns"] and d["mdns"].get("qr") == 1:
            if not (d["mdns"].get("services") or d["mdns"].get("names")):
                return
            tag, did = "device", f"📣 {d['text']}"
        elif proto in ("DNS", "mDNS", "LLMNR"):
            if proto == "DNS" and d["dns"] and d["dns"].get("qr") == 1:
                return                    # answers repeat the question
            tag = "dns"
            did = f"🔍 looked up  {d['text']}" if d["text"] else "🔍 DNS lookup"
        elif proto in ("TLS", "DoT"):
            if not (d["tls"] and d["tls"].get("kind") == "client"):
                return
            tag = "secure"
            did = f"🔐 {d['text']}"
        elif proto == "QUIC":
            if d["tls"] and d["tls"].get("sni"):
                tag = "secure"
                did = f"🔐 {d['text']}"
            elif not (d["tcp_flags"] is None and d["payload_len"] > 1000):
                return
            else:
                tag = "secure"
                did = "🔐 opened a fast secure connection (QUIC)"
        elif proto == "HTTP":
            tag = "unsecure"
            did = f"⚠️ {d['text']}"
        elif proto in ("DHCP", "DHCPv6"):
            tag = "device"
            did = f"🆔 {d['text']}"
        elif proto in ("ARP", "NDP"):
            if d["arp_op"] == 1 and d["src_ip"] in self.my_ips:
                return                    # our own discovery sweep
            tag = "device"
            did = f"🔎 {d['text']}"
        elif proto == "SSDP":
            tag = "device"
            did = f"📣 {d['text']}"
        elif proto in ("ICMP", "ICMPv6"):
            did = f"📡 {d['text']}"
        elif proto in ("SSH", "RDP", "TELNET", "FTP", "SMB"):
            tag = "unsecure" if proto in ("TELNET", "FTP") else "other"
            did = f"🖥  {d['text']}"
        elif proto in ("NTP", "IGMP", "NBNS"):
            did = f"🕑 {d['text']}" if proto == "NTP" else d["text"]
        self.feed(tag, who, did, fmt_clock(d["time"]))

    # ---- periodic work --------------------------------------------------------
    def tick(self, now=None):
        """All upkeep at once (tests, file imports)."""
        for _name in self.tick_steps(now):
            pass

    def tick_steps(self, now=None):
        """The same upkeep as named steps: the window runs one step per
        callback, so a large network never freezes it for the whole pass
        (5.0.2: one 40-60 ms callback every 5 s at 300 devices)."""
        now = now or self.now()
        newly_inactive, newly_expired = self.registry.tick_lifecycle(now)
        for dev in newly_inactive:
            self._dirty_dev(dev)
            self.push_timeline("device left", "INFO",
                               f"{dev.display_name()} went offline",
                               ("device", dev.key), dev.key)
        for dev in newly_expired:
            self._dirty_dev(dev)
            self.push_timeline("device expired", "INFO",
                               f"{dev.display_name()} moved to history "
                               f"(expired)", ("device", dev.key), dev.key)
        yield "lifecycle"
        for f in self.flows.expire(now):
            pass
        self.dns.expire(now)
        yield "expiry"
        self._check_dns(now)
        self._check_broadcast(now)
        self._check_scans(now)
        yield "checks"
        for dev in list(self.registry.by_key.values()):
            if dev.state != STATE_ACTIVE or not dev.live:
                continue
            if dev.confidence in (CONFIDENCE_LOW, CONFIDENCE_UNCONFIRMED) \
                    and dev.packets >= int(self.config.get(
                        "alerts.unknown_min_packets", 5)) and \
                    not dev.expected:
                self._alert(self.alerts.unknown_device(dev))
        yield "unknown devices"
        for keep, other in self.registry.auto_merge_pass():
            dev = self.registry.by_key.get(keep)
            self.dirty_devices.add(keep)
            if dev:
                self.push_timeline("identity merged", "INFO",
                                   f"{dev.display_name()}: two identities "
                                   f"combined (automatic)",
                                   ("device", keep), keep)
        yield "merges"
        if self.config.get("devices.suggest_merges", True):
            self._suggest_merges()
        yield "merge suggestions"
        self._apply_cache_names()
        yield "names"
        self._classify()
        yield "classify"
        active = sum(1 for d in self.registry.by_key.values()
                     if d.live and d.state in (STATE_ACTIVE, STATE_IDLE))
        self.metrics.series["active_devices"].add(now, active)
        self._detect_vpn()
        yield "vpn"
        for key, b in list(self.baselines.devices.items()):
            if b.cur_min is not None and int(now // 60) > b.cur_min + 1:
                dev = self.registry.by_key.get(key)
                snap = b.finish()
                b.cur_min = None
                if dev is not None and dev.live:
                    self._baseline_check(dev, snap)
        for k, exp in list(self.own_probe_targets.items()):
            if exp < now:
                self.own_probe_targets.pop(k, None)
        for kind, sev, text, key in self.registry.events:
            self.push_timeline(kind, sev, text, ("device", key), key)
            self.dirty_devices.add(key)
        self.registry.events = []
        self._announce_created()

    def _check_dns(self, now):
        rate, n = self.dns.failure_rate(now)
        if n >= 20 and rate >= 0.3:
            servers = [ip for ip, *_ in self.dns.summary_rows()[:3]]
            self._alert(self.alerts.dns_failures(rate, n, servers))
        med, n = self.dns.median_latency(now)
        slow = float(self.config.get("dns.slow_ms", 800))
        if med is not None and n >= 10 and med >= slow:
            rows = self.dns.summary_rows()
            self._alert(self.alerts.dns_slow(med, n, rows[0][0] if rows
                                             else ""))
        ext = [ip for ip in self.dns.servers
               if ip != self.gateway_ip and ip not in self.dhcp_dns]
        if len(ext) > 3:
            self._alert(self.alerts.dns_multi(ext))

    def _check_broadcast(self, now):
        thr = float(self.config.get("alerts.broadcast_pps_threshold", 400))
        pps = self.metrics.series["bcast_packets"].total_window(
            1, 10, now, skip_current=True) / 10.0
        if pps >= thr:
            recent = Counter(src for t, src in self.bcast_talkers
                             if now - t <= 10)
            top = recent.most_common(1)
            who = ""
            if top:
                dev = self.registry.by_key.get(top[0][0]) or \
                    self.device_for(top[0][0])
                who = dev.display_name() if dev else top[0][0]
            self._alert(self.alerts.broadcast_storm(pps, who))

    def _check_scans(self, now):
        pt = int(self.config.get("alerts.scan_ports_threshold", 60))
        ht = int(self.config.get("alerts.scan_hosts_threshold", 40))
        for key, dq in list(self.scans.attempts.items()):
            while dq and now - dq[0][0] > 60:
                dq.popleft()
            if len(dq) < min(pt, ht):
                if not dq:
                    self.scans.forget(key)
                continue
            res = self.scans.evaluate(key, pt, ht)
            dev = self.registry.by_key.get(key)
            if res and dev is not None and dev.live:
                self._alert(self.alerts.scan_pattern(dev, res[0], res[1]))

    def _suggest_merges(self):
        pool = self.registry.merge_pool()
        for dev in list(self.registry.by_key.values()):
            if not dev.live or dev.pinned_no_merge:
                continue
            if not (dev.dhcp_hostname or dev.mdns_name or dev.alias):
                continue
            for other, conf, reasons in self.registry.merge_candidates(
                    dev, pool(dev)):
                pair = other.key
                if pair in dev.suggested or dev.key in other.suggested:
                    continue
                dev.suggested.add(pair)
                other.suggested.add(dev.key)
                self.push_timeline(
                    "possible duplicate", "INFO",
                    f"Possibly the same device: {dev.display_name()} and "
                    f"{other.display_name()} ({conf} confidence) — open "
                    f"either device to merge them", ("device", dev.key),
                    dev.key)

    def _apply_cache_names(self):
        if self.cache.version == self._cache_version:
            return
        self._cache_version = self.cache.version
        for dev in list(self.registry.by_key.values()):
            for ip in [dev.ip] + sorted(dev.ipv6)[:2]:
                if not ip:
                    continue
                name = self.cache.get(ip)
                if not name:
                    continue
                src = self.cache.source(ip)
                src = {"dns": "rdns", "sni": ""}.get(src, src)
                if not src:
                    continue
                if src == "mdns":
                    short = name[:-6] if name.lower().endswith(".local") \
                        else name
                    if not dev.mdns_name and short:
                        dev.mdns_name = short
                        self._dirty_dev(dev)
                    break
                if self.registry.set_hostname(ip, name, src):
                    self._dirty_dev(dev)
                break

    def _classify(self):
        keys, self._classify_dirty = self._classify_dirty, set()
        for key in keys:
            dev = self.registry.by_key.get(key)
            if dev is None:
                continue
            cls, word, reasons = classify_device(
                dev, self.gateway_ip, self.my_ips, self.my_macs,
                self.registry.ra_routers, self.registry.gw_macs)
            if dev.user_class:
                auto = f"{word} {cls}".strip()
                reasons = ["You set this type"] + (
                    [f"Detection alone suggests: {auto}"]
                    if cls not in ("Unknown", dev.user_class) else [])
                cls, word = dev.user_class, ""
            elif word != "Likely" and not getattr(self, "demo", False) and \
                    not dev.demo and \
                    self.config.get("devices.learn_types", True):
                hit = learned_types().match(dev)
                if hit:
                    cls = hit["cls"]
                    word = "Likely" if hit["score"] >= 5 else "Possibly"
                    reasons = [f"Looks like {hit['from']}, which you said is "
                               f"a {hit['cls']} ({hit['why']})"] + reasons
            if cls != dev.device_class or word != dev.class_confidence:
                dev.device_class, dev.class_confidence = cls, word
                dev.class_reasons = reasons
                dev.type = CLASS_TO_TYPE.get(cls, "unknown")
                if dev.type == "unknown" and dev.type_hint:
                    dev.type = dev.type_hint
                self.dirty_devices.add(key)
            else:
                dev.class_reasons = reasons

    def _detect_vpn(self):
        total = self.metrics.totals["bytes_up"] + \
            self.metrics.totals["bytes_down"]
        if not self.vpn_bytes or total < 512 * 1024:
            return
        ip, b = self.vpn_bytes.most_common(1)[0]
        if b >= 0.5 * total and b >= 512 * 1024:
            rec = self.remote_hosts.get(ip)
            kind = ""
            if rec:
                for p in rec.ports:
                    if p in VPN_PORTS:
                        kind = VPN_PORTS[p]
                        break
                if rec.vpn_endpoint != (kind or "VPN"):
                    rec.vpn_endpoint = kind or "VPN"
                    self.dirty_remotes.add(ip)
            if self.vpn.get("endpoint") != ip:
                self.vpn.update({"endpoint": ip, "kind": kind or "VPN"})
                self.push_timeline("vpn", "INFO",
                                   f"Most Internet traffic goes to {ip}, "
                                   f"which looks like a {kind or 'VPN'} "
                                   f"server", ("remote", ip))

    def infer_gateway(self):
        """For imported captures: work out which address is the router,
        from DHCP 'router' options or from where Internet traffic flows."""
        if self.dhcp_routers:
            return self.dhcp_routers.most_common(1)[0][0]
        if self.gw_mac_traffic:
            mac = self.gw_mac_traffic.most_common(1)[0][0]
            dev = self.registry.by_key.get(mac)
            if dev is not None and dev.ip:
                return dev.ip
        return ""

    def note_probes(self, probes, until):
        for host, port in probes:
            self.own_probe_targets[(host, port)] = until

    # ---- clearing -------------------------------------------------------------
    def has_data(self):
        return bool(self.count or self.registry.by_key or self.websites)


