CURRENT_LOCALE = "en"
LOCALE_NAMES = {"en": "English", "fr": "Fran\u00e7ais", "es": "Espa\u00f1ol"}


def tr(key, **kwargs):
    """Translate a UI string. Falls back to English, then to the raw key,
    so a missing translation never breaks the UI."""
    text = STRINGS.get(CURRENT_LOCALE, {}).get(key) or \
        STRINGS["en"].get(key, key)
    return text.format(**kwargs) if kwargs else text


def set_locale(name):
    """Accepts a display name ("Français") or a code ("fr"); anything else
    means English. Returns the code now in use."""
    global CURRENT_LOCALE
    for code, display in LOCALE_NAMES.items():
        if name in (display, code):
            CURRENT_LOCALE = code
            return code
    CURRENT_LOCALE = "en"
    return "en"


