_I18N_PATTERNS_RX = [(re.compile(r"\A" + p + r"\Z", re.S), fr, es)
                     for p, fr, es in I18N_PATTERNS]
_I18N_CORE = re.compile(
    r"\A([^A-Za-z0-9\u00c0-\u024f\u201c\"(\u00bf\u00a1]*)(.*?)"
    r"((?:\.\.\.|[\s:\u2026\u25be\u203a])*)\Z", re.S)
I18N_REVERSE = {}          # shown translation -> English source
_I18N_CACHE = {}


def _i18n_lookup(s, table, loc):
    hit = table.get(s)
    if hit is not None:
        return hit
    tries = [("", s, "")]
    m = _I18N_CORE.match(s)
    if m and m.group(2) and (m.group(1) or m.group(3)):
        tries.append((m.group(1), m.group(2), m.group(3)))
        hit = table.get(m.group(2))
        if hit is not None:
            return m.group(1) + hit + m.group(3)
    for pre, core, post in tries:
        for rx, fr, es in _I18N_PATTERNS_RX:
            mm = rx.match(core)
            if not mm:
                continue
            tpl = fr if loc == "fr" else es
            if tpl is None:              # numbered title: "3. Something"
                rest = _i18n_lookup(mm.group(2), table, loc)
                if rest is None:
                    break
                return f"{pre}{mm.group(1)}. {rest}{post}"
            out = mm.expand(tpl)
            if "{t" in out:              # {tN}: group N, itself translated
                for i, g in enumerate(mm.groups(), 1):
                    tok = "{t%d}" % i
                    if tok in out:
                        sub = g or ""
                        if sub:
                            sub = _i18n_lookup(sub, table, loc) or sub
                        out = out.replace(tok, sub)
            return pre + out + post
    # "Title — explanation": both halves known
    for pre, core, post in tries:
        if " \u2014 " in core:
            a, b = core.split(" \u2014 ", 1)
            ta, tb = table.get(a), _i18n_lookup(b, table, loc)
            if ta is not None and tb is not None:
                return f"{pre}{ta} \u2014 {tb}{post}"
    return None


def translate_text(s, locale=None):
    """English UI text -> the current language (unchanged when English,
    unknown, or not text)."""
    loc = locale or CURRENT_LOCALE
    if loc == "en" or not isinstance(s, str) or not s or len(s) > 2000:
        return s
    table = I18N.get(loc)
    if not table:
        return s
    key = (loc, s)
    out = _I18N_CACHE.get(key)
    if out is None:
        out = _i18n_lookup(s, table, loc)
        if out is None:
            out = s
        if len(_I18N_CACHE) > 20000:
            _I18N_CACHE.clear()
        _I18N_CACHE[key] = out
        if out is not s:
            if len(I18N_REVERSE) > 50000:
                I18N_REVERSE.clear()
            I18N_REVERSE[out] = s
    return out


def translate_lines(text, locale=None):
    """Translate a multi-line report line by line (values stay as they
    are; lines without a translation stay English)."""
    if (locale or CURRENT_LOCALE) == "en" or not isinstance(text, str):
        return text
    return "\n".join(translate_text(line, locale) if line.strip() else line
                     for line in text.split("\n"))


_CELL_WORDS = []
_CELL_CACHE = {}


def translate_cell(v):
    """A table cell in the current language — only the fixed words a
    table shows (states, confidence, device kinds, what a connection is
    for, "Private address"), never names, addresses or numbers: those
    are the user's data and filters read them back. Exact lookups only,
    so a table of thousands of rows costs a dictionary hit per cell."""
    loc = CURRENT_LOCALE
    if loc == "en" or not isinstance(v, str) or not v or len(v) > 60:
        return v
    key = (loc, v)
    out = _CELL_CACHE.get(key)
    if out is not None:
        return out
    if not _CELL_WORDS:
        words = {"High", "Medium", "Low", "Unconfirmed", "Unknown",
                 "Private address", "Your router / gateway", "Active",
                 "Idle", "Offline", "Expired", "Online", "Closing",
                 "Closed", "Open", "Encrypted", "Not encrypted", "INFO",
                 "WARNING", "DANGER", "New", "Acknowledged", "New (saved)",
                 "Acknowledged (saved)"}
        words.update(FRIENDLY_PROTO.values())
        words.update(PORT_SERVICES.values())
        words.update(DEVICE_CLASSES)
        for c in DEVICE_CLASSES:
            words.update((f"Likely {c}", f"Possibly {c}"))
        _CELL_WORDS.append(frozenset(words))
    m = _I18N_CORE.match(v)
    core = m.group(2) if m else v
    out = translate_text(v, loc) if core in _CELL_WORDS[0] else v
    if len(_CELL_CACHE) > 20000:
        _CELL_CACHE.clear()
    _CELL_CACHE[key] = out
    return out


def translate_cells(values):
    if CURRENT_LOCALE == "en" or not isinstance(values, (list, tuple)):
        return values
    return [translate_cell(x) for x in values]


_EVENT_RX = []
_EVENT_CACHE = {}


def translate_event(text):
    """A Timeline / Live feed / alert sentence in the current language:
    the catalog, then only EVENT_PATTERNS (not every pattern), cached.
    Names and addresses inside stay as they are."""
    loc = CURRENT_LOCALE
    if loc == "en" or not isinstance(text, str) or not text or \
            len(text) > 400:
        return text
    key = (loc, text)
    out = _EVENT_CACHE.get(key)
    if out is not None:
        return out
    if not _EVENT_RX:
        _EVENT_RX.extend((re.compile(r"\A" + p + r"\Z", re.S), fr, es)
                         for p, fr, es in EVENT_PATTERNS)
    table = I18N.get(loc) or {}
    m = _I18N_CORE.match(text)
    pre, core, post = (m.group(1), m.group(2), m.group(3)) if m else \
        ("", text, "")
    hit = table.get(core)
    if hit is None:
        for rx, fr, es in _EVENT_RX:
            mm = rx.match(core)
            if not mm:
                continue
            hit = mm.expand(fr if loc == "fr" else es)
            if "{t" in hit:
                for i, g in enumerate(mm.groups(), 1):
                    tok = "{t%d}" % i
                    if tok in hit:
                        hit = hit.replace(tok, table.get(g or "", g or ""))
            break
    out = pre + hit + post if hit is not None else text
    if len(_EVENT_CACHE) > 20000:
        _EVENT_CACHE.clear()
    _EVENT_CACHE[key] = out
    return out


def untranslate_text(s):
    """Shown text -> its English source (unchanged when not a translation)."""
    if not isinstance(s, str):
        return s
    return I18N_REVERSE.get(s, s)


_I18N_KEYS = ("text", "label", "message", "detail", "title")
_I18N_HOOKED = []


def _i18n_cnf(cnf):
    if not cnf:
        return cnf
    hit = [k for k in _I18N_KEYS if isinstance(cnf.get(k), str)]
    if not hit:
        return cnf
    cnf = dict(cnf)
    for k in hit:
        cnf[k] = translate_text(cnf[k])
    return cnf


def _i18n_fit_heading(tree, column, text):
    """Widen a table column so a longer translated heading isn't cut."""
    try:
        need = text_width(tkfont.nametofont("TkHeadingFont"), text) + 18
        if int(tree.column(column, "width")) < need:
            tree.column(column, width=need)
    except (tk.TclError, ValueError, TypeError):
        pass


def install_i18n_hooks():
    """Route every widget's visible text through translate_text(). Costs one
    comparison per call while the language is English."""
    if _I18N_HOOKED:
        return
    orig_options = tk.Misc._options

    def _options(self, cnf, kw=None):
        if CURRENT_LOCALE != "en":
            try:
                merged = tk._cnfmerge((cnf, kw)) if kw else tk._cnfmerge(cnf)
            except (TypeError, AttributeError):
                return orig_options(self, cnf, kw)
            if isinstance(merged, dict):
                return orig_options(self, _i18n_cnf(merged))
        return orig_options(self, cnf, kw)
    tk.Misc._options = _options

    orig_title = tk.Wm.wm_title

    def wm_title(self, string=None):
        if string is not None and CURRENT_LOCALE != "en":
            string = translate_text(string)
        return orig_title(self, string)
    tk.Wm.wm_title = tk.Wm.title = wm_title

    def wrap_kw(cls, name):
        orig = getattr(cls, name)

        def method(self, *a, **kw):
            if CURRENT_LOCALE != "en" and isinstance(kw.get("text"), str):
                src = kw["text"]
                kw["text"] = translate_text(src)
                if kw["text"] != src and name == "heading" and a:
                    out = orig(self, *a, **kw)
                    _i18n_fit_heading(self, a[0], kw["text"])
                    return out
            return orig(self, *a, **kw)
        method.__doc__ = orig.__doc__
        setattr(cls, name, method)
    for cls, name in ((ttk.Notebook, "add"), (ttk.Notebook, "insert"),
                      (ttk.Notebook, "tab"), (ttk.Treeview, "heading")):
        wrap_kw(cls, name)

    # 5.1.2: table cells with fixed words ("Active", "High", what a
    # connection is for) in the current language
    for name in ("insert", "item"):
        orig_tv = getattr(ttk.Treeview, name)

        def tv_method(self, *a, _orig=orig_tv, **kw):
            if CURRENT_LOCALE != "en" and "values" in kw:
                kw["values"] = translate_cells(kw["values"])
            return _orig(self, *a, **kw)
        tv_method.__doc__ = orig_tv.__doc__
        setattr(ttk.Treeview, name, tv_method)

    orig_column = ttk.Treeview.column

    def column(self, col, option=None, **kw):
        out = orig_column(self, col, option, **kw)
        if kw.get("width") is not None and CURRENT_LOCALE != "en":
            try:
                text = self.heading(col, "text")
            except tk.TclError:
                text = ""
            if text and text != untranslate_text(text):
                _i18n_fit_heading(self, col, text)
        return out
    column.__doc__ = orig_column.__doc__
    ttk.Treeview.column = column

    # read-only drop-downs: the program's variable keeps the English value,
    # the box shows (and accepts) the current language
    orig_combo = ttk.Combobox.__init__

    def combo_init(self, master=None, **kw):
        var, vals = kw.get("textvariable"), kw.get("values")
        if not (isinstance(var, tk.StringVar) and
                not isinstance(var, DisplayVar) and
                isinstance(vals, (list, tuple)) and vals and
                all(isinstance(v, str) for v in vals) and
                str(kw.get("state", "")) == "readonly"):
            return orig_combo(self, master, **kw)
        info = {"var": var, "values": list(vals)}
        shown = tk.StringVar(master, value=translate_text(var.get()))
        info["shown"] = shown

        def to_var(*_):
            val = shown.get()
            for v in info["values"]:
                if translate_text(v) == val:
                    val = v
                    break
            if var.get() != val:
                var.set(val)

        def to_shown(*_):
            val = translate_text(var.get())
            if shown.get() != val:
                shown.set(val)
        shown.trace_add("write", to_var)
        var.trace_add("write", to_shown)
        kw["textvariable"] = shown
        kw["values"] = [translate_text(v) for v in vals]
        width = kw.get("width")
        if isinstance(width, int) and width > 0:
            kw["width"] = max(width, max(len(v) for v in kw["values"]) + 1)
        orig_combo(self, master, **kw)
        self._mw_i18n = info
    combo_init.__doc__ = orig_combo.__doc__
    ttk.Combobox.__init__ = combo_init
    _I18N_HOOKED.append(True)


def i18n_retranslate(root):
    """Re-label every open window after the language changes: each shown
    text goes back to its English source and through the hook again."""
    count = 0
    stack = [root]
    while stack:
        w = stack.pop()
        try:
            stack.extend(w.winfo_children())
        except tk.TclError:
            continue
        try:
            if isinstance(w, (tk.Tk, tk.Toplevel)):
                w.title(untranslate_text(w.title()))
            if isinstance(w, tk.Menu):
                end = w.index("end")
                for i in range(0 if end is None else end + 1):
                    if w.type(i) in ("command", "cascade", "checkbutton",
                                     "radiobutton"):
                        lab = w.entrycget(i, "label")
                        w.entryconfigure(i, label=untranslate_text(lab))
                continue
            if isinstance(w, ttk.Notebook):
                for t in w.tabs():
                    w.tab(t, text=untranslate_text(w.tab(t, "text")))
            elif isinstance(w, ttk.Combobox) and \
                    getattr(w, "_mw_i18n", None):
                info = w._mw_i18n
                w.configure(values=[translate_text(v)
                                    for v in info["values"]])
                info["shown"].set(translate_text(info["var"].get()))
            elif isinstance(w, ttk.Treeview):
                for c in ("#0",) + tuple(w["columns"]):
                    w.heading(c, text=untranslate_text(w.heading(c, "text")))
            elif isinstance(w, tk.Canvas):
                for item in w.find_all():
                    if w.type(item) == "text":
                        w.itemconfigure(item, text=untranslate_text(
                            w.itemcget(item, "text")))
            keys = w.keys()
            if "text" in keys and "textvariable" in keys and \
                    not str(w.cget("textvariable")):
                cur = w.cget("text")
                if isinstance(cur, str) and cur:
                    w.configure(text=untranslate_text(cur))
                    count += 1
        except (tk.TclError, TypeError, ValueError):
            continue
    return count


class DisplayVar(tk.StringVar):
    """A StringVar for text that is only shown (status lines, card values):
    whatever is set is shown in the current language. Never use it for a
    value the program reads back as a setting."""

    @staticmethod
    def shown(value):
        if not isinstance(value, str):
            return value
        out = translate_text(value)
        if out == value and "\n" in value:     # an info block: line by line
            out = translate_lines(value)
        return out

    def __init__(self, master=None, value=None, name=None):
        super().__init__(master, self.shown(value), name)

    def set(self, value):
        # 5.1.2: setting the same text again made Tk lay out and redraw
        # its label anyway; the Dashboard alone does this ~15 times every
        # 2 s, so an unchanged text is not written again
        shown = self.shown(value)
        try:
            if isinstance(shown, str) and super().get() == shown and \
                    not self.trace_info():
                return None
        except (tk.TclError, RuntimeError):
            pass
        return super().set(shown)


# ---- V5.0.2: layout that survives small screens, long translations and
#      large text ---------------------------------------------------------------
#  Three generic pieces, all installed once at start-up:
#   · FlowLayout: a row of buttons/fields that wraps onto a second line when
#     the window is too narrow, instead of squeezing the last widgets down
#     to nothing (Tk's pack never wraps).
#   · autowrap: every label created with a wraplength re-wraps to the width
#     it actually gets, so its right side is never cut off.
#   · headings: a table heading is never narrower than its text.
_SMALL_CLASSES = {"TButton", "Button", "Label", "TLabel", "TCheckbutton",
                  "Checkbutton", "TRadiobutton", "Radiobutton", "TEntry",
                  "Entry", "TCombobox", "TMenubutton", "Menubutton",
                  "TSpinbox", "Spinbox"}
_INPUT_CLASSES = {"TEntry", "Entry", "TCombobox", "TSpinbox", "Spinbox"}


def _pad_pair(v):
    try:
        if isinstance(v, (tuple, list)):
            a = [int(float(str(x))) for x in v]
        else:
            a = [int(float(x)) for x in str(v).split()]
    except (TypeError, ValueError):
        return 0, 0
    if not a:
        return 0, 0
    return (a[0], a[1]) if len(a) > 1 else (a[0], a[0])


class FlowLayout:
    """Lays out a frame's children left to right and wraps them onto more
    rows when the frame is narrower than they need. Children keep using
    pack()/pack_forget(): the hooks below route those calls here."""

    def __init__(self, frame):
        self.f = frame
        self.items = []          # dicts: w, side, padx, pady, expand
        self._job = None
        self._last = None
        frame._mw_flow = self
        for w in frame.pack_slaves():
            info = _ORIG_PACK["info"](w)
            self.items.append(self._item(w, info))
            _ORIG_PACK["forget"](w)
        frame.bind("<Configure>", self._on_conf, add="+")
        for it in self.items:
            self._watch(it["w"])
        self.schedule()

    @staticmethod
    def _item(w, info):
        return {"w": w, "side": str(info.get("side", "left")),
                "padx": _pad_pair(info.get("padx", 0)),
                "pady": _pad_pair(info.get("pady", 0)),
                "expand": str(info.get("expand", 0)) in ("1", "True",
                                                         "true", "yes"),
                "shown": True}

    def _watch(self, w):
        if not getattr(w, "_mw_flow_watched", False):
            w._mw_flow_watched = True
            w.bind("<Configure>", lambda e: self.schedule(), add="+")

    def _on_conf(self, e):
        if (e.width, e.height) != self._last:
            self.schedule()

    def schedule(self):
        if self._job is None:
            try:
                self._job = self.f.after_idle(self.relayout)
            except (tk.TclError, RuntimeError):
                self._job = None

    def find(self, w):
        for it in self.items:
            if it["w"] is w:
                return it
        return None

    def pack_child(self, w, kw):
        it = self.find(w)
        info = {"side": kw.get("side", it["side"] if it else "left"),
                "padx": kw.get("padx", 0), "pady": kw.get("pady", 0),
                "expand": kw.get("expand", 0)}
        new = self._item(w, info)
        if it is not None:
            self.items.remove(it)
        ref = kw.get("before") or kw.get("after")
        pos = len(self.items)
        if ref is not None:
            for i, x in enumerate(self.items):
                if x["w"] is ref:
                    pos = i if kw.get("before") is not None else i + 1
                    break
        self.items.insert(pos, new)
        self._watch(w)
        self.schedule()

    def hide(self, w):
        it = self.find(w)
        if it is not None:
            it["shown"] = False
            with contextlib.suppress(tk.TclError):
                w.place_forget()
            self.schedule()

    def _units(self, items):
        """Keep a "Label:" together with the field after it."""
        units, i = [], 0
        while i < len(items):
            it = items[i]
            if i + 1 < len(items):
                nxt = items[i + 1]
                try:
                    lab = it["w"].winfo_class() in ("Label", "TLabel") and \
                        str(it["w"].cget("text")).rstrip().endswith(
                            (":", "：")) and \
                        nxt["w"].winfo_class() in _INPUT_CLASSES
                except tk.TclError:
                    lab = False
                if lab:
                    units.append([it, nxt])
                    i += 2
                    continue
            units.append([it])
            i += 1
        return units

    @staticmethod
    def _wid(it):
        w = it["w"]
        return w.winfo_reqwidth() + it["padx"][0] + it["padx"][1]

    def _inner(self):
        """(left, top, right, bottom) padding inside the frame itself."""
        f = self.f
        try:
            if isinstance(f, ttk.Frame):
                raw = f.cget("padding")
                if isinstance(raw, (tuple, list)):
                    p = [_int(x) for x in raw]
                else:
                    p = [_int(x) for x in str(raw or "").split()]
                if not p:
                    return (0, 0, 0, 0)
                if len(p) == 1:
                    p = p * 4
                elif len(p) == 2:
                    p = [p[0], p[1], p[0], p[1]]
                elif len(p) == 3:
                    p = [p[0], p[1], p[2], p[1]]
                return tuple(p[:4])
            px, py = _int(f.cget("padx")), _int(f.cget("pady"))
            b = _int(f.cget("bd")) + _int(f.cget("highlightthickness"))
            return (px + b, py + b, px + b, py + b)
        except (tk.TclError, ValueError):
            return (0, 0, 0, 0)

    def relayout(self):
        self._job = None
        f = self.f
        try:
            if not f.winfo_exists():
                return
            items = [it for it in self.items if it["shown"] and
                     it["w"].winfo_exists()]
            pl, pt, pr, pb = self._inner()
            natural = sum(self._wid(it) for it in items)
            W = f.winfo_width() - pl - pr
            if f.winfo_width() <= 1:
                W = natural
            lefts = [it for it in items if it["side"] != "right"]
            rights = [it for it in items if it["side"] == "right"]
            rows = [[]]          # each: list of (it, x, w)
            x = xmin = 0         # xmin: a stretching label may shrink
            for unit in self._units(lefts):
                umin = sum(min(self._wid(it), 260) if it["expand"]
                           else self._wid(it) for it in unit)
                if xmin > 0 and xmin + umin > W:
                    rows.append([])
                    x = xmin = 0
                for it in unit:
                    wd = self._wid(it)
                    rows[-1].append([it, x, wd])
                    x += wd
                xmin += umin
            # right-hand items, the first packed is the right-most
            left_end = xmin
            xr = W
            for it in rights:
                wd = self._wid(it)
                if xr - wd < left_end and (xr < W or left_end > 0):
                    rows.append([])
                    left_end, xr = 0, W
                xr -= wd
                rows[-1].append([it, xr, wd])
            # an expanding item takes what is left of its row; anything
            # wider than the frame is clamped to it
            for row in rows:
                used = sum(r[2] for r in row)
                flex = [r for r in row if r[0]["expand"]]
                if flex and W > used:
                    extra = (W - used) // len(flex)
                    shift = 0
                    for r in sorted((r for r in row
                                     if r[0]["side"] != "right"),
                                    key=lambda r: r[1]):
                        r[1] += shift
                        if r in flex:
                            r[2] += extra
                            shift += extra
                elif flex and used > W:
                    over = used - W
                    for r in flex:
                        cut = min(over, max(0, r[2] - 120))
                        r[2] -= cut
                        over -= cut
                    xx = 0
                    for r in sorted((r for r in row
                                     if r[0]["side"] != "right"),
                                    key=lambda r: r[1]):
                        r[1] = xx
                        xx += r[2]
            y = 0
            for row in rows:
                if not row:
                    continue
                h = max(r[0]["w"].winfo_reqheight() + sum(r[0]["pady"])
                        for r in row)
                for it, rx, wd in row:
                    w = it["w"]
                    inner = wd - it["padx"][0] - it["padx"][1]
                    clamp = min(inner, W - it["padx"][0] - it["padx"][1])
                    kw = {"x": max(0, rx) + it["padx"][0],
                          "y": y + it["pady"][0] + max(
                              0, (h - sum(it["pady"]) -
                                  w.winfo_reqheight()) // 2)}
                    if it["expand"] or clamp < w.winfo_reqwidth():
                        kw["width"] = max(20, clamp)
                        w._mw_flex = True
                    else:
                        # back to its own width (a width set earlier would
                        # otherwise stay and overlap the next widget)
                        kw["width"] = ""
                        w._mw_flex = False
                    _ORIG_PLACE(w, **kw)
                    with contextlib.suppress(tk.TclError):
                        w.lift()
                y += h
            hh, ww = y + pt + pb, natural + pl + pr
            if _int(f.cget("height")) != hh or _int(f.cget("width")) != ww:
                f.configure(height=max(1, hh), width=max(1, ww))
            self._last = (f.winfo_width(), f.winfo_height())
        except tk.TclError:
            pass


_ORIG_PACK = {}
_ORIG_PLACE = None


def _int(v):
    try:
        return int(float(str(v) or 0))
    except (TypeError, ValueError):
        return 0


def _flow_of(w, kw=None):
    m = (kw or {}).get("in_") or (kw or {}).get("in") or w.master
    return getattr(m, "_mw_flow", None)


def install_layout_hooks():
    global _ORIG_PLACE
    if _ORIG_PACK:
        return
    _ORIG_PACK["configure"] = tk.Pack.pack_configure
    _ORIG_PACK["forget"] = tk.Pack.pack_forget
    _ORIG_PACK["info"] = tk.Pack.pack_info
    _ORIG_PLACE = tk.Place.place_configure

    def pack_configure(self, cnf=None, **kw):
        kw = dict(tk._cnfmerge((cnf, kw))) if cnf else kw
        fl = _flow_of(self, kw)
        if fl is not None and kw.get("side", "left") in ("left", "right"):
            fl.pack_child(self, kw)
            return None
        return _ORIG_PACK["configure"](self, **kw)

    def pack_forget(self):
        fl = _flow_of(self)
        if fl is not None and fl.find(self) is not None:
            return fl.hide(self)
        return _ORIG_PACK["forget"](self)
    tk.Pack.pack_configure = tk.Pack.pack = pack_configure
    tk.Pack.pack_forget = tk.Pack.forget = pack_forget
    for cls in (tk.Widget,):
        cls.pack = cls.pack_configure = pack_configure
        cls.pack_forget = pack_forget
        cls.forget = pack_forget

    # labels with a wraplength re-wrap to the width they really get
    orig_options = tk.Misc._options

    def _options(self, cnf, kw=None):
        out = orig_options(self, cnf, kw)
        if isinstance(self, (tk.Label, ttk.Label)) and \
                not getattr(self, "_mw_wrapping", False):
            try:
                merged = tk._cnfmerge((cnf, kw)) if kw else cnf
                wl = merged.get("wraplength") if isinstance(merged,
                                                            dict) else None
            except (TypeError, AttributeError):
                wl = None
            if wl is not None:
                # set by the program (now or later): that is the widest
                # it may wrap; autowrap only narrows it when it is cut off
                try:
                    self._mw_wrap0 = int(float(str(wl) or 0))
                except (TypeError, ValueError):
                    self._mw_wrap0 = 0
                if self._mw_wrap0 > 0:
                    _autowrap_install(self.master)
                    # set on a label already on screen: its width will not
                    # change, so no <Configure> comes — check it once
                    try:
                        if self.winfo_exists():
                            self.after_idle(lambda w=self: _autowrap(
                                _WrapEvent(w)))
                    except tk.TclError:
                        pass
        return out
    tk.Misc._options = _options

    # table headings are never narrower than their text
    orig_heading = ttk.Treeview.heading

    def heading(self, column, option=None, **kw):
        out = orig_heading(self, column, option, **kw)
        if isinstance(kw.get("text"), str) and kw["text"]:
            fit_heading(self, column)
        return out
    heading.__doc__ = orig_heading.__doc__
    ttk.Treeview.heading = heading
    orig_column = ttk.Treeview.column

    def column(self, col, option=None, **kw):
        out = orig_column(self, col, option, **kw)
        if kw.get("width") is not None:
            fit_heading(self, col)
        return out
    column.__doc__ = orig_column.__doc__
    ttk.Treeview.column = column


_HEADING_W = {}         # (heading font size, text) -> pixels (5.1.2)


_HEADING_FONT = {}


def heading_font():
    """The font table headings are really drawn in: the Treeview.Heading
    style's (5.1.2: measuring TkHeadingFont left headings tight or cut
    at 150 %, where the two differ), TkHeadingFont when it names none."""
    try:
        spec = ttk.Style().lookup("Treeview.Heading", "font")
    except tk.TclError:
        spec = ""
    if not spec:
        return tkfont.nametofont("TkHeadingFont"), "TkHeadingFont"
    f = _HEADING_FONT.get(spec)
    if f is None:
        try:
            f = _HEADING_FONT[spec] = tkfont.Font(font=spec)
        except (tk.TclError, RuntimeError):
            return tkfont.nametofont("TkHeadingFont"), "TkHeadingFont"
    return f, spec


def heading_width(text):
    """Pixel width of a heading text. Measuring took about 1 ms per call
    (on X), and the same few heading texts repeat across tables."""
    f, spec = heading_font()
    key = (spec, f.cget("size"), f.cget("family"), UI_SCALE[0], text)
    w = _HEADING_W.get(key)
    if w is None:
        if len(_HEADING_W) > 4000:
            _HEADING_W.clear()
        w = _HEADING_W[key] = text_width(f, text)
    return w


class TextWidths:
    """5.1.2 rc.11: the pixel widths of interface texts (table headings,
    Settings page titles), remembered between starts. Tk measures a text
    in about 0.9 ms on Linux (Xft), and a start measured ~200 headings in
    English and ~500 in French (0.2-0.5 s of the window's build).

    Kept per font (its family, size, weight and slant as Tk resolved
    them) and per screen setup (Tk's scaling, windowing system and
    version). On the first use of a font in a process, one probe text is
    measured: a different width (another font installed under the same
    name) throws that font's widths away. Only texts the caller marks as
    interface text are written to disk, never names or addresses seen on
    the network; Safe Mode and the warm_start switch turn it off."""

    PROBE = "MiniWireshark Ag 0123 \u00c9\u00e9\u00d1 \u2014 W"
    MAX_PER_FONT = 3000
    MAX_FONTS = 32
    VERSION = 1

    def __init__(self, path=None):
        self.path = path
        self.fonts = {}          # sig -> {"probe": px, "w": {text: px}}
        self.session = {}        # (sig, text) -> px, not kept
        self.checked = set()
        self.env = None
        self.loaded = False
        self.dirty = False
        self.hits = self.misses = 0

    def on(self):
        return FEATURES.get("warm_start", True) and not SAFE_MODE

    def _path(self):
        return self.path or os.path.join(PATHS.cache, "text_widths.json")

    @staticmethod
    def env_key(widget=None):
        try:
            tkapp = (widget or tk._default_root).tk
            return "|".join(str(x) for x in (
                round(float(tkapp.call("tk", "scaling")), 4),
                tkapp.call("tk", "windowingsystem"),
                tkapp.call("info", "patchlevel"), sys.platform))
        except Exception:                            # noqa: BLE001
            return ""

    _SIGS = {}

    @classmethod
    def font_sig(cls, font):
        """What Tk resolved the font to. `font actual` costs as much as a
        measure (~0.85 ms on Xft), so it is asked once per font name and
        requested options (`font configure`, a few microseconds)."""
        try:
            key = (font.name, tuple(sorted(font.configure().items())))
        except (tk.TclError, AttributeError, RuntimeError):
            key = None
        sig = cls._SIGS.get(key) if key is not None else None
        if sig is not None:
            return sig
        try:
            a = font.actual()
            sig = f"{a.get('family')}|{a.get('size')}|{a.get('weight')}" \
                  f"|{a.get('slant')}"
        except (tk.TclError, AttributeError, RuntimeError):
            return ""
        if key is not None:
            if len(cls._SIGS) > 500:
                cls._SIGS.clear()
            cls._SIGS[key] = sig
        return sig

    def load(self, widget=None):
        """Read the remembered widths (once). → how many."""
        if self.loaded:
            return sum(len(b.get("w", {})) for b in self.fonts.values())
        self.loaded = True
        if not self.on():
            return 0
        self.env = self.env_key(widget)
        data = read_json(self._path(), None)
        if not isinstance(data, dict) or data.get("v") != self.VERSION or \
                data.get("env") != self.env or not self.env:
            return 0
        fonts = data.get("fonts")
        if not isinstance(fonts, dict):
            return 0
        n = 0
        for sig, b in list(fonts.items())[:self.MAX_FONTS]:
            if isinstance(b, dict) and isinstance(b.get("w"), dict) and \
                    isinstance(b.get("probe"), int):
                w = {k: v for k, v in b["w"].items()
                     if isinstance(k, str) and isinstance(v, int)}
                self.fonts[str(sig)] = {"probe": b["probe"], "w": w}
                n += len(w)
        return n

    def width(self, font, text, keep=True):
        if not self.loaded:
            self.load()
        if not self.on():
            return font.measure(text)
        sig = self.font_sig(font)
        if not sig:
            return font.measure(text)
        bucket = self.fonts.get(sig)
        if sig not in self.checked:
            self.checked.add(sig)
            probe = font.measure(self.PROBE)
            if bucket is None or bucket.get("probe") != probe:
                if bucket is not None:
                    self.dirty = True
                bucket = self.fonts[sig] = {"probe": probe, "w": {}}
        got = bucket["w"].get(text)
        if got is None:
            got = self.session.get((sig, text))
        if got is not None:
            self.hits += 1
            return got
        self.misses += 1
        got = font.measure(text)
        if keep and len(text) <= 120 and \
                len(bucket["w"]) < self.MAX_PER_FONT:
            bucket["w"][text] = got
            self.dirty = True
        else:
            if len(self.session) > 20000:
                self.session.clear()
            self.session[(sig, text)] = got
        return got

    def save(self):
        """Write the widths when something new was measured. Quiet."""
        if not self.dirty or not self.on() or not self.env:
            return False
        fonts = dict(list(self.fonts.items())[-self.MAX_FONTS:])
        data = {"v": self.VERSION, "env": self.env, "fonts": fonts}
        try:
            os.makedirs(os.path.dirname(self._path()), exist_ok=True)
            atomic_write_text(self._path(), json.dumps(
                data, ensure_ascii=False, separators=(",", ":")))
        except (OSError, TypeError, ValueError):
            return False
        self.dirty = False
        return True


TEXT_WIDTHS = TextWidths()


def text_width(font, text, keep=True):
    """Pixel width of an interface text in `font`, remembered (between
    starts when keep=True: only for fixed interface texts)."""
    try:
        return TEXT_WIDTHS.width(font, text, keep)
    except (tk.TclError, RuntimeError):
        return font.measure(text)


def fit_heading(tree, col):
    try:
        text = str(tree.heading(col, "text") or "")
        if not text:
            return
        need = heading_width(text) + 20
        if int(tree.column(col, "width")) < need:
            tree.column(col, width=need, minwidth=min(need, 60))
    except (tk.TclError, ValueError, TypeError, RuntimeError):
        pass


def fit_tree_headings(tree):
    try:
        cols = ("#0",) + tuple(tree["columns"])
    except tk.TclError:
        return
    for c in cols:
        fit_heading(tree, c)


def fit_all_headings(root):
    for tree in _walk_class(root, ttk.Treeview):
        fit_tree_headings(tree)


def dialog_contract(win):
    """Every window: Escape closes it, Enter runs its main button (the
    one accent button), unless the window already says otherwise."""
    try:
        if not win.winfo_exists() or win.wm_overrideredirect():
            return False
        if not win.bind("<Escape>"):
            win.bind("<Escape>", lambda e: win.destroy())
        if not win.bind("<Return>"):
            main = [b for b in _walk_class(win, ttk.Button)
                    if str(b.cget("style")) == "Accent.TButton"]
            if len(main) == 1:
                def run(e, b=main[0]):
                    if isinstance(e.widget, tk.Text):
                        return None
                    with contextlib.suppress(tk.TclError):
                        if b.instate(["!disabled"]):
                            b.invoke()
                    return "break"
                win.bind("<Return>", run)
                win.bind("<KP_Enter>", run)
        return True
    except tk.TclError:
        return False


def focus_ring(widget, color="#2b7de9", width=2):
    """A visible ring when a plain widget (a label used as a tab) has the
    keyboard focus. The ring takes the place of padding, so nothing
    moves or grows."""
    try:
        padx = int(str(widget.cget("padx")))
        pady = int(str(widget.cget("pady")))
    except (tk.TclError, ValueError):
        return

    def on(_e=None):
        with contextlib.suppress(tk.TclError):
            widget.configure(highlightthickness=width, highlightcolor=color,
                             highlightbackground=color,
                             padx=max(0, padx - width),
                             pady=max(0, pady - width))

    def off(_e=None):
        with contextlib.suppress(tk.TclError):
            widget.configure(highlightthickness=0, padx=padx, pady=pady)
    widget.bind("<FocusIn>", on, add="+")
    widget.bind("<FocusOut>", off, add="+")
    off()


def _walk_class(root, cls):
    stack = [root]
    while stack:
        w = stack.pop()
        try:
            stack.extend(w.winfo_children())
        except tk.TclError:
            continue
        if isinstance(w, cls):
            yield w


_AUTOWRAP_INTERPS = set()


def _autowrap_install(master):
    """One class binding per Tcl interpreter (the label itself does not
    exist yet while its options are being built)."""
    try:
        key = id(master.tk)
        if key in _AUTOWRAP_INTERPS:
            return
        _AUTOWRAP_INTERPS.add(key)
        for cls in ("Label", "TLabel"):
            master.bind_class(cls, "<Configure>", _autowrap, add="+")
    except (tk.TclError, AttributeError):
        pass


def _label_pad(w):
    try:
        if isinstance(w, ttk.Label):
            return 8
        return 2 * int(float(str(w.cget("padx")))) + \
            2 * int(float(str(w.cget("bd")))) + 6
    except (tk.TclError, ValueError):
        return 8


def _is_flexible(w):
    """Its width comes from the layout, not from its own text."""
    try:
        if getattr(w, "_mw_flex", False):
            return True
        mgr = w.winfo_manager()
        if mgr == "pack":
            info = _ORIG_PACK["info"](w)
            return str(info.get("fill")) in ("x", "both")
        if mgr == "grid":
            st = str(w.grid_info().get("sticky", ""))
            return "e" in st and "w" in st
    except (tk.TclError, KeyError):
        pass
    return False


class _WrapEvent:
    def __init__(self, w):
        self.widget = w
        try:
            self.width = w.winfo_width()
        except tk.TclError:
            self.width = 0


def _autowrap(e):
    w = e.widget
    if isinstance(w, str):
        return
    try:
        orig = getattr(w, "_mw_wrap0", 0)
        if orig <= 0 or e.width <= 30:
            return
        cur = int(float(str(w.cget("wraplength")) or 0))
        pad = _label_pad(w)
        room = max(40, e.width - pad)
        new = cur
        if w.winfo_reqwidth() > e.width + 2:
            new = room                    # clipped: wrap tighter
        elif cur < orig and e.width > w.winfo_reqwidth() + 16:
            new = min(orig, room)         # room again: back towards orig
        if abs(new - cur) > 3:
            # safety net: a label whose container sizes itself from the
            # label could bounce; after 12 changes in 2 s it stays put
            now = time.monotonic()
            hist = [t for t in getattr(w, "_mw_wrap_hist", ())
                    if now - t < 2.0]
            if len(hist) >= 12:
                return
            hist.append(now)
            w._mw_wrap_hist = hist
            w._mw_wrapping = True
            try:
                w.configure(wraplength=new)
            finally:
                w._mw_wrapping = False
    except (tk.TclError, ValueError):
        pass


_FLOW_SKIP = set()


def make_flow(frame):
    """Turn a row of packed widgets into a wrapping row (idempotent)."""
    if getattr(frame, "_mw_flow", None) is None:
        FlowLayout(frame)
    return frame._mw_flow


def _flow_candidate(frame):
    if getattr(frame, "_mw_flow", None) is not None or \
            getattr(frame, "_mw_noflow", False):
        return False
    try:
        slaves = frame.pack_slaves()
        if len(slaves) < 2:
            return False
        if frame.grid_slaves() or frame.place_slaves():
            return False
        small = 0
        for w in slaves:
            info = _ORIG_PACK["info"](w)
            if str(info.get("side")) not in ("left", "right"):
                return False
            if str(info.get("fill")) in ("y", "both"):
                return False
            cls = w.winfo_class()
            if cls in _SMALL_CLASSES:
                small += cls not in ("Label", "TLabel")
                continue
            if cls in ("Frame", "TFrame"):
                kids = w.winfo_children()
                if kids and all(k.winfo_class() in _SMALL_CLASSES
                                for k in kids):
                    small += 1
                    continue
            return False
        if small >= 1:
            return True
        # a row of four or more labels (step lists, legends) wraps too
        return len(slaves) >= 4
    except (tk.TclError, KeyError):
        return False


def protect_bottom(root):
    """Button bars packed after a stretching list or text are squeezed
    first by Tk when the window is short, so their buttons got cut in
    half. Re-pack such trailing rows from the bottom: same order on
    screen, but they keep their height and the list gives way."""
    n = 0
    masters = [root] + list(_walk_class(root, tk.Frame)) + \
        list(_walk_class(root, ttk.Frame)) + \
        list(_walk_class(root, tk.Toplevel))
    for m in masters:
        try:
            slaves = m.pack_slaves()
            infos = [_ORIG_PACK["info"](w) for w in slaves]
        except (tk.TclError, KeyError):
            continue
        exp = None
        for w, info in zip(slaves, infos):
            side = str(info.get("side", "top"))
            if exp is None:
                if side == "top" and str(info.get("expand")) in ("1",
                                                                 "True"):
                    exp = w
                continue
            if side != "top":
                continue
            if str(info.get("expand")) in ("1", "True"):
                exp = None          # a second stretcher: leave it alone
                break
        if exp is None:
            continue
        i = slaves.index(exp)
        trailing = [(w, inf) for w, inf in zip(slaves[i + 1:],
                                                infos[i + 1:])
                    if str(inf.get("side", "top")) == "top"]
        if not trailing or getattr(m, "_mw_flow", None) is not None:
            continue
        for w, inf in reversed(trailing):
            opts = {k: v for k, v in inf.items()
                    if k in ("fill", "padx", "pady", "ipadx", "ipady",
                             "anchor")}
            try:
                _ORIG_PACK["configure"](w, side="bottom", before=exp,
                                        **opts)
                n += 1
            except tk.TclError:
                pass
    return n


def grid_reflow(frame, widgets, max_cols=3, padx=3, pady=3):
    """Lay `widgets` out in as many equal columns as fit (at most
    max_cols); re-done when the frame is resized or a text changes."""
    state = {"cols": None}

    def place(_e=None):
        try:
            W = frame.winfo_width()
            need = max(w.winfo_reqwidth() for w in widgets) + 2 * padx
            cols = max(1, min(max_cols, W // max(1, need))) if W > 1 \
                else max_cols
            if cols == state["cols"]:
                return
            state["cols"] = cols
            for c in range(max_cols):
                frame.columnconfigure(c, weight=1 if c < cols else 0,
                                      uniform="rf" if c < cols else "")
            for i, w in enumerate(widgets):
                w.grid(row=i // cols, column=i % cols, sticky="ew",
                       padx=padx, pady=pady)
        except tk.TclError:
            pass
    frame.bind("<Configure>", place, add="+")
    place()
    return place


_AUDIT_TEXT = {"Label", "TLabel", "Button", "TButton", "Checkbutton",
               "TCheckbutton", "Radiobutton", "TRadiobutton", "Menubutton",
               "TMenubutton"}


def _rect(w):
    return (w.winfo_rootx(), w.winfo_rooty(), w.winfo_width(),
            w.winfo_height())


def _overlap_area(a, b):
    x, y = max(a[0], b[0]), max(a[1], b[1])
    x2 = min(a[0] + a[2], b[0] + b[2])
    y2 = min(a[1] + a[3], b[1] + b[3])
    return max(0, x2 - x) * max(0, y2 - y)


def layout_audit(top):
    """What a person would see as broken: text cut off by its own box or
    by its parent, widgets drawn over each other, chart texts on top of
    each other, table headings cut. → [(kind, widget path, detail)].
    Used by the GUI test (any language, text size and window size) and
    by Diagnostics."""
    out = []
    stack = [top]
    while stack:
        w = stack.pop()
        try:
            if not w.winfo_ismapped() or not w.winfo_viewable():
                continue
            kids = [c for c in w.winfo_children()
                    if not isinstance(c, (tk.Toplevel, tk.Menu))]
            cls = w.winfo_class()
        except tk.TclError:
            continue
        stack.extend(kids)
        try:
            if cls in _AUDIT_TEXT:
                txt = str(w.cget("text"))
                if not txt:
                    var = str(w.cget("textvariable") or "")
                    txt = str(w.getvar(var)) if var else ""
                if txt.strip():
                    r = _rect(w)
                    if 1 < r[2] < w.winfo_reqwidth() - 3:
                        out.append(("clipped-width", str(w), txt[:40]))
                    if 1 < r[3] < w.winfo_reqheight() - 3:
                        out.append(("clipped-height", str(w), txt[:40]))
                    p, inside = w.master, False
                    while p is not None:
                        if isinstance(p, (tk.Canvas, tk.Text)):
                            inside = True
                            break
                        p = p.master
                    if not inside and r[2] > 4 and r[3] > 4:
                        x, y = r[0], r[1]
                        x2, y2 = r[0] + r[2], r[1] + r[3]
                        p = w.master
                        while p is not None:
                            pr = _rect(p)
                            x, y = max(x, pr[0]), max(y, pr[1])
                            x2 = min(x2, pr[0] + pr[2])
                            y2 = min(y2, pr[1] + pr[3])
                            if isinstance(p, (tk.Tk, tk.Toplevel)):
                                break
                            p = p.master
                        if x2 - x < r[2] - 3:
                            out.append(("cut-x", str(w), txt[:40]))
                        if 0 < y2 - y < r[3] - 3:
                            out.append(("cut-y", str(w), txt[:40]))
            if len(kids) > 1 and cls not in ("TPanedwindow", "Panedwindow",
                                             "TNotebook", "Canvas", "Text"):
                rs = [(c, _rect(c)) for c in kids
                      if c.winfo_ismapped() and c.winfo_manager()]
                for i in range(len(rs)):
                    for j in range(i + 1, len(rs)):
                        a, b = rs[i][1], rs[j][1]
                        if a[2] * a[3] and b[2] * b[3] and \
                                _overlap_area(a, b) > 6:
                            out.append(("overlap", str(rs[i][0]),
                                        str(rs[j][0])))
            if cls == "Canvas":
                boxes = []
                for i in w.find_all():
                    if w.type(i) == "text" and w.itemcget(i, "text").strip() \
                            and str(w.itemcget(i, "state")) != "hidden":
                        b = w.bbox(i)
                        if b:
                            boxes.append((i, (b[0], b[1], b[2] - b[0],
                                              b[3] - b[1])))
                for k in range(len(boxes)):
                    for m in range(k + 1, len(boxes)):
                        if _overlap_area(boxes[k][1], boxes[m][1]) > 12:
                            out.append(("canvas-text-overlap", str(w),
                                        w.itemcget(boxes[k][0], "text")[:30]
                                        + " × " +
                                        w.itemcget(boxes[m][0], "text")[:30]))
            if cls == "Treeview":
                # the font the headings are really drawn in (the style's;
                # TkHeadingFont only when the style names none)
                hf = heading_font()[0]
                cols = (["#0"] if "tree" in str(w.cget("show")) else []) + \
                    list(w["columns"])
                disp = w["displaycolumns"]
                if disp and disp[0] != "#all":
                    cols = [c for c in cols if c == "#0" or c in disp]
                for c in cols:
                    txt = str(w.heading(c, "text"))
                    if txt and hf.measure(txt) + 10 > int(w.column(c,
                                                                   "width")):
                        out.append(("heading-cut", str(w), txt))
        except (tk.TclError, ValueError, TypeError):
            continue
    return out


def auto_flow(root):
    """Make every toolbar-like row under `root` wrap when needed."""
    n = 0
    for fr in list(_walk_class(root, tk.Frame)) + \
            list(_walk_class(root, ttk.Frame)):
        if _flow_candidate(fr):
            make_flow(fr)
            n += 1
    return n


install_i18n_hooks()
install_layout_hooks()


