def settings_schema_keys():
    """Every config key the settings window exposes."""
    out = []
    for page in SETTINGS_PAGES:
        for sec in page["sections"]:
            for c in sec["controls"]:
                if c.get("key"):
                    out.append(c["key"])
    return out


def settings_conflicts(values):
    """Non-blocking explanations when two settings pull against each
    other. `values` is {dotted_key: value}."""
    out = []
    if values.get("health.active_checks") and \
            not values.get("mode.active_scanning"):
        out.append("Health checks are on, but Quiet Mode is selected, so "
                   "they will stay paused (Quiet Mode never sends anything).")
    if values.get("privacy.geoip_enabled") and \
            values.get("privacy.local_asn_db"):
        out.append("Both country lookups are on: the offline database is "
                   "used first; the online service only for addresses it "
                   "doesn't cover.")
    if values.get("notifications.danger_only") and \
            not values.get("notifications.feed_alerts"):
        out.append("“Only DANGER in the feed” has no effect while "
                   "alerts are not shown in the feed.")
    if values.get("history.save_raw_packets") and \
            not values.get("history.enabled"):
        out.append("Saving raw packets works even with history off; it "
                   "writes a .pcap to the data folder on exit.")
    if values.get("history.enabled") and \
            values.get("history.retention") == "Session only":
        out.append("History is on but set to “Session only”, so "
                   "nothing will be kept after you close MiniWireshark.")
    return out


def _pretty_seq(seq):
    names = {"Control": "Ctrl", "period": ".", "comma": ",",
             "Return": "Enter", "space": "Space", "slash": "/",
             "minus": "-", "plus": "+", "Escape": "Esc", "Delete": "Del",
             "BackSpace": "Backspace", "Prior": "PageUp", "Next": "PageDown"}
    parts = [p for p in (seq or "").strip("<>").split("-") if p != "Key"]
    return "+".join(names.get(p, p.upper() if len(p) == 1 else p)
                    for p in parts if p)


def _open_path(path):
    try:
        if sys.platform.startswith("win"):
            os.startfile(path)  # type: ignore[attr-defined]
        elif sys.platform == "darwin":
            subprocess.Popen(["open", path])
        else:
            subprocess.Popen(["xdg-open", path])
        return True
    except Exception as e:                           # noqa: BLE001
        # several "Open folder" buttons ignore the answer: leave a trace
        LOG.warning("couldn't open %s: %s", path, e)
        return False



class SettingsWindow:
    """Two-pane settings: categories on the left, one page of grouped
    options on the right, with search, per-page reset, inline validation
    and Apply / OK / Cancel. Built entirely from SETTINGS_PAGES."""

    F_BASE = ("TkDefaultFont", 10)
    F_HELP = ("TkDefaultFont", 9)
    F_SECTION = ("TkDefaultFont", 11, "bold")
    F_TITLE = ("TkDefaultFont", 15, "bold")

    def __init__(self, app, page="general"):
        self.app = app
        self.cfg = app.config
        self.defaults = _default_config()
        self.vars = {}
        self.controls = {}
        for pg in SETTINGS_PAGES:
            for sec in pg["sections"]:
                for c in sec["controls"]:
                    if c.get("key"):
                        self.controls[c["key"]] = c
        self.errors = {}
        self._wrap = []
        self._deps = []
        self._nav = {}
        self._shortcut_prev = {}
        self.page_id = page if any(p["id"] == page for p in SETTINGS_PAGES) \
            else "general"
        self.searching = False
        self.win = tk.Toplevel(app.root)
        self.win.title("Settings")
        sw_, sh_ = app.root.winfo_screenwidth(), app.root.winfo_screenheight()
        w_, h_ = min(940, sw_ - 80), min(720, sh_ - 100)
        x_ = max(0, app.root.winfo_rootx() + (app.root.winfo_width() - w_) // 2)
        y_ = max(0, app.root.winfo_rooty() + 40)
        self.win.geometry(f"{w_}x{h_}+{x_}+{y_}")
        self.win.minsize(min(760, w_), min(520, h_))
        self.win.transient(app.root)
        self._create_vars()
        self.baseline = self._snapshot()
        self._build_chrome()
        self.show_page(self.page_id)
        self.win.bind("<Escape>", lambda e: self.cancel())
        self.win.protocol("WM_DELETE_WINDOW", self.cancel)
        self._tick()

    # ---------------------------------------------------------------- state
    def alive(self):
        try:
            return bool(self.win.winfo_exists())
        except tk.TclError:
            return False

    def sync_key(self, key, value):
        """Another part of the app changed `key`: show it here without
        marking the window as having unsaved changes."""
        var = self.vars.get(key)
        if var is None:
            return
        var.set(value if isinstance(var, tk.BooleanVar) else str(value))
        # this key now matches what's saved; any OTHER pending edits stay
        self.baseline[key] = str(var.get())
        self._refresh_footer()

    @property
    def t(self):
        return self.app.theme

    def _default_for(self, key):
        section, _, name = key.partition(".")
        return self.defaults.get(section, {}).get(name)

    def _create_vars(self):
        for key, c in self.controls.items():
            cur = self.cfg.get(key, self._default_for(key))
            if c["type"] == "bool":
                self.vars[key] = tk.BooleanVar(value=bool(cur))
            else:
                self.vars[key] = tk.StringVar(value="" if cur is None
                                              else str(cur))
            if c["type"] == "shortcut":
                self._shortcut_prev[key] = self.vars[key].get()
            self.vars[key].trace_add(
                "write", lambda *a, k=key: self._on_change(k))

    def _snapshot(self):
        return {k: str(v.get()) for k, v in self.vars.items()}

    def _value_of(self, key):
        c, v = self.controls[key], self.vars[key]
        if c["type"] == "bool":
            return bool(v.get())
        raw = str(v.get()).strip()
        if c["type"] == "int":
            try:
                n = int(float(raw))
            except ValueError:
                n = int(self._default_for(key) or 0)
            return max(c["min"], min(c["max"], n))
        return raw

    def _validate(self, key):
        c, v = self.controls[key], self.vars[key]
        if c["type"] == "int":
            raw = str(v.get()).strip()
            try:
                n = float(raw)
            except ValueError:
                return "Enter a whole number."
            if n != int(n):
                return "Enter a whole number."
            if not c["min"] <= n <= c["max"]:
                return f"Choose a value from {c['min']} to {c['max']}."
        elif c["type"] == "text" and c.get("pattern"):
            raw = str(v.get()).strip()
            if raw and not re.match(c["pattern"], raw):
                return c.get("pattern_msg", "That doesn't look right.")
        elif c["type"] == "path":
            raw = str(v.get()).strip()
            if raw and not os.path.isdir(raw):
                return "That folder doesn't exist."
        elif c["type"] == "shortcut":
            seq = str(v.get()).strip()
            for other, ov in self.vars.items():
                if other != key and self.controls[other]["type"] == "shortcut" \
                        and str(ov.get()).strip() == seq and seq:
                    return (f"Already used by "
                            f"\u201c{self.controls[other]['label']}\u201d.")
        return ""

    def _validate_all(self):
        self.errors = {}
        for key in self.controls:
            msg = self._validate(key)
            if msg:
                self.errors[key] = msg
        msg = self._cross_check()
        if msg:
            self.errors["devices.inactive_minutes"] = msg
        return self.errors

    def _cross_check(self):
        try:
            idle = int(float(self.vars["devices.idle_minutes"].get()))
            off = int(float(self.vars["devices.inactive_minutes"].get()))
            exp = int(float(self.vars["devices.expire_minutes"].get()))
        except (ValueError, KeyError):
            return ""
        if not idle < off < exp:
            return ("\u201cIdle\u201d must be shorter than \u201cOffline\u201d, "
                    "which must be shorter than \u201cExpire\u201d.")
        return ""

    def _current_values(self):
        return {k: self._value_of(k) for k in self.controls}

    def _update_conflicts(self):
        lbl = getattr(self, "_conflict_lbl", None)
        if lbl is None:
            return
        try:
            msgs = settings_conflicts(self._current_values())
            if msgs:
                lbl.configure(text="\u2139  " + "\n\u2139  ".join(msgs))
                first = getattr(self, "_first_section", None)
                if first is not None and first.winfo_exists():
                    lbl.pack(fill="x", pady=(12, 0), before=first)
                else:
                    lbl.pack(fill="x", pady=(12, 0))
            else:
                lbl.pack_forget()
        except tk.TclError:
            pass

    def dirty(self):
        return self._snapshot() != self.baseline

    def _on_change(self, key):
        if key is not None and key in self.controls:
            msg = self._validate(key)
            if msg:
                self.errors[key] = msg
            else:
                self.errors.pop(key, None)
            self._show_error(key)
            if self.controls[key]["type"] == "shortcut" and not msg:
                self._shortcut_prev[key] = self.vars[key].get()
        self._refresh_deps()
        self._refresh_footer()
        self._update_conflicts()

    # --------------------------------------------------------------- chrome
    def _build_chrome(self):
        t = self.t
        for w in self.win.winfo_children():
            w.destroy()
        self._wrap, self._deps, self._nav = [], [], {}
        self.win.configure(bg=t["window_bg"])

        # ---- sidebar
        f_base = tkfont.Font(root=self.win, font=self.F_BASE)
        longest = max(text_width(f_base, translate_text(p["title"]))
                      for p in SETTINGS_PAGES)
        side_w = max(220, min(330, longest + 60))
        side = tk.Frame(self.win, bg=t["side_bg"], width=side_w)
        side.pack(side="left", fill="y")
        side.pack_propagate(False)
        # the page list must fit the window: tighter rows on short screens
        avail = int(self.win.winfo_screenheight()) - 100
        avail = min(avail, 720) - 190
        scale = self.app.TEXT_SIZES.get(self.cfg.get(
            "appearance.text_size", "Normal"), 1.0)
        line = int(f_base.metrics("linespace") * scale)
        side_w = max(220, min(380, int(longest * scale) + 84))
        side.configure(width=side_w)
        self._nav_pady = max(1, min(5, (avail // max(1, len(
            SETTINGS_PAGES)) - line) // 2))
        tk.Label(side, text="Settings", bg=t["side_bg"], fg=t["text_fg"],
                 font=self.F_TITLE, anchor="w").pack(fill="x", padx=16,
                                                     pady=(16, 8))
        self.search_var = tk.StringVar()
        se = ttk.Entry(side, textvariable=self.search_var)
        se.pack(fill="x", padx=14, pady=(0, 10))
        self.search_entry = se
        self.search_var.trace_add("write", lambda *a: self._on_search())
        self._placeholder(se, self.search_var, "\U0001F50D Search settings")
        tk.Label(side, text=f"MiniWireshark {SCRIPT_VERSION}",
                 bg=t["side_bg"], fg=t["muted_fg"], font=self.F_HELP
                 ).pack(side="bottom", pady=(0, 8))
        ttk.Button(side, text="Reset all settings\u2026",
                   command=self.reset_all).pack(side="bottom", fill="x",
                                                padx=14, pady=(0, 4))
        ttk.Button(side, text="Changed from default",
                   command=self.show_changed).pack(side="bottom", fill="x",
                                                   padx=14, pady=(0, 4))
        # the page list scrolls if it still does not fit (very large text)
        nav_outer, nav = make_scrollable(side, t["side_bg"])
        nav_outer.pack(fill="both", expand=True)
        for pg in SETTINGS_PAGES:
            self._add_nav_row(nav, pg)

        # ---- right side: header / scrolling body / footer
        right = tk.Frame(self.win, bg=t["tab_bg"])
        right.pack(side="left", fill="both", expand=True)
        head = tk.Frame(right, bg=t["tab_bg"], padx=24, pady=16)
        head.pack(fill="x")
        self.title_lbl = tk.Label(head, bg=t["tab_bg"], fg=t["text_fg"],
                                  font=self.F_TITLE, anchor="w")
        self.title_lbl.pack(fill="x")
        self.blurb_lbl = tk.Label(head, bg=t["tab_bg"], fg=t["muted_fg"],
                                  font=self.F_BASE, anchor="w",
                                  justify="left")
        self.blurb_lbl.pack(fill="x", pady=(2, 0))
        self._wrap.append((self.blurb_lbl, 60))
        tk.Frame(right, bg=t["border"], height=1).pack(fill="x")

        foot = tk.Frame(right, bg=t["window_bg"], padx=16, pady=10)
        foot.pack(side="bottom", fill="x")
        tk.Frame(right, bg=t["border"], height=1).pack(side="bottom",
                                                       fill="x")
        self.dirty_lbl = tk.Label(foot, bg=t["window_bg"], fg=t["muted_fg"],
                                  font=self.F_HELP, anchor="w")
        self.dirty_lbl.pack(side="left")
        self.ok_btn = ttk.Button(foot, text="OK", width=9,
                                 style="Accent.TButton", command=self.ok)
        self.ok_btn.pack(side="right")
        self.apply_btn = ttk.Button(foot, text="Apply", width=9,
                                    command=self.apply)
        self.apply_btn.pack(side="right", padx=6)
        ttk.Button(foot, text="Cancel", width=9,
                   command=self.cancel).pack(side="right")
        self.reset_btn = ttk.Button(foot, text="Reset this page",
                                    command=self.reset_page)
        self.reset_btn.pack(side="right", padx=(0, 16))

        body = tk.Frame(right, bg=t["tab_bg"])
        body.pack(fill="both", expand=True)
        self.canvas = tk.Canvas(body, bg=t["tab_bg"], highlightthickness=0)
        vs = ttk.Scrollbar(body, orient="vertical",
                           command=self.canvas.yview)
        self.canvas.configure(yscrollcommand=vs.set)
        vs.pack(side="right", fill="y")
        self.canvas.pack(side="left", fill="both", expand=True)
        self.content = tk.Frame(self.canvas, bg=t["tab_bg"], padx=24,
                                pady=6)
        with contextlib.suppress(tk.TclError):
            ttk.Style().configure("SettingsWrap.TCheckbutton",
                                  wraplength=560)
        self._cwin = self.canvas.create_window((0, 0), window=self.content,
                                               anchor="nw")
        self.content.bind("<Configure>", lambda e: self.canvas.configure(
            scrollregion=self.canvas.bbox("all")))
        self.canvas.bind("<Configure>", self._on_canvas_resize)
        for w in (self.canvas, self.content):
            w.bind("<Enter>", self._bind_wheel)
            w.bind("<Leave>", self._unbind_wheel)
        self.win.bind("<Destroy>", self._on_destroy, add="+")
        self._refresh_footer()

    def _add_nav_row(self, parent, page):
        t = self.t
        row = tk.Frame(parent, bg=t["side_bg"], cursor="hand2")
        row.pack(fill="x")
        bar = tk.Frame(row, bg=t["side_bg"], width=4)
        bar.pack(side="left", fill="y")
        pady = getattr(self, "_nav_pady", 5)
        icon = tk.Label(row, text=page["icon"], bg=t["side_bg"],
                        fg=t["text_fg"], font=self.F_BASE, width=3,
                        pady=pady)
        icon.pack(side="left")
        lbl = tk.Label(row, text=page["title"], bg=t["side_bg"],
                       fg=t["text_fg"], font=self.F_BASE, anchor="w",
                       pady=pady)
        lbl.pack(side="left", fill="x", expand=True)
        for w in (row, lbl, bar, icon):
            w.bind("<Button-1>", lambda e, p=page["id"]: self._go(p))
        self._nav[page["id"]] = (row, bar, lbl, icon)

    def _placeholder(self, entry, var, text):
        """Grey hint text inside an empty entry that vanishes on focus."""
        state = {"on": False}
        text = translate_text(text)

        def show(_e=None):
            if not var.get():
                state["on"] = True
                var.set(text)
                entry.configure(foreground=self.t["muted_fg"])

        def hide(_e=None):
            if state["on"]:
                state["on"] = False
                var.set("")
                entry.configure(foreground=self.t["text_fg"])
        entry.bind("<FocusIn>", hide)
        entry.bind("<FocusOut>", show)
        self._search_placeholder = (state, text)
        show()

    def _go(self, page_id):
        state, _t = self._search_placeholder
        if self.search_var.get() and not state["on"]:
            self.search_var.set("")
        self.show_page(page_id)

    def _mark_nav(self, page_id):
        t = self.t
        for pid, (row, bar, lbl, icon) in self._nav.items():
            sel = (pid == page_id)
            bg = t["side_sel"] if sel else t["side_bg"]
            for w in (row, lbl, icon):
                w.configure(bg=bg)
            bar.configure(bg=t["accent"] if sel else bg)
            lbl.configure(font=(self.F_BASE[0], self.F_BASE[1], "bold")
                          if sel else self.F_BASE)

    # -------------------------------------------------------------- scrolling
    def _on_canvas_resize(self, e):
        self.canvas.itemconfigure(self._cwin, width=e.width)
        # long check box labels wrap too (ttk takes it from the style)
        with contextlib.suppress(tk.TclError):
            ttk.Style().configure("SettingsWrap.TCheckbutton",
                                  wraplength=max(240, e.width - 110))
        for lbl, reserve in self._wrap:
            try:
                # 80: indicators and paddings grow with the text size;
                # 48 cut the last word of some help texts
                lbl.configure(wraplength=max(240, e.width - reserve - 80))
            except tk.TclError:
                pass

    def _bind_wheel(self, _e=None):
        self.win.bind_all("<MouseWheel>", self._wheel)
        self.win.bind_all("<Button-4>", self._wheel)
        self.win.bind_all("<Button-5>", self._wheel)

    def _unbind_wheel(self, _e=None):
        for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            try:
                self.win.unbind_all(seq)
            except tk.TclError:
                pass

    def _on_destroy(self, e):
        if e.widget is self.win:
            self._unbind_wheel()

    def _wheel(self, e):
        if not self.alive():
            return
        if getattr(e, "num", None) == 4:
            step = -3
        elif getattr(e, "num", None) == 5:
            step = 3
        else:
            step = -1 * (1 if e.delta > 0 else -1) * 3 if abs(e.delta) < 120 \
                else -int(e.delta / 120) * 3
        self.canvas.yview_scroll(step, "units")

    # ---------------------------------------------------------------- pages
    def _clear_content(self):
        for w in self.content.winfo_children():
            w.destroy()
        self._wrap = [(l, r) for l, r in self._wrap if l is self.blurb_lbl]
        self._deps = []
        self._err_labels = {}

    def show_page(self, page_id):
        self.page_id = page_id
        self.searching = False
        page = next(p for p in SETTINGS_PAGES if p["id"] == page_id)
        self._clear_content()
        self.title_lbl.configure(text=f"{page['icon']}  {page['title']}")
        self.blurb_lbl.configure(text=page.get("blurb", ""))
        self._mark_nav(page_id)
        self._conflict_lbl = tk.Label(
            self.content, text="", bg=self.t["warn_bg"], fg=self.t["warn_fg"],
            font=self.F_HELP, justify="left", anchor="w", padx=10, pady=8)
        self._wrap.append((self._conflict_lbl, 60))
        self._first_section = None
        for sec in page["sections"]:
            self._render_section(sec["title"], sec["controls"])
        self._finish_render()
        self._update_conflicts()

    def _finish_render(self):
        self.canvas.yview_moveto(0)
        self._refresh_deps()
        self._refresh_footer()
        self.win.update_idletasks()
        self._on_canvas_resize(type("E", (), {
            "width": max(self.canvas.winfo_width(), 400)})())
        scale = self.app.TEXT_SIZES.get(
            self.cfg.get("appearance.text_size", "Normal"), 1.0)
        if scale != 1.0:
            self.app._scale_explicit_fonts(self.win, scale)

    def _rerender(self):
        """The current page again (a rule was removed)."""
        if getattr(self, "searching", False):
            return
        with contextlib.suppress(tk.TclError, AttributeError):
            y = self.canvas.yview()[0] if hasattr(self, "canvas") else 0
            self.show_page(self.page_id)
            if y and hasattr(self, "canvas"):
                self.canvas.yview_moveto(y)

    def find_setting(self, key):
        """Show one setting (Ctrl+K, header search): search its label."""
        c = self.controls.get(key)
        if c is None:
            return
        state, _text = getattr(self, "_search_placeholder",
                               ({"on": False}, ""))
        state["on"] = False
        with contextlib.suppress(tk.TclError):
            self.search_entry.configure(foreground=self.t["text_fg"])
        self.search_var.set(translate_text(c.get("label", key)))

    def _is_changed(self, key):
        var = self.vars.get(key)
        if var is None:
            return False
        d = self._default_for(key)
        if isinstance(var, tk.BooleanVar):
            return bool(var.get()) != bool(d)
        return str(var.get()) != str("" if d is None else d)

    def changed_keys(self):
        return [k for k in self.controls if self._is_changed(k)]

    def show_changed(self):
        """Every setting that differs from its default, each with Reset
        (useful when asking for help)."""
        self.searching = True
        self._clear_content()
        self.title_lbl.configure(text="\u270E  Changed from default")
        self.blurb_lbl.configure(text="Every setting you changed, each "
                                      "with its own Reset.")
        self._mark_nav(None)
        keys = set(self.changed_keys())
        found = 0
        for page in SETTINGS_PAGES:
            for sec in page["sections"]:
                hits = [c for c in sec["controls"] if c.get("key") in keys]
                if not hits:
                    continue
                found += len(hits)
                self._render_section(f"{page['title']}  \u203a  "
                                     f"{sec['title']}", [])
                for c in hits:
                    self._render_control(c)
                    ttk.Button(self.content, text="Reset to default",
                               command=lambda k=c["key"]:
                               self._reset_key(k)).pack(anchor="e")
        if not found:
            tk.Label(self.content, text="Everything is at its default.",
                     bg=self.t["tab_bg"], fg=self.t["muted_fg"],
                     font=self.F_BASE).pack(anchor="w", pady=20)
        self._finish_render()

    def _reset_key(self, key):
        var, d = self.vars.get(key), self._default_for(key)
        if var is None:
            return
        var.set(bool(d) if isinstance(var, tk.BooleanVar) else
                str("" if d is None else d))
        self._on_change(key)

    def _on_search(self):
        state, text = getattr(self, "_search_placeholder", ({"on": False}, ""))
        if state["on"]:
            return
        q = self.search_var.get().strip().lower()
        if len(q) < 2:
            if self.searching:
                self.show_page(self.page_id)
            return
        self.searching = True
        self._clear_content()
        self.title_lbl.configure(text="\U0001F50D  Search results")
        self.blurb_lbl.configure(text=f"Settings matching \u201c{q}\u201d")
        self._mark_nav(None)
        found = 0
        for page in SETTINGS_PAGES:
            for sec in page["sections"]:
                hits = [c for c in sec["controls"] if c.get("key") and
                        q in " ".join([c.get("label", ""), c.get("help", ""),
                                       sec["title"], page["title"]]).lower()]
                if hits:
                    found += len(hits)
                    self._render_section(
                        f"{page['title']}  \u203a  {sec['title']}", hits)
        if not found:
            tk.Label(self.content, text="No settings match that search.",
                     bg=self.t["tab_bg"], fg=self.t["muted_fg"],
                     font=self.F_BASE).pack(anchor="w", pady=20)
        self._finish_render()

    # ------------------------------------------------------------- rendering
    def _render_section(self, title, controls):
        t = self.t
        hdr = tk.Frame(self.content, bg=t["tab_bg"])
        hdr.pack(fill="x", pady=(16, 4))
        if getattr(self, "_first_section", None) is None:
            self._first_section = hdr
        tk.Label(hdr, text=title, bg=t["tab_bg"], fg=t["text_fg"],
                 font=self.F_SECTION, anchor="w").pack(fill="x")
        tk.Frame(hdr, bg=t["border"], height=1).pack(fill="x", pady=(3, 0))
        for c in controls:
            self._render_control(c)

    def _help(self, parent, text, indent=0, reserve=60):
        lbl = tk.Label(parent, text=text, bg=self.t["tab_bg"],
                       fg=self.t["muted_fg"], font=self.F_HELP,
                       justify="left", anchor="w")
        lbl.pack(fill="x", padx=(indent, 0))
        self._wrap.append((lbl, reserve))
        return lbl

    def _render_control(self, c):
        t, typ = self.t, c["type"]
        row = tk.Frame(self.content, bg=t["tab_bg"], pady=7)
        row.pack(fill="x")
        key = c.get("key")
        widgets = []

        if typ == "bool":
            top = tk.Frame(row, bg=t["tab_bg"])
            top.pack(fill="x")
            cb = ttk.Checkbutton(top, text=c["label"],
                                 variable=self.vars[key],
                                 style="SettingsWrap.TCheckbutton")
            cb.pack(side="left")
            widgets.append(cb)
            if c.get("badge"):
                self._badge(top, c["badge"])
            self._help(row, c.get("help", ""), indent=24, reserve=40)

        elif typ in ("choice", "int", "text", "path", "shortcut"):
            left = tk.Frame(row, bg=t["tab_bg"])
            left.pack(side="left", fill="x", expand=True)
            tk.Label(left, text=c["label"], bg=t["tab_bg"], fg=t["text_fg"],
                     font=self.F_BASE, anchor="w").pack(fill="x")
            if c.get("help"):
                self._help(left, c["help"], reserve={
                    "choice": 200, "int": 300, "text": 260, "path": 400,
                    "shortcut": 340}.get(typ, 260))
            right = tk.Frame(row, bg=t["tab_bg"])
            right.pack(side="right", anchor="n", padx=(12, 0))
            widgets += self._render_input(right, c)

        elif typ == "info":
            text = c.get("text") or getattr(self, c["text_fn"])()
            self._help(row, translate_lines(text), reserve=40)

        elif typ == "cvd_preview":
            self._cvd_preview(row)

        elif typ == "alert_rules":
            rules = self.app.alert_rules()
            tk.Label(row, text=translate_text("Your rules"),
                     bg=t["tab_bg"], fg=t["text_fg"], font=self.F_BASE,
                     anchor="w").pack(fill="x")
            if not rules:
                self._help(row, translate_text(
                    "None yet. “Mark expected” and “Mute for this device” "
                    "add one here."), reserve=40)
            for name, tag, words in rules[:200]:
                line = tk.Frame(row, bg=t["tab_bg"])
                line.pack(fill="x", pady=1)
                ttk.Button(line, text="Remove", style="Settings.TButton",
                           command=lambda n=name, tg=tag: (
                               self.app.remove_alert_rule(n, tg),
                               self._rerender())).pack(side="right")
                lbl = tk.Label(line, text=words, bg=t["tab_bg"],
                               fg=t["text_fg"], font=self.F_HELP,
                               anchor="w", justify="left")
                lbl.pack(side="left", fill="x", expand=True)
                self._wrap.append((lbl, 140))

        elif typ == "geo_status":
            self.geo_var = DisplayVar(value=self.app._geoip_status_text())
            lbl = tk.Label(row, textvariable=self.geo_var, bg=t["card_bg"],
                           fg=t["text_fg"], font=self.F_HELP, justify="left",
                           anchor="w", padx=10, pady=8)
            lbl.pack(fill="x")
            self._wrap.append((lbl, 60))

        elif typ == "big_action":
            box = tk.Frame(row, bg=t["card_bg"], padx=12, pady=10,
                           highlightthickness=1,
                           highlightbackground=t["border"])
            box.pack(fill="x", pady=(2, 4))
            ttk.Button(box, text=c["label"], style="Accent.TButton",
                       command=lambda n=c["action"]: self._act(n)).pack(
                side="left")
            lbl = tk.Label(box, text=c.get("help", ""), bg=t["card_bg"],
                           fg=t["text_fg"], font=self.F_HELP,
                           justify="left", anchor="w")
            lbl.pack(side="left", fill="x", expand=True, padx=(12, 0))
            self._wrap.append((lbl, 260))

        elif typ == "action":
            bar = tk.Frame(row, bg=t["tab_bg"])
            bar.pack(fill="x")
            for text, name in c["actions"]:
                b = ttk.Button(bar, text=text, style="Settings.TButton",
                               command=lambda n=name: self._act(n))
                b.pack(side="left", padx=(0, 8))

        if key:
            err = tk.Label(row, text="", bg=t["tab_bg"], fg=t["danger_fg"],
                           font=self.F_HELP, anchor="w", justify="left")
            self._err_labels[key] = err
            self._show_error(key)
        if c.get("requires"):
            self._deps.append((c["requires"], widgets))

    def _cvd_preview(self, row):
        """Swatches of the meaning-carrying colours for the chosen mode,
        updated as you change the choice."""
        t = self.t
        box = tk.Frame(row, bg=t["card_bg"], padx=12, pady=10,
                       highlightthickness=1, highlightbackground=t["border"])
        box.pack(fill="x")
        cv = tk.Canvas(box, height=64, bg=t["card_bg"], highlightthickness=0)
        cv.pack(fill="x")
        var = self.vars.get("accessibility.colorblind")

        def draw(*_a):
            with contextlib.suppress(tk.TclError):
                mode = CVD_LABELS.get(var.get() if var else "Off", "")
                pal = palette_name(self.app.theme_name,
                                   self.app.high_contrast, mode)
                th = THEMES[pal]
                cv.configure(bg=th["card_bg"])
                cv.delete("all")
                items = [("✔ Healthy", th["good_fg"]),
                         ("⚠ Warning", th["warn_fg"]),
                         ("‼ Danger", th["danger_fg"]),
                         ("ℹ Info", th["info_fg"])]
                x = 8
                for label, col in items:
                    cv.create_rectangle(x, 8, x + 22, 30, fill=col,
                                        outline="")
                    cv.create_text(x + 30, 19, text=label, anchor="w",
                                   fill=col, font=("TkDefaultFont", 10,
                                                   "bold"))
                    x += 150
                x = 8
                for k in ("chart_down", "chart_up", "chart_a", "chart_b",
                          "chart_c", "chart_d", "chart_e"):
                    cv.create_rectangle(x, 40, x + 60, 56, fill=th[k],
                                        outline="")
                    x += 70
        if var is not None:
            var.trace_add("write", draw)
        cv.bind("<Configure>", draw)
        draw()

    def _badge(self, parent, sev):
        t = self.t
        fg, bg = {"INFO": (t["info_fg"], t["card_bg"]),
                  "WARNING": (t["warn_fg"], t["warn_bg"]),
                  "DANGER": (t["danger_fg"], t["danger_bg"])}[sev]
        icon = self.app.SEVERITY_ICON.get(sev, "")
        tk.Label(parent, text=f" {icon} {sev} ", bg=bg, fg=fg,
                 font=(self.F_HELP[0], 8, "bold")).pack(side="left",
                                                        padx=(10, 0))

    def _render_input(self, parent, c):
        key, typ, var = c["key"], c["type"], self.vars[c["key"]]
        if typ == "choice":
            vals = c["choices"]
            if vals == "@locales":
                vals = list(LOCALE_NAMES.values())
            w = ttk.Combobox(parent, textvariable=var, values=vals,
                             state="readonly", width=c.get("width", 16))
            w.pack(anchor="e")
            return [w]
        if typ == "int":
            box = tk.Frame(parent, bg=self.t["tab_bg"])
            box.pack(anchor="e")
            w = ttk.Spinbox(box, from_=c["min"], to=c["max"],
                            increment=c.get("step", 1), textvariable=var,
                            width=8, justify="right")
            w.pack(side="left")
            tk.Label(box, text=c.get("unit", ""), bg=self.t["tab_bg"],
                     fg=self.t["muted_fg"], font=self.F_HELP, anchor="w",
                     width=16).pack(side="left", padx=(6, 0))
            return [w]
        if typ == "text":
            w = ttk.Entry(parent, textvariable=var, width=c.get("width", 24))
            w.pack(anchor="e")
            return [w]
        if typ == "path":
            box = tk.Frame(parent, bg=self.t["tab_bg"])
            box.pack(anchor="e")
            w = ttk.Entry(box, textvariable=var, width=26)
            w.pack(side="left")
            b = ttk.Button(box, text="Browse\u2026", width=9,
                           command=lambda: self._browse(var))
            b.pack(side="left", padx=(6, 0))
            return [w, b]
        if typ == "shortcut":
            box = tk.Frame(parent, bg=self.t["tab_bg"])
            box.pack(anchor="e")
            shown = tk.StringVar(value=_pretty_seq(var.get()))
            var.trace_add("write", lambda *a: shown.set(
                _pretty_seq(var.get())))
            tk.Label(box, textvariable=shown, bg=self.t["card_bg"],
                     fg=self.t["text_fg"], font=self.F_BASE, width=14,
                     padx=6, pady=3).pack(side="left")
            b1 = ttk.Button(box, text="Change", width=8,
                            command=lambda: self._change_shortcut(key))
            b1.pack(side="left", padx=(6, 0))
            b2 = ttk.Button(box, text="Default", width=8,
                            command=lambda: var.set(
                                DEFAULT_SHORTCUTS.get(key.split(".")[1], "")))
            b2.pack(side="left", padx=(4, 0))
            return [b1, b2]
        return []

    # ------------------------------------------------------- dynamic pieces
    def _show_error(self, key):
        lbl = getattr(self, "_err_labels", {}).get(key)
        if lbl is None:
            return
        try:
            msg = self.errors.get(key, "")
            if msg:
                lbl.configure(text="\u26a0 " + msg)
                lbl.pack(fill="x")
            else:
                lbl.pack_forget()
        except tk.TclError:
            pass

    def _refresh_deps(self):
        for req, widgets in self._deps:
            v = self.vars.get(req)
            on = bool(v.get()) if isinstance(v, tk.BooleanVar) else \
                bool(str(v.get()).strip()) if v is not None else True
            if isinstance(v, tk.StringVar) and req == "updates.repo":
                on = on and not self.errors.get(req)
            for w in widgets:
                try:
                    w.state(["!disabled"] if on else ["disabled"])
                except tk.TclError:
                    pass

    def _refresh_footer(self):
        try:
            bad = bool(self.errors)
            dirty = self.dirty()
            if bad:
                self.dirty_lbl.configure(
                    text="\u26a0 Some settings need attention",
                    fg=self.t["danger_fg"])
            elif dirty:
                self.dirty_lbl.configure(text="\u25cf Unsaved changes",
                                         fg=self.t["warn_fg"])
            else:
                self.dirty_lbl.configure(text="All changes saved",
                                         fg=self.t["muted_fg"])
            state = ["!disabled"] if (dirty and not bad) else ["disabled"]
            self.apply_btn.state(state)
            self.reset_btn.state(["disabled"] if self.searching
                                 else ["!disabled"])
        except tk.TclError:
            pass

    def _tick(self):
        if not self.alive():
            return
        try:
            if hasattr(self, "geo_var"):
                self.geo_var.set(self.app._geoip_status_text())
        except tk.TclError:
            pass
        self.win.after(1000, self._tick)

    # ------------------------------------------------------------- actions
    def _browse(self, var):
        d = filedialog.askdirectory(parent=self.win,
                                    initialdir=var.get() or None)
        if d:
            var.set(d)

    def _change_shortcut(self, key):
        self.app._capture_shortcut(self.win, key.split(".")[1],
                                   self.vars[key])

    def config_path_text(self):
        return (f"Settings are saved in:\n{self.cfg.path}\n\n"
                f"Data folder (caches, logs, history, sessions):\n"
                f"{PATHS.data}")

    def data_status_text(self):
        return self.app.data_status_text()

    def components_summary_text(self):
        return self.app.components_summary_text()

    def ledger_status_text(self):
        return self.app.ledger_status_text()

    def release_keys_text(self):
        if RELEASE_KEYS:
            return ("Updates and data packs are installed only when signed "
                    "by: " + ", ".join(RELEASE_KEYS) + ". Older versions "
                    "are never installed over newer ones.")
        return ("No release key is built into this copy, so updates are "
                "check-only: you're told about a new version and download "
                "it yourself. Nothing unsigned is ever installed.")

    def history_size_text(self):
        return self.app.history_status_text()

    def deps_status_text(self):
        return self.app.deps_status_text()

    def diag_summary_text(self):
        return self.app.diag_summary_text()

    def runtime_status_text(self):
        return self.app.runtime_status_text()

    def _act(self, name):
        if name == "open_config_folder":
            folder = os.path.dirname(self.cfg.path)
            if not _open_path(folder):
                messagebox.showinfo("Settings folder", folder,
                                    parent=self.win)
        elif name == "check_updates":
            self.app._check_for_updates(manual=True)
        elif name == "install_datapack":
            self.app.install_datapack(self.win)
        elif name == "geoip_test":
            self.app._geoip_test(self.win)
        elif name == "geoip_retry":
            self.app._geoip_retry()
        elif name == "refresh_data":
            self.app.refresh_reference_data(force=True)
        elif name == "components_center":
            self.app.open_components_center(self.win)
        elif name == "components_reset":
            self.app.components_reset(self.win)
        elif name == "forget_learned_types":
            self.app.forget_learned_types(self.win)
        elif name == "repair_deps":
            self.app.repair_dependencies(self.win)
        elif name == "clear_history":
            self.app.clear_history(self.win)
        elif name == "reset_baseline":
            self.app.reset_baselines(self.win)
        elif name == "open_data_folder":
            if not _open_path(PATHS.data):
                messagebox.showinfo("Data folder", PATHS.data,
                                    parent=self.win)
        elif name == "open_logs":
            if not _open_path(PATHS.logs):
                messagebox.showinfo("Logs", PATHS.logs, parent=self.win)
        elif name == "open_diagnostics":
            self.app.open_diagnostics()
        elif name == "run_self_test":
            self.app.run_self_test_window()
        elif name == "repair_all":
            self.app.repair_everything(self.win)
        elif name == "runtime_manager":
            self.app.open_runtime_manager(self.win)
        elif name == "open_ledger":
            self.app.open_ledger(self.win)
        elif name == "export_bundle":
            self.app.export_debug_bundle(self.win)
        elif name == "quick_start":
            self.app.open_quick_start()
        elif name == "unmute_alerts":
            self.cfg.set("alerts.muted_devices", [])
            self.cfg.set("alerts.expected", [])
            self.cfg.save()
            self.app._set_banner("\U0001F514  All alert mutes were cleared.")
            self._rerender()

    def reset_page(self):
        if self.searching:
            return
        page = next(p for p in SETTINGS_PAGES if p["id"] == self.page_id)
        for sec in page["sections"]:
            for c in sec["controls"]:
                k = c.get("key")
                if not k:
                    continue
                d = self._default_for(k)
                self.vars[k].set(bool(d) if c["type"] == "bool"
                                 else ("" if d is None else str(d)))

    def reset_all(self):
        if not messagebox.askyesno(
                "Reset all settings",
                "Restore every setting to its default?\n\nYour captured "
                "data isn't affected.", parent=self.win):
            return
        self.cfg.reset()
        self.app._apply_runtime_settings()
        for key, c in self.controls.items():
            d = self._default_for(key)
            self.vars[key].set(bool(d) if c["type"] == "bool"
                               else ("" if d is None else str(d)))
        self.errors = {}
        self.baseline = self._snapshot()
        self._build_chrome()
        self.show_page(self.page_id)

    def apply(self):
        errs = self._validate_all()
        if errs:
            self._refresh_footer()
            for k in errs:
                self._show_error(k)
            return False
        before = (self.cfg.get("appearance.theme"),
                  self.cfg.get("appearance.high_contrast"),
                  self.cfg.get("appearance.text_size"))
        for key in self.controls:
            self.cfg.set(key, self._value_of(key))
        self.cfg.save()
        self.app._apply_runtime_settings()
        # show the values as actually stored (e.g. numbers clamped)
        for key in self.controls:
            v = self._value_of(key)
            self.vars[key].set(v if isinstance(v, bool) else str(v))
        self.baseline = self._snapshot()
        after = (self.cfg.get("appearance.theme"),
                 self.cfg.get("appearance.high_contrast"),
                 self.cfg.get("appearance.text_size"))
        if before != after:
            self._build_chrome()
            self.show_page(self.page_id)
        else:
            self._refresh_footer()
        self.app._set_banner("\u2699\ufe0e  Settings saved.")
        return True

    def ok(self):
        if self.apply():
            self.win.destroy()

    def cancel(self):
        if self.dirty() and not messagebox.askyesno(
                "Discard changes?", "You have unsaved changes. Close "
                "without saving?", parent=self.win):
            return
        self.win.destroy()




# ============================================================================
#  17.  GUI components — tables, charts, dialogs, menus
#
#  Small reusable builders so every tab looks and behaves the same, and so
#  every new widget is themed through the same palette (no hard-coded white
#  panels in Dark mode).
# ============================================================================
_UNIT_MULT = {"B": 1, "KB": 1024, "MB": 1024 ** 2, "GB": 1024 ** 3,
              "B/s": 1, "KB/s": 1024, "MB/s": 1024 ** 2, "GB/s": 1024 ** 3}


def sort_key(v):
    """Numeric-aware sort for table cells ("1.2 MB", "350", "12:01:05")."""
    s = str(v).strip()
    m = re.match(r"^[^\d\-]*(-?[\d,]*\.?\d+)\s*([KMG]?B(?:/s)?)?", s)
    if m and (m.group(2) or re.match(r"^-?[\d,]*\.?\d+$", s.replace(" ", ""))):
        try:
            n = float(m.group(1).replace(",", ""))
            return (0, n * _UNIT_MULT.get(m.group(2) or "", 1), "")
        except ValueError:
            pass
    return (1, 0, s.lower())


def enable_sorting(tree, on_sort=None):
    state = {"col": None, "rev": False}

    def do_sort(col):
        rev = state["rev"] if state["col"] == col else False
        state["col"], state["rev"] = col, not rev
        for parent in ("",) + tuple(tree.get_children("")):
            kids = list(tree.get_children(parent))
            if not kids:
                continue
            kids.sort(key=lambda k: sort_key(tree.set(k, col)), reverse=rev)
            for i, k in enumerate(kids):
                tree.move(k, parent, i)
        for c in tree["columns"]:
            txt = tree.heading(c, "text").rstrip(" ▲▼")
            if c == col:
                txt += " ▼" if rev else " ▲"
            tree.heading(c, text=txt)
        if on_sort:
            on_sort(col, rev)

    for c in tree["columns"]:
        tree.heading(c, command=lambda cc=c: do_sort(cc))
    return state


def make_scrollable(parent, bg="#ffffff", fit_width=False):
    """A frame that scrolls vertically (wheel, scrollbar). → (outer to
    pack, inner to fill). fit_width: as wide as its content."""
    outer = tk.Frame(parent, bg=bg)
    canvas = tk.Canvas(outer, bg=bg, highlightthickness=0)
    vs = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
    canvas.configure(yscrollcommand=vs.set)
    vs.pack(side="right", fill="y")
    canvas.pack(side="left", fill="both", expand=True)
    inner = tk.Frame(canvas, bg=bg)
    win = canvas.create_window((0, 0), window=inner, anchor="nw")
    def show_bar():
        """The scroll bar only when there is something to scroll."""
        try:
            need = inner.winfo_reqheight() > canvas.winfo_height() + 2
            if need and not vs.winfo_manager():
                vs.pack(side="right", fill="y", before=canvas)
            elif not need and vs.winfo_manager():
                vs.pack_forget()
                canvas.yview_moveto(0)
        except tk.TclError:
            pass

    def inner_conf(_e=None):
        canvas.configure(scrollregion=canvas.bbox("all"))
        if fit_width:
            want = inner.winfo_reqwidth()
            if abs(int(canvas.cget("width")) - want) > 2:
                canvas.configure(width=want)
        show_bar()

    def canvas_conf(e):
        canvas.itemconfigure(win, width=e.width)
        show_bar()
    inner.bind("<Configure>", inner_conf)
    canvas.bind("<Configure>", canvas_conf)
    seqs = ("<MouseWheel>", "<Button-4>", "<Button-5>")

    def wheel(e):
        num = getattr(e, "num", 0)
        step = -1 if num == 4 else 1 if num == 5 else \
            (-1 if getattr(e, "delta", 0) > 0 else 1)
        with contextlib.suppress(tk.TclError):
            canvas.yview_scroll(step * 2, "units")

    # 5.2.3 (B-28): the wheel command is registered once; bind_all(fn)
    # on every <Enter> registered a new Tcl command each time (a leak)
    script = 'if {"[%s %s]" == "break"} break\n' % (
        canvas._register(wheel, canvas._substitute, True),
        canvas._subst_format_str)

    def bind(_e=None):
        for sq in seqs:
            with contextlib.suppress(tk.TclError):
                canvas.tk.call("bind", "all", sq, script)

    def unbind(_e=None):
        for sq in seqs:
            with contextlib.suppress(tk.TclError):
                canvas.tk.call("bind", "all", sq, "")
    outer.bind("<Enter>", bind)
    outer.bind("<Leave>", unbind)
    outer.canvas = canvas
    return outer, inner


def make_tree(parent, columns, bg="#ffffff", show="headings",
              selectmode="browse", hscroll=False, sortable=True):
    """columns: list of (id, title, width, anchor, stretch)."""
    frame = tk.Frame(parent, bg=bg)
    tree = ttk.Treeview(frame, columns=[c[0] for c in columns], show=show,
                        selectmode=selectmode)
    for cid, title, width, anchor, stretch in columns:
        tree.heading(cid, text=title, anchor=anchor if anchor != "e"
                     else "e")
        tree.column(cid, width=width, anchor=anchor, stretch=stretch,
                    minwidth=30)
    vs = ttk.Scrollbar(frame, orient="vertical", command=tree.yview)
    tree.configure(yscrollcommand=vs.set)
    tree.grid(row=0, column=0, sticky="nsew")
    vs.grid(row=0, column=1, sticky="ns")
    if hscroll:
        hs = ttk.Scrollbar(frame, orient="horizontal", command=tree.xview)
        tree.configure(xscrollcommand=hs.set)
        hs.grid(row=1, column=0, sticky="ew")
    frame.rowconfigure(0, weight=1)
    frame.columnconfigure(0, weight=1)
    if sortable:
        enable_sorting(tree)
    return frame, tree


def tree_upsert(tree, iid_map, key, values, tags=(), parent="", index="end",
                kit=None):
    """Insert or update one row; returns its iid. Never redraws the whole
    table. With a TableKit, the row keeps its sorted place and shows the
    new-row dot and "4 min ago"."""
    iid = iid_map.get(key)
    # in the shown language before the kit sorts by it (the tree holds
    # the shown words; see translate_cell)
    values = translate_cells(values)
    if kit is not None:
        values = kit.decorate(key, values)
    if iid is not None:
        try:
            tree.item(iid, values=values, tags=tags)
            if kit is not None:
                kit.updated(iid, key, values)
            return iid
        except tk.TclError:
            iid_map.pop(key, None)
            if kit is not None:
                kit.removed(iid)
    slot = None
    if kit is not None:
        index, slot = kit.insert_index(parent, key, values, default=index)
    try:
        iid = tree.insert(parent, index, values=values, tags=tags)
        iid_map[key] = iid
        if kit is not None:
            kit.inserted(parent, iid, slot, key)
        return iid
    except tk.TclError:
        return None


def tree_remove(tree, iid_map, key, kit=None):
    iid = iid_map.pop(key, None)
    if iid is not None:
        with contextlib.suppress(tk.TclError):
            tree.delete(iid)
        if kit is not None:
            kit.removed(iid)


class IidMap(dict):
    """key -> Treeview iid, with an O(1) reverse index (iid -> key). Tables
    with thousands of rows used to scan every row on each click."""

    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self.rev = {v: key for key, v in self.items()}

    def __setitem__(self, key, iid):
        old = self.get(key)
        if old is not None:
            self.rev.pop(old, None)
        super().__setitem__(key, iid)
        self.rev[iid] = key

    def __delitem__(self, key):
        iid = self[key]
        super().__delitem__(key)
        self.rev.pop(iid, None)

    def pop(self, key, *default):
        if key in self:
            iid = super().pop(key)
            self.rev.pop(iid, None)
            return iid
        if default:
            return default[0]
        raise KeyError(key)

    def clear(self):
        super().clear()
        self.rev.clear()

    def setdefault(self, key, iid=None):
        if key not in self:
            self[key] = iid
        return self[key]

    def update(self, *a, **k):
        for key, v in dict(*a, **k).items():
            self[key] = v


def key_for_iid(iid_map, iid):
    rev = getattr(iid_map, "rev", None)
    if rev is not None:
        return rev.get(iid)
    for k, v in iid_map.items():
        if v == iid:
            return k
    return None


# ---- Table kit (5.1.2 F4) -----------------------------------------------------
#  One set of table behaviours for Devices, Websites, Connections, Internet
#  hosts, Alerts, Timeline and the feed: remembered columns, widths and sort;
#  a sort that holds while rows update; a sentence instead of a blank table;
#  the same right-click layout everywhere; copy and export of what is shown;
#  rows that are new since you last looked; "4 min ago" while watching live.
# ============================================================================
ROW_DOT = "• "              # marks a row that is new since you last looked


def relative_age(ts, now):
    """'just now', '4 min ago'... (translated); the clock time stays in
    the tooltip and in copies and exports."""
    if not ts:
        return "—"
    d = max(0.0, now - ts)
    if d < 10:
        s = "just now"
    elif d < 60:
        s = "%d s ago" % int(d)
    elif d < 3600:
        s = "%d min ago" % int(d // 60)
    elif d < 86400:
        s = "%d h ago" % int(d // 3600)
    else:
        s = "%d d ago" % int(d // 86400)
    return translate_text(s)


def debounce(widget, fn, ms=150):
    """A callable that runs fn() once, `ms` after the last call (typing in
    a filter box rebuilt the whole table on every key)."""
    state = {"job": None}

    def fire():
        state["job"] = None
        fn()

    def call(*_a):
        job = state["job"]
        if job is not None:
            with contextlib.suppress(tk.TclError):
                widget.after_cancel(job)
        state["job"] = widget.after(ms, fire)
    return call


class _Desc:
    """Wraps a sort key so that bisect keeps a descending list."""
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v

    def __lt__(self, other):
        return other.v < self.v

    def __eq__(self, other):
        return self.v == other.v


class TableKit:
    """Shared behaviour of one ttk.Treeview (F4).

    key_of(iid) -> the row's key (None for rows the kit should ignore).
    empty_state() -> None or (sentence, button text or None, callback).
    default_cols() -> the column ids shown by default (the view decides).
    sort_values: {col: fn(key)} raw values to sort by instead of the text.
    relative: {col: fn(key) -> timestamp}: "4 min ago" while live.
    dot_col: the column (or "#0") that carries the new-row dot.
    menu(key) -> {"open", "filter", "packets", "goto": [(label, fn)],
                  "own": [items]} for the right-click menu.
    all_keys() -> every key the table could show (for the new-row dots).
    """

    SAVE_EVERY = 2.0
    REL_EVERY = 20000            # ms between "min ago" refreshes

    def __init__(self, tab, tree, wrap, table_id, key_of, empty_state=None,
                 default_cols=None, sort_values=None, relative=None,
                 dot_col=None, menu=None, all_keys=None, sortable=True,
                 on_sort=None, explain=None):
        app = tab.app
        self.tab, self.app, self.tree, self.wrap = tab, app, tree, wrap
        self.table_id = table_id
        self.key_of = key_of
        self.empty_state = empty_state
        self.default_cols = default_cols
        self.sort_values = dict(sort_values or {})
        self.relative = dict(relative or {})
        self.dot_col = dot_col
        self.menu = menu
        self.all_keys = all_keys
        self.sortable = sortable
        self.on_sort = on_sort
        self.explain = explain
        self.columns = tuple(tree["columns"])
        self.col_index = {c: i for i, c in enumerate(self.columns)}
        self.titles = {c: str(tree.heading(c, "text") or "")
                       for c in self.columns}
        self.sort_col, self.sort_desc = None, False
        self._order = {}           # parent iid -> sorted [(k, seq, iid)]
        self._ent = {}             # iid -> (parent, entry)
        self._seq = iter(range(1 << 62))
        self.stale = False
        self.snapshot = None       # keys present when you last left the tab
        self.dotted = {}           # iid -> key currently showing the dot
        self._empty_job = None
        self._save_job = None
        self._rel_text = {}
        self._press_region = ""
        self._tip = None
        self._tip_job = None
        self._tip_cell = None
        self._build_overlays()
        tree.bind("<Button-3>", self._right_click)
        tree.bind("<Button-2>", self._right_click)
        tree.bind("<ButtonPress-1>", self._press, add="+")
        tree.bind("<Configure>", lambda e: self.empty_soon(), add="+")
        tree.bind("<Map>", lambda e: self.empty_soon(), add="+")
        tree.bind("<<TreeviewSelect>>", lambda e: self.update_explain(),
                  add="+")
        tree.bind("<ButtonRelease-1>", self._release, add="+")
        if self.relative:
            tree.bind("<Motion>", self._motion, add="+")
            tree.bind("<Leave>", lambda e: self._hide_tip(), add="+")
        for c in ("#0",) + self.columns:
            with contextlib.suppress(tk.TclError):
                tree.heading(c, command=lambda cc=c: self.sort_by(cc))
        self.load()
        app.kits.append(self)
        self.empty_soon()

    # ---- settings ----------------------------------------------------------
    @property
    def sticky(self):
        return FEATURES.get("sticky_sort", True)

    def _saved(self):
        tables = self.app.config.get("appearance.tables") or {}
        return tables.get(self.table_id) or {}

    def load(self):
        """Saved columns, widths and sort (none when the switch is off:
        the 5.0.2 defaults)."""
        st = self._saved() if self.sticky else {}
        self.apply_columns()
        widths = st.get("widths") or {}
        ratio = 1.0
        with contextlib.suppress(TypeError, ValueError, ZeroDivisionError):
            ratio = MW_FONT_SCALE[0] / float(st.get("scale") or 1.0)
        for c, w in widths.items():
            if c in self.col_index or c == "#0":
                with contextlib.suppress(tk.TclError, TypeError, ValueError):
                    self.tree.column(c, width=max(30, int(int(w) * ratio)))
        sort = st.get("sort")
        if self.sortable and isinstance(sort, list) and len(sort) == 2 and \
                (sort[0] in self.col_index or sort[0] == "#0"):
            self.sort_col, self.sort_desc = sort[0], bool(sort[1])
            self._arrows()

    def save_soon(self):
        if self._save_job is not None or not self.sticky:
            return
        with contextlib.suppress(tk.TclError):
            self._save_job = self.tree.after(int(self.SAVE_EVERY * 1000),
                                             self.save)

    def save(self):
        self._save_job = None
        cfg = self.app.config
        tables = dict(cfg.get("appearance.tables") or {})
        st = dict(tables.get(self.table_id) or {})
        if self.user_cols is None:
            st.pop("cols", None)
        else:
            st["cols"] = list(self.user_cols)
        widths = {}
        for c in ("#0",) + self.columns:
            with contextlib.suppress(tk.TclError, ValueError):
                widths[c] = int(self.tree.column(c, "width"))
        st["widths"], st["scale"] = widths, MW_FONT_SCALE[0]
        if self.sort_col:
            st["sort"] = [self.sort_col, self.sort_desc]
        else:
            st.pop("sort", None)
        tables[self.table_id] = st
        cfg.set("appearance.tables", tables)
        cfg.save()

    # ---- columns -----------------------------------------------------------
    @property
    def user_cols(self):
        cols = self._saved().get("cols") if self.sticky else None
        if getattr(self, "_cols_override", "unset") != "unset":
            cols = self._cols_override
        if cols is None:
            return None
        return [c for c in cols if c in self.col_index] or None

    def defaults(self):
        cols = self.default_cols() if self.default_cols else None
        return list(cols) if cols else list(self.columns)

    def shown_cols(self):
        return self.user_cols or self.defaults()

    def apply_columns(self):
        with contextlib.suppress(tk.TclError):
            self.tree.configure(displaycolumns=self.shown_cols())

    def set_column_shown(self, col, shown):
        cols = list(self.shown_cols())
        if shown and col not in cols:
            # back in its usual place
            cols.append(col)
            cols.sort(key=lambda c: self.col_index.get(c, 999))
        elif not shown and col in cols and len(cols) > 1:
            cols.remove(col)
        self._cols_override = cols
        self.apply_columns()
        self.save_soon()

    def reset_columns(self):
        """Back to the view's default columns and widths."""
        self._cols_override = None
        cfg = self.app.config
        tables = dict(cfg.get("appearance.tables") or {})
        st = dict(tables.get(self.table_id) or {})
        st.pop("cols", None)
        st.pop("widths", None)
        tables[self.table_id] = st
        cfg.set("appearance.tables", tables)
        cfg.save()
        self.apply_columns()

    def _press(self, e):
        with contextlib.suppress(tk.TclError):
            self._press_region = self.tree.identify_region(e.x, e.y)

    def _release(self, _e):
        if self._press_region == "separator":
            self.save_soon()          # a column was resized
        self._press_region = ""

    # ---- sort that holds while rows update --------------------------------
    def _raw_key(self, key, values, col):
        fn = self.sort_values.get(col) or self.relative.get(col)
        if fn is not None:
            try:
                v = fn(key)
            except Exception:                        # noqa: BLE001
                v = None
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                return (0, float(v), "")
            return (1, 0, str(v if v is not None else "").lower())
        if col == "#0":
            return sort_key(values)
        i = self.col_index.get(col)
        v = values[i] if values is not None and i is not None and \
            i < len(values) else ""
        if isinstance(v, str) and v.startswith(ROW_DOT):
            v = v[len(ROW_DOT):]
        return sort_key(v)

    def _k(self, key, values):
        k = self._raw_key(key, values, self.sort_col)
        return _Desc(k) if self.sort_desc else k

    def _row_values(self, iid):
        if self.sort_col == "#0":
            return self.tree.item(iid, "text")
        return self.tree.item(iid, "values")

    def _list(self, parent):
        lst = self._order.get(parent)
        if lst is None:
            lst = []
            for iid in self.tree.get_children(parent):
                e = (self._k(self.key_of(iid), self._row_values(iid)),
                     next(self._seq), iid)
                lst.append(e)
                self._ent[iid] = (parent, e)
            lst.sort()
            self._order[parent] = lst
        return lst

    def active(self):
        return bool(self.sort_col) and self.sticky

    def insert_index(self, parent, key, values, text=None, default="end"):
        """Where a new row goes: its sorted place while a sort is set."""
        if not self.active():
            return default, None
        try:
            lst = self._list(parent)
            e = (self._k(key, text if self.sort_col == "#0" else values),
                 next(self._seq), "")
            pos = bisect.bisect_left(lst, e)
            if pos >= len(lst):
                return "end", (e, pos)
            return self.tree.index(lst[pos][2]), (e, pos)
        except (tk.TclError, TypeError):
            self.invalidate()
            return default, None

    def inserted(self, parent, iid, slot, key=None):
        self.note_row(iid, key)
        self.empty_soon()
        if slot is None or not self.active():
            return
        e, pos = slot
        lst = self._order.get(parent)
        if lst is None:
            return
        e = (e[0], e[1], iid)
        lst.insert(pos, e)
        self._ent[iid] = (parent, e)

    def updated(self, iid, key, values):
        """A row's values changed: keep it in its sorted place, except the
        selected row, which stays where the user is looking."""
        self.note_row(iid, key)
        if not self.active() or self.sort_col == "#0":
            return
        if getattr(self, "quiet", False):
            # Reduce motion: rows never move under the pointer; the
            # Re-sort line offers the new order
            self._set_stale(True)
            return
        got = self._ent.get(iid)
        if got is None:
            self.invalidate()
            return
        parent, old = got
        new_k = self._k(key, values)
        if new_k == old[0]:
            return
        lst = self._order.get(parent)
        if lst is None:
            return
        i = bisect.bisect_left(lst, old)
        if i >= len(lst) or lst[i][2] != iid:
            self.invalidate()
            return
        del lst[i]
        e = (new_k, old[1], iid)
        j = bisect.bisect_left(lst, e)
        lst.insert(j, e)
        self._ent[iid] = (parent, e)
        if j == i:
            return                    # same neighbours, same place
        try:
            if iid in self.tree.selection():
                self._set_stale(True)
                return
            if j + 1 < len(lst):
                target = self.tree.index(lst[j + 1][2])
                if self.tree.index(iid) < target:
                    target -= 1
            else:
                target = "end"
            self.tree.move(iid, parent, target)
        except tk.TclError:
            self.invalidate()

    def removed(self, iid):
        got = self._ent.pop(iid, None)
        self.dotted.pop(iid, None)
        self._rel_text.pop(iid, None)
        if got is not None:
            parent, e = got
            lst = self._order.get(parent)
            if lst is not None:
                i = bisect.bisect_left(lst, e)
                if i < len(lst) and lst[i][2] == iid:
                    del lst[i]
                else:
                    self._order.pop(parent, None)
        self.empty_soon()

    def invalidate(self):
        """The order lists no longer match the table (rows added or
        removed elsewhere): rebuilt from the table when next needed."""
        self._order.clear()
        self._ent.clear()

    def clear(self):
        """The table was emptied."""
        self.invalidate()
        self.dotted.clear()
        self._rel_text.clear()
        self._set_stale(False)
        self.empty_soon()

    def sort_by(self, col):
        if not self.sortable:
            return
        if self.sort_col == col:
            self.sort_desc = not self.sort_desc
        else:
            self.sort_col, self.sort_desc = col, False
        self.resort()
        self.save_soon()
        if self.on_sort is not None:
            self.on_sort(col, self.sort_desc)

    def clear_sort(self):
        self.sort_col, self.sort_desc = None, False
        self.invalidate()
        self._arrows()
        self._set_stale(False)
        self.save_soon()

    def resort(self):
        """Put every row in order now (also ends 'order changed')."""
        self.invalidate()
        self._set_stale(False)
        self._arrows()
        if not self.sort_col:
            return
        parents = [""] + [p for p in self.tree.get_children("")
                          if self.tree.get_children(p)]
        for parent in parents:
            lst = self._list(parent)
            for i, (_k, _s, iid) in enumerate(lst):
                with contextlib.suppress(tk.TclError):
                    self.tree.move(iid, parent, i)
        if not self.sticky:
            self.invalidate()

    def _arrows(self):
        for c in ("#0",) + self.columns:
            with contextlib.suppress(tk.TclError):
                txt = str(self.tree.heading(c, "text")).rstrip(" ▲▼")
                if c == self.sort_col:
                    txt += " ▼" if self.sort_desc else " ▲"
                self.tree.heading(c, text=txt)

    # ---- overlays: empty state, "order changed" ----------------------------
    def _build_overlays(self):
        t = self.app.theme
        # a child of the table, drawn over its empty body
        self.empty = tk.Frame(self.tree, bg=t["tab_bg"])
        self.empty_lbl = tk.Label(self.empty, text="", bg=t["tab_bg"],
                                  fg=t["muted_fg"], wraplength=420,
                                  justify="center", font=mw_font(10))
        self.empty_lbl.pack(padx=12, pady=(10, 4))
        # the kit sizes this label itself: the automatic re-wrapping (made
        # for labels laid out by their parents) would narrow it in a loop,
        # since its frame takes its size from it
        self.empty_lbl._mw_wrap0 = 0
        self.empty_lbl._mw_wrapping = True
        self.empty_btn = ttk.Button(self.empty, text="")
        self.stale_lbl = tk.Label(
            self.wrap, text="The order changed while a row was selected. "
                            "Re-sort", bg=t["tab_bg"], fg=t["accent"],
            cursor="hand2", anchor="w", font=mw_font(9))
        self.stale_lbl.bind("<Button-1>", lambda e: self.resort())
        self.fresh_lbl = tk.Label(self.wrap, text="", bg=t["tab_bg"],
                                  fg=t["muted_fg"], anchor="w",
                                  font=mw_font(9))
        self.explain_lbl = tk.Label(self.wrap, text="", bg=t["tab_bg"],
                                    fg=t["accent"], anchor="w",
                                    justify="left", font=mw_font(9),
                                    wraplength=1100)

    def on_theme(self):
        t = self.app.theme
        with contextlib.suppress(tk.TclError):
            self.empty.configure(bg=t["tab_bg"])
            self.empty_lbl.configure(bg=t["tab_bg"], fg=t["muted_fg"])
            self.stale_lbl.configure(bg=t["tab_bg"], fg=t["accent"])
            self.fresh_lbl.configure(bg=t["tab_bg"], fg=t["muted_fg"])
            self.explain_lbl.configure(bg=t["tab_bg"], fg=t["accent"])

    def _set_stale(self, on):
        self.stale = on
        with contextlib.suppress(tk.TclError):
            if on and not self.stale_lbl.winfo_manager():
                self.stale_lbl.grid(row=2, column=0, columnspan=2,
                                    sticky="ew", padx=4)
            elif not on and self.stale_lbl.winfo_manager():
                self.stale_lbl.grid_forget()

    def update_explain(self):
        """Explain inline: one line under the table about the selected row
        (never a line per row)."""
        text = ""
        if self.explain is not None and self.app.explain_on():
            with contextlib.suppress(tk.TclError):
                sel = self.tree.selection()
                key = self.key_of(sel[0]) if sel else None
                if key is not None:
                    try:
                        text = self.explain(key) or ""
                    except Exception:                # noqa: BLE001
                        LOG.debug("explain row", exc_info=True)
                        text = ""
        with contextlib.suppress(tk.TclError):
            if text:
                self.explain_lbl.configure(text=text)
                if not self.explain_lbl.winfo_manager():
                    self.explain_lbl.grid(row=4, column=0, columnspan=2,
                                          sticky="ew", padx=4, pady=(2, 0))
            elif self.explain_lbl.winfo_manager():
                self.explain_lbl.grid_forget()

    def explain_text(self):
        with contextlib.suppress(tk.TclError):
            if self.explain_lbl.winfo_manager():
                return str(self.explain_lbl.cget("text"))
        return ""

    def empty_soon(self):
        if self._empty_job is None:
            with contextlib.suppress(tk.TclError):
                self._empty_job = self.tree.after(60, self.update_empty)

    def update_empty(self):
        self._empty_job = None
        self._show_fresh()
        try:
            has_rows = bool(self.tree.get_children(""))
        except tk.TclError:
            return
        spec = None if has_rows or self.empty_state is None else \
            self.empty_state()
        try:
            if not spec:
                if self.empty.winfo_manager():
                    self.empty.place_forget()
                return
            text, button, fn = (tuple(spec) + (None, None))[:3]
            tw, th = self.tree.winfo_width(), self.tree.winfo_height()
            if not self.tree.winfo_ismapped() or tw <= 1:
                return                # placed when the table is shown
            head = tkfont.nametofont("TkHeadingFont").metrics(
                "linespace") + 14
            self.empty_lbl.configure(
                text=text, wraplength=max(160, min(520, tw - 60)))
            if button and fn:
                self.empty_btn.configure(text=button, command=fn)
                if not self.empty_btn.winfo_manager():
                    self.empty_btn.pack(pady=(0, 10))
            elif self.empty_btn.winfo_manager():
                self.empty_btn.pack_forget()
            # below the headings; the button goes when the table is too
            # short for both
            room = th - head - 8
            need = self.empty_lbl.winfo_reqheight() + 14
            if self.empty_btn.winfo_manager():
                if th > 1 and need + self.empty_btn.winfo_reqheight() + \
                        10 > room:
                    self.empty_btn.pack_forget()
                else:
                    need += self.empty_btn.winfo_reqheight() + 10
            if th > 1 and need > room:
                # a table too short for the sentence shows nothing rather
                # than half of it
                self.empty.place_forget()
                return
            y = head + max(0, (room - need) // 3)
            self.empty.place(relx=0.5, y=y, anchor="n")
            self.empty.lift()
        except tk.TclError:
            pass

    def empty_text(self):
        """What the empty state says now ('' when rows are shown)."""
        with contextlib.suppress(tk.TclError):
            if self.empty.winfo_manager():
                return str(self.empty_lbl.cget("text"))
        return ""

    @staticmethod
    def filtered(q, clear):
        """The empty state of a table whose filter matches nothing."""
        return (f"No rows match “{q}”.", "Clear the filter", clear)

    # ---- rows new since you last looked; relative "last seen" ---------------
    def fresh(self, key):
        return self.snapshot is not None and key is not None and \
            key not in self.snapshot

    def decorate(self, key, values):
        """The values to show: the dot on new rows, "4 min ago" while live."""
        if values is None:
            return values
        out = None
        if self.dot_col and self.dot_col != "#0" and self.fresh(key):
            i = self.col_index.get(self.dot_col)
            if i is not None and i < len(values):
                out = list(values)
                v = str(out[i])
                if not v.startswith(ROW_DOT):
                    out[i] = ROW_DOT + v
        if self.relative and self.app.data_mode == "live":
            now = time.time()
            for col, fn in self.relative.items():
                i = self.col_index.get(col)
                if i is None or i >= len(values):
                    continue
                if out is None:
                    out = list(values)
                with contextlib.suppress(Exception):
                    out[i] = relative_age(fn(key), now)
        return tuple(out) if out is not None else values

    def decorate_text(self, key, text):
        if self.dot_col == "#0" and self.fresh(key) and \
                not str(text).startswith(ROW_DOT):
            return ROW_DOT + str(text)
        return text

    def note_row(self, iid, key):
        """Remember dotted rows so leaving the tab can clear the dots."""
        if self.dot_col and self.fresh(key) and iid not in self.dotted:
            self.dotted[iid] = key
            self.empty_soon()

    def fresh_count(self):
        return len(self.dotted)

    def _show_fresh(self):
        n = len(self.dotted)
        try:
            if n:
                self.fresh_lbl.configure(
                    text=f"{ROW_DOT}{n} new since you last looked")
                if not self.fresh_lbl.winfo_manager():
                    self.fresh_lbl.grid(row=3, column=0, columnspan=2,
                                        sticky="ew", padx=4)
            elif self.fresh_lbl.winfo_manager():
                self.fresh_lbl.grid_forget()
        except tk.TclError:
            pass

    def on_show(self):
        self.refresh_relative()
        self.empty_soon()

    def on_hide(self):
        """Leaving the tab: what you saw is no longer new."""
        for iid in list(self.dotted):
            with contextlib.suppress(tk.TclError):
                if self.dot_col == "#0":
                    txt = str(self.tree.item(iid, "text"))
                    if txt.startswith(ROW_DOT):
                        self.tree.item(iid, text=txt[len(ROW_DOT):])
                else:
                    v = str(self.tree.set(iid, self.dot_col))
                    if v.startswith(ROW_DOT):
                        self.tree.set(iid, self.dot_col, v[len(ROW_DOT):])
        self.dotted.clear()
        self._show_fresh()
        if self.all_keys is not None:
            try:
                self.snapshot = set(self.all_keys())
            except Exception:                        # noqa: BLE001
                self.snapshot = None

    def forget_snapshot(self):
        """A new capture or session: nothing is 'new since you looked'."""
        self.snapshot = None
        self.dotted.clear()
        self._show_fresh()

    def refresh_relative(self, chunk=400):
        """Re-word "min ago" cells (only what changed), a slice at a time."""
        if not self.relative or self.app.data_mode != "live":
            return
        try:
            kids = list(self.tree.get_children(""))
        except tk.TclError:
            return
        now = time.time()

        def run(i=0):
            for iid in kids[i:i + chunk]:
                key = self.key_of(iid)
                if key is None:
                    continue
                for col, fn in self.relative.items():
                    try:
                        txt = relative_age(fn(key), now)
                    except Exception:                # noqa: BLE001
                        continue
                    seen = self._rel_text.setdefault(iid, {})
                    if seen.get(col) != txt:
                        seen[col] = txt
                        with contextlib.suppress(tk.TclError):
                            self.tree.set(iid, col, txt)
            if i + chunk < len(kids):
                with contextlib.suppress(tk.TclError):
                    self.tree.after(1, run, i + chunk)
        run()

    # ---- the clock time behind "4 min ago" ---------------------------------
    def _motion(self, e):
        try:
            iid = self.tree.identify_row(e.y)
            col = self._col_at(e.x)
        except tk.TclError:
            return
        cell = (iid, col) if iid and col in self.relative and \
            self.app.data_mode == "live" else None
        if cell == self._tip_cell:
            return
        self._hide_tip()
        self._tip_cell = cell
        if cell:
            with contextlib.suppress(tk.TclError):
                self._tip_job = self.tree.after(
                    500, lambda: self._show_tip(e.x_root, e.y_root))

    def _show_tip(self, x, y):
        self._tip_job = None
        if not self._tip_cell:
            return
        iid, col = self._tip_cell
        key = self.key_of(iid)
        try:
            ts = self.relative[col](key)
        except Exception:                            # noqa: BLE001
            return
        if not ts:
            return
        t = Tooltip.theme or THEME_LIGHT
        try:
            tip = tk.Toplevel(self.tree)
            tip.wm_overrideredirect(True)
            tip.wm_geometry(f"+{x + 12}+{y + 16}")
            tk.Label(tip, text=fmt_clock(ts, True), bg=t["tooltip_bg"],
                     fg=t["tooltip_fg"], relief="solid", borderwidth=1,
                     font=mw_font(9), padx=6, pady=3).pack()
            self._tip = tip
        except tk.TclError:
            pass

    def _hide_tip(self):
        self._tip_cell = None
        if self._tip_job is not None:
            with contextlib.suppress(tk.TclError):
                self.tree.after_cancel(self._tip_job)
            self._tip_job = None
        if self._tip is not None:
            with contextlib.suppress(tk.TclError):
                self._tip.destroy()
            self._tip = None

    # ---- copy and export what is shown -------------------------------------
    def _col_at(self, x):
        c = self.tree.identify_column(x)
        if not c or c == "#0":
            return "#0" if c == "#0" else None
        try:
            n = int(c[1:]) - 1
        except ValueError:
            return None
        shown = list(self.tree["displaycolumns"])
        if not shown or shown[0] == "#all":
            shown = list(self.columns)
        return shown[n] if 0 <= n < len(shown) else None

    def visible_cols(self):
        shown = list(self.tree["displaycolumns"])
        if not shown or shown[0] == "#all":
            shown = list(self.columns)
        tree_col = "tree" in str(self.tree.cget("show"))
        return (["#0"] if tree_col else []) + shown

    def cell_text(self, iid, col):
        """A cell as text for copies and exports: no new-row dot, and the
        clock time instead of "4 min ago"."""
        key = self.key_of(iid)
        if col in self.relative:
            with contextlib.suppress(Exception):
                ts = self.relative[col](key)
                return fmt_clock(ts, True) if ts else "—"
        if col == "#0":
            v = str(self.tree.item(iid, "text"))
        else:
            v = str(self.tree.set(iid, col))
        if v.startswith(ROW_DOT):
            v = v[len(ROW_DOT):]
        return v

    def header_row(self):
        return [str(self.tree.heading(c, "text")).rstrip(" ▲▼")
                for c in self.visible_cols()]

    def row_cells(self, iid):
        return [self.cell_text(iid, c) for c in self.visible_cols()]

    def all_iids(self):
        out = []
        for iid in self.tree.get_children(""):
            out.append(iid)
            out.extend(self.tree.get_children(iid))
        return out

    def copy_cell(self, iid, col):
        if col:
            copy_to_clipboard(self.app, self.cell_text(iid, col))

    def copy_row(self, iid):
        copy_to_clipboard(self.app, "\t".join(self.row_cells(iid)))

    def csv_text(self, iids):
        buf = io.StringIO()
        w = safe_csv_writer(buf)
        w.writerow(self.header_row())
        for iid in iids:
            w.writerow(self.row_cells(iid))
        return buf.getvalue()

    def copy_selection(self):
        sel = list(self.tree.selection())
        if sel:
            copy_to_clipboard(self.app, self.csv_text(sel))

    def export(self, path=None, done=None):
        """This table as you see it (filter, sort, columns) to a CSV file.
        The rows are read on the Tk thread a slice at a time (Tk may only
        be used there); the job runner writes the file."""
        if path is None:
            path = filedialog.asksaveasfilename(
                parent=self.app.root, title="Export this table",
                defaultextension=".csv",
                initialfile=f"{self.table_id}.csv",
                filetypes=[("CSV", "*.csv")])
        if not path:
            return None
        iids = self.all_iids()
        rows = [self.header_row()]

        def read(i=0):
            for iid in iids[i:i + 300]:
                with contextlib.suppress(tk.TclError):
                    rows.append(self.row_cells(iid))
            if i + 300 < len(iids):
                self.tree.after(1, read, i + 300)
            else:
                self._export_write(path, rows, done)
        read()
        return path

    def _export_write(self, path, rows, done):
        def run(job):
            buf = io.StringIO()
            w = safe_csv_writer(buf)
            for r in rows:
                w.writerow(r)
            tmp = path + ".part"
            with open(tmp, "w", encoding="utf-8", newline="") as f:
                f.write(buf.getvalue())
            os.replace(tmp, path)
            return len(rows) - 1

        def ok(n):
            self.app.status_var.set(f"Exported {n} rows to {path}")
            if done is not None:
                done(path)

        def bad(e):
            if not isinstance(e, JobCancelled):
                messagebox.showerror("Export error", str(e),
                                     parent=self.app.root)
        return self.app.jobs.submit("table_export", "Exporting the table",
                                    run, ok, bad)

    # ---- menus --------------------------------------------------------------
    def _right_click(self, e):
        try:
            region = self.tree.identify_region(e.x, e.y)
        except tk.TclError:
            return
        if region == "heading":
            popup_menu(self.app, e, self.header_items())
            return "break"
        iid = self.tree.identify_row(e.y)
        if not iid:
            return
        if iid not in self.tree.selection():
            self.tree.selection_set(iid)
        self.tree.focus(iid)
        items = self.row_items(iid, self._col_at(e.x))
        if items:
            popup_menu(self.app, e, items)
        return "break"

    def header_items(self):
        shown = set(self.shown_cols())
        cols = []
        for c in self.columns:
            title = str(self.tree.heading(c, "text")).rstrip(" ▲▼") or \
                translate_text("(icon)")
            cols.append((title, lambda cc=c, on=(c not in shown):
                         self.set_column_shown(cc, on), True,
                         c in shown))
        items = [("Columns", cols), ("Reset columns", self.reset_columns)]
        if self.sortable and self.sort_col:
            items.append(("Clear the sort", self.clear_sort))
        items += [None, ("Export this table…", lambda: self.export())]
        return items

    def row_items(self, iid, col=None):
        """Open · Copy ▸ · Filter to this · Show its packets · Go to ▸ ·
        then the row's own actions, the same order in every table."""
        key = self.key_of(iid)
        spec = self.menu(key) if (self.menu and key is not None) else {}
        spec = spec or {}
        items = []
        if spec.get("open"):
            items.append(("Open", spec["open"]))
        copy = []
        if col:
            copy.append(("Copy cell", lambda: self.copy_cell(iid, col)))
        copy.append(("Copy row", lambda: self.copy_row(iid)))
        copy.append(("Copy selected rows as CSV", self.copy_selection))
        copy += spec.get("copy") or []
        items.append(("Copy", copy))
        if spec.get("filter"):
            items.append(("Filter to this", spec["filter"]))
        if spec.get("packets") and not self.app.beginner_mode:
            items.append(("Show its packets", spec["packets"]))
        goto = [g for g in (spec.get("goto") or []) if g]
        if goto:
            items.append(("Go to", goto))
        own = spec.get("own") or []
        if own:
            items.append(None)
            items += own
        return items


def kit_menu_labels(items):
    """The top-level labels of a kit menu (tests)."""
    return [it[0] for it in items if it]


# ---- named fonts (5.1.2) -------------------------------------------------------
# Widgets used to carry their own ("TkDefaultFont", 11, "bold") tuples, so a
# text-size change had to walk every widget and build a Font object for
# each (0.33 s). They now share named fonts, one per size and style; a
# text-size change re-sizes these few fonts and Tk updates every widget.
MW_FONTS = {}          # name -> (base size, style tuple)
MW_FONT_OBJ = {}       # name -> tkfont.Font (keeps the named font alive)


def mw_font(size, *style):
    """Name of the shared font that looks exactly like the old
    ("TkDefaultFont", size, *style) tuple, created on first use and
    scaled with the current text size."""
    name = "MW%d%s" % (size, "".join(x[0] for x in style))
    try:
        tkfont.nametofont(name)
        return name
    except (tk.TclError, RuntimeError):
        pass
    actual = tkfont.Font(font=("TkDefaultFont", size) + tuple(style)).actual()
    scale = MW_FONT_SCALE[0]
    # keep the Font object: when it is garbage-collected, Tk deletes the
    # named font
    MW_FONT_OBJ[name] = tkfont.Font(
        name=name, family=actual["family"],
        size=(-1 if size < 0 else 1) * max(6, int(round(abs(size) * scale))),
        weight=actual["weight"], slant=actual["slant"],
        underline=actual["underline"], overstrike=actual["overstrike"])
    MW_FONTS[name] = (size, tuple(style))
    return name


MW_FONT_SCALE = [1.0]


def scale_mw_fonts(scale):
    """Text size: every shared font follows at once."""
    for _name in scale_mw_fonts_steps(scale):
        pass


def scale_mw_fonts_steps(scale):
    """The same, one font per step: Tk re-lays out every widget using a
    font when it changes (10-70 ms each at S1), so a caller can let the
    window breathe between fonts."""
    MW_FONT_SCALE[0] = scale
    for name, (size, _style) in list(MW_FONTS.items()):
        with contextlib.suppress(tk.TclError, RuntimeError):
            tkfont.nametofont(name).configure(
                size=(-1 if size < 0 else 1) * max(
                    6, int(round(abs(size) * scale))))
        yield name


def themed_menu(app):
    t = app.theme
    return tk.Menu(app.root, tearoff=0, bg=t["tab_bg"], fg=t["text_fg"],
                   activebackground=t["accent"],
                   activeforeground="#000000" if app.high_contrast and
                   app.theme_name == "Dark" else "#ffffff")


def popup_menu(app, event, items):
    """items: list of (label, callback[, enabled[, checked]]) or None for
    a separator; (label, [items]) opens a submenu."""
    m = themed_menu(app)
    fill_menu(m, items)
    try:
        m.tk_popup(event.x_root, event.y_root)
    finally:
        m.grab_release()


def fill_menu(m, items):
    m._mw_vars = getattr(m, "_mw_vars", [])
    for it in items:
        if it is None:
            m.add_separator()
            continue
        label, cb = it[0], it[1]
        if isinstance(cb, list):
            sub = tk.Menu(m, tearoff=0)
            with contextlib.suppress(tk.TclError):
                sub.configure(**{k: m.cget(k) for k in (
                    "bg", "fg", "activebackground", "activeforeground")})
            fill_menu(sub, cb)
            m.add_cascade(label=label, menu=sub,
                          state="normal" if cb else "disabled")
            continue
        state = "normal" if (len(it) < 3 or it[2]) else "disabled"
        if len(it) >= 4:
            var = tk.BooleanVar(master=m, value=bool(it[3]))
            m._mw_vars.append(var)
            m.add_checkbutton(label=label, variable=var, command=cb,
                              state=state)
        else:
            m.add_command(label=label, command=cb, state=state)


class _SafeCsv:
    """csv.writer whose text cells can never start a spreadsheet formula
    (device names, DHCP host names and packet text come from the
    network)."""

    BAD = ("=", "+", "-", "@", "\t", "\r")

    def __init__(self, f):
        self.w = csv.writer(f)

    @classmethod
    def cell(cls, v):
        if isinstance(v, str):
            v = hide_credentials(v)
        if isinstance(v, str) and v.startswith(cls.BAD):
            return "'" + v
        return v

    def writerow(self, row):
        return self.w.writerow([self.cell(v) for v in row])


def safe_csv_writer(f):
    return _SafeCsv(f)


def copy_to_clipboard(app, text):
    text = hide_credentials(scrub_secrets(text))
    try:
        app.root.clipboard_clear()
        app.root.clipboard_append(text)
        app.root.update_idletasks()
        app._set_banner("\U0001F4CB  Copied to the clipboard.")
        return True
    except tk.TclError:
        return False


class DetailDialog:
    """A themed, scrollable report window used for devices, connections,
    alerts, websites and remote hosts. `sections` is a list of
    (heading, text) and `actions` a list of (label, callback)."""

    def __init__(self, app, title, sections, actions=None, size="560x620",
                 extra=None):
        self.app = app
        t = app.theme
        self.win = tk.Toplevel(app.root)
        self.win.title(title)
        self.win.geometry(px_geo(size))
        self.win.minsize(px(420), px(320))
        self.win.configure(bg=t["tab_bg"])
        self.win.transient(app.root)
        top = tk.Frame(self.win, bg=t["tab_bg"], padx=14, pady=10)
        top.pack(fill="x")
        tk.Label(top, text=title, bg=t["tab_bg"], fg=t["text_fg"],
                 font=mw_font(13, "bold"), anchor="w",
                 justify="left", wraplength=500).pack(fill="x")
        if extra is not None:
            extra(self.win)
        body = tk.Frame(self.win, bg=t["tab_bg"])
        body.pack(fill="both", expand=True, padx=8)
        self.txt = tk.Text(body, wrap="word", bg=t["text_bg"],
                           fg=t["text_fg"], relief="flat", padx=12, pady=10,
                           font=mw_font(10),
                           insertbackground=t["text_fg"],
                           highlightthickness=0)
        vs = ttk.Scrollbar(body, orient="vertical", command=self.txt.yview)
        self.txt.configure(yscrollcommand=vs.set)
        self.txt.pack(side="left", fill="both", expand=True)
        vs.pack(side="right", fill="y")
        self.txt.tag_configure("h", font=mw_font(11, "bold"),
                               spacing1=6, spacing3=3)
        self.txt.tag_configure("muted", foreground=t["muted_fg"])
        self.txt.tag_configure("fold", foreground=t["accent"],
                               spacing1=4, spacing3=8)
        self.txt.tag_configure("lk", foreground=t["accent"], underline=True)
        self._links = 0
        self.txt.tag_bind("fold", "<Button-1>", lambda e: self.toggle_fold())
        self.txt.tag_bind("fold", "<Enter>",
                          lambda e: self.txt.configure(cursor="hand2"))
        self.txt.tag_bind("fold", "<Leave>",
                          lambda e: self.txt.configure(cursor=""))
        self.fold_kind = None
        self.set_sections(sections)
        self.btns = tk.Frame(self.win, bg=t["tab_bg"], padx=8, pady=8)
        self.btns.pack(fill="x")
        ttk.Button(self.btns, text="Close", command=self.win.destroy).pack(
            side="right")
        ttk.Button(self.btns, text="Copy report",
                   command=self.copy).pack(side="right", padx=6)
        for label, cb in actions or []:
            ttk.Button(self.btns, text=label, command=cb).pack(
                side="left", padx=(0, 6))
        self.win.bind("<Escape>", lambda e: self.win.destroy())
        scale = app.TEXT_SIZES.get(app.config.get("appearance.text_size",
                                                  "Normal"), 1.0)
        if scale != 1.0:
            app._scale_explicit_fonts(self.win, scale)

    def set_sections(self, sections):
        self.sections = sections
        try:
            y = self.txt.yview()[0]
        except tk.TclError:
            y = 0.0
        self.txt.config(state="normal")
        self.txt.delete("1.0", "end")
        kind = getattr(self, "fold_kind", None)
        keep = len(sections)
        if kind and len(sections) > self.FOLD_KEEP + 1:
            keep = self.FOLD_KEEP
        self.folded = keep < len(sections) and self.app.fold_closed(kind)
        for tag in self.txt.tag_names():
            if tag.startswith("lk_"):
                self.txt.tag_delete(tag)
        for i, sec in enumerate(sections):
            heading, text = sec[0], sec[1]
            links = (getattr(self, "links", None) or {}).get(heading, ())
            if i == keep:
                more = len(sections) - keep
                self.txt.insert("end", ("\u25B8 " + translate_text(
                    "More detail") + f" ({more})") if self.folded else
                    ("\u25BE " + translate_text("Less detail")) + "",
                    ("fold",))
                self.txt.insert("end", "\n")
                if self.folded:
                    break
            self.txt.insert("end", translate_text(heading) + "\n", ("h",))
            if isinstance(text, (list, tuple)):
                # sentences, each with a link to its proof
                for line, link in text:
                    self.txt.insert("end", translate_lines(line))
                    if link:
                        self.txt.insert("end", "  ")
                        self._link(link)
                    self.txt.insert("end", "\n")
                self.txt.insert("end", "\n")
                continue
            self.txt.insert("end", translate_lines(text or "—") + "\n")
            for j, link in enumerate(links or ()):
                self.txt.insert("end", "   " if j else "")
                self._link(link)
            self.txt.insert("end", "\n\n" if links else "\n")
        with contextlib.suppress(Exception):
            gloss_mark(self.txt, self.app)
        self.txt.config(state="disabled")
        if y:
            with contextlib.suppress(tk.TclError):
                self.txt.yview_moveto(y)

    def alive(self):
        try:
            return bool(self.win.winfo_exists())
        except tk.TclError:
            return False

    FOLD_KEEP = 3

    def _link(self, link):
        """(label, app method name, args): a link in the text."""
        label, meth, args = link
        self._links += 1
        tag = f"lk_{self._links}"
        self.txt.insert("end", translate_text(label), ("lk", tag))
        fn = getattr(self.app, meth, None)
        if fn is not None:
            self.txt.tag_bind(tag, "<Button-1>",
                              lambda e, f=fn, a=tuple(args): f(*a))
        self.txt.tag_bind(tag, "<Enter>",
                          lambda e: self.txt.configure(cursor="hand2"))
        self.txt.tag_bind(tag, "<Leave>",
                          lambda e: self.txt.configure(cursor=""))

    @staticmethod
    def section_text(text):
        if isinstance(text, (list, tuple)):
            return "\n".join(line for line, _l in text)
        return text or "—"

    def toggle_fold(self):
        kind = getattr(self, "fold_kind", None)
        if not kind:
            return
        self.app.set_fold(kind, not self.folded)
        self.set_sections(self.sections)

    def copy(self):
        title = self.win.title()
        body = "\n\n".join(f"{sec[0]}\n{self.section_text(sec[1])}"
                           for sec in self.sections)
        copy_to_clipboard(self.app, f"{title}\n{'=' * len(title)}\n\n{body}")


def ask_text(app, title, prompt, initial="", multiline=False, parent=None):
    """Small themed input dialog. Returns the text or None if cancelled."""
    t = app.theme
    res = {"v": None}
    win = tk.Toplevel(parent or app.root)
    win.title(title)
    win.configure(bg=t["tab_bg"])
    win.transient(parent or app.root)
    win.resizable(True, multiline)
    tk.Label(win, text=prompt, bg=t["tab_bg"], fg=t["text_fg"],
             justify="left", wraplength=380).pack(anchor="w", padx=14,
                                                  pady=(12, 6))
    if multiline:
        w = tk.Text(win, height=6, width=48, bg=t["text_bg"], fg=t["text_fg"],
                    insertbackground=t["text_fg"], wrap="word")
        w.insert("1.0", initial or "")
    else:
        var = tk.StringVar(value=initial or "")
        w = ttk.Entry(win, textvariable=var, width=44)
    w.pack(fill="both", expand=True, padx=14)
    w.focus_set()

    def ok(_e=None):
        res["v"] = (w.get("1.0", "end").strip() if multiline
                    else var.get().strip())
        win.destroy()
    bar = tk.Frame(win, bg=t["tab_bg"])
    bar.pack(fill="x", padx=14, pady=12)
    ttk.Button(bar, text="OK", style="Accent.TButton", command=ok).pack(
        side="right")
    ttk.Button(bar, text="Cancel", command=win.destroy).pack(side="right",
                                                             padx=6)
    if not multiline:
        win.bind("<Return>", ok)
    win.bind("<Escape>", lambda e: win.destroy())
    win.grab_set()
    win.wait_window()
    return res["v"]


def ask_tags(app, dev, places=(), owners=(), parent=None):
    """Place and owner for a device: two short fields with what you
    used before. → (place, owner) or None."""
    t = app.theme
    res = {"v": None}
    win = tk.Toplevel(parent or app.root)
    win.title(translate_text("Place and owner"))
    win.configure(bg=t["tab_bg"])
    win.transient(parent or app.root)
    tk.Label(win, text=translate_text("Where is %s, and whose is it? Two "
                                      "short words, kept on this computer "
                                      "only.") % app.device_label(dev),
             bg=t["tab_bg"], fg=t["text_fg"], justify="left",
             wraplength=380).pack(anchor="w", padx=14, pady=(12, 6))
    grid = tk.Frame(win, bg=t["tab_bg"])
    grid.pack(fill="x", padx=14)
    pv = tk.StringVar(value=dev.place)
    ov = tk.StringVar(value=dev.owner)
    for r, (label, var, vals) in enumerate((("Place:", pv, places),
                                            ("Owner:", ov, owners))):
        tk.Label(grid, text=label, bg=t["tab_bg"], fg=t["text_fg"]).grid(
            row=r, column=0, sticky="w", pady=3)
        cb = ttk.Combobox(grid, textvariable=var, values=list(vals),
                          width=28)
        cb.grid(row=r, column=1, sticky="ew", padx=(8, 0), pady=3)
        if r == 0:
            cb.focus_set()
    grid.columnconfigure(1, weight=1)

    def ok(_e=None):
        res["v"] = (pv.get().strip()[:40], ov.get().strip()[:40])
        win.destroy()
    bar = tk.Frame(win, bg=t["tab_bg"])
    bar.pack(fill="x", padx=14, pady=12)
    ttk.Button(bar, text="OK", style="Accent.TButton", command=ok).pack(
        side="right")
    ttk.Button(bar, text="Cancel", command=win.destroy).pack(side="right",
                                                             padx=6)
    win.bind("<Return>", ok)
    win.bind("<Escape>", lambda e: win.destroy())
    win.grab_set()
    win.wait_window()
    return res["v"]


def choose_from_list(app, title, prompt, options, parent=None):
    """options: list of (label, value). Returns the chosen value or None."""
    t = app.theme
    res = {"v": None}
    win = tk.Toplevel(parent or app.root)
    win.title(title)
    win.configure(bg=t["tab_bg"])
    win.geometry(px_geo("440x380"))
    win.transient(parent or app.root)
    tk.Label(win, text=prompt, bg=t["tab_bg"], fg=t["text_fg"],
             justify="left", wraplength=400).pack(anchor="w", padx=14,
                                                  pady=(12, 6))
    lb = tk.Listbox(win, bg=t["text_bg"], fg=t["text_fg"],
                    selectbackground=t["accent"], activestyle="dotbox",
                    highlightthickness=1)
    for label, _v in options:
        lb.insert("end", label)
    lb.pack(fill="both", expand=True, padx=14)

    def ok(_e=None):
        sel = lb.curselection()
        if sel:
            res["v"] = options[sel[0]][1]
        win.destroy()
    lb.bind("<Double-1>", ok)
    bar = tk.Frame(win, bg=t["tab_bg"])
    bar.pack(fill="x", padx=14, pady=12)
    ttk.Button(bar, text="Choose", style="Accent.TButton", command=ok).pack(
        side="right")
    ttk.Button(bar, text="Cancel", command=win.destroy).pack(side="right",
                                                             padx=6)
    win.bind("<Escape>", lambda e: win.destroy())
    win.grab_set()
    win.wait_window()
    return res["v"]


class Charts:
    """Tiny native Tk canvas charts. Colours come from the active theme;
    every series also differs by dash pattern and has a text legend, so
    nothing relies on colour alone."""

    DASHES = ((), (6, 3), (2, 2), (8, 2, 2, 2))

    @staticmethod
    def nice_max(v):
        if v <= 0:
            return 1
        exp = 10 ** int(math.floor(math.log10(v)))
        for m in (1, 2, 2.5, 5, 10):
            if v <= m * exp:
                return m * exp
        return 10 * exp

    _FONTS = {}

    class _Measured:
        """A chart font whose measure() and metrics() are remembered: the
        Dashboard asked Tk ~30 times per redraw (a theme change spent
        ~35 ms there). Charts.forget_fonts() empties it when the text size
        or the scale changes."""
        __slots__ = ("font", "_w", "_m")

        def __init__(self, font):
            self.font, self._w, self._m = font, {}, {}

        def measure(self, text):
            got = self._w.get(text)
            if got is None:
                if len(self._w) > 4000:
                    self._w.clear()
                got = self._w[text] = self.font.measure(text)
            return got

        def metrics(self, *opts):
            got = self._m.get(opts)
            if got is None:
                got = self._m[opts] = self.font.metrics(*opts)
            return got

    @classmethod
    def font(cls, c, spec):
        f = cls._FONTS.get(spec)
        if f is None:
            f = cls._FONTS[spec] = cls._Measured(
                tkfont.Font(root=c, font=spec))
        return f

    @classmethod
    def forget_fonts(cls):
        for f in cls._FONTS.values():
            f._w.clear()
            f._m.clear()

    @classmethod
    def elide(cls, c, text, spec, width):
        """`text` cut with … so it fits `width` pixels."""
        f = cls.font(c, spec)
        text = str(text)
        if width <= 8:
            return ""
        if f.measure(text) <= width:
            return text
        lo, hi = 0, len(text)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if f.measure(text[:mid] + "…") <= width:
                lo = mid
            else:
                hi = mid - 1
        return text[:lo] + "…" if lo else ""

    @classmethod
    def line(cls, c, x, y, w, h, series, t, title="", fmt=str,
             xlabels=("", ""), empty="No data yet"):
        """A line chart in the box (x, y, w, h). The legend, the axis
        labels and the title are measured so that none of them overlap
        (V5.0.2: they did with long labels, translations or a short
        chart)."""
        small, bold = ("TkDefaultFont", 8), ("TkDefaultFont", 10, "bold")
        fs, fb = cls.font(c, small), cls.font(c, bold)
        title = translate_text(title)
        tw = fb.measure(title) if title else 0
        tid = c.create_text(x, y, anchor="nw", text=title, fill=t["text_fg"],
                            font=bold)
        n_pts = max((len(v) for _l, v, _c in series), default=0)
        cls.record(c, tid, title, ["#"] + [lab for lab, _v, _c in series],
                   [[i + 1] + [(v[i] if i < len(v) else "")
                               for _l, v, _c in series]
                    for i in range(n_pts)], fmt,
                   note=f"{xlabels[0]} … {xlabels[1]}".strip(" …"))
        # legend: right-aligned rows above the plot, never over the title
        rows, row, rx = [], [], x + w
        for i, (label, vals, color) in enumerate(series):
            lw = fs.measure(label) + 34
            limit = (x + tw + 16) if not rows else x
            if row and rx - lw < limit:
                rows.append(row)
                row, rx = [], x + w
            row.append((i, label, color))
            rx -= lw
        if row:
            rows.append(row)
        if rows and rows[0] and (x + w - sum(fs.measure(r[1]) + 34
                                             for r in rows[0])) < x + tw + 16:
            rows.insert(0, [])          # no room beside the title
        line_h = fs.metrics("linespace") + 3
        for k, r in enumerate(rows):
            ly, lx = y + 2 + k * line_h, x + w
            for i, label, color in r:
                txt = c.create_text(lx, ly, anchor="ne", text=label,
                                    fill=t["text_fg"], font=small)
                bx = c.bbox(txt)
                sx = (bx[0] if bx else lx) - 6
                mid = ly + line_h / 2 - 1
                c.create_line(sx - 22, mid, sx, mid, fill=color, width=2,
                              dash=cls.DASHES[i % len(cls.DASHES)])
                lx = sx - 34
        head = max(fb.metrics("linespace") + 6, len(rows) * line_h + 4)
        top = y + head + fs.metrics("linespace") // 2
        ph = max(20, h - (top - y) - fs.metrics("linespace") - 8)
        vmax = max((max(vals) if vals else 0) for _l, vals, _c in series) \
            if series else 0
        nm = cls.nice_max(vmax)
        # as many grid lines as fit without their labels touching
        steps = max(1, min(4, int(ph // (fs.metrics("linespace") + 4))))
        labels = [fmt(nm * i / steps) for i in range(steps + 1)]
        left = x + max(30, max(fs.measure(s) for s in labels) + 10)
        pw = max(40, x + w - left - 4)
        for i in range(steps + 1):
            gy = top + ph - ph * i / steps
            c.create_line(left, gy, left + pw, gy, fill=t["grid"])
            c.create_text(left - 6, gy, anchor="e", fill=t["muted_fg"],
                          text=labels[i], font=small)
        x0 = cls.elide(c, xlabels[0], small, pw / 2 - 4)
        x1 = cls.elide(c, xlabels[1], small, pw / 2 - 4)
        c.create_text(left, top + ph + 4, anchor="nw", fill=t["muted_fg"],
                      text=x0, font=small)
        c.create_text(left + pw, top + ph + 4, anchor="ne",
                      fill=t["muted_fg"], text=x1, font=small)
        if vmax <= 0:
            c.create_text(left + pw / 2, top + ph / 2, text=empty,
                          fill=t["muted_fg"], font=("TkDefaultFont", 9))
        for i, (label, vals, color) in enumerate(series):
            if not vals:
                continue
            n = len(vals)
            pts = []
            for j, v in enumerate(vals):
                pts += [left + pw * j / max(1, n - 1),
                        top + ph - ph * min(v, nm) / nm]
            if len(pts) >= 4 and vmax > 0:
                c.create_line(*pts, fill=color, width=2,
                              dash=cls.DASHES[i % len(cls.DASHES)])
        return left, pw

    # 5.1.2: each chart keeps the numbers it drew; right-click copies them
    # as text or CSV (also for screen-reader users)
    @classmethod
    def record(cls, c, anchor, title, header, rows, fmt=None, texts=None,
               note=""):
        recs = getattr(c, "_mw_chart", None)
        if recs is None:
            recs = c._mw_chart = OrderedDict()
            c.bind("<Button-3>", lambda e: cls.chart_menu(c, e), add="+")
        recs[title or f"chart {len(recs) + 1}"] = {
            "anchor": anchor, "header": header, "rows": rows,
            "fmt": fmt, "texts": texts, "note": note}

    @classmethod
    def chart_data(cls, c):
        """The charts now on the canvas (a cleared one's are dropped)."""
        out = OrderedDict()
        for title, r in (getattr(c, "_mw_chart", None) or {}).items():
            try:
                alive = r["anchor"] is None or bool(c.type(r["anchor"]))
            except tk.TclError:
                alive = False
            if alive:
                out[title] = r
        return out

    @classmethod
    def chart_text(cls, c, csv_=False):
        parts = []
        for title, r in cls.chart_data(c).items():
            head = [translate_text(h) for h in r["header"]]
            if csv_:
                buf = io.StringIO()
                wr = safe_csv_writer(buf)       # 5.3.4 (RT-03)
                wr.writerow([title] + ([r["note"]] if r["note"] else []))
                wr.writerow(head)
                for row in r["rows"]:
                    wr.writerow(row)
                parts.append(buf.getvalue().rstrip("\n"))
                continue
            lines = [title + (f"  ({r['note']})" if r["note"] else "")]
            rows = r["texts"] or [
                [x if i == 0 or r["fmt"] is None or x == "" else
                 r["fmt"](x) for i, x in enumerate(row)]
                for row in r["rows"]]
            lines.append("\t".join(str(h) for h in head))
            lines += ["\t".join(str(x) for x in row) for row in rows]
            parts.append("\n".join(lines))
        return "\n\n".join(parts)

    @classmethod
    def chart_menu(cls, c, e):
        if not cls.chart_data(c):
            return

        def copy(csv_):
            with contextlib.suppress(tk.TclError):
                c.clipboard_clear()
                c.clipboard_append(hide_credentials(cls.chart_text(c, csv_)))
        m = tk.Menu(c, tearoff=0)
        m.add_command(label=translate_text("Copy chart data as text"),
                      command=lambda: copy(False))
        m.add_command(label=translate_text("Copy chart data as CSV"),
                      command=lambda: copy(True))
        with contextlib.suppress(tk.TclError):
            m.tk_popup(e.x_root, e.y_root)

    @classmethod
    def hbars(cls, c, x, y, w, h, items, t, title="", color=None,
              empty="Nothing yet", tags_prefix=""):
        """items: list of (label, value, value_text, click_key). Labels
        and values are cut to their column, so a long device name or a
        value never runs into the chart beside it."""
        bold, norm, small = (("TkDefaultFont", 10, "bold"),
                             ("TkDefaultFont", 9), ("TkDefaultFont", 8))
        tid = c.create_text(x, y, anchor="nw", text=cls.elide(
            c, translate_text(title), bold, w), fill=t["text_fg"],
            font=bold)
        cls.record(c, tid, translate_text(title), ["", "Value"],
                   [[lab, v] for lab, v, _vt, _k in items],
                   texts=[[lab, vt] for lab, _v, vt, _k in items])
        if not items:
            c.create_text(x, y + 30, anchor="nw", text=translate_text(empty),
                          fill=t["muted_fg"], font=norm)
            return
        line = cls.font(c, norm).metrics("linespace")
        head = max(24, cls.font(c, bold).metrics("linespace") + 8)
        rowh_min = max(16, line + 2)
        items = items[:max(1, int((h - head - 2) // rowh_min))]
        rowh = max(rowh_min, min(24, (h - head - 2) / max(1, len(items))))
        top = y + head
        fsm = cls.font(c, small)
        valw = min(w * 0.35, max(fsm.measure(str(vt))
                                 for _l, _v, vt, _k in items) + 8)
        labw = min(170, w * 0.40)
        vmax = max(v for _l, v, _t, _k in items) or 1
        barw = max(10, w - labw - valw - 6)
        for i, (label, v, vt, key) in enumerate(items):
            yy = top + i * rowh
            tag = f"{tags_prefix}{i}" if tags_prefix else ""
            c.create_text(x, yy + rowh / 2, anchor="w",
                          text=cls.elide(c, label, norm, labw - 8),
                          fill=t["text_fg"], font=norm,
                          tags=(tag,) if tag else ())
            bw = max(3, barw * v / vmax)
            c.create_rectangle(x + labw, yy + 3, x + labw + bw,
                               yy + rowh - 3, fill=color or t["chart_down"],
                               outline="", tags=(tag,) if tag else ())
            c.create_text(x + labw + bw + 6, yy + rowh / 2, anchor="w",
                          text=cls.elide(c, vt, small, valw),
                          fill=t["muted_fg"], font=small)



# ============================================================================
#  18.  Tabs
#
#  Each tab is a small class with build() / refresh() / reset(). They all
#  read from app.model (the single NetworkModel) — Beginner and Advanced
#  views are different presentations of the same data, not separate apps.
# ============================================================================
WHITE = "#ffffff"


class BaseTab:
    name = ""
    label_key = ""
    advanced = False

    def __init__(self, app):
        self.app = app
        self.frame = tk.Frame(app.nb, bg=WHITE)
        self.build()

    @property
    def model(self):
        return self.app.model

    @property
    def t(self):
        return self.app.theme

    def is_visible(self):
        try:
            return self.app.nb.select() == str(self.frame)
        except tk.TclError:
            return False

    def header(self, text, sub=None):
        top = tk.Frame(self.frame, bg=WHITE, padx=12, pady=8)
        top.pack(fill="x")
        lbl = tk.Label(top, text=text, bg=WHITE, fg="#333333",
                       wraplength=1000, justify="left",
                       font=mw_font(11))
        lbl.pack(anchor="w")
        if sub:
            tk.Label(top, text=sub, bg=WHITE, fg="#666666",
                     wraplength=1000, justify="left",
                     font=mw_font(9)).pack(anchor="w",
                                                     pady=(2, 0))
        return top

    def toolbar(self):
        bar = tk.Frame(self.frame, bg=WHITE, padx=12)
        bar.pack(fill="x", pady=(0, 6))
        return bar

    def lbl(self, parent, text, muted=False, **kw):
        w = tk.Label(parent, text=text, bg=WHITE,
                     fg="#888888" if muted else "#333333", **kw)
        return w

    def build(self):
        pass

    def refresh(self):
        pass

    def reset(self):
        pass

    def on_theme(self):
        pass

    # what Back restores (F2): sub-view, filter fields, selected row,
    # scroll position. VIEW_VARS names the tab's filter variables, the
    # free-text one first.
    VIEW_VARS = ()

    def view_state(self):
        st = {"subview": getattr(self, "subview", None)}
        vals = {}
        for name in self.VIEW_VARS:
            var = getattr(self, name, None)
            if var is not None:
                with contextlib.suppress(tk.TclError):
                    vals[name] = var.get()
        st["vars"] = vals
        if self.VIEW_VARS:
            st["query"] = str(vals.get(self.VIEW_VARS[0], "") or "").strip()
        kit = getattr(self, "kit", None)
        tree = getattr(self, "tree", None)
        if kit is not None and tree is not None:
            with contextlib.suppress(tk.TclError):
                sel = tree.selection()
                st["sel"] = kit.key_of(sel[0]) if sel else None
                st["y"] = tree.yview()[0]
            st["sort"] = [kit.sort_col, kit.sort_desc]
            st["cols"] = list(kit.shown_cols())
        return st

    def apply_view_state(self, st):
        if st.get("subview") and hasattr(self, "_sub_frames") and \
                st["subview"] != getattr(self, "subview", None):
            self.show_subview(st["subview"])
        changed = False
        for name, val in (st.get("vars") or {}).items():
            var = getattr(self, name, None)
            if var is not None and var.get() != val:
                var.set(val)
                changed = True
        if changed:
            self.apply_filters()
        kit = getattr(self, "kit", None)
        tree = getattr(self, "tree", None)
        if kit is None or tree is None:
            return
        if st.get("cols") and list(st["cols"]) != list(kit.shown_cols()):
            kit._cols_override = list(st["cols"])
            kit.apply_columns()
        srt = st.get("sort")
        if isinstance(srt, list) and len(srt) == 2 and \
                (srt[0], bool(srt[1])) != (kit.sort_col, kit.sort_desc):
            kit.sort_col, kit.sort_desc = srt[0], bool(srt[1])
            kit.resort()
        want = st.get("sel")
        if want is not None:
            for iid in kit.all_iids():
                if kit.key_of(iid) == want:
                    with contextlib.suppress(tk.TclError):
                        parent = tree.parent(iid)
                        if parent:
                            tree.item(parent, open=True)
                        tree.selection_set(iid)
                        tree.focus(iid)
                    break
        if st.get("y") is not None:
            with contextlib.suppress(tk.TclError):
                tree.yview_moveto(st["y"])

    def rebuild_in_slices(self):
        """rebuild_steps() a slice (~30 ms) per callback, so showing a tab
        that has to catch up does not freeze the window (a 3,000-row
        Connections refill took 110 ms in one go)."""
        steps = self.rebuild_steps()
        app = self.app

        def step():
            end = time.perf_counter() + app.REBUILD_SLICE
            try:
                while time.perf_counter() < end:
                    next(steps)
            except StopIteration:
                return
            except tk.TclError:
                return
            app.root.after(1, step)
        step()

    def apply_filters(self):
        """The filter fields changed from outside (Back): show it."""
        fn = getattr(self, "rebuild", None)
        if fn is not None:
            fn()

    def make_subviews(self, names, on_switch=None):
        """A row of buttons at the top of the tab that switches between
        sub-views (no extra top-level tabs). → {name: frame}."""
        outer = self.frame
        bar = tk.Frame(outer, bg=WHITE, padx=12)
        bar.pack(fill="x", pady=(6, 0))
        self._sub_frames, self._sub_btns = {}, {}
        self._sub_cb = on_switch
        for n in names:
            self._sub_frames[n] = tk.Frame(outer, bg=WHITE)
            b = ttk.Button(bar, text=n, command=lambda n=n:
                           self.show_subview(n))
            b.pack(side="left", padx=(0, 4))
            self._sub_btns[n] = b
        self.subview = names[0]
        self._sub_frames[names[0]].pack(fill="both", expand=True)
        self._style_subviews()
        return self._sub_frames

    def _style_subviews(self):
        for n, b in getattr(self, "_sub_btns", {}).items():
            with contextlib.suppress(tk.TclError):
                b.configure(style="Sub.Accent.TButton" if n == self.subview
                            else "Sub.TButton")

    def show_subview(self, name):
        if name not in getattr(self, "_sub_frames", {}):
            return
        for f in self._sub_frames.values():
            f.pack_forget()
        self._sub_frames[name].pack(fill="both", expand=True)
        self.subview = name
        self._style_subviews()
        if self._sub_cb:
            self._sub_cb(name)

    def device_choices(self):
        devs = sorted(self.model.registry.by_key.values(),
                      key=lambda d: d.display_name().lower())
        return ["All devices"] + [f"{d.display_name()}  [{d.ip or d.mac}]"
                                  for d in devs][:400]

    def device_key_from_choice(self, choice):
        if not choice or choice == "All devices":
            return None
        m = re.search(r"\[([^\]]+)\]\s*$", choice)
        if not m:
            return None
        ident = m.group(1)
        dev = self.model.device_for(ident, ident)
        return dev.key if dev else None


# ---- Inspector (docked evidence pane, F2) -------------------------------------
class Inspector:
    """Shows the selected device / website / remote host / connection /
    alert as a list of claims, each with its evidence level and clickable
    proof chips (#packet numbers) that open the packet behind it."""

    WIDTH = 360

    def __init__(self, app, parent):
        self.app = app
        self.frame = tk.Frame(parent, bg=WHITE, width=px(self.WIDTH))
        head = tk.Frame(self.frame, bg=WHITE, padx=10, pady=6)
        head.pack(fill="x")
        self.title_var = DisplayVar(value="Inspector")
        tk.Label(head, textvariable=self.title_var, bg=WHITE, fg="#2b3a56",
                 font=mw_font(11, "bold"), anchor="w",
                 justify="left", wraplength=self.WIDTH - 40).pack(
            side="left", fill="x", expand=True)
        close = tk.Label(head, text="✕", bg=WHITE, fg="#666666",
                         cursor="hand2")
        close.pack(side="right")
        close.bind("<Button-1>", lambda e: app.toggle_inspector(False))
        Tooltip(close, "Hide the inspector (F2 shows it again)")
        body = tk.Frame(self.frame, bg=WHITE)
        body.pack(fill="both", expand=True, padx=(8, 4))
        self.txt = tk.Text(body, wrap="word", bg=WHITE, fg="#222222",
                           relief="flat", highlightthickness=0, padx=4,
                           pady=4, cursor="arrow", width=40,
                           font=mw_font(10))
        vs = ttk.Scrollbar(body, orient="vertical", command=self.txt.yview)
        self.txt.configure(yscrollcommand=vs.set, state="disabled")
        self.txt.pack(side="left", fill="both", expand=True)
        vs.pack(side="right", fill="y")
        self.legend = tk.Label(
            self.frame, text="◉ observed  ◈ reported  ◎ correlated  "
                             "◌ inferred  ? unknown", bg=WHITE,
            fg="#666666", font=mw_font(8), anchor="w",
            justify="left", wraplength=self.WIDTH - 30)
        self.legend.pack(fill="x", padx=10, pady=(0, 6))
        self.frame.bind("<Configure>", self._on_resize)
        self.current = None
        self._chip = 0
        self.on_theme()
        self._empty()

    def _on_resize(self, event):
        w = max(120, event.width - 30)
        with contextlib.suppress(tk.TclError):
            self.legend.configure(wraplength=w)
            for child in self.frame.winfo_children()[0].winfo_children():
                if isinstance(child, tk.Label) and child.cget("textvariable"):
                    child.configure(wraplength=w - 20)

    # ---- rendering helpers
    def on_theme(self):
        t = self.app.theme
        with contextlib.suppress(tk.TclError):
            self.txt.configure(bg=t["tab_bg"], fg=t["text_fg"],
                               insertbackground=t["text_fg"])
            self.txt.tag_configure("h", font=mw_font(10, "bold"),
                                   foreground=t["text_fg"], spacing1=6)
            self.txt.tag_configure("muted", foreground=t["muted_fg"],
                                   font=mw_font(9))
            self.txt.tag_configure("chip", foreground=t["accent"],
                                   underline=True,
                                   font=mw_font(9))
            self.txt.tag_configure("link", foreground=t["accent"],
                                   underline=True)
            self.txt.tag_configure("warn", foreground=t["warn_fg"])
            self.txt.tag_configure("good", foreground=t["good_fg"])
            self.txt.tag_configure("explain", foreground=t["accent"],
                                   font=mw_font(9), lmargin1=18,
                                   lmargin2=18)

    def _begin(self, title):
        self.title_var.set(title)
        self.txt.configure(state="normal")
        self.txt.delete("1.0", "end")
        for tag in self.txt.tag_names():
            if tag.startswith("c_"):
                self.txt.tag_delete(tag)

    def _end(self):
        with contextlib.suppress(Exception):
            gloss_mark(self.txt, self.app)
        self.txt.configure(state="disabled")

    def _w(self, text, *tags):
        # 5.1.2: in the current language (it stayed English in French)
        self.txt.insert("end", translate_lines(text), tags)

    def _clickable(self, text, fn, base="link"):
        self._chip += 1
        tag = f"c_{self._chip}"
        self.txt.insert("end", translate_text(text), (base, tag))
        self.txt.tag_bind(tag, "<Button-1>", lambda e: fn())
        self.txt.tag_bind(tag, "<Enter>",
                          lambda e: self.txt.configure(cursor="hand2"))
        self.txt.tag_bind(tag, "<Leave>",
                          lambda e: self.txt.configure(cursor="arrow"))

    def _claim(self, label, value, level, why=""):
        # French puts a space before the colon
        colon = " : " if CURRENT_LOCALE == "fr" else ": "
        self._w(f"{LEVEL_GLYPH.get(level, '?')} {translate_text(label)}"
                f"{colon}", "h")
        self._w(f"{value}\n")
        if why:
            if "; " in why and CURRENT_LOCALE != "en":
                why = "; ".join(translate_text(x) for x in why.split("; "))
            self._w(f"   {why}\n", "muted")
        if self.app.explain_on():
            self._w(f"   {LEVEL_GLYPH.get(level, '?')} "
                    f"{translate_text(LEVEL_WORD.get(level, 'Unknown'))}: "
                    f"{translate_text(explain('level', level))}\n",
                    "explain")

    def _chips(self, obs, limit=5):
        obs = [o for o in obs if o[5]][-limit:]
        if not obs:
            return
        self._w("   proof: ", "muted")
        for o in obs:
            no = o[5]
            self._clickable(f"#{no}", lambda n=no: self.app.jump_to_packet(n),
                            "chip")
            self._w(f" {OBS_KIND_TEXT.get(o[2], o[2])} "
                    f"{fmt_clock(o[1])}   ", "muted")
        self._w("\n")

    def _empty(self):
        self._begin("Inspector")
        self._w("Select a device, website, connection or alert to see "
                "what MiniWireshark knows about it — and how it knows.\n\n",
                "muted")
        self._w("Every statement carries a mark:\n", "muted")
        for lv in (LV_OBSERVED, LV_REPORTED, LV_CORRELATED, LV_INFERRED,
                   LV_UNKNOWN):
            self._w(f"{LEVEL_GLYPH[lv]} {LEVEL_WORD[lv]}", "h")
            self._w(f" — {LEVEL_HELP[lv]}\n", "muted")
        self._end()

    # ---- entry point
    def show(self, kind, key):
        self.current = (kind, key)
        fn = {"device": self._show_device, "website": self._show_website,
              "remote": self._show_remote, "flow": self._show_flow,
              "alert": self._show_alert, "slow": self._show_slow}.get(kind)
        try:
            if fn is None or not fn(key):
                self._empty()
        except tk.TclError:
            pass

    def refresh(self):
        if self.current:
            self.show(*self.current)

    # ---- 5.1.2: "Why is it slow?" docked here (the window's "Show in the
    # Inspector"); the same ranking, narrower
    SLOW_TAG = {"Likely": "warn", "Possible": "warn", "Can't tell": "muted",
                "Unlikely": "good"}

    def _show_slow(self, _key=""):
        app, tr = self.app, translate_text
        hyps = investigate_slow(app.collect_slow_facts())
        self._begin(tr("Why is it slow?"))
        self._w(tr("A ranked list, not a verdict.") + " " +
                app.slow_freshness() + "\n", "muted")
        for h in hyps:
            st = h["status"]
            self._w(tr(h["title"]) + "\n", "h")
            self._w("   " + tr(st) + "\n", self.SLOW_TAG.get(st, "muted"))
            if st == "Unlikely":
                for it in h["against"][:1]:
                    self._w("   " + tr("Against: " + it) + "\n", "muted")
                continue
            for it in h["for"]:
                self._w("   " + tr("For: " + it) + "\n")
            for it in h["against"]:
                self._w("   " + tr("Against: " + it) + "\n", "muted")
            if h["fix"]:
                self._w("   " + tr("What to try: " + h["fix"]) + "\n",
                        "muted")
        self._w("\n")
        self._clickable(tr("Check again"), self._slow_again)
        self._w("    ")
        self._clickable(tr("Open in a window…"),
                        lambda: app.investigate("slow"))
        self._end()
        return True

    def _slow_again(self):
        """Ask for a check where checks may be sent, then rank again when
        it lands (or after a few seconds)."""
        app = self.app
        if app.health_checks_allowed():
            with contextlib.suppress(AttributeError):
                app.prober.run_now.set()
            n0 = len(app.model.health_history)
            t0 = time.monotonic()

            def wait():
                if self.current != ("slow", ""):
                    return
                if len(app.model.health_history) > n0 or \
                        time.monotonic() - t0 > app.CHECK_WAIT_S:
                    self.refresh()
                    return
                self.frame.after(250, wait)
            self.title_var.set(translate_text("Checking the router…"))
            self.frame.after(250, wait)
        else:
            self.refresh()

    # ---- entity views
    def _show_device(self, key):
        m = self.app.model
        dev = m.registry.by_key.get(m.registry.resolve(key))
        if dev is None:
            return False
        self._begin(f"{DEVICE_ICONS.get(dev.type, '❓')} "
                    f"{dev.display_name()}")
        for label, value, level, why, kinds in device_claims(m, dev):
            self._claim(label, value, level, why)
            if kinds:
                self._chips(m.observations_for(dev.key, kinds))
        sites = []
        for dom in dev.websites:
            w = m.websites.get(dom)
            if w is not None:
                sites.append((ASSOC_RANK.get(w.ties.get(dev.key, [""])[0], 0),
                              dom, w.ties.get(dev.key, [""])[0]))
        if sites:
            self._w("\nWebsites\n", "h")
            for _r, dom, a in sorted(sites, reverse=True)[:12]:
                self._w(f"  {assoc_label(a)}  ")
                self._clickable(dom, lambda d=dom: self.app.inspect(
                    "website", d))
                self._w("\n")
        if dev.merge_history:
            self._w("\nMerged identities: ", "h")
            self._w(", ".join(h.get("key", "?") for h in dev.merge_history)
                    + "\n", "muted")
        held = m.registry.bindings.history(dev.ip) if dev.ip else []
        if len(held) > 1:
            self._w("\nThis address over time\n", "h")
            for owner, start, end, src in held[-4:]:
                who = "this device" if owner in (dev.mac, dev.key) else owner
                self._w(f"  {fmt_clock(start)}–"
                        f"{fmt_clock(end) if end else 'now'}  {who} "
                        f"({src})\n", "muted")
        self._w("\n")
        self._clickable("Open full details…",
                        lambda: self.app.show_device(dev.key))
        self._w("    ")
        self._clickable("Show its packets", lambda: self.app.goto(
            "packets", f'device:"{dev.ip or dev.mac}"'))
        self._end()
        return True

    def _show_website(self, dom):
        m = self.app.model
        w = m.websites.get(dom)
        if w is None:
            return False
        self._begin(f"\U0001F30D {w.domain}")
        self._claim("Best evidence", ASSOC_TEXT.get(w.best_assoc, "unknown"),
                    ASSOC_LEVEL.get(w.best_assoc, LV_UNKNOWN),
                    "A lookup alone doesn't prove a visit; HTTPS shows "
                    "only the site name, never the page.")
        self._w("\nDevices\n", "h")
        obs = m.observations_for("site:" + dom)
        for dev_key, t in sorted(w.ties.items(),
                                 key=lambda kv: -ASSOC_RANK.get(kv[1][0],
                                                                0))[:15]:
            self._w(f"  {assoc_label(t[0])}  ")
            self._clickable(self.app.short_device_name(dev_key),
                            lambda k=dev_key: self.app.inspect("device", k))
            self._w(f"  ×{t[3]}\n", "muted")
            self._chips([o for o in obs if o[3] == dev_key], 3)
        if not w.ties:
            self._w("  (no device tied to it — e.g. the router's own "
                    "lookup)\n", "muted")
        self._claim("Server addresses",
                    ", ".join(sorted(w.resolved_ips)[:6]) or "—",
                    LV_OBSERVED if w.resolved_ips else LV_UNKNOWN,
                    "From DNS answers or the connection itself.")
        self._claim("Encryption", w.encryption_text(),
                    LV_OBSERVED if (w.encrypted or w.cleartext)
                    else LV_UNKNOWN)
        self._w("\n")
        self._clickable("Open full details…",
                        lambda: self.app.show_website(dom))
        self._end()
        return True

    def _show_remote(self, ip):
        m = self.app.model
        r = m.remote_hosts.get(ip)
        if r is None:
            return False
        self._begin(f"☁️ {ip}")
        names = list(m.ip_to_domains.get(ip) or ())
        self._claim("Names for this address",
                    ", ".join(names[-5:]) or "none seen",
                    LV_CORRELATED if names else LV_UNKNOWN,
                    "Names come from DNS answers and secure-connection "
                    "names; shared (CDN) addresses serve many sites.")
        self._claim("Never a local device", "it's on the Internet",
                    LV_OBSERVED, "Public addresses are kept separate from "
                    "your devices.")
        if r.country or r.asn:
            self._claim("Location / provider",
                        f"{r.country_name or r.country} {r.org}".strip(),
                        LV_REPORTED, f"From {r.geo_source or 'a database'};"
                        f" an estimate.")
        self._claim("Traffic", f"↑{_human_bytes(r.bytes_out)} "
                               f"↓{_human_bytes(r.bytes_in)} · "
                               f"{r.connections} connections", LV_OBSERVED)
        self._w("\nDevices\n", "h")
        for k in sorted(r.devices)[:12]:
            self._w("  ")
            self._clickable(self.app.short_device_name(k),
                            lambda kk=k: self.app.inspect("device", kk))
            self._w("\n")
        self._w("\n")
        self._clickable("Open full details…",
                        lambda: self.app.show_remote(ip))
        self._end()
        return True

    def _show_flow(self, fid):
        m = self.app.model
        f = m.flows.get(fid)
        if f is None:
            return False
        self._begin(f"\U0001F517 Connection #{f.fid}")
        self._claim("Device", self.app.short_device_name(f.device_key)
                    if f.device_key else f.local_ip,
                    LV_OBSERVED if f.device_key else LV_UNKNOWN,
                    f"{f.local_ip}:{f.local_port}")
        self._claim("Other side", f"{f.remote_ip}:{f.remote_port}",
                    LV_OBSERVED)
        if f.domain:
            self._claim("Website", f"{f.domain} — "
                        f"{ASSOC_TEXT.get(f.assoc, f.domain_conf)}",
                        ASSOC_LEVEL.get(f.assoc, LV_INFERRED),
                        f.domain_conf)
        else:
            self._claim("Website", "unknown", LV_UNKNOWN,
                        "No name was visible and no lookup preceded it.")
        purpose_lvl = LV_OBSERVED if f.interp_conf == "Observed" else \
            LV_INFERRED
        self._claim("Purpose", f.purpose(), purpose_lvl, f.interp_conf or "")
        self._claim("Encryption", f.encryption_text(),
                    LV_OBSERVED if f.encrypted in ("yes", "no")
                    else LV_INFERRED)
        self._claim("Traffic", f"↑{_human_bytes(f.bytes_out)} "
                               f"↓{_human_bytes(f.bytes_in)} · "
                               f"{f.packets} packets · {f.status_text()}",
                    LV_OBSERVED)
        self._chips(m.observations_for(f"flow:{f.fid}"), 3)
        self._w("\n")
        self._clickable("Show its packets", lambda: self.app.goto(
            "packets", f"stream:{f.fid}"))
        self._end()
        return True

    def _show_alert(self, aid):
        m = self.app.model
        a = m.alerts.alerts.get(aid)
        if a is None:
            return False
        self._begin(f"{MiniWireshark.SEVERITY_ICON.get(a.severity, '')} "
                    f"{a.reason}")
        self._claim("What was observed", a.observed, LV_OBSERVED)
        self._claim("What it might mean", a.interpretation, LV_INFERRED,
                    f"Confidence: {a.confidence}. {a.why}")
        self._claim("Innocent explanations", a.possible_explanations,
                    LV_INFERRED)
        if a.evidence:
            self._w("\nEvidence\n", "h")
            for e in a.evidence[-8:]:
                self._w(f"  • {e}\n", "muted")
        if a.device_key:
            self._w("\n")
            self._clickable("Go to the device", lambda: self.app.inspect(
                "device", a.device_key))
        self._end()
        return True


# ---- Dashboard ---------------------------------------------------------------
class DashboardTab(BaseTab):
    name, label_key = "dash", "tab_dashboard"
    CARDS = (
        ("internet", "INTERNET", "health"),
        ("capture", "CAPTURE", "help"),
        ("active", "ACTIVE DEVICES", "devices"),
        ("known", "KNOWN DEVICES", "devices_all"),
        ("down", "DOWNLOAD NOW", "connections"),
        ("up", "UPLOAD NOW", "connections"),
        ("pps", "PACKETS / SEC", "packets"),
        ("dns", "DNS HEALTH", "health"),
        ("alerts", "ALERTS", "alerts"),
        ("topdev", "MOST ACTIVE DEVICE", "topdev"),
        ("topsite", "MOST CONTACTED WEBSITE", "topsite"),
        ("duration", "CAPTURE DURATION", "timeline"),
    )
    RANGES = {"Last 5 minutes": (1, 300), "Last hour": (10, 360),
              "Last 24 hours": (60, 1440)}
    # Explain inline: one grey line under each card title
    CARD_EXPLAIN = {
        "internet": "Whether the Internet answers from here, measured "
                    "passively from your own traffic.",
        "capture": "What MiniWireshark is listening to right now.",
        "active": "Devices that sent something in the last few minutes.",
        "known": "Every device seen, including those now offline.",
        "down": "What is arriving from the Internet right now.",
        "up": "What is leaving for the Internet right now.",
        "pps": "How busy the network card is.",
        "dns": "How quickly names (like example.com) are answered.",
        "alerts": "Unusual things worth a look; none means 'hacked'.",
        "topdev": "The device moving the most data right now.",
        "topsite": "The website most looked up or connected to.",
        "duration": "How long this capture has been running.",
    }

    def build(self):
        # scrolls on a short screen (the second row of cards was cut off
        # on a 768-pixel laptop); the charts fill whatever height is left
        self.scroller, outer = make_scrollable(self.frame, WHITE)
        self.scroller.pack(fill="both", expand=True)
        outer.configure(padx=14, pady=10)
        self._outer = outer
        self.scroller.canvas.bind("<Configure>", self._fit_charts, add="+")
        head = tk.Frame(outer, bg=WHITE)
        head.pack(fill="x")
        tk.Label(head, text="\U0001F4CA  Dashboard", bg=WHITE, fg="#2b3a56",
                 font=mw_font(14, "bold")).pack(side="left")
        self.range_var = tk.StringVar(value="Last 5 minutes")
        cb = ttk.Combobox(head, textvariable=self.range_var,
                          values=list(self.RANGES), width=14,
                          state="readonly")
        cb.pack(side="right")
        cb.bind("<<ComboboxSelected>>", lambda e: self.refresh(force=True))
        tk.Label(head, text="Charts:", bg=WHITE, fg="#666666").pack(
            side="right", padx=6)
        tk.Label(outer, text="A quick overview — click any card to open "
                             "the full picture.", bg=WHITE,
                 fg="#666666").pack(anchor="w", pady=(0, 8))
        self.state_var = DisplayVar(value="Getting started …")
        self.state_lbl = tk.Label(outer, textvariable=self.state_var,
                                  bg="#eef4fb", fg="#0b5394", anchor="w",
                                  justify="left", wraplength=1100, padx=12,
                                  pady=8, font=mw_font(11))
        self.answers = FEATURES.get("answer_cards", True)
        if self.answers:
            self._build_answers(outer)
        else:
            self.state_lbl.pack(fill="x", pady=(0, 8))
        self.story_card = None
        if FEATURES.get("story_mode", True):
            self._build_story_card(outer)
        self.big = tk.Frame(outer, bg=WHITE)
        if not self.answers:
            self.big.pack(fill="x", pady=(0, 4))
        self.big_vars = {}
        for i, (key, title, cmd) in enumerate((
                ("coverage", "WHAT I CAN SEE FROM HERE",
                 lambda: self.app.open_coverage()),
                ("changed", "WHAT CHANGED (LAST HOUR)",
                 lambda: self.app.open_changes("Last hour")))):
            card = tk.Frame(self.big, bg="#f6f7fa", padx=12, pady=8,
                            highlightbackground="#e0e2e8",
                            highlightthickness=1, cursor="hand2",
                            takefocus=1)
            card.grid(row=0, column=i, sticky="nsew", padx=4)
            tl = tk.Label(card, text=title, bg="#f6f7fa", fg="#888888",
                          font=mw_font(8, "bold"), anchor="w")
            tl.pack(anchor="w")
            v = DisplayVar(value="—")
            vl = tk.Label(card, textvariable=v, bg="#f6f7fa", fg="#222222",
                          font=mw_font(10), justify="left",
                          anchor="w", wraplength=520)
            vl.pack(anchor="w", fill="x", pady=(2, 0))
            self.big_vars[key] = v
            for w in (card, tl, vl):
                w.bind("<Button-1>", lambda e, c=cmd: c())
            card.bind("<Return>", lambda e, c=cmd: c())
            self.big.columnconfigure(i, weight=1, uniform="big")
        grid = tk.Frame(outer, bg=WHITE)
        grid.pack(fill="x")
        self.card_grid, self.card_frames, self._card_cols = grid, [], 6
        self.vars, self.card_widgets = {}, []
        for i, (key, title, target) in enumerate(self.CARDS):
            card = tk.Frame(grid, bg="#f6f7fa", padx=12, pady=8,
                            highlightbackground="#e0e2e8",
                            highlightthickness=1, cursor="hand2",
                            takefocus=1)
            card.grid(row=i // 6, column=i % 6, sticky="nsew", padx=4,
                      pady=4)
            card.configure(highlightcolor="#2b7de9")
            self.card_frames.append(card)
            tl = tk.Label(card, text=title, bg="#f6f7fa", fg="#888888",
                          font=mw_font(8, "bold"), anchor="w",
                          justify="left", wraplength=170)
            tl.pack(anchor="w")
            ex = tk.Label(card, text=self.CARD_EXPLAIN.get(key, ""),
                          bg="#f6f7fa", fg="#666666", font=mw_font(8),
                          anchor="w", justify="left", wraplength=170)
            self.explain_lbls = getattr(self, "explain_lbls", [])
            self.explain_lbls.append((ex, tl))
            v = DisplayVar(value="—")
            vl = tk.Label(card, textvariable=v, bg="#f6f7fa", fg="#222222",
                          font=mw_font(12, "bold"), justify="left",
                          anchor="w", wraplength=170)
            vl.pack(anchor="w", pady=(2, 0))
            self.vars[key] = v
            for w in (card, tl, vl):
                w.bind("<Button-1>", lambda e, tg=target: self.app.goto(tg))
            card.bind("<Return>", lambda e, tg=target: self.app.goto(tg))
            Tooltip(card, "Click to open the details.")
        for c in range(6):
            grid.columnconfigure(c, weight=1, uniform="card")
        grid.bind("<Configure>", self._reflow_cards, add="+")
        self.show_explain(self.app.explain_on())
        self.canvas = tk.Canvas(outer, bg=WHITE, highlightthickness=0,
                                height=140)
        self.canvas.pack(fill="both", expand=True, pady=(10, 0))
        self.canvas.bind("<Configure>", lambda e: self.refresh(force=True))
        self.canvas.bind("<Button-1>", self._on_chart_click)
        self._click_items = {}

    # 5.1.2: three questions answered in a sentence each, then the honesty
    # line (what this computer can see); the number cards and charts follow
    ANSWERS = (("wrong", "Is anything wrong?"),
               ("usage", "Who is using the Internet?"),
               ("new", "What is new?"))
    ANSWER_FG = {"good": "#0b6b3a", "warn": "#8a5a00", "bad": "#8a1a08",
                 "muted": "#666666", "": "#222222"}

    def _build_answers(self, outer):
        box = tk.Frame(outer, bg=WHITE)
        box.pack(fill="x", pady=(0, 2))
        self.answer_box = box
        self.answer_lbls, self.answer_show = {}, {}
        for i, (key, question) in enumerate(self.ANSWERS):
            card = tk.Frame(box, bg="#f6f7fa", padx=12, pady=8,
                            highlightbackground="#e0e2e8",
                            highlightthickness=1, cursor="hand2",
                            takefocus=1)
            card.grid(row=0, column=i, sticky="nsew", padx=4)
            card.configure(highlightcolor="#2b7de9")
            q = tk.Label(card, text=question, bg="#f6f7fa", fg="#2b3a56",
                         font=mw_font(10, "bold"), anchor="w",
                         justify="left")
            q.pack(anchor="w", fill="x")
            a = tk.Label(card, text="…", bg="#f6f7fa", fg="#222222",
                         font=mw_font(10), anchor="w", justify="left",
                         wraplength=320)
            a.pack(anchor="w", fill="x", pady=(3, 4))
            more = tk.Label(card, text="Show me ›", bg="#f6f7fa",
                            fg="#0b5394", anchor="w", cursor="hand2")
            more.pack(anchor="w")
            for w in (card, q, a, more):
                w.bind("<Button-1>", lambda e, k=key: self._answer_show(k))
            card.bind("<Return>", lambda e, k=key: self._answer_show(k))
            card.bind("<Configure>", lambda e, lb=a: self._fit_answer(
                lb, e.width), add="+")
            self.answer_lbls[key] = a
            box.columnconfigure(i, weight=1, uniform="answer")
        self.honest_lbl = tk.Label(outer, text="", bg=WHITE, fg="#666666",
                                   anchor="w", justify="left",
                                   cursor="hand2")
        self.honest_lbl.pack(fill="x", padx=4, pady=(2, 8))
        self.honest_lbl.bind("<Button-1>",
                             lambda e: self.app.open_coverage())
        Tooltip(self.honest_lbl, "What this computer can and can't see "
                                 "from where it is — click for details.")

    def _build_story_card(self, outer):
        """5.3.4 (M7, MC4): "3 changes since you last looked", opening the
        Timeline in Story mode. Written by the jobs thread; this only
        shows the sentence."""
        card = tk.Frame(outer, bg="#f6f7fa", padx=12, pady=6,
                        highlightbackground="#e0e2e8", highlightthickness=1,
                        cursor="hand2", takefocus=1)
        card.configure(highlightcolor="#2b7de9")
        where = {"before": self.honest_lbl} if self.answers else \
            {"after": self.state_lbl}
        card.pack(fill="x", padx=4, pady=(0, 6), **where)
        title = tk.Label(card, text="\U0001F4D6  What changed: the story",
                         bg="#f6f7fa", fg="#2b3a56", font=mw_font(10, "bold"),
                         anchor="w")
        title.pack(side="left")
        self.story_lbl = tk.Label(card, text="…", bg="#f6f7fa",
                                  fg="#222222", font=mw_font(10), anchor="w",
                                  justify="left")
        self.story_lbl.pack(side="left", padx=(10, 0), fill="x",
                            expand=True)
        more = tk.Label(card, text="Read the story ›", bg="#f6f7fa",
                        fg="#0b5394", anchor="e", cursor="hand2")
        more.pack(side="right")
        for w in (card, title, self.story_lbl, more):
            w.bind("<Button-1>", lambda e: self.app.open_story())
        card.bind("<Return>", lambda e: self.app.open_story())
        Tooltip(card, "The changes of the last days in plain sentences, "
                      "with what is new since you last looked.")
        self.story_card = card

    def show_story_card(self):
        """The card's sentence from the last story (no work here)."""
        if self.story_card is None:
            return ""
        app = self.app
        st = app.story
        if st is not None and st.get("model_id") != id(app.model):
            st = None
        text = story_card_text(st, app.data_mode)
        with contextlib.suppress(tk.TclError):
            if self.story_lbl.cget("text") != text:
                self.story_lbl.configure(text=text)
        return text

    @staticmethod
    def _fit_answer(lbl, width):
        want = max(160, width - 30)
        with contextlib.suppress(tk.TclError, ValueError):
            if abs(int(float(str(lbl.cget("wraplength")) or 0)) - want) > 4:
                lbl.configure(wraplength=want)

    def _answer_show(self, key):
        fn = self.answer_show.get(key)
        if fn is not None:
            fn()

    def _refresh_answers(self):
        app = self.app
        got = app.dashboard_answers()
        for key, _q in self.ANSWERS:
            text, kind, show = got[key]
            self.answer_show[key] = show
            lbl = self.answer_lbls[key]
            fg = self.ANSWER_FG.get(kind, "#222222")
            table = PALETTES[palette_name(app.theme_name,
                                          app.high_contrast)]
            fg = table.get(fg, fg)
            with contextlib.suppress(tk.TclError):
                if lbl.cget("text") != text or lbl.cget("fg") != fg:
                    lbl.configure(text=text, fg=fg)
        with contextlib.suppress(tk.TclError):
            h = app.honesty_line()
            if self.honest_lbl.cget("text") != h:
                self.honest_lbl.configure(text=h)

    def show_explain(self, on):
        for ex, tl in getattr(self, "explain_lbls", ()):
            with contextlib.suppress(tk.TclError):
                if on and not ex.winfo_manager():
                    ex.pack(anchor="w", after=tl)
                elif not on and ex.winfo_manager():
                    ex.pack_forget()

    def _fit_charts(self, e):
        try:
            others = self._outer.winfo_reqheight() - \
                self.canvas.winfo_reqheight()
            want = max(240, e.height - others - 8)
            if abs(int(self.canvas.cget("height")) - want) > 4:
                self.canvas.configure(height=want)
        except (tk.TclError, AttributeError):
            pass

    def _reflow_cards(self, e):
        """Six cards a row on a wide window, four or three on a narrow
        one (they were squeezed until their titles were cut)."""
        cols = 6 if e.width >= 1150 else 4 if e.width >= 760 else 3
        if cols == self._card_cols:
            return
        self._card_cols = cols
        g = self.card_grid
        for c in range(6):
            g.columnconfigure(c, weight=1 if c < cols else 0,
                              uniform="card" if c < cols else "",
                              minsize=0)
        for i, card in enumerate(self.card_frames):
            card.grid_configure(row=i // cols, column=i % cols)

    def _on_chart_click(self, event):
        ids = self.canvas.find_overlapping(event.x - 2, event.y - 2,
                                           event.x + 2, event.y + 2)
        for i in ids:
            for tag in self.canvas.gettags(i):
                if tag in self._click_items:
                    kind, key = self._click_items[tag]
                    if kind == "device":
                        self.app.show_device(key)
                    elif kind == "website":
                        self.app.goto("websites", key)
                    return

    def refresh(self, force=False):
        if not force and not self.is_visible():
            return
        m, app = self.model, self.app
        if self.story_card is not None:
            app.request_story()         # a job; at most once a minute
            self.show_story_card()
        now = m.now()
        devs = [d for d in m.registry.visible_devices()]
        active = sum(1 for d in devs if d.state in (STATE_ACTIVE, STATE_IDLE))
        self.vars["active"].set(str(active))
        self.vars["known"].set(f"{len(m.registry.by_key)}")
        down = m.metrics.current("bytes_down", now)
        up = m.metrics.current("bytes_up", now)
        self.vars["down"].set(human_rate(down))
        self.vars["up"].set(human_rate(up))
        self.vars["pps"].set(f"{m.metrics.current('packets', now):.0f}")
        c = m.alerts.counts()
        self.vars["alerts"].set(f"‼ {c['DANGER']}  ⚠ {c['WARNING']}  "
                                f"ℹ {c['INFO']}")
        self.vars["capture"].set(app.capture_status_short())
        self.vars["internet"].set(app.internet_status_short())
        self.vars["dns"].set(app.dns_status_short())
        top = max((d for d in m.registry.by_key.values()),
                  key=lambda d: d.bytes_up + d.bytes_down, default=None)
        self.vars["topdev"].set(app.device_label(top)[:24] if top and
                                (top.bytes_up + top.bytes_down) else "—")
        site = max(m.websites.values(), key=lambda w: w.requests,
                   default=None)
        self.vars["topsite"].set(site.registrable[:26] if site else "—")
        self.vars["duration"].set(human_duration(m.metrics.duration(now))
                                  if m.metrics.first_ts else "—")
        if self.answers:
            self._refresh_answers()
            self._draw_charts(now)
            return
        state, bg, fg = app.network_state_text()
        self.state_var.set(state)
        v = m.vantage.classify(offline=app.data_mode in ("offline",
                                                         "session"))
        spots = blind_spots(m, app.data_mode, app.active_mode())
        self.big_vars["coverage"].set(
            f"{VANTAGE_TEXT[v][0]}. " + (
                "Blind spots: " + "; ".join(spots) + "." if spots else
                "No known blind spots right now.") + "  (click for details)")
        self.big_vars["changed"].set(app.changes_summary_short())
        with contextlib.suppress(tk.TclError):
            self.state_lbl.configure(bg=bg, fg=fg)
        self._draw_charts(now)

    def _draw_charts(self, now):
        c, t, m = self.canvas, self.t, self.model
        try:
            # the real size: drawing for at least 600 × 300 cut the right
            # and bottom off on small windows
            w = max(320, c.winfo_width())
            h = max(120, c.winfo_height())
        except tk.TclError:
            return
        res, n = self.RANGES.get(self.range_var.get(), (1, 300))
        span = res * n
        xl = (f"-{human_duration(span)}", "now")
        down = [v / res for _b, v in m.metrics.series["bytes_down"].series(
            res, n, now)]
        up = [v / res for _b, v in m.metrics.series["bytes_up"].series(
            res, n, now)]
        pps = [v / res for _b, v in m.metrics.series["packets"].series(
            res, n, now)]
        # 5.1.2: nothing to redraw when the data, size and theme are the
        # same as last time (the whole canvas was redrawn every 2 s)
        sig = (w, h, res, self.app.theme_name, self.app.high_contrast,
               CVD_STATE["mode"], tuple(down), tuple(up), tuple(pps),
               len(m.registry.by_key), len(m.websites), m.cache.version,
               m.journal._next, sum(1 for e in m.journal.entries
                                    if e["undone"]),
               m.metrics.duration(now) // 5 if m.metrics.first_ts else 0)
        if sig == getattr(self, "_chart_sig", None):
            return
        self._chart_sig = sig
        try:
            c.delete("all")
        except tk.TclError:
            return
        c.configure(bg=t["tab_bg"])
        half = w / 2
        bars = h >= 260                 # room for the three lists too?
        top_h = h * 0.48 if bars else h - 8
        Charts.line(c, 8, 4, half - 20, top_h,
                    [("Download", down, t["chart_down"]),
                     ("Upload", up, t["chart_up"])], t,
                    "Internet traffic", fmt=human_rate, xlabels=xl,
                    empty="No Internet traffic measured yet")
        Charts.line(c, half + 8, 4, half - 20, top_h,
                    [("Packets/sec", pps, t["chart_a"])], t,
                    "Packets per second", fmt=lambda v: f"{v:.0f}",
                    xlabels=xl, empty="No packets yet")
        if not bars:
            self._click_items = {}
            return
        y2 = top_h + 16
        third = w / 3
        bh = h - y2 - 4
        protos = m.metrics.top_protocols(
            recent_minutes=None if res > 1 else 5, n=7)
        Charts.hbars(c, 8, y2, third - 16, bh,
                     [(p, b, _human_bytes(b), None) for p, b in protos], t,
                     "Protocols (by volume)", color=t["chart_e"])
        devs = sorted(m.registry.by_key.values(),
                      key=lambda d: -(d.bytes_up + d.bytes_down))[:7]
        self._click_items = {}
        items = []
        for d in devs:
            if d.bytes_up + d.bytes_down <= 0:
                continue
            # the tag is the row number in the chart (5.0.1 used the
            # number among all devices, so a click could open the wrong one)
            self._click_items[f"dev{len(items)}"] = ("device", d.key)
            items.append((self.app.device_label(d), d.bytes_up + d.bytes_down,
                          f"↑{_human_bytes(d.bytes_up)} "
                          f"↓{_human_bytes(d.bytes_down)}", d.key))
        Charts.hbars(c, third + 8, y2, third - 16, bh, items, t,
                     "Top devices (click to open)", color=t["chart_b"],
                     tags_prefix="dev")
        groups = Counter()
        for wrec in m.websites.values():
            groups[wrec.registrable] += wrec.requests
        sites = groups.most_common(7)
        for i, (dom, _n) in enumerate(sites):
            self._click_items[f"site{i}"] = ("website", dom)
        Charts.hbars(c, 2 * third + 8, y2, third - 16, bh,
                     [(dom, n, f"{n} hits", dom) for dom, n in sites], t,
                     "Top websites (click to open)", color=t["chart_d"],
                     tags_prefix="site")


# ---- Happening (friendly feed) -------------------------------------------------
class FeedTab(BaseTab):
    name, label_key = "feed", "tab_feed"

    def build(self):
        self.speed = DEFAULT_FEED_SPEED
        self.paused = False
        self.buffer = []
        ctrl = tk.Frame(self.frame, bg=WHITE, padx=10)
        ctrl.pack(fill="x", pady=(8, 4))
        tk.Label(ctrl, text="Feed speed:", bg=WHITE, fg="#333333").pack(
            side="left")
        self.speed_var = tk.StringVar(value=self.speed)
        sb = ttk.Combobox(ctrl, textvariable=self.speed_var,
                          values=list(FEED_SPEEDS.keys()), width=12,
                          state="readonly")
        sb.pack(side="left", padx=(6, 14))
        sb.bind("<<ComboboxSelected>>",
                lambda e: setattr(self, "speed", self.speed_var.get()))
        self.pause_btn = ttk.Button(ctrl, text="⏸  Pause feed",
                                    command=self.toggle_pause)
        self.pause_btn.pack(side="left")
        ttk.Button(ctrl, text="Jump to now", command=self.jump_to_now).pack(
            side="left", padx=(6, 0))
        tk.Label(ctrl, text="   Show only:", bg=WHITE, fg="#333333").pack(
            side="left")
        self.q_var = tk.StringVar()
        qe = ttk.Entry(ctrl, textvariable=self.q_var, width=14)
        self.filter_entry = qe
        qe.pack(side="left", padx=(4, 0))
        self._filter_soon = debounce(self.frame, self.refilter, 150)
        qe.bind("<KeyRelease>", lambda e: self._filter_soon())
        self.rows = deque(maxlen=500)
        self.hover = False
        tk.Label(ctrl, text="   “Calm” groups busy moments so they're "
                            "easy to read — “Full speed” shows "
                            "every line as it happens.",
                 bg=WHITE, fg="#888888", font=mw_font(9)).pack(
            side="left", padx=(12, 0))
        self.hint_var = DisplayVar(value="")
        self.hint = tk.Label(self.frame, textvariable=self.hint_var,
                             bg=WHITE, fg="#888888", anchor="w",
                             justify="left", wraplength=900, padx=12)
        # one line that is always there (a line appearing under the
        # pointer would move the list it is pointing at)
        self.hint.pack(fill="x", pady=(0, 4))
        self.hover_var = self.hint_var
        wrap, self.tree = make_tree(
            self.frame, [("who", "Who", 260, "w", False),
                         ("did", "What they did", 760, "w", True),
                         ("when", "When", 110, "center", False)],
            sortable=False)
        wrap.pack(fill="both", expand=True)
        self._wrap = wrap
        # the list holds still while the pointer is over it
        self.tree.bind("<Enter>", lambda e: self._set_hover(True), add="+")
        self.tree.bind("<Leave>", lambda e: self._set_hover(False), add="+")
        self.kit = TableKit(self, self.tree, wrap, "feed",
                            key_of=lambda iid: iid, menu=self.menu_spec,
                            sortable=False)
        self.restyle()
        self.refresh()

    def _set_hover(self, on):
        self.hover = on
        self.update_pause_label()

    def menu_spec(self, iid):
        try:
            who = str(self.tree.set(iid, "who"))
        except tk.TclError:
            return {}
        return {"filter": lambda: (self.q_var.set(who), self.refilter())}

    def _match(self, row):
        q = self.q_var.get().strip().lower()
        return not q or q in f"{row[1]} {row[2]}".lower()

    def refilter(self):
        with contextlib.suppress(tk.TclError):
            self.tree.delete(*self.tree.get_children())
            for tag, who, did, when in reversed(
                    [r for r in self.rows if self._match(r)]):
                self.tree.insert("", "end", tags=(tag,),
                                 values=(who, translate_event(did), when))
        self.refresh()

    def jump_to_now(self):
        self.paused = False
        self.hover = False
        self.update_pause_label()
        self.flush()
        with contextlib.suppress(tk.TclError):
            self.tree.yview_moveto(0)

    def refresh(self):
        """An empty feed says why (it looked broken after opening a file
        or a saved session, which have no live feed)."""
        if getattr(self, "hover", False) and not self.paused:
            return                    # the "paused under the pointer" line
        try:
            empty = not self.tree.get_children()
            mode = self.app.data_mode
            if not empty:
                text = ""
            elif mode in ("offline", "session"):
                text = ("This feed shows what happens while MiniWireshark "
                        "is watching live. For this capture, see the "
                        "Timeline, Devices and Connections tabs.")
            else:
                text = ("Nothing yet — this feed fills in as soon as "
                        "MiniWireshark is watching and devices do something.")
            self.hint_var.set(text)
        except (tk.TclError, AttributeError):
            pass

    def restyle(self):
        table = PALETTES[palette_name(self.app.theme_name,
                                      self.app.high_contrast)]
        for tag, hexcolor in {"dns": "#6a2ca0", "secure": "#0b5394",
                              "unsecure": "#0b6b3a", "device": "#8a5a00",
                              "other": "#333333", "alert": "#a01a08"}.items():
            with contextlib.suppress(tk.TclError):
                self.tree.tag_configure(tag, foreground=table.get(hexcolor,
                                                                  hexcolor))

    on_theme = restyle

    def push(self, events):
        self.buffer.extend(events)
        if len(self.buffer) > 1500:
            del self.buffer[:-1500]

    def toggle_pause(self):
        self.paused = not self.paused
        self.update_pause_label()

    def update_pause_label(self):
        if self.paused:
            n = len(self.buffer)
            label = f"▶  Resume ({n} waiting)" if n else "▶  Resume"
        else:
            label = "⏸  Pause feed"
        with contextlib.suppress(tk.TclError):
            self.pause_btn.config(text=label)
        hold = getattr(self, "hover", False) and not self.paused
        with contextlib.suppress(AttributeError):
            n = len(self.buffer)
            if hold:
                self.hint_var.set(
                    "Paused while the pointer is over the list — move it "
                    "away to resume" + (f" ({n} waiting)" if n else ""))
            else:
                self.refresh()

    def flush(self):
        """Called on the feed's own timer. Returns the next delay in ms."""
        cfg = FEED_SPEEDS.get(self.speed, FEED_SPEEDS[DEFAULT_FEED_SPEED])
        if self.paused or getattr(self, "hover", False):
            self.update_pause_label()
            return 300
        buf, self.buffer = self.buffer, []
        if buf:
            if cfg["digest"] or len(buf) > cfg["max_rows"] or \
                    self.app.perf_level >= 2:
                rows = self.digest(buf, cfg["max_rows"])
            else:
                rows = [(b["tag"], b["who"], b["did"], b["when"])
                        for b in buf]
            anchor = None
            if self.app.reduce_motion():
                # keep the line you are reading where it is
                with contextlib.suppress(tk.TclError):
                    if self.tree.yview()[0] > 0:
                        anchor = self.tree.identify_row(4)
            for row in rows:
                self.rows.append(row)
                if not self._match(row):
                    continue
                tag, who, did, when = row
                with contextlib.suppress(tk.TclError):
                    self.tree.insert("", 0, tags=(tag,),
                                     values=(who, translate_event(did),
                                             when))
            if anchor:
                with contextlib.suppress(tk.TclError):
                    n = len(self.tree.get_children())
                    self.tree.yview_moveto(self.tree.index(anchor) /
                                           max(1, n))
            kids = self.tree.get_children()
            if len(kids) > 500:
                self.tree.delete(*kids[500:])
        return cfg["interval"]

    @staticmethod
    def digest(buf, cap):
        """Collapse exact repeats and cap how many lines appear in one go,
        so a burst reads as a short summary instead of a wall of text."""
        counts, order = {}, []
        for b in buf:
            key = (b["who"], b["tag"], b["did"])
            if key not in counts:
                counts[key] = 0
                order.append(key)
            counts[key] += 1
        rows = []
        for key in order[:cap]:
            who, tag, did = key
            n = counts[key]
            rows.append((tag, who, did if n == 1 else f"{did}  (×{n})",
                         buf[-1]["when"]))
        leftover = order[cap:]
        if leftover:
            extra = sum(counts[k] for k in leftover)
            rows.append(("other", "…",
                         f"+{extra} more thing(s) just happened — switch "
                         f"to “Full speed” to see every line",
                         buf[-1]["when"]))
        return rows

    def reset(self):
        self.buffer.clear()
        self.rows.clear()
        with contextlib.suppress(tk.TclError):
            self.tree.delete(*self.tree.get_children())


# ---- Timeline v2 -------------------------------------------------------------
TIMELINE_CATEGORY = {
    "new device": "Devices", "device left": "Devices",
    "device back": "Devices", "device expired": "Devices",
    "ip changed": "Devices", "dhcp lease": "Devices",
    "hostname": "Devices", "identity": "Devices",
    "identity merged": "Devices", "possible duplicate": "Devices",
    "service": "Devices", "traffic spike": "Devices",
    "website": "Websites", "alert": "Alerts", "dns change": "DNS",
    "capture": "Network & capture", "interface": "Network & capture",
    "internet": "Network & capture", "vpn": "Network & capture",
    "network": "Network & capture", "wifi": "Network & capture",
}


class TimelineTab(BaseTab):
    name, label_key = "timeline", "tab_timeline"
    VIEW_VARS = ("search_var", "type_var", "sev_var", "dev_var")

    def build(self):
        self.header("\U0001F553  Timeline — devices joining and leaving, "
                    "address and name changes, first visits to websites, DNS "
                    "changes, capture events and alerts, in order. "
                    "Double-click a row to jump to it.")
        bar = self.toolbar()
        self.search_var = tk.StringVar()
        self.lbl(bar, "Search:").pack(side="left")
        e = ttk.Entry(bar, textvariable=self.search_var, width=18)
        self.filter_entry = e
        e.pack(side="left", padx=(4, 10))
        e.bind("<KeyRelease>", lambda ev: self._schedule_rebuild())
        self.type_var = tk.StringVar(value="All types")
        self._combo(bar, "Type:", self.type_var,
                    ["All types", "Devices", "Websites", "Alerts", "DNS",
                     "Network & capture"], 16)
        self.sev_var = tk.StringVar(value="All")
        self._combo(bar, "Severity:", self.sev_var,
                    ["All", "INFO", "WARNING", "DANGER"], 9)
        self.dev_var = tk.StringVar(value="All devices")
        self.dev_box = self._combo(bar, "Device:", self.dev_var,
                                   ["All devices"], 22)
        self.dev_box.bind("<Button-1>", lambda e: self.dev_box.configure(
            values=self.device_choices()), add="+")
        self.zoom_var = tk.StringVar(value="Full session")
        self.zoom_box = self._combo(bar, "Show:", self.zoom_var,
                                    self.LIVE_ZOOMS, 15)
        self.pause_var = tk.BooleanVar(value=False)
        self.pause_chk = ttk.Checkbutton(bar, text="Pause live updates",
                                         variable=self.pause_var,
                                         command=self._on_pause)
        self.pause_chk.pack(side="left", padx=(8, 0))
        bar2 = self.toolbar()
        # 5.3.4 (M7, MC4): the same events told as a story, day by day
        self.story_var = tk.BooleanVar(value=False)
        self._story_shown = None
        if FEATURES.get("story_mode", True):
            self.story_chk = ttk.Checkbutton(
                bar2, text="\U0001F4D6 Story mode", variable=self.story_var,
                command=self._on_story)
            self.story_chk.pack(side="left", padx=(0, 10))
            Tooltip(self.story_chk, "Story mode tells what changed in plain "
                                    "sentences, day by day, with repeats "
                                    "folded into one line. A line marks "
                                    "what is new since you last looked.")
        self.source_var = tk.StringVar(value="This session")
        self.source_box = self._combo(bar2, "Source:", self.source_var,
                                      ["This session", "Saved history"], 14)
        self.source_box.bind("<<ComboboxSelected>>",
                             lambda e: self._on_source(), add="+")
        self.episodes_var = tk.BooleanVar(value=False)
        ttk.Checkbutton(bar2, text="Group into episodes",
                        variable=self.episodes_var,
                        command=self.rebuild).pack(side="left",
                                                   padx=(0, 10))
        self.older_btn = ttk.Button(bar2, text="Load 200 older",
                                    command=self.load_older)
        self.older_btn.pack(side="left", padx=(0, 10))
        self.status_lbl = self.lbl(bar2, "", muted=True)
        self.status_lbl.pack(side="left")
        ttk.Button(bar2, text="Compare sessions…",
                   command=self.app.open_compare).pack(side="right")
        self.changes_btn = ttk.Menubutton(bar2, text="What changed since…")
        menu = tk.Menu(self.changes_btn, tearoff=False)
        for period in CHANGE_PERIODS:
            menu.add_command(label=period, command=lambda p=period:
                             self.app.open_changes(p))
        self.changes_btn["menu"] = menu
        self.changes_btn.pack(side="right", padx=6)
        self.oldest_ts = self.cursor = None
        self.exhausted = False
        # 5.1.2: events per minute; click or drag to see the session as of
        # that minute (Left/Right: a minute, Shift: ten, Escape: now)
        self.strip = tk.Canvas(self.frame, height=28, bg=WHITE,
                               highlightthickness=0, takefocus=1,
                               cursor="hand2")
        self.strip.pack(fill="x", padx=8, pady=(0, 2))
        self.strip.bind("<Button-1>", self._strip_click)
        self.strip.bind("<B1-Motion>", self._strip_click)
        self.strip.bind("<Configure>", lambda e: self.draw_strip(True))
        for seq, d in (("<Left>", -60), ("<Right>", 60),
                       ("<Shift-Left>", -600), ("<Shift-Right>", 600)):
            self.strip.bind(seq, lambda e, dd=d: self._strip_step(dd))
        self.strip.bind("<Escape>", lambda e: self.app.set_asof(None))
        Tooltip(self.strip, "Events per minute. Click or drag to see "
                            "Timeline, Devices and Websites as of that "
                            "minute; Left/Right move a minute, Shift ten, "
                            "Escape goes back to now.")
        self._strip_sig = None
        self.asof_bar = AsofBar(self)
        wrap, self.tree = make_tree(
            self.frame, [("sev", "Severity", 100, "w", False),
                         ("when", "Time", 80, "center", False),
                         ("kind", "Type", 130, "w", False),
                         ("text", "What happened", 700, "w", True)])
        wrap.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        self.tree.bind("<Double-1>", self._on_double)
        self.refs = {}
        # always in time order: no column sort here
        self.kit = TableKit(self, self.tree, wrap, "timeline",
                            key_of=lambda iid: iid if iid in self.refs
                            else None,
                            empty_state=self.empty_state,
                            menu=self.menu_spec, sortable=False)
        self.pending = []
        self._rebuild_job = None
        self.on_theme()

    def _combo(self, bar, label, var, values, width):
        self.lbl(bar, label).pack(side="left")
        cb = ttk.Combobox(bar, textvariable=var, values=values, width=width,
                          state="readonly")
        cb.pack(side="left", padx=(4, 10))
        cb.bind("<<ComboboxSelected>>", lambda e: self.rebuild())
        return cb

    STRIP_MAX_BARS = 1440

    def strip_span(self):
        """The session's time range on the strip (the Timeline's own
        events decide; live, it runs to now)."""
        m = self.model
        now = m.now()
        tl = m.timeline
        if tl:
            start, end = tl[0]["when"], tl[-1]["when"]
        elif m.metrics.first_ts:
            start, end = m.metrics.first_ts, m.metrics.last_ts or now
        else:
            start, end = now - 60, now
        if self.app.data_mode == "live":
            end = max(end, now)
        return start, max(end, start + 60)

    def strip_bins(self):
        start, end = self.strip_span()
        width = max(60.0, (end - start) / self.STRIP_MAX_BARS)
        width = 60.0 * math.ceil(width / 60.0)
        n = max(1, int(math.ceil((end - start) / width)))
        bins = [0] * n
        for e in self.model.timeline:
            i = int((e["when"] - start) // width)
            if 0 <= i < n:
                bins[i] += 1
        return start, width, bins

    def draw_strip(self, force=False):
        c, t = self.strip, self.t
        try:
            w, h = max(100, c.winfo_width()), int(c.cget("height"))
        except tk.TclError:
            return
        start, width, bins = self.strip_bins()
        asof = getattr(self.app, "asof", None)
        sig = (w, len(bins), sum(bins), asof, self.app.theme_name)
        if not force and sig == self._strip_sig:
            return
        self._strip_sig = sig
        with contextlib.suppress(tk.TclError):
            c.configure(bg=t["tab_bg"])
            c.delete("all")
            top = max(bins) or 1
            bw = w / len(bins)
            bar = max(1, min(bw - 1, 8))     # a short session: thin bars
            for i, v in enumerate(bins):
                if v:
                    bh = max(2, (h - 6) * v / top)
                    x0 = i * bw + (bw - bar) / 2
                    c.create_rectangle(x0, h - 2 - bh, x0 + bar, h - 2,
                                       fill=t["chart_a"], outline="")
            c.create_line(0, h - 1, w, h - 1, fill=t["grid"])
            if asof is not None:
                x = (asof - start) / (width * len(bins)) * w
                c.create_line(x, 0, x, h, fill=t["warn_fg"], width=2)
                c.create_text(min(w - 30, x + 4), 2, anchor="nw",
                              text=hm_clock(asof), fill=t["warn_fg"],
                              font=("TkDefaultFont", 8, "bold"))

    def _strip_click(self, e):
        with contextlib.suppress(tk.TclError):
            self.strip.focus_set()
        start, width, bins = self.strip_bins()
        w = max(1, self.strip.winfo_width())
        t = start + max(0, min(1, e.x / w)) * width * len(bins)
        self.app.set_asof(t)

    def _strip_step(self, d):
        cur = getattr(self.app, "asof", None)
        cur = cur if cur is not None else self.model.now()
        self.app.set_asof(cur + d)
        return "break"

    def mark_asof(self, t):
        """Scroll to the last event at or before t and select it."""
        best = None
        for iid in self.tree.get_children():
            e = self.refs.get(iid)
            if e and e["when"] <= t:
                best = iid
                break
        if best is not None:
            with contextlib.suppress(tk.TclError):
                self.tree.see(best)
                self.tree.selection_set(best)
        return best

    LIVE_ZOOMS = ["Last 5 minutes", "Last hour", "Full session"]
    HISTORY_ZOOMS = ["Last hour", "Last 24 hours", "Last 7 days",
                     "Last 30 days", "Everything saved"]
    ZOOM_SECONDS = {"Last 5 minutes": 300, "Last hour": 3600,
                    "Last 24 hours": 86400, "Last 7 days": 7 * 86400,
                    "Last 30 days": 30 * 86400}

    def history_mode(self):
        return self.source_var.get() == "Saved history" and \
            self.app.history is not None

    def _on_source(self):
        if self.source_var.get() == "Saved history" and \
                self.app.history is None:
            self.source_var.set("This session")
            self.app._set_banner("Saved history is off. Turn it on in "
                                 "Settings → History to keep events from "
                                 "earlier sessions.", kind="info")
        hist = self.history_mode()
        zooms = self.HISTORY_ZOOMS if hist else self.LIVE_ZOOMS
        self.zoom_box.configure(values=zooms)
        if self.zoom_var.get() not in zooms:
            self.zoom_var.set("Last 24 hours" if hist else "Full session")
        self.rebuild()

    def _sql_filters(self):
        zoom = self.zoom_var.get()
        secs = self.ZOOM_SECONDS.get(zoom)
        since = time.time() - secs if secs else 0.0
        return {"category": self.type_var.get(),
                "severity": self.sev_var.get(),
                "device": self.device_key_from_choice(self.dev_var.get()),
                "q": self.search_var.get().strip(), "since": since}

    def load_older(self):
        if not self.history_mode() or self.exhausted:
            return 0
        rows = store_events_page(self.app.history, before=self.cursor,
                                 limit=200, **self._sql_filters())
        for e in rows:
            self._insert(e)
        if rows:
            self.oldest_ts = rows[-1]["when"]
            self.cursor = (rows[-1]["when"], rows[-1]["rowid"])
        self.exhausted = len(rows) < 200
        self._update_status()
        return len(rows)

    def _update_status(self):
        hist = self.history_mode()
        n = len(self.tree.get_children())
        if self.story_on():
            st = self.app.story
            with contextlib.suppress(tk.TclError):
                self.older_btn.configure(state="disabled")
                self.pause_chk.configure(state="disabled")
                if st is None or st.get("model_id") != id(self.model):
                    self.status_lbl.configure(text=translate_text(
                        "Writing the story…"))
                else:
                    c = st["count"]
                    txt = translate_text("1 change") if c == 1 else \
                        translate_text("%d changes") % c
                    if st.get("last_looked") and st["fresh"]:
                        txt += " · " + translate_text(
                            f"{st['fresh']} new since you last looked")
                    self.status_lbl.configure(text=txt)
            return
        with contextlib.suppress(tk.TclError):
            self.older_btn.configure(state="normal" if hist and not
                                     self.exhausted else "disabled")
            self.pause_chk.configure(state="disabled" if hist else "normal")
            if hist:
                self.status_lbl.configure(
                    text=f"{n} saved events" + (
                        f", back to {fmt_clock(self.oldest_ts, True)}"
                        if self.oldest_ts else "") +
                    ("" if not self.exhausted else " (all loaded)"))
            else:
                self.status_lbl.configure(text=f"{n} events this session")

    def on_theme(self):
        for sev, (fg, bg) in self.app._severity_colors().items():
            with contextlib.suppress(tk.TclError):
                self.tree.tag_configure(sev, foreground=fg,
                                        background=bg or "")
        with contextlib.suppress(tk.TclError):
            self.tree.tag_configure("episode", font=("TkDefaultFont", 10,
                                                     "bold"),
                                    background=self.t["card_bg"])
            self.tree.tag_configure("story_mark", foreground=self.t[
                "warn_fg"], font=("TkDefaultFont", 9, "bold"))

    def _schedule_rebuild(self):
        if self._rebuild_job:
            with contextlib.suppress(tk.TclError):
                self.frame.after_cancel(self._rebuild_job)
        self._rebuild_job = self.frame.after(300, self.rebuild)

    def _on_pause(self):
        if not self.pause_var.get():
            self.rebuild()

    def _matches(self, e, cutoff, dev_key, q):
        return timeline_match(e, cutoff, self.sev_var.get(),
                              self.type_var.get(), dev_key, q)

    def _filters(self):
        zoom = self.zoom_var.get()
        now = self.model.now()
        cutoff = {"Last 5 minutes": now - 300,
                  "Last hour": now - 3600}.get(zoom, 0)
        return cutoff, self.device_key_from_choice(self.dev_var.get()), \
            self.search_var.get().strip().lower()

    # ---- Story mode (5.3.4 M7) -----------------------------------------------
    def story_on(self):
        try:
            return bool(self.story_var.get()) and \
                FEATURES.get("story_mode", True)
        except (tk.TclError, AttributeError):
            return False

    def set_story(self, on=True):
        if bool(self.story_var.get()) != bool(on):
            self.story_var.set(bool(on))
            self._on_story()
        return self.story_on()

    def _on_story(self):
        if not self.story_on():
            # leaving the story: what it showed has been read
            self.app.story_seen()
            self._story_shown = None
        self.rebuild()

    def refresh(self):
        """Shown again: a story older than a minute is written again."""
        if self.story_on():
            if self.app.request_story() is None and \
                    self.app.story is not None and \
                    self._story_shown is not self.app.story:
                self.show_story(self.app.story)

    def _story_matches(self, it):
        sev, cat = self.sev_var.get(), self.type_var.get()
        if sev and sev != "All" and sev != it["severity"]:
            return False
        if cat and cat != "All types" and it["category"] != cat:
            return False
        dev = self.device_key_from_choice(self.dev_var.get())
        if dev and it.get("device") != dev:
            return False
        q = self.search_var.get().strip().lower()
        return not q or q in it["text"].lower() or \
            q in story_sentence(it).lower()

    def show_story(self, story):
        """Draw a story: a heading row per day, the sentences newest first,
        and the line at "Since you last looked". Tk time only: the story
        was written by the jobs thread."""
        self._story_shown = story
        self.tree.delete(*self.tree.get_children())
        self.refs.clear()
        self.kit.clear()
        tr = translate_text
        shown = 0
        marked = not story.get("last_looked") or not story["fresh"]
        for day, items in story["days"]:
            items = [it for it in items if self._story_matches(it)]
            if not items:
                continue
            n = len(items)
            with contextlib.suppress(tk.TclError):
                iid = self.tree.insert(
                    "", "end", tags=("episode",),
                    values=("", "", tr("1 change") if n == 1 else
                            tr("%d changes") % n, story_day_label(day)))
                self.refs[iid] = None
            for it in items:
                if not marked and not it["fresh"]:
                    marked = True
                    self._insert_story_mark()
                self._insert_story(it)
                shown += 1
        if not marked and shown:
            self._insert_story_mark()
        self._update_status()
        self.kit.empty_soon()
        return shown

    def _insert_story_mark(self):
        with contextlib.suppress(tk.TclError):
            iid = self.tree.insert(
                "", "end", tags=("story_mark",),
                values=("", "", "", "▼  " + translate_text(
                    "Since you last looked")))
            self.refs[iid] = None

    def _insert_story(self, it):
        icon = self.app.SEVERITY_ICON.get(it["severity"], "•")
        when = hm_clock(it["when"]) if it["count"] == 1 or \
            hm_clock(it["first"]) == hm_clock(it["when"]) else \
            f"{hm_clock(it['first'])}–{hm_clock(it['when'])}"
        mark = ROW_DOT if it["fresh"] else ""
        with contextlib.suppress(tk.TclError):
            iid = self.tree.insert(
                "", "end", tags=(it["severity"],),
                values=(f"{icon} {it['severity']}", when,
                        f"×{it['count']}" if it["count"] > 1 else "",
                        mark + story_sentence(it)))
            self.refs[iid] = it

    def add(self, entries):
        with contextlib.suppress(Exception):
            if self.is_visible():
                self.draw_strip()
        if self.story_on():
            # the story is written again (at most once a minute), not
            # appended to
            if self.is_visible():
                self.app.request_story()
            return
        if self.pause_var.get() or self.history_mode():
            return
        cutoff, dev_key, q = self._filters()
        for e in entries:
            if self._matches(e, cutoff, dev_key, q):
                self._insert(e, index=0)
        kids = self.tree.get_children()
        if len(kids) > 1500:
            for old in kids[1500:]:
                self.refs.pop(old, None)
            self.tree.delete(*kids[1500:])
        self.kit.empty_soon()

    def _insert(self, e, index="end"):
        icon = self.app.SEVERITY_ICON.get(e["severity"], "•")
        try:
            old = e.get("live", True) is False and \
                time.time() - e["when"] > 86400
            iid = self.tree.insert(
                "", index, tags=(e["severity"],),
                values=(f"{icon} {e['severity']}",
                        fmt_clock(e["when"], with_date=old),
                        e["kind"], translate_event(e["text"])))
            self.refs[iid] = e
        except tk.TclError:
            pass

    def rebuild(self):
        for _ in self.rebuild_steps():
            pass

    def rebuild_steps(self):
        my = self._fill_gen = getattr(self, "_fill_gen", 0) + 1
        self._rebuild_job = None
        self.tree.delete(*self.tree.get_children())
        self.refs.clear()
        self.kit.clear()
        self.oldest_ts, self.cursor, self.exhausted = None, None, False
        if self.story_on():
            st = self.app.story
            job = self.app.request_story(
                force=st is None or st.get("model_id") != id(self.model))
            if st is not None and st.get("model_id") == id(self.model):
                self.show_story(st)
            elif job is not None or "story" in self.app.jobs.active:
                self._update_status()
            return
        if self.history_mode():
            self.load_older()
            return
        cutoff, dev_key, q = self._filters()
        rows = [e for e in self.model.timeline
                if self._matches(e, cutoff, dev_key, q)]
        if self.episodes_var.get():
            self._insert_episodes(rows[-1500:])
        else:
            for i, e in enumerate(reversed(rows[-1500:])):
                if i and i % 300 == 0:
                    yield
                    if self._fill_gen != my:
                        return
                self._insert(e)
        self._update_status()
        self.kit.empty_soon()

    def _insert_episodes(self, rows):
        eps = build_episodes(rows)
        inside = {id(e) for ep in eps for e in ep["events"]}
        items = [(ep["end"], "ep", ep) for ep in eps] + \
            [(e["when"], "ev", e) for e in rows if id(e) not in inside]
        items.sort(key=lambda it: -it[0])
        for _when, kind, obj in items:
            if kind == "ev":
                self._insert(obj)
                continue
            ep = obj
            head = f"{LEVEL_GLYPH[ep['level']]} {ep['headline']}" + (
                f" — likely {ep['cause']}" if ep["cause"] else "")
            try:
                iid = self.tree.insert(
                    "", "end", tags=("episode",),
                    values=("▸ Episode", fmt_clock(ep["start"]) + "–" +
                            fmt_clock(ep["end"]), f"{len(ep['events'])} "
                            f"events", head))
                self.refs[iid] = None
            except tk.TclError:
                continue
            for e in reversed(ep["events"]):
                self._insert(dict(e, text="    ↳ " + e["text"]))

    def empty_state(self):
        q = self.search_var.get().strip()
        if q:
            return TableKit.filtered(q, lambda: (self.search_var.set(""),
                                                 self.rebuild()))
        if self.story_on():
            if self.app.story is None:
                return ("Writing the story…", None, None)
            return ("Nothing changed in this period.", None, None)
        if self.app.history is None:
            return ("Only this session is shown. Turn on History to keep "
                    "earlier days.", "History settings",
                    lambda: self.app._open_settings("History"))
        return ("Nothing in this view yet.", None, None)

    def menu_spec(self, iid):
        e = self.refs.get(iid)
        if not e:
            return {}
        app = self.app
        ref = e.get("ref") or ()
        dev_key = e.get("device") or (ref[1] if ref and ref[0] == "device"
                                      else None)
        goto = []
        if dev_key and dev_key in self.model.registry.by_key:
            goto.append((f"{translate_text('Device')} — "
                         f"{app.short_device_name(dev_key)}",
                         lambda: app.goto("device", dev_key)))
        if ref and ref[0] == "website":
            goto.append((f"{translate_text('Website')} — {ref[1]}",
                         lambda: app.goto("websites", ref[1])))
        dev = self.model.registry.by_key.get(dev_key) if dev_key else None

        def filt():
            if dev is not None:
                self.dev_var.set(f"{dev.display_name()}  "
                                 f"[{dev.ip or dev.mac}]")
            else:
                self.search_var.set(e.get("kind") or "")
            self.rebuild()
        spec = {"open": lambda: self._open_event(e), "filter": filt,
                "goto": goto}
        if dev is not None:
            spec["packets"] = lambda: app.goto(
                "packets", f'device:"{dev.ip or dev.mac}"')
        return spec

    def _on_double(self, _e=None):
        sel = self.tree.selection()
        if not sel:
            return
        e = self.refs.get(sel[0])
        if e:
            self._open_event(e)

    def _open_event(self, e):
        if e.get("say"):                     # a line of the story
            ref = e.get("ref")
            if ref and (ref[0] != "device" or
                        ref[1] in self.model.registry.by_key):
                self.app.open_ref(ref)
                return
            DetailDialog(self.app, "Story", [
                ("What happened", story_sentence(e)),
                ("When", fmt_clock(e["first"], True) + (
                    " → " + fmt_clock(e["when"], True)
                    if e["count"] > 1 else "")),
                ("How many times", str(e["count"]))], size="520x360")
            return
        ref = e.get("ref")
        st = self.app.history
        this_session = e.get("live", True) is not False or (
            st is not None and e.get("session") == st.session)
        if ref and (this_session or ref[0] in ("device", "website")):
            if ref[0] != "device" or ref[1] in self.model.registry.by_key:
                self.app.open_ref(ref)
                return
        sess = e.get("session")
        DetailDialog(self.app, e["kind"].capitalize() if e["kind"] else
                     "Event", [("What happened", e["text"]),
                               ("When", fmt_clock(e["when"], True)),
                               ("Recorded in", f"session #{sess}" if sess
                                else "this session")], size="520x360")

    def reset(self):
        self.tree.delete(*self.tree.get_children())
        self.refs.clear()
        self.kit.clear()
        self.oldest_ts, self.cursor, self.exhausted = None, None, False



# ---- Devices -----------------------------------------------------------------
class DevicesTab(BaseTab):
    name, label_key = "devices", "tab_devices"
    VIEW_VARS = ("filter_var",)
    COLS = [("icon", "", 40, "center", False),
            ("name", "Device", 200, "w", True),
            ("cls", "What it likely is", 170, "w", False),
            ("ip", "Local IP", 115, "w", False),
            ("mac", "MAC address", 135, "w", False),
            ("vendor", "Made by", 140, "w", True),
            ("conf", "Confidence", 110, "w", False),
            ("evidence", "Evidence", 80, "center", False),
            ("status", "Status", 95, "w", False),
            ("traffic", "Traffic ↑/↓", 150, "w", False),
            ("last", "Last seen", 80, "center", False),
            ("ipv6", "IPv6", 200, "w", False),
            ("packets", "Packets", 70, "e", False),
            ("tags", "Place / owner", 130, "w", True)]

    def build(self):
        self.header("🏠  The devices on your local network. Confidence shows "
                    "how much local evidence supports each one — an IP "
                    "address alone is never enough to count as a device.",
                    "Double-click a device for details, or right-click for "
                    "actions (rename, mark as yours, merge…).")
        bar = self.toolbar()
        self.show_inactive_var = tk.BooleanVar(
            value=self.app.config.get("devices.show_inactive", False))
        self.show_expired_var = tk.BooleanVar(
            value=self.app.config.get("devices.show_expired", False))
        ttk.Checkbutton(bar, text="Show offline", command=self._vis_changed,
                        variable=self.show_inactive_var).pack(side="left")
        ttk.Checkbutton(bar, text="Show expired", command=self._vis_changed,
                        variable=self.show_expired_var).pack(side="left",
                                                             padx=(10, 0))
        self.lbl(bar, "   Filter:").pack(side="left")
        self.filter_var = tk.StringVar()
        fe = ttk.Entry(bar, textvariable=self.filter_var, width=18)
        self.filter_entry = fe
        fe.pack(side="left", padx=4)
        # 5.1.2: the table follows 150 ms after the last key, not on each
        self._filter_soon = debounce(self.frame, self.rebuild, 150)
        fe.bind("<KeyRelease>", lambda e: self._filter_soon())
        ttk.Button(bar, text="Merge devices…",
                   command=self.merge_dialog).pack(side="right")
        ttk.Button(bar, text="Details", command=self._details).pack(
            side="right", padx=6)
        self.count_lbl = self.lbl(bar, "", muted=True)
        self.count_lbl.pack(side="right", padx=10)
        wrap, self.tree = make_tree(self.frame, self.COLS,
                                    selectmode="extended")
        wrap.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        self.tree.bind("<Double-1>", lambda e: self._details())
        self.tree.bind("<Return>", lambda e: self._details())
        self.iids = IidMap()
        dev = self._dev
        self.kit = TableKit(
            self, self.tree, wrap, "devices",
            key_of=lambda iid: key_for_iid(self.iids, iid),
            empty_state=self.empty_state, default_cols=self.default_cols,
            sort_values={
                "traffic": lambda k: dev(k, lambda d: d.bytes_up +
                                         d.bytes_down),
                "packets": lambda k: dev(k, lambda d: d.packets)},
            relative={"last": lambda k: dev(k, lambda d: d.last_seen)},
            dot_col="name", menu=self.menu_spec,
            all_keys=lambda: list(self.model.registry.by_key),
            explain=self.explain_row)
        self.apply_mode()

    def explain_row(self, key):
        d = self.model.registry.by_key.get(key)
        if d is None:
            return ""
        tr_ = translate_text
        return (f"{tr_(d.confidence)} {tr_('confidence')}: "
                f"{tr_(explain('confidence', d.confidence))}   ·   "
                f"{tr_(explain('state', d.state, long=False))}: "
                f"{tr_(explain('state', d.state))}")

    def _dev(self, key, fn):
        d = self.model.registry.by_key.get(key)
        return fn(d) if d is not None else None

    def default_cols(self):
        """Beginner's shorter column set is the default, not a lock: the
        heading's right-click menu shows any column."""
        cols = [c[0] for c in self.COLS if c[0] != "tags"]
        if self.app.beginner_mode:
            cols = [c for c in cols if c not in ("ipv6", "packets")]
        if any(d.place or d.owner
               for d in self.model.registry.by_key.values()):
            cols.insert(cols.index("name") + 1, "tags")
        return cols

    def show_tags(self):
        """The Place / owner column, next to the name, once you use it."""
        cols = list(self.kit.shown_cols())
        if "tags" in cols:
            return
        cols.insert(cols.index("name") + 1 if "name" in cols else 1, "tags")
        self.kit._cols_override = cols
        self.kit.apply_columns()
        self.kit.save_soon()

    def apply_mode(self):
        self.kit.apply_columns()

    def empty_state(self):
        q = self.filter_var.get().strip()
        if q:
            return TableKit.filtered(q, lambda: (self.filter_var.set(""),
                                                 self.rebuild()))
        app = self.app
        if self.model.registry.by_key:
            return ("No devices to show. Offline and expired devices are "
                    "hidden.", "Show offline", lambda: (
                        self.show_inactive_var.set(True),
                        self.show_expired_var.set(True),
                        self._vis_changed()))
        if app.data_mode in ("offline", "session"):
            return ("No devices in this file.", "Return to live capture",
                    app._return_to_live)
        if app.data_mode == "live":
            return ("No devices yet. They appear as soon as they send "
                    "something on your network.", None, None)
        return ("No devices yet. They appear as soon as they send "
                "something on your network.", "Start watching",
                lambda: app.start())

    def menu_spec(self, key):
        dev = self.model.registry.by_key.get(key)
        if dev is None:
            return {}
        app = self.app
        moved = ("Details", "Filter packets to this device", "Copy IP",
                 "Copy MAC")
        own = [it for it in app.device_menu_items(dev)
               if it is None or it[0] not in moved]
        while own and own[0] is None:
            own.pop(0)
        ident = dev.ip or dev.mac
        return {
            "open": lambda: app.show_device(key),
            "copy": [("Copy IP", lambda: copy_to_clipboard(app, dev.ip),
                      bool(dev.ip)),
                     ("Copy MAC", lambda: copy_to_clipboard(app, dev.mac),
                      bool(dev.mac))],
            "filter": lambda: (self.filter_var.set(ident), self.rebuild()),
            "packets": lambda: app.goto("packets", f'device:"{ident}"'),
            "goto": [("Its websites", lambda: app.show_websites_of(key))],
            "own": own}

    def _vis_changed(self):
        cfg = self.app.config
        cfg.set("devices.show_inactive", self.show_inactive_var.get())
        cfg.set("devices.show_expired", self.show_expired_var.get())
        cfg.save()
        self.rebuild()

    def _visible(self, dev):
        asof = getattr(self.app, "asof", None)
        if asof is not None:
            if not device_online_at(dev, asof):
                return False
        elif not dev.live:
            return True
        elif dev.state == STATE_EXPIRED and \
                not self.show_expired_var.get():
            return False
        elif dev.state == STATE_INACTIVE and \
                not self.show_inactive_var.get():
            return False
        q = self.filter_var.get().strip().lower()
        if q:
            hay = " ".join([dev.display_name(), dev.ip, dev.mac, dev.vendor,
                            dev.device_class, dev.alias, dev.notes]).lower()
            if q not in hay:
                return False
        return True

    def values(self, dev):
        app = self.app
        icon = DEVICE_ICONS.get(dev.type, "❓")
        label = app.device_label(dev)
        if dev.mine:
            label = "★ " + label
        cls = (f"{dev.class_confidence} {dev.device_class}".strip()
               if dev.device_class != "Unknown" else "Unknown")
        conf = f"{CONFIDENCE_ICON.get(dev.confidence, '')} {dev.confidence}"
        status = STATE_LABEL.get(dev.state, dev.state)
        if not dev.live:
            status += " (saved)"
        elif dev.packets_out == 0 and dev.state == STATE_ACTIVE:
            status = "◌ Heard about"
        vendor = dev.vendor or ("Private address" if dev.randomized_mac
                                else "—")
        traffic = (f"↑{_human_bytes(dev.bytes_up)}  "
                   f"↓{_human_bytes(dev.bytes_down)}")
        return (icon, label, cls, dev.ip or "—", dev.mac or "—",
                vendor, conf, device_weakest(self.model, dev), status,
                traffic, fmt_clock(dev.last_seen),
                ", ".join(sorted(dev.ipv6)[:2]) or "—", dev.packets,
                tag_text(dev.place, dev.owner))

    def update_keys(self, keys):
        reg = self.model.registry
        for key in keys:
            dev = reg.by_key.get(key)
            if dev is None or not self._visible(dev):
                tree_remove(self.tree, self.iids, key, kit=self.kit)
                continue
            tree_upsert(self.tree, self.iids, key, self.values(dev),
                        kit=self.kit)
        self._count()

    def rekey(self, old, new):
        iid = self.iids.pop(old, None)
        if iid is not None:
            if new in self.iids:
                with contextlib.suppress(tk.TclError):
                    self.tree.delete(iid)
                self.kit.removed(iid)
            else:
                self.iids[new] = iid

    def rebuild(self):
        for _ in self.rebuild_steps():
            pass

    def rebuild_steps(self):
        """The refill in slices; rebuild() runs them all at once. A newer
        refill ends an older one."""
        my = self._fill_gen = getattr(self, "_fill_gen", 0) + 1
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.kit.clear()
        keys = list(self.model.registry.by_key)
        for i in range(0, len(keys), 150):
            if i:
                yield
                if self._fill_gen != my:
                    return
            self.update_keys(keys[i:i + 150])
        if not keys:
            self._count()

    def _count(self):
        n = len(self.iids)
        total = len(self.model.registry.by_key)
        extra = len(self.app.arp_cache_only()) if \
            self.app.data_mode == "live" else 0
        self.count_lbl.configure(
            text=f"{n} shown" + (f" of {total}" if total != n else "")
            + (f" · {extra} more in this computer's ARP cache (Reported, "
               f"not seen on the wire yet)" if extra else ""))

    def selected_keys(self):
        return [k for k in (key_for_iid(self.iids, i)
                            for i in self.tree.selection()) if k]

    def inspect_target(self):
        keys = self.selected_keys()
        return ("device", keys[0]) if keys else None

    def select(self, key):
        iid = self.iids.get(key)
        if iid is None:
            dev = self.model.registry.by_key.get(key)
            if dev is not None and dev.state == STATE_INACTIVE:
                self.show_inactive_var.set(True)
                self._vis_changed()
            elif dev is not None and dev.state == STATE_EXPIRED:
                self.show_expired_var.set(True)
                self._vis_changed()
            iid = self.iids.get(key)
        if iid:
            with contextlib.suppress(tk.TclError):
                self.tree.selection_set(iid)
                self.tree.see(iid)
                self.tree.focus(iid)

    def _details(self):
        keys = self.selected_keys()
        if keys:
            self.app.show_device(keys[0])

    def _context(self, event):
        return self.kit._right_click(event)

    def merge_dialog(self):
        keys = self.selected_keys()
        if len(keys) == 2:
            self.app.merge_devices_ui(keys[0], keys[1])
            return
        if len(keys) == 1:
            self.app.merge_with_ui(keys[0])
            return
        messagebox.showinfo(
            "Merge devices", "Select one device (to choose what to merge it "
            "with) or two devices (Ctrl+click), then click Merge.",
            parent=self.app.root)

    def reset(self):
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.kit.clear()
        self._count()


# ---- Websites -----------------------------------------------------------------
class WebsitesTab(BaseTab):
    name, label_key = "websites", "tab_websites"
    VIEW_VARS = ("q_var", "dev_var", "src_var", "ev_var", "enc_var",
                 "cat_var", "sort_var")
    COLS = [("hits", "Lookups / visits", 110, "e", False),
            ("evidence", "How we know", 170, "w", False),
            ("traffic", "Traffic", 90, "e", False),
            ("who", "Contacted by", 200, "w", True),
            ("security", "Security", 120, "w", False),
            ("category", "Category", 120, "w", False),
            ("source", "Seen via", 130, "w", False),
            ("first", "First seen", 80, "center", False),
            ("last", "Last seen", 80, "center", False),
            ("where", "Where", 110, "w", False),
            ("ips", "Server IPs", 160, "w", False)]
    SORTS = ("Most contacted", "Most traffic", "Recently seen",
             "First seen")

    def build(self):
        self.header("🌍  Websites and online services your devices looked up "
                    "or connected to.",
                    "For secure (https) sites MiniWireshark sees only the "
                    "site NAME (e.g. example.com) — never the page or full "
                    "address like https://example.com/private/page. Lookups "
                    "hidden by encrypted DNS or a VPN can't be listed.")
        bar = self.toolbar()
        self.lbl(bar, "Search:").pack(side="left")
        self.q_var = tk.StringVar()
        e = ttk.Entry(bar, textvariable=self.q_var, width=16)
        self.filter_entry = e
        e.pack(side="left", padx=(4, 8))
        e.bind("<KeyRelease>", lambda ev: self.schedule())
        self.dev_var = tk.StringVar(value="All devices")
        self.dev_box = self._combo(bar, "Device:", self.dev_var,
                                   ["All devices"], 20)
        self.sort_box = None
        self.dev_box.bind("<Button-1>", lambda e: self.dev_box.configure(
            values=self.device_choices()), add="+")
        self.src_var = tk.StringVar(value="Any source")
        self._combo(bar, "Seen via:", self.src_var,
                    ["Any source", "DNS", "TLS SNI", "QUIC first packet",
                     "HTTP Host"], 15)
        self.ev_var = tk.StringVar(value="Any evidence")
        self._combo(bar, "Evidence:", self.ev_var,
                    ["Any evidence", "Connected", "Looked up only",
                     "Possibly"], 13)
        self.enc_var = tk.StringVar(value="Any")
        self._combo(bar, "Security:", self.enc_var,
                    ["Any", "Encrypted", "Not encrypted"], 12)
        self.cat_var = tk.StringVar(value="Any category")
        self._combo(bar, "Category:", self.cat_var,
                    ["Any category", "Advertising", "Analytics", "Tracking",
                     "Social", "CDN", "Content", "Uncategorised"], 13)
        self.sort_var = tk.StringVar(value="Most contacted")
        self.sort_box = self._combo(bar, "Sort:", self.sort_var,
                                    list(self.SORTS), 13)
        # choosing a sort here replaces a sort set by a column heading
        self.sort_box.bind("<<ComboboxSelected>>",
                           lambda e: (self.kit.clear_sort(), self.rebuild()))
        wrap, self.tree = make_tree(self.frame, self.COLS,
                                    show="tree headings")
        self.tree.heading("#0", text="Website (grouped by main domain)")
        self.tree.column("#0", width=280, stretch=True)
        wrap.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        self.tree.bind("<Double-1>", self._details)
        self.iid_to_key = {}
        self.key_to_iid = {}
        self.group_iid = {}
        self.group_last = {}
        self.kit = TableKit(
            self, self.tree, wrap, "websites",
            key_of=lambda iid: self.iid_to_key.get(iid),
            empty_state=self.empty_state,
            sort_values={"traffic": lambda k: self._site_num(k, "bytes"),
                         "hits": lambda k: self._site_num(k, "requests"),
                         "first": lambda k: self._site_num(k, "first_seen")},
            relative={"last": self._site_last}, dot_col="#0",
            menu=self.menu_spec, all_keys=self._all_keys,
            explain=self.explain_row)
        self._job = None
        self._dirty = False
        self.count_lbl = self.lbl(bar, "", muted=True)
        self.count_lbl.pack(side="right")

    def explain_row(self, key):
        kind, dom = key
        w = self.model.websites.get(dom)
        if w is None:
            return ""
        lv = ASSOC_LEVEL.get(w.best_assoc, LV_UNKNOWN)
        return (f"{translate_text(ASSOC_TEXT.get(w.best_assoc, 'unknown'))}"
                f" — {translate_text(explain('level', lv))}  "
                f"{translate_text('A lookup alone does not prove a visit.')}"
                + (f"   ·   {translate_text('Category')}: "
                   f"{self.app.category_why(w)}" if w.category or
                   w.category_source else ""))

    def _combo(self, bar, label, var, values, width):
        self.lbl(bar, label).pack(side="left")
        cb = ttk.Combobox(bar, textvariable=var, values=values, width=width,
                          state="readonly")
        cb.pack(side="left", padx=(4, 8))
        cb.bind("<<ComboboxSelected>>", lambda e: self.rebuild())
        return cb

    def _site_num(self, key, attr):
        kind, name = key
        if kind == "site":
            w = self.model.websites.get(name)
            return getattr(w, attr) if w is not None else None
        members = self.group_members.get(name, ())
        vals = [getattr(w, attr) for w in members]
        if not vals:
            return None
        return min(vals) if attr == "first_seen" else sum(vals)

    def _site_last(self, key):
        kind, name = key
        if kind == "site":
            w = self.model.websites.get(name)
            return w.last_seen if w is not None else None
        return self.group_last.get(name)

    def _all_keys(self):
        out = [("site", d) for d in self.model.websites]
        out += [("group", w.registrable or w.domain)
                for w in self.model.websites.values()]
        return out

    def _filters_on(self):
        return (self.dev_var.get() != "All devices" or
                self.src_var.get() != "Any source" or
                self.ev_var.get() != "Any evidence" or
                self.enc_var.get() != "Any" or
                self.cat_var.get() != "Any category")

    def clear_filters(self):
        self.q_var.set("")
        self.dev_var.set("All devices")
        self.src_var.set("Any source")
        self.ev_var.set("Any evidence")
        self.enc_var.set("Any")
        self.cat_var.set("Any category")
        self.rebuild()

    def empty_state(self):
        q = self.q_var.get().strip()
        if q:
            return TableKit.filtered(q, self.clear_filters)
        if self._filters_on():
            return ("No websites match these filters.", "Clear the filters",
                    self.clear_filters)
        return ("No websites yet. Names appear when a device looks one up "
                "or connects.", None, None)

    def menu_spec(self, key):
        kind, dom = key
        app = self.app
        spec = {"copy": [("Copy domain", lambda: copy_to_clipboard(app, dom))],
                "filter": lambda: self.set_filter(dom),
                "packets": lambda: app.goto("packets", f"site:{dom}"),
                "own": [("Show contacting devices",
                         lambda: app.show_website_devices(dom)),
                        ("Show remote hosts",
                         lambda: app.goto("remote", dom)),
                        ("Set its category…",
                         lambda: app.set_website_category(dom))]}
        if kind == "site":
            spec["open"] = lambda: app.show_website(dom)
        else:
            iid = self.group_iid.get(dom)
            spec["open"] = lambda: self.tree.item(
                iid, open=not self.tree.item(iid, "open")) if iid else None
        return spec

    def schedule(self):
        if self._job:
            with contextlib.suppress(tk.TclError):
                self.frame.after_cancel(self._job)
        self._job = self.frame.after(350, self.rebuild)

    def set_filter(self, text):
        self.q_var.set(text or "")
        self.rebuild()

    def _match(self, w, dev_key):
        asof = getattr(self.app, "asof", None)
        if asof is not None and not website_known_at(w, asof):
            return False
        q = self.q_var.get().strip().lower()
        if q and q not in w.domain and q not in w.registrable:
            return False
        if dev_key and dev_key not in w.devices:
            return False
        src = self.src_var.get()
        if src != "Any source" and src not in w.sources:
            return False
        ev = self.ev_var.get()
        if ev != "Any evidence":
            a = self._assoc(w, dev_key)
            if ev == "Connected" and ASSOC_RANK.get(a, 0) < 4:
                return False
            if ev == "Looked up only" and a not in (AS_LOOKUP_ONLY,
                                                    AS_REPORTED):
                return False
            if ev == "Possibly" and a not in (AS_INFERRED, ""):
                return False
        enc = self.enc_var.get()
        if enc == "Encrypted" and not (w.encrypted and not w.cleartext):
            return False
        if enc == "Not encrypted" and not w.cleartext:
            return False
        cat = self.cat_var.get()
        if cat == "Uncategorised" and w.category:
            return False
        if cat not in ("Any category", "Uncategorised") and \
                w.category != cat:
            return False
        return True

    def _assoc(self, w, dev_key=None):
        if dev_key:
            return w.ties.get(dev_key, [""])[0]
        return w.best_assoc

    def _values(self, w):
        who = ", ".join(self.app.short_device_name(k)
                        for k in sorted(w.devices)[:3]) or "—"
        if len(w.devices) > 3:
            who += f" +{len(w.devices) - 3}"
        where = ", ".join(sorted(w.countries)[:3])
        dev_key = self.device_key_from_choice(self.dev_var.get())
        return (w.requests, assoc_label(self._assoc(w, dev_key)),
                _human_bytes(w.bytes) if w.bytes else "—",
                who, w.encryption_text(), w.category or "",
                ", ".join(sorted(w.sources)), fmt_clock(w.first_seen),
                fmt_clock(w.last_seen), where,
                ", ".join(sorted(w.resolved_ips)[:2]))

    def _sorted(self, recs):
        s = self.sort_var.get()
        if s == "Most traffic":
            return sorted(recs, key=lambda w: -w.bytes)
        if s == "Recently seen":
            return sorted(recs, key=lambda w: -w.last_seen)
        if s == "First seen":
            return sorted(recs, key=lambda w: w.first_seen)
        return sorted(recs, key=lambda w: -w.requests)

    def rebuild(self):
        for _ in self.rebuild_steps():
            pass

    def rebuild_steps(self):
        my = self._fill_gen = getattr(self, "_fill_gen", 0) + 1
        self._job = None
        self._dirty = False
        self.tree.delete(*self.tree.get_children())
        self.iid_to_key.clear()
        self.key_to_iid.clear()
        self.group_iid.clear()
        self.group_last.clear()
        self.group_members = {}
        self.kit.clear()
        dev_key = self.device_key_from_choice(self.dev_var.get())
        recs = [w for w in self.model.websites.values()
                if self._match(w, dev_key)]
        self.count_lbl.configure(text=f"{len(recs)} sites")
        grouped = self.app.config.get("websites.group_subdomains", True)
        if grouped:
            groups = defaultdict(list)
            for w in recs:
                groups[w.registrable or w.domain].append(w)
            order = sorted(groups.items(), key=lambda kv: self._group_key(
                kv[1]))
            done = 0
            for reg, members in order[:3000]:
                if done >= 150:
                    done = 0
                    yield
                    if self._fill_gen != my:
                        return
                done += len(members)
                if len(members) == 1 and members[0].domain == reg:
                    self._row("", members[0])
                    continue
                self.group_members[reg] = members
                self.group_last[reg] = max(w.last_seen for w in members)
                key = ("group", reg)
                agg = self.kit.decorate(key, self._agg(members))
                text = self.kit.decorate_text(key, f"{reg}  "
                                                   f"({len(members)})")
                idx, slot = self.kit.insert_index("", key, agg, text=text)
                giid = self.tree.insert("", idx, text=text, values=agg,
                                        open=False)
                self.group_iid[reg] = giid
                self.iid_to_key[giid] = key
                self.kit.inserted("", giid, slot, key)
                for w in self._sorted(members)[:300]:
                    self._row(giid, w)
        else:
            for i, w in enumerate(self._sorted(recs)[:5000]):
                if i and i % 150 == 0:
                    yield
                    if self._fill_gen != my:
                        return
                self._row("", w)

    def _group_key(self, members):
        s = self.sort_var.get()
        if s == "Most traffic":
            return -sum(w.bytes for w in members)
        if s == "Recently seen":
            return -max(w.last_seen for w in members)
        if s == "First seen":
            return min(w.first_seen for w in members)
        return -sum(w.requests for w in members)

    def _agg(self, members):
        devs = set()
        for w in members:
            devs |= w.devices
        enc = any(w.encrypted for w in members)
        clear = any(w.cleartext for w in members)
        sec = "Mixed" if enc and clear else ("⚠ Not encrypted" if clear
                                             else ("\U0001F512 Encrypted"
                                                   if enc else "Unknown"))
        cats = {w.category for w in members if w.category}
        who = ", ".join(self.app.short_device_name(k)
                        for k in sorted(devs)[:3]) or "—"
        b = sum(w.bytes for w in members)
        best = ""
        for w in members:
            best = better_assoc(w.best_assoc, best)
        return (sum(w.requests for w in members), assoc_label(best),
                _human_bytes(b) if b else "—", who, sec,
                ", ".join(sorted(cats)), "",
                fmt_clock(min(w.first_seen for w in members)),
                fmt_clock(max(w.last_seen for w in members)), "", "")

    def _row(self, parent, w):
        key = ("site", w.domain)
        vals = self.kit.decorate(key, self._values(w))
        text = self.kit.decorate_text(key, w.domain)
        idx, slot = self.kit.insert_index(parent, key, vals, text=text)
        iid = self.tree.insert(parent, idx, text=text, values=vals)
        self.iid_to_key[iid] = key
        self.key_to_iid[w.domain] = iid
        self.kit.inserted(parent, iid, slot, key)

    def update_keys(self, keys):
        """Incremental: update rows that exist; anything new triggers a
        throttled rebuild (new rows must land in the right group/order)."""
        for k in keys:
            w = self.model.websites.get(k)
            iid = self.key_to_iid.get(k)
            if w is None:
                continue
            if iid is None:
                self._dirty = True
                continue
            key = ("site", k)
            vals = self.kit.decorate(key, self._values(w))
            with contextlib.suppress(tk.TclError):
                self.tree.item(iid, values=vals)
                self.kit.updated(iid, key, vals)

    def refresh(self):
        if self._dirty and self.is_visible() and self._job is None:
            self._job = self.frame.after(10, self.rebuild)

    def selected(self):
        sel = self.tree.selection()
        return self.iid_to_key.get(sel[0]) if sel else None

    def inspect_target(self):
        k = self.selected()
        return ("website", k[1]) if k and k[0] == "site" else None

    def _details(self, _e=None):
        k = self.selected()
        if k and k[0] == "site":
            self.app.show_website(k[1])

    def _context(self, event):
        return self.kit._right_click(event)

    def select(self, dom):
        self.q_var.set("")
        if dom not in self.key_to_iid:
            self.rebuild()
        iid = self.key_to_iid.get(dom) or self.group_iid.get(dom)
        if iid:
            with contextlib.suppress(tk.TclError):
                parent = self.tree.parent(iid)
                if parent:
                    self.tree.item(parent, open=True)
                self.tree.selection_set(iid)
                self.tree.see(iid)
        else:
            self.set_filter(dom)

    def reset(self):
        self.tree.delete(*self.tree.get_children())
        self.iid_to_key.clear()
        self.key_to_iid.clear()
        self.group_iid.clear()
        self.kit.clear()


# ---- Connections (Advanced) ---------------------------------------------------
class ConnectionsTab(BaseTab):
    name, label_key, advanced = "connections", "tab_connections", True
    VIEW_VARS = ("q_var", "dev_var", "status_var")
    COLS = [("device", "Device", 160, "w", False),
            ("to", "Connected to", 220, "w", True),
            ("purpose", "Purpose", 190, "w", True),
            ("up", "Upload", 80, "e", False),
            ("down", "Download", 80, "e", False),
            ("dur", "Duration", 80, "e", False),
            ("status", "Status", 120, "w", False),
            ("local", "Local endpoint", 160, "w", False),
            ("remote", "Remote endpoint", 170, "w", False),
            ("transport", "Transport", 70, "w", False),
            ("port", "Port", 60, "e", False),
            ("packets", "Packets", 70, "e", False),
            ("tcp", "TCP state", 110, "w", False),
            ("security", "Security", 120, "w", False),
            ("domain", "Domain (how known)", 200, "w", False),
            ("asn", "Provider / country", 170, "w", False),
            ("program", "Program (this computer)", 190, "w", False),
            ("id", "ID", 60, "e", False)]
    BEGINNER = ("device", "to", "purpose", "up", "down", "dur", "status")

    def build(self):
        outer = self.frame
        views = self.make_subviews(["Connections", "Mail"],
                                   on_switch=self._on_subview)
        self.frame = views["Connections"]
        try:
            self._build_connections()
        finally:
            self.frame = outer
        self.mail = MailView(self.app, views["Mail"])

    def _on_subview(self, name):
        if name == "Mail":
            self.mail.refresh(force=True)

    def _build_connections(self):
        self.header("\U0001F517  Connections — each row is one "
                    "conversation between a device and something else. "
                    "Upload is what the device sent; download is what it "
                    "received.",
                    "Double-click for a plain-English report. “Domain "
                    "(how known)” says whether the name was seen in the "
                    "connection itself or inferred from an earlier lookup.")
        bar = self.toolbar()
        self.lbl(bar, "Search:").pack(side="left")
        self.q_var = tk.StringVar()
        e = ttk.Entry(bar, textvariable=self.q_var, width=16)
        self.filter_entry = e
        e.pack(side="left", padx=(4, 8))
        self._filter_soon = debounce(self.frame, self.rebuild, 150)
        e.bind("<KeyRelease>", lambda ev: self._filter_soon())
        self.dev_var = tk.StringVar(value="All devices")
        self.lbl(bar, "Device:").pack(side="left")
        self.dev_box = ttk.Combobox(bar, textvariable=self.dev_var, width=22,
                                    values=["All devices"], state="readonly")
        self.dev_box.pack(side="left", padx=(4, 8))
        self.dev_box.bind("<<ComboboxSelected>>", lambda e: self.rebuild())
        self.dev_box.bind("<Button-1>", lambda e: self.dev_box.configure(
            values=self.device_choices()), add="+")
        self.status_var = tk.StringVar(value="All")
        self.lbl(bar, "Status:").pack(side="left")
        sb = ttk.Combobox(bar, textvariable=self.status_var, width=10,
                          values=["All", "Open", "Finished", "Reset",
                                  "Not encrypted"], state="readonly")
        sb.pack(side="left", padx=(4, 8))
        sb.bind("<<ComboboxSelected>>", lambda e: self.rebuild())
        self.group_var = tk.StringVar(value=self.app.config.get(
            "connections.group_by", "None"))
        self.lbl(bar, "Group by:").pack(side="left")
        gb = ttk.Combobox(bar, textvariable=self.group_var, width=9,
                          values=list(self.GROUPS), state="readonly")
        gb.pack(side="left", padx=(4, 8))
        gb.bind("<<ComboboxSelected>>", lambda e: self._group_changed())
        self.tech_var = tk.BooleanVar(value=True)
        ttk.Checkbutton(bar, text="Technical columns", variable=self.tech_var,
                        command=self._tech_changed).pack(side="left")
        self.count_lbl = self.lbl(bar, "", muted=True)
        self.count_lbl.pack(side="right")
        wrap, self.tree = make_tree(self.frame, self.COLS, hscroll=True)
        self.tree.heading("#0", text="Group")
        self.tree.column("#0", width=230, stretch=False)
        wrap.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        self.tree.bind("<Double-1>", self._details)
        self.iids = IidMap()
        self.group_rows = {}         # parent iid -> (kind, group key)
        self._group_dirty = False
        self._group_built = 0.0
        flow = self._flow
        self.kit = TableKit(
            self, self.tree, wrap, "connections",
            key_of=self._key_of, empty_state=self.empty_state,
            default_cols=self.default_cols,
            sort_values={"up": lambda k: flow(k, "bytes_out"),
                         "down": lambda k: flow(k, "bytes_in"),
                         "dur": lambda k: flow(k, "duration"),
                         "packets": lambda k: flow(k, "packets"),
                         "id": lambda k: k if isinstance(k, int) else None},
            menu=self.menu_spec)
        self._apply_grouping()
        self.apply_mode()

    GROUPS = ("None", "Device", "Website")

    def _flow(self, key, attr):
        f = self.model.flows.get(key) if isinstance(key, int) else None
        return getattr(f, attr) if f is not None else None

    def _key_of(self, iid):
        g = self.group_rows.get(iid)
        if g is not None:
            return g
        return key_for_iid(self.iids, iid)

    def default_cols(self):
        if not self.tech_var.get():
            return list(self.BEGINNER)
        return [c[0] for c in self.COLS]

    def _tech_changed(self):
        # the checkbox picks a column set: it replaces columns chosen by
        # hand (widths stay)
        self.kit._cols_override = None
        self.kit.apply_columns()
        self.kit.save_soon()

    def apply_mode(self):
        self.kit.apply_columns()

    def grouping(self):
        g = self.group_var.get()
        return g if g in ("Device", "Website") else None

    def _apply_grouping(self):
        with contextlib.suppress(tk.TclError):
            self.tree.configure(show="tree headings" if self.grouping()
                                else "headings")

    def _group_changed(self):
        self.app.config.set("connections.group_by", self.group_var.get())
        self.app.config.save()
        self._apply_grouping()
        self.rebuild()

    def empty_state(self):
        q = self.q_var.get().strip()
        clear = lambda: (self.q_var.set(""), self.status_var.set("All"),  # noqa: E731
                         self.dev_var.set("All devices"), self.rebuild())
        if q:
            return TableKit.filtered(q, clear)
        if self.status_var.get() != "All" or \
                self.dev_var.get() != "All devices":
            return ("No connections match these filters.",
                    "Clear the filters", clear)
        if self.app.beginner_mode and self.app.config.get(
                "connections.hide_short_beginner", True):
            return ("No connections in this view. Short ones are hidden in "
                    "Beginner.", "Show short connections",
                    self._show_short)
        return ("No connections yet.", None, None)

    def _show_short(self):
        self.app.config.set("connections.hide_short_beginner", False)
        self.app.config.save()
        self.rebuild()

    def menu_spec(self, key):
        app = self.app
        if isinstance(key, tuple):              # a group row
            kind, gk = key
            iid = next((i for i, g in self.group_rows.items() if g == key),
                       None)
            label = self.tree.item(iid, "text") if iid else str(gk)
            spec = {"open": lambda: self.tree.item(
                        iid, open=not self.tree.item(iid, "open"))
                    if iid else None,
                    "copy": [("Copy name", lambda: copy_to_clipboard(
                        app, label))]}
            if kind == "device" and gk:
                spec["filter"] = lambda: self.set_filter(text="",
                                                         device_key=gk)
                spec["goto"] = [(f"{translate_text('Device')} — {label}",
                                 lambda: app.goto("device", gk))]
            elif kind == "website" and gk:
                spec["filter"] = lambda: self.set_filter(text=gk)
                spec["goto"] = [(f"{translate_text('Website')} — {gk}",
                                 lambda: app.goto("websites", gk))]
            return spec
        f = self.model.flows.get(key)
        if f is None:
            return {}
        goto = []
        if f.device_key:
            goto.append((f"{translate_text('Device')} — "
                         f"{app.short_device_name(f.device_key)}",
                         lambda: app.goto("device", f.device_key)))
        if f.domain:
            goto.append((f"{translate_text('Website')} — {f.domain}",
                         lambda: app.goto("websites", f.domain)))
        if f.remote_public:
            goto.append((f"{translate_text('Internet host')} — "
                         f"{f.remote_ip}",
                         lambda: app.goto("remote", f.remote_ip)))
        return {"open": lambda: app.show_flow(key),
                "copy": [("Copy remote address", lambda: copy_to_clipboard(
                    app, f"{f.remote_ip}:{f.remote_port}"))],
                "filter": lambda: self.set_filter(
                    text=f.domain or f.remote_ip),
                "packets": lambda: app.goto("packets", f"stream:{key}"),
                "goto": goto}

    def set_filter(self, text=None, device_key=None):
        if text is not None:
            self.q_var.set(text)
        if device_key:
            dev = self.model.registry.by_key.get(device_key)
            if dev:
                self.dev_var.set(f"{dev.display_name()}  [{dev.ip or dev.mac}]")
        self.rebuild()

    def _match(self, f, dev_key, q):
        if dev_key and f.device_key != dev_key:
            return False
        st = self.status_var.get()
        if st == "Open" and f.closed:
            return False
        if st == "Finished" and not f.closed:
            return False
        if st == "Reset" and not f.rst:
            return False
        if st == "Not encrypted" and f.encrypted != "no":
            return False
        if self.app.beginner_mode and self.app.config.get(
                "connections.hide_short_beginner", True) and \
                f.closed and f.duration < 1 and f.packets < 3:
            return False
        if q:
            hay = " ".join(str(x) for x in (
                f.local_ip, f.remote_ip, f.domain, f.app, f.service,
                f.remote_port, self.app.short_device_name(f.device_key),
                f.org)).lower()
            if q not in hay:
                return False
        return True

    def values(self, f):
        to = f.domain or f.remote_ip
        if f.domain and f.domain_conf and f.domain_conf != "Observed":
            to += "  (likely)"
        port = f.remote_port if f.transport in ("TCP", "UDP") else ""
        tcp = ""
        if f.transport == "TCP":
            bits = []
            if f.syn:
                bits.append("SYN")
            if f.synack:
                bits.append("SYN-ACK")
            if f.fin_out or f.fin_in:
                bits.append("FIN")
            if f.rst:
                bits.append(f"RST×{f.rst}")
            if f.retrans:
                bits.append(f"retx×{f.retrans}")
            if f.rtt is not None:
                bits.append(f"rtt {f.rtt * 1000:.0f}ms")
            if f.zero_win:
                bits.append(f"0win×{f.zero_win}")
            tcp = " ".join(bits)
        prov = " · ".join(x for x in (f"AS{f.asn} {f.org}".strip()
                                           if f.asn else f.org,
                                           f.country) if x)
        return (self.app.short_device_name(f.device_key) if f.device_key
                else f.local_ip, to, f.purpose(),
                _human_bytes(f.bytes_out), _human_bytes(f.bytes_in),
                human_duration(f.duration), f.status_text(),
                f"{f.local_ip}:{f.local_port}" if f.local_port else
                f.local_ip,
                f"{f.remote_ip}:{f.remote_port}" if f.remote_port else
                f.remote_ip,
                f.transport, port, f.packets, tcp, f.encryption_text(),
                f"{f.domain} ({f.domain_conf})" if f.domain else "—",
                prov, f.process or "", f.fid)

    def update_ids(self, fids):
        if not self.is_visible():
            self._pending = True
            return
        dev_key = self.device_key_from_choice(self.dev_var.get())
        q = self.q_var.get().strip().lower()
        if self.grouping():
            # grouped: rows already shown update in place; new ones come
            # with the next regrouping (at most every 3 s)
            for fid in fids:
                f = self.model.flows.get(fid)
                iid = self.iids.get(fid)
                if f is None or iid is None:
                    if f is not None and self._match(f, dev_key, q):
                        self._group_dirty = True
                    continue
                with contextlib.suppress(tk.TclError):
                    self.tree.item(iid, values=self.values(f))
            return
        for fid in fids:
            f = self.model.flows.get(fid)
            if f is None or not self._match(f, dev_key, q):
                tree_remove(self.tree, self.iids, fid, kit=self.kit)
                continue
            tree_upsert(self.tree, self.iids, fid, self.values(f),
                        index=0 if fid not in self.iids else "end",
                        kit=self.kit)
        if len(self.iids) > 3000:
            for fid in sorted(self.iids)[:len(self.iids) - 3000]:
                tree_remove(self.tree, self.iids, fid, kit=self.kit)
        self.count_lbl.configure(text=f"{len(self.iids)} shown")

    def refresh(self):
        if self.subview == "Mail" and self.is_visible():
            self.mail.refresh()
        if getattr(self, "_pending", False) and self.is_visible():
            self._pending = False
            self.rebuild_in_slices()
        elif self._group_dirty and self.is_visible() and \
                time.monotonic() - self._group_built > 3:
            self.rebuild_in_slices()

    def rebuild(self):
        for _ in self.rebuild_steps():
            pass

    def _group_of(self, f):
        if self.grouping() == "Device":
            return ("device", f.device_key or ""), (
                self.app.short_device_name(f.device_key) if f.device_key
                else f.local_ip)
        reg = registrable_domain(f.domain) if f.domain else ""
        return ("website", reg), (reg or translate_text("(no name seen)"))

    def _group_values(self, flows):
        up = sum(f.bytes_out for f in flows)
        down = sum(f.bytes_in for f in flows)
        n_open = sum(1 for f in flows if not f.closed)
        vals = [""] * len(self.COLS)
        idx = {c[0]: i for i, c in enumerate(self.COLS)}
        vals[idx["to"]] = translate_text(f"{len(flows)} connections")
        vals[idx["up"]] = _human_bytes(up)
        vals[idx["down"]] = _human_bytes(down)
        vals[idx["status"]] = translate_text(f"{n_open} open")
        vals[idx["packets"]] = sum(f.packets for f in flows)
        return vals

    def rebuild_steps(self):
        my = self._fill_gen = getattr(self, "_fill_gen", 0) + 1
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.group_rows.clear()
        self.kit.clear()
        self._group_dirty = False
        self._group_built = time.monotonic()
        dev_key = self.device_key_from_choice(self.dev_var.get())
        q = self.q_var.get().strip().lower()
        flows = [f for f in self.model.flows.all_flows()
                 if self._match(f, dev_key, q)]
        flows.sort(key=lambda f: -f.last_seen)
        if self.grouping():
            groups, names = OrderedDict(), {}
            for f in flows[:3000]:
                gk, name = self._group_of(f)
                groups.setdefault(gk, []).append(f)
                names[gk] = name
            done = 0
            for gk, members in groups.items():
                if done >= 200:
                    done = 0
                    yield
                    if self._fill_gen != my:
                        return
                giid = self.tree.insert(
                    "", "end", text=f"{names[gk]}  ({len(members)})",
                    values=self._group_values(members), open=False)
                self.group_rows[giid] = gk
                for f in members:
                    self.iids[f.fid] = self.tree.insert(
                        giid, "end", values=self.values(f))
                done += len(members) + 1
            if self.kit.sort_col:
                self.kit.resort()
            self.kit.empty_soon()
            self.count_lbl.configure(text=f"{len(self.iids)} shown")
            return
        for i, f in enumerate(flows[:3000]):
            if i and i % 200 == 0:
                self.count_lbl.configure(text=f"{len(self.iids)} shown")
                yield
                if self._fill_gen != my:
                    return
            # appended after rows that arrived while filling
            tree_upsert(self.tree, self.iids, f.fid, self.values(f),
                        kit=self.kit)
        self.kit.empty_soon()
        self.count_lbl.configure(text=f"{len(self.iids)} shown")

    def select(self, fid):
        if fid not in self.iids:
            self.status_var.set("All")
            self.q_var.set("")
            self.dev_var.set("All devices")
            self.rebuild()
        iid = self.iids.get(fid)
        if iid:
            with contextlib.suppress(tk.TclError):
                parent = self.tree.parent(iid)
                if parent:
                    self.tree.item(parent, open=True)
                self.tree.selection_set(iid)
                self.tree.see(iid)

    def selected(self):
        sel = self.tree.selection()
        return key_for_iid(self.iids, sel[0]) if sel else None

    def inspect_target(self):
        fid = self.selected()
        return ("flow", fid) if fid is not None else None

    def _details(self, _e=None):
        fid = self.selected()
        if fid is not None:
            self.app.show_flow(fid)

    def _context(self, event):
        return self.kit._right_click(event)

    def reset(self):
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.group_rows.clear()
        self.kit.clear()
        self.mail.reset()


class MailView:
    """Email Traffic: how mail connections behave — never what anyone
    wrote. Sessions come from the Full Power pass; their records contain
    no content, credentials or addresses (the parser drops them)."""

    COLS = [("client", "Device", 150, "w", False),
            ("server", "Mail server", 170, "w", True),
            ("proto", "Protocol", 70, "w", False),
            ("enc", "Encryption", 200, "w", False),
            ("logins", "Logins (ok / failed)", 130, "w", False),
            ("msgs", "Messages / recipients", 140, "w", False),
            ("bytes", "Bytes up / down", 130, "w", False),
            ("dur", "Duration", 70, "e", False),
            ("end", "Ended", 90, "w", False)]

    def __init__(self, app, frame):
        self.app = app
        self.frame = frame
        self._version = -1
        self.rows = {}
        top = tk.Frame(frame, bg=WHITE, padx=12, pady=8)
        top.pack(fill="x")
        tk.Label(top, text="\u2709  Email Traffic — which mail servers your "
                 "devices use, whether the connection was encrypted, and "
                 "where it failed. What anyone wrote is never shown.",
                 bg=WHITE, fg="#333333", wraplength=1000, justify="left",
                 font=mw_font(11)).pack(anchor="w")
        self.summary = tk.Label(top, text="", bg=WHITE, fg="#666666",
                                wraplength=1000, justify="left",
                                font=mw_font(9))
        self.summary.pack(anchor="w", pady=(2, 0))
        bar = tk.Frame(frame, bg=WHITE, padx=12)
        bar.pack(fill="x", pady=(0, 6))
        self.fp_btn = ttk.Button(bar, text="Turn on Full Power",
                                 command=self._full_power)
        ttk.Button(bar, text="Export report…",
                   command=lambda: self.export()).pack(side="right")
        wrap, self.tree = make_tree(frame, self.COLS, hscroll=True)
        wrap.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        self.tree.bind("<Double-1>", self._details)
        self.bar = bar

    def _full_power(self):
        self.app.config.set("performance.mode", "Full Power")
        self.app.config.save()
        self.refresh(force=True)

    def sessions(self):
        store = self.app.deep.store
        with store.lock:
            return [t for t in store.txns if t.get("kind") == "mail"]

    def summary_text(self, rows):
        if not rows:
            mode, _w = self.app.effective_perf_mode()
            if mode != "Full Power":
                return ("Mail sessions are followed in Full Power mode "
                        "(Settings → Performance). Nothing is collected "
                        "until you turn it on.")
            return "No mail traffic seen yet."
        by = Counter(r.get("proto") for r in rows)
        enc = sum(1 for r in rows if r.get("encryption", "").startswith(
            ("encrypted", "upgraded")))
        failed = sum(r.get("auth_failures", 0) for r in rows)
        early = sum(1 for r in rows if r.get("auth_before_tls"))
        parts = [", ".join(f"{v} {k}" for k, v in by.most_common()),
                 f"encrypted {enc} of {len(rows)}"]
        if failed:
            parts.append(f"{failed} failed login(s)")
        if early:
            parts.append(f"{early} login(s) sent before encryption")
        return " · ".join(translate_text(p) for p in parts)

    def values(self, r):
        name = self.app.short_device_name
        dev = self.app.model.device_for(r.get("client", ""), None)
        if r.get("proto") == "webmail":
            return (name(dev.key) if dev else r.get("client", ""),
                    r.get("service") or r.get("server", ""),
                    "webmail", r.get("encryption", ""), "—", "—", "—", "—",
                    "—")
        return (name(dev.key) if dev else r.get("client", ""),
                f"{r.get('server')}:{r.get('port')}", r.get("proto", ""),
                r.get("encryption", ""),
                f"{r.get('auth_ok', 0)} / {r.get('auth_failures', 0)}"
                if r.get("auth_attempts") else "none seen",
                f"{r.get('messages', 0)} / {r.get('rcpt', 0)}",
                f"{_human_bytes(r.get('bytes_up', 0))} / "
                f"{_human_bytes(r.get('bytes_down', 0))}",
                human_duration(r.get("duration_s", 0) or 0),
                r.get("closed", ""))

    def refresh(self, force=False):
        v = self.app.deep.store.version
        if v == self._version and not force:
            return
        self._version = v
        rows = self.sessions()
        mode, _w = self.app.effective_perf_mode()
        with contextlib.suppress(tk.TclError):
            if mode != "Full Power":
                self.fp_btn.pack(side="left")
            else:
                self.fp_btn.pack_forget()
            self.summary.configure(text=self.summary_text(rows))
            self.tree.delete(*self.tree.get_children())
            self.rows = {}
            for i, r in enumerate(reversed(rows[-2000:])):
                iid = self.tree.insert("", "end", values=self.values(r))
                self.rows[iid] = r

    def _details(self, _e=None):
        sel = self.tree.selection()
        r = self.rows.get(sel[0]) if sel else None
        if r is not None:
            self.show(r)

    def report_sections(self, r):
        steps = "\n".join(f"+{t:.2f} s  {w}" for t, w in
                           r.get("timeline", [])) or "—"
        sec = [("What happened", r.get("summary", "")),
               ("Timeline", steps)]
        if r.get("proto") != "webmail":
            sec.append(("Logins", (
                f"{r.get('auth_attempts', 0)} attempt(s) using "
                f"{', '.join(r.get('auth_mechs') or ['?'])}: "
                f"{r.get('auth_ok', 0)} accepted, "
                f"{r.get('auth_failures', 0)} refused."
                + (" A login was sent before the connection was encrypted."
                   if r.get("auth_before_tls") else "")
                if r.get("auth_attempts") else "No login seen.")
                + " Passwords and login data are never read."))
            sec.append(("Mail sent", f"{r.get('messages', 0)} message(s) to "
                        f"{r.get('rcpt', 0)} recipient(s), "
                        f"{r.get('data_bytes', 0)} bytes. Addresses, "
                        f"subjects and contents are never kept."))
            if r.get("errors"):
                sec.append(("Errors", ", ".join(str(e) for e in
                                                r["errors"])))
        return sec

    def show(self, r):
        DetailDialog(self.app, f"Mail session: {r.get('server')}",
                     self.report_sections(r), size="600x560")

    def export(self, path=None):
        rows = self.sessions()
        if path is None:
            path = filedialog.asksaveasfilename(
                parent=self.app.root, title="Export mail report",
                defaultextension=".txt", initialfile="mail-report.txt",
                filetypes=[("Text", "*.txt")])
        if not path:
            return None
        lines = ["MiniWireshark — Email Traffic report (metadata only: no "
                 "contents, passwords or addresses)", "",
                 self.summary_text(rows), ""]
        for r in rows:
            lines.append(r.get("summary", ""))
            for h, txt in self.report_sections(r)[1:]:
                lines.append(f"  {h}: " + txt.replace("\n", "; "))
            lines.append("")
        text = scrub_secrets("\n".join(lines))
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)
        return path

    def reset(self):
        with contextlib.suppress(tk.TclError):
            self.tree.delete(*self.tree.get_children())
        self.rows = {}
        self._version = -1


# ---- Remote hosts (Advanced) -------------------------------------------------
class RemoteTab(BaseTab):
    name, label_key, advanced = "remote", "tab_remote", True
    VIEW_VARS = ("q_var",)
    COLS = [("ip", "Remote IP", 130, "w", False),
            ("country", "Country", 150, "w", False),
            ("asn", "Provider (ASN)", 190, "w", True),
            ("domain", "Known name(s)", 210, "w", True),
            ("ports", "Ports", 90, "w", False),
            ("protocols", "Protocol(s)", 100, "w", False),
            ("who", "Contacted by", 170, "w", True),
            ("traffic", "Traffic ↑/↓", 150, "w", False),
            ("conns", "Connections", 85, "e", False),
            ("packets", "Packets", 70, "e", False),
            ("first", "First seen", 80, "center", False),
            ("last", "Last seen", 80, "center", False)]

    def build(self):
        self.header("\U0001F5A5  INTERNET HOSTS — public Internet addresses "
                    "your devices talked to. These are never devices on your "
                    "network — they live somewhere out on the Internet.")
        geo = self.toolbar()
        self.geoip_var = tk.BooleanVar(
            value=self.app.config.get("privacy.geoip_enabled", False))
        cb = ttk.Checkbutton(geo, text="Online country lookup",
                             variable=self.geoip_var,
                             command=lambda: self.app._set_geoip_enabled(
                                 self.geoip_var.get()))
        cb.pack(side="left")
        Tooltip(cb, "Sends each remote IP address (never your own devices, "
                    "never packet contents) to a public geolocation service "
                    "to find its country. Off by default. The offline "
                    "database (Settings → Privacy) needs no online "
                    "lookups.")
        ttk.Button(geo, text="Test", width=6,
                   command=self.app._geoip_test).pack(side="left",
                                                       padx=(10, 0))
        ttk.Button(geo, text="Retry failed", width=12,
                   command=self.app._geoip_retry).pack(side="left",
                                                        padx=(6, 0))
        self.lbl(geo, "   Search:").pack(side="left")
        self.q_var = tk.StringVar()
        e = ttk.Entry(geo, textvariable=self.q_var, width=16)
        self.filter_entry = e
        e.pack(side="left", padx=4)
        self._filter_soon = debounce(self.frame, self.rebuild, 150)
        e.bind("<KeyRelease>", lambda ev: self._filter_soon())
        self.status_var = DisplayVar()
        tk.Label(self.frame, textvariable=self.status_var, bg=WHITE,
                 fg="#666666", justify="left", anchor="w", wraplength=1100,
                 font=mw_font(9)).pack(fill="x", padx=12)
        wrap, self.tree = make_tree(self.frame, self.COLS)
        wrap.pack(fill="both", expand=True, padx=6, pady=(4, 6))
        self.tree.bind("<Double-1>", self._details)
        self.iids = IidMap()
        host = self._host
        self.kit = TableKit(
            self, self.tree, wrap, "remote",
            key_of=lambda iid: key_for_iid(self.iids, iid),
            empty_state=self.empty_state,
            # the name, not the flag in front of it
            sort_values={
                "country": lambda k: host(k, lambda r: r.country_name or
                                          r.country or ""),
                "asn": lambda k: host(k, lambda r: r.org or ""),
                "traffic": lambda k: host(k, lambda r: r.bytes_total),
                "first": lambda k: host(k, lambda r: r.first_seen)},
            relative={"last": lambda k: host(k, lambda r: r.last_seen)},
            menu=self.menu_spec)

    def _host(self, ip, fn):
        r = self.model.remote_hosts.get(ip)
        return fn(r) if r is not None else None

    def empty_state(self):
        q = self.q_var.get().strip()
        if q:
            return TableKit.filtered(q, lambda: self.set_filter(""))
        return ("No Internet hosts yet. They appear when a device talks to "
                "a public address.", None, None)

    def menu_spec(self, ip):
        r = self.model.remote_hosts.get(ip)
        if r is None:
            return {}
        app = self.app
        return {
            "open": lambda: app.show_remote(ip),
            "copy": [("Copy IP", lambda: copy_to_clipboard(app, ip))],
            "filter": lambda: self.set_filter(ip),
            "packets": lambda: app.goto("packets", ip),
            "goto": [(f"{translate_text('Website')} — {r.domain}",
                      lambda: app.goto("websites", r.domain))]
            if r.domain else [],
            "own": [("Show devices that contacted it",
                     lambda: app.show_remote(ip)),
                    ("Show domain associations",
                     lambda: app.goto("websites", r.domain) if r.domain else
                     app._set_banner("No website names were seen for this "
                                     "address.")),
                    ("Show its connections",
                     lambda: app.goto("connections", ip))]}

    def _match(self, r):
        q = self.q_var.get().strip().lower()
        if not q:
            return True
        hay = " ".join([r.ip, r.domain, " ".join(r.domains), r.country,
                        r.country_name, r.org, str(r.asn)]).lower()
        return q in hay

    def values(self, r):
        app = self.app
        who = ", ".join(app.short_device_name(k)
                        for k in sorted(r.devices)[:3]) or "—"
        names = r.domain or ""
        if len(r.domains) > 1:
            names += f" +{len(r.domains) - 1}"
        if r.vpn_endpoint:
            names = f"(likely {r.vpn_endpoint} VPN server) " + names
        return (r.ip, r.location_text() or "—",
                r.provider_text() or "—", names or "(no name seen)",
                ", ".join(str(p) for p in sorted(r.ports)[:4]) or "—",
                ", ".join(sorted(r.protocols)[:4]) or "—", who,
                f"↑{_human_bytes(r.bytes_out)} "
                f"↓{_human_bytes(r.bytes_in)}", r.connections,
                r.packets, fmt_clock(r.first_seen), fmt_clock(r.last_seen))

    def update_keys(self, ips):
        if not self.is_visible():
            self._pending = True
            return
        for ip in ips:
            r = self.model.remote_hosts.get(ip)
            if r is None or not self._match(r):
                tree_remove(self.tree, self.iids, ip, kit=self.kit)
                continue
            tree_upsert(self.tree, self.iids, ip, self.values(r),
                        kit=self.kit)

    def refresh(self):
        self.status_var.set(self.app._geoip_status_text())
        if getattr(self, "_pending", False) and self.is_visible():
            self._pending = False
            self.rebuild_in_slices()

    def rebuild(self):
        for _ in self.rebuild_steps():
            pass

    def rebuild_steps(self):
        my = self._fill_gen = getattr(self, "_fill_gen", 0) + 1
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.kit.clear()
        recs = sorted(self.model.remote_hosts.values(),
                      key=lambda r: -r.bytes_total)
        for i, r in enumerate(recs[:5000]):
            if i and i % 200 == 0:
                yield
                if self._fill_gen != my:
                    return
            if self._match(r):
                tree_upsert(self.tree, self.iids, r.ip, self.values(r),
                            kit=self.kit)
        self.kit.empty_soon()

    def set_filter(self, text):
        self.q_var.set(text or "")
        self.rebuild()

    def select(self, ip):
        if ip not in self.iids:
            self.set_filter(ip)
        iid = self.iids.get(ip)
        if iid:
            with contextlib.suppress(tk.TclError):
                self.tree.selection_set(iid)
                self.tree.see(iid)

    def inspect_target(self):
        sel = self.tree.selection()
        ip = key_for_iid(self.iids, sel[0]) if sel else None
        return ("remote", ip) if ip else None

    def _details(self, _e=None):
        sel = self.tree.selection()
        if sel:
            ip = key_for_iid(self.iids, sel[0])
            if ip:
                self.app.show_remote(ip)

    def _context(self, event):
        return self.kit._right_click(event)

    def reset(self):
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.kit.clear()



# ---- Alerts ------------------------------------------------------------------
class AlertsTab(BaseTab):
    name, label_key = "alerts", "tab_alerts"
    VIEW_VARS = ("q_var", "sev_var")

    def build(self):
        top = self.header("\U0001F514  Alerts — every alert separates "
                          "what was observed from what it might mean. These "
                          "are ANOMALIES (unusual behaviour), never a "
                          "verdict that something is hacked.")
        legend = tk.Frame(top, bg=WHITE)
        legend.pack(anchor="w", pady=(6, 0))
        for icon, name, fg in (("ℹ", tr("legend_info"), "#333333"),
                               ("⚠", tr("legend_warning"), "#8a5a00"),
                               ("‼", tr("legend_danger"), "#a01a08")):
            tk.Label(legend, text=f"{icon} {name}", bg=WHITE, fg=fg,
                     font=mw_font(9)).pack(side="left",
                                                     padx=(0, 16))
        bar = self.toolbar()
        self.show_ack_var = tk.BooleanVar(value=True)
        ttk.Checkbutton(bar, text="Show acknowledged", command=self.rebuild,
                        variable=self.show_ack_var).pack(side="left")
        self.sev_var = tk.StringVar(value="All")
        self.lbl(bar, "  Severity:").pack(side="left")
        sb = ttk.Combobox(bar, textvariable=self.sev_var, width=10,
                          values=["All", "DANGER", "WARNING", "INFO"],
                          state="readonly")
        sb.pack(side="left", padx=4)
        sb.bind("<<ComboboxSelected>>", lambda e: self.rebuild())
        inv = ttk.Menubutton(bar, text="\U0001F50E Investigate…")
        menu = tk.Menu(inv, tearoff=False)
        menu.add_command(label="Why is my Internet slow?",
                         command=lambda: self.app.investigate("slow"))
        menu.add_command(label="What is using my bandwidth?",
                         command=lambda: self.app.investigate("bandwidth"))
        inv["menu"] = menu
        inv.pack(side="left", padx=(12, 0))
        self.lbl(bar, "  Search:").pack(side="left")
        self.q_var = tk.StringVar()
        qe = ttk.Entry(bar, textvariable=self.q_var, width=14)
        self.filter_entry = qe
        qe.pack(side="left", padx=4)
        self._filter_soon = debounce(self.frame, self.rebuild, 150)
        qe.bind("<KeyRelease>", lambda e: self._filter_soon())
        # 5.1.2: three buttons; the rest are under More and in the
        # right-click menu, all still there
        more = ttk.Menubutton(bar, text="More ▾")
        mm = tk.Menu(more, tearoff=False)
        for label, fn in (("Mark expected", self.mark_expected),
                          ("Mute this type", self.mute_type),
                          ("Mute for this device", self.mute_device),
                          ("Go to related", self.goto_related),
                          ("Copy report", self.copy_report)):
            mm.add_command(label=label, command=fn)
        snz = tk.Menu(mm, tearoff=False)            # 5.3.4 (IP-001)
        for label, secs in MiniWireshark.SNOOZE_CHOICES:
            snz.add_command(label=label, command=lambda s_=secs:
                            self.snooze(s_))
        mm.add_cascade(label="Snooze", menu=snz)
        more["menu"] = mm
        more.pack(side="right", padx=(4, 0))
        # 5.3.4 (IP-001): what mute and snooze held back stays visible
        self.held_var = tk.StringVar(value="")
        self.lbl(bar, "", textvariable=self.held_var).pack(side="right",
                                                           padx=(4, 0))
        for label, fn in (("Acknowledge", self.acknowledge),
                          ("Details", self._details)):
            ttk.Button(bar, text=label, command=fn).pack(side="right",
                                                         padx=(4, 0))
        # 5.1.2: one alert at a time, newest danger first
        self.review_btn = ttk.Button(bar, text="Review",
                                     command=self.app.review_alerts)
        self.review_btn.pack(side="right", padx=(4, 0))
        self._review_job = None
        wrap, self.tree = make_tree(
            self.frame, [("sev", "Severity", 100, "w", False),
                         ("when", "Last seen", 80, "center", False),
                         ("reason", "What happened", 440, "w", True),
                         ("device", "Related to", 190, "w", False),
                         ("conf", "Confidence", 85, "w", False),
                         ("count", "Times", 55, "e", False),
                         ("status", "Status", 110, "w", False)],
            selectmode="extended")
        wrap.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        self.tree.bind("<Double-1>", self._details)
        self.tree.bind("<Return>", self._details)
        self.iids = IidMap()
        alert = self._alert
        self.kit = TableKit(
            self, self.tree, wrap, "alerts",
            key_of=lambda iid: key_for_iid(self.iids, iid),
            empty_state=self.empty_state,
            sort_values={"count": lambda k: alert(k, lambda a: a.count)},
            relative={"when": lambda k: alert(
                k, lambda a: a.last_seen or a.when)},
            dot_col="reason", menu=self.menu_spec,
            all_keys=lambda: list(self.model.alerts.alerts),
            explain=self.explain_row)
        self.on_theme()

    def explain_row(self, aid):
        a = self.model.alerts.alerts.get(aid)
        if a is None:
            return ""
        tr_ = translate_text
        means = tr_(explain("alert", a.kind))
        steps = ALERT_CHECKLIST.get(a.kind) or []
        out = f"{tr_('What it usually means:')} {means}" if means else ""
        if steps:
            out += f"\n{tr_('What to check:')} {tr_(steps[0])}"
        return out

    def _alert(self, aid, fn):
        a = self.model.alerts.alerts.get(aid)
        return fn(a) if a is not None else None

    def empty_state(self):
        q = self.q_var.get().strip()
        if q:
            return TableKit.filtered(q, lambda: (self.q_var.set(""),
                                                 self.rebuild()))
        if self.model.alerts.alerts:
            return ("No alerts match these filters.", "Show all",
                    self._show_all)
        return ("Nothing unusual so far. That is good news, not a sign that "
                "checks are off.", "Alert settings",
                lambda: self.app._open_settings("Alerts"))

    def _show_all(self):
        self.q_var.set("")
        self.show_ack_var.set(True)
        self.sev_var.set("All")
        self.rebuild()

    def menu_spec(self, aid):
        a = self.model.alerts.alerts.get(aid)
        if a is None:
            return {}
        app = self.app
        dev = self.model.registry.by_key.get(a.device_key)
        who = dev.display_name() if dev else ""
        spec = {"open": lambda: app.show_alert(aid),
                "copy": [("Copy report", self.copy_report)],
                "filter": lambda: (self.q_var.set(who or a.reason),
                                   self.rebuild()),
                "own": [("Acknowledge", self.acknowledge),
                        ("Mark expected", self.mark_expected),
                        ("Mute this alert type", self.mute_type),
                        ("Mute for this device", self.mute_device),
                        ("Snooze for 1 hour", lambda: self.snooze(3600)),
                        ("Snooze for 1 day", lambda: self.snooze(86400)),
                        None,
                        ("Go to related item", self.goto_related)]}
        if dev is not None:
            spec["packets"] = lambda: app.goto(
                "packets", f'device:"{dev.ip or dev.mac}"')
            spec["goto"] = [(f"{translate_text('Device')} — {who}",
                             lambda: app.goto("device", dev.key))]
        return spec

    def on_theme(self):
        for sev, (fg, bg) in self.app._severity_colors().items():
            with contextlib.suppress(tk.TclError):
                self.tree.tag_configure(sev, foreground=fg,
                                        background=bg or "")
        with contextlib.suppress(tk.TclError):
            self.tree.tag_configure("ack", foreground=self.t["muted_fg"],
                                    background="")

    def _visible(self, a):
        if a.acknowledged and not self.show_ack_var.get():
            return False
        if self.sev_var.get() != "All" and a.severity != self.sev_var.get():
            return False
        q = self.q_var.get().strip().lower() if hasattr(self, "q_var") \
            else ""
        if q:
            dev = self.model.registry.by_key.get(a.device_key)
            hay = " ".join([a.reason, a.kind, a.device_key,
                            dev.display_name() if dev else ""]).lower()
            if q not in hay:
                return False
        return True

    def values(self, a):
        dev = self.model.registry.by_key.get(a.device_key)
        who = dev.display_name() if dev else (a.device_key.replace(
            "ip:", "") or "—")
        icon = self.app.SEVERITY_ICON.get(a.severity, "")
        status = "Acknowledged" if a.acknowledged else "New"
        if not a.live:
            status += " (saved)"
        return (f"{icon} {a.severity}", fmt_clock(a.last_seen or a.when),
                translate_event(a.reason), who, a.confidence, a.count,
                status)

    def upsert(self, a):
        if not self._visible(a):
            tree_remove(self.tree, self.iids, a.id, kit=self.kit)
            return
        tags = ("ack",) if a.acknowledged else (a.severity,)
        tree_upsert(self.tree, self.iids, a.id, self.values(a), tags=tags,
                    index=0, kit=self.kit)
        self.review_soon()

    def review_soon(self):
        if getattr(self, "_review_job", None):
            return
        with contextlib.suppress(tk.TclError):
            self._review_job = self.frame.after(300, self._sync_review)

    def _sync_review(self):
        self._review_job = None
        n = len(self.app.review_queue())
        with contextlib.suppress(tk.TclError):
            text = (translate_text("Review %d new") % n if n else
                    translate_text("Review"))
            if self.review_btn.cget("text") != text:
                self.review_btn.configure(text=text)
            self.review_btn.state(["!disabled"] if n else ["disabled"])
            held = self.model.alerts.suppressed
            self.held_var.set(translate_text("%d held back (muted or "
                                             "snoozed)") % held
                              if held else "")

    def rebuild(self):
        for _ in self.rebuild_steps():
            pass

    def rebuild_steps(self):
        my = self._fill_gen = getattr(self, "_fill_gen", 0) + 1
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.kit.clear()
        for i, aid in enumerate(list(reversed(self.model.alerts.order))):
            if i and i % 200 == 0:
                yield
                if self._fill_gen != my:
                    return
            a = self.model.alerts.alerts.get(aid)
            if a:
                self.upsert(a)

    def inspect_target(self):
        sel = self.tree.selection()
        aid = key_for_iid(self.iids, sel[0]) if sel else None
        return ("alert", aid) if aid else None

    def selected(self):
        out = []
        for iid in self.tree.selection():
            aid = key_for_iid(self.iids, iid)
            a = self.model.alerts.alerts.get(aid)
            if a:
                out.append(a)
        return out

    def select(self, aid):
        if aid not in self.iids:
            self.show_ack_var.set(True)
            self.sev_var.set("All")
            self.rebuild()
        iid = self.iids.get(aid)
        if iid:
            with contextlib.suppress(tk.TclError):
                self.tree.selection_set(iid)
                self.tree.see(iid)

    def _details(self, _e=None):
        sel = self.selected()
        if sel:
            self.app.show_alert(sel[0].id)

    def acknowledge(self):
        for a in self.selected():
            a.acknowledged = True
            self.upsert(a)

    def mark_expected(self):
        for a in self.selected():
            self.app.alert_mark_expected(a)
            self.upsert(a)

    def mute_type(self):
        sel = self.selected()
        if sel:
            self.app.alert_mute_type(sel[0])

    def mute_device(self):
        for a in self.selected():
            self.app.alert_mute_device(a)
            self.upsert(a)

    def snooze(self, seconds):
        for a in self.selected():
            self.app.alert_snooze(a, seconds)
            self.upsert(a)

    def goto_related(self):
        sel = self.selected()
        if sel:
            self.app.alert_goto_related(sel[0])

    def copy_report(self):
        sel = self.selected()
        if sel:
            copy_to_clipboard(self.app, self.app.alert_text(sel[0]))

    def _context(self, event):
        return self.kit._right_click(event)

    def reset(self):
        self.tree.delete(*self.tree.get_children())
        self.iids.clear()
        self.kit.clear()


# ---- Network map v2 ----------------------------------------------------------
class MapTab(BaseTab):
    name, label_key = "map", "tab_map"
    LEGEND = ("Letters = confidence (H M L ?) · hollow = offline · ─ seen "
              "(switch said so) · ┄ logical (inferred) · ★ new this hour "
              "· red ring = open alert · drag a device to place it")

    def build(self):
        top = tk.Frame(self.frame, bg=WHITE, padx=10, pady=6)
        top.pack(fill="x")
        tk.Label(top, text="\U0001F5FA  Network map", bg=WHITE, fg="#333333",
                 font=mw_font(11, "bold")).pack(side="left")
        tk.Label(top, text="   Click a node to select it, double-click for "
                           "details, drag the background to move, scroll or "
                           "use +/− to zoom.", bg=WHITE, fg="#888888",
                 font=mw_font(9), justify="left",
                 wraplength=900).pack(side="left")
        ctrl = self.toolbar()
        self.mode_var = tk.StringVar(value="Topology")
        ttk.Radiobutton(ctrl, text="Topology (your LAN)",
                        variable=self.mode_var, value="Topology",
                        command=self.redraw).pack(side="left")
        ttk.Radiobutton(ctrl, text="Connections (device → website → "
                                   "remote host)", variable=self.mode_var,
                        value="Connections",
                        command=self.redraw).pack(side="left", padx=(12, 0))
        self.lbl(ctrl, "   Device:").pack(side="left")
        self.dev_var = tk.StringVar(value="All devices")
        self.dev_box = ttk.Combobox(ctrl, textvariable=self.dev_var,
                                    state="readonly", width=24,
                                    values=["All devices"])
        self.dev_box.pack(side="left", padx=4)
        self.dev_box.bind("<<ComboboxSelected>>", lambda e: self.redraw())
        self.dev_box.bind("<Button-1>", lambda e: self.dev_box.configure(
            values=self.device_choices()), add="+")
        self.inactive_var = tk.BooleanVar(value=False)
        ttk.Checkbutton(ctrl, text="Include offline devices",
                        variable=self.inactive_var,
                        command=self.redraw).pack(side="left", padx=(8, 0))
        # the five layer switches live in one "Show ▾" menu now: their own
        # row of checkboxes left the map a few pixels tall on a laptop
        self.layer_internet = tk.BooleanVar(value=True)
        self.layer_switch = tk.BooleanVar(value=True)
        self.ov_traffic = tk.BooleanVar(value=True)
        self.ov_alerts = tk.BooleanVar(value=True)
        self.ov_new = tk.BooleanVar(value=True)
        self.layers = (("Internet hosts", self.layer_internet),
                       ("Switch (LLDP/CDP)", self.layer_switch),
                       ("Traffic", self.ov_traffic),
                       ("Open alerts", self.ov_alerts),
                       ("New this hour", self.ov_new))
        ttk.Button(ctrl, text="Forget dragged positions",
                   command=self.forget_positions).pack(side="right")
        self.list_btn = ttk.Button(ctrl, text="List view",
                                   command=self.toggle_list)
        self.list_btn.pack(side="right", padx=6)
        show = ttk.Button(ctrl, text="Show ▾")
        show.configure(command=lambda b=show: self._layers_menu(b))
        show.pack(side="right", padx=(0, 6))
        ttk.Button(ctrl, text="Reset view", command=self.reset_view).pack(
            side="right", padx=(0, 6))
        ttk.Button(ctrl, text="−", width=3,
                   command=lambda: self.zoom(0.8)).pack(side="right", padx=2)
        ttk.Button(ctrl, text="+", width=3,
                   command=lambda: self.zoom(1.25)).pack(side="right", padx=2)
        self.info_var = DisplayVar(value="")
        tk.Label(self.frame, textvariable=self.info_var, bg=WHITE,
                 fg="#666666", anchor="w", font=mw_font(9)).pack(
            fill="x", padx=12)
        self.legend_lbl = tk.Label(
            self.frame, bg=WHITE, fg="#888888", anchor="w", justify="left",
            wraplength=1100, font=mw_font(8), text=self.LEGEND)
        self.legend_lbl.pack(side="bottom", fill="x", padx=12, pady=(0, 4))
        self.c = tk.Canvas(self.frame, bg=WHITE, highlightthickness=0,
                           takefocus=1)
        self.c.pack(fill="both", expand=True, padx=10, pady=6)
        self.list_wrap, self.list_tree = make_tree(self.frame, [
            ("name", "Device", 220, "w", True),
            ("kind", "Kind", 160, "w", False),
            ("addr", "Address", 140, "w", False),
            ("via", "Connected via", 330, "w", True),
            ("state", "Status", 100, "w", False),
            ("lvl", "Evidence", 100, "w", False)])
        self.list_tree.bind("<Double-1>", self._list_open)
        self.list_tree.bind("<Return>", self._list_open)
        self.c.bind("<Key>", self._key)
        self.c.bind("<FocusIn>", lambda e: self.info_var.set(
            "Keyboard: arrows move · + / − zoom · 0 resets · Tab picks a "
            "device · Enter opens it"))
        self._node_drag = None
        self.scale, self.ox, self.oy = 1.0, 0.0, 0.0
        self.nodes = {}            # canvas item id -> (kind, key, label, info)
        self.selected = None
        self._drag = None
        self._hover_items = []
        self._last_sig = None
        # hidden, the map is drawn when shown (a text-size change re-laid
        # out the hidden canvas and drew 300 devices for nothing)
        self.c.bind("<Configure>", lambda e: self.redraw()
                    if self.is_visible() else None)
        self.c.bind("<ButtonPress-1>", self._press)
        self.c.bind("<B1-Motion>", self._motion)
        self.c.bind("<ButtonRelease-1>", self._release)
        self.c.bind("<Double-1>", self._double)
        self.c.bind("<Motion>", self._hover)
        self.c.bind("<Button-3>", self._context)
        self.c.bind("<Button-2>", self._context)
        self.c.bind("<MouseWheel>", lambda e: self.zoom(1.1 if e.delta > 0
                                                        else 0.9))
        self.c.bind("<Button-4>", lambda e: self.zoom(1.1))
        self.c.bind("<Button-5>", lambda e: self.zoom(0.9))

    def _layers_menu(self, btn):
        m = themed_menu(self.app)
        for text, var in self.layers:
            m.add_checkbutton(label=text, variable=var,
                              command=lambda: self.redraw(force=True))
        try:
            m.tk_popup(btn.winfo_rootx(), btn.winfo_rooty() +
                       btn.winfo_height())
        finally:
            m.grab_release()

    # ---- view transform
    def P(self, x, y):
        w, h = self.c.winfo_width(), self.c.winfo_height()
        return (w / 2 + (x - w / 2) * self.scale + self.ox,
                h / 2 + (y - h / 2) * self.scale + self.oy)

    def zoom(self, f):
        self._fast_zoom(f)

    def reset_view(self):
        self.scale, self.ox, self.oy = 1.0, 0.0, 0.0
        self.selected = None
        self.redraw(force=True)

    def forget_positions(self):
        allpos = dict(self.app.config.get("map.positions", {}) or {})
        allpos.pop(self.app.network_fp or "default", None)
        self.app.config.set("map.positions", allpos)
        self.app.config.save()
        self.redraw(force=True)

    def _list_open(self, _e=None):
        sel = self.list_tree.selection()
        if sel and sel[0].startswith("d:"):
            self.app.show_device(sel[0][2:])

    def _press(self, e):
        with contextlib.suppress(tk.TclError):
            self.c.focus_set()
        node = self._node_at(e.x, e.y)
        if node and node[0] == "device" and self.mode_var.get() == \
                "Topology":
            self._node_drag = (node[1], e.x, e.y, e.x, e.y, False)
            self._drag = None
            return
        self._node_drag = None
        self._drag = (e.x, e.y, self.ox, self.oy, False, e.x, e.y)

    def _motion(self, e):
        nd = self._node_drag
        if nd:
            key, x0, y0, lx, ly, _mv = nd
            if abs(e.x - x0) + abs(e.y - y0) > 3:
                self.c.move(f"n:{key}", e.x - lx, e.y - ly)
                self._node_drag = (key, x0, y0, e.x, e.y, True)
            return
        if self._drag:
            x0, y0, ox, oy, _m, lx, ly = self._drag
            if abs(e.x - x0) + abs(e.y - y0) > 3:
                self.ox, self.oy = ox + e.x - x0, oy + e.y - y0
                self._drag = (x0, y0, ox, oy, True, e.x, e.y)
                self._fast_pan(e.x - lx, e.y - ly)

    def _release(self, e):
        nd = self._node_drag
        self._node_drag = None
        if nd and nd[5]:
            key = nd[0]
            w, h = self.c.winfo_width(), self.c.winfo_height()
            # screen → layout coordinates (undo pan and zoom)
            x = (e.x - self.ox - w / 2) / self.scale + w / 2
            y = (e.y - self.oy - h / 2) / self.scale + h / 2
            self._save_position(key, x / max(w, 1), y / max(h, 1))
            self.redraw(force=True)
            return
        moved = self._drag[4] if self._drag else False
        self._drag = None
        if moved:
            return
        node = self._node_at(e.x, e.y)
        self.selected = (node[0], node[1]) if node else None
        if node:
            self.info_var.set(f"Selected: {node[2]} — {node[3]}  "
                              f"(double-click for details)")
        else:
            self.info_var.set("")
        self.redraw(force=True)

    def _double(self, e):
        node = self._node_at(e.x, e.y)
        if node:
            self._open(node[0], node[1])

    def _open(self, kind, key):
        app = self.app
        if kind == "device":
            app.show_device(key)
        elif kind == "website":
            app.show_website(key)
        elif kind == "remote":
            app.show_remote(key)
        elif kind == "router" and app.model.gateway_ip:
            dev = app.model.device_for(app.model.gateway_ip)
            if dev:
                app.show_device(dev.key)

    def _context(self, e):
        node = self._node_at(e.x, e.y)
        if not node:
            return
        kind, key = node[0], node[1]
        app = self.app
        items = [("Details", lambda: self._open(kind, key))]
        if kind == "device":
            dev = app.model.registry.by_key.get(key)
            if dev:
                items = app.device_menu_items(dev)
                items.insert(1, ("Focus the map on this device",
                                 lambda: self._focus(dev)))
        elif kind == "website":
            items += [("Copy domain", lambda: copy_to_clipboard(app, key)),
                      ("Show in Websites", lambda: app.goto("websites",
                                                            key))]
        elif kind == "remote":
            items += [("Copy IP", lambda: copy_to_clipboard(app, key)),
                      ("Show in Remote hosts", lambda: app.goto("remote",
                                                                key))]
        popup_menu(app, e, items)

    def _focus(self, dev):
        self.dev_var.set(f"{dev.display_name()}  [{dev.ip or dev.mac}]")
        self.mode_var.set("Connections")
        self.redraw(force=True)

    def _node_at(self, x, y):
        for item in reversed(self.c.find_overlapping(x - 3, y - 3, x + 3,
                                                     y + 3)):
            if item in self.nodes:
                return self.nodes[item]
        return None

    def _hover(self, e):
        for it in self._hover_items:
            self.c.delete(it)
        self._hover_items = []
        node = self._node_at(e.x, e.y)
        if not node:
            self.c.configure(cursor="")
            return
        self.c.configure(cursor="hand2")
        t = self.t
        txt = self.c.create_text(e.x + 14, e.y + 12, anchor="nw",
                                 text=f"{node[2]}\n{node[3]}",
                                 fill=t["tooltip_fg"],
                                 font=("TkDefaultFont", 9))
        bb = self.c.bbox(txt)
        if bb:
            rect = self.c.create_rectangle(bb[0] - 5, bb[1] - 4, bb[2] + 5,
                                           bb[3] + 4, fill=t["tooltip_bg"],
                                           outline=t["border"])
            self.c.tag_raise(txt, rect)
            self._hover_items = [rect, txt]

    # ---- drawing
    def refresh(self):
        if self.is_visible():
            self.redraw()

    def _devices(self):
        devs = [d for d in self.model.registry.by_key.values()
                if (not d.live) or d.state in (STATE_ACTIVE, STATE_IDLE) or
                (self.inactive_var.get() and d.state == STATE_INACTIVE)]
        key = self.device_key_from_choice(self.dev_var.get())
        if key:
            devs = [d for d in devs if d.key == key]
        return devs

    def redraw(self, force=False):
        c = self.c
        try:
            w, h = c.winfo_width(), c.winfo_height()
        except tk.TclError:
            return
        if w < 40 or h < 40:
            return
        m = self.model
        sig = (self.mode_var.get(), self.dev_var.get(), self.scale, self.ox,
               self.oy, self.selected, len(m.registry.by_key),
               len(m.websites), len(m.remote_hosts), w, h,
               self.inactive_var.get(), self.app.theme_name,
               self.app.high_contrast, CVD_STATE["mode"],
               int(m.now() // 10), UI_SCALE[0],
               self.app.config.get("appearance.text_size", "Normal"))
        if sig == self._last_sig and not force:
            return
        self._last_sig = sig
        c.delete("all")
        self.nodes.clear()
        self._label_boxes = []
        self._label_ids = []
        self._hover_items = []
        c.configure(bg=self.t["tab_bg"])
        if self.mode_var.get() == "Topology":
            self._topology(w, h)
            self._draw_stars(w, h)
            self.after_draw_declutter()
        else:
            self._connections(w, h)
        c.tag_lower("edge")
        if self.list_wrap.winfo_ismapped():
            self.fill_list()

    def _conf_color(self, conf):
        t = self.t
        return {"High": t["conf_high"], "Medium": t["conf_med"],
                "Low": t["conf_low"]}.get(conf, t["conf_none"])

    def _node(self, x, y, r, fill, kind, key, label, info, hollow=False,
              letter="", show_label=True):
        t = self.t
        X, Y = self.P(x, y)
        R = r * max(0.7, min(1.6, self.scale))
        sel = self.selected == (kind, key)
        tag = (f"n:{key}", "node")
        oid = self.c.create_oval(X - R, Y - R, X + R, Y + R,
                                 fill="" if hollow else fill,
                                 outline=t["focus"] if sel else fill,
                                 width=3 if sel else 2, tags=tag)
        self.nodes[oid] = (kind, key, label, info)
        # labels placed later keep clear of this node too
        boxes = getattr(self, "_label_boxes", None)
        if boxes is None:
            boxes = self._label_boxes = []
        boxes.append((X - R, Y - R, X + R, Y + R, f"n:{key}"))
        if letter:
            lid = self.c.create_text(X, Y, text=letter,
                                     fill=t["tab_bg"] if not hollow
                                     else fill, tags=tag,
                                     font=("TkDefaultFont", 8, "bold"))
            self.nodes[lid] = (kind, key, label, info)
        if show_label:
            tid = self.c.create_text(X, Y + R + 8, text=label[:22],
                                     fill=t["text_fg"], tags=tag,
                                     font=("TkDefaultFont", 8,
                                           "bold" if sel else "normal"))
            self.nodes[tid] = (kind, key, label, info)
            self._place_label(tid, X, Y, R, label, sel)
            self._label_ids.append((tid, X, Y, R, label, sel))
        return X, Y

    def _draw_stars(self, w, h):
        """★ = new this hour, drawn once every node is placed: at a corner
        of its node that is free (the release-gate pictures showed stars
        on the neighbours' letters and on the title); none, and a note,
        when most devices are new (reading a file: every one is)."""
        c, t = self.c, self.t
        stars = getattr(self, "_stars", [])
        total = len({v[1] for v in self.nodes.values() if v[0] == "device"})
        hide = bool(stars) and len(stars) > max(3, total // 2)
        # the note goes in the legend line under the map (on the canvas
        # it landed on a node in French)
        with contextlib.suppress(tk.TclError, AttributeError):
            self.legend_lbl.configure(text=translate_text(self.LEGEND) + (
                "  ·  " + translate_text("★ not shown: most devices are new "
                                         "this hour") if hide else ""))
        if not stars or hide:
            return
        for X, Y, R, key in stars:
            k = R * 0.7
            sid = c.create_text(X + k, Y - k, text="★", anchor="sw",
                                fill=t["warn_fg"], tags=(f"n:{key}", "ov"),
                                font=("TkDefaultFont", 10))
            for x, y, anchor in ((X + k, Y - k, "sw"), (X - k, Y - k, "se"),
                                 (X + k, Y + k, "nw"), (X - k, Y + k, "ne")):
                c.coords(sid, x, y)
                c.itemconfigure(sid, anchor=anchor)
                b = c.bbox(sid)
                if not b:
                    break
                own = f"n:{key}"
                if not any(i != sid and c.type(i) in ("text", "oval") and
                           own not in c.gettags(i) and
                           not (c.type(i) == "oval" and
                                "deco" in c.gettags(i))
                           for i in c.find_overlapping(*b)):
                    break
            else:
                c.coords(sid, X + k, Y - k)
                c.itemconfigure(sid, anchor="sw")

    def after_draw_declutter(self):
        """Second pass once everything is drawn (stars, rings, the router
        and titles come after some names): every name keeps clear of
        every other text and node."""
        c = self.c
        labels = {t[0] for t in getattr(self, "_label_ids", ())}
        fixed = []
        for i in c.find_all():
            if i in labels:
                continue
            kind = c.type(i)
            if kind in ("text", "oval") and str(c.itemcget(i, "state")) \
                    != "hidden":
                b = c.bbox(i)
                # nodes, letters, stars and titles; not the big dashed
                # ring around the local network
                if b and (kind == "text" or (b[2] - b[0] < 80 and
                                             b[3] - b[1] < 80)):
                    # a node's own circles do not block its name; its
                    # star and other texts do
                    own = next((t for t in c.gettags(i)
                                if t.startswith("n:")), "") \
                        if kind == "oval" else ""
                    fixed.append(tuple(b) + (own,))
        self._label_boxes = fixed
        for tid, X, Y, R, label, sel in getattr(self, "_label_ids", ()):
            c.itemconfigure(tid, state="normal")
            self._place_label(tid, X, Y, R, label, sel)

    def _place_label(self, tid, X, Y, R, label, sel):
        """Names of neighbouring nodes were written over each other on a
        small map: try below, then above, then a shorter name; if none
        fits, the name shows on hover only (the selected one always
        shows)."""
        boxes = getattr(self, "_label_boxes", None)
        if boxes is None:
            boxes = self._label_boxes = []
        c = self.c

        own = next((t for t in c.gettags(tid) if t.startswith("n:")), "")

        def free():
            b = c.bbox(tid)
            if not b:
                return True
            for o in boxes:
                if len(o) > 4 and o[4] == own:
                    continue        # its own node, ring and star
                if b[0] < o[2] and o[0] < b[2] and b[1] < o[3] and \
                        o[1] < b[3]:
                    return False
            return True
        short = label[:10] + ("…" if len(label) > 10 else "")
        # below, above, then (5.1.2) right and left of the node, then the
        # short name; the selected name always shows, in the first free
        # place or else below
        tries = ((X, Y + R + 8, label[:22], "center"),
                 (X, Y - R - 8, label[:22], "center"),
                 (X + R + 6, Y, label[:22], "w"),
                 (X - R - 6, Y, label[:22], "e"),
                 (X, Y + R + 8, short, "center"),
                 (X, Y - R - 8, short, "center"),
                 (X + R + 6, Y, short, "w"),
                 (X - R - 6, Y, short, "e"))
        ok = False
        for x, y, text, anchor in tries:
            c.coords(tid, x, y)
            c.itemconfigure(tid, text=text, anchor=anchor)
            if free():
                ok = True
                break
        if not ok and sel:
            c.coords(tid, X, Y + R + 8)
            c.itemconfigure(tid, text=label[:22], anchor="center")
            ok = True
        if not ok:
            c.itemconfigure(tid, state="hidden")
            return
        b = c.bbox(tid)
        if b:
            boxes.append(tuple(b) + (own,))

    def _line(self, a, b, weight=0, dash=(), hi=False, tag=None):
        t = self.t
        width = 1 + min(5, int(math.log10(max(weight, 1)) / 1.5)) \
            if weight else 1
        self.c.create_line(a[0], a[1], b[0], b[1],
                           fill=t["line_hi"] if hi else t["line"],
                           width=width + (1 if hi else 0), dash=dash,
                           tags=("edge",) + ((tag,) if tag else ()))

    # ---- Map v3: layers, saved positions, evidence-styled edges, fast
    #      pan/zoom, keyboard and a list twin -----------------------------------
    KIND_ORDER = ("router", "computer", "this-pc", "phone", "tablet", "tv",
                  "speaker", "console", "printer", "camera", "iot",
                  "unknown")

    def _ui_scale(self):
        try:
            return max(1.0, float(self.c.tk.call("tk", "scaling")) / 1.333)
        except (tk.TclError, ValueError):
            return 1.0

    KEEP_NETWORKS = 10

    def _positions_store(self):
        allpos = self.app.config.get("map.positions", {}) or {}
        return allpos.get(self.app.network_fp or "default", {})

    def _save_position(self, key, fx, fy):
        allpos = dict(self.app.config.get("map.positions", {}) or {})
        net = self.app.network_fp or "default"
        cur = dict(allpos.get(net, {}))
        cur[key] = [round(fx, 4), round(fy, 4)]
        if len(cur) > 2000:
            cur = dict(list(cur.items())[-2000:])
        allpos.pop(net, None)              # most recently used last
        allpos[net] = cur
        if len(allpos) > self.KEEP_NETWORKS:
            # 5.2.3 (B-30): positions were kept for every network ever
            # seen, and the whole settings file is rewritten on each drag
            allpos = dict(list(allpos.items())[-self.KEEP_NETWORKS:])
        self.app.config.set("map.positions", allpos)
        self.app.config.save()

    def layout_topology(self, devs, w, h):
        """Deterministic ring layout grouped by kind (sectors), for any
        number of devices; positions you dragged are kept."""
        cx, cy = w * 0.36, h / 2
        # never larger than the canvas (the ring was cut off top and
        # bottom on a short window); 80 is still the size it aims for
        base_r = max(min(80, h / 2 - 28), min(h, w * 0.6) * 0.40, 24)
        saved = self._positions_store()
        order = sorted(devs, key=lambda d: (
            self.KIND_ORDER.index(d.type) if d.type in self.KIND_ORDER
            else len(self.KIND_ORDER), d.display_name().lower(), d.key))
        pos, i, ring = {}, 0, 0
        n = len(order)
        while i < n:
            cap = 14 + 10 * ring
            chunk = order[i:i + cap]
            rr = base_r * (0.55 + 0.28 * ring) if n > 14 else base_r * 0.72
            for j, d in enumerate(chunk):
                ang = 2 * math.pi * j / max(len(chunk), 1) - math.pi / 2 + \
                    ring * 0.21
                pos[d.key] = (cx + rr * math.cos(ang), cy + rr * math.sin(
                    ang))
            i += cap
            ring += 1
        for k, (fx, fy) in saved.items():
            if k in pos:
                pos[k] = (fx * w, fy * h)
        return pos, (cx, cy), base_r * (0.55 + 0.28 * max(ring - 1, 0)) \
            if n > 14 else base_r

    def _topology(self, w, h):
        t, m = self.t, self.model
        ui = self._ui_scale()
        devs = sorted(self._devices(), key=lambda d: d.display_name())
        gw = m.gateway_ip
        devs = [d for d in devs if d.ip != gw or not gw][:400]
        pos, (cx, cy), radius = self.layout_topology(devs, w, h)
        self._pos = pos
        X0, Y0 = self.P(cx, cy)
        R0 = radius * self.scale * 1.08
        self.c.create_oval(X0 - R0, Y0 - R0, X0 + R0, Y0 + R0,
                           outline=t["muted_fg"], dash=(4, 3),
                           tags=("deco",))
        if radius >= 60:          # small ring: the title would sit on a node
            tt = self.c.create_text(X0, Y0 - R0 - 12,
                                    text="YOUR LOCAL NETWORK",
                                    fill=t["muted_fg"], tags=("deco",),
                                    font=("TkDefaultFont", 9,
                                          "bold"))
            if self.c.bbox(tt):
                self._label_boxes = [self.c.bbox(tt)]
        # the router is drawn last, in the middle: keep names off it
        rr_ = 18 * ui * max(0.7, min(1.6, self.scale)) + 4
        self._label_boxes = getattr(self, "_label_boxes", []) + [
            (X0 - rr_, Y0 - rr_, X0 + rr_, Y0 + rr_)]
        sel_key = self.selected[1] if self.selected and \
            self.selected[0] == "device" else None
        stars = self._stars = []
        alerted = {a.device_key for a in m.alerts.alerts.values()
                   if a.severity in ("WARNING", "DANGER") and
                   not getattr(a, "acknowledged", False)} \
            if self.ov_alerts.get() else set()
        now = m.now()
        sw = m.switch_summary(now)
        me = m.my_device_key()
        sw_pos = None
        if sw and self.layer_switch.get():
            sw_pos = (cx - radius * 0.35, cy + radius * 0.35)
        traffic = self.ov_traffic.get()
        self._list_rows = []
        for dev in devs:
            x, y = pos[dev.key]
            weight = (dev.bytes_up + dev.bytes_down) if traffic else 0
            hi = dev.key == sel_key
            if sw_pos and dev.key == me:
                # an Observed physical link: the switch said so (LLDP/CDP)
                self._line(self.P(*sw_pos), self.P(x, y), weight, hi=hi,
                           tag=f"e:{dev.key}")
                via = (f"switch {sw['system'] or sw['chassis']} port "
                       f"{sw['port_desc'] or sw['port']} (◉ LLDP/CDP)")
            else:
                # logical only: we know it uses the router, not the path
                self._line(self.P(cx, cy), self.P(x, y), weight,
                           dash=(5, 4), hi=hi, tag=f"e:{dev.key}")
                via = "router (◌ logical — the physical path isn't visible)"
            hollow = dev.live and dev.state not in (STATE_ACTIVE, STATE_IDLE)
            letter = dev.confidence[:1] if dev.confidence != \
                CONFIDENCE_UNCONFIRMED else "?"
            info = (f"{dev.class_confidence} {dev.device_class}".strip() +
                    f" · {dev.ip or dev.mac} · "
                    f"{dev.confidence} confidence · "
                    f"{STATE_LABEL.get(dev.state, dev.state)} · "
                    f"↑{_human_bytes(dev.bytes_up)} "
                    f"↓{_human_bytes(dev.bytes_down)}")
            label = f"{DEVICE_ICONS.get(dev.type, '')} " \
                    f"{self.app.device_label(dev)}"
            X, Y = self._node(x, y, 10 * ui, self._conf_color(dev.confidence),
                              "device", dev.key, label, info, hollow=hollow,
                              letter=letter, show_label=len(devs) <= 60 or
                              hi)
            R = 10 * ui * max(0.7, min(1.6, self.scale))
            if dev.key in alerted:
                self.c.create_oval(X - R - 5, Y - R - 5, X + R + 5, Y + R + 5,
                                   outline=t["danger_fg"], width=2,
                                   tags=(f"n:{dev.key}", "ov"))
            if self.ov_new.get() and now - dev.first_seen < 3600 and \
                    dev.live:
                stars.append((X, Y, R, dev.key))
            self._list_rows.append((dev.key, label.strip(),
                                    f"{dev.class_confidence} "
                                    f"{dev.device_class}".strip(),
                                    dev.ip or dev.mac, via,
                                    STATE_LABEL.get(dev.state, dev.state),
                                    LEVEL_WORD.get(device_weakest(m, dev),
                                                   "")))
        if sw_pos:
            self._line(self.P(*sw_pos), self.P(cx, cy), 0, dash=(5, 4),
                       tag="e:switch")
            name = sw["system"] or sw["chassis"]
            self._node(sw_pos[0], sw_pos[1], 12 * ui, t["node_router"],
                       "switch", name, f"\U0001F500 {name}",
                       f"Switch (announced itself via {sw['proto']}) · "
                       f"this computer is on port "
                       f"{sw['port_desc'] or sw['port']}"
                       + (f", VLAN {sw['vlan']}" if sw["vlan"] else ""),
                       letter="S")
        self._node(cx, cy, 18 * ui, t["node_router"], "router", "router",
                   "Your router", gw or "router address not known yet",
                   letter="R")
        remotes = []
        if self.layer_internet.get():
            # as many as fit one above the other with their names
            fit = max(1, int((h - 70) // (26 * ui)))
            remotes = sorted(m.remote_hosts.values(),
                             key=lambda r: -r.bytes_total)[:min(8, fit)]
            if sel_key:
                remotes = [r for r in remotes if sel_key in r.devices] or \
                    remotes
        rx = cx + radius + max(90, (w - cx - radius) * 0.55)
        X, _ = self.P(rx, 0)
        # remote hosts share the height available (their title was drawn
        # above the top edge on a short window)
        sp = min(30 * ui, max(14 * ui, (h - 70) / max(1, len(remotes))))
        if remotes:
            ty = max(12, cy - (len(remotes) - 1) / 2 * sp - 34 * ui)
            it = self.c.create_text(X, self.P(0, ty)[1],
                                    text="INTERNET (outside your network)",
                                    fill=t["muted_fg"], tags=("deco",),
                                    font=("TkDefaultFont", 9,
                                          "bold"))
            if self.c.bbox(it):
                self._label_boxes = getattr(self, "_label_boxes", []) + [
                    self.c.bbox(it)]
        for i, r in enumerate(remotes):
            ry = cy + (i - (len(remotes) - 1) / 2) * sp
            hi = bool(sel_key and sel_key in r.devices)
            self._line(self.P(cx + radius, cy), self.P(rx, ry),
                       r.bytes_total if traffic else 0, dash=(2, 2), hi=hi)
            label = r.domain or r.ip
            self._node(rx, ry, 7 * ui, t["node_remote"], "remote", r.ip,
                       label, f"{r.ip} · "
                       f"{r.location_text() or 'location unknown'} · "
                       f"{_human_bytes(r.bytes_total)}")
        if not devs and not remotes:
            self.c.create_text(20, 20, anchor="nw", fill=t["muted_fg"],
                               text="Nothing to show yet — start watching "
                                    "and browse for a bit.")
        # the legend lives under the map now (it was drawn over the nodes)
        with contextlib.suppress(tk.TclError, AttributeError):
            self.legend_lbl.configure(fg=t["muted_fg"], bg=t["tab_bg"])

    def _fast_pan(self, dx, dy):
        """Pan by moving what is drawn (one Tcl call), not redrawing."""
        self.c.move("all", dx, dy)
        self.c.move("legend", -dx, -dy)
        self._schedule_full_redraw()

    def _fast_zoom(self, f, cx=None, cy=None):
        new = max(0.4, min(3.0, self.scale * f))
        f = new / self.scale
        if abs(f - 1) < 1e-6:
            return
        w, h = self.c.winfo_width(), self.c.winfo_height()
        cx = w / 2 if cx is None else cx
        cy = h / 2 if cy is None else cy
        self.c.scale("all", cx, cy, f, f)
        # keep P() in step with what is on screen
        self.ox = (self.ox + w / 2 - cx) * f + cx - w / 2
        self.oy = (self.oy + h / 2 - cy) * f + cy - h / 2
        self.scale = new
        self._schedule_full_redraw()

    def _schedule_full_redraw(self, ms=180):
        if getattr(self, "_redraw_job", None):
            with contextlib.suppress(tk.TclError):
                self.c.after_cancel(self._redraw_job)
        self._redraw_job = self.c.after(ms, lambda: self.redraw(force=True))

    def _key(self, e):
        k = e.keysym
        step = 40
        if k in ("Left", "Right", "Up", "Down"):
            dx = {"Left": step, "Right": -step}.get(k, 0)
            dy = {"Up": step, "Down": -step}.get(k, 0)
            self.ox += dx
            self.oy += dy
            self._fast_pan(dx, dy)
        elif k in ("plus", "equal", "KP_Add"):
            self._fast_zoom(1.25)
        elif k in ("minus", "KP_Subtract"):
            self._fast_zoom(0.8)
        elif k in ("0", "Home"):
            self.reset_view()
        elif k in ("Tab", "ISO_Left_Tab"):
            rows = getattr(self, "_list_rows", [])
            if rows:
                keys = [r[0] for r in rows]
                cur = self.selected[1] if self.selected and \
                    self.selected[0] == "device" else None
                i = keys.index(cur) if cur in keys else -1
                i = (i + (-1 if e.state & 1 or k == "ISO_Left_Tab" else 1)) \
                    % len(keys)
                self.selected = ("device", keys[i])
                r = rows[i]
                self.info_var.set(f"Selected: {r[1]} — {r[2]} · {r[3]} · "
                                  f"via {r[4]} (Enter for details)")
                self.redraw(force=True)
        elif k in ("Return", "KP_Enter"):
            if self.selected:
                self._open(*self.selected)
        else:
            return None
        return "break"

    def toggle_list(self):
        """The list twin: the same nodes as a table (screen readers,
        keyboard users, very big networks)."""
        if self.list_wrap.winfo_ismapped():
            self.list_wrap.pack_forget()
            self.c.pack(fill="both", expand=True, padx=10, pady=6)
            self.list_btn.configure(text="List view")
            self.redraw(force=True)
            return False
        self.c.pack_forget()
        self.list_wrap.pack(fill="both", expand=True, padx=10, pady=6)
        self.list_btn.configure(text="Map view")
        self.fill_list()
        return True

    def fill_list(self):
        if not getattr(self, "_list_rows", None):
            self.redraw(force=True)
        tv = self.list_tree
        tv.delete(*tv.get_children())
        for key, name, kind, addr, via, state, lvl in getattr(
                self, "_list_rows", []):
            tv.insert("", "end", iid="d:" + key,
                      values=(name, kind, addr, via, state, lvl))

    def _connections(self, w, h):
        t, m = self.t, self.model
        devs = self._devices()
        sel_dev = self.selected[1] if self.selected and \
            self.selected[0] == "device" else None
        devs = sorted(devs, key=lambda d: -(d.bytes_up + d.bytes_down))[:12]
        dkeys = {d.key for d in devs}
        focused = self.dev_var.get() != "All devices"
        sites = sorted(m.websites.values(), key=lambda s: -(s.bytes or
                                                            s.requests))
        remotes = sorted(m.remote_hosts.values(), key=lambda r:
                         -r.bytes_total)
        if focused or sel_dev:
            keyset = {sel_dev} if sel_dev else dkeys
            sites = [s for s in sites if s.devices & keyset]
            remotes = [r for r in remotes if r.devices & keyset]
        sites, remotes = sites[:14], remotes[:14]
        cols = (w * 0.14, w * 0.5, w * 0.86)
        for label, x in zip(("Devices", "Websites", "Remote hosts"), cols):
            X, Y = self.P(x, 16)
            self.c.create_text(X, Y, text=label, fill=t["muted_fg"],
                               font=("TkDefaultFont", 9, "bold"))

        def positions(items, keyfn):
            n = max(len(items), 1)
            step = (h - 50) / n
            return {keyfn(it): 40 + step * (i + 0.5)
                    for i, it in enumerate(items)}
        dy = positions(devs, lambda d: d.key)
        sy = positions(sites, lambda s: s.domain)
        ry = positions(remotes, lambda r: r.ip)
        for s in sites:
            for dk in s.devices:
                if dk in dy:
                    self._line(self.P(cols[0], dy[dk]),
                               self.P(cols[1], sy[s.domain]),
                               s.bytes or s.requests * 1000,
                               hi=(dk == sel_dev))
        for r in remotes:
            for dk in r.devices:
                if dk in dy:
                    self._line(self.P(cols[0], dy[dk]),
                               self.P(cols[2], ry[r.ip]), r.bytes_total,
                               dash=(3, 3), hi=(dk == sel_dev))
            for s in sites:
                if r.ip in s.resolved_ips:
                    self._line(self.P(cols[1], sy[s.domain]),
                               self.P(cols[2], ry[r.ip]), 0, dash=(1, 3))
        for d in devs:
            self._node(cols[0], dy[d.key], 9,
                       self._conf_color(d.confidence), "device", d.key,
                       self.app.device_label(d),
                       f"{d.ip or d.mac} · ↑{_human_bytes(d.bytes_up)}"
                       f" ↓{_human_bytes(d.bytes_down)}",
                       letter=d.confidence[:1])
        for s in sites:
            self._node(cols[1], sy[s.domain], 7, t["node_site"], "website",
                       s.domain, s.domain,
                       f"{s.requests} lookups/visits · "
                       f"{s.encryption_text()}")
        for r in remotes:
            self._node(cols[2], ry[r.ip], 7, t["node_remote"], "remote",
                       r.ip, r.domain or r.ip,
                       f"{r.ip} · {r.location_text() or 'location unknown'}")
        if not devs and not sites and not remotes:
            self.c.create_text(20, 40, anchor="nw", fill=t["muted_fg"],
                               text="Nothing to show yet — start watching "
                                    "and browse for a bit.")

    def reset(self):
        self.selected = None
        self._last_sig = None
        with contextlib.suppress(tk.TclError):
            self.c.delete("all")


# ---- Health ------------------------------------------------------------------
# When several things look wrong, the one most likely to explain the
# others comes first: a weak Wi-Fi signal causes loss, retransmissions,
# slow lookups and high latency, not the other way round.
CULPRIT_ORDER = ("link", "wifi", "gateway", "loss", "dhcp", "dupip",
                 "internet", "dns", "latency", "retrans", "resets",
                 "reconnects", "switch", "driver", "vpn")


def likely_culprit(results):
    rank = {"Needs attention": 2, "Degraded": 1}
    bad = [k for k in CULPRIT_ORDER if rank.get((results.get(k) or
                                                 ("",))[0], 0)]
    if not bad:
        return None
    top = max(rank[results[k][0]] for k in bad)
    for k in bad:                         # most severe, then most causal
        if rank[results[k][0]] == top:
            return k
    return bad[0]


class HealthTab(BaseTab):
    name, label_key = "health", "tab_health"
    CHECKS = (("overall", "Overall"), ("wifi", "Wi-Fi signal (this "
                                               "computer)"),
              ("gateway", "Router reachable"),
              ("internet", "Internet reachable"), ("dns", "Website lookups "
                                                         "(DNS)"),
              ("loss", "Packet loss (from checks)"),
              ("latency", "Internet round trip"),
              ("resets", "Connection resets"),
              ("retrans", "Re-sent data (retransmissions)"),
              ("dhcp", "Address assignment (DHCP)"),
              ("dupip", "Duplicate addresses"),
              ("reconnects", "Devices reconnecting"),
              ("link", "Network card"), ("switch", "Wired switch port"),
              ("driver", "Capture driver"),
              ("vpn", "VPN"))

    def build(self):
        outer = tk.Frame(self.frame, bg=WHITE, padx=14, pady=10)
        outer.pack(fill="both", expand=True)
        head = tk.Frame(outer, bg=WHITE)
        head.pack(fill="x")
        tk.Label(head, text="\U0001FA7A  Network health", bg=WHITE,
                 fg="#2b3a56", font=mw_font(14, "bold")).pack(
            side="left")
        self.run_btn = ttk.Button(head, text="Run checks now",
                                  command=self.app.run_health_checks)
        self.run_btn.pack(side="right")
        ttk.Button(head, text="\U0001F50E Why is it slow?",
                   command=lambda: self.app.investigate("slow")).pack(
            side="right", padx=6)
        # 5.1.2: the checks that are fine and not about the connection
        # itself fold away (folded in Beginner, open in Advanced)
        self.fold_btn = ttk.Button(head, text="", style="Sub.TButton",
                                   command=self.toggle_fold)
        self.fold_btn.pack(side="right")
        self._fold_sig = None
        self.note_var = DisplayVar()
        tk.Label(outer, textvariable=self.note_var, bg=WHITE, fg="#666666",
                 justify="left", anchor="w", wraplength=1100).pack(
            fill="x", pady=(2, 8))
        body = tk.Frame(outer, bg=WHITE)
        body.pack(fill="both", expand=True)
        # the right-hand panel keeps its width and scrolls on a short
        # screen; the checks take the rest (V5.0.2: on a 1024-pixel
        # window the panel squeezed the checks to one word per line and
        # its own text was cut off at the bottom)
        right_outer, right = make_scrollable(body, WHITE, fit_width=True)
        right_outer.pack(side="right", fill="y")
        right.configure(padx=12)
        left_outer, left = make_scrollable(body, WHITE)
        left_outer.pack(side="left", fill="both", expand=True)
        self.rows = {}
        for key, title in self.CHECKS:
            row = tk.Frame(left, bg="#f6f7fa", padx=10, pady=6,
                           highlightbackground="#e0e2e8",
                           highlightthickness=1)
            row.pack(fill="x", pady=2)
            st = tk.Label(row, text="?", bg="#f6f7fa", fg="#666666",
                          anchor="w", font=mw_font(10, "bold"))
            st.grid(row=0, column=0, sticky="nw")
            tl = tk.Label(row, text=title, bg="#f6f7fa", fg="#222222",
                          anchor="w", justify="left", wraplength=210,
                          font=mw_font(10, "bold"))
            tl.grid(row=0, column=1, sticky="nw", padx=(8, 8))
            ex = tk.Label(row, text="", bg="#f6f7fa", fg="#333333",
                          anchor="w", justify="left")
            ex.grid(row=0, column=2, sticky="new")
            row.columnconfigure(0, minsize=150)
            row.columnconfigure(1, minsize=200)
            row.columnconfigure(2, weight=1)
            row.bind("<Configure>", lambda e, r=row, lb=ex: self._fit_row(
                r, lb, e.width), add="+")
            self.rows[key] = (st, ex, row)
        tk.Label(right, text="Your connection", bg=WHITE, fg="#2b3a56",
                 font=mw_font(11, "bold")).pack(anchor="w")
        self.info_var = DisplayVar()
        tk.Label(right, textvariable=self.info_var, bg=WHITE, fg="#333333",
                 justify="left", anchor="w", wraplength=420,
                 font=("TkFixedFont", 9)).pack(
            anchor="w", pady=(2, 10))
        tk.Label(right, text="DNS servers seen", bg=WHITE, fg="#2b3a56",
                 font=mw_font(11, "bold")).pack(anchor="w")
        wrap, self.dns_tree = make_tree(
            right, [("srv", "Server", 120, "w", False),
                    ("q", "Queries", 65, "e", False),
                    ("lat", "Typical ms", 75, "e", False),
                    ("fail", "Failed", 55, "e", False),
                    ("nx", "Not found", 70, "e", False)])
        self.dns_tree.configure(height=4)
        wrap.pack(fill="x")
        self.dns_tree.bind("<<TreeviewSelect>>", lambda e: self._draw_hist())
        self.hist_title = tk.Label(right, text="Lookup times (all servers)",
                                   bg=WHITE, fg="#2b3a56",
                                   font=mw_font(11, "bold"))
        self.hist_title.pack(anchor="w", pady=(10, 0))
        self.hist = tk.Canvas(right, width=px(430), height=px(112), bg=WHITE,
                              highlightthickness=0)
        self.hist.pack(anchor="w")
        self.hist.bind("<Configure>", lambda e: self._draw_hist())
        # 5.1.2: when it got slow — the checks of the last hour
        tk.Label(right, text="Answer times (last hour)", bg=WHITE,
                 fg="#2b3a56", font=mw_font(11, "bold")).pack(
            anchor="w", pady=(10, 0))
        self.strip = tk.Canvas(right, width=px(430), height=px(120), bg=WHITE,
                               highlightthickness=0)
        self.strip.pack(anchor="w")
        self.strip.bind("<Configure>", lambda e: self._draw_strip(True))
        self._strip_sig = None

    def _fit_row(self, row, ex, width):
        """Wide: status | check | explanation on one line. Narrow: the
        explanation goes under them, full width."""
        narrow = width < 720
        try:
            if narrow:
                ex.grid_configure(row=1, column=0, columnspan=3,
                                  pady=(4, 0))
                want = max(200, width - 30)
            else:
                ex.grid_configure(row=0, column=2, columnspan=1, pady=0)
                want = max(200, width - 440)
            if abs(int(float(str(ex.cget("wraplength")) or 0)) - want) > 4:
                ex.configure(wraplength=want)
        except (tk.TclError, ValueError):
            pass

    def _draw_hist(self):
        c = self.hist
        t = self.t
        sel = self.dns_tree.selection()
        server = self.dns_tree.set(sel[0], "srv") if sel else None
        counts = self.model.dns.histogram(server)
        with contextlib.suppress(tk.TclError):
            self.hist_title.configure(
                text="Lookup times (" + (server or "all servers") + ")")
            c.configure(bg=t["tab_bg"])
            c.delete("all")
            w = max(300, c.winfo_width())
            h = int(c.cget("height"))
            n = len(counts)
            total = sum(counts)
            if not total:
                c.create_text(w // 2, h // 2, text="No timed lookups yet",
                              fill=t["muted_fg"])
                return
            top = max(counts)
            bw = (w - 20) / n
            base = h - 22
            # labels that would touch: show every second (or third) one
            fnt = Charts.font(c, ("TkDefaultFont", 7))
            widest = max(fnt.measure(x) for x in DNS_BUCKET_LABELS) + 6
            step = max(1, int(math.ceil(widest / max(1.0, bw))))
            slow = float(self.app.config.get("dns.slow_ms", 800))
            for i, v in enumerate(counts):
                x0 = 10 + i * bw + 3
                x1 = 10 + (i + 1) * bw - 3
                bh = 0 if not top else (base - 14) * v / top
                edge = DNS_BUCKETS[i - 1] if i else 0
                color = t["danger_fg"] if edge >= slow else \
                    t["warn_fg"] if edge >= 250 else t["accent"]
                if v:
                    c.create_rectangle(x0, base - bh, x1, base, fill=color,
                                       outline="")
                    c.create_text((x0 + x1) / 2, base - bh - 7,
                                  text=f"{v / total:.0%}", fill=t["text_fg"],
                                  font=("TkDefaultFont", 7))
                if i % step == 0:
                    c.create_text((x0 + x1) / 2, base + 9,
                                  text=DNS_BUCKET_LABELS[i],
                                  fill=t["muted_fg"],
                                  font=("TkDefaultFont", 7))
            c.create_text(w - 4, 2, text="ms", anchor="ne",
                          fill=t["muted_fg"], font=("TkDefaultFont", 7))
            Charts.record(c, (c.find_all() or (None,))[0],
                          self.hist_title.cget("text"),
                          ["ms", "Lookups"],
                          [[DNS_BUCKET_LABELS[i], v]
                           for i, v in enumerate(counts)])

    STRIP_S = 3600

    def strip_series(self):
        """Router and Internet answer times (ms) of the checks in the last
        hour, oldest first; a check that got no answer is left out (and
        counted)."""
        m = self.model
        now = time.time()
        rows = [r for r in m.health_history
                if now - (r.get("time") or 0) <= self.STRIP_S]
        gw = [float(r["gateway_ms"]) for r in rows
              if r.get("gateway_ok") and r.get("gateway_ms") is not None]
        inet = [float(r["internet_ms"]) for r in rows
                if r.get("internet_ok") and r.get("internet_ms")
                is not None]
        lost = sum(1 for r in rows if r.get("gateway_ok") is False or
                   r.get("internet_ok") is False)
        first = rows[0]["time"] if rows else None
        return gw, inet, lost, first

    def _draw_strip(self, force=False):
        c, t = self.strip, self.t
        gw, inet, lost, first = self.strip_series()
        try:
            w = max(300, c.winfo_width())
            h = int(c.cget("height"))
        except tk.TclError:
            return
        sig = (w, h, len(gw), len(inet), lost, self.app.theme_name)
        if not force and sig == self._strip_sig:
            return
        self._strip_sig = sig
        with contextlib.suppress(tk.TclError):
            c.configure(bg=t["tab_bg"])
            c.delete("all")
            empty = ("No checks in the last hour (they need live watching "
                     "with Active Scanning)" if not self.app
                     .health_checks_allowed() else "No checks yet")
            if not gw and not inet:
                # no grid and axis labels for nothing: the sentence alone
                c.create_text(w // 2, h // 2, text=translate_text(empty) + (
                    "\n" + translate_text("%d without an answer") % lost
                    if lost else ""), fill=t["muted_fg"], width=w - 24,
                    justify="center", font=("TkDefaultFont", 9))
                return
            Charts.line(c, 4, 2, w - 8, h - 4,
                        [("Router", gw, t["chart_a"]),
                         ("Internet", inet, t["chart_down"])], t,
                        title=(translate_text("%d without an answer") % lost
                               if lost else ""),
                        fmt=lambda v: f"{v:.0f} ms",
                        xlabels=(hm_clock(first) if first else "",
                                 translate_text("now")),
                        empty=translate_text(empty))

    CORE = ("overall", "wifi", "gateway", "internet", "dns", "loss",
            "latency")
    PROBLEM = ("Degraded", "Needs attention")

    def folded_keys(self, results):
        """The rows the fold hides: not a core check and not a problem."""
        if not self.app.fold_closed("health"):
            return set()
        return {k for k, _t in self.CHECKS
                if k not in self.CORE and
                (results.get(k) or ("Unknown", ""))[0] not in self.PROBLEM}

    def toggle_fold(self):
        self.app.set_fold("health", not self.app.fold_closed("health"))
        self.refresh()

    def _apply_fold(self, results):
        hidden = self.folded_keys(results)
        closed = self.app.fold_closed("health")
        sig = (frozenset(hidden), closed)
        if sig == self._fold_sig:
            return
        self._fold_sig = sig
        with contextlib.suppress(tk.TclError):
            for key, _t in self.CHECKS:
                self.rows[key][2].pack_forget()
            for key, _t in self.CHECKS:
                if key not in hidden:
                    self.rows[key][2].pack(fill="x", pady=2)
            self.fold_btn.configure(
                text=("\u25B8 " + translate_text("More detail") +
                      (f" ({len(hidden)})" if hidden else "")) if closed
                else ("\u25BE " + translate_text("Less detail")))

    STATUS_STYLE = {"Healthy": ("✔ Healthy", "good_fg"),
                    "Degraded": ("⚠ Degraded", "warn_fg"),
                    "Needs attention": ("✖ Needs attention",
                                        "danger_fg"),
                    "Unknown": ("? Unknown", "muted_fg"),
                    "Info": ("ℹ Info", "info_fg")}

    def refresh(self):
        if not self.is_visible():
            return
        app = self.app
        with contextlib.suppress(Exception):
            self._draw_strip()
        results = app.health_summary()
        self._apply_fold(results)
        for key, (status, text) in results.items():
            if key not in self.rows:
                continue
            st, ex, _row = self.rows[key]
            label, tok = self.STATUS_STYLE.get(status,
                                               self.STATUS_STYLE["Unknown"])
            with contextlib.suppress(tk.TclError):
                st.configure(text=label, fg=self.t[tok])
                ex.configure(text=text)
        self.note_var.set(app.health_note())
        self.info_var.set(app.connection_info_text())
        allowed = app.health_checks_allowed()
        with contextlib.suppress(tk.TclError):
            self.run_btn.state(["!disabled"] if allowed else ["disabled"])
        sel = self.dns_tree.selection()
        keep = self.dns_tree.set(sel[0], "srv") if sel else None
        self.dns_tree.delete(*self.dns_tree.get_children())
        for ip, q, resp, nx, fail, lat in self.model.dns.summary_rows()[:20]:
            iid = self.dns_tree.insert("", "end", values=(
                ip, q, f"{lat:.0f}" if lat is not None else "—",
                fail, nx))
            if ip == keep:
                self.dns_tree.selection_set(iid)
        culprit = getattr(app, "health_culprit", None)
        for key, (_st, _ex, row) in self.rows.items():
            with contextlib.suppress(tk.TclError):
                row.configure(highlightbackground=self.t["danger_fg"]
                              if key == culprit else self.t["border"],
                              highlightthickness=2 if key == culprit else 1)
        self._draw_hist()



# ---- Security check ----------------------------------------------------------
class SecurityTab(BaseTab):
    name, label_key = "security", "tab_security"

    def build(self):
        outer = tk.Frame(self.frame, bg=WHITE)
        outer.pack(fill="both", expand=True, padx=14, pady=12)
        tk.Label(outer, text="🔒  Security check", bg=WHITE, fg="#2b3a56",
                 font=mw_font(14, "bold")).pack(anchor="w")
        tk.Label(outer, text="Friendly explanations of what I've noticed. "
                             "Unusual is not the same as dangerous.",
                 bg=WHITE, fg="#666666").pack(anchor="w", pady=(0, 4))
        bar = tk.Frame(outer, bg=WHITE)
        bar.pack(fill="x", pady=(0, 8))
        self.upnp_btn = ttk.Button(
            bar, text="Check my router's port forwarding (UPnP)…",
            command=self.app.run_upnp_audit)
        self.upnp_btn.pack(side="left")
        ttk.Button(bar, text="What MiniWireshark sent…",
                   command=self.app.open_ledger).pack(side="left", padx=8)
        ttk.Button(bar, text="Privacy posture…",
                   command=self.app.open_privacy_posture).pack(side="left")
        # 5.1.2: sections with nothing to report fold to one line each
        # (folded in Beginner, open in Advanced)
        self.fold_btn = ttk.Button(bar, text="", style="Sub.TButton",
                                   command=self.toggle_fold)
        self.fold_btn.pack(side="right")
        self.folded_titles = []
        self.text = tk.Text(outer, wrap="word", bg="#fbfbfb", fg="#222222",
                            relief="flat", padx=14, pady=12,
                            font=mw_font(11), state="disabled",
                            highlightthickness=0)
        vs = ttk.Scrollbar(outer, orient="vertical", command=self.text.yview)
        self.text.configure(yscrollcommand=vs.set)
        self.text.pack(side="left", fill="both", expand=True)
        vs.pack(side="right", fill="y")
        self.text.tag_configure("h1", font=mw_font(12, "bold"),
                                foreground="#2b3a56", spacing1=10,
                                spacing3=4)
        self.text.tag_configure("good", foreground="#0b6b3a",
                                font=mw_font(11))
        self.text.tag_configure("warn", foreground="#a05608",
                                font=mw_font(11))
        self.text.tag_configure("bad", foreground="#a01a08",
                                font=mw_font(11))
        self.text.tag_configure("dim", foreground="#666666")
        self.text.tag_configure("body", foreground="#222222", spacing3=4)
        self.text.tag_configure("fold_h", foreground="#2b3a56",
                                font=mw_font(11, "bold"))

    def toggle_fold(self):
        self.app.set_fold("security", not self.app.fold_closed("security"))
        self.refresh()

    ALWAYS = ("What is this?", "The honest summary")

    def emit(self, secs):
        """Write the sections. Open: as built. Folded: the sections with
        something to look at first, in full; then the others one line
        each under "Nothing to report"."""
        t, tr = self.text, translate_text
        closed = self.app.fold_closed("security")

        def full(sec):
            title, lines, _w = sec
            if title:
                t.insert("end", tr(title) + "\n", "h1")
            for tag, text in lines:
                t.insert("end", translate_lines(text), tag)
        calm = [x for x in secs if not x[2] and x[0] not in self.ALWAYS]
        self.folded_titles = [x[0] for x in calm] if closed else []
        with contextlib.suppress(tk.TclError):
            self.fold_btn.configure(
                text=("\u25B8 " + tr("More detail") +
                      (f" ({len(calm)})" if calm else "")) if closed
                else ("\u25BE " + tr("Less detail")))
        if not closed:
            for sec in secs:
                full(sec)
            return
        tail = [x for x in secs if x[0] == "The honest summary"]
        for sec in secs:
            if sec[0] != "The honest summary" and sec not in calm:
                full(sec)
        if calm:
            t.insert("end", tr("Nothing to report") + "\n", "h1")
            for title, lines, _w in calm:
                first = next(((tag, text) for tag, text in lines
                              if tag in ("good", "dim")), None)
                t.insert("end", "    " + tr(title) + "  ", "fold_h")
                if first:
                    t.insert("end", tr(first[1].strip().lstrip("✔")
                                       .strip()) + "\n",
                             "good" if first[0] == "good" else "dim")
                else:
                    t.insert("end", "\n")
        for sec in tail:
            full(sec)

    def refresh(self):
        if self.is_visible():
            y = self.text.yview()[0]
            self.render()
            self.text.yview_moveto(y)

    def reset(self):
        self.refresh()


    def render(self):
        t = self.text
        m, app = self.model, self.app
        t.config(state="normal")
        t.delete("1.0", "end")

        secs = []          # [title, [(tag, text)], something to look at]
        cur = [None]

        def h1(s):
            cur[0] = [s, [], False]
            secs.append(cur[0])

        def add(tag, text, worry=False):
            if cur[0] is None:
                h1("")
            cur[0][1].append((tag, text))
            if worry:
                cur[0][2] = True
        def good(s): add("good", "✔  " + s + "\n")
        def warn(s): add("warn", "⚠  " + s + "\n", True)
        def bad(s): add("bad", "✘  " + s + "\n", True)
        guidance = app.config.get("general.beginner_explanations", True)
        def body(s):
            if guidance:
                add("body", "    " + s + "\n")
        def dim(s): add("dim", "    " + s + "\n")

        h1("What is this?")
        body("This page explains what I've seen on your network in plain "
             "English. Nothing leaves your computer — everything here is "
             "based on packets I've captured.")

        h1("Your gateway / router")
        if m.gateway_ip:
            good(f"Your router is at {m.gateway_ip}. All your internet "
                 f"traffic goes through it.")
            body("If you didn't recognize this number, someone may have "
                 "changed your Wi-Fi router. Your router's admin page is "
                 "usually at http://" + m.gateway_ip)
        else:
            warn("I couldn't detect your router yet. Start watching and "
                 "then open a website — I'll figure it out.")

        h1("Device identity checks (ARP)")
        gw_all = m.registry.gw_macs | m.registry.gw_candidates
        if m.gateway_ip and len(gw_all) > 1:
            bad(f"Your router's address has answered from "
                f"{len(gw_all)} different MAC addresses. "
                f"That can happen after a router reboot or firmware "
                f"update, but it's also the classic sign of ARP spoofing "
                f"— a device on your Wi-Fi pretending to be your router "
                f"so it can see your traffic.")
            body("If you didn't just restart your router, disconnect from "
                 "this Wi-Fi and check your router's admin page from a "
                 "device you trust.")
        elif m.gateway_ip:
            good("Your router's address has stayed consistent — no signs "
                 "of ARP spoofing so far.")
        else:
            dim("Watching for this once I know where your router is.")
        odd = {ip: macs for ip, macs in m.registry.ip_macs.items()
              if len(macs) > 1 and ip != m.gateway_ip}
        if odd:
            shown = list(odd.items())[:5]
            names = ", ".join(app.short_device_name_ip(ip) for ip, _ in shown)
            warn(f"{len(odd)} local address(es) have answered from more "
                 f"than one device: {names}.")
            body("This is usually harmless — phones and laptops often "
                 "rotate their Wi-Fi address for privacy, and a device "
                 "reconnecting can pick up the same IP as before. It's "
                 "only worth worrying about if it happens a lot, all at "
                 "once, right when something on your network starts "
                 "acting strangely.")

        h1("Who is handing out addresses (DHCP)?")
        if not m.dhcp_servers:
            dim("No DHCP activity seen yet.")
        elif len(m.dhcp_servers) > 1:
            servers = ", ".join(sorted(m.dhcp_servers))
            bad(f"{len(m.dhcp_servers)} different devices are handing "
                f"out IP addresses: {servers}.")
            body("Normally only your router does this. More than one "
                 "usually means either a second router plugged into the "
                 "network by mistake, or — less commonly — a rogue DHCP "
                 "server. If a device you don't recognize is on that "
                 "list, unplug it and check your network.")
        else:
            server_ip = next(iter(m.dhcp_servers))
            if server_ip == m.gateway_ip or not m.gateway_ip:
                good(f"Your router ({server_ip}) is the one handing out "
                     f"addresses. Normal setup.")
            else:
                warn(f"{server_ip} is handing out addresses, which isn't "
                     f"your router ({m.gateway_ip}).")
                body("Unusual, but not necessarily bad — some home setups "
                     "use a separate DHCP server on purpose.")

        h1("Who is doing your DNS lookups (finding website addresses)?")
        if not m.dns.servers:
            dim("No DNS traffic seen yet. Open a website and check again.")
        else:
            for server_ip, count in sorted({ip: s['queries'] for ip, s in m.dns.servers.items()}.items(),
                                           key=lambda x: -x[1])[:6]:
                if server_ip == m.gateway_ip:
                    good(f"Your router ({server_ip}) is handling DNS "
                         f"lookups. {count} queries so far.")
                    body("This is the normal setup at home: your router "
                         "looks up websites on your behalf. Whatever DNS "
                         "service your router uses (often your ISP's, "
                         "sometimes a custom one), that's what you get.")
                elif is_private_ip(server_ip):
                    warn(f"A local device at {server_ip} is acting as a "
                         f"DNS server ({count} queries).")
                    body("This is unusual unless you set up a Pi-hole, AdGuard "
                         "Home, or a similar DNS filter. If you didn't set "
                         "that up, someone might have added a device to your "
                         "Wi-Fi.")
                else:
                    known = KNOWN_DNS.get(server_ip, "")
                    if known:
                        warn(f"Someone is using {known} directly "
                             f"({server_ip}), {count} queries.")
                        body("This means a device on your Wi-Fi is bypassing "
                             "your router's DNS and asking a public DNS "
                             "provider directly. It usually means either: "
                             "(a) the device has a custom DNS setting, "
                             "or (b) your router itself was configured to "
                             "use this DNS service. On its own, this isn't "
                             "dangerous — it's a choice about privacy and "
                             "speed.")
                    else:
                        warn(f"Someone is using a custom DNS server at "
                             f"{server_ip} ({count} queries).")
                        body("I don't recognize this DNS server. It might be "
                             "your ISP, or a company VPN, or something "
                             "unusual. If you didn't set this up yourself, "
                             "it's worth checking your router's settings.")

        h1("Encrypted DNS (DoH) — the private option")
        if not app.config.get("dns.detect_encrypted_dns", True):
            dim("Encrypted-DNS detection is turned off in Settings.")
        elif m.doh_seen:
            for dev, hosts in m.doh_seen.items():
                who = app.short_device_name_ip(dev)
                for h in sorted(hosts):
                    good(f"{who} is using {h}.")
            body("Encrypted DNS (DoH) hides your website lookups even from "
                 "your router. It's good for privacy, but it also means "
                 "I can't see your browsing history. That's fine — I just "
                 "want you to know it's happening.")
        else:
            dim("No encrypted DNS detected so far. Website lookups are "
                "visible in plain text on your network.")

        h1("Unencrypted web traffic")
        if m.http_count:
            warn(f"I saw {m.http_count} unencrypted (http://) web "
                 f"requests.")
            body("These send the web page contents in plain text. Anyone on "
                 "the same Wi-Fi could read them. Modern sites use https:// "
                 "which is encrypted. If you see a lot of these, it might be "
                 "an old website or an app that needs updating.")
            hosts = [h for h, _n in m.http_hosts.most_common(6)]
            if hosts:
                body("Examples: " + ", ".join(hosts))
        else:
            good("No unencrypted web traffic seen so far.")

        h1("Other unencrypted protocols")
        others = {k: v for k, v in m.cleartext_seen.items() if k != "HTTP"}
        if others:
            warn("Seen: " + ", ".join(f"{k} ({v} "
                                      f"{translate_text('packets')})"
                                      for k, v in sorted(others.items())))
            body("Telnet, FTP, plain POP3/IMAP and similar protocols send "
                 "everything \u2014 sometimes including passwords \u2014 "
                 "without encryption. Prefer their secure versions.")
        else:
            good("No Telnet, FTP or other unencrypted logins seen.")

        h1("What I can and can't see")
        hidden = []
        if m.doh_seen or m.dns.encrypted_seen:
            hidden.append("some devices use encrypted DNS")
        quic = m.metrics.proto_bytes.get("QUIC", 0)
        if quic:
            hidden.append("QUIC connections hide the site name unless an "
                          "earlier lookup revealed it")
        if m.vpn.get("endpoint") or m.vpn.get("iface"):
            hidden.append("a VPN tunnel hides individual destinations")
        if hidden:
            warn("Visibility is reduced because " + "; ".join(
                translate_text(x) for x in hidden) + ".")
            body("That's privacy technology working as intended. "
                 "MiniWireshark never tries to decrypt anything; it reports "
                 "only what is visible.")
        else:
            good("Nothing is currently hiding website names from me.")
        body("For secure (https) sites I see only the site name \u2014 never "
             "the pages, searches or passwords.")

        h1("VPN")
        if m.vpn.get("iface"):
            warn(f"The selected network card looks like a VPN/tunnel "
                 f"adapter ({m.vpn['iface']}).")
            body("Traffic may be encrypted inside a VPN tunnel, so "
                 "MiniWireshark can see less about individual Internet "
                 "destinations.")
        if m.vpn.get("endpoint"):
            warn(f"Most Internet traffic goes to {m.vpn['endpoint']}, which "
                 f"looks like a {m.vpn.get('kind') or 'VPN'} server.")
            body("The VPN server is not counted as a website you visited.")
        if not (m.vpn.get("iface") or m.vpn.get("endpoint")):
            dim("No VPN detected.")

        if app.config.get("websites.tracker_classification", False):
            h1("Advertising & tracking domains (informational)")
            cats = Counter(w.category for w in m.websites.values()
                           if w.category and w.category not in ("CDN",
                                                                "Content"))
            if cats:
                body(", ".join(f"{c}: {n}" for c, n in cats.most_common()))
                body("Being on a tracker list doesn't make a domain "
                     "malicious \u2014 it describes what the service is "
                     "used for. Nothing is blocked.")
            else:
                dim("No listed tracker domains seen yet.")

        h1("Devices on your Wi-Fi")
        if not m.registry.by_key:
            dim("No local devices seen yet.")
        else:
            unknown = [d for d in m.registry.by_key.values()
                      if d.type == "unknown" and not d.vendor]
            if unknown:
                warn(f"{len(unknown)} device(s) couldn't be identified.")
                body("Their MAC addresses don't match any known manufacturer. "
                     "This is common for cheap IoT devices, phones with "
                     "privacy MAC randomization, and some virtual machines. "
                     "Check the Devices tab to see them.")
            else:
                good("Every device I've seen can be identified.")

        lst = app.listening_rows() if app.data_mode == "live" else []
        if app.data_mode == "live" and app.procmap.available:
            h1("This computer: programs that accept connections")
            net = [r for r in lst if r[2] == "the network"]
            if net:
                warn(f"{len(net)} program(s) on this computer can be reached "
                     f"from the network:")
                for proto, port, _scope, prog in net[:12]:
                    dim(f"{prog} — {proto} port {port}")
                body("Usually fine (file sharing, games, development tools). "
                     "New ones are reported on the timeline as they appear.")
            else:
                good("No program on this computer accepts connections from "
                     "the network.")
            if app.procmap.needs_admin:
                dim("Some programs couldn't be named without administrator "
                    "rights.")
        elif app.data_mode == "live":
            h1("This computer: programs that accept connections")
            dim("Needs the optional psutil component (Settings → Repair).")
        up = getattr(app, "upnp_result", None)
        h1("Router port forwarding (UPnP)")
        if up is None:
            dim("Not checked. Use “Check my router's port forwarding” above "
                "(Active Mode, on a network you trust). It asks your router "
                "only, and every request appears in the ledger.")
        elif up.get("error") and not up.get("mappings"):
            (good if up.get("upnp") is False else warn)(up["error"])
        else:
            maps = up.get("mappings") or []
            on = [x for x in maps if x.get("Enabled", "1") in ("1", "true")]
            if on:
                warn(f"Your router forwards {len(on)} port(s) from the "
                     f"Internet into your network:")
                for x in on[:20]:
                    dim(app.upnp_mapping_text(x))
                body("Each one lets the Internet reach a device here. Remove "
                     "the ones you don't recognise in the router's settings, "
                     "and turn UPnP off if you don't need it.")
            else:
                good("UPnP is on, but no ports are forwarded right now.")
            dim(f"Checked {fmt_clock(up.get('at', 0), True)}.")

        h1("The honest summary")
        if app.sniffer is None and app.data_mode == 'idle':
            dim("I'm not watching right now. Click “Start watching” and "
                "browse the web for a minute to get real results.")
        else:
            body(f"I've seen {m.count} packets, "
                 f"{len(m.registry.by_key)} device(s), "
                 f"and {len(m.websites)} website(s).")
        self.emit(secs)
        t.config(state="disabled")




# ---- Display filters (independent of the capture BPF filter) ----------------
# ---- V5 M8: field filter expressions -------------------------------------------
#  ip.src == 192.168.1.5 · tcp.port == 443 · dns.qry.name contains "example"
#  · smtp · expert.severity >= warning · frame.len > 1000, combined with
#  and / or / not and parentheses. A hand-written parser compiles to Python
#  closures: no eval, no user regex. Common fields read the packet row
#  directly; any other registry field dissects the packet once (cached).
FILTER_OPS = ("==", "!=", ">=", "<=", ">", "<", "contains")
_FTOK = re.compile(r'\s*(?:(\(|\)|==|!=|>=|<=|>|<|&&|\|\||!)|"((?:[^"\\]|'
                   r'\\.)*)"|([^\s()=!<>"&|]+))')
FILTER_PROTOCOLS = {
    "eth": ("eth",), "arp": ("arp",), "ip": ("ip",), "ipv6": ("ipv6",),
    "icmp": ("icmp",), "icmpv6": ("icmpv6",), "tcp": ("tcp",),
    "udp": ("udp",), "dns": ("dns",), "mdns": ("dns",), "dhcp": ("dhcp",),
    "tls": ("tls",), "quic": ("quic",), "http": ("http",),
    "ntp": ("ntp",), "vlan": ("vlan",)}
FILTER_PORT_PROTOS = {"smtp": {25, 465, 587}, "imap": {143, 993},
                      "pop3": {110, 995}, "ssh": {22}, "ftp": {21},
                      "telnet": {23}, "smb": {445, 139}, "rdp": {3389},
                      "mqtt": {1883, 8883}, "sip": {5060, 5061},
                      "rtsp": {554}, "ssdp": {1900}, "dot": {853}}
EXPERT_RANK = {"chat": 0, "note": 1, "warn": 2, "warning": 2, "error": 3}
SPECIAL_FIELDS = {
    "frame.number": "int", "ip.addr": "ipv4", "ipv6.addr": "ipv6",
    "tcp.port": "int", "udp.port": "int", "eth.addr": "mac",
    "expert.severity": "severity", "frame.time_relative": "float",
    "tcp.stream": "int", "expert.group": "str", "expert.message": "str"}
SPECIAL_DESC = {
    "frame.number": "Packet number",
    "ip.addr": "IPv4 address, either direction",
    "ipv6.addr": "IPv6 address, either direction",
    "tcp.port": "TCP port, either direction",
    "udp.port": "UDP port, either direction",
    "eth.addr": "MAC address, either direction",
    "expert.severity": "Worst expert finding on the packet (chat, note, "
                       "warning, error)",
    "expert.group": "Expert finding group (Sequence, Malformed, Protocol, "
                    "Security, Checksum, Response code)",
    "expert.message": "Expert finding text",
    "frame.time_relative": "Seconds since the first packet",
    "tcp.stream": "Connection number"}


def conversation_filter(src, dst, sport=None, dport=None, transport=None,
                        ipver=None, src_mac="", dst_mac=""):
    """The field expression for one conversation (both directions)."""
    parts = []
    fam = "ip" if ipver == 4 else "ipv6" if ipver == 6 else None
    if fam is None and src and dst:
        fam = "ipv6" if ":" in src else "ip" if "." in src else None
    if fam and src and dst:
        parts += [f"{fam}.addr == {src}", f"{fam}.addr == {dst}"]
    elif src_mac and dst_mac:
        parts += [f"eth.addr == {src_mac}", f"eth.addr == {dst_mac}"]
    tr = (transport or "").lower()
    if tr in ("tcp", "udp") and sport is not None and dport is not None:
        parts += [f"{tr}.port == {sport}", f"{tr}.port == {dport}"]
    return " and ".join(parts)


def address_filter(addr):
    """The field expression for one address (either direction)."""
    if not addr:
        return ""
    if re.match(r"^[0-9a-f]{2}([:-][0-9a-f]{2}){5}$", addr, re.I):
        return f"eth.addr == {addr}"
    return f"{'ipv6' if ':' in addr else 'ip'}.addr == {addr}"


def filter_quote(text):
    return '"' + str(text).replace("\\", " ").replace('"', '\\"') + '"'


def _row_field(d, key):
    """Fast values straight from the packet row (None = needs dissection).
    Always a list (a field can occur twice)."""
    if key in ("frame.len",):
        return [d.get("length")]
    if key == "frame.number":
        return [d.get("no")]
    if key in ("ip.src", "ip.dst", "ip.addr"):
        if d.get("ipver") != 4:
            return []
        return [d.get("src_ip")] if key == "ip.src" else \
            [d.get("dst_ip")] if key == "ip.dst" else \
            [d.get("src_ip"), d.get("dst_ip")]
    if key in ("ipv6.src", "ipv6.dst", "ipv6.addr"):
        if d.get("ipver") != 6:
            return []
        return [d.get("src_ip")] if key == "ipv6.src" else \
            [d.get("dst_ip")] if key == "ipv6.dst" else \
            [d.get("src_ip"), d.get("dst_ip")]
    tr = (d.get("transport") or "").lower()
    if key.startswith(("tcp.", "udp.")):
        proto = key.split(".", 1)[0]
        if key.endswith((".srcport", ".dstport", ".port")) and tr != proto:
            return []
        if key.endswith(".srcport"):
            return [d.get("sport")]
        if key.endswith(".dstport"):
            return [d.get("dport")]
        if key.endswith(".port"):
            return [d.get("sport"), d.get("dport")]
    if key == "tcp.stream":
        return [d.get("flow_id")] if d.get("flow_id") else []
    if key in ("eth.src", "eth.dst", "eth.addr"):
        if d.get("linktype", 1) != 1:
            return []
        return [d.get("src_mac")] if key == "eth.src" else \
            [d.get("dst_mac")] if key == "eth.dst" else \
            [d.get("src_mac"), d.get("dst_mac")]
    return None


class FieldFilter:
    """A compiled field expression: fn(row, ctx) → bool."""

    def __init__(self, text):
        self.text = text.strip()
        self.toks = []
        for m in _FTOK.finditer(self.text):
            if m.group(1):
                self.toks.append(("op", m.group(1)))
            elif m.group(2) is not None:
                self.toks.append(("str", m.group(2).replace('\\"', '"')))
            elif m.group(3):
                self.toks.append(("word", m.group(3)))
        rebuilt = "".join(m.group(0) for m in _FTOK.finditer(self.text))
        if rebuilt.strip().replace(" ", "") != self.text.replace(" ", ""):
            raise ValueError("Unexpected character in the filter.")
        self.i = 0
        if not self.toks:
            raise ValueError("The filter is empty.")
        self.fn = self._or()
        if self.i != len(self.toks):
            raise ValueError(f"Unexpected “{self.toks[self.i][1]}”.")
        self.needs_dissect = getattr(self, "_dissect", False)

    @staticmethod
    def looks_like(text):
        """True when the text uses the field syntax (not the friendly
        tokens such as site: and port:)."""
        if re.search(r"==|!=|>=|<=|&&|\|\||\bcontains\b|[()]", text):
            return True
        words = re.findall(r"[A-Za-z][\w.]*|\S", text)
        for w in words:
            if "." in w and (w.lower() in FIELD_REGISTRY or
                             w.lower() in SPECIAL_FIELDS):
                return True
        protos = set(FILTER_PROTOCOLS) | set(FILTER_PORT_PROTOS) | {
            "and", "or", "not", "!"}
        return bool(words) and all(w.lower() in protos for w in words) \
            and any(w.lower() not in ("and", "or", "not", "!")
                    for w in words)

    # ---- parser
    def _peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None,
                                                                 None)

    def _take(self):
        t = self._peek()
        self.i += 1
        return t

    def _or(self):
        parts = [self._and()]
        while self._peek()[1] in ("or", "||"):
            self._take()
            parts.append(self._and())
        if len(parts) == 1:
            return parts[0]
        return lambda d, c: any(p(d, c) for p in parts)

    def _and(self):
        parts = [self._not()]
        while self._peek()[1] in ("and", "&&"):
            self._take()
            parts.append(self._not())
        if len(parts) == 1:
            return parts[0]
        return lambda d, c: all(p(d, c) for p in parts)

    def _not(self):
        if self._peek()[1] in ("not", "!"):
            self._take()
            inner = self._not()
            return lambda d, c: not inner(d, c)
        return self._primary()

    def _primary(self):
        kind, val = self._take()
        if kind is None:
            raise ValueError("The filter ends too early.")
        if val == "(":
            inner = self._or()
            if self._take()[1] != ")":
                raise ValueError("A “(” is not closed.")
            return inner
        if kind != "word":
            raise ValueError(f"Expected a field name, found “{val}”.")
        field = val.lower()
        nxt = self._peek()
        if nxt[1] in FILTER_OPS or nxt[1] == "contains":
            op = self._take()[1]
            vk, value = self._take()
            if vk is None or value in ("(", ")"):
                raise ValueError(f"“{field} {op}” needs a value.")
            return self._compare(field, op, value)
        return self._exists(field)

    # ---- leaves
    def _check_field(self, field):
        if field in FIELD_REGISTRY or field in SPECIAL_FIELDS:
            return
        close = [k for k in FIELD_REGISTRY if k.startswith(field + ".")]
        raise ValueError(f"Unknown field “{field}”." + (
            f" Try {close[0]}." if close else
            " The Fields… button lists them all."))

    def _values(self, field):
        if field == "expert.severity":
            return lambda d, c: c.expert_severities(d)
        if field in ("expert.group", "expert.message"):
            i = 1 if field == "expert.group" else 2
            return lambda d, c: c.expert_info(d, i)
        if field == "frame.time_relative":
            return lambda d, c: [round(d["time"] - c.time_zero(), 6)] if \
                d.get("time") is not None else []
        fast = field in ("frame.len", "frame.number", "ip.src", "ip.dst",
                         "ip.addr", "ipv6.src", "ipv6.dst", "ipv6.addr",
                         "tcp.srcport", "tcp.dstport", "tcp.port",
                         "udp.srcport", "udp.dstport", "udp.port",
                         "eth.src", "eth.dst", "eth.addr", "tcp.stream")
        if fast:
            return lambda d, c: [v for v in _row_field(d, field)
                                 if v is not None]
        self._dissect = True
        return lambda d, c: c.dissection(d).values(field)

    def _exists(self, field):
        if field in FILTER_PROTOCOLS:
            keys = FILTER_PROTOCOLS[field]
            if field in ("tcp", "udp"):
                return lambda d, c: (d.get("transport") or "").lower() == \
                    field
            if field in ("arp",):
                return lambda d, c: d.get("tag") == "ARP" or \
                    d.get("proto") == "ARP"
            self._dissect = True
            return lambda d, c: any(n.key in keys for n in
                                    c.dissection(d).nodes) and (
                field != "mdns" or 5353 in (d.get("sport"), d.get("dport")))
        if field in FILTER_PORT_PROTOS:
            ports = FILTER_PORT_PROTOS[field]
            return lambda d, c: d.get("sport") in ports or \
                d.get("dport") in ports
        self._check_field(field)
        get = self._values(field)
        return lambda d, c: bool(get(d, c))

    def _compare(self, field, op, raw):
        self._check_field(field)
        get = self._values(field)
        ftype = SPECIAL_FIELDS.get(field) or FIELD_REGISTRY[field][0]
        if ftype == "severity":
            rank = EXPERT_RANK.get(raw.lower())
            if rank is None:
                raise ValueError("expert.severity is chat, note, warning or "
                                 "error.")
            want = rank
            conv = EXPERT_RANK.get
        elif op == "contains":
            want = raw.lower()
            return lambda d, c: any(want in str(v).lower()
                                    for v in get(d, c))
        elif ftype in ("int", "float", "hex"):
            try:
                want = int(raw, 0) if ftype != "float" else float(raw)
            except ValueError:
                raise ValueError(f"{field} needs a number, not “{raw}”.")
            conv = None
        elif ftype == "bool":
            want = raw.lower() in ("1", "true", "yes", "on")
            if raw.lower() not in ("1", "0", "true", "false", "yes", "no",
                                   "on", "off"):
                raise ValueError(f"{field} is yes or no.")
            conv = bool
        elif ftype in ("ipv4", "ipv6") and "/" in raw:
            try:
                net = ipaddress.ip_network(raw, strict=False)
            except ValueError:
                raise ValueError(f"“{raw}” is not an address range.")
            if op not in ("==", "!="):
                raise ValueError("Address ranges work with == and !=.")
            inside = lambda v: _in_net(v, net)
            if op == "==":
                return lambda d, c: any(inside(v) for v in get(d, c))
            return lambda d, c: not any(inside(v) for v in get(d, c))
        else:
            want = raw.lower()
            conv = lambda v: str(v).lower()
        cmp = {"==": lambda a: a == want, "!=": lambda a: a != want,
               ">": lambda a: a > want, "<": lambda a: a < want,
               ">=": lambda a: a >= want, "<=": lambda a: a <= want}[op]

        def test(d, c):
            vals = get(d, c)
            if not vals:
                return op == "!="
            for v in vals:
                try:
                    a = conv(v) if conv else v
                    if a is None:
                        continue
                    if op == "!=":
                        if not cmp(a):
                            return False
                    elif cmp(a):
                        return True
                except TypeError:
                    continue
            return op == "!="
        return test

    def match(self, d, ctx):
        return self.fn(d, ctx)


def _in_net(v, net):
    try:
        return ipaddress.ip_address(v) in net
    except (ValueError, TypeError):
        return False


# 5.1.2 M7: plain-word filter rows → DisplayFilter's own syntax (no new
# language: every expression it writes is one DisplayFilter accepts)
BUILDER_FIELDS = OrderedDict((
    ("Device", "device"), ("Website", "site"), ("Address", "ip"),
    ("Source", "src"), ("Destination", "dst"), ("Port", "port"),
    ("Protocol", "proto"), ("Direction", "dir"), ("Severity", "sev"),
    ("Length", "len"), ("Text", "text"), ("Connection", "stream"),
))
BUILDER_OPS = ("is", "is not", "greater than", "less than")
BUILDER_VALUES = {"dir": ("up", "down", "lan", "bcast", "other"),
                  "sev": ("info", "warning", "danger")}


def builder_term(field, op, value):
    """One row → one term, or raise ValueError."""
    key = BUILDER_FIELDS.get(field, field)
    value = str(value or "").strip()
    if not value:
        raise ValueError(f"“{field}” needs a value.")
    if key == "len" or op in ("greater than", "less than"):
        if key != "len":
            raise ValueError("Only Length can be greater or less than.")
        if not value.isdigit():
            raise ValueError("Length needs a number.")
        return ("len>" if op == "greater than" else
                "len<" if op == "less than" else "len>=") + value \
            if op != "is" else f"len>={value} len<={value}"
    v = value if re.match(r"^[^\s\"']+$", value) else \
        '"' + value.replace('"', "") + '"'
    term = f"{key}:{v}"
    return "-" + term if op == "is not" else term


def builder_expression(rows):
    """rows: [(join, field, op, value)] (join of the first row ignored:
    "and" / "or") → the expression text."""
    out = []
    for i, (join, fname, op, value) in enumerate(rows):
        term = builder_term(fname, op, value)
        if i:
            out.append("or" if join == "or" else "and")
        out.append(term)
    return " ".join(out)


def builder_rows(expr):
    """The expression as rows, or None when the builder can't show it
    (parentheses, field syntax, bare words): then it says “Edit as
    text” instead of guessing."""
    expr = (expr or "").strip()
    if not expr:
        return []
    if FieldFilter.looks_like(expr):
        return None
    try:
        toks = shlex.split(expr)
    except ValueError:
        return None
    names = {v: k for k, v in BUILDER_FIELDS.items()}
    rows, join, pending_len = [], "and", None
    for tok in toks:
        low = tok.lower()
        if low in ("and", "or"):
            join = low
            continue
        neg = tok.startswith("-") and len(tok) > 1
        body = tok[1:] if neg else tok
        m = re.match(r"^len\s*([<>])=?\s*(\d+)$", body.lower())
        if m and not neg:
            rows.append((join, "Length", "greater than" if m.group(1) == ">"
                         else "less than", m.group(2)))
            join = "and"
            continue
        if ":" not in body:
            return None
        f, v = body.split(":", 1)
        if f.lower() not in names or not v:
            return None
        rows.append((join, names[f.lower()], "is not" if neg else "is", v))
        join = "and"
    del pending_len
    return rows


class DisplayFilter:
    """A friendly display filter. GUI fields AND an optional text
    expression:  terms are ANDed, `or` separates alternatives, `-term` or
    `not term` negates. Fields: proto: ip: src: dst: port: sport: dport:
    site: device: dir: mac: stream: sev: len>N len<N, the word `marked`,
    or any bare word (searched everywhere). A bad expression raises
    ValueError at compile time and never affects capture."""

    FIELDS = {"proto", "ip", "src", "dst", "port", "sport", "dport", "site",
              "host", "domain", "device", "dir", "mac", "stream", "sev",
              "text"}

    def __init__(self, proto="All", device_key=None, site="", direction="Both",
                 port="", severity="Any", marked_only=False, expr=""):
        self.field = FieldFilter(expr) if expr and \
            FieldFilter.looks_like(expr) else None
        self.groups = [] if self.field else self.compile(expr)
        self.proto = proto
        self.device_key = device_key
        self.site = site.strip().lower()
        self.direction = direction
        self.port = None
        if str(port).strip():
            if not str(port).strip().isdigit():
                raise ValueError("Port must be a number, e.g. 443")
            self.port = int(port)
        self.severity = severity
        self.marked_only = marked_only
        self.expr = expr.strip()

    @classmethod
    def compile(cls, expr):
        expr = (expr or "").strip()
        if not expr:
            return []
        try:
            tokens = shlex.split(expr)
        except ValueError as e:
            raise ValueError(f"Check your quotes ({e}).")
        groups, cur, neg = [], [], False
        for tok in tokens:
            low = tok.lower()
            if low == "or":
                if not cur:
                    raise ValueError("“or” needs something on both "
                                     "sides.")
                groups.append(cur)
                cur = []
                continue
            if low == "and":
                continue
            if low == "not":
                neg = True
                continue
            if tok.startswith("-") and len(tok) > 1:
                neg, tok, low = True, tok[1:], low[1:]
            m = re.match(r"^len\s*([<>]=?)\s*(\d+)$", low)
            if m:
                cur.append((neg, "len", (m.group(1), int(m.group(2)))))
            elif ":" in tok and tok.split(":", 1)[0].lower() in cls.FIELDS:
                f, v = tok.split(":", 1)
                if not v:
                    raise ValueError(f"“{f}:” needs a value.")
                f = f.lower()
                if f in ("port", "sport", "dport", "stream") and \
                        not v.isdigit():
                    raise ValueError(f"“{f}:” needs a number.")
                if f == "dir" and v.lower() not in ("up", "down", "lan",
                                                    "bcast", "other"):
                    raise ValueError("dir: must be up, down, lan, bcast or "
                                     "other.")
                if f == "sev" and v.lower() not in ("info", "warning",
                                                    "danger"):
                    raise ValueError("sev: must be info, warning or "
                                     "danger.")
                cur.append((neg, f, v.lower()))
            elif ":" in tok:
                raise ValueError(f"Unknown field “{tok.split(':')[0]}”. "
                                 f"Try proto:, ip:, port:, site:, device:, "
                                 f"dir:, sev:.")
            else:
                cur.append((neg, "word", low))
            neg = False
        if cur:
            groups.append(cur)
        elif groups:
            raise ValueError("“or” needs something on both sides.")
        return groups

    def describe(self):
        bits = []
        if self.proto != "All":
            bits.append(f"protocol {self.proto}")
        if self.device_key:
            bits.append("one device")
        if self.site:
            bits.append(f"site “{self.site}”")
        if self.direction != "Both":
            bits.append(self.direction.lower())
        if self.port:
            bits.append(f"port {self.port}")
        if self.severity != "Any":
            bits.append(f"devices with {self.severity} alerts")
        if self.marked_only:
            bits.append("bookmarked")
        if self.expr:
            bits.append(f"“{self.expr}”")
        return ", ".join(bits) if bits else "showing everything"

    def active(self):
        return self.describe() != "showing everything"

    # ---- matching
    def match(self, d, ctx):
        if self.proto != "All" and d["tag"] != self.proto and \
                d["proto"] != self.proto:
            return False
        if self.device_key and self.device_key not in ctx.device_keys(d):
            return False
        if self.site and not any(self.site in n for n in ctx.names(d)):
            return False
        if self.direction != "Both":
            want = {"Upload": "up", "Download": "down",
                    "Local only": "lan"}.get(self.direction)
            if want and d.get("direction") != want:
                return False
        if self.port and self.port not in (d["sport"], d["dport"]):
            return False
        if self.severity != "Any" and not ctx.has_alert(
                d, "DANGER" if self.severity == "DANGER" else "WARNING"):
            return False
        if self.marked_only and not ctx.is_marked(d):
            return False
        if self.field is not None:
            return self.field.match(d, ctx)
        if not self.groups:
            return True
        return any(all(self._term(d, ctx, t) != t[0] for t in g)
                   for g in self.groups)

    @staticmethod
    def _term(d, ctx, term):
        _neg, f, v = term
        if f == "len":
            op, n = v
            L = d["length"]
            return {"<": L < n, "<=": L <= n, ">": L > n, ">=": L >= n}[op]
        if f == "proto":
            return v in (d["proto"].lower(), d["tag"].lower(),
                         (d["transport"] or "").lower())
        if f in ("ip", "src", "dst"):
            ips = {"ip": (d["src_ip"], d["dst_ip"]), "src": (d["src_ip"],),
                   "dst": (d["dst_ip"],)}[f]
            if "/" in v:
                try:
                    net = ipaddress.ip_network(v, strict=False)
                except ValueError:
                    return False
                return any(ip and ip_obj(ip) in net for ip in ips
                           if ip_obj(ip) and ip_obj(ip).version ==
                           net.version)
            return any(ip and (ip == v or (v.endswith(".") and
                                           ip.startswith(v))) for ip in ips)
        if f == "port":
            return int(v) in (d["sport"], d["dport"])
        if f == "sport":
            return int(v) == d["sport"]
        if f == "dport":
            return int(v) == d["dport"]
        if f in ("site", "host", "domain"):
            return any(v in n for n in ctx.names(d))
        if f == "device":
            return ctx.device_matches(d, v)
        if f == "dir":
            return d.get("direction") == v
        if f == "mac":
            return v in (d["src_mac"], d["dst_mac"])
        if f == "stream":
            return d.get("flow_id") == int(v)
        if f == "sev":
            return ctx.has_alert(d, v.upper())
        if f == "word" and v == "marked":
            return ctx.is_marked(d)
        hay = " ".join([d["src_ip"], d["dst_ip"], d["proto"], d["text"],
                        str(d["sport"] or ""), str(d["dport"] or ""),
                        d["src_mac"], d["dst_mac"]] +
                       list(ctx.names(d))).lower()
        return v in hay


class FilterContext:
    """What a display filter needs to know about the model."""

    SEV_RANK = {"INFO": 0, "WARNING": 1, "DANGER": 2}

    def __init__(self, app):
        self.app = app
        self._alert_cache = None
        self._dis = OrderedDict()
        self._sev = (None, {})

    def dissection(self, d):
        """The packet's field tree (cached for the last 5000 packets)."""
        key = (d.get("no"), id(d.get("raw")))
        got = self._dis.get(key)
        if got is None:
            got = dissect(d.get("raw") or b"", d.get("linktype", 1))
            self._dis[key] = got
            if len(self._dis) > 5000:
                self._dis.popitem(last=False)
        return got

    def _expert_index(self):
        store = self.app.deep.store
        ver, idx = self._sev
        if ver != store.version:
            idx = {}
            with store.lock:
                for f in store.findings:
                    idx.setdefault(f[0], []).append((f[2], f[3], f[4]))
            self._sev = (store.version, idx)
        return idx

    def expert_severities(self, d):
        return [x[0] for x in self._expert_index().get(d.get("no"), ())]

    def expert_info(self, d, i):
        """i = 0 severity, 1 group, 2 message."""
        return [x[i] for x in self._expert_index().get(d.get("no"), ())]

    def worst_expert(self, d):
        """'error', 'warn' or None — for row colours."""
        sev = self.expert_severities(d)
        if not sev:
            return None
        best = max(EXPERT_RANK.get(x, 0) for x in sev)
        return "error" if best >= 3 else "warn" if best == 2 else None

    def time_zero(self):
        """frame.time_relative counts from the first packet of the
        session (or the oldest one still in memory)."""
        t0 = getattr(self.app.model.metrics, "first_ts", 0) or 0
        rows = self.app.all_rows
        if rows and (not t0 or rows[0]["time"] < t0):
            t0 = rows[0]["time"]
        return t0

    def device_keys(self, d):
        m = self.app.model
        out = set()
        for ip, mac in ((d["src_ip"], d["src_mac"]),
                        (d["dst_ip"], d["dst_mac"])):
            dev = m.device_for(ip, mac if is_unicast_mac(mac) else None)
            if dev is not None:
                out.add(dev.key)
        return out

    def names(self, d):
        m = self.app.model
        out = [n.lower() for n in d["dns_names"]]
        if d["dns"] and d["dns"].get("qname"):
            out.append(d["dns"]["qname"].lower())
        f = m.flows.get(d.get("flow_id")) if d.get("flow_id") else None
        if f is not None and f.domain:
            out.append(f.domain)
        for ip in (d["src_ip"], d["dst_ip"]):
            n = m.cache.get(ip)
            if n:
                out.append(n.lower())
        return out

    def device_matches(self, d, v):
        reg = self.app.model.registry
        for key in self.device_keys(d):
            dev = reg.by_key.get(key)
            if dev is None:
                continue
            if v == "@mine" and dev.mine:
                return True
            if v == "@mine-phone" and dev.mine and dev.device_class in (
                    "iPhone", "Android phone", "Tablet"):
                return True
            hay = " ".join([dev.display_name(), dev.alias, dev.ip, dev.mac,
                            dev.device_class]).lower()
            if not v.startswith("@") and v in hay:
                return True
        return False

    def has_alert(self, d, sev):
        if self._alert_cache is None:
            c = defaultdict(int)
            am = self.app.model.alerts
            for aid in am.order:
                a = am.alerts.get(aid)
                if a and not a.acknowledged:
                    c[a.device_key] = max(c[a.device_key],
                                          self.SEV_RANK.get(a.severity, 0))
                    for ip in (a.device_key.replace("ip:", ""),):
                        c[ip] = max(c[ip], self.SEV_RANK.get(a.severity, 0))
            self._alert_cache = c
        need = self.SEV_RANK.get(sev, 1)
        keys = self.device_keys(d) | {d["src_ip"], d["dst_ip"]}
        return any(self._alert_cache.get(k, -1) >= need for k in keys)

    def is_marked(self, d):
        return d.get("no") in self.app.bookmarks


# ---- Packets (Advanced) -------------------------------------------------------
TIME_FORMATS = ("Time of day", "Seconds since start",
                "Since previous shown")
EXPERT_ROW_COLORS = {"x_error": ("#8a1a08", "#fbe9e7"),
                     "x_warn": ("#7a4a00", "#fff4e0")}


def format_packet_time(ts, fmt, t0=0.0, prev=None):
    """Time column: clock time, seconds since the first packet, or the
    gap since the previous packet in the list (like Wireshark's View →
    Time Display Format)."""
    if fmt == "Seconds since start":
        return f"{max(0.0, ts - (t0 or ts)):.6f}"
    if fmt == "Since previous shown":
        return f"{max(0.0, ts - prev):.6f}" if prev is not None else \
            "0.000000"
    return datetime.fromtimestamp(ts).strftime("%H:%M:%S.%f")[:-3]


class PacketsTab(BaseTab):
    name, label_key, advanced = "packets", "tab_raw", True
    VIEW_VARS = ("expr_var", "site_var")

    def apply_filters(self):
        self.apply()
    SUBVIEWS = ("Packets", "Streams", "Exchanges", "Statistics", "Expert")

    def build(self):
        outer = self.frame
        views = self.make_subviews(list(self.SUBVIEWS),
                                   on_switch=self._on_subview)
        self.frame = views["Packets"]
        try:
            self._build_packets()
        finally:
            self.frame = outer
        self.streams = StreamsView(self.app, views["Streams"])
        self.exchanges = ExchangesView(self.app, views["Exchanges"])
        self.stats = StatisticsView(self.app, views["Statistics"])
        self.expert = ExpertView(self.app, views["Expert"])

    def _sub(self):
        return {"Streams": self.streams, "Exchanges": self.exchanges,
                "Statistics": self.stats,
                "Expert": self.expert}.get(self.subview)

    def _on_subview(self, name):
        v = self._sub()
        if v is not None:
            v.refresh(force=True)
        elif self._dirty:
            self.rebuild()

