def gloss_mark(txt, app, start="1.0"):
    """Underline the first use of each glossary word in a Text; a click
    shows a short note with More in Help."""
    t = app.theme
    try:
        txt.tag_configure("gloss", underline=True)
        with contextlib.suppress(tk.TclError):
            txt.tag_configure("gloss", underlinefg=t["muted_fg"])
    except tk.TclError:
        return 0
    n = 0
    for word, title in GLOSS_TERMS.items():
        tag = "gl_" + word
        with contextlib.suppress(tk.TclError):
            txt.tag_remove(tag, "1.0", "end")
            idx = txt.search(r"\m" + word + r"\M", start, "end",
                             regexp=True)
            if not idx:
                continue
            end = f"{idx}+{len(word)}c"
            txt.tag_add("gloss", idx, end)
            txt.tag_add(tag, idx, end)
            if not getattr(txt, "_mw_gloss_bound", None) or \
                    tag not in txt._mw_gloss_bound:
                txt.tag_bind(tag, "<Button-1>", lambda e, tt=title:
                             app.gloss_note(txt, tt, e))
                txt.tag_bind(tag, "<Enter>",
                             lambda e: txt.configure(cursor="hand2"))
                txt.tag_bind(tag, "<Leave>",
                             lambda e: txt.configure(cursor=""))
                bound = getattr(txt, "_mw_gloss_bound", None) or set()
                bound.add(tag)
                txt._mw_gloss_bound = bound
            n += 1
    return n


class HelpTab(BaseTab):
    name, label_key = "help", "tab_about"

    def build(self):
        outer = tk.Frame(self.frame, bg=WHITE)
        outer.pack(fill="both", expand=True, padx=14, pady=12)
        head = tk.Frame(outer, bg=WHITE)
        head.pack(fill="x")
        tk.Label(head, text=f"❓  Help / About — MiniWireshark "
                            f"{SCRIPT_VERSION}", bg=WHITE, fg="#2b3a56",
                 font=mw_font(14, "bold")).pack(side="left")
        bar = tk.Frame(outer, bg=WHITE)
        bar.pack(fill="x", pady=(8, 8))
        self.demo_btn = ttk.Button(bar, text="\U0001F3AE Try Demo Mode",
                                   command=self.app.toggle_demo)
        self.demo_btn.pack(side="left")
        Tooltip(self.demo_btn, "Explore every tab with simulated, clearly "
                               "labelled sample data. No real capture "
                               "happens and nothing mixes with your real "
                               "session.")
        ttk.Button(bar, text="\U0001F6E0 Diagnostics",
                   command=self.app.open_diagnostics).pack(side="left",
                                                           padx=6)
        ttk.Button(bar, text="Run self-test",
                   command=self.app.run_self_test_window).pack(side="left")
        ttk.Button(bar, text="Open data folder",
                   command=lambda: _open_path(PATHS.data)).pack(side="left",
                                                                padx=6)
        ttk.Button(bar, text="Open logs",
                   command=lambda: _open_path(PATHS.logs)).pack(side="left")
        body = tk.Frame(outer, bg=WHITE)
        body.pack(fill="both", expand=True)
        left = tk.Frame(body, bg=WHITE, width=262)
        left.pack(side="left", fill="y")
        left.pack_propagate(False)
        tk.Label(left, text="Search help", bg=WHITE, fg="#666666",
                 anchor="w").pack(fill="x")
        self.q_var = tk.StringVar()
        qe = ttk.Entry(left, textvariable=self.q_var)
        qe.pack(fill="x", pady=(2, 6))
        self.filter_entry = qe
        soon = debounce(qe, self.refill, 150)
        qe.bind("<KeyRelease>", lambda e: soon())
        qe.bind("<Return>", lambda e: self._open_first())
        lw = tk.Frame(left, bg=WHITE)
        lw.pack(fill="both", expand=True)
        self.lb = tk.Listbox(lw, activestyle="none", highlightthickness=0,
                             relief="flat", exportselection=False,
                             bg="#f6f7fa", fg="#222222",
                             selectbackground="#0b5394",
                             selectforeground="#ffffff")
        lvs = ttk.Scrollbar(lw, orient="vertical", command=self.lb.yview)
        self.lb.configure(yscrollcommand=lvs.set)
        self.lb.pack(side="left", fill="both", expand=True)
        lvs.pack(side="right", fill="y")
        self.lb.bind("<<ListboxSelect>>", self._picked)
        right = tk.Frame(body, bg=WHITE)
        right.pack(side="left", fill="both", expand=True, padx=(10, 0))
        txt = tk.Text(right, wrap="word", bg="#fbfbfb", fg="#222222",
                      relief="flat", padx=14, pady=12, cursor="arrow",
                      font=mw_font(10), highlightthickness=0)
        vs = ttk.Scrollbar(right, orient="vertical", command=txt.yview)
        txt.configure(yscrollcommand=vs.set)
        txt.pack(side="left", fill="both", expand=True)
        vs.pack(side="right", fill="y")
        txt.tag_configure("h", font=mw_font(12, "bold"),
                          foreground="#2b3a56", spacing1=8, spacing3=3)
        txt.tag_configure("h1", font=mw_font(14, "bold"),
                          foreground="#2b3a56", spacing3=6)
        txt.tag_configure("show", foreground="#0b5394", underline=True,
                          spacing1=4)
        txt.tag_configure("muted", foreground="#666666")
        self.txt = txt
        self.rows = []              # listbox row -> topic or None
        self.topic = None
        self._links = 0
        self.refill()
        self.open_topic("Start here")

    # ---- the list
    def refill(self):
        q = self.q_var.get().strip()
        topics = help_topics()
        self.lb.delete(0, "end")
        self.rows = []
        if q:
            by = {tp["title"]: tp for tp in topics}
            hits = [by[t] for t in self.app.help_matches(q)]
            for tp in hits:
                self.lb.insert("end", "  " + translate_text(tp["title"]))
                self.rows.append(tp)
            if not hits:
                self.lb.insert("end", translate_text("No topic matches."))
                self.lb.itemconfigure(0, foreground="#888888")
                self.rows.append(None)
            return
        group = None
        for tp in topics:
            if tp["group"] != group:
                group = tp["group"]
                self.lb.insert("end", translate_text(group).upper())
                self.lb.itemconfigure("end", foreground="#888888")
                self.rows.append(None)
            self.lb.insert("end", "  " + translate_text(tp["title"]))
            self.rows.append(tp)
        self._mark_current()

    def shown_titles(self):
        return [tp["title"] for tp in self.rows if tp]

    def _mark_current(self):
        for i, tp in enumerate(self.rows):
            if tp is not None and tp is self.topic:
                with contextlib.suppress(tk.TclError):
                    self.lb.selection_clear(0, "end")
                    self.lb.selection_set(i)
                    self.lb.see(i)
                return

    def _picked(self, _e=None):
        sel = self.lb.curselection()
        if not sel:
            return
        tp = self.rows[sel[0]] if sel[0] < len(self.rows) else None
        if tp is None:
            self._mark_current()
            return
        self.open_topic(tp["title"])

    def _open_first(self):
        for tp in self.rows:
            if tp:
                self.open_topic(tp["title"])
                break
        return "break"

    # ---- the topic
    def open_topic(self, title):
        tp = next((x for x in help_topics() if x["title"] == title), None)
        if tp is None:
            return False
        self.topic = tp
        self._topic_locale = CURRENT_LOCALE
        txt = self.txt
        txt.config(state="normal")
        txt.delete("1.0", "end")
        for tag in txt.tag_names():
            if tag.startswith("lk_"):
                txt.tag_delete(tag)
        txt.insert("end", translate_text(tp["title"]) + "\n", ("h1",))
        txt.insert("end", translate_lines(help_body(tp, self.app)) + "\n")
        for label, tab, attr in tp["show"]:
            self._links += 1
            tag = f"lk_{self._links}"
            word = "Take the tour" if tab == "tour" else "Show me"
            txt.insert("end", f"\n\u25B6 {translate_text(word)}: "
                              f"{translate_text(label)}", ("show", tag))
            txt.tag_bind(tag, "<Button-1>", lambda e, tb=tab, at=attr:
                         self.app.show_me(tb, at))
            txt.tag_bind(tag, "<Enter>",
                         lambda e: txt.configure(cursor="hand2"))
            txt.tag_bind(tag, "<Leave>",
                         lambda e: txt.configure(cursor="arrow"))
        gloss_mark(txt, self.app, "2.0")
        txt.config(state="disabled")
        self._mark_current()
        return True

    def refresh(self):
        with contextlib.suppress(tk.TclError):
            self.demo_btn.configure(
                text="⏹ Stop Demo Mode" if self.app.data_mode == "demo"
                else "\U0001F3AE Try Demo Mode")
        # the topic was written in the language of the moment: again in
        # the new one after a language change (and the list with it)
        if getattr(self, "_topic_locale", CURRENT_LOCALE) != CURRENT_LOCALE \
                and getattr(self, "topic", None):
            with contextlib.suppress(tk.TclError):
                self.refill()
                self.open_topic(self.topic["title"])



# ============================================================================
#  18c.  Background jobs — slow work that must not freeze the window
#
#  One "jobs" thread runs them in order. A job never touches Tk; when it
#  needs the model it takes the GuiGate for one short piece at a time and
#  gives the window its turn in between (GuiGate.yield_to_tk). Its result
#  comes back to the Tk thread through the app's _async_results queue.
# ============================================================================
class JobCancelled(Exception):
    """Raised inside a job's run() when the user cancelled it."""


class Job:
    def __init__(self, kind, title, run, done=None, failed=None):
        self.kind, self.title = kind, title
        self.run, self.done, self.failed = run, done, failed
        self.cancelled = False
        self.frac = None              # 0..1 or None (unknown)
        self.started = time.monotonic()

    def progress(self, frac=None):
        self.frac = frac
        if self.cancelled:
            raise JobCancelled()

    def pieces_under_gate(self, gate, pieces, total=None):
        """Take items from the iterator `pieces`, each one while holding
        the gate, giving the window its turn between them. -> list."""
        out = []
        it = iter(pieces)
        while True:
            with gate:
                try:
                    out.append(next(it))
                except StopIteration:
                    break
                seen = gate.tk_entries
            gate.yield_to_tk(seen)
            if total:
                self.progress(min(0.95, len(out) / total))
            elif self.cancelled:
                raise JobCancelled()
        return out


class JobRunner:
    """At most one job of each kind; a second request says it is already
    running. busy() is what tests and the benchmark wait on."""

    def __init__(self, app):
        self.app = app
        self.q = queue.Queue()
        self.active = OrderedDict()     # kind -> Job (queued or running)
        self.thread = threading.Thread(target=self._loop, daemon=True,
                                       name="jobs")
        self.thread.start()

    # jobs whose garbage is plain text, lists and dicts (freed without the
    # cycle collector): it is paused while they run. Its full pass over the
    # session being saved or the JSON just read took 90-130 ms holding the
    # GIL, a freeze of the window, and found nothing such a job made.
    NO_GC = ("session_save", "journal", "pcap_save", "session_load",
             "table_export")

    def submit(self, kind, title, run, done=None, failed=None):
        if kind in self.active:
            with contextlib.suppress(Exception):
                self.app._set_banner(f"{translate_text(title)} — "
                                     f"{translate_text('already running.')}")
            return None
        job = Job(kind, title, run, done, failed)
        self.active[kind] = job
        self.q.put(job)
        self._changed()
        return job

    def busy(self):
        return bool(self.active)

    def cancel_all(self):
        for job in self.active.values():
            job.cancelled = True

    def stop(self, finish=(), wait=0.0):
        """Cancel the jobs and end the jobs thread. Kinds in `finish` (a
        save the user asked for) may complete first, for up to `wait`
        seconds (5.2.3, B-04: closing used to cancel a session save that
        was under way)."""
        keep = False
        for job in self.active.values():
            if job.kind in finish:
                keep = True
            else:
                job.cancelled = True
        self.q.put(None)
        if keep and wait:
            self.thread.join(wait)

    def _changed(self):
        fn = getattr(self.app, "_show_jobs", None)
        if fn is not None:
            with contextlib.suppress(Exception):
                fn()

    def _loop(self):
        while True:
            job = self.q.get()
            if job is None:
                return
            paused = job.kind in self.NO_GC and gc.isenabled()
            if paused:
                gc.disable()
            fast_switch("jobs", True)
            try:
                if job.cancelled:
                    raise JobCancelled()
                res, ok = job.run(job), True
            except JobCancelled as e:
                res, ok = e, False
            except Exception as e:                   # noqa: BLE001
                LOG.exception("background job %s", job.kind)
                res, ok = e, False
            finally:
                fast_switch("jobs", False)
                if paused:
                    gc.enable()
            self.app._async_results.put(
                lambda job=job, ok=ok, res=res: self._finish(job, ok, res))

    def _finish(self, job, ok, res):
        """On the Tk thread."""
        self.active.pop(job.kind, None)
        try:
            if ok and job.done is not None:
                job.done(res)
            elif not ok and job.failed is not None:
                job.failed(res)
        finally:
            self._changed()


