def _folder_size(path):
    total = 0
    if not path or not os.path.exists(path):
        return 0
    if os.path.isfile(path):
        return os.path.getsize(path)
    for root, _dirs, files in os.walk(path):
        for f in files:
            with contextlib.suppress(OSError):
                total += os.path.getsize(os.path.join(root, f))
    return total


def privacy_posture(model, mail_sessions=()):
    """Devices that used protocols anyone on the path could read. Never a
    verdict: plaintext is common on home gear, and encryption is not a
    sign of anything bad either."""
    plain = {80: "web pages (HTTP)", 21: "file transfer (FTP)",
             23: "remote terminal (Telnet)", 110: "mail download (POP3)",
             143: "mail (IMAP)", 25: "mail sending (SMTP)",
             1883: "smart-home messages (MQTT)", 554: "video streams (RTSP)",
             5060: "internet calls (SIP)", 69: "file transfer (TFTP)"}
    out = defaultdict(lambda: defaultdict(int))
    for f in model.flows.all_flows():
        if f.device_key and f.remote_port in plain and \
                f.encrypted != "yes":
            out[f.device_key][plain[f.remote_port]] += 1
    for s in mail_sessions:
        if s.get("auth_before_tls"):
            dev = model.device_for(s.get("client", ""), None)
            if dev is not None:
                out[dev.key][f"{s.get('proto')} login before "
                             f"encryption"] += 1
    return {k: dict(v) for k, v in out.items()}


def dns_resolver_stats(txns):
    """Per resolver: lookups, answers, latency median / 95th percentile,
    failures and retries (from matched DNS pairs only)."""
    by = defaultdict(list)
    for t in txns:
        if t.get("kind") == "dns":
            by[t.get("server", "?")].append(t)
    out = []
    for srv, ts in by.items():
        lat = sorted(t["latency_ms"] for t in ts
                     if isinstance(t.get("latency_ms"), (int, float)))
        q = lambda p: lat[min(len(lat) - 1, int(p * len(lat)))] if lat \
            else None
        out.append({"server": srv, "lookups": len(ts),
                    "answered": len(lat),
                    "median_ms": q(0.5), "p95_ms": q(0.95),
                    "failures": sum(1 for t in ts if t.get("rcode")),
                    "no_answer": sum(1 for t in ts
                                     if t.get("result") == "no answer"),
                    "retries": sum(max(0, (t.get("tries") or 1) - 1)
                                   for t in ts)})
    return sorted(out, key=lambda r: -r["lookups"])


def calibrate(seconds=1.5):
    """A short synthetic replay through the real decode and model path
    (no network traffic). → packets per second on this computer."""
    frames = ScenarioBuilder().busy_mix(4000)
    tmp = tempfile.mkdtemp(prefix="mw_cal_")
    try:
        cfg = AppConfig(path=os.path.join(tmp, "cal.json"))
        m = NetworkModel(cfg, *scenario_identity()[:3])
        m.set_identity(local_nets=scenario_identity()[3])
        m.use_packet_clock = True
        reasm = TlsReassembler()
        n = 0
        t0 = time.perf_counter()
        while time.perf_counter() - t0 < seconds:
            for raw, ts, lt in frames[:1000]:
                d = fast_decode(raw, ts, lt, reasm)
                m.ingest(d)
                n += 1
        return n / max(1e-6, time.perf_counter() - t0)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def store_calibration(cfg, pps):
    """Keep a speed measurement in the settings (and size Full Power from
    the cores when that is still the default)."""
    if not pps:
        return False
    cores = os.cpu_count() or 1
    cfg.set("performance.calibration", {
        "pps": round(pps), "when": time.time(), "cores": cores})
    if cfg.get("performance.full_power_cores", 2) == 2:
        cfg.set("performance.full_power_cores", max(1, min(4, cores - 1)))
    cfg.save()
    LOG.info("calibration: %.0f packets/s on %d cores", pps, cores)
    return True


def needs_calibration(cfg):
    """No speed measurement yet, or one made with another number of cores
    (a new computer, or the data folder copied over)."""
    cal = cfg.get("performance.calibration", {}) or {}
    if not isinstance(cal, dict) or not cal.get("pps"):
        return True
    return bool(cal.get("cores")) and cal.get("cores") != (os.cpu_count()
                                                           or 1)


class CrashDialog:
    _open = False

    @classmethod
    def show(cls, app, text):
        with contextlib.suppress(OSError):
            atomic_write_text(PATHS.crash_marker, text)
        if cls._open:
            return
        cls._open = True
        try:
            path = app.autosave("crash")
        except Exception:                            # noqa: BLE001
            LOG.exception("autosave after a crash")
            path = None
        t = app.theme
        win = tk.Toplevel(app.root)
        win.title("Something went wrong")
        win.geometry(px_geo("620x420"))
        win.configure(bg=t["tab_bg"])
        tk.Label(win, text="\U0001F915  MiniWireshark hit an unexpected problem",
                 bg=t["tab_bg"], fg=t["text_fg"],
                 font=mw_font(13, "bold")).pack(anchor="w",
                                                          padx=14, pady=(12, 2))
        tk.Label(win, text="It's usually safe to keep going. The details "
                           "below are also in the log file." +
                           (f" Your session was saved to {path}." if path
                            else ""),
                 bg=t["tab_bg"], fg=t["muted_fg"], wraplength=580,
                 justify="left").pack(anchor="w", padx=14)
        txt = tk.Text(win, height=12, bg=t["text_bg"], fg=t["text_fg"],
                      font=app.mono, relief="flat", highlightthickness=0)
        txt.insert("1.0", text[-4000:])
        txt.config(state="disabled")
        txt.pack(fill="both", expand=True, padx=14, pady=8)
        bar = tk.Frame(win, bg=t["tab_bg"])
        bar.pack(fill="x", padx=14, pady=(0, 12))

        def close():
            cls._open = False
            win.destroy()

        def restart():
            # 5.2.3 (B-37): close first (session, journal and history are
            # released), then start the new copy as the same user; it was
            # started first, marked "elevated", while this one still held
            # the journal
            LOG.info("restart requested from crash dialog")
            args = self_cmd(*[
                a for a in sys.argv[1:]
                if a not in (SELF_TEST_FLAG, ELEVATED_FLAG)])
            cls._open = False
            app._on_close()
            try:
                _popen_hidden(args)
            except OSError as e:
                LOG.error("restart failed: %s", e)
        ttk.Button(bar, text="Continue", style="Accent.TButton",
                   command=close).pack(side="right")
        ttk.Button(bar, text="Restart MiniWireshark",
                   command=restart).pack(side="right", padx=6)
        ttk.Button(bar, text="Open log",
                   command=lambda: _open_path(PATHS.logs)).pack(side="left")
        ttk.Button(bar, text="Copy error", command=lambda: copy_to_clipboard(
            app, text)).pack(side="left", padx=6)
        win.protocol("WM_DELETE_WINDOW", close)


# ============================================================================
#  21b.  Signed updates and data packs (Ed25519)
#
#  An update is installed only when its manifest is signed by one of the
#  release keys below, its SHA-256 and size match, and it is newer than
#  this version (no downgrades). With no release key configured, updates
#  are check-only: you are told a new version exists, nothing is installed.
#  Verification uses `cryptography` when present, else a small pure-Python
#  Ed25519 (RFC 8032), checked against the RFC's own test vectors.
# ============================================================================
RELEASE_KEYS = {
    # "key-id": "64 hex chars of an Ed25519 public key" — added by the
    # person who publishes releases (see --make-release-key). Two keys may
    # be listed at once so a key can be rotated without breaking updates.
}
MANIFEST_NAME = "miniwireshark.manifest.json"

_ED_P = 2 ** 255 - 19
_ED_Q = 2 ** 252 + 27742317777372353535851937790883648493
_ED_D = -121665 * pow(121666, _ED_P - 2, _ED_P) % _ED_P
_ED_I = pow(2, (_ED_P - 1) // 4, _ED_P)


def _ed_add(P, Q):
    p, d = _ED_P, _ED_D
    A = (P[1] - P[0]) * (Q[1] - Q[0]) % p
    B = (P[1] + P[0]) * (Q[1] + Q[0]) % p
    C = 2 * P[3] * Q[3] * d % p
    D = 2 * P[2] * Q[2] % p
    E, F, G, H = B - A, D - C, D + C, B + A
    return (E * F % p, G * H % p, F * G % p, E * H % p)


def _ed_mul(s, P):
    Q = (0, 1, 1, 0)
    while s > 0:
        if s & 1:
            Q = _ed_add(Q, P)
        P = _ed_add(P, P)
        s >>= 1
    return Q


def _ed_recover_x(y, sign):
    p = _ED_P
    if y >= p:
        return None
    x2 = (y * y - 1) * pow(_ED_D * y * y + 1, p - 2, p) % p
    if x2 == 0:
        return None if sign else 0
    x = pow(x2, (p + 3) // 8, p)
    if (x * x - x2) % p:
        x = x * _ED_I % p
    if (x * x - x2) % p:
        return None
    if (x & 1) != sign:
        x = p - x
    return x


_ED_GY = 4 * pow(5, _ED_P - 2, _ED_P) % _ED_P
_ED_GX = _ed_recover_x(_ED_GY, 0)
_ED_G = (_ED_GX, _ED_GY, 1, _ED_GX * _ED_GY % _ED_P)


def _ed_decompress(s):
    if len(s) != 32:
        return None
    y = int.from_bytes(s, "little")
    sign = y >> 255
    y &= (1 << 255) - 1
    x = _ed_recover_x(y, sign)
    return None if x is None else (x, y, 1, x * y % _ED_P)


def _ed_compress(P):
    zi = pow(P[2], _ED_P - 2, _ED_P)
    x, y = P[0] * zi % _ED_P, P[1] * zi % _ED_P
    return (y | ((x & 1) << 255)).to_bytes(32, "little")


def _ed_equal(P, Q):
    p = _ED_P
    return (P[0] * Q[2] - Q[0] * P[2]) % p == 0 and \
        (P[1] * Q[2] - Q[1] * P[2]) % p == 0


def ed25519_public_key(secret):
    h = hashlib.sha512(secret).digest()
    a = int.from_bytes(h[:32], "little")
    a &= (1 << 254) - 8
    a |= 1 << 254
    return _ed_compress(_ed_mul(a, _ED_G))


def ed25519_sign(secret, msg):
    """Release tooling only (the app itself never signs anything)."""
    h = hashlib.sha512(secret).digest()
    a = int.from_bytes(h[:32], "little")
    a &= (1 << 254) - 8
    a |= 1 << 254
    A = _ed_compress(_ed_mul(a, _ED_G))
    r = int.from_bytes(hashlib.sha512(h[32:] + msg).digest(), "little") \
        % _ED_Q
    Rs = _ed_compress(_ed_mul(r, _ED_G))
    k = int.from_bytes(hashlib.sha512(Rs + A + msg).digest(), "little") \
        % _ED_Q
    return Rs + ((r + k * a) % _ED_Q).to_bytes(32, "little")


def _ed25519_verify_py(public, msg, sig):
    if len(public) != 32 or len(sig) != 64:
        return False
    A = _ed_decompress(public)
    R = _ed_decompress(sig[:32])
    if A is None or R is None:
        return False
    s = int.from_bytes(sig[32:], "little")
    if s >= _ED_Q:
        return False
    k = int.from_bytes(hashlib.sha512(sig[:32] + public + msg).digest(),
                       "little") % _ED_Q
    return _ed_equal(_ed_mul(s, _ED_G), _ed_add(R, _ed_mul(k, A)))


def ed25519_verify(public, msg, sig):
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import \
            Ed25519PublicKey
        from cryptography.exceptions import InvalidSignature
    except Exception:                                # noqa: BLE001
        return _ed25519_verify_py(public, msg, sig)
    try:
        Ed25519PublicKey.from_public_bytes(bytes(public)).verify(bytes(sig),
                                                                msg)
        return True
    except (InvalidSignature, ValueError):
        return False


def _canonical(obj):
    return json.dumps(obj, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=True).encode()


def sign_manifest(body, keys):
    """body: dict without "signatures"; keys: {key_id: 32-byte secret}."""
    msg = _canonical(body)
    out = dict(body)
    out["signatures"] = [{"key": kid, "sig": ed25519_sign(sec, msg).hex()}
                         for kid, sec in keys.items()]
    return out


class UpdateRefused(ValueError):
    pass


def verify_manifest(manifest, trusted=None, kind="release"):
    """→ the manifest body when a trusted key signed it, else raises
    UpdateRefused with a plain-English reason."""
    trusted = RELEASE_KEYS if trusted is None else trusted
    if not trusted:
        raise UpdateRefused("No release key is configured, so updates are "
                            "check-only (nothing is installed "
                            "automatically).")
    if not isinstance(manifest, dict) or manifest.get("kind", "release") \
            != kind:
        raise UpdateRefused("Not a MiniWireshark manifest of this kind.")
    body = {k: v for k, v in manifest.items() if k != "signatures"}
    msg = _canonical(body)
    for s in manifest.get("signatures") or []:
        pk = trusted.get(s.get("key", ""))
        if not pk:
            continue
        with contextlib.suppress(ValueError, TypeError):
            if ed25519_verify(bytes.fromhex(pk), msg, bytes.fromhex(
                    s.get("sig", ""))):
                return body
    raise UpdateRefused("The release isn't signed by a key this "
                        "MiniWireshark trusts — it was NOT installed.")


def check_release(manifest, data, current=SCRIPT_VERSION, trusted=None):
    """All checks before an update is installed."""
    body = verify_manifest(manifest, trusted)
    if _version_tuple(body.get("version", "")) <= _version_tuple(current):
        raise UpdateRefused(f"The release ({body.get('version')}) isn't "
                            f"newer than this one ({current}) — downgrades "
                            f"are refused.")
    if len(data) != int(body.get("size", -1)):
        raise UpdateRefused("The download is incomplete or the wrong size.")
    if hashlib.sha256(data).hexdigest() != body.get("sha256"):
        raise UpdateRefused("The download doesn't match the signed "
                            "fingerprint.")
    return body


def make_release_manifest(script_bytes, version, keys, notes=""):
    return sign_manifest({"kind": "release", "app": APP_NAME,
                          "version": version,
                          "sha256": hashlib.sha256(script_bytes).hexdigest(),
                          "size": len(script_bytes), "notes": notes,
                          "made": time.strftime("%Y-%m-%d")}, keys)


# ---- data packs: signed updates of the reference lists -----------------------
DATA_PACK_TARGETS = {"services": "PORT_SERVICES", "doh": "DOH_HOSTS"}


def apply_data_pack(pack, trusted=None):
    """Install a signed data pack (port→service names, encrypted-DNS
    hosts). → number of entries added."""
    body = verify_manifest(pack, trusted, kind="datapack")
    target = DATA_PACK_TARGETS.get(body.get("pack"))
    if target is None:
        raise UpdateRefused(f"Unknown data pack “{body.get('pack')}”.")
    data = body.get("data") or {}
    if not isinstance(data, dict) or len(data) > 50000:
        raise UpdateRefused("The data pack is malformed.")
    table = globals()[target]
    n = 0
    for k, v in data.items():
        key = int(k) if target == "PORT_SERVICES" else str(k).lower()
        val = sanitize_text(str(v), 80)
        if table.get(key) != val:
            table[key] = val
            n += 1
    return n


def release_check(path=None):
    """Release checklist (developers): prints what to verify and the
    file's fingerprint. Exit code 0 only when every automatic check
    passes."""
    path = path or SCRIPT_PATH
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8")
    checks = []
    try:
        import ast
        ast.parse(text, feature_version=(3, 7))  # novermin (guarded)
        ast.parse(text, feature_version=(3, 8))  # novermin (guarded)
        checks.append(("Python 3.7 and 3.8 grammar", True, ""))
    except SyntaxError as e:
        checks.append(("Python 3.7 and 3.8 grammar", False, str(e)))
    except TypeError:            # Python 3.7: no feature_version
        checks.append(("Python 3.7 and 3.8 grammar", False,
                       "run the release check with Python 3.8 or newer"))
    m = re.search(r'^SCRIPT_VERSION = "([^"]+)"', text, re.M)
    checks.append(("Version string", bool(m), m.group(1) if m else ""))
    checks.append(("Release keys listed", bool(RELEASE_KEYS),
                   ", ".join(RELEASE_KEYS) or "none — updates check-only"))
    checks.append(("Runtime lock fingerprint", True, lock_fingerprint()))
    checks.append(("No debugger left in", "breakpoint()" not in text.replace(
        '"breakpoint()"', ""), ""))
    print(f"MiniWireshark release check — {os.path.basename(path)}")
    for name, ok, detail in checks:
        print(f"  [{'OK' if ok else '!!'}] {name}" + (f": {detail}"
                                                      if detail else ""))
    print(f"  sha256 {hashlib.sha256(data).hexdigest()}  size {len(data)}")
    print("  Manual: run --release-gate on Windows, macOS and Linux (and "
          "on the reference laptop) and read each summary.txt; sign with "
          "--sign-release; attach the .py and "
          f"{MANIFEST_NAME} to the release.")
    return 0 if all(ok for name, ok, _d in checks
                    if name != "Release keys listed") else 1


def _arg(argv, name, default=None):
    if name in argv:
        i = argv.index(name)
        if i + 1 < len(argv):
            return argv[i + 1]
    return default


def release_tool(argv):
    """Developer commands (never needed by users):
      --release-check [FILE]
      --make-release-key KEYFILE [--key-id ID]
      --sign-release FILE --key KEYFILE [--key-id ID] [--version X]
      --sign-datapack JSON --key KEYFILE --pack services|doh"""
    if "--release-check" in argv:
        return release_check(_arg(argv, "--release-check"))
    if "--make-release-key" in argv:
        path = _arg(argv, "--make-release-key")
        if not path or os.path.exists(path):
            print("Give a NEW file name for the secret key.")
            return 2
        secret = os.urandom(32)
        kid = _arg(argv, "--key-id", time.strftime("release-%Y"))
        with open(path, "w", encoding="utf-8") as f:
            json.dump({"key_id": kid, "secret": secret.hex()}, f)
        with contextlib.suppress(OSError):
            os.chmod(path, 0o600)
        print(f"Secret key written to {path} — keep it OFFLINE and backed "
              f"up.\nAdd this line to RELEASE_KEYS:\n    "
              f"\"{kid}\": \"{ed25519_public_key(secret).hex()}\",")
        return 0
    keyfile = _arg(argv, "--key")
    if not keyfile:
        print("--key KEYFILE is required")
        return 2
    with open(keyfile, encoding="utf-8") as f:
        kd = json.load(f)
    keys = {kd["key_id"]: bytes.fromhex(kd["secret"])}
    if "--sign-release" in argv:
        path = _arg(argv, "--sign-release")
        with open(path, "rb") as f:
            data = f.read()
        m = re.search(rb'^SCRIPT_VERSION = "([^"]+)"', data, re.M)
        ver = _arg(argv, "--version", m.group(1).decode() if m else "")
        man = make_release_manifest(data, ver, keys)
        out = os.path.join(os.path.dirname(os.path.abspath(path)),
                           MANIFEST_NAME)
        atomic_write_json(out, man)
        print(f"Signed {os.path.basename(path)} {ver} → {out}")
        return 0
    if "--sign-datapack" in argv:
        path = _arg(argv, "--sign-datapack")
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        pack = sign_manifest({"kind": "datapack",
                              "pack": _arg(argv, "--pack", "services"),
                              "version": time.strftime("%Y%m%d"),
                              "data": data}, keys)
        out = path + ".signed.json"
        atomic_write_json(out, pack)
        print(f"Signed data pack → {out}")
        return 0
    print(release_tool.__doc__)
    return 2


def apply_self_update(data, tag, script_path=None, marker_path=None):
    """Validate, back up, atomically replace. Never destroys the only
    working copy: the backup stays until the new version has run fine."""
    if FROZEN and script_path is None:
        raise UpdateRefused("the standalone program is updated by its "
                            "installer, not by replacing a .py file")
    script_path = script_path or SCRIPT_PATH
    marker_path = marker_path or PATHS.update_marker
    if not data or len(data) < 50_000:
        raise ValueError("the downloaded file is too small to be "
                         "MiniWireshark")
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as e:
        raise ValueError(f"the download isn't a text file ({e})")
    if "MiniWireshark" not in text or "def main" not in text:
        raise ValueError("the download doesn't look like MiniWireshark")
    compile(text, "miniwireshark_update.py", "exec")
    backup = f"{script_path}.v{SCRIPT_VERSION}.bak"
    shutil.copy2(script_path, backup)
    tmp = script_path + ".new"
    with open(tmp, "w", encoding="utf-8", newline="") as f:
        f.write(text)
    os.replace(tmp, script_path)
    # 5.2.3 (B-31): the marker names the file it belongs to and what was
    # written, so another copy of MiniWireshark sharing this data folder
    # (an archived version) never "rolls back" over itself
    marker = {"backup": backup, "version": tag, "from": SCRIPT_VERSION,
              "script": os.path.abspath(script_path),
              "sha256": sha256_file(script_path),
              "backup_sha256": sha256_file(backup),
              "time": time.time(), "attempts": 0}
    marker["mac"] = update_marker_mac(marker)
    atomic_write_json(marker_path, marker)
    LOG.info("installed update %s (backup %s)", tag, backup)
    return (f"MiniWireshark {tag} was installed. Restart it to use the new "
            f"version. A backup of {SCRIPT_VERSION} is at:\n{backup}\nIf the "
            f"new version fails to start, the backup is restored "
            f"automatically.")


def _norm_path(p):
    return os.path.normcase(os.path.abspath(p))


_MARKER_SIGNED = ("backup", "version", "from", "script", "sha256",
                  "backup_sha256", "time")


def update_marker_mac(marker, key=None):
    """5.3.4 (RT-02): an HMAC over the marker's fields (not `attempts`,
    which changes every start) with the install key, or "" without one."""
    import hmac
    key = key or install_key()
    if not key:
        return ""
    body = json.dumps({k: marker.get(k) for k in _MARKER_SIGNED},
                      sort_keys=True).encode("utf-8")
    return hmac.new(key, body, hashlib.sha256).hexdigest()


def rollback_source_ok(marker, script_path):
    """5.3.4 (RT-02): the backup a rollback may copy over the program.
    Only the one this install wrote: next to the program, named after the
    version it replaced, owned like the program, and (for a marker 5.3.4
    wrote) under a valid HMAC with the sha256 it had then. Before, the
    marker was plain JSON in the data folder, so anyone who could write
    there chose what replaced the program. -> (ok, why)."""
    import hmac
    backup = str(marker.get("backup") or "")
    want = f"{script_path}.v{marker.get('from')}.bak"
    if not backup or _norm_path(backup) != _norm_path(want):
        return False, "the backup isn't the one this program writes"
    try:
        bst, sst = os.stat(backup), os.stat(script_path)
    except OSError:
        return False, "the backup is missing"
    if not IS_WINDOWS and (bst.st_uid != sst.st_uid or
                           bst.st_mode & 0o022):
        return False, "the backup is owned by someone else"
    if marker.get("mac") or marker.get("backup_sha256"):
        mac = update_marker_mac(marker)
        if not mac or not hmac.compare_digest(mac, str(marker.get("mac"))):
            return False, "the update marker isn't authentic"
        try:
            if sha256_file(backup) != marker.get("backup_sha256"):
                return False, "the backup has changed since the update"
        except OSError:
            return False, "the backup can't be read"
    elif str(marker.get("version")) != SCRIPT_VERSION or \
            _version_tuple(str(marker.get("from") or "")) >= (5, 3, 4):
        # (review of RT-02) a marker without an HMAC can only be the one an
        # older release wrote while updating to this very version
        return False, "the update marker isn't authentic"
    return True, ""


def update_marker_for(script_path=None, marker_path=None):
    """The pending-update marker if it belongs to this very file, else
    None. 5.2.3 (B-31): before, any copy of MiniWireshark started with the
    same data folder counted the attempts and could copy the backup over
    itself. A marker whose file has since been replaced by something else
    is dropped."""
    script_path = script_path or SCRIPT_PATH
    marker_path = marker_path or PATHS.update_marker
    marker = read_json(marker_path, None)
    if not isinstance(marker, dict):
        return None
    me = _norm_path(script_path)
    owner = marker.get("script") or ""
    if owner:
        if _norm_path(owner) != me:
            return None
    else:                     # written by 5.1.2 or older: judge the backup
        backup = str(marker.get("backup") or "")
        if not _norm_path(backup).startswith(me + ".v"):
            return None
    want = marker.get("sha256")
    if want:
        try:
            have = sha256_file(script_path)
        except OSError:
            have = ""
        if have and have != want:
            LOG.info("update marker is for a file that has since been "
                     "replaced; dropping it")
            with contextlib.suppress(OSError):
                os.remove(marker_path)
            return None
    return marker


def update_start_not_counted(script_path=None, marker_path=None):
    """The user left before the window (loading screen, Welcome Center):
    that start says nothing about the update, so it doesn't count toward
    the automatic rollback (5.2.3, B-31)."""
    marker_path = marker_path or PATHS.update_marker
    marker = update_marker_for(script_path, marker_path)
    if marker and int(marker.get("attempts", 0)) > 0:
        marker["attempts"] = int(marker["attempts"]) - 1
        with contextlib.suppress(OSError):
            atomic_write_json(marker_path, marker)


def journal_owner(path):
    """The pid that wrote this crash journal (5.3.4), or 0."""
    side = read_json(path + ".sha256", None)
    try:
        return int(side.get("pid") or 0) if isinstance(side, dict) else 0
    except (TypeError, ValueError):
        return 0


def claim_interrupted_journal(path=None, now=None, keep=3):
    """5.2.3 (B-33): a crash journal found at start-up is moved aside to
    journal-interrupted-<time>.mwsession.json before anything else, so 30 s
    of new capture can no longer overwrite the session it holds. Returns
    the moved file ("" if none). A journal written in the last 45 s
    belongs to a copy of MiniWireshark that is still running and is left
    alone. A .sha256 file older than the journal was left by another
    version (5.0.x writes no .sha256) and is not taken along."""
    path = path or PATHS.journal
    now = time.time() if now is None else now
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        return ""
    if now - mtime < 45:
        return ""
    # 5.3.4 (OS-07): the copy that wrote it is still running (its pid is
    # alive and it said so in the last 2 minutes, even when idle)
    owner = journal_owner(path)
    try:
        beat = os.path.getmtime(path + ".sha256")
    except OSError:
        beat = 0.0
    if owner and owner != os.getpid() and _pid_alive(owner) and \
            now - beat < 120:
        return ""
    folder = os.path.dirname(path)
    dest = os.path.join(folder, time.strftime(
        "journal-interrupted-%Y%m%d-%H%M%S", time.localtime(mtime)) +
        f"-{os.getpid()}.mwsession.json")
    side = path + ".sha256"
    try:
        side_ok = os.path.getmtime(side) >= mtime - 1
    except OSError:
        side_ok = False
    try:
        os.replace(path, dest)
    except OSError as e:
        LOG.warning("could not set the crash journal aside: %s", e)
        return path
    with contextlib.suppress(OSError):
        if side_ok:
            os.replace(side, dest + ".sha256")
        else:
            os.remove(side)
    try:
        olds = sorted((n for n in os.listdir(folder)
                       if n.startswith("journal-interrupted-") and
                       n.endswith(".mwsession.json")), reverse=True)
    except OSError:
        olds = []
    for n in olds[keep:]:
        for p_ in (os.path.join(folder, n), os.path.join(folder, n) +
                   ".sha256"):
            with contextlib.suppress(OSError):
                os.remove(p_)
    return dest


def rollback_update_if_needed(force=False, script_path=None,
                              marker_path=None):
    """Called at startup (and on a startup crash). Returns a message if a
    rollback happened."""
    script_path = script_path or SCRIPT_PATH
    marker_path = marker_path or PATHS.update_marker
    marker = update_marker_for(script_path, marker_path)
    if not marker:
        return ""
    marker["attempts"] = int(marker.get("attempts", 0)) + 1
    with contextlib.suppress(OSError):
        atomic_write_json(marker_path, marker)
    if not force and marker["attempts"] < 3:
        return ""
    backup = marker.get("backup", "")
    ok, why = rollback_source_ok(marker, script_path)
    if not ok:
        LOG.warning("update rollback refused: %s", why)
        with contextlib.suppress(OSError):
            os.remove(marker_path)
        return ""
    if backup and os.path.exists(backup):
        try:
            shutil.copy2(backup, script_path)
            os.remove(marker_path)
            LOG.warning("rolled back update %s", marker.get("version"))
            return (f"The update to {marker.get('version')} didn't start "
                    f"correctly, so the previous version "
                    f"({marker.get('from')}) was restored. Please start "
                    f"MiniWireshark again.")
        except OSError as e:
            return f"Rolling back the update failed: {e}. Backup: {backup}"
    return ""



# ============================================================================
#  20.  Demo mode — simulated, clearly-labelled, never mixed with real data
#
#  The generator builds ordinary packets and pushes them through the SAME
#  decoder and analysis as live capture, so every tab behaves for real.
#  Domains use the reserved ".example" names. Nothing is transmitted.
# ============================================================================
# ---- V5: a small packet builder of our own -----------------------------------
#  Demo Mode, the scripted scenarios, the fuzzer and the benchmarks build their
#  frames with these few layers instead of scapy, so they work on a computer
#  where the capture engine is missing (limited mode) and produce the same
#  bytes everywhere. Layers stack with "/" like scapy's and serialise with
#  bytes(); lengths and checksums are filled in automatically. The self-test
#  checks that every scripted frame is byte-identical to what scapy builds.
def _pk_mac(s):
    return bytes.fromhex(s.replace(":", "").replace("-", ""))


def _pk_ip4(s):
    return _socket.inet_aton(s)


def _pk_ip6(s):
    return _socket.inet_pton(_socket.AF_INET6, s)


def _pk_csum(data):
    if len(data) % 2:
        data += b"\x00"
    s = sum(struct.unpack("!%dH" % (len(data) // 2), data))
    while s >> 16:
        s = (s & 0xFFFF) + (s >> 16)
    return (~s) & 0xFFFF


def _pk_name(name):
    """DNS name → wire format (no compression, like scapy's builder)."""
    if isinstance(name, bytes):
        name = name.decode("ascii", "replace")
    name = name.rstrip(".")
    out = b""
    for label in name.split(".") if name else []:
        lab = label.encode("utf-8")
        out += bytes([len(lab)]) + lab
    return out + b"\x00"


class PkLayer:
    """One protocol layer; `a / b` puts b on top of a."""

    FIELDS = {}

    def __init__(self, *args, **kw):
        for k, v in self.FIELDS.items():
            setattr(self, k, v)
        for k, v in zip(self.FIELDS, args):     # positional, in field order
            setattr(self, k, v)
        for k, v in kw.items():
            if k not in self.FIELDS:
                raise TypeError(f"{type(self).__name__} has no field {k}")
            setattr(self, k, v)
        self.payload = None
        self.under = None

    def copy(self):
        c = object.__new__(type(self))
        c.__dict__.update(self.__dict__)
        c.payload = self.payload.copy() if self.payload is not None else None
        if c.payload is not None:
            c.payload.under = c
        c.under = None
        return c

    def __truediv__(self, other):
        if isinstance(other, (bytes, bytearray)):
            other = PkRaw(load=bytes(other))
        top = self.copy()
        last = top
        while last.payload is not None:
            last = last.payload
        o = other.copy()
        last.payload = o
        o.under = last
        return top

    def payload_bytes(self):
        return bytes(self.payload) if self.payload is not None else b""

    def build(self, pay):            # → this layer's bytes + pay
        raise NotImplementedError

    def __bytes__(self):
        return self.build(self.payload_bytes())

    def __len__(self):
        return len(bytes(self))


class PkRaw(PkLayer):
    FIELDS = {"load": b""}

    def build(self, pay):
        return bytes(self.load) + pay


class PkEther(PkLayer):
    FIELDS = {"dst": "ff:ff:ff:ff:ff:ff", "src": "00:00:00:00:00:00",
              "type": None}

    def build(self, pay):
        t = self.type
        if t is None:
            t = {PkIP: 0x0800, PkIPv6: 0x86DD, PkARP: 0x0806,
                 PkDot1Q: 0x8100}.get(type(self.payload), 0x9000)
        return _pk_mac(self.dst) + _pk_mac(self.src) + \
            struct.pack("!H", t) + pay


class PkDot1Q(PkLayer):
    FIELDS = {"prio": 0, "id": 0, "vlan": 1, "type": None}

    def build(self, pay):
        t = self.type
        if t is None:
            t = {PkIP: 0x0800, PkIPv6: 0x86DD, PkARP: 0x0806}.get(
                type(self.payload), 0x9000)
        return struct.pack("!HH", (self.prio << 13) | (self.id << 12) |
                           self.vlan, t) + pay


class PkARP(PkLayer):
    FIELDS = {"hwtype": 1, "ptype": 0x0800, "hwlen": 6, "plen": 4, "op": 1,
              "hwsrc": "00:00:00:00:00:00", "psrc": "0.0.0.0",
              "hwdst": "00:00:00:00:00:00", "pdst": "0.0.0.0"}

    def build(self, pay):
        return struct.pack("!HHBBH", self.hwtype, self.ptype, self.hwlen,
                           self.plen, self.op) + _pk_mac(self.hwsrc) + \
            _pk_ip4(self.psrc) + _pk_mac(self.hwdst) + \
            _pk_ip4(self.pdst) + pay


class PkIP(PkLayer):
    FIELDS = {"tos": 0, "id": 1, "flags": 0, "frag": 0, "ttl": 64,
              "proto": None, "src": "0.0.0.0", "dst": "127.0.0.1",
              "options": b""}

    def build(self, pay):
        proto = self.proto
        if proto is None:
            proto = {PkTCP: 6, PkUDP: 17, PkICMP: 1}.get(type(self.payload),
                                                         0)
        opts = bytes(self.options or b"")
        if len(opts) % 4:
            opts += b"\x00" * (4 - len(opts) % 4)
        hl = 20 + len(opts)
        hdr = struct.pack("!BBHHHBBH4s4s", 0x40 | (hl // 4), self.tos,
                          hl + len(pay),
                          self.id, (self.flags << 13) | self.frag, self.ttl,
                          proto, 0, _pk_ip4(self.src),
                          _pk_ip4(self.dst)) + opts
        c = _pk_csum(hdr)
        return hdr[:10] + struct.pack("!H", c) + hdr[12:] + pay

    def pseudo(self, proto, length):
        return _pk_ip4(self.src) + _pk_ip4(self.dst) + \
            struct.pack("!BBH", 0, proto, length)


class PkIPv6(PkLayer):
    FIELDS = {"tc": 0, "fl": 0, "nh": None, "hlim": None, "src": "::1",
              "dst": "::1"}

    def build(self, pay):
        hlim = self.hlim
        if hlim is None:          # neighbour discovery must arrive with 255
            hlim = 255 if isinstance(self.payload, (
                PkICMPv6ND_RA, PkICMPv6ND_NA)) else 64
        nh = self.nh
        if nh is None:
            nh = 58 if isinstance(self.payload, _PkICMPv6) else \
                {PkTCP: 6, PkUDP: 17}.get(type(self.payload), 59)
        return struct.pack("!IHBB", (6 << 28) | (self.tc << 20) | self.fl,
                           len(pay), nh, hlim) + _pk_ip6(self.src) + \
            _pk_ip6(self.dst) + pay

    def pseudo(self, proto, length):
        return _pk_ip6(self.src) + _pk_ip6(self.dst) + \
            struct.pack("!IxxxB", length, proto)


def _pk_l4_csum(layer, proto, seg, zero_is_ffff=False):
    ip = layer.under
    if ip is None or not hasattr(ip, "pseudo"):
        return 0
    c = _pk_csum(ip.pseudo(proto, len(seg)) + seg)
    if zero_is_ffff and c == 0:
        c = 0xFFFF
    return c


class PkICMP(PkLayer):
    FIELDS = {"type": 8, "code": 0, "id": 0, "seq": 0}

    def build(self, pay):
        msg = struct.pack("!BBHHH", self.type, self.code, 0, self.id,
                          self.seq) + pay
        return msg[:2] + struct.pack("!H", _pk_csum(msg)) + msg[4:]


class PkUDP(PkLayer):
    FIELDS = {"sport": 53, "dport": 53}

    def build(self, pay):
        n = 8 + len(pay)
        seg = struct.pack("!HHHH", self.sport, self.dport, n, 0) + pay
        c = _pk_l4_csum(self, 17, seg, zero_is_ffff=True)
        return seg[:6] + struct.pack("!H", c) + seg[8:]


_PK_TCP_FLAGS = {"F": 0x01, "S": 0x02, "R": 0x04, "P": 0x08, "A": 0x10,
                 "U": 0x20, "E": 0x40, "C": 0x80}


class PkTCP(PkLayer):
    FIELDS = {"sport": 20, "dport": 80, "seq": 0, "ack": 0, "flags": "S",
              "window": 8192, "urgptr": 0, "options": b""}

    def build(self, pay):
        fl = self.flags
        if isinstance(fl, str):
            fl = sum(_PK_TCP_FLAGS[c] for c in fl)
        opts = bytes(self.options or b"")
        if len(opts) % 4:
            opts += b"\x00" * (4 - len(opts) % 4)
        off = (20 + len(opts)) // 4
        seg = struct.pack("!HHIIBBHHH", self.sport, self.dport,
                          self.seq & 0xFFFFFFFF, self.ack & 0xFFFFFFFF,
                          off << 4, fl, self.window, 0, self.urgptr) + \
            opts + pay
        c = _pk_l4_csum(self, 6, seg)
        return seg[:16] + struct.pack("!H", c) + seg[18:]


class PkBOOTP(PkLayer):
    FIELDS = {"op": 1, "htype": 1, "hlen": 6, "hops": 0, "xid": 0, "secs": 0,
              "flags": 0, "ciaddr": "0.0.0.0", "yiaddr": "0.0.0.0",
              "siaddr": "0.0.0.0", "giaddr": "0.0.0.0", "chaddr": b"",
              "sname": b"", "file": b"", "options": b""}

    def build(self, pay):
        opts = self.options
        if not opts and isinstance(self.payload, PkDHCP):
            opts = b"c\x82Sc"
        return struct.pack("!BBBBIHH", self.op, self.htype, self.hlen,
                           self.hops, self.xid, self.secs, self.flags) + \
            _pk_ip4(self.ciaddr) + _pk_ip4(self.yiaddr) + \
            _pk_ip4(self.siaddr) + _pk_ip4(self.giaddr) + \
            bytes(self.chaddr)[:16].ljust(16, b"\x00") + \
            bytes(self.sname)[:64].ljust(64, b"\x00") + \
            bytes(self.file)[:128].ljust(128, b"\x00") + bytes(opts) + pay


_PK_DHCP_CODES = {"subnet_mask": (1, "ip"), "router": (3, "ip"),
                  "name_server": (6, "ip"), "hostname": (12, "bytes"),
                  "requested_addr": (50, "ip"), "lease_time": (51, "int"),
                  "message-type": (53, "type"), "server_id": (54, "ip"),
                  "param_req_list": (55, "list"),
                  "vendor_class_id": (60, "bytes"),
                  "client_id": (61, "bytes")}
_PK_DHCP_TYPES = {"discover": 1, "offer": 2, "request": 3, "decline": 4,
                  "ack": 5, "nak": 6, "release": 7, "inform": 8}


class PkDHCP(PkLayer):
    FIELDS = {"options": ()}

    def build(self, pay):
        out = b""
        for o in self.options:
            if o == "end":
                out += b"\xff"
                continue
            if o == "pad":
                out += b"\x00"
                continue
            name, val = o[0], o[1]
            code, kind = _PK_DHCP_CODES[name]
            if kind == "ip":
                data = _pk_ip4(val)
            elif kind == "int":
                data = struct.pack("!I", int(val))
            elif kind == "type":
                data = bytes([_PK_DHCP_TYPES.get(val, val)
                              if isinstance(val, str) else int(val)])
            elif kind == "list":
                data = bytes(int(x) for x in val)
            else:
                data = val.encode() if isinstance(val, str) else bytes(val)
            out += bytes([code, len(data)]) + data
        return out + pay


_PK_DNS_TYPES = {"A": 1, "NS": 2, "CNAME": 5, "PTR": 12, "TXT": 16,
                 "AAAA": 28, "SRV": 33}


class PkDNSQR(PkLayer):
    FIELDS = {"qname": "www.example.com", "qtype": 1, "qclass": 1}

    def build(self, pay):
        qt = _PK_DNS_TYPES.get(self.qtype, self.qtype)
        return _pk_name(self.qname) + struct.pack("!HH", qt,
                                                  self.qclass) + pay


class PkDNSRR(PkLayer):
    FIELDS = {"rrname": ".", "type": 1, "rclass": 1, "ttl": 0, "rdata": None}

    def build(self, pay):
        t = _PK_DNS_TYPES.get(self.type, self.type)
        rd = self.rdata
        if t == 1:
            data = _pk_ip4(rd or "0.0.0.0")
        elif t == 28:
            data = _pk_ip6(rd or "::")
        elif t in (2, 5, 12):
            data = _pk_name(rd or "")
        elif t == 16:
            items = rd if isinstance(rd, (list, tuple)) else [rd or b""]
            data = b"".join(bytes([len(x)]) + x for x in
                            (i.encode() if isinstance(i, str) else bytes(i)
                             for i in items))
        else:
            data = bytes(rd or b"")
        return _pk_name(self.rrname) + struct.pack(
            "!HHIH", t, self.rclass, self.ttl, len(data)) + data + pay


class PkDNS(PkLayer):
    FIELDS = {"id": 0, "qr": 0, "opcode": 0, "aa": 0, "tc": 0, "rd": 1,
              "ra": 0, "z": 0, "ad": 0, "cd": 0, "rcode": 0, "qd": (),
              "an": None, "ns": None, "ar": None}

    @staticmethod
    def _list(v):
        if v is None:
            return []
        return list(v) if isinstance(v, (list, tuple)) else [v]

    def build(self, pay):
        qd, an = self._list(self.qd), self._list(self.an)
        ns, ar = self._list(self.ns), self._list(self.ar)
        flags = (self.qr << 15) | (self.opcode << 11) | (self.aa << 10) | \
            (self.tc << 9) | (self.rd << 8) | (self.ra << 7) | \
            (self.z << 6) | (self.ad << 5) | (self.cd << 4) | self.rcode
        body = b"".join(bytes(x) for x in qd + an + ns + ar)
        return struct.pack("!HHHHHH", self.id, flags, len(qd), len(an),
                           len(ns), len(ar)) + body + pay


class _PkICMPv6(PkLayer):
    TYPE = 0

    def head(self):
        return b""

    def build(self, pay):
        msg = struct.pack("!BBH", self.TYPE, 0, 0) + self.head() + pay
        c = _pk_l4_csum(self, 58, msg)
        return msg[:2] + struct.pack("!H", c) + msg[4:]


class PkICMPv6ND_RA(_PkICMPv6):
    TYPE = 134
    FIELDS = {"chlim": 0, "M": 0, "O": 0, "H": 0, "prf": 1, "P": 0,
              "routerlifetime": 1800, "reachabletime": 0, "retranstimer": 0}

    def head(self):
        b = (self.M << 7) | (self.O << 6) | (self.H << 5) | \
            (self.prf << 3) | (self.P << 2)
        return struct.pack("!BBHII", self.chlim, b, self.routerlifetime,
                           self.reachabletime, self.retranstimer)


class PkICMPv6ND_NA(_PkICMPv6):
    TYPE = 136
    FIELDS = {"R": 1, "S": 0, "O": 1, "tgt": "::"}

    def head(self):
        return struct.pack("!I", (self.R << 31) | (self.S << 30) |
                           (self.O << 29)) + _pk_ip6(self.tgt)


class _PkNDOpt(PkLayer):
    def build(self, pay):
        return self.body() + pay


class PkICMPv6NDOptSrcLLAddr(_PkNDOpt):
    FIELDS = {"lladdr": "00:00:00:00:00:00"}

    def body(self):
        return b"\x01\x01" + _pk_mac(self.lladdr)


class PkICMPv6NDOptDstLLAddr(_PkNDOpt):
    FIELDS = {"lladdr": "00:00:00:00:00:00"}

    def body(self):
        return b"\x02\x01" + _pk_mac(self.lladdr)


class PkICMPv6NDOptPrefixInfo(_PkNDOpt):
    FIELDS = {"prefixlen": 64, "L": 1, "A": 1, "R": 0,
              "validlifetime": 0xFFFFFFFF, "preferredlifetime": 0xFFFFFFFF,
              "prefix": "::"}

    def body(self):
        fl = (self.L << 7) | (self.A << 6) | (self.R << 5)
        return struct.pack("!BBBBIII", 3, 4, self.prefixlen, fl,
                           self.validlifetime, self.preferredlifetime, 0) + \
            _pk_ip6(self.prefix)


class PK:
    """The builder's layers under scapy's names (PK.Ether, PK.IP, ...)."""
    Ether, ARP, IP, IPv6, UDP, TCP, Raw = (PkEther, PkARP, PkIP, PkIPv6,
                                           PkUDP, PkTCP, PkRaw)
    Dot1Q, ICMP = PkDot1Q, PkICMP
    BOOTP, DHCP, DNS, DNSQR, DNSRR = PkBOOTP, PkDHCP, PkDNS, PkDNSQR, PkDNSRR
    ICMPv6ND_RA, ICMPv6ND_NA = PkICMPv6ND_RA, PkICMPv6ND_NA
    ICMPv6NDOptSrcLLAddr = PkICMPv6NDOptSrcLLAddr
    ICMPv6NDOptDstLLAddr = PkICMPv6NDOptDstLLAddr
    ICMPv6NDOptPrefixInfo = PkICMPv6NDOptPrefixInfo


# ============================================================================
#  V5: packet dissection — one field model, one declarative registry
#
#  Every decoded value is a PacketField with its exact byte range, how it
#  was known (observed / inferred) and a Wireshark-style filter key. Each
#  dissector declares its fields once in FIELD_REGISTRY (key, type, unit,
#  one-line description): the packet tree, the hex view highlight, the help
#  glossary and the tests all read that one table. Dissection never raises:
#  a short or malformed packet ends with a "truncated" / "malformed"
#  warning on the last node. Secrets never reach a field value: cookies,
#  authorization headers and mail/FTP passwords are replaced by "(hidden)".
# ============================================================================
LV_FIELD_OBSERVED = "observed"
LV_FIELD_INFERRED = "inferred"

FIELD_REGISTRY = {}          # key -> (type, unit, description, protocol)
PROTOCOL_TITLES = {}         # protocol key -> title


def declare_fields(proto, title, fields):
    """fields: [(key, type, unit, description)]."""
    PROTOCOL_TITLES[proto] = title
    for key, ftype, unit, desc in fields:
        FIELD_REGISTRY[key] = (ftype, unit, desc, proto)


class PacketField:
    __slots__ = ("key", "name", "value", "offset", "length", "level",
                 "warning", "children", "raw_value")

    def __init__(self, key, name, value, offset, length,
                 level=LV_FIELD_OBSERVED, warning="", raw_value=None):
        self.key, self.name, self.value = key, name, value
        self.offset, self.length = offset, length
        self.level, self.warning = level, warning
        self.children = []
        self.raw_value = value if raw_value is None else raw_value

    def __repr__(self):
        return f"<{self.key}={self.value!r} @{self.offset}+{self.length}>"


class ProtocolNode:
    __slots__ = ("key", "title", "offset", "length", "fields", "warning",
                 "level", "how")

    def __init__(self, key, title, offset, length=0,
                 level=LV_FIELD_OBSERVED, how=""):
        self.key, self.title, self.offset, self.length = key, title, \
            offset, length
        self.fields, self.warning, self.level, self.how = [], "", level, how


class Dissection:
    """The result: protocol nodes in order, plus helpers."""

    def __init__(self, raw, linktype):
        self.raw, self.linktype = raw, linktype
        self.nodes = []
        self._idx = None

    def all_fields(self):
        for n in self.nodes:
            stack = list(reversed(n.fields))
            while stack:
                f = stack.pop()
                yield f
                stack.extend(reversed(f.children))

    def _index(self):
        if self._idx is None:
            idx = {}
            for f in self.all_fields():
                idx.setdefault(f.key, []).append(f.raw_value)
            self._idx = idx
        return self._idx

    def get(self, key):
        """First value for a filter key (or None)."""
        v = self._index().get(key)
        return v[0] if v else None

    def values(self, key):
        return list(self._index().get(key, ()))

    def keys(self):
        return set(self._index())

    def warnings(self):
        out = [(n.title, n.warning) for n in self.nodes if n.warning]
        out += [(f.name, f.warning) for f in self.all_fields() if f.warning]
        return out

    def text(self):
        """Plain-text tree (the Packet details pane and reports)."""
        lines = []
        for n in self.nodes:
            head = n.title + (f"  [{n.how}]" if n.how else "")
            if n.warning:
                head += f"  ⚠ {n.warning}"
            lines.append(head)

            def walk(fields, depth):
                for f in fields:
                    w = f"  ⚠ {f.warning}" if f.warning else ""
                    lines.append("    " * depth + f"{f.name}: {f.value}{w}")
                    walk(f.children, depth + 1)
            walk(n.fields, 1)
        return "\n".join(lines)


class _Cut(Exception):
    """Raised inside a dissector when the packet ends too early."""


class _D:
    """Cursor over the frame used by the dissectors."""

    def __init__(self, out):
        self.out = out
        self.raw = out.raw
        self.node = None

    def begin(self, proto, start, end=None, how="", title=None,
              level=LV_FIELD_OBSERVED):
        n = ProtocolNode(proto, title or PROTOCOL_TITLES.get(proto, proto),
                         start, ((end if end is not None else len(self.raw))
                                 - start), level, how)
        self.out.nodes.append(n)
        self.node = n
        return n

    def need(self, off, n):
        if off + n > len(self.raw):
            raise _Cut()

    def add(self, key, value, off, length, display=None, parent=None,
            warning="", level=None):
        self.need(off, length)
        if display is None and isinstance(value, bool):
            display = "yes" if value else "no"
        f = PacketField(key, _FIELD_LABELS.get(key, key),
                        display if display is not None else value, off,
                        length, level or (self.node.level if self.node else
                                          LV_FIELD_OBSERVED), warning,
                        raw_value=value)
        (parent.children if parent is not None else self.node.fields
         ).append(f)
        return f

    def u8(self, off):
        self.need(off, 1)
        return self.raw[off]

    def u16(self, off):
        self.need(off, 2)
        return struct.unpack_from("!H", self.raw, off)[0]

    def u32(self, off):
        self.need(off, 4)
        return struct.unpack_from("!I", self.raw, off)[0]


def _fmt_mac(b):
    return ":".join(f"{x:02x}" for x in b)


def _mac_desc(b):
    mac = _fmt_mac(b)
    if mac == "ff:ff:ff:ff:ff:ff":
        return f"{mac} (broadcast)"
    v = ""
    with contextlib.suppress(Exception):
        v = mac_vendor(mac) if not (b[0] & 1) else ""
    if b[0] & 1:
        return f"{mac} (multicast)"
    return f"{mac} ({v})" if v else mac


_FIELD_LABELS = {}            # key -> short label shown in the tree

_ETHERTYPES = {0x0800: "IPv4", 0x86DD: "IPv6", 0x0806: "ARP",
               0x8100: "802.1Q VLAN", 0x88A8: "802.1ad (Q-in-Q)",
               0x88CC: "LLDP", 0x888E: "802.1X (EAPOL)", 0x8863: "PPPoE",
               0x8864: "PPPoE session", 0x88E5: "MACsec"}
_IP_PROTOS = {1: "ICMP", 2: "IGMP", 6: "TCP", 17: "UDP", 41: "IPv6",
              47: "GRE", 50: "ESP", 51: "AH", 58: "ICMPv6", 89: "OSPF",
              132: "SCTP"}


def _labels(pairs):
    for k, lab in pairs:
        _FIELD_LABELS[k] = lab


