declare_fields("ntp", "Network Time Protocol", [
    ("ntp.flags.li", "int", "", "Leap indicator"),
    ("ntp.flags.vn", "int", "", "Version"),
    ("ntp.flags.mode", "int", "", "Mode: 3 client, 4 server"),
    ("ntp.stratum", "int", "", "Stratum: distance from a reference clock"),
    ("ntp.xmt", "str", "", "Transmit time"),
])
declare_fields("text", "Text protocol", [
    ("text.line", "str", "", "Line"),
])
declare_fields("data", "Data", [
    ("data.len", "int", "bytes", "Bytes not decoded further"),
])
_labels([(k, v[2].split(":")[0]) for k, v in FIELD_REGISTRY.items()])

_ARP_OPS = {1: "request (who has?)", 2: "reply"}
_ICMP_TYPES = {0: "Echo reply (ping answer)", 3: "Destination unreachable",
               5: "Redirect", 8: "Echo request (ping)", 11: "Time exceeded"}
_ICMPV6_TYPES = {1: "Destination unreachable", 2: "Packet too big",
                 3: "Time exceeded", 128: "Echo request (ping)",
                 129: "Echo reply", 133: "Router solicitation",
                 134: "Router advertisement", 135: "Neighbour solicitation",
                 136: "Neighbour advertisement", 143: "Multicast listener "
                 "report v2"}
_DNS_TYPES = {1: "A", 2: "NS", 5: "CNAME", 6: "SOA", 12: "PTR", 15: "MX",
              16: "TXT", 28: "AAAA", 33: "SRV", 41: "OPT", 47: "NSEC",
              64: "SVCB", 65: "HTTPS", 255: "ANY"}
_DNS_RCODES = {0: "no error", 1: "format error", 2: "server failure",
               3: "no such name", 4: "not implemented", 5: "refused"}
_DHCP_MSG = {1: "Discover", 2: "Offer", 3: "Request", 4: "Decline",
             5: "ACK", 6: "NAK", 7: "Release", 8: "Inform"}
_TLS_CT = {20: "Change cipher spec", 21: "Alert", 22: "Handshake",
           23: "Application data", 24: "Heartbeat"}
_TLS_HS = {1: "Client Hello", 2: "Server Hello", 4: "New session ticket",
           8: "Encrypted extensions", 11: "Certificate", 12: "Server key "
           "exchange", 13: "Certificate request", 14: "Server hello done",
           15: "Certificate verify", 16: "Client key exchange",
           20: "Finished"}
_TLS_VER = {0x0300: "SSL 3.0", 0x0301: "TLS 1.0", 0x0302: "TLS 1.1",
            0x0303: "TLS 1.2", 0x0304: "TLS 1.3"}
_HIDDEN_HEADERS = {"cookie", "set-cookie", "authorization",
                   "proxy-authorization", "x-api-key", "x-auth-token"}
_TEXT_PORTS = {21: "FTP", 25: "SMTP", 110: "POP3", 143: "IMAP", 587: "SMTP",
               22: "SSH", 23: "Telnet", 119: "NNTP", 6667: "IRC"}
_SECRET_CMDS = re.compile(
    rb"^(?:(?P<tag>[A-Za-z0-9.]+\s+)?(?P<cmd>PASS|AUTH|LOGIN|APOP|"
    rb"AUTHENTICATE)\b)(?P<rest>.*)$", re.I)


def _verify_l4(d, proto, off, length, csum_off, kind):
    """Checksum check of a TCP/UDP/ICMPv6 segment in place."""
    ipn = next((n for n in reversed(d.out.nodes) if n.key in ("ip",
                                                              "ipv6")), None)
    if ipn is None or off + length > len(d.raw):
        return "not checked"
    raw = d.raw
    seg = bytearray(raw[off:off + length])
    if seg[csum_off:csum_off + 2] == b"\x00\x00" and kind == "udp":
        return "none (allowed for UDP over IPv4)"
    seg[csum_off:csum_off + 2] = b"\x00\x00"
    if ipn.key == "ip":
        pseudo = raw[ipn.offset + 12:ipn.offset + 20] + struct.pack(
            "!BBH", 0, proto, length)
    else:
        pseudo = raw[ipn.offset + 8:ipn.offset + 40] + struct.pack(
            "!IxxxB", length, proto)
    c = _pk_csum(pseudo + bytes(seg))
    if kind == "udp" and c == 0:
        c = 0xFFFF
    want = struct.unpack_from("!H", raw, off + csum_off)[0]
    return "correct" if c == want else "incorrect"


def _dns_name(raw, off, base, depth=0):
    """→ (name, end offset of the name in place). Follows compression."""
    labels, end, jumps = [], None, 0
    while True:
        if off >= len(raw):
            raise _Cut()
        ln = raw[off]
        if ln == 0:
            off += 1
            break
        if ln & 0xC0 == 0xC0:
            if off + 1 >= len(raw):
                raise _Cut()
            ptr = ((ln & 0x3F) << 8) | raw[off + 1]
            if end is None:
                end = off + 2
            off = base + ptr
            jumps += 1
            if jumps > 20:
                raise ValueError("DNS name loop")
            continue
        off += 1
        labels.append(raw[off:off + ln].decode("utf-8", "replace"))
        off += ln
        if len(labels) > 64:
            raise ValueError("DNS name too long")
    return ".".join(labels) or "<root>", (end if end is not None else off)


def _dissect_dns(d, off, end, how, tcp=False):
    if tcp:
        d.begin("dns", off, end, how)
        ln = d.u16(off)
        d.add("data.len", ln, off, 2, f"{ln} (DNS over TCP length)")
        off += 2
    else:
        d.begin("dns", off, end, how)
    base = off
    d.add("dns.id", d.u16(off), off, 2, f"0x{d.u16(off):04x}")
    fl = d.u16(off + 2)
    ff = d.add("dns.flags.response", bool(fl & 0x8000), off + 2, 2,
               "response" if fl & 0x8000 else "query")
    for key, bit in (("dns.flags.authoritative", 0x0400),
                     ("dns.flags.truncated", 0x0200),
                     ("dns.flags.recdesired", 0x0100),
                     ("dns.flags.recavail", 0x0080)):
        d.add(key, bool(fl & bit), off + 2, 2, parent=ff)
    d.add("dns.flags.opcode", (fl >> 11) & 15, off + 2, 2, parent=ff)
    rc = fl & 15
    d.add("dns.flags.rcode", rc, off + 2, 2,
          f"{rc} ({_DNS_RCODES.get(rc, 'other')})", parent=ff,
          warning="" if rc in (0,) or not fl & 0x8000 else
          _DNS_RCODES.get(rc, "error"))
    counts = [d.u16(off + 4 + 2 * i) for i in range(4)]
    for key, i in (("dns.count.queries", 0), ("dns.count.answers", 1),
                   ("dns.count.auth_rr", 2), ("dns.count.add_rr", 3)):
        d.add(key, counts[i], off + 4 + 2 * i, 2)
    p = off + 12
    for _ in range(min(counts[0], 50)):
        name, q_end = _dns_name(d.raw, p, base)
        qt = d.u16(q_end)
        q = d.add("dns.qry.name", name, p, q_end + 4 - p,
                  f"{name}  (type {_DNS_TYPES.get(qt, qt)})")
        d.add("dns.qry.type", qt, q_end, 2,
              f"{_DNS_TYPES.get(qt, qt)} ({qt})", parent=q)
        p = q_end + 4
    for _ in range(min(sum(counts[1:]), 100)):
        name, n_end = _dns_name(d.raw, p, base)
        t, _cls, ttl, rdl = struct.unpack_from("!HHIH", d.raw, n_end) \
            if n_end + 10 <= len(d.raw) else (None, 0, 0, 0)
        if t is None:
            raise _Cut()
        rd = n_end + 10
        d.need(rd, rdl)
        tname = _DNS_TYPES.get(t, str(t))
        rr = d.add("dns.resp.name", name, p, rd + rdl - p,
                   f"{name}  {tname}")
        d.add("dns.resp.type", t, n_end, 2, f"{tname} ({t})", parent=rr)
        if t != 41:
            d.add("dns.resp.ttl", ttl, n_end + 4, 4, f"{ttl} s", parent=rr)
        if t == 1 and rdl == 4:
            v = _socket.inet_ntoa(d.raw[rd:rd + 4])
            d.add("dns.a", v, rd, 4, parent=rr)
            rr.value += f"  {v}"
        elif t == 28 and rdl == 16:
            v = _socket.inet_ntop(_socket.AF_INET6, d.raw[rd:rd + 16])
            d.add("dns.aaaa", v, rd, 16, parent=rr)
            rr.value += f"  {v}"
        elif t in (5, 12, 2):
            v, _e = _dns_name(d.raw, rd, base)
            d.add("dns.cname" if t == 5 else "dns.ptr.domain_name" if
                  t == 12 else "dns.resp.name", v, rd, rdl, parent=rr)
            rr.value += f"  {v}"
        elif t == 16:
            q = rd
            while q < rd + rdl:
                ln = d.raw[q]
                txt = d.raw[q + 1:q + 1 + ln].decode("utf-8", "replace")
                d.add("dns.txt", txt, q, 1 + ln, parent=rr)
                q += 1 + ln
        elif t == 33 and rdl >= 7:
            port = struct.unpack_from("!H", d.raw, rd + 4)[0]
            v, _e = _dns_name(d.raw, rd + 6, base)
            d.add("dns.srv.port", port, rd + 4, 2, parent=rr)
            d.add("dns.srv.target", v, rd + 6, rdl - 6, parent=rr)
            rr.value += f"  {v}:{port}"
        p = rd + rdl


def _dissect_dhcp(d, off, end, how):
    d.begin("dhcp", off, end, how)
    op = d.u8(off)
    d.add("dhcp.type", op, off, 1, f"{op} ({'request' if op == 1 else 'reply'})")
    d.add("dhcp.id", d.u32(off + 4), off + 4, 4, f"0x{d.u32(off + 4):08x}")
    for key, o in (("dhcp.ip.client", 12), ("dhcp.ip.your", 16),
                   ("dhcp.ip.server", 20), ("dhcp.ip.relay", 24)):
        d.need(off + o, 4)
        d.add(key, _socket.inet_ntoa(d.raw[off + o:off + o + 4]), off + o, 4)
    d.need(off + 28, 6)
    d.add("dhcp.hw.mac_addr", _fmt_mac(d.raw[off + 28:off + 34]), off + 28,
          16, _mac_desc(d.raw[off + 28:off + 34]))
    p = off + 236
    if d.raw[p:p + 4] != b"c\x82Sc":
        return
    d.add("dhcp.cookie", 0x63825363, p, 4, "DHCP")
    p += 4
    while p < end:
        code = d.u8(p)
        if code == 255:
            d.add("dhcp.option.other", 255, p, 1, "End")
            break
        if code == 0:
            p += 1
            continue
        ln = d.u8(p + 1)
        d.need(p + 2, ln)
        v = d.raw[p + 2:p + 2 + ln]
        ip = _socket.inet_ntoa(v[:4]) if ln >= 4 else ""
        if code == 53 and ln == 1:
            d.add("dhcp.option.dhcp", v[0], p, 2 + ln,
                  f"{_DHCP_MSG.get(v[0], v[0])} ({v[0]})")
        elif code == 12:
            d.add("dhcp.option.hostname", v.decode("utf-8", "replace"), p,
                  2 + ln)
        elif code == 50 and ln == 4:
            d.add("dhcp.option.requested_ip_address", ip, p, 2 + ln)
        elif code == 51 and ln == 4:
            s = struct.unpack("!I", v)[0]
            d.add("dhcp.option.ip_address_lease_time", s, p, 2 + ln,
                  f"{s} s ({human_duration(s)})")
        elif code == 3 and ln >= 4:
            d.add("dhcp.option.router", ip, p, 2 + ln)
        elif code == 6 and ln >= 4:
            d.add("dhcp.option.domain_name_server", ip, p, 2 + ln,
                  ", ".join(_socket.inet_ntoa(v[i:i + 4])
                            for i in range(0, ln - ln % 4, 4)))
        elif code == 54 and ln == 4:
            d.add("dhcp.option.dhcp_server_id", ip, p, 2 + ln)
        elif code == 60:
            d.add("dhcp.option.vendor_class_id",
                  v.decode("utf-8", "replace"), p, 2 + ln)
        elif code == 55:
            d.add("dhcp.option.request_list", ",".join(str(x) for x in v),
                  p, 2 + ln)
        elif code == 61:
            d.add("dhcp.option.client_id", v.hex(), p, 2 + ln)
        else:
            d.add("dhcp.option.other", code, p, 2 + ln,
                  f"option {code}: {v[:32].hex()}")
        p += 2 + ln


def _dissect_tls(d, off, end, how):
    d.begin("tls", off, end, how)
    p = off
    n = 0
    while p + 5 <= end and n < 16:
        ct, ver, ln = d.raw[p], d.u16(p + 1), d.u16(p + 3)
        if ct not in _TLS_CT or ver >> 8 != 3:
            break
        rec = d.add("tls.record.content_type", ct, p, min(5 + ln, end - p),
                    f"{_TLS_CT[ct]} ({ct})")
        d.add("tls.record.version", ver, p + 1, 2,
              _TLS_VER.get(ver, f"0x{ver:04x}"), parent=rec)
        d.add("tls.record.length", ln, p + 3, 2, parent=rec)
        body = p + 5
        if p + 5 + ln > end:
            rec.warning = "continues in the next segment"
        if ct == 22 and body + 4 <= end:
            ht = d.raw[body]
            hs = d.add("tls.handshake.type", ht, body, 4,
                       f"{_TLS_HS.get(ht, ht)} ({ht})", parent=rec)
            if ht in (1, 2) and body + 6 <= end:
                _tls_hello(d, body + 4, min(end, body + 4 + ((
                    d.raw[body + 1] << 16) | d.u16(body + 2))), ht, hs)
        elif ct == 23:
            d.add("tls.app_data", f"{ln} bytes", body,
                  min(ln, end - body), "encrypted — content is not "
                  "visible", parent=rec)
        p += 5 + ln
        n += 1


def _tls_hello(d, p, end, ht, parent):
    try:
        ver = d.u16(p)
        d.add("tls.handshake.version", ver, p, 2,
              _TLS_VER.get(ver, f"0x{ver:04x}"), parent=parent)
        p += 2 + 32
        sid = d.u8(p)
        p += 1 + sid
        if ht == 1:
            n = d.u16(p)
            d.add("tls.handshake.ciphersuites_count", n // 2, p, 2 + n,
                  parent=parent)
            p += 2 + n
            p += 1 + d.u8(p)
        else:
            p += 3
        if p + 2 > end:
            return
        ext_end = min(end, p + 2 + d.u16(p))
        p += 2
        while p + 4 <= ext_end:
            et, el = d.u16(p), d.u16(p + 2)
            body = p + 4
            if et == 0 and el >= 5:
                nl = d.u16(body + 3)
                host = d.raw[body + 5:body + 5 + nl].decode("ascii",
                                                             "replace")
                d.add("tls.handshake.extensions_server_name", host, p,
                      4 + el, parent=parent)
            elif et == 16 and el >= 2:
                q, names = body + 2, []
                while q < body + el:
                    ln = d.raw[q]
                    names.append(d.raw[q + 1:q + 1 + ln].decode("ascii",
                                                                "replace"))
                    q += 1 + ln
                d.add("tls.handshake.extensions_alpn_str", ", ".join(names),
                      p, 4 + el, parent=parent)
            elif et == 43:
                vals = d.raw[body + (1 if ht == 1 else 0):body + el]
                for i in range(0, len(vals) - 1, 2):
                    v = struct.unpack_from("!H", vals, i)[0]
                    d.add("tls.handshake.extensions.supported_version", v,
                          p, 4 + el, _TLS_VER.get(v, f"0x{v:04x}"),
                          parent=parent)
            p = body + el
    except _Cut:
        parent.warning = "continues in the next segment"


def _dissect_quic(d, off, end, how):
    d.begin("quic", off, end, how)
    b0 = d.u8(off)
    if not b0 & 0x80:
        d.add("quic.header_form", "short", off, 1,
              "short header (after the handshake)")
        d.add("quic.payload", f"{end - off - 1} bytes", off + 1,
              end - off - 1, "encrypted — content is not visible")
        return
    d.add("quic.header_form", "long", off, 1, "long header (handshake)")
    ver = d.u32(off + 1)
    d.add("quic.version", ver, off + 1, 4,
          {1: "1 (RFC 9000)", 0x6B3343CF: "2 (RFC 9369)", 0: "version "
           "negotiation"}.get(ver, f"0x{ver:08x}"))
    ptype = (b0 >> 4) & 3
    d.add("quic.long.packet_type", ptype, off, 1,
          ("Initial", "0-RTT", "Handshake", "Retry")[ptype])
    p = off + 5
    dl = d.u8(p)
    d.add("quic.dcid", d.raw[p + 1:p + 1 + dl].hex(), p, 1 + dl)
    p += 1 + dl
    sl = d.u8(p)
    d.add("quic.scid", d.raw[p + 1:p + 1 + sl].hex(), p, 1 + sl)
    p += 1 + sl
    d.add("quic.payload", f"{max(0, end - p)} bytes", p, max(0, end - p),
          "protected — only the first packet's site name can be read, "
          "and only by decrypting it with keys anyone can derive")


def _dissect_http(d, off, end, how):
    data = d.raw[off:end]
    head, sep, _body = data.partition(b"\r\n\r\n")
    lines = head.split(b"\r\n")
    first = lines[0].decode("latin-1", "replace")
    d.begin("http", off, end, how)
    m = re.match(r"^([A-Z]+) (\S+) (HTTP/\d\.\d)$", first)
    r = re.match(r"^(HTTP/\d\.\d) (\d{3}) ?(.*)$", first)
    if m:
        d.add("http.request.method", m.group(1), off, len(m.group(1)))
        uri = m.group(2)
        d.add("http.request.uri", uri, off + len(m.group(1)) + 1, len(uri),
              uri if len(uri) < 200 else uri[:200] + "…")
        d.add("http.request.version", m.group(3), off + len(first) -
              len(m.group(3)), len(m.group(3)))
    elif r:
        d.add("http.request.version", r.group(1), off, len(r.group(1)))
        d.add("http.response.code", int(r.group(2)), off + 9, 3)
        d.add("http.response.phrase", r.group(3), off + 13,
              max(0, len(first) - 13))
    else:
        d.add("text.line", first[:200], off, len(lines[0]))
    p = off + len(lines[0]) + 2
    for line in lines[1:60]:
        k, _c, v = line.decode("latin-1", "replace").partition(":")
        v = v.strip()
        kl = k.strip().lower()
        shown = "(hidden: may contain a password or session)" \
            if kl in _HIDDEN_HEADERS else v[:200]
        key = {"host": "http.host", "user-agent": "http.user_agent",
               "server": "http.server",
               "content-length": "http.content_length"}.get(kl,
                                                            "http.header")
        val = int(v) if key == "http.content_length" and v.isdigit() \
            else (shown if key == "http.header" else v[:200])
        d.add(key, val, p, len(line), f"{k.strip()}: {shown}"
              if key == "http.header" else None)
        p += len(line) + 2
    if not sep:
        d.node.warning = "headers continue in the next segment"


_MAIL_LABEL_VERBS = {"EHLO", "HELO", "STARTTLS", "QUIT", "MAIL", "RCPT",
                     "DATA", "AUTH", "LOGIN", "AUTHENTICATE", "USER", "PASS",
                     "APOP", "SELECT", "EXAMINE", "FETCH", "LOGOUT", "CAPA",
                     "STLS", "RETR", "TOP", "LIST", "UIDL", "STAT", "NOOP",
                     "RSET", "CAPABILITY", "IDLE", "DELE", "UID", "SEARCH",
                     "STORE", "EXPUNGE", "CLOSE", "NAMESPACE", "ID", "ENABLE"}


def _mail_line_label(line):
    """Mail lines in the packet tree: command names and reply codes only
    (addresses, subjects and contents are never shown)."""
    words = [w.decode("latin-1", "replace").upper()
             for w in line.split()[:3]]
    if not words:
        return "(blank line)"
    if re.match(r"^\d{3}(-.*)?$|^\+OK$|^-ERR$", words[0]):
        return f"reply {words[0][:4]} (text hidden)"
    for w in words[:2]:
        if w in ("OK", "NO", "BAD", "BYE", "PREAUTH") or w.startswith("*"):
            return f"reply {w} (text hidden)" if w != "*" else \
                "server status line (text hidden)"
        verb = w.split(":", 1)[0]
        if verb in _MAIL_LABEL_VERBS:
            return f"command {verb} (details hidden)"
    return "(content hidden: Email Traffic shows metadata only)"


def _dissect_text_lines(d, off, end, proto_name, how):
    d.begin("text", off, end, how, title=f"{proto_name} (text)")
    p = off
    for line in d.raw[off:end].split(b"\n")[:30]:
        clean = line.rstrip(b"\r")
        m = _SECRET_CMDS.match(clean)
        if m:
            shown = ((m.group("tag") or b"") + m.group("cmd")).decode(
                "latin-1", "replace") + " (hidden: credentials)"
        elif proto_name in ("SMTP", "POP3", "IMAP"):
            shown = _mail_line_label(clean)
        else:
            shown = clean.decode("utf-8", "replace")[:200]
        if clean or p < end:
            d.add("text.line", shown, p, len(line))
        p += len(line) + 1
        if p >= end:
            break


def _dissect_ntp(d, off, end, how):
    d.begin("ntp", off, end, how)
    b0 = d.u8(off)
    d.add("ntp.flags.li", b0 >> 6, off, 1)
    d.add("ntp.flags.vn", (b0 >> 3) & 7, off, 1)
    mode = b0 & 7
    mname = {3: "client", 4: "server", 5: "broadcast"}.get(mode, "other")
    d.add("ntp.flags.mode", mode, off, 1, f"{mode} ({mname})")
    d.add("ntp.stratum", d.u8(off + 1), off + 1, 1)
    sec = d.u32(off + 40)
    d.add("ntp.xmt", sec, off + 40, 8,
          "not set" if sec == 0 else fmt_clock(sec - 2208988800, True))


def _app_layer(d, off, end, transport, sport, dport):
    """Pick the application dissector: by content first, then by port."""
    if end <= off:
        return
    data = d.raw[off:end]
    ports = (sport, dport)
    if transport == "tcp":
        if data[:1] in (b"\x14", b"\x15", b"\x16", b"\x17") and \
                data[1:2] == b"\x03":
            return _dissect_tls(d, off, end, "recognised from the content")
        if re.match(rb"^(GET|POST|PUT|HEAD|DELETE|OPTIONS|PATCH|CONNECT) "
                    rb"\S+ HTTP/1\.[01]\r\n|^HTTP/1\.[01] \d{3}", data):
            return _dissect_http(d, off, end, "recognised from the content")
        if 53 in ports:
            return _dissect_dns(d, off, end, "port 53", tcp=True)
        for p in ports:
            if p in _TEXT_PORTS:
                return _dissect_text_lines(d, off, end, _TEXT_PORTS[p],
                                           f"port {p}")
        if data.startswith(b"SSH-"):
            return _dissect_text_lines(d, off, end, "SSH",
                                       "recognised from the content")
    else:
        if ports[0] in (67, 68) or ports[1] in (67, 68):
            return _dissect_dhcp(d, off, end, "port 67/68")
        dns_ports = [p for p in ports if p in (53, 5353, 5355)]
        if dns_ports:
            return _dissect_dns(d, off, end, f"port {dns_ports[0]}")
        if 123 in ports and len(data) >= 48:
            return _dissect_ntp(d, off, end, "port 123")
        if 443 in ports and data[:1] and (data[0] & 0x40):
            return _dissect_quic(d, off, end, "port 443")
        if 1900 in ports:
            return _dissect_http(d, off, end, "port 1900 (SSDP)")
    d.begin("data", off, end)
    d.add("data.len", end - off, off, end - off, f"{end - off} bytes")


def _dissect_tcp(d, off, end):
    d.begin("tcp", off, end)
    sp, dp = d.u16(off), d.u16(off + 2)
    d.add("tcp.srcport", sp, off, 2)
    d.add("tcp.dstport", dp, off + 2, 2)
    d.add("tcp.seq_raw", d.u32(off + 4), off + 4, 4)
    d.add("tcp.ack_raw", d.u32(off + 8), off + 8, 4)
    hl = (d.u8(off + 12) >> 4) * 4
    d.add("tcp.hdr_len", hl, off + 12, 1, f"{hl} bytes",
          warning="" if hl >= 20 else "too short")
    fl = d.u8(off + 13)
    names = [n for n, b in (("FIN", 1), ("SYN", 2), ("RST", 4), ("PSH", 8),
                            ("ACK", 16), ("URG", 32)) if fl & b]
    ff = d.add("tcp.flags", fl, off + 12, 2, f"0x{fl:03x} "
               f"({', '.join(names) or 'none'})")
    for key, b in (("tcp.flags.syn", 2), ("tcp.flags.ack", 16),
                   ("tcp.flags.push", 8), ("tcp.flags.fin", 1),
                   ("tcp.flags.reset", 4), ("tcp.flags.urg", 32)):
        d.add(key, bool(fl & b), off + 13, 1, parent=ff)
    d.add("tcp.window_size_value", d.u16(off + 14), off + 14, 2)
    d.add("tcp.checksum", d.u16(off + 16), off + 16, 2,
          f"0x{d.u16(off + 16):04x}")
    st = _verify_l4(d, 6, off, end - off, 16, "tcp")
    d.add("tcp.checksum.status", st, off + 16, 2, warning="checksum does "
          "not match (normal for packets this computer sends when the card "
          "computes it)" if st == "incorrect" else "")
    d.add("tcp.urgent_pointer", d.u16(off + 18), off + 18, 2)
    p, oend = off + 20, off + max(20, hl)
    while p < oend:
        kind = d.u8(p)
        if kind == 0:
            break
        if kind == 1:
            p += 1
            continue
        ln = d.u8(p + 1)
        if ln < 2:
            d.node.warning = "malformed TCP option"
            break
        if kind == 2 and ln == 4:
            d.add("tcp.options.mss_val", d.u16(p + 2), p, 4)
        elif kind == 3 and ln == 3:
            d.add("tcp.options.wscale.shift", d.u8(p + 2), p, 3,
                  f"{d.u8(p + 2)} (×{1 << min(d.u8(p + 2), 14)})")
        elif kind == 4:
            d.add("tcp.options.sack_perm", True, p, ln)
        elif kind == 5:
            blocks = [f"{d.u32(p + 2 + i)}-{d.u32(p + 6 + i)}"
                      for i in range(0, ln - 2, 8)]
            d.add("tcp.options.sack", ", ".join(blocks), p, ln)
        elif kind == 8 and ln == 10:
            d.add("tcp.options.timestamp.tsval", d.u32(p + 2), p + 2, 4)
            d.add("tcp.options.timestamp.tsecr", d.u32(p + 6), p + 6, 4)
        p += ln
    pay = off + hl
    d.add("tcp.len", max(0, end - pay), off, 0, f"{max(0, end - pay)} bytes")
    _app_layer(d, pay, end, "tcp", sp, dp)


def _dissect_udp(d, off, end):
    d.begin("udp", off, end)
    sp, dp, ln = d.u16(off), d.u16(off + 2), d.u16(off + 4)
    d.add("udp.srcport", sp, off, 2)
    d.add("udp.dstport", dp, off + 2, 2)
    d.add("udp.length", ln, off + 4, 2, warning="" if off + ln <= len(
        d.raw) else "longer than the packet (truncated)")
    d.add("udp.checksum", d.u16(off + 6), off + 6, 2,
          f"0x{d.u16(off + 6):04x}")
    seg_end = min(end, off + ln) if ln >= 8 else end
    st = _verify_l4(d, 17, off, seg_end - off, 6, "udp")
    d.add("udp.checksum.status", st, off + 6, 2,
          warning="checksum does not match" if st == "incorrect" else "")
    _app_layer(d, off + 8, seg_end, "udp", sp, dp)


def _dissect_icmp(d, off, end):
    d.begin("icmp", off, end)
    t, c = d.u8(off), d.u8(off + 1)
    d.add("icmp.type", t, off, 1, f"{t} ({_ICMP_TYPES.get(t, 'other')})")
    d.add("icmp.code", c, off + 1, 1)
    d.add("icmp.checksum", d.u16(off + 2), off + 2, 2,
          f"0x{d.u16(off + 2):04x}")
    if t in (0, 8):
        d.add("icmp.ident", d.u16(off + 4), off + 4, 2)
        d.add("icmp.seq", d.u16(off + 6), off + 6, 2)


def _dissect_icmpv6(d, off, end):
    d.begin("icmpv6", off, end)
    t, c = d.u8(off), d.u8(off + 1)
    d.add("icmpv6.type", t, off, 1, f"{t} ({_ICMPV6_TYPES.get(t, 'other')})")
    d.add("icmpv6.code", c, off + 1, 1)
    d.add("icmpv6.checksum", d.u16(off + 2), off + 2, 2,
          f"0x{d.u16(off + 2):04x}")
    p = off + 4
    if t == 134:
        d.add("icmpv6.nd.ra.cur_hop_limit", d.u8(p), p, 1)
        d.add("icmpv6.nd.ra.flag", d.u8(p + 1), p + 1, 1,
              f"0x{d.u8(p + 1):02x}")
        d.add("icmpv6.nd.ra.router_lifetime", d.u16(p + 2), p + 2, 2,
              f"{d.u16(p + 2)} s")
        p += 12
    elif t in (135, 136):
        if t == 136:
            d.add("icmpv6.nd.na.flag", d.u32(p) >> 29, p, 4,
                  ", ".join(n for n, b in (("router", 4), ("solicited", 2),
                                           ("override", 1))
                            if (d.u32(p) >> 29) & b) or "none")
        d.need(p + 4, 16)
        d.add("icmpv6.nd.target", _socket.inet_ntop(
            _socket.AF_INET6, d.raw[p + 4:p + 20]), p + 4, 16)
        p += 20
    elif t == 133:
        p += 4
    else:
        return
    while p + 2 <= end:
        ot, ol = d.u8(p), d.u8(p + 1) * 8
        if ol == 0:
            d.node.warning = "malformed option (length 0)"
            break
        o = d.add("icmpv6.opt.type", ot, p, ol, {1: "Source link-layer "
                                                  "address", 2: "Target "
                                                  "link-layer address",
                                                  3: "Prefix information",
                                                  5: "MTU", 25: "DNS "
                                                  "servers (RDNSS)"}.get(
            ot, f"option {ot}"))
        if ot in (1, 2) and ol >= 8:
            d.add("icmpv6.opt.linkaddr", _fmt_mac(d.raw[p + 2:p + 8]), p + 2,
                  6, _mac_desc(d.raw[p + 2:p + 8]), parent=o)
        elif ot == 3 and ol >= 32:
            d.add("icmpv6.opt.prefix.length", d.u8(p + 2), p + 2, 1,
                  parent=o)
            d.need(p + 16, 16)
            d.add("icmpv6.opt.prefix", _socket.inet_ntop(
                _socket.AF_INET6, d.raw[p + 16:p + 32]), p + 16, 16,
                parent=o)
        p += ol


def _dissect_ipv4(d, off):
    d.begin("ip", off)
    b0 = d.u8(off)
    hl = (b0 & 15) * 4
    tl = d.u16(off + 2)
    end = min(len(d.raw), off + tl) if tl >= hl else len(d.raw)
    d.node.length = end - off
    d.add("ip.version", b0 >> 4, off, 1)
    d.add("ip.hdr_len", hl, off, 1, f"{hl} bytes",
          warning="" if hl >= 20 else "too short")
    d.add("ip.dsfield", d.u8(off + 1), off + 1, 1, f"0x{d.u8(off + 1):02x}")
    d.add("ip.len", tl, off + 2, 2, warning="" if off + tl <= len(d.raw)
          else "longer than the captured frame (truncated capture)")
    d.add("ip.id", d.u16(off + 4), off + 4, 2, f"0x{d.u16(off + 4):04x}")
    fr = d.u16(off + 6)
    d.add("ip.flags.df", bool(fr & 0x4000), off + 6, 1)
    d.add("ip.flags.mf", bool(fr & 0x2000), off + 6, 1)
    fo = (fr & 0x1FFF) * 8
    d.add("ip.frag_offset", fo, off + 6, 2)
    d.add("ip.ttl", d.u8(off + 8), off + 8, 1)
    proto = d.u8(off + 9)
    d.add("ip.proto", proto, off + 9, 1,
          f"{_IP_PROTOS.get(proto, 'other')} ({proto})")
    d.add("ip.checksum", d.u16(off + 10), off + 10, 2,
          f"0x{d.u16(off + 10):04x}")
    d.need(off, hl)
    hdr = bytearray(d.raw[off:off + hl])
    hdr[10:12] = b"\x00\x00"
    ok = _pk_csum(bytes(hdr)) == d.u16(off + 10)
    d.add("ip.checksum.status", "correct" if ok else "incorrect", off + 10, 2,
          warning="" if ok else "checksum does not match (normal for "
          "packets this computer sends when the card computes it)")
    d.add("ip.src", _socket.inet_ntoa(d.raw[off + 12:off + 16]), off + 12, 4)
    d.add("ip.dst", _socket.inet_ntoa(d.raw[off + 16:off + 20]), off + 16, 4)
    if hl > 20:
        d.add("ip.options", d.raw[off + 20:off + hl].hex(), off + 20, hl - 20)
    if fr & 0x2000 or fo:
        d.node.warning = (f"fragment at offset {fo}"
                          + (" (more follow)" if fr & 0x2000 else
                             " (last piece)"))
        if fo:
            d.begin("data", off + hl, end)
            d.add("data.len", end - off - hl, off + hl, end - off - hl,
                  f"{end - off - hl} bytes (rest of a fragmented packet)")
            return
    _next_proto(d, proto, off + hl, end)


def _dissect_ipv6(d, off):
    d.begin("ipv6", off)
    w = d.u32(off)
    plen = d.u16(off + 4)
    end = min(len(d.raw), off + 40 + plen)
    d.node.length = end - off
    d.add("ipv6.version", w >> 28, off, 1)
    d.add("ipv6.tclass", (w >> 20) & 0xFF, off, 2, f"0x{(w >> 20) & 0xFF:02x}")
    d.add("ipv6.flow", w & 0xFFFFF, off + 1, 3, f"0x{w & 0xFFFFF:05x}")
    d.add("ipv6.plen", plen, off + 4, 2, warning="" if off + 40 + plen <=
          len(d.raw) else "longer than the captured frame")
    nh = d.u8(off + 6)
    d.add("ipv6.nxt", nh, off + 6, 1, f"{_IP_PROTOS.get(nh, nh)} ({nh})")
    d.add("ipv6.hlim", d.u8(off + 7), off + 7, 1)
    d.need(off + 8, 32)
    d.add("ipv6.src", _socket.inet_ntop(_socket.AF_INET6,
                                        d.raw[off + 8:off + 24]), off + 8, 16)
    d.add("ipv6.dst", _socket.inet_ntop(_socket.AF_INET6,
                                        d.raw[off + 24:off + 40]), off + 24,
          16)
    p = off + 40
    hops = 0
    while nh in (0, 43, 44, 60) and hops < 8:
        hops += 1
        nxt = d.u8(p)
        if nh == 44:
            fo = d.u16(p + 2)
            x = d.add("ipv6.ext", "fragment", p, 8, "Fragment header")
            d.add("ipv6.fragment.offset", (fo >> 3) * 8, p + 2, 2, parent=x)
            d.add("ipv6.fragment.more", bool(fo & 1), p + 2, 2, parent=x)
            d.add("ipv6.fragment.id", d.u32(p + 4), p + 4, 4,
                  f"0x{d.u32(p + 4):08x}", parent=x)
            if fo >> 3:
                d.node.warning = "fragment (not the first piece)"
                return
            p += 8
        else:
            ln = (d.u8(p + 1) + 1) * 8
            d.add("ipv6.ext", {0: "hop-by-hop", 43: "routing",
                               60: "destination options"}[nh], p, ln)
            p += ln
        nh = nxt
    _next_proto(d, nh, p, end)


def _next_proto(d, proto, off, end):
    if proto == 6:
        _dissect_tcp(d, off, end)
    elif proto == 17:
        _dissect_udp(d, off, end)
    elif proto == 1:
        _dissect_icmp(d, off, end)
    elif proto == 58:
        _dissect_icmpv6(d, off, end)
    elif end > off:
        d.begin("data", off, end)
        d.add("data.len", end - off, off, end - off,
              f"{end - off} bytes ({_IP_PROTOS.get(proto, 'protocol')} "
              f"{proto})")


def _dissect_ethertype(d, et, off):
    if et == 0x0800:
        _dissect_ipv4(d, off)
    elif et == 0x86DD:
        _dissect_ipv6(d, off)
    elif et == 0x0806:
        d.begin("arp", off, min(len(d.raw), off + 28))
        d.add("arp.hw.type", d.u16(off), off, 2)
        d.add("arp.proto.type", d.u16(off + 2), off + 2, 2,
              f"0x{d.u16(off + 2):04x}")
        op = d.u16(off + 6)
        d.add("arp.opcode", op, off + 6, 2, f"{op} ({_ARP_OPS.get(op, '?')})")
        d.need(off + 8, 20)
        d.add("arp.src.hw_mac", _fmt_mac(d.raw[off + 8:off + 14]), off + 8,
              6, _mac_desc(d.raw[off + 8:off + 14]))
        d.add("arp.src.proto_ipv4", _socket.inet_ntoa(
            d.raw[off + 14:off + 18]), off + 14, 4)
        d.add("arp.dst.hw_mac", _fmt_mac(d.raw[off + 18:off + 24]), off + 18,
              6)
        d.add("arp.dst.proto_ipv4", _socket.inet_ntoa(
            d.raw[off + 24:off + 28]), off + 24, 4)
    elif et in (0x8100, 0x88A8):
        d.begin("vlan", off, off + 4)
        tci = d.u16(off)
        d.add("vlan.priority", tci >> 13, off, 2)
        d.add("vlan.id", tci & 0xFFF, off, 2)
        inner = d.u16(off + 2)
        d.add("vlan.etype", inner, off + 2, 2,
              f"{_ETHERTYPES.get(inner, 'other')} (0x{inner:04x})")
        _dissect_ethertype(d, inner, off + 4)
    elif off < len(d.raw):
        d.begin("data", off)
        d.add("data.len", len(d.raw) - off, off, len(d.raw) - off,
              f"{len(d.raw) - off} bytes ({_ETHERTYPES.get(et, 'type')} "
              f"0x{et:04x})")


def dissect(raw, linktype=1):
    """Raw frame → Dissection. Never raises."""
    raw = bytes(raw or b"")
    out = Dissection(raw, linktype)
    d = _D(out)
    d.begin("frame", 0, len(raw), title=f"Frame: {len(raw)} bytes")
    d.add("frame.len", len(raw), 0, 0, f"{len(raw)} bytes")
    d.add("frame.linktype", linktype, 0, 0,
          {1: "Ethernet", 101: "raw IP", 12: "raw IP", 113: "Linux cooked",
           228: "raw IPv4", 229: "raw IPv6"}.get(linktype, str(linktype)))
    try:
        if linktype == 1:
            d.begin("eth", 0, 14)
            d.need(0, 14)
            d.add("eth.dst", _fmt_mac(raw[0:6]), 0, 6, _mac_desc(raw[0:6]))
            d.add("eth.src", _fmt_mac(raw[6:12]), 6, 6, _mac_desc(raw[6:12]))
            et = d.u16(12)
            d.add("eth.type", et, 12, 2,
                  f"{_ETHERTYPES.get(et, 'other')} (0x{et:04x})")
            if et >= 0x0600:
                _dissect_ethertype(d, et, 14)
        elif linktype in (101, 12, 228, 229):
            v = raw[0] >> 4 if raw else 0
            (_dissect_ipv4 if v == 4 else _dissect_ipv6)(d, 0)
        elif linktype == 113:
            d.begin("sll", 0, 16)
            d.add("sll.pkttype", d.u16(0), 0, 2)
            alen = d.u16(4)
            d.add("sll.src.eth", _fmt_mac(raw[6:6 + min(alen, 6)]), 6, 8)
            et = d.u16(14)
            d.add("sll.etype", et, 14, 2,
                  f"{_ETHERTYPES.get(et, 'other')} (0x{et:04x})")
            _dissect_ethertype(d, et, 16)
        else:
            d.begin("data", 0)
            d.add("data.len", len(raw), 0, len(raw),
                  f"{len(raw)} bytes (link type {linktype})")
    except _Cut:
        if out.nodes:
            out.nodes[-1].warning = (out.nodes[-1].warning + "; "
                                     if out.nodes[-1].warning else "") + \
                "truncated: the packet ends early"
    except (ValueError, IndexError, struct.error, OSError) as e:
        if out.nodes:
            out.nodes[-1].warning = f"malformed ({e})"
    return out


def hex_dump_lines(raw):
    """Hex view text: 16 bytes per line, offset · hex · ASCII."""
    out = []
    for i in range(0, len(raw), 16):
        chunk = raw[i:i + 16]
        hx = " ".join(f"{b:02x}" for b in chunk)
        asc = "".join(chr(b) if 32 <= b < 127 else "." for b in chunk)
        out.append(f"{i:04x}  {hx:<47}  {asc}")
    return "\n".join(out)


def hex_dump_ranges(offset, length):
    """Tk text index ranges (start, end) covering bytes [offset, offset +
    length) in hex_dump_lines() output, for both the hex and ASCII
    columns."""
    out = []
    end = offset + max(1, length)
    p = offset
    while p < end:
        line = p // 16
        a, b = p % 16, min(16, (end - line * 16))
        out.append((f"{line + 1}.{6 + 3 * a}", f"{line + 1}.{6 + 3 * b - 1}"))
        out.append((f"{line + 1}.{55 + a}", f"{line + 1}.{55 + b}"))
        p = (line + 1) * 16
    return out


# ============================================================================
#  V5: reassembly — IP fragments, TCP streams, message framing
#
#  Mail, HTTP and DNS-over-TCP span segments, so they are read from the
#  reassembled stream, never from single packets. Rules: memory is
#  bounded everywhere; the first copy of a byte wins and a conflicting
#  overlap is flagged (a known evasion trick); a stream may start in the
#  middle; sequence numbers wrap at 2^32; and a message with a hole is
#  shown as partial with the hole's byte range — never as complete.
# ============================================================================
class IpDefragmenter:
    """Puts IPv4/IPv6 fragments back together. Keyed by (src, dst,
    protocol, id); 30 s timeout; 64 KB per datagram; bounded in total."""

    def __init__(self, timeout=30.0, max_datagram=65535,
                 max_total=8 * 1024 * 1024, max_pending=1024):
        self.timeout, self.max_datagram = timeout, max_datagram
        self.max_total, self.max_pending = max_total, max_pending
        self.pending = OrderedDict()   # key -> state dict
        self.total = 0
        self.completed = self.expired = self.overlaps = 0
        self.conflicts = self.too_big = 0

    def _expire(self, now):
        while self.pending:
            k, st = next(iter(self.pending.items()))
            if now - st["first"] <= self.timeout and \
                    self.total <= self.max_total and \
                    len(self.pending) <= self.max_pending:
                break
            self.pending.popitem(last=False)
            self.total -= st["bytes"]
            self.expired += 1

    def add(self, key, offset, more, data, now):
        """→ (datagram payload or None, warning or "")."""
        self._expire(now)
        if offset + len(data) > self.max_datagram:
            self.too_big += 1
            self.pending.pop(key, None)
            return None, "fragment would make the packet too large"
        st = self.pending.get(key)
        if st is None:
            st = self.pending[key] = {"first": now, "out": bytearray(),
                                      "filled": bytearray(), "covered": 0,
                                      "bytes": 0, "end": None, "warn": ""}
        # 5.3.4 (QA-06): one buffer per datagram, written once per byte;
        # the first copy of a byte wins and the datagram is finished when
        # the covered count reaches the end (no rebuild per fragment)
        warn = ""
        out, filled = st["out"], st["filled"]
        hi = offset + len(data)
        if hi > len(out):
            grow = hi - len(out)
            out += bytes(grow)
            filled += bytes(grow)
            st["bytes"] += grow
            self.total += grow
        seen = filled[offset:hi]
        if not seen.count(1):
            out[offset:hi] = data
            filled[offset:hi] = b"\x01" * len(data)
            st["covered"] += len(data)
        else:
            self.overlaps += 1
            differ = False
            for i, b in enumerate(data):
                if seen[i]:
                    differ = differ or out[offset + i] != b
                else:
                    out[offset + i] = b
                    filled[offset + i] = 1
                    st["covered"] += 1
            if differ:
                self.conflicts += 1
                warn = st["warn"] = ("overlapping fragments with "
                                     "different content (a known way "
                                     "to hide traffic from monitors); "
                                     "the first copy was kept")
            else:
                warn = "overlapping fragments (identical content)"
        if not more:
            st["end"] = hi
        end = st["end"]
        if end is None or st["covered"] < end or \
                filled[:end].count(0):
            return None, warn
        self.pending.pop(key, None)
        self.total -= st["bytes"]
        self.completed += 1
        return bytes(out[:end]), warn or st["warn"]


class StreamMessage:
    """One application message read from a stream direction."""
    __slots__ = ("direction", "start", "end", "data", "partial", "gaps",
                 "kind")

    def __init__(self, direction, start, data, kind="", gaps=()):
        self.direction, self.start, self.data = direction, start, data
        self.end = start + len(data)
        self.kind = kind
        self.gaps = list(gaps)
        self.partial = bool(self.gaps)

    def key(self):
        return (self.direction, self.start, self.end, self.kind,
                bytes(self.data), tuple(self.gaps))

    def __repr__(self):
        return (f"<{self.kind} dir={self.direction} {self.start}-{self.end}"
                f"{' partial' if self.partial else ''}>")


class LineFramer:
    """Line protocols (SMTP, IMAP, POP3, FTP): one message per line."""
    kind = "line"
    MAX = 8192

    def __init__(self):
        self.buf, self.start, self.gaps = bytearray(), 0, []

    def feed(self, off, data, out, direction):
        if not self.buf:
            self.start = off
        self.buf += data
        while True:
            i = self.buf.find(b"\n")
            if i < 0:
                if len(self.buf) > self.MAX:
                    out.append(StreamMessage(direction, self.start,
                                             bytes(self.buf), self.kind,
                                             self.gaps + [("too long", "")]))
                    self.start += len(self.buf)
                    self.buf, self.gaps = bytearray(), []
                return
            line = bytes(self.buf[:i + 1])
            out.append(StreamMessage(direction, self.start, line, self.kind,
                                     self.gaps))
            self.start += len(line)
            del self.buf[:i + 1]
            self.gaps = []

    def gap(self, start, end, out, direction):
        if self.buf:
            out.append(StreamMessage(direction, self.start, bytes(self.buf),
                                     self.kind, self.gaps +
                                     [(start, end)]))
            self.buf = bytearray()
        self.gaps = [(start, end)]
        self.start = end

    def flush(self, out, direction):
        if self.buf:
            out.append(StreamMessage(direction, self.start, bytes(self.buf),
                                     self.kind, self.gaps +
                                     [("unterminated", "")]))
            self.buf = bytearray()


class LengthFramer:
    """Length-prefixed records: TLS (5-byte header) or DNS over TCP
    (2-byte length)."""

    def __init__(self, kind="tls"):
        self.kind = kind
        self.buf, self.start, self.gaps = bytearray(), 0, []
        self.lost = False          # after a gap the framing is unknown

    def _need(self):
        if self.kind == "tls":
            if len(self.buf) < 5:
                return None
            return 5 + struct.unpack_from("!H", self.buf, 3)[0]
        if self.kind == "nbss":
            if len(self.buf) < 4:
                return None
            return 4 + ((self.buf[1] & 1) << 16 | self.buf[2] << 8 |
                        self.buf[3])
        if self.kind == "mqtt":
            n, mult, i = 0, 1, 1
            while i < len(self.buf) and i <= 4:
                b = self.buf[i]
                n += (b & 0x7F) * mult
                mult *= 128
                i += 1
                if not b & 0x80:
                    return 1 + (i - 1) + n
            return None
        if len(self.buf) < 2:
            return None
        return 2 + struct.unpack_from("!H", self.buf, 0)[0]

    def feed(self, off, data, out, direction):
        if self.lost:
            return
        if not self.buf:
            self.start = off
        self.buf += data
        while True:
            n = self._need()
            if n is None or len(self.buf) < n:
                return
            out.append(StreamMessage(direction, self.start,
                                     bytes(self.buf[:n]), self.kind,
                                     self.gaps))
            self.start += n
            del self.buf[:n]
            self.gaps = []

    def gap(self, start, end, out, direction):
        if self.buf:
            out.append(StreamMessage(direction, self.start, bytes(self.buf),
                                     self.kind, self.gaps + [(start, end)]))
            self.buf = bytearray()
        self.lost = True           # can't find the next record boundary

    def flush(self, out, direction):
        if self.buf:
            out.append(StreamMessage(direction, self.start, bytes(self.buf),
                                     self.kind, self.gaps +
                                     [("unterminated", "")]))
            self.buf = bytearray()


class HttpFramer:
    """HTTP/1.x: headers, then a body by Content-Length or chunked."""
    kind = "http"
    MAX_HEAD = 65536
    # 5.3.4 (QA-09): only this much of a body is kept; the rest of a big
    # download is counted and dropped instead of growing with the file
    BODY_KEEP = 65536

    def __init__(self):
        self.buf, self.start, self.gaps = bytearray(), 0, []
        self.lost = False
        self.skip = 0

    def _message_len(self):
        i = self.buf.find(b"\r\n\r\n")
        if i < 0:
            return None
        head = bytes(self.buf[:i]).lower()
        hl = i + 4
        m = re.search(rb"\r\ncontent-length:\s*(\d+)", head)
        if m:
            # QA-07: 4,300+ digits made int() raise and killed the worker
            return hl + int(m.group(1)) if len(m.group(1)) <= 15 else hl
        if re.search(rb"\r\ntransfer-encoding:\s*chunked", head):
            p = hl
            while True:
                j = self.buf.find(b"\r\n", p)
                if j < 0:
                    return None
                try:
                    size = int(bytes(self.buf[p:j]).split(b";")[0], 16)
                except ValueError:
                    return len(self.buf)        # malformed: take it all
                p = j + 2 + size + 2
                if size == 0:
                    return p if len(self.buf) >= p else None
                if len(self.buf) < p:
                    return None
        if head.startswith(b"http/") and not re.match(
                rb"http/1\.\d (1\d\d|204|304)", head):
            return None if not self.closing else len(self.buf)
        return hl

    closing = False

    def feed(self, off, data, out, direction):
        if self.lost:
            return
        if self.skip:
            k = min(self.skip, len(data))
            self.skip -= k
            data, off = data[k:], off + k
            if not data:
                return
        if not self.buf:
            self.start = off
        self.buf += data
        while self.buf:
            n = self._message_len()
            if n is None:
                if len(self.buf) > self.MAX_HEAD and \
                        b"\r\n\r\n" not in self.buf:
                    self.lost = True
                elif len(self.buf) > self.MAX_HEAD + self.BODY_KEEP:
                    # chunked or unframed and huge: keep the start only
                    out.append(StreamMessage(
                        direction, self.start,
                        bytes(self.buf[:self.MAX_HEAD + self.BODY_KEEP]),
                        self.kind, self.gaps + [("too long", "")]))
                    self.buf = bytearray()
                    self.lost = True
                return
            hl = self.buf.find(b"\r\n\r\n") + 4
            keep = hl + self.BODY_KEEP
            if n > keep and len(self.buf) >= keep:
                out.append(StreamMessage(direction, self.start,
                                         bytes(self.buf[:keep]), self.kind,
                                         self.gaps + [("too long", "")]))
                rest = len(self.buf) - n
                self.start += n
                self.gaps = []
                if rest >= 0:
                    del self.buf[:n]
                    continue
                self.skip = -rest
                self.buf = bytearray()
                return
            if len(self.buf) < n:
                return
            out.append(StreamMessage(direction, self.start,
                                     bytes(self.buf[:n]), self.kind,
                                     self.gaps))
            self.start += n
            del self.buf[:n]
            self.gaps = []

    def gap(self, start, end, out, direction):
        if self.buf:
            out.append(StreamMessage(direction, self.start, bytes(self.buf),
                                     self.kind, self.gaps + [(start, end)]))
            self.buf = bytearray()
        self.lost = True

    def flush(self, out, direction):
        self.closing = True
        if self.buf:
            n = self._message_len()
            data = bytes(self.buf if n is None else self.buf[:n])
            gaps = self.gaps if n is not None and n <= len(self.buf) else \
                self.gaps + [("unterminated", "")]
            out.append(StreamMessage(direction, self.start, data, self.kind,
                                     gaps))
            self.buf = bytearray()


def framer_for(sport, dport, first=b""):
    """Pick a framer from the ports (or the first bytes)."""
    ports = {sport, dport}
    if ports & {25, 587, 110, 143, 21, 465, 993, 995} and \
            not ports & {465, 993, 995}:
        return LineFramer
    if 53 in ports:
        return lambda: LengthFramer("dns")
    if ports & {443, 465, 993, 995, 853} or first[:1] in (b"\x16",
                                                          b"\x17"):
        return lambda: LengthFramer("tls")
    if ports & {80, 8080, 8000, 5060, 554} or re.match(
            rb"^[A-Z]+ \S+ (HTTP/1|RTSP/1|SIP/2)|^(HTTP/1|RTSP/1|SIP/2)",
            first or b""):
        return HttpFramer
    if ports & {445, 139}:
        return lambda: LengthFramer("nbss")
    if ports & {1883}:
        return lambda: LengthFramer("mqtt")
    return LineFramer


class _Dir:
    __slots__ = ("base", "next", "held", "held_bytes", "fin_at", "closed",
                 "framer", "midstream", "dups", "conflicts", "gap_bytes",
                 "delivered", "recent", "pre", "pre_bytes", "pre_since",
                 "pre_fin")

    def __init__(self):
        self.pre = []              # (seq, flags, data) before the SYN
        self.pre_bytes = 0
        self.pre_since = None
        self.pre_fin = None
        self.base = None
        self.next = 0
        self.held = {}             # relative offset -> bytes
        self.held_bytes = 0
        self.fin_at = None
        self.closed = False
        self.framer = None
        self.midstream = False
        self.dups = self.conflicts = self.gap_bytes = self.delivered = 0
        self.recent = bytearray()   # last delivered bytes (overlap checks)


class TcpStream:
    __slots__ = ("key", "a", "dirs", "last", "messages", "notes", "reset")

    def __init__(self, key, a, now):
        self.key, self.a, self.last = key, a, now
        self.dirs = (_Dir(), _Dir())
        self.messages = []
        self.notes = []
        self.reset = False


class TcpReassembler:
    """Both directions of each TCP connection, in order, with holes
    reported. Memory is bounded per stream and in total; the oldest
    stream is closed first (its holes become gap markers)."""

    RECENT = 65536
    # 5.3.4 (QA-05): a count cap next to the byte cap, so a hole that never
    # fills can't make every new tiny segment walk thousands of held ones
    MAX_HELD = 256

    SYN_WAIT = 3.0     # capture seconds to wait for a SYN seen out of order

    def __init__(self, per_stream=256 * 1024, total=32 * 1024 * 1024,
                 idle=300.0, max_streams=4096, max_messages=2000,
                 framer=None):
        self.per_stream, self.total_cap = per_stream, total
        self.idle, self.max_streams = idle, max_streams
        self.max_messages = max_messages
        self.framer_choice = framer
        self.streams = OrderedDict()
        self.total = 0
        self.closed = []           # streams finished (kept briefly)
        self.recent_closed = OrderedDict()   # key -> stream (late copies)
        self.evicted = 0
        self.late = 0

    @staticmethod
    def stream_key(src, sport, dst, dport):
        a, b = (src, sport), (dst, dport)
        return (a, b) if a <= b else (b, a)

    def segment(self, src, sport, dst, dport, seq, flags, payload, now):
        """flags: TCP flag bits (int). Returns the stream."""
        key = self.stream_key(src, sport, dst, dport)
        st = self.streams.get(key)
        if st is None and key in self.recent_closed and not (
                flags & 0x02 and not flags & 0x10):
            self.late += 1             # a late copy of a finished stream
            return self.recent_closed[key]
        if st is None:
            # the side that sends the SYN (or speaks first) is direction 0
            a = (src, sport) if (flags & 0x02 and not flags & 0x10) or \
                not flags & 0x02 else (dst, dport)
            st = self.streams[key] = TcpStream(key, a, now)
            self._bound(now)
        else:
            self.streams.move_to_end(key)
        st.last = now
        if flags & 0x02 and not st.messages and not any(
                x.delivered for x in st.dirs):
            # the SYN says who opened the connection (direction 0)
            opener = (src, sport) if not flags & 0x10 else (dst, dport)
            if opener != st.a:
                st.a = opener
                st.dirs = (st.dirs[1], st.dirs[0])
        di = 0 if (src, sport) == st.a else 1
        d = st.dirs[di]
        if d.framer is None:
            ch = self.framer_choice or framer_for(sport, dport, payload)
            d.framer = ch()
        if flags & 0x04:                       # RST: finish both sides
            st.reset = True
            st.notes.append("connection reset")
            self._finish(st, now)
            return st
        if d.base is None:
            if flags & 0x02:
                d.base = (seq + 1) & 0xFFFFFFFF
                pre, d.pre, d.pre_bytes = d.pre, [], 0
                self.total -= sum(len(x[2]) for x in pre)
                for s2, f2, p2 in pre:
                    self._take(st, di, d, s2, f2, p2)
            else:
                # no SYN yet: hold briefly in case it arrives out of order
                d.pre.append((seq, flags, bytes(payload)))
                d.pre_bytes += len(payload)
                self.total += len(payload)
                if d.pre_since is None:
                    d.pre_since = now
                if d.pre_bytes > self.per_stream or \
                        now - d.pre_since > self.SYN_WAIT:
                    self._start_midstream(st, di, d)
                return st
        self._take(st, di, d, seq, flags, payload)
        if all(x.closed for x in st.dirs) or (
                st.dirs[0].closed and st.dirs[1].base is None and
                not st.dirs[1].pre):
            self._finish(st, now)
        return st

    def _start_midstream(self, st, di, d):
        """Give up waiting for the SYN: start at the earliest byte held."""
        pre, d.pre, d.pre_bytes = d.pre, [], 0
        self.total -= sum(len(x[2]) for x in pre)
        if not pre:
            return
        first = pre[0][0]
        d.base = min((x[0] for x in pre),
                     key=lambda x: (x - first + 0x80000000) & 0xFFFFFFFF)
        d.midstream = True
        st.notes.append(f"direction {di} started mid-stream")
        for s2, f2, p2 in pre:
            self._take(st, di, d, s2, f2, p2)

    def _take(self, st, di, d, seq, flags, payload):
        rel = (seq + (1 if flags & 0x02 else 0) - d.base) & 0xFFFFFFFF
        if rel >= 0x80000000:                  # before what we know: old
            if payload:
                d.dups += 1
            return st
        if payload:
            self._place(st, di, d, rel, payload)
        if flags & 0x01:
            d.fin_at = rel + len(payload)
            self._drain(st, di, d)

    def _place(self, st, di, d, rel, data):
        end = rel + len(data)
        if end <= d.next:                      # fully old: duplicate?
            d.dups += 1
            self._check_old(st, d, rel, data)
            return
        if rel < d.next:                       # partly old
            self._check_old(st, d, rel, data[:d.next - rel])
            data = data[d.next - rel:]
            rel = d.next
        # overlap with held segments: first copy wins
        for o in list(d.held):
            b = d.held[o]
            lo, hi = max(o, rel), min(o + len(b), rel + len(data))
            if lo < hi:
                if b[lo - o:hi - o] != data[lo - rel:hi - rel]:
                    d.conflicts += 1
                    st.notes.append(f"conflicting retransmission at byte "
                                    f"{lo} (first copy kept)")
                else:
                    d.dups += 1
        if rel in d.held and len(d.held[rel]) >= len(data):
            return
        if rel in d.held:
            d.held_bytes -= len(d.held[rel])
            self.total -= len(d.held[rel])
        d.held[rel] = bytes(data)
        d.held_bytes += len(data)
        self.total += len(data)
        self._drain(st, di, d)
        if d.held_bytes > self.per_stream or \
                len(d.held) > self.MAX_HELD:   # a hole that won't fill
            self._skip_hole(st, di, d)
        if self.total > self.total_cap:
            self._bound(st.last)

    def _check_old(self, st, d, rel, data):
        back = d.next - rel
        if back <= len(d.recent):
            have = d.recent[len(d.recent) - back:len(d.recent) - back +
                            len(data)]
            if have and bytes(have) != data[:len(have)]:
                d.conflicts += 1
                st.notes.append(f"conflicting retransmission at byte {rel} "
                                f"(first copy kept)")

    def _drain(self, st, di, d):
        while True:
            # the held segment that covers d.next (lowest start first)
            cand = [o for o in d.held if o <= d.next]
            if not cand:
                break
            o = min(cand)
            b = d.held.pop(o)
            d.held_bytes -= len(b)
            self.total -= len(b)
            if o + len(b) <= d.next:
                continue
            chunk = b[d.next - o:]
            self._deliver(st, di, d, d.next, chunk)
        if d.fin_at is not None and d.next >= d.fin_at and not d.held:
            if not d.closed:
                d.closed = True
                d.framer.flush(st.messages, di)

    def _deliver(self, st, di, d, off, chunk):
        d.next = off + len(chunk)
        d.delivered += len(chunk)
        d.recent += chunk
        if len(d.recent) > self.RECENT:
            del d.recent[:len(d.recent) - self.RECENT]
        if len(st.messages) < self.max_messages:
            d.framer.feed(off, chunk, st.messages, di)

    def _skip_hole(self, st, di, d):
        if not d.held:
            return
        nxt = min(d.held)
        if nxt > d.next:
            d.gap_bytes += nxt - d.next
            d.framer.gap(d.next, nxt, st.messages, di)
            st.notes.append(f"bytes {d.next}–{nxt} of direction {di} were "
                            f"never seen")
            d.next = nxt
        self._drain(st, di, d)

    def _finish(self, st, now):
        for di, d in enumerate(st.dirs):
            if d.framer is None:
                continue
            if d.base is None:
                self._start_midstream(st, di, d)
            while d.held:
                self._skip_hole(st, di, d)
            if d.fin_at is not None and d.next < d.fin_at:
                # bytes before the FIN that never arrived
                d.gap_bytes += d.fin_at - d.next
                d.framer.gap(d.next, d.fin_at, st.messages, di)
                st.notes.append(f"bytes {d.next}–{d.fin_at} of direction "
                                f"{di} were never seen")
                d.next = d.fin_at
            if not d.closed:
                d.closed = True
                d.framer.flush(st.messages, di)
        self.streams.pop(st.key, None)
        self.recent_closed[st.key] = st
        if len(self.recent_closed) > 1024:
            self.recent_closed.popitem(last=False)
        self.closed.append(st)
        if len(self.closed) > 256:
            del self.closed[:64]

    def _bound(self, now):
        while self.streams and (len(self.streams) > self.max_streams or
                                self.total > self.total_cap):
            _k, st = next(iter(self.streams.items()))
            st.notes.append("closed early to stay within memory")
            self.evicted += 1
            self._finish(st, now)

    def expire(self, now):
        for st in [s for s in self.streams.values()
                   if now - s.last > self.idle]:
            st.notes.append("idle")
            self._finish(st, now)

    def flush(self, now=0.0):
        for st in list(self.streams.values()):
            self._finish(st, now)
        return self.closed

    def all_streams(self):
        return list(self.closed) + list(self.streams.values())


def reassemble_frames(frames, **kw):
    """Feed (raw, ts, lt) Ethernet/IP frames through the defragmenter and
    the TCP reassembler. → (TcpReassembler, IpDefragmenter)."""
    tr = TcpReassembler(**kw)
    df = IpDefragmenter()
    for raw, ts, lt in frames:
        d = dissect(raw, lt)
        ipn = next((n for n in d.nodes if n.key in ("ip", "ipv6")), None)
        if ipn is None:
            continue
        src = d.get("ip.src") or d.get("ipv6.src")
        dst = d.get("ip.dst") or d.get("ipv6.dst")
        if ipn.key == "ip" and (d.get("ip.flags.mf") or
                                d.get("ip.frag_offset")):
            hl = d.get("ip.hdr_len")
            pay = raw[ipn.offset + hl:ipn.offset + ipn.length]
            whole, _w = df.add((src, dst, d.get("ip.proto"), d.get("ip.id")),
                               d.get("ip.frag_offset"),
                               bool(d.get("ip.flags.mf")), pay, ts)
            if whole is None or d.get("ip.proto") != 6:
                continue
            seg = whole
        else:
            tcpn = next((n for n in d.nodes if n.key == "tcp"), None)
            if tcpn is None:
                continue
            seg = raw[tcpn.offset:tcpn.offset + tcpn.length]
        if len(seg) < 20:
            continue
        sp, dp, seq = struct.unpack_from("!HHI", seg, 0)
        hl = (seg[12] >> 4) * 4
        tr.segment(src, sp, dst, dp, seq, seg[13], seg[hl:], ts)
    return tr, df


# ============================================================================
#  V5: Full Power — deep analysis inside a budget
#
#  The fast path (fast_decode → model) runs for every packet in every mode
#  and is never slowed by depth. Full Power adds a second, budgeted pass:
#  every supported dissector, TCP reassembly for all flows within a memory
#  cap, and expert findings. It runs in worker processes (this same .py
#  started with --mw-worker) when that is faster than a thread — measured,
#  see bench_deep — and falls back to a thread otherwise. Results live in
#  their own store, so switching modes never changes the model.
# ============================================================================
WORKER_FLAG = "--mw-worker"
DEEP_SEVERITIES = ("error", "warn", "note", "chat")
DEEP_GROUPS = ("Malformed", "Sequence", "Protocol", "Security", "Checksum",
               "Response code")


def _deep_preview(kind, data):
    """A short, secret-free label for a reassembled message."""
    if kind == "line":
        line = data.split(b"\n", 1)[0].rstrip(b"\r")
        m = _SECRET_CMDS.match(line)
        if m:
            return ((m.group("tag") or b"") + m.group("cmd")).decode(
                "latin-1", "replace") + " (hidden: credentials)"
        return line[:120].decode("utf-8", "replace")
    if kind == "http":
        return data.split(b"\r\n", 1)[0][:120].decode("latin-1", "replace")
    if kind == "tls":
        ct = data[0] if data else 0
        return f"TLS {_TLS_CT.get(ct, ct)} record, {len(data)} bytes"
    if kind == "dns":
        return f"DNS message over TCP, {len(data)} bytes"
    return f"{len(data)} bytes"


# ---- V5 M5: protocol transactions -------------------------------------------
#  Request/response pairs and handshakes built from single packets (DNS,
#  DHCP, TLS, NTP, SIP over UDP) and from reassembled stream messages
#  (HTTP/1, RTSP, SIP over TCP, SSH, SMB, MQTT). Each finished exchange is
#  one "transaction" dict of plain values (it crosses the worker pipe).
#  Nothing private leaves the tracker: HTTP paths lose their query string,
#  cookies and auth headers are never read, MQTT topics and payloads are
#  never read (counts only).
_SMB_DIALECTS = {0x0202: "2.0.2", 0x0210: "2.1", 0x0300: "3.0",
                 0x0302: "3.0.2", 0x0311: "3.1.1", 0x02FF: "2.x (any)"}
_MQTT_TYPES = {1: "CONNECT", 2: "CONNACK", 3: "PUBLISH", 4: "PUBACK",
               8: "SUBSCRIBE", 9: "SUBACK", 12: "PINGREQ", 13: "PINGRESP",
               14: "DISCONNECT"}
_MQTT_CONNACK = {0: "accepted", 1: "refused: protocol version",
                 2: "refused: client id", 3: "refused: server unavailable",
                 4: "refused: bad user name or password",
                 5: "refused: not authorized"}
_NTP_EPOCH = 2208988800


def _ntp_time(b):
    sec, frac = struct.unpack("!II", b)
    return sec - _NTP_EPOCH + frac / 2 ** 32 if sec else 0.0


# ---- V5 M6: Email Traffic (metadata only) -------------------------------------
#  SMTP, IMAP and POP3 sessions followed on reassembled lines. Secrets are
#  removed inside the parser: an AUTH / LOGIN / PASS / USER / APOP line is
#  reduced to its command (and mechanism) before anything else sees it;
#  SASL continuation lines, DATA bodies, IMAP literals and POP3 RETR/TOP
#  bodies are skipped by length, never stored. Addresses are counted, never
#  kept. After STARTTLS / STLS succeeds, parsing stops: the rest is
#  encrypted and is only measured.
MAIL_PORTS = {25: "SMTP", 587: "SMTP", 465: "SMTP", 2525: "SMTP",
              143: "IMAP", 993: "IMAP", 110: "POP3", 995: "POP3"}
MAIL_TLS_PORTS = {465, 993, 995}
WEBMAIL_HOSTS = {"mail.google.com": "Gmail", "outlook.live.com": "Outlook",
                 "outlook.office.com": "Outlook",
                 "outlook.office365.com": "Outlook",
                 "mail.yahoo.com": "Yahoo Mail", "mail.proton.me": "Proton",
                 "app.fastmail.com": "Fastmail", "mail.aol.com": "AOL Mail",
                 "www.icloud.com": "iCloud", "mail.zoho.com": "Zoho Mail",
                 "webmail.gmx.net": "GMX"}
_IMAP_LITERAL = re.compile(rb"\{(\d{1,9})\+?\}\r?\n?$")


class MailSession:
    """Everything kept about one mail connection: counts, codes, timing,
    and a short timeline. No content, no credentials, no addresses."""

    def __init__(self, proto, client, server, port, ts, implicit_tls=False):
        self.proto, self.client, self.server = proto, client, server
        self.port, self.start, self.last = port, ts, ts
        self.implicit_tls = implicit_tls
        self.tls = implicit_tls          # traffic is encrypted from here
        self.starttls_offered = False
        self.starttls_asked = False
        self.auth_mechs = []
        self.auth_attempts = self.auth_failures = self.auth_ok = 0
        self.auth_before_tls = False
        self.mail_from = self.rcpt = self.messages_sent = 0
        self.data_bytes = 0
        self.commands = Counter()
        self.replies = Counter()
        self.errors = []
        self.greeting = ""
        self.timeline = []
        self.bytes = [0, 0]
        self.mode = ""                   # data / auth / literal / multiline
        self.skip = [0, 0]               # literal bytes to skip, per dir
        self.pending_tags = {}           # IMAP tag -> command
        self.last_cmd = ""
        self.signature = proto is not None

    def note(self, ts, what):
        if len(self.timeline) < 40:
            self.timeline.append((round(ts - self.start, 3), what))

    def result(self, closed_ts, how):
        enc = "encrypted from the start" if self.implicit_tls else \
            "upgraded to encryption (STARTTLS)" if self.tls else \
            "not encrypted"
        dur = max(0.0, closed_ts - self.start)
        steps = " → ".join(w for _t, w in self.timeline[:12])
        return {
            "kind": "mail", "proto": self.proto, "ts": self.start,
            "client": self.client, "server": self.server, "port": self.port,
            "encryption": enc, "starttls_offered": self.starttls_offered,
            "auth_mechs": list(self.auth_mechs),
            "auth_attempts": self.auth_attempts,
            "auth_failures": self.auth_failures, "auth_ok": self.auth_ok,
            "auth_before_tls": self.auth_before_tls,
            "mail_from": self.mail_from, "rcpt": self.rcpt,
            "messages": self.messages_sent, "data_bytes": self.data_bytes,
            "commands": dict(self.commands), "replies": dict(self.replies),
            "errors": list(self.errors[:20]), "greeting_ok":
                bool(self.greeting), "bytes_up": self.bytes[0],
            "bytes_down": self.bytes[1], "duration_s": round(dur, 3),
            "closed": how, "timeline": list(self.timeline),
            "result": enc,
            "summary": f"{self.proto} {self.client} → {self.server}:"
                       f"{self.port}, {enc}, {steps or 'no commands seen'}"
                       f" → {how} after {dur:.1f} s"}


class MailTracker:
    """Follows mail sessions inside ProtocolTracker."""

    MAX = 1024

    def __init__(self, emit, finding):
        self.sessions = OrderedDict()     # stream key -> MailSession
        self.emit, self.finding = emit, finding
        self.reconnects = defaultdict(deque)   # (client, server) -> ts

    def proto_for(self, st, first_line, direction):
        ports = (st.key[0][1], st.key[1][1])
        for p in ports:
            if p in MAIL_PORTS:
                return MAIL_PORTS[p], p
        # nonstandard port: a greeting from the server, never a keyword
        if direction == 1:
            if re.match(rb"^220[ -].*(SMTP|ESMTP|mail)", first_line, re.I):
                return "SMTP", ports[1] if st.a == st.key[0] else ports[0]
            if re.match(rb"^\* OK.*IMAP", first_line, re.I):
                return "IMAP", ports[1] if st.a == st.key[0] else ports[0]
            if re.match(rb"^\+OK.*(POP|ready)", first_line, re.I):
                return "POP3", ports[1] if st.a == st.key[0] else ports[0]
        return None, None

    def session(self, st, ts, m):
        key = repr(st.key)
        s = self.sessions.get(key)
        if s is not None:
            return s
        if m.kind not in ("line", "tls"):
            return None
        proto, port = self.proto_for(st, m.data[:200], m.direction)
        if proto is None:
            return None
        server = st.key[1] if st.a == st.key[0] else st.key[0]
        s = MailSession(proto, st.a[0], server[0], port, ts,
                        implicit_tls=port in MAIL_TLS_PORTS)
        self.sessions[key] = s
        while len(self.sessions) > self.MAX:
            k, old = self.sessions.popitem(last=False)
            self._close(old, old.last, "still open (too many sessions)")
        rc = self.reconnects[(s.client, s.server)]
        rc.append(ts)
        while rc and ts - rc[0] > 60:
            rc.popleft()
        if len(rc) == 10:
            self.finding(ts, "note", "Sequence",
                         f"{s.client} reconnected to the mail server "
                         f"{s.server} 10 times within a minute (a "
                         f"misconfigured mail app or wrong password)", "")
        return s

    def message(self, no, ts, st, m):
        s = self.session(st, ts, m)
        if s is None:
            return False
        s.last = ts
        s.bytes[m.direction] += len(m.data)
        if s.tls or m.kind != "line":
            return True                   # encrypted: measured only
        line = m.data
        if s.skip[m.direction]:
            take = min(s.skip[m.direction], len(line))
            s.skip[m.direction] -= take
            return True
        text = line.rstrip(b"\r\n")
        if s.proto == "SMTP":
            self._smtp(no, ts, s, m.direction, text)
        elif s.proto == "IMAP":
            self._imap(no, ts, s, m.direction, text)
        else:
            self._pop3(no, ts, s, m.direction, text)
        return True

    # ---- SMTP ---------------------------------------------------------------------
    def _smtp(self, no, ts, s, direction, text):
        if direction == 0:
            if s.mode == "data":
                if text == b".":
                    s.mode = ""
                    s.messages_sent += 1
                    s.note(ts, f"message {s.data_bytes} bytes")
                else:
                    s.data_bytes += len(text) + 2
                return
            if s.mode == "auth":
                return                    # SASL response: never read
            verb = text.split(b" ", 1)[0].split(b":", 1)[0].upper().decode(
                "latin-1", "replace")[:12]
            s.commands[verb] += 1
            s.last_cmd = verb
            if verb in ("EHLO", "HELO"):
                s.note(ts, verb)
            elif verb == "STARTTLS":
                s.starttls_asked = True
                s.note(ts, "STARTTLS")
            elif verb == "AUTH":
                parts = text.split(None, 2)
                mech = parts[1].upper().decode("latin-1", "replace")[:20] \
                    if len(parts) > 1 else "?"
                self._auth(no, ts, s, mech)
            elif verb == "MAIL":
                s.mail_from += 1
            elif verb == "RCPT":
                s.rcpt += 1
            elif verb == "QUIT":
                s.note(ts, "QUIT")
            return
        m = re.match(rb"^(\d{3})([ -])(.*)$", text)
        if not m:
            return
        code, more, rest = int(m.group(1)), m.group(2) == b"-", m.group(3)
        if not more:
            s.replies[str(code)] += 1
        if code == 220 and not s.greeting and not s.starttls_asked:
            s.greeting = "ok"
            s.note(ts, "greeting")
        elif s.last_cmd in ("EHLO", "HELO") and code == 250:
            cap = rest.upper()
            if cap.startswith(b"STARTTLS"):
                s.starttls_offered = True
            if cap.startswith(b"AUTH"):
                s.auth_mechs = [x.decode("latin-1", "replace")[:20]
                                for x in cap.split()[1:8]]
            if not more:
                s.note(ts, "capabilities")
        if s.starttls_asked and code == 220 and s.last_cmd == "STARTTLS":
            s.tls = True
            s.note(ts, "encrypted")
        elif code == 334:
            s.mode = "auth"
        elif code == 235:
            s.mode = ""
            s.auth_ok += 1
            s.note(ts, "login ok")
        elif code == 354:
            s.mode = "data"
        elif code >= 400 and not more:
            if s.mode == "auth" or s.last_cmd == "AUTH":
                s.mode = ""
                self._auth_failed(no, ts, s)
            s.errors.append(code)
            s.note(ts, f"error {code}")
        elif code == 221:
            s.note(ts, "bye")

    # ---- IMAP ---------------------------------------------------------------------
    def _imap(self, no, ts, s, direction, text):
        lit = _IMAP_LITERAL.search(text)
        if direction == 0:
            parts = text.split(None, 2)
            if len(parts) >= 2 and s.mode != "auth":
                tag = parts[0][:20].decode("latin-1", "replace")
                cmd = parts[1].upper().decode("latin-1", "replace")[:14]
                if cmd == "UID" and len(parts) > 2:
                    cmd = "UID " + parts[2].split(None, 1)[0].upper().decode(
                        "latin-1", "replace")[:10]
                s.commands[cmd] += 1
                s.pending_tags[tag] = cmd
                if len(s.pending_tags) > 200:
                    s.pending_tags.clear()
                if cmd == "STARTTLS":
                    s.starttls_asked = True
                    s.note(ts, "STARTTLS")
                elif cmd in ("LOGIN", "AUTHENTICATE"):
                    mech = "LOGIN" if cmd == "LOGIN" else (
                        parts[2].split(None, 1)[0].upper().decode(
                            "latin-1", "replace")[:20] if len(parts) > 2
                        else "?")
                    self._auth(no, ts, s, mech)
                    if cmd == "AUTHENTICATE":
                        s.mode = "auth"
                elif cmd in ("SELECT", "EXAMINE", "IDLE", "LOGOUT"):
                    s.note(ts, cmd)
            elif s.mode == "auth":
                pass                      # SASL response: never read
            if lit:
                s.skip[0] = int(lit.group(1))
            return
        if lit:
            s.skip[1] = int(lit.group(1))   # FETCH literal: skipped
        if text.startswith(b"* "):
            up = text.upper()
            if not s.greeting and up.startswith(b"* OK"):
                s.greeting = "ok"
                s.note(ts, "greeting")
            if b"CAPABILITY" in up[:40] or b"[CAPABILITY" in up:
                if b"STARTTLS" in up:
                    s.starttls_offered = True
                s.auth_mechs = sorted({x.split(b"=", 1)[1].decode(
                    "latin-1", "replace")[:20] for x in up.split()
                    if x.startswith(b"AUTH=")})[:8]
            return
        if text.startswith(b"+"):
            return
        parts = text.split(None, 2)
        if len(parts) < 2:
            return
        tag = parts[0].decode("latin-1", "replace")[:20]
        status = parts[1].upper().decode("latin-1", "replace")[:3]
        cmd = s.pending_tags.pop(tag, "")
        s.replies[status] += 1
        if cmd == "STARTTLS" and status == "OK":
            s.tls = True
            s.note(ts, "encrypted")
        elif cmd in ("LOGIN", "AUTHENTICATE"):
            s.mode = ""
            if status == "OK":
                s.auth_ok += 1
                s.note(ts, "login ok")
            else:
                self._auth_failed(no, ts, s)
        if status in ("NO", "BAD"):
            s.errors.append(f"{cmd or '?'} {status}")
            s.note(ts, f"{cmd or 'command'} {status}")

    # ---- POP3 ---------------------------------------------------------------------
    def _pop3(self, no, ts, s, direction, text):
        if direction == 0:
            if s.mode == "auth":
                if text.startswith(b"*"):
                    s.mode = ""
                return
            verb = text.split(b" ", 1)[0].upper().decode("latin-1",
                                                          "replace")[:8]
            s.commands[verb] += 1
            s.last_cmd = verb
            if verb == "STLS":
                s.starttls_asked = True
                s.note(ts, "STLS")
            elif verb in ("USER", "APOP"):
                self._auth(no, ts, s, verb)
            elif verb == "PASS":
                pass                      # counted with USER
            elif verb == "AUTH":
                parts = text.split(None, 2)
                if len(parts) > 1:
                    self._auth(no, ts, s, parts[1].upper().decode(
                        "latin-1", "replace")[:20])
                    s.mode = "auth"
            elif verb == "QUIT":
                s.note(ts, "QUIT")
            return
        if s.mode == "multiline":
            if text == b".":
                s.mode = ""
            return                         # message bodies: never read
        if text.startswith(b"+OK"):
            s.replies["+OK"] += 1
            if not s.greeting:
                s.greeting = "ok"
                s.note(ts, "greeting")
            elif s.last_cmd == "STLS":
                s.tls = True
                s.note(ts, "encrypted")
            elif s.last_cmd == "PASS" or (s.last_cmd == "APOP"):
                s.auth_ok += 1
                s.note(ts, "login ok")
            elif s.last_cmd in ("RETR", "TOP", "LIST", "UIDL", "CAPA") and \
                    not (s.last_cmd in ("LIST", "UIDL") and
                         len(text.split()) > 2):
                s.mode = "multiline"
                if s.last_cmd == "CAPA":
                    s.mode = "capa"
        elif text.startswith(b"-ERR"):
            s.replies["-ERR"] += 1
            if s.last_cmd in ("PASS", "APOP", "USER", "AUTH"):
                self._auth_failed(no, ts, s)
            s.errors.append(f"{s.last_cmd} -ERR")
            s.note(ts, f"{s.last_cmd} failed")
        elif s.mode == "capa":
            if text == b".":
                s.mode = ""
            elif text.upper().startswith(b"STLS"):
                s.starttls_offered = True
            elif text.upper().startswith(b"SASL"):
                s.auth_mechs = [x.decode("latin-1", "replace")[:20]
                                for x in text.split()[1:8]]

    # ---- shared -------------------------------------------------------------------
    def _auth(self, no, ts, s, mech):
        s.auth_attempts += 1
        if mech not in s.auth_mechs:
            s.auth_mechs.append(mech)
        s.note(ts, f"login ({mech})")
        if not s.tls:
            s.auth_before_tls = True
            if s.auth_attempts == 1:
                art = "a" if s.proto == "POP3" else "an"
                self.finding(ts, "warn", "Security",
                             f"{s.client} sent {art} {s.proto} login to "
                             f"{s.server} before encryption was on (the "
                             f"password itself is not read by "
                             f"MiniWireshark)", "", no)

    def _auth_failed(self, no, ts, s):
        s.auth_failures += 1
        s.note(ts, "login failed")
        if s.auth_failures == 3:
            self.finding(ts, "warn", "Security",
                         f"{s.client} failed to log in to the mail server "
                         f"{s.server} {s.auth_failures} times (wrong saved "
                         f"password, or someone guessing)", "", no)

    SAFE_VERBS = {"EHLO", "HELO", "STARTTLS", "QUIT", "MAIL", "RCPT",
                  "DATA", "AUTH", "LOGIN", "AUTHENTICATE", "USER", "PASS",
                  "APOP", "SELECT", "EXAMINE", "FETCH", "LOGOUT", "CAPA",
                  "STLS", "RETR", "TOP", "LIST", "UIDL", "STAT", "NOOP",
                  "RSET", "CAPABILITY", "IDLE", "DELE", "UID", "SEARCH",
                  "STORE", "EXPUNGE", "CLOSE", "NAMESPACE", "ID", "ENABLE"}

    def preview(self, st, m):
        """A label for a mail line that can never contain content:
        command names and reply codes only."""
        s = self.sessions.get(repr(st.key))
        if s is None:
            return None
        if m.kind != "line" or s.tls:
            return f"{s.proto}: encrypted, {len(m.data)} bytes"
        t = m.data.strip().split()
        who = "client" if m.direction == 0 else "server"
        if not t:
            return f"{s.proto} {who}: blank line"
        words = [w.decode("latin-1", "replace").upper() for w in t[:3]]
        if m.direction == 1:
            code = next((w for w in words[:2] if re.match(
                r"^(\d{3}(-.*)?|\+OK|-ERR|OK|NO|BAD|\*|\+)$", w)), "")
            return f"{s.proto} {who}: reply {code[:4] or '(text)'}"
        verb = next((w for w in words[:2] if w in self.SAFE_VERBS), "")
        return f"{s.proto} {who}: {verb or '(content not shown)'}"

    def closed(self, st, ts, how):
        s = self.sessions.pop(repr(st.key), None)
        if s is not None:
            self._close(s, ts, how)

    def _close(self, s, ts, how):
        if s.starttls_offered and not s.tls and (s.auth_attempts or
                                                  s.mail_from):
            self.finding(ts, "warn", "Security",
                         f"{s.server} offered encryption (STARTTLS) but "
                         f"{s.client} did not use it", "")
        if s.rcpt > 100:
            self.finding(ts, "note", "Protocol",
                         f"{s.client} sent mail to {s.rcpt} recipients in "
                         f"one session (normal for newsletters, printers "
                         f"scanning to email, backups or a mail gateway)",
                         "")
        self.emit(**s.result(ts, how))


class ProtocolTracker:
    """Pairs requests with replies and follows handshakes. Bounded: at
    most MAX_PENDING open exchanges of each kind; old ones expire as
    unanswered."""

    MAX_PENDING = 2048
    DNS_TIMEOUT = 5.0

    def __init__(self):
        self.out = []              # finished transactions
        self.findings = []
        self.dns = OrderedDict()   # (client, cport, id) -> state
        self.dns_last = OrderedDict()   # (client, name, type) -> ts
        self.dhcp = OrderedDict()  # xid -> state
        self.dhcp_servers = set()
        self._dhcp_warned = False
        self.http = {}             # stream -> deque of pending requests
        self.tls = OrderedDict()   # stream -> handshake state
        self.ntp = OrderedDict()   # (client, server, xmt) -> (ts, no)
        self.ssh = {}              # stream -> banners
        self.mqtt = {}             # stream -> counters
        self.counts = Counter()
        self.mail = MailTracker(self._emit_kw, self._finding)

    def _emit_kw(self, **t):
        self._emit(**t)

    def _finding(self, ts, sev, group, summary, field, no=0):
        self.findings.append((no, ts, sev, group, summary, field))

    def closed(self, st, ts, how):
        """A TCP stream finished (FIN, RST, idle or memory)."""
        self.mail.closed(st, ts, how)

    def take(self):
        out, self.out = self.out, []
        f, self.findings = self.findings, []
        return out, f

    def _emit(self, **t):
        self.counts[t["kind"]] += 1
        self.out.append(t)

    @staticmethod
    def _bound(od, n):
        while len(od) > n:
            od.popitem(last=False)

    # ---- single packets ----------------------------------------------------------
    def packet(self, no, ts, d, src, dst):
        if d.get("dns.id") is not None and 53 in (d.get("udp.srcport"),
                                                  d.get("udp.dstport"),
                                                  d.get("tcp.srcport"),
                                                  d.get("tcp.dstport")):
            self._dns(no, ts, d, src, dst)
        if d.get("dhcp.id") is not None:
            self._dhcp(no, ts, d, src, dst)
        if d.get("tls.handshake.type") is not None or \
                21 in d.values("tls.record.content_type"):
            self._tls(no, ts, d, src, dst)
        if d.get("ntp.flags.mode") is not None:
            self._ntp(no, ts, d, src, dst)
        if d.get("udp.srcport") is not None and 5060 in (
                d.get("udp.srcport"), d.get("udp.dstport")):
            node = next((n for n in d.nodes if n.key == "udp"), None)
            if node is not None:
                self._sip_text(no, ts, d.raw[node.offset + 8:node.offset +
                                              node.length], src, dst)
        self._expire(ts)

    def _expire(self, ts):
        while self.dns:
            k, s = next(iter(self.dns.items()))
            if ts - s["ts"] <= self.DNS_TIMEOUT:
                break
            self.dns.popitem(last=False)
            self._emit(kind="dns", ts=s["ts"], no=s["no"], client=k[0],
                       server=s["server"], name=s["name"], qtype=s["qtype"],
                       result="no answer", latency_ms=None,
                       tries=s["tries"], answers=0,
                       summary=f"{s['name']} ({s['qtype']}): no answer "
                               f"from {s['server']}")

    def _dns(self, no, ts, d, src, dst):
        sport = d.get("udp.srcport") or d.get("tcp.srcport")
        dport = d.get("udp.dstport") or d.get("tcp.dstport")
        qid = d.get("dns.id")
        name = d.get("dns.qry.name") or "?"
        qt = d.get("dns.qry.type")
        qtn = _DNS_TYPES.get(qt, str(qt))
        if not d.get("dns.flags.response"):
            last = self.dns_last.get((src, name, qtn))
            k = (src, sport, qid)
            tries = 1
            if last is not None and ts - last < self.DNS_TIMEOUT:
                prev = next((s for s in self.dns.values()
                             if s["client"] == src and s["name"] == name and
                             s["qtype"] == qtn), None)
                if prev is not None:
                    tries = prev["tries"] + 1
            self.dns[k] = {"ts": ts, "no": no, "name": name, "qtype": qtn,
                           "server": dst, "client": src, "tries": tries}
            self.dns_last[(src, name, qtn)] = ts
            self._bound(self.dns, self.MAX_PENDING)
            self._bound(self.dns_last, self.MAX_PENDING)
            return
        s = self.dns.pop((dst, dport, qid), None)
        if s is None:
            return
        rc = d.get("dns.flags.rcode") or 0
        lat = (ts - s["ts"]) * 1000.0
        # an answered retry closes its earlier tries too
        for k2 in [k for k, v in self.dns.items() if v["client"] == dst and
                   v["name"] == s["name"] and v["qtype"] == s["qtype"]]:
            self.dns.pop(k2, None)
        res = _DNS_RCODES.get(rc, f"code {rc}")
        n_ans = d.get("dns.count.answers") or 0
        self._emit(kind="dns", ts=s["ts"], no=s["no"], reply_no=no,
                   client=dst, server=src, name=s["name"], qtype=s["qtype"],
                   result=res, rcode=rc, latency_ms=round(lat, 2),
                   tries=s["tries"], answers=n_ans,
                   summary=f"{s['name']} ({s['qtype']}): {res}, "
                           f"{lat:.0f} ms via {src}"
                           + (f" after {s['tries']} tries"
                              if s["tries"] > 1 else ""))

    def _dhcp(self, no, ts, d, src, dst):
        xid = d.get("dhcp.id")
        mt = d.get("dhcp.option.dhcp")
        if mt is None:
            return
        name = _DHCP_MSG.get(mt, str(mt))
        s = self.dhcp.get(xid)
        if s is None:
            s = self.dhcp[xid] = {"ts": ts, "no": no, "steps": [],
                                  "mac": d.get("dhcp.hw.mac_addr") or "",
                                  "host": "", "servers": set()}
            self._bound(self.dhcp, self.MAX_PENDING)
        s["steps"].append(name)
        if d.get("dhcp.option.hostname"):
            s["host"] = d.get("dhcp.option.hostname")
        server = d.get("dhcp.option.dhcp_server_id") or (
            src if mt in (2, 5, 6) else "")
        if mt in (2, 5, 6) and server:
            s["servers"].add(server)
            self.dhcp_servers.add(server)
            if len(self.dhcp_servers) > 1 and not self._dhcp_warned:
                self._dhcp_warned = True
                self.findings.append((
                    no, ts, "warn", "Security", "More than one DHCP server "
                    "answered on this network (" + ", ".join(sorted(
                        self.dhcp_servers)) + ")", "dhcp.option."
                    "dhcp_server_id"))
        if mt in (5, 6):
            self.dhcp.pop(xid, None)
            lease = d.get("dhcp.option.ip_address_lease_time")
            ip = d.get("dhcp.ip.your")
            steps = " → ".join(s["steps"])
            self._emit(kind="dhcp", ts=s["ts"], no=s["no"], reply_no=no,
                       client=s["mac"], server=server, host=s["host"],
                       ip=ip, lease_s=lease, result=name,
                       latency_ms=round((ts - s["ts"]) * 1000.0, 2),
                       steps=steps,
                       summary=f"{s['host'] or s['mac']}: {steps}"
                               + (f", got {ip}" if mt == 5 else "")
                               + (f" for {human_duration(lease)}"
                                  if lease and mt == 5 else "")
                               + f" from {server}")

    def _tls(self, no, ts, d, src, dst):
        sp = d.get("tcp.srcport")
        dp = d.get("tcp.dstport")
        if sp is None:
            return
        key = repr(TcpReassembler.stream_key(src, sp, dst, dp))
        hs = d.values("tls.handshake.type")
        s = self.tls.get(key)
        if 1 in hs:
            sni = d.get("tls.handshake.extensions_server_name") or ""
            if sni in WEBMAIL_HOSTS:
                self._emit(kind="mail", proto="webmail", ts=ts, no=no,
                           client=src, server=dst, port=dp,
                           service=f"{WEBMAIL_HOSTS[sni]} ({sni})",
                           encryption="encrypted (HTTPS)", result="contacted",
                           summary=f"{src} contacted the webmail service "
                                   f"{WEBMAIL_HOSTS[sni]} ({sni}); its "
                                   f"contents are encrypted and never shown")
            self.tls[key] = s = {
                "ts": ts, "no": no, "client": src, "server": dst,
                "sni": d.get("tls.handshake.extensions_server_name") or "",
                "alpn": d.get("tls.handshake.extensions_alpn_str") or "",
                "offered": max(d.values("tls.handshake.extensions."
                                        "supported_version") or
                               [d.get("tls.handshake.version") or 0])}
            self._bound(self.tls, self.MAX_PENDING)
        if s is None:
            return
        alert = 21 in d.values("tls.record.content_type")
        if 2 in hs or alert:
            self.tls.pop(key, None)
            sv = d.values("tls.handshake.extensions.supported_version")
            ver = sv[0] if sv else d.get("tls.handshake.version") or 0
            vname = _TLS_VER.get(ver, "?") if 2 in hs else "—"
            res = "alert before the handshake finished" if alert and \
                2 not in hs else "ok"
            lat = (ts - s["ts"]) * 1000.0
            self._emit(kind="tls", ts=s["ts"], no=s["no"], reply_no=no,
                       client=s["client"], server=s["server"], name=s["sni"],
                       alpn=s["alpn"], version=vname, result=res,
                       latency_ms=round(lat, 2),
                       summary=f"{s['sni'] or s['server']}: {vname}, "
                               f"handshake {lat:.0f} ms"
                               + (f" (client offered {s['alpn']})"
                                  if s["alpn"] else "") if res == "ok" else
                               f"{s['sni'] or s['server']}: {res}")
            if 2 in hs and ver and ver < 0x0303:
                self.findings.append((no, ts, "warn", "Security",
                                      f"Old TLS version {vname} chosen for "
                                      f"{s['sni'] or s['server']}",
                                      "tls.handshake.version"))

    def _ntp(self, no, ts, d, src, dst):
        node = next((n for n in d.nodes if n.key == "ntp"), None)
        if node is None or node.length < 48:
            return
        b = d.raw[node.offset:node.offset + 48]
        mode = b[0] & 7
        if mode == 3:
            self.ntp[(src, dst, b[40:48])] = (ts, no)
            self._bound(self.ntp, self.MAX_PENDING)
        elif mode == 4:
            got = self.ntp.pop((dst, src, b[24:32]), None)
            if got is None:
                return
            t1, t2 = _ntp_time(b[24:32]), _ntp_time(b[32:40])
            t3, t4 = _ntp_time(b[40:48]), ts
            offset = ((t2 - t1) + (t3 - t4)) / 2 if t1 and t2 and t3 \
                else None
            delay = (t4 - t1) - (t3 - t2) if t1 and t2 and t3 else None
            self._emit(kind="ntp", ts=got[0], no=got[1], reply_no=no,
                       client=dst, server=src, stratum=b[1],
                       offset_ms=None if offset is None else
                       round(offset * 1000, 1),
                       latency_ms=round((ts - got[0]) * 1000.0, 2),
                       # 5.2.3 (B-43): round trip minus the server's own
                       # processing time, from the four NTP timestamps
                       delay_ms=None if delay is None else
                       round(delay * 1000.0, 2),
                       result="ok",
                       summary=f"time from {src} (stratum {b[1]})"
                               + (f", clock offset about "
                                  f"{offset * 1000:+.0f} ms (only meaningful "
                                  f"when the client is this computer)"
                                  if offset is not None else ""))

    def _sip_text(self, no, ts, data, src, dst, kind="sip"):
        first = data.split(b"\r\n", 1)[0][:200].decode("latin-1", "replace")
        m = re.match(r"^([A-Z]+) (\S+) (SIP|RTSP)/\d\.\d$", first)
        r = re.match(r"^(SIP|RTSP)/\d\.\d (\d{3}) ?(.*)$", first)
        if m:
            self._emit(kind=m.group(3).lower(), ts=ts, no=no, client=src,
                       server=dst, method=m.group(1), result="request",
                       summary=f"{m.group(3)} {m.group(1)} → {dst}")
        elif r:
            code = int(r.group(2))
            self._emit(kind=r.group(1).lower(), ts=ts, no=no, client=dst,
                       server=src, status=code, result=r.group(3)[:60],
                       summary=f"{r.group(1)} {code} {r.group(3)[:60]} "
                               f"from {src}")
            if code >= 400 and kind == "sip":
                self.findings.append((no, ts, "note", "Response code",
                                      f"SIP {code} {r.group(3)[:60]}",
                                      ""))

    # ---- reassembled messages -----------------------------------------------------
    def message(self, no, ts, st, m):
        if self.mail.message(no, ts, st, m):
            return None
        key = repr(st.key)
        server = st.key[1] if st.a == st.key[0] else st.key[0]
        client = st.a
        data = m.data
        if m.kind == "http":
            first = data.split(b"\r\n", 1)[0][:300].decode("latin-1",
                                                           "replace")
            if first.startswith(("RTSP/", "SIP/")) or re.match(
                    r"^[A-Z]+ \S+ (RTSP|SIP)/", first):
                return self._sip_text(no, ts, data, client[0] if
                                      m.direction == 0 else server[0],
                                      server[0] if m.direction == 0 else
                                      client[0], kind="rtsp")
            q = self.http.setdefault(key, deque(maxlen=64))
            mm = re.match(r"^([A-Z]+) (\S+) HTTP/1\.\d", first)
            if m.direction == 0 and mm:
                host = re.search(rb"\r\nhost:\s*([^\r\n]+)", data, re.I)
                q.append((ts, no, mm.group(1), mm.group(2).split("?", 1)[0]
                          [:200], host.group(1).decode("latin-1",
                                                       "replace")[:120]
                          if host else server[0], m.partial))
            elif m.direction == 1:
                rr = re.match(r"^HTTP/1\.\d (\d{3}) ?(.*)$", first)
                if not rr:
                    return None
                req = q.popleft() if q else None
                code = int(rr.group(1))
                if req is None:
                    self._emit(kind="http", ts=ts, no=no, client=client[0],
                               server=server[0], status=code,
                               result=rr.group(2)[:60],
                               summary=f"HTTP {code} (its request was not "
                                       f"captured)")
                    return None
                lat = (ts - req[0]) * 1000.0
                self._emit(kind="http", ts=req[0], no=req[1], reply_no=no,
                           client=client[0], server=server[0],
                           method=req[2], name=req[4], path=req[3],
                           status=code, result=rr.group(2)[:60],
                           latency_ms=round(lat, 2), bytes=len(data),
                           partial=bool(req[5] or m.partial),
                           summary=f"{req[2]} {req[4]}{req[3]} → {code} "
                                   f"{rr.group(2)[:40]} in {lat:.0f} ms"
                                   + (" (partial)" if m.partial or req[5]
                                      else ""))
            return None
        if m.kind == "line" and data.startswith(b"SSH-"):
            s = self.ssh.setdefault(key, {})
            s[m.direction] = data.strip()[:120].decode("latin-1", "replace")
            if m.direction == 1 and not s.get("done"):
                s["done"] = True
                self._emit(kind="ssh", ts=ts, no=no, client=client[0],
                           server=server[0], result="banner",
                           client_banner=s.get(0, ""),
                           server_banner=s.get(1, ""),
                           summary=f"SSH to {server[0]}: {s.get(1)}")
                if len(self.ssh) > self.MAX_PENDING:
                    self.ssh.clear()
            return None
        if m.kind == "nbss" and len(data) >= 4 + 64:
            smb = data[4:]
            if smb[:4] == b"\xffSMB" and key not in self.ssh:
                self.ssh[key] = {"done": True}      # once per connection
                self._emit(kind="smb", ts=ts, no=no, client=client[0],
                           server=server[0], dialect="1 (obsolete)",
                           result="SMB1", summary=f"SMB1 with "
                           f"{server[0]} (obsolete and unsafe)")
                self.findings.append((no, ts, "warn", "Security",
                                      f"SMB version 1 in use with "
                                      f"{server[0]} (obsolete; disable it "
                                      f"if you can)", ""))
            elif smb[:4] == b"\xfeSMB":
                cmd = struct.unpack_from("<H", smb, 12)[0]
                flags = struct.unpack_from("<I", smb, 16)[0]
                if cmd == 0 and flags & 1 and len(smb) >= 64 + 6:
                    dia = struct.unpack_from("<H", smb, 64 + 4)[0]
                    dn = _SMB_DIALECTS.get(dia, f"0x{dia:04x}")
                    self._emit(kind="smb", ts=ts, no=no, client=client[0],
                               server=server[0], dialect=dn, result="ok",
                               summary=f"SMB {dn} with {server[0]}")
            return None
        if m.kind == "mqtt" and data:
            t = data[0] >> 4
            s = self.mqtt.setdefault(key, Counter())
            s[_MQTT_TYPES.get(t, str(t))] += 1
            if t == 2 and len(data) >= 4:
                rc = data[3]
                res = _MQTT_CONNACK.get(rc, f"code {rc}")
                self._emit(kind="mqtt", ts=ts, no=no, client=client[0],
                           server=server[0], result=res,
                           summary=f"MQTT connection to {server[0]}: {res}")
                if rc:
                    self.findings.append((no, ts, "note", "Response code",
                                          f"MQTT broker {server[0]} {res}",
                                          ""))
        return None


class DeepAnalyzer:
    """Stateful deep pass for one share of the flows. Pure Python, no Tk,
    no scapy: used by the deep thread and by worker processes alike."""

    ANALYZERS = ("dissect", "reassembly", "protocols", "expert")

    def __init__(self, my_ips=(), per_stream=256 * 1024,
                 total=64 * 1024 * 1024):
        self.my_ips = set(my_ips)
        self.tcp = TcpReassembler(per_stream=per_stream, total=total)
        self.frag = IpDefragmenter()
        self.cost_ns = {a: 0 for a in self.ANALYZERS}
        self.count = 0
        self.proto = ProtocolTracker()
        self._seen_msgs = {}       # stream key -> messages already reported

    def process(self, no, ts, lt, raw):
        """→ (findings, messages, transactions). findings: [(no, ts,
        severity, group, summary, field_key)]; messages: [(stream, dir,
        kind, start, end, partial, preview, no)]; transactions: [dict]."""
        self.count += 1
        f = []
        t0 = time.perf_counter_ns()
        d = dissect(raw, lt)
        t1 = time.perf_counter_ns()
        self.cost_ns["dissect"] += t1 - t0
        msgs = []
        src = d.get("ip.src") or d.get("ipv6.src")
        dst = d.get("ip.dst") or d.get("ipv6.dst")
        notes_before = None
        st = None
        new_msgs, finished = (), False
        if src and (d.get("ip.flags.mf") or d.get("ip.frag_offset")):
            ipn = next(n for n in d.nodes if n.key == "ip")
            hl = d.get("ip.hdr_len") or 20
            whole, warn = self.frag.add(
                (src, dst, d.get("ip.proto"), d.get("ip.id")),
                d.get("ip.frag_offset") or 0, bool(d.get("ip.flags.mf")),
                raw[ipn.offset + hl:ipn.offset + ipn.length], ts)
            if warn and "different content" in warn:
                f.append((no, ts, "warn", "Security",
                          "Overlapping IP fragments with different "
                          "content", "ip.frag_offset"))
        elif d.get("tcp.srcport") is not None and src and \
                d.get("tcp.seq_raw") is not None and \
                d.get("tcp.flags") is not None:      # S4: cut-off header
            tcpn = next(n for n in d.nodes if n.key == "tcp")
            hl = d.get("tcp.hdr_len") or 20
            key = TcpReassembler.stream_key(src, d.get("tcp.srcport"), dst,
                                            d.get("tcp.dstport"))
            old = self.tcp.streams.get(key)
            dups = sum(x.dups for x in old.dirs) if old else 0
            notes_before = len(old.notes) if old else 0
            st = self.tcp.segment(
                src, d.get("tcp.srcport"), dst, d.get("tcp.dstport"),
                d.get("tcp.seq_raw"), d.get("tcp.flags"),
                raw[tcpn.offset + hl:tcpn.offset + tcpn.length], ts)
            if old is not st:
                notes_before, dups = 0, 0
            if sum(x.dups for x in st.dirs) > dups and \
                    d.get("tcp.len"):
                f.append((no, ts, "note", "Sequence",
                          "Retransmission (data seen before)", "tcp.seq_raw"))
            for n in st.notes[notes_before:]:
                if "conflicting" in n:
                    f.append((no, ts, "warn", "Security",
                              "Retransmitted data differs from the first "
                              "copy (" + n + ")", "tcp.seq_raw"))
                elif "never seen" in n:
                    f.append((no, ts, "note", "Sequence",
                              "Missing bytes: " + n, "tcp.seq_raw"))
            new_msgs = st.messages[self._seen_msgs.get(st.key, 0):]
            finished = st.key not in self.tcp.streams
            self._seen_msgs[st.key] = len(st.messages)
        t2 = time.perf_counter_ns()
        self.cost_ns["reassembly"] += t2 - t1
        try:
            self.proto.packet(no, ts, d, src, dst)
            for m in new_msgs:
                self.proto.message(no, ts, st, m)
            for m in new_msgs:
                msgs.append((repr(st.key), m.direction, m.kind, m.start,
                             m.end, m.partial, self.proto.mail.preview(st, m)
                             or _deep_preview(m.kind, m.data), no))
            if st is not None and finished:
                self.proto.closed(st, ts, "reset" if st.reset else "closed")
        except (ValueError, IndexError, KeyError, struct.error) as e:
            f.append((no, ts, "note", "Malformed", f"Could not follow the "
                      f"protocol exchange ({type(e).__name__})", ""))
        txns, pf = self.proto.take()
        f.extend(pf)
        t3 = time.perf_counter_ns()
        self.cost_ns["protocols"] += t3 - t2
        t2 = t3
        f.extend(self._rules(no, ts, d, src))
        self.cost_ns["expert"] += time.perf_counter_ns() - t2
        if len(self._seen_msgs) > 8192:
            live = set(map(lambda s: s.key, self.tcp.streams.values()))
            self._seen_msgs = {k: v for k, v in self._seen_msgs.items()
                               if k in live}
        return f, msgs, txns

    def _rules(self, no, ts, d, src):
        out = []
        for title, w in d.warnings():
            if "checksum" in w:
                if src not in self.my_ips:
                    out.append((no, ts, "note", "Checksum",
                                f"{title}: checksum does not match", ""))
            elif "truncated" in w:
                out.append((no, ts, "warn", "Malformed", f"{title}: {w}",
                            ""))
            elif "malformed" in w or "too short" in w:
                out.append((no, ts, "error", "Malformed", f"{title}: {w}",
                            ""))
            elif w.startswith("fragment"):
                out.append((no, ts, "chat", "Sequence", f"IP {w}",
                            "ip.frag_offset"))
        fl = d.get("tcp.flags")
        if fl is not None:
            if fl & 0x04:
                out.append((no, ts, "warn", "Sequence",
                            "Connection reset (RST)", "tcp.flags.reset"))
            elif d.get("tcp.window_size_value") == 0 and not fl & 0x02:
                out.append((no, ts, "warn", "Sequence",
                            "Zero window: the receiver has no room left",
                            "tcp.window_size_value"))
            if fl & 0x02 and not fl & 0x10:
                out.append((no, ts, "chat", "Sequence",
                            "Connection opened (SYN)", "tcp.flags.syn"))
        rc = d.get("dns.flags.rcode")
        if rc and d.get("dns.flags.response"):
            name = d.get("dns.qry.name") or "?"
            out.append((no, ts, "note" if rc == 3 else "warn",
                        "Response code", f"DNS {_DNS_RCODES.get(rc, rc)} "
                        f"for {name}", "dns.flags.rcode"))
        code = d.get("http.response.code")
        if code and code >= 400:
            out.append((no, ts, "warn" if code >= 500 else "note",
                        "Response code", f"HTTP {code} "
                        f"{d.get('http.response.phrase') or ''}".strip(),
                        "http.response.code"))
        if 21 in d.values("tls.record.content_type"):
            out.append((no, ts, "note", "Protocol", "TLS alert (the "
                        "connection reported an error or closed)",
                        "tls.record.content_type"))
        if d.get("icmp.type") == 3 or d.get("icmpv6.type") == 1:
            out.append((no, ts, "note", "Protocol", "Destination "
                        "unreachable", "icmp.type"))
        return out

    def flush(self, now, final=False):
        """Close idle streams (or all of them when final) and report the
        messages that closing completed."""
        msgs = []
        if final:
            self.tcp.flush(now)
        else:
            self.tcp.expire(now)
        for st in list(self.tcp.closed):
            done = self._seen_msgs.get(st.key, 0)
            for m in st.messages[done:]:
                with contextlib.suppress(ValueError, IndexError, KeyError,
                                         struct.error):
                    self.proto.message(0, now or 0.0, st, m)
                msgs.append((repr(st.key), m.direction, m.kind, m.start,
                             m.end, m.partial, self.proto.mail.preview(st, m)
                             or _deep_preview(m.kind, m.data), 0))
            self._seen_msgs[st.key] = len(st.messages)
            with contextlib.suppress(ValueError, IndexError, KeyError):
                self.proto.closed(st, st.last, "idle" if not final else
                                  "end of capture")
        self.proto._expire((now or 0.0) + ProtocolTracker.DNS_TIMEOUT + 1
                           if final else (now or 0.0))
        txns, pf = self.proto.take()
        return msgs, txns, pf

    def costs_us(self):
        n = max(1, self.count)
        return {k: v / 1000.0 / n for k, v in self.cost_ns.items()}


# ---- the worker process side --------------------------------------------------
def _wire_send(stream, obj):
    data = marshal.dumps(obj)
    stream.write(struct.pack("!I", len(data)) + data)
    stream.flush()


def _wire_recv(stream):
    head = stream.read(4)
    if len(head) < 4:
        return None
    n = struct.unpack("!I", head)[0]
    if n > 256 * 1024 * 1024:
        raise ValueError("message too large")
    data = stream.read(n)
    if len(data) < n:
        return None
    return marshal.loads(data)


def deep_worker_main(inp=None, out=None):
    """Entry point of `python miniwireshark.py --mw-worker`: reads batches
    of frames on stdin, writes compact results on stdout. Never touches
    the network, the GUI or any file."""
    if inp is None:
        inp = getattr(sys.stdin, "buffer", None) or os.fdopen(0, "rb")
    if out is None:
        out = getattr(sys.stdout, "buffer", None) or os.fdopen(1, "wb")
        # anything a library prints from now on goes to stderr, never into
        # the binary result stream
        sys.stdout = sys.stderr if sys.stderr is not None else \
            open(os.devnull, "w", encoding="utf-8")
    an = DeepAnalyzer()
    _wire_send(out, ("ready", SCRIPT_VERSION, os.getpid()))
    while True:
        msg = _wire_recv(inp)
        if msg is None or msg[0] == "stop":
            return 0
        if msg[0] == "config":
            an.my_ips = set(msg[1])
            continue
        if msg[0] == "flush":
            try:
                m2, t2, f2 = an.flush(msg[2], msg[3])
            except Exception as e:                    # noqa: BLE001
                # QA-07: a dissector error at the end of a capture must
                # not end the worker (its queued batches would be lost)
                LOG.warning("deep flush failed: %s", type(e).__name__)
                m2, t2, f2 = [], [], []
            _wire_send(out, ("flushed", msg[1], m2, an.costs_us(), t2, f2))
            continue
        if msg[0] == "batch":
            epoch, items = msg[1], msg[2]
            findings, messages, txns = [], [], []
            for no, ts, lt, raw in items:
                try:
                    f, m, t = an.process(no, ts, lt, raw)
                except Exception as e:                # noqa: BLE001
                    f, m, t = [(no, ts, "error", "Malformed",
                                f"Deep analysis failed: {type(e).__name__}",
                                "")], [], []
                findings.extend(f)
                messages.extend(m)
                txns.extend(t)
            _wire_send(out, ("res", epoch, len(items), findings, messages,
                             an.costs_us(), txns))


def deep_value(d):
    """How much a packet is worth deep-analysing: 3 control / names /
    alerts, 2 ordinary, 1 bulk repeat. Smart shedding drops 1 first."""
    tr = d.get("transport")
    if tr == "TCP":
        fl = d.get("tcp_flags") or 0
        if fl & 0x07 or d.get("win") == 0:
            return 3
        if d.get("tls") is not None or d.get("http_host") or \
                d.get("dns") is not None:
            return 3
        ports = {d.get("sport"), d.get("dport")}
        if ports & {21, 25, 53, 110, 143, 587, 80, 8080, 22, 23}:
            return 3
        return 1 if (d.get("payload_len") or 0) >= 1000 or \
            not d.get("payload_len") else 2
    if tr == "UDP":
        if d.get("dns") is not None or d.get("dhcp") is not None or \
                d.get("mdns") is not None or d.get("ssdp") is not None:
            return 3
        return 1 if (d.get("payload_len") or 0) >= 1000 else 2
    return 3                      # ARP, ICMP, ND, other link protocols


class DeepStore:
    """What the deep pass found (bounded; shared with the window)."""

    def __init__(self, max_findings=20000, max_messages=20000,
                 max_txns=20000):
        self.findings = deque(maxlen=max_findings)
        self.messages = deque(maxlen=max_messages)
        self.txns = deque(maxlen=max_txns)
        self.by_kind = Counter()
        self.by_sev = Counter()
        self.by_group = Counter()
        self.lock = threading.Lock()
        self.version = 0

    def add(self, findings, messages, txns=()):
        if not findings and not messages and not txns:
            return
        with self.lock:
            for t in txns:
                self.txns.append(t)
                self.by_kind[t.get("kind", "?")] += 1
            for f in findings:
                self.findings.append(tuple(f))
                self.by_sev[f[2]] += 1
                self.by_group[f[3]] += 1
            self.messages.extend(tuple(m) for m in messages)
            self.version += 1

    def clear(self):
        with self.lock:
            self.findings.clear()
            self.messages.clear()
            self.txns.clear()
            self.by_kind.clear()
            self.by_sev.clear()
            self.by_group.clear()
            self.version += 1

    def summary(self):
        with self.lock:
            if not self.findings:
                return "no findings"
            return ", ".join(f"{self.by_sev[s]} {s}" for s in
                             DEEP_SEVERITIES if self.by_sev[s])


class _DeepWorkerProc:
    """One `--mw-worker` process: a writer feeds it batches, a reader
    collects its results. At most IN_FLIGHT batches outstanding."""

    IN_FLIGHT = 4

    def __init__(self, engine, idx):
        self.engine, self.idx = engine, idx
        self.items = deque()
        self.cv = threading.Condition()
        self.inflight = 0
        self.alive = False
        self.error = ""
        self.costs = {}
        self.proc = None

    def start(self, my_ips, timeout=20.0):
        self.launch()
        self.handshake(my_ips, time.monotonic() + timeout)

    def launch(self):
        script = os.path.abspath(__file__)
        env = dict(os.environ)
        env["PYTHONIOENCODING"] = "utf-8"
        lp = os.path.join(PATHS.logs, f"deep-worker-{self.idx}.log")
        with contextlib.suppress(OSError):          # keep the log small
            if os.path.getsize(lp) > 1024 * 1024:
                os.replace(lp, lp + ".1")
        kw = {}
        if IS_WINDOWS:
            kw["creationflags"] = 0x08000000          # CREATE_NO_WINDOW
        with open(lp, "ab") as log:     # the child keeps its own handle
            self.proc = subprocess.Popen(
                cached_cmd(sys.executable, script, [WORKER_FLAG]),
                stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=log,
                env=cached_env(env), **kw)

    def handshake(self, my_ips, deadline):
        """Wait for the child's "ready" until `deadline` (5.2.3, B-05:
        the wait had no limit, so a child stuck at start — an antivirus
        scan — stopped the analysis for good)."""
        box = []
        t = threading.Thread(target=lambda: box.append(
            _wire_recv(self.proc.stdout)), daemon=True,
            name=f"deep-w{self.idx}-hello")
        t.start()
        t.join(max(0.0, deadline - time.monotonic()))
        if t.is_alive():
            with contextlib.suppress(Exception):
                self.proc.kill()
            raise RuntimeError("deep worker did not answer in time")
        hello = box[0] if box else None
        if not hello or hello[0] != "ready":
            raise RuntimeError("deep worker did not start")
        _wire_send(self.proc.stdin, ("config", sorted(my_ips)))
        self.alive = True
        threading.Thread(target=self._writer, daemon=True,
                         name=f"deep-w{self.idx}-out").start()
        threading.Thread(target=self._reader, daemon=True,
                         name=f"deep-w{self.idx}-in").start()

    def put(self, item):
        with self.cv:
            self.items.append(item)
            self.cv.notify()

    def pending(self):
        return len(self.items) + self.inflight * 256

    def _writer(self):
        try:
            while self.alive:
                with self.cv:
                    while self.alive and (not self.items or
                                          self.inflight >= self.IN_FLIGHT):
                        self.cv.wait(0.2)
                    if not self.alive:
                        break
                    batch = [self.items.popleft() for _ in range(
                        min(256, len(self.items)))]
                    self.inflight += 1
                epoch = self.engine.epoch
                _wire_send(self.proc.stdin, ("batch", epoch,
                                             [b[:4] for b in batch]))
        except (OSError, ValueError) as e:
            self._died(e)

    def _reader(self):
        try:
            while self.alive:
                msg = _wire_recv(self.proc.stdout)
                if msg is None:
                    raise OSError("worker closed its output")
                if msg[0] == "res":
                    _k, _epoch, n, findings, messages, costs, txns = msg
                    self.costs = costs
                    self.engine._results(n, findings, messages, txns)
                    with self.cv:
                        self.inflight -= 1
                        self.cv.notify()
                elif msg[0] == "flushed":
                    self.engine.store.add(msg[5], msg[2], msg[4])
                    self.costs = msg[3]
        except (OSError, ValueError, EOFError) as e:
            self._died(e)

    def _died(self, e):
        if self.alive:
            self.alive = False
            self.error = f"{type(e).__name__}: {e}"
            LOG.warning("deep worker %d stopped: %s", self.idx, self.error)
            lost = len(self.items) + self.inflight * 256
            self.items.clear()
            self.engine._lost(lost)

    def flush(self, now, final=False):
        with contextlib.suppress(OSError, ValueError):
            if self.alive:
                with self.cv:
                    pass
                _wire_send(self.proc.stdin, ("flush", 0, now, final))

    def stop(self, kill=False, deadline=None):
        """kill=True (closing the app): end the process at once; a worker
        keeps no state, and one blocked writing results to a full pipe
        never reads "stop" (5.2.3, B-04: up to 2 s per worker on the Tk
        thread). deadline: shared time.monotonic() limit for the wait."""
        self.alive = False
        with self.cv:
            self.cv.notify_all()
        if self.proc is None:
            return
        if not kill:
            self.ask_stop()
            left = 2.0 if deadline is None else \
                max(0.0, deadline - time.monotonic())
            with contextlib.suppress(Exception):
                self.proc.wait(timeout=left)
        if self.proc.poll() is None:
            with contextlib.suppress(Exception):
                self.proc.kill()
            with contextlib.suppress(Exception):
                self.proc.wait(timeout=0.5)

    def ask_stop(self):
        if self.proc is not None and self.proc.poll() is None:
            with contextlib.suppress(OSError, ValueError):
                _wire_send(self.proc.stdin, ("stop",))


class DeepEngine:
    """Schedules the deep pass: decides per packet whether it is eligible
    (the mode), worth it (Smart shedding with measured costs) and where it
    runs (worker processes or a thread). Every offered packet ends in one
    bucket: deep-analysed, skipped by budget, or lost with a worker."""

    QUEUE_CAP = 20000
    START_TIMEOUT = 30.0            # all worker processes together

    def __init__(self, store=None):
        self.store = store or DeepStore()
        self.mode = "Normal"
        self.backend = "off"          # off | thread | process
        self.workers = []
        self.thread = None
        self.analyzer = None
        self.pending = deque()
        self.cv = threading.Condition()
        self.epoch = 0
        self.policy = "Smart"
        self.cores = 1
        self.ram_mb = 1536
        self.my_ips = set()
        self.offered = self.done = self.shed = self.lost = 0
        self.shed_why = Counter()
        self.window = deque()          # (second, offered, done, shed)
        self.stop_flag = False
        self.last_error = ""
        self.want_process = True
        self._busy_ns = 0
        self._t_start = time.monotonic()

    # ---- configuration ------------------------------------------------------
    def configure(self, mode, cores=2, ram_mb=1536, policy="Smart",
                  my_ips=(), prefer_process=True):
        """Atomic switch at a batch boundary (called by the analysis
        worker between batches). Returns True when the mode changed."""
        changed = mode != self.mode
        self.cores, self.ram_mb, self.policy = cores, ram_mb, policy
        self.my_ips = set(my_ips)
        self.want_process = prefer_process
        if changed:
            self.epoch += 1
            self.mode = mode
            if mode != "Full Power":
                with self.cv:
                    n = len(self.pending)
                    self.pending.clear()
                if n:
                    self._count_shed(n, "mode change")
        return changed

    def active(self):
        return self.mode == "Full Power"

    def _ensure_backend(self):
        if self.backend != "off" and (
                self.backend == "thread" and self.thread is not None and
                self.thread.is_alive() or
                self.backend == "process" and any(w.alive for w in
                                                  self.workers)):
            return
        n = max(1, min(self.cores, (os.cpu_count() or 1) - 1))
        if self.want_process and (os.cpu_count() or 1) > 1:
            try:
                # 5.2.3 (B-05): all children start together (each one
                # compiles or loads the program: ~2.5 s on Windows, which
                # used to add up one after another on the analysis thread)
                ws = []
                for i in range(n):
                    w = _DeepWorkerProc(self, i)
                    w.launch()
                    ws.append(w)
                deadline = time.monotonic() + self.START_TIMEOUT
                for w in ws:
                    w.handshake(self.my_ips, deadline)
                self.workers, self.backend = ws, "process"
                return
            except Exception as e:                   # noqa: BLE001
                self.last_error = f"worker processes unavailable: {e}"
                LOG.warning("deep analysis: %s; using a thread",
                            self.last_error)
                for w in locals().get("ws", []):
                    w.stop(kill=True)
        self.analyzer = DeepAnalyzer(self.my_ips,
                                     total=self.ram_mb * 1024 * 1024 // 2)
        self.thread = threading.Thread(target=self._thread_loop, daemon=True,
                                       name="deep")
        self.backend = "thread"
        self.thread.start()

    # ---- the scheduler -------------------------------------------------------
    def cost_us(self):
        """Measured microseconds per packet (all analyzers)."""
        costs = self.analyzer_costs()
        return sum(costs.values()) if costs else 70.0

    def analyzer_costs(self):
        if self.backend == "process":
            agg = Counter()
            ws = [w for w in self.workers if w.costs]
            for w in ws:
                for k, v in w.costs.items():
                    agg[k] += v / len(ws)
            return dict(agg)
        return self.analyzer.costs_us() if self.analyzer else {}

    def queued(self):
        if self.backend == "process":
            return len(self.pending) + sum(w.pending() for w in self.workers)
        return len(self.pending)

    def offer(self, d, no):
        """Called by the analysis worker for each committed packet."""
        if self.mode != "Full Power" or d.get("raw") is None:
            return False
        self.offered += 1
        self._tick(1, 0, 0)
        v = deep_value(d)
        q = self.queued()
        lanes = max(1, len(self.workers) if self.backend == "process" else 1)
        drain = q * self.cost_us() / 1e6 / lanes
        cap = self.QUEUE_CAP if self.policy != "Strict" else \
            self.QUEUE_CAP // 4
        why = ""
        if q >= cap:
            why = "queue full"
        elif self.policy == "Smart" and ((drain > 2.0 and v == 1) or
                                         (drain > 5.0 and v <= 2)):
            why = "busy: low-value packet"
        elif self.policy == "Strict" and drain > 1.0:
            why = "over budget"
        if why:
            self._count_shed(1, why)
            return False
        self._ensure_backend()
        item = (no, d.get("time", 0.0), d.get("linktype", 1), d["raw"], v)
        if self.backend == "process":
            live = [w for w in self.workers if w.alive]
            if not live:
                self._lost(1)
                return False
            key = (d.get("src_ip") or "", d.get("sport") or 0), \
                (d.get("dst_ip") or "", d.get("dport") or 0)
            h = zlib.crc32(repr(min(key) + max(key)).encode())
            live[h % len(live)].put(item)
        else:
            with self.cv:
                self.pending.append(item)
                self.cv.notify()
        return True

    def _count_shed(self, n, why):
        self.shed += n
        self.shed_why[why] += n
        self._tick(0, 0, n)

    def _lost(self, n):
        self.lost += n

    def _results(self, n, findings, messages, txns=()):
        self.done += n
        self._tick(0, n, 0)
        self.store.add(findings, messages, txns)

    def _tick(self, off, done, shed):
        sec = int(time.monotonic())
        w = self.window
        if w and w[-1][0] == sec:
            s, a, b, c = w[-1]
            w[-1] = (s, a + off, b + done, c + shed)
        else:
            w.append((sec, off, done, shed))
            while w and w[0][0] < sec - 60:
                w.popleft()

    def coverage_60s(self):
        """→ (percent deep-analysed of eligible, offered, done, shed)."""
        sec = int(time.monotonic())
        off = done = shed = 0
        for s, a, b, c in list(self.window):
            if s >= sec - 60:
                off, done, shed = off + a, done + b, shed + c
        pct = 100.0 * done / off if off else 100.0
        return min(100.0, pct), off, done, shed

    def in_flight(self):
        return max(0, self.offered - self.done - self.shed - self.lost)

    # ---- the thread backend --------------------------------------------------
    def _thread_loop(self):
        an = self.analyzer
        while not self.stop_flag and self.backend == "thread":
            with self.cv:
                while not self.pending and not self.stop_flag:
                    self.cv.wait(0.25)
                batch = [self.pending.popleft() for _ in range(
                    min(256, len(self.pending)))]
            if not batch:
                continue
            t0 = time.perf_counter_ns()
            findings, messages, txns = [], [], []
            for no, ts, lt, raw, _v in batch:
                try:
                    f, m, t = an.process(no, ts, lt, raw)
                except Exception as e:               # noqa: BLE001
                    f, m, t = [(no, ts, "error", "Malformed",
                                f"Deep analysis failed: {type(e).__name__}",
                                "")], [], []
                findings.extend(f)
                messages.extend(m)
                txns.extend(t)
            self._busy_ns += time.perf_counter_ns() - t0
            self._results(len(batch), findings, messages, txns)
            time.sleep(0)               # let capture and the window in

    # ---- lifecycle -------------------------------------------------------------
    def flush(self, final=False):
        now = time.time()
        if self.backend == "process":
            for w in self.workers:
                w.flush(now, final)
        elif self.analyzer is not None:
            with self.cv:
                idle = not self.pending
            if idle:
                m, t, f = self.analyzer.flush(now, final)
                self.store.add(f, m, t)

    def drain(self, timeout=30.0):
        """Wait until everything offered is analysed (tests, imports)."""
        t_end = time.time() + timeout
        while self.in_flight() and time.time() < t_end:
            time.sleep(0.02)
        return self.in_flight() == 0

    def reset(self):
        """A new session: fresh state, same backend."""
        with self.cv:
            self.pending.clear()
        self.epoch += 1
        self.offered = self.done = self.shed = self.lost = 0
        self.shed_why.clear()
        self.window.clear()
        self.store.clear()
        if self.backend == "thread" and self.analyzer is not None:
            self.analyzer.__init__(self.my_ips,
                                   total=self.ram_mb * 1024 * 1024 // 2)
        elif self.backend == "process":
            for w in self.workers:
                w.stop()
            self.workers, self.backend = [], "off"

    def stop(self, kill=False):
        """Stops every worker under one shared 2 s deadline (5.2.3: was
        2 s each, one after another); kill=True when the app closes."""
        self.stop_flag = True
        with self.cv:
            self.cv.notify_all()
        if not kill:
            for w in self.workers:
                w.ask_stop()
        deadline = time.monotonic() + 2.0
        for w in self.workers:
            w.stop(kill=kill, deadline=deadline)
        self.workers = []
        self.backend = "off"

    def status_text(self):
        pct, off, done, shed = self.coverage_60s()
        costs = self.analyzer_costs()
        lines = [
            f"Mode                {self.mode}",
            f"Runs in             {self.backend}"
            + (f" ({len(self.workers)} worker process"
               f"{'es' if len(self.workers) != 1 else ''})"
               if self.backend == "process" else ""),
            f"Offered / analysed  {self.offered:,} / {self.done:,} "
            f"(skipped {self.shed:,}, lost {self.lost:,}, waiting "
            f"{self.in_flight():,})",
            f"Last 60 s           {pct:.0f} % of {off:,} eligible "
            f"packets deep-analysed",
            "Skipped because     " + (", ".join(
                f"{k} ({v:,})" for k, v in self.shed_why.most_common())
                or "—"),
            "Cost per packet     " + (", ".join(
                f"{k} {v:.0f} µs" for k, v in costs.items()) or
                "not measured yet"),
            f"Findings            {self.store.summary()}",
            "Exchanges followed  " + (", ".join(
                f"{k} {v:,}" for k, v in self.store.by_kind.most_common())
                or "none yet"),
        ]
        if self.last_error:
            lines.append(f"Note                {self.last_error}")
        return lines


def tls_app_record(n):
    """n bytes of TLS application data with a correct record header (the
    content itself is zeros: it is encrypted on a real network)."""
    n = max(5, n)
    return b"\x17\x03\x03" + struct.pack("!H", n - 5) + bytes(n - 5)


def build_client_hello(sni, alpn=("h2", "http/1.1"), pad=600, rnd=None):
    """A syntactically valid TLS 1.3-style ClientHello (used by Demo Mode
    and the self-tests). `rnd` = the 32-byte client random (scenarios pass
    a seeded one so their bytes never change)."""
    host = sni.encode("ascii")
    ext_sni = struct.pack(">HHHBH", 0, len(host) + 5, len(host) + 3, 0,
                          len(host)) + host
    al = b"".join(bytes([len(a)]) + a.encode() for a in alpn)
    ext_alpn = struct.pack(">HHH", 16, len(al) + 2, len(al)) + al
    ext_ver = struct.pack(">HHB", 43, 5, 4) + b"\x03\x04\x03\x03"
    ext_pad = struct.pack(">HH", 21, pad) + b"\x00" * pad
    exts = ext_ver + ext_pad + ext_alpn + ext_sni
    body = (b"\x03\x03" + (rnd or os.urandom(32)) + b"\x00" + b"\x00\x04\x13\x01\x13"
            b"\x02" + b"\x01\x00" + struct.pack(">H", len(exts)) + exts)
    hs = b"\x01" + struct.pack(">I", len(body))[1:] + body
    return b"\x16\x03\x01" + struct.pack(">H", len(hs)) + hs


class DemoGenerator(threading.Thread):
    L = PK                    # our own packet builder: works without scapy
    GW = ("192.168.50.1", "02:00:5e:10:00:01")
    ME = ("192.168.50.10", "02:00:5e:10:00:10")
    DEVICES = [
        # ip, mac, dhcp hostname, vendor class, mdns service/name/txt
        ("192.168.50.23", "da:a1:19:23:45:67", "Alex-iPhone", "", None),
        ("192.168.50.40", "f4:f5:d8:40:00:40", "", "",
         ("_googlecast._tcp", "Living Room TV", {"md": "Chromecast",
                                                 "fn": "Living Room TV"})),
        ("192.168.50.50", "00:80:77:50:00:50", "BRW008077500050", "",
         ("_ipp._tcp", "Brother HL-L2350DW", {"ty": "Brother HL-L2350DW"})),
        ("192.168.50.60", "24:0a:c4:60:00:60", "ESP_6A1B2C", "udhcp 1.30",
         None),
        ("192.168.50.70", "00:11:32:70:00:70", "family-nas", "",
         ("_smb._tcp", "family-nas", {"model": "DS220+"})),
    ]
    LATE = ("192.168.50.88", "3c:22:fb:88:00:88", "DESKTOP-GUEST7Q",
            "MSFT 5.0")
    SITES = [("www.example.com", "93.184.215.14"),
             ("news.example.org", "151.101.65.69"),
             ("video.example.net", "142.250.80.46"),
             ("cdn.example.net", "104.18.32.47"),
             ("api.example.com", "34.117.59.81"),
             ("updates.example.com", "52.84.150.39"),
             ("photos.example.org", "185.199.108.153"),
             ("mail.example.com", "23.215.0.136")]

    def __init__(self, sink):
        super().__init__(daemon=True, name="demo")
        self.sink = sink              # sink(raw, ts, lt, cancelled)
        self.stop_flag = False
        self.t0 = time.time()
        self.port = 40000

    def stop(self):
        self.stop_flag = True

    def _emit(self, p):
        self.sink(bytes(p), time.time(), 1, lambda: self.stop_flag)

    def _eth(self, src, dst):
        return self.L.Ether(src=src[1], dst=dst[1] if isinstance(dst, tuple)
                     else dst)

    def _dhcp(self, ip, mac, host, vc):
        chaddr = bytes.fromhex(mac.replace(":", ""))
        opts = [("message-type", "request"), ("requested_addr", ip)]
        if host:
            opts.append(("hostname", host.encode()))
        if vc:
            opts.append(("vendor_class_id", vc.encode()))
        self._emit(self.L.Ether(src=mac, dst="ff:ff:ff:ff:ff:ff") /
                   self.L.IP(src="0.0.0.0", dst="255.255.255.255") /
                   self.L.UDP(sport=68, dport=67) / self.L.BOOTP(chaddr=chaddr) /
                   self.L.DHCP(options=opts + ["end"]))
        self._emit(self.L.Ether(src=self.GW[1], dst=mac) /
                   self.L.IP(src=self.GW[0], dst=ip) / self.L.UDP(sport=67, dport=68) /
                   self.L.BOOTP(op=2, yiaddr=ip, chaddr=chaddr) /
                   self.L.DHCP(options=[("message-type", "ack"),
                                 ("lease_time", 86400),
                                 ("router", self.GW[0]),
                                 ("name_server", self.GW[0]), "end"]))

    def _mdns(self, ip, mac, svc, name, txt):
        txtv = [f"{k}={v}".encode() for k, v in txt.items()]
        self._emit(self.L.Ether(src=mac, dst="01:00:5e:00:00:fb") /
                   self.L.IP(src=ip, dst="224.0.0.251", ttl=255) /
                   self.L.UDP(sport=5353, dport=5353) /
                   self.L.DNS(qr=1, aa=1, qd=None,
                       an=self.L.DNSRR(rrname=f"{svc}.local", type="PTR",
                                rdata=f"{name}.{svc}.local"),
                       ar=[self.L.DNSRR(rrname=f"{name}.{svc}.local", type="TXT",
                                 rdata=txtv),
                           self.L.DNSRR(rrname=f"{name.replace(' ', '-')}.local",
                                 rdata=ip)]))

    def _visit_quic(self, dev, site, sip, sp, size):
        """An HTTP/3 visit: the first packet names the site (readable by
        design), everything after it is opaque."""
        ip, mac = dev[0], dev[1]
        base = self.L.Ether(src=mac, dst=self.GW[1]) / self.L.IP(src=ip, dst=sip) / \
            self.L.UDP(sport=sp, dport=443)
        back = self.L.Ether(src=self.GW[1], dst=mac) / self.L.IP(src=sip, dst=ip, ttl=54) \
            / self.L.UDP(sport=443, dport=sp)
        dcid = os.urandom(8)
        self._emit(base / self.L.Raw(quic_build_initial(
            dcid, os.urandom(4), tls_client_hello(site))))
        time.sleep(random.uniform(0.018, 0.045))
        sent = 0
        while sent < size and not self.stop_flag:
            chunk = min(1250, size - sent)
            self._emit(back / self.L.Raw(b"\x40" + os.urandom(8) +
                                  b"\x00" * (chunk - 9)))
            sent += chunk

    def _visit(self, dev, site, sip, size=40000):
        ip, mac = dev[0], dev[1]
        self.port += 1
        sp = self.port
        qid = random.randint(1, 65000)
        self._emit(self.L.Ether(src=mac, dst=self.GW[1]) / self.L.IP(src=ip, dst=self.GW[0])
                   / self.L.UDP(sport=sp, dport=53) /
                   self.L.DNS(id=qid, rd=1, qd=self.L.DNSQR(qname=site)))
        time.sleep(0.02)
        self._emit(self.L.Ether(src=self.GW[1], dst=mac) / self.L.IP(src=self.GW[0], dst=ip)
                   / self.L.UDP(sport=53, dport=sp) /
                   self.L.DNS(id=qid, qr=1, qd=self.L.DNSQR(qname=site),
                       an=self.L.DNSRR(rrname=site, rdata=sip, ttl=300)))
        seq = random.randint(1000, 10 ** 9)
        base = self.L.Ether(src=mac, dst=self.GW[1]) / self.L.IP(src=ip, dst=sip)
        back = self.L.Ether(src=self.GW[1], dst=mac) / self.L.IP(src=sip, dst=ip, ttl=54)
        if random.random() < 0.3:
            self._visit_quic(dev, site, sip, sp, size)
            return
        self._emit(base / self.L.TCP(sport=sp, dport=443, flags="S", seq=seq))
        time.sleep(random.uniform(0.018, 0.045))     # an Internet round trip
        self._emit(back / self.L.TCP(sport=443, dport=sp, flags="SA", seq=7,
                              ack=seq + 1))
        hello = build_client_hello(site)
        self._emit(base / self.L.TCP(sport=sp, dport=443, flags="PA", seq=seq + 1) /
                   self.L.Raw(hello))
        sent = 0
        s2 = 8
        while sent < size and not self.stop_flag:
            chunk = min(1400, size - sent)
            self._emit(back / self.L.TCP(sport=443, dport=sp, flags="A", seq=s2) /
                       self.L.Raw(tls_app_record(chunk)))
            s2 += chunk
            sent += chunk
        self._emit(base / self.L.TCP(sport=sp, dport=443, flags="FA",
                              seq=seq + 1 + len(hello)))
        self._emit(back / self.L.TCP(sport=443, dport=sp, flags="FA", seq=s2))

    def run(self):
        try:
            self._run()
        except Exception:                            # noqa: BLE001
            LOG.exception("demo generator")

    def _run(self):
        gw, me = self.GW, self.ME
        for dev in [me] + self.DEVICES:
            self._emit(self.L.Ether(src=dev[1], dst="ff:ff:ff:ff:ff:ff") /
                       self.L.ARP(op=1, psrc=dev[0], pdst=gw[0], hwsrc=dev[1]))
            self._emit(self.L.Ether(src=gw[1], dst=dev[1]) /
                       self.L.ARP(op=2, psrc=gw[0], hwsrc=gw[1], pdst=dev[0],
                           hwdst=dev[1]))
            self._emit(self.L.Ether(src=dev[1], dst=gw[1]) /
                       self.L.ARP(op=2, psrc=dev[0], hwsrc=dev[1], pdst=gw[0],
                           hwdst=gw[1]))
        for ip, mac, host, vc, md in self.DEVICES:
            self._dhcp(ip, mac, host, vc)
            if md:
                self._mdns(ip, mac, *md)
        self._emit(self.L.Ether(src=gw[1], dst="33:33:00:00:00:01") /
                   self.L.IPv6(src="fe80::1", dst="ff02::1") / self.L.ICMPv6ND_RA() /
                   self.L.ICMPv6NDOptSrcLLAddr(lladdr=gw[1]))
        tv = self.DEVICES[1]
        self._emit(self.L.Ether(src=tv[1], dst="01:00:5e:7f:ff:fa") /
                   self.L.IP(src=tv[0], dst="239.255.255.250") /
                   self.L.UDP(sport=1900, dport=1900) /
                   self.L.Raw(b"NOTIFY * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\n"
                       b"NT: urn:dial-multiscreen-org:service:dial:1\r\n"
                       b"SERVER: Linux/4.9 UPnP/1.0 Chromecast/1.56\r\n\r\n"))
        tick = 0
        late_done = ftp_done = ssh_done = False
        while not self.stop_flag:
            tick += 1
            people = [me, self.DEVICES[0], self.DEVICES[1]]
            dev = random.choice(people)
            site, sip = random.choice(self.SITES)
            big = dev is self.DEVICES[1] and site.startswith("video")
            self._visit(dev, site, sip, size=random.choice(
                (8000, 20000, 60000)) * (8 if big else 1))
            if tick % 4 == 0:
                plug = self.DEVICES[3]
                self._emit(self.L.Ether(src=plug[1], dst=gw[1]) /
                           self.L.IP(src=plug[0], dst="129.6.15.28") /
                           self.L.UDP(sport=12345, dport=123) / self.L.Raw(b"\x1b" +
                                                              b"\x00" * 47))
            if tick % 6 == 0:
                for dv in self.DEVICES:
                    self._emit(self.L.Ether(src=dv[1], dst=me[1]) /
                               self.L.ARP(op=2, psrc=dv[0], hwsrc=dv[1],
                                   pdst=me[0], hwdst=me[1]))
            elapsed = time.time() - self.t0
            if elapsed > 45 and not late_done:
                late_done = True
                ip, mac, host, vc = self.LATE
                self._dhcp(ip, mac, host, vc)
                self._visit((ip, mac), "www.example.com", "93.184.215.14")
            if elapsed > 25 and not ftp_done:
                ftp_done = True
                pr = self.DEVICES[2]
                b = self.L.Ether(src=pr[1], dst=gw[1]) / self.L.IP(src=pr[0],
                                                     dst="34.117.59.81")
                self._emit(b / self.L.TCP(sport=40500, dport=21, flags="S"))
                self._emit(self.L.Ether(src=gw[1], dst=pr[1]) /
                           self.L.IP(src="34.117.59.81", dst=pr[0]) /
                           self.L.TCP(sport=21, dport=40500, flags="SA"))
                self._emit(b / self.L.TCP(sport=40500, dport=21, flags="PA") /
                           self.L.Raw(b"USER scanner\r\n"))
            if elapsed > 35 and not ssh_done:
                ssh_done = True
                ph = self.DEVICES[0]
                self._emit(self.L.Ether(src=ph[1], dst=me[1]) /
                           self.L.IP(src=ph[0], dst=me[0]) /
                           self.L.TCP(sport=50022, dport=22, flags="S"))
                self._emit(self.L.Ether(src=me[1], dst=ph[1]) /
                           self.L.IP(src=me[0], dst=ph[0]) /
                           self.L.TCP(sport=22, dport=50022, flags="SA"))
                self._emit(self.L.Ether(src=me[1], dst=ph[1]) /
                           self.L.IP(src=me[0], dst=ph[0]) /
                           self.L.TCP(sport=22, dport=50022, flags="PA") /
                           self.L.Raw(b"SSH-2.0-OpenSSH_9.6\r\n"))
            for _ in range(int(random.uniform(8, 20))):
                if self.stop_flag:
                    return
                time.sleep(0.1)


# ============================================================================
#  20a.  Replay scenarios — deterministic synthetic captures
#
#  A scripted home network built from ordinary packets (raw bytes plus a
#  timestamp). The same frames drive the self-tests, the fuzzer, the GUI
#  test, the benchmarks and the "golden" checks, so a behaviour change in
#  the decoder or the model shows up as a failing check within seconds.
#  All public addresses are real-looking but every domain is a reserved
#  ".example" name. Nothing is ever transmitted.
# ============================================================================
SCENARIO_T0 = 1_760_000_000.0


class ScenarioBuilder:
    """Builds lists of (raw_bytes, timestamp, linktype) frames with
    MiniWireshark's own packet builder (PK), so scenarios, the fuzzer and
    the benchmarks run without scapy. `layers` swaps in another builder
    with the same names (the self-test compares against scapy's)."""

    L = PK

    GW = ("192.168.1.1", "00:1e:58:aa:00:01")
    ME = ("192.168.1.10", "3c:7c:3f:10:00:10")
    PHONE = ("192.168.1.23", "da:a1:19:23:45:67", "Alex-iPhone")
    TV = ("192.168.1.40", "f4:f5:d8:40:00:40", "Living Room TV")
    PRINTER = ("192.168.1.50", "00:80:77:50:00:50", "BRW008077500050")
    PLUG = ("192.168.1.60", "24:0a:c4:60:00:60", "ESP_6A1B2C")
    NAS = ("192.168.1.70", "00:11:32:70:00:70", "family-nas")
    LAPTOP = ("192.168.1.50", "3c:22:fb:88:00:88", "DESKTOP-GUEST7Q")
    V6_PREFIX = "2a01:e0a:1f:2c0"
    SITES = {"www.example.com": "93.184.215.14",
             "video.example.net": "142.250.80.46",
             "tracker.example.net": "151.101.1.1",
             "plain.example.org": "34.117.59.81",
             "files.example.org": "34.117.59.81"}

    def __init__(self, t0=SCENARIO_T0, seed=7, layers=None):
        if layers is not None:
            self.L = layers
        self.t = t0
        self.frames = []
        self.rng = random.Random(seed)
        self.port = 40000
        self.qid = 100

    # ---- low level -----------------------------------------------------------
    def _emit(self, pkt, dt=0.01):
        self.t += dt
        self.frames.append((bytes(pkt), round(self.t, 6), 1))

    def _next_port(self):
        self.port += 1
        return self.port

    def arp_announce(self, host):
        ip, mac = host[0], host[1]
        self._emit(self.L.Ether(src=mac, dst="ff:ff:ff:ff:ff:ff") /
                   self.L.ARP(op=1, psrc=ip, pdst=self.GW[0], hwsrc=mac))
        self._emit(self.L.Ether(src=self.GW[1], dst=mac) /
                   self.L.ARP(op=2, psrc=self.GW[0], hwsrc=self.GW[1], pdst=ip,
                       hwdst=mac))
        self._emit(self.L.Ether(src=mac, dst=self.GW[1]) /
                   self.L.ARP(op=2, psrc=ip, hwsrc=mac, pdst=self.GW[0],
                       hwdst=self.GW[1]))

    def dhcp(self, host, vendor_class="", client_id=True, lease=86400):
        ip, mac, name = host[0], host[1], host[2]
        chaddr = bytes.fromhex(mac.replace(":", "")) + b"\x00" * 10
        opts = [("message-type", "request"), ("requested_addr", ip)]
        if client_id:
            opts.append(("client_id", b"\x01" + bytes.fromhex(
                mac.replace(":", ""))))
        if name:
            opts.append(("hostname", name.encode()))
        if vendor_class:
            opts.append(("vendor_class_id", vendor_class.encode()))
        opts.append(("param_req_list", [1, 3, 6, 15, 119, 252]))
        self._emit(self.L.Ether(src=mac, dst="ff:ff:ff:ff:ff:ff") /
                   self.L.IP(src="0.0.0.0", dst="255.255.255.255") /
                   self.L.UDP(sport=68, dport=67) /
                   self.L.BOOTP(chaddr=chaddr, xid=self.rng.randint(1, 2 ** 31)) /
                   self.L.DHCP(options=opts + ["end"]))
        self._emit(self.L.Ether(src=self.GW[1], dst=mac) /
                   self.L.IP(src=self.GW[0], dst=ip) / self.L.UDP(sport=67, dport=68) /
                   self.L.BOOTP(op=2, yiaddr=ip, chaddr=chaddr) /
                   self.L.DHCP(options=[("message-type", "ack"),
                                 ("server_id", self.GW[0]),
                                 ("lease_time", lease),
                                 ("router", self.GW[0]),
                                 ("name_server", self.GW[0]), "end"]))

    def mdns(self, host, svc, name, txt):
        ip, mac = host[0], host[1]
        txtv = [f"{k}={v}".encode() for k, v in txt.items()]
        self._emit(self.L.Ether(src=mac, dst="01:00:5e:00:00:fb") /
                   self.L.IP(src=ip, dst="224.0.0.251", ttl=255) /
                   self.L.UDP(sport=5353, dport=5353) /
                   self.L.DNS(qr=1, aa=1, qd=None,
                       an=self.L.DNSRR(rrname=f"{svc}.local", type="PTR",
                                rdata=f"{name}.{svc}.local"),
                       ar=[self.L.DNSRR(rrname=f"{name}.{svc}.local", type="TXT",
                                 rdata=txtv),
                           self.L.DNSRR(rrname=f"{name.replace(' ', '-')}.local",
                                 rdata=ip)]))

    def dns(self, host, name, answer_ip, rcode=0):
        ip, mac = host[0], host[1]
        sp = self._next_port()
        self.qid += 1
        self._emit(self.L.Ether(src=mac, dst=self.GW[1]) /
                   self.L.IP(src=ip, dst=self.GW[0]) / self.L.UDP(sport=sp, dport=53) /
                   self.L.DNS(id=self.qid, rd=1, qd=self.L.DNSQR(qname=name)))
        an = self.L.DNSRR(rrname=name, rdata=answer_ip, ttl=300) if answer_ip \
            else None
        self._emit(self.L.Ether(src=self.GW[1], dst=mac) /
                   self.L.IP(src=self.GW[0], dst=ip) / self.L.UDP(sport=53, dport=sp) /
                   self.L.DNS(id=self.qid, qr=1, rcode=rcode,
                       qd=self.L.DNSQR(qname=name), an=an), dt=0.02)

    def tls(self, host, site, rip, size=30000, sni=True, rst=False,
            port=443):
        ip, mac = host[0], host[1]
        sp = self._next_port()
        seq = self.rng.randint(1000, 10 ** 9)
        out = self.L.Ether(src=mac, dst=self.GW[1]) / self.L.IP(src=ip, dst=rip)
        back = self.L.Ether(src=self.GW[1], dst=mac) / self.L.IP(src=rip, dst=ip, ttl=54)
        self._emit(out / self.L.TCP(sport=sp, dport=port, flags="S", seq=seq))
        self._emit(back / self.L.TCP(sport=port, dport=sp, flags="SA", seq=7,
                              ack=seq + 1), dt=0.03)
        hello = build_client_hello(site if sni else "", pad=300, rnd=bytes(
            self.rng.getrandbits(8) for _ in range(32))) if sni \
            else b"\x16\x03\x01\x00\x05\x01\x00\x00\x01\x00"
        self._emit(out / self.L.TCP(sport=sp, dport=port, flags="PA", seq=seq + 1) /
                   self.L.Raw(hello))
        s2, sent = 8, 0
        while sent < size:
            chunk = min(1400, size - sent)
            self._emit(back / self.L.TCP(sport=port, dport=sp, flags="A", seq=s2) /
                       self.L.Raw(tls_app_record(chunk)), dt=0.002)
            s2 += chunk
            sent += chunk
        if rst:
            self._emit(back / self.L.TCP(sport=port, dport=sp, flags="R", seq=s2))
            return
        self._emit(out / self.L.TCP(sport=sp, dport=port, flags="FA",
                             seq=seq + 1 + len(hello)))
        self._emit(back / self.L.TCP(sport=port, dport=sp, flags="FA", seq=s2))

    def http(self, host, site, rip):
        ip, mac = host[0], host[1]
        sp = self._next_port()
        out = self.L.Ether(src=mac, dst=self.GW[1]) / self.L.IP(src=ip, dst=rip)
        back = self.L.Ether(src=self.GW[1], dst=mac) / self.L.IP(src=rip, dst=ip, ttl=54)
        self._emit(out / self.L.TCP(sport=sp, dport=80, flags="S", seq=1))
        self._emit(back / self.L.TCP(sport=80, dport=sp, flags="SA", seq=1, ack=2))
        self._emit(out / self.L.TCP(sport=sp, dport=80, flags="PA", seq=2) /
                   self.L.Raw(f"GET /index.html HTTP/1.1\r\nHost: {site}\r\n"
                       f"User-Agent: test\r\n\r\n".encode()))
        self._emit(back / self.L.TCP(sport=80, dport=sp, flags="PA", seq=2) /
                   self.L.Raw(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok"))

    # ---- the scripted home network ---------------------------------------------
    def home_network(self):
        gw, me = self.GW, self.ME
        hosts = [me, self.PHONE, self.TV, self.PRINTER, self.PLUG, self.NAS]
        for h in hosts:
            self.arp_announce(h)
        self.dhcp(self.PHONE, client_id=True)
        self.dhcp(self.TV)
        self.dhcp(self.PRINTER)
        self.dhcp(self.PLUG, vendor_class="udhcp 1.30")
        self.dhcp(self.NAS)
        # IPv6: router advertisement with a global prefix, then the phone's
        # global address is resolved by neighbour discovery
        self._emit(self.L.Ether(src=gw[1], dst="33:33:00:00:00:01") /
                   self.L.IPv6(src="fe80::21e:58ff:feaa:1", dst="ff02::1") /
                   self.L.ICMPv6ND_RA(routerlifetime=1800) /
                   self.L.ICMPv6NDOptPrefixInfo(prefix=self.V6_PREFIX + "::",
                                         prefixlen=64) /
                   self.L.ICMPv6NDOptSrcLLAddr(lladdr=gw[1]))
        p6 = self.V6_PREFIX + "::23"
        self._emit(self.L.Ether(src=self.PHONE[1], dst=gw[1]) /
                   self.L.IPv6(src=p6, dst="fe80::21e:58ff:feaa:1") /
                   self.L.ICMPv6ND_NA(tgt=p6, R=0, S=1, O=1) /
                   self.L.ICMPv6NDOptDstLLAddr(lladdr=self.PHONE[1]))
        self.mdns(self.TV, "_googlecast._tcp", "Living Room TV",
                  {"md": "Chromecast", "fn": "Living Room TV"})
        self.mdns(self.PRINTER, "_ipp._tcp", "Brother HL-L2350DW",
                  {"ty": "Brother HL-L2350DW"})
        self.mdns(self.NAS, "_smb._tcp", "family-nas", {"model": "DS220+"})
        self._emit(self.L.Ether(src=self.TV[1], dst="01:00:5e:7f:ff:fa") /
                   self.L.IP(src=self.TV[0], dst="239.255.255.250") /
                   self.L.UDP(sport=1900, dport=1900) /
                   self.L.Raw(b"NOTIFY * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\n"
                       b"NT: urn:dial-multiscreen-org:service:dial:1\r\n"
                       b"SERVER: Linux/4.9 UPnP/1.0 Chromecast/1.56\r\n\r\n"))
        # browsing: lookup → connection with SNI
        s = self.SITES
        self.dns(me, "www.example.com", s["www.example.com"])
        self.tls(me, "www.example.com", s["www.example.com"], size=40000)
        # a lookup with no connection afterwards
        self.dns(self.PHONE, "tracker.example.net", s["tracker.example.net"])
        self.dns(self.PHONE, "video.example.net", s["video.example.net"])
        self.tls(self.PHONE, "video.example.net", s["video.example.net"],
                 size=120000)
        # a connection that only the earlier lookup can name (no SNI)
        self.dns(self.TV, "files.example.org", s["files.example.org"])
        self.tls(self.TV, "", s["files.example.org"], sni=False, size=6000)
        # plain web and cleartext
        self.http(me, "plain.example.org", s["plain.example.org"])
        pr = self.PRINTER
        out = self.L.Ether(src=pr[1], dst=gw[1]) / self.L.IP(src=pr[0], dst="34.117.59.81")
        self._emit(out / self.L.TCP(sport=40500, dport=21, flags="S"))
        self._emit(self.L.Ether(src=gw[1], dst=pr[1]) /
                   self.L.IP(src="34.117.59.81", dst=pr[0]) /
                   self.L.TCP(sport=21, dport=40500, flags="SA"))
        self._emit(out / self.L.TCP(sport=40500, dport=21, flags="PA") /
                   self.L.Raw(b"USER scanner\r\n"))
        # NTP from the smart plug
        self._emit(self.L.Ether(src=self.PLUG[1], dst=gw[1]) /
                   self.L.IP(src=self.PLUG[0], dst="129.6.15.28") /
                   self.L.UDP(sport=12345, dport=123) / self.L.Raw(b"\x1b" + bytes(47)))
        self._emit(self.L.Ether(src=gw[1], dst=self.PLUG[1]) /
                   self.L.IP(src="129.6.15.28", dst=self.PLUG[0], ttl=50) /
                   self.L.UDP(sport=123, dport=12345) / self.L.Raw(b"\x1c" + bytes(47)))
        # QUIC (long header) and encrypted DNS to a known DoH host
        self._emit(self.L.Ether(src=me[1], dst=gw[1]) /
                   self.L.IP(src=me[0], dst="142.250.80.46") /
                   self.L.UDP(sport=51000, dport=443) / self.L.Raw(b"\xc3" + bytes(1250)))
        self.tls(me, "dns.google", "8.8.8.8", size=3000)
        # local name protocols
        self._emit(self.L.Ether(src=me[1], dst="01:00:5e:00:00:fc") /
                   self.L.IP(src=me[0], dst="224.0.0.252") /
                   self.L.UDP(sport=55000, dport=5355) /
                   self.L.DNS(id=9, qd=self.L.DNSQR(qname="nas")))
        nb = (b"\x81\x02\x85\x00\x00\x00\x00\x01\x00\x00\x00\x00\x20" +
              b"".join(bytes([0x41 + (c >> 4), 0x41 + (c & 15)])
                       for c in b"FAMILY-NAS      ") + b"\x00")
        self._emit(self.L.Ether(src=self.NAS[1], dst=me[1]) /
                   self.L.IP(src=self.NAS[0], dst=me[0]) /
                   self.L.UDP(sport=137, dport=137) / self.L.Raw(nb))
        # a reset connection and an SSH session on the LAN
        self.tls(me, "www.example.com", s["www.example.com"], size=1400,
                 rst=True)
        ph = self.PHONE
        self._emit(self.L.Ether(src=ph[1], dst=me[1]) / self.L.IP(src=ph[0], dst=me[0]) /
                   self.L.TCP(sport=50022, dport=22, flags="S"))
        self._emit(self.L.Ether(src=me[1], dst=ph[1]) / self.L.IP(src=me[0], dst=ph[0]) /
                   self.L.TCP(sport=22, dport=50022, flags="SA"))
        self._emit(self.L.Ether(src=me[1], dst=ph[1]) / self.L.IP(src=me[0], dst=ph[0]) /
                   self.L.TCP(sport=22, dport=50022, flags="PA") /
                   self.L.Raw(b"SSH-2.0-OpenSSH_9.6\r\n"))
        # later: the printer is gone and its address is reused by a laptop
        self.t += 900
        self.dhcp(self.LAPTOP, vendor_class="MSFT 5.0")
        self.arp_announce(self.LAPTOP)
        self.tls(self.LAPTOP, "www.example.com", s["www.example.com"],
                 size=9000)
        return self.frames

    def protocol_tour(self):
        """Frames that exercise every field the dissectors declare but the
        home network never sends: VLAN tags, IP options, ping, TCP
        options, IPv6 extension headers, CNAME/AAAA/SRV answers and a
        Linux "cooked" capture frame."""
        self.vlan_ping()
        L = self.L
        me = self.ME
        self._emit(L.Ether(src=me[1], dst="01:00:5e:00:00:16") /
                   L.IP(src=me[0], dst="224.0.0.22", ttl=1,
                        options=b"\x94\x04\x00\x00") /
                   L.UDP(sport=50001, dport=50002) / L.Raw(b"opt"))
        return self._tour_rest()

    def vlan_ping(self):
        L, me, gw = self.L, self.ME, self.GW
        self._emit(L.Ether(src=me[1], dst=gw[1]) / L.Dot1Q(vlan=20, prio=3) /
                   L.IP(src=me[0], dst="1.1.1.1") /
                   L.ICMP(type=8, id=7, seq=1) / L.Raw(b"ping" * 8))
        self._emit(L.Ether(src=gw[1], dst=me[1]) / L.Dot1Q(vlan=20, prio=3) /
                   L.IP(src="1.1.1.1", dst=me[0], ttl=57) /
                   L.ICMP(type=0, id=7, seq=1) / L.Raw(b"ping" * 8))
        return self.frames

    def _tour_rest(self):
        L = self.L
        me, gw, nas = self.ME, self.GW, self.NAS
        sp = self._next_port()
        syn_opts = (b"\x02\x04\x05\xb4\x04\x02\x08\x0a" +
                    struct.pack("!II", 123456, 0) + b"\x01\x03\x03\x07")
        out = L.Ether(src=me[1], dst=nas[1]) / L.IP(src=me[0], dst=nas[0])
        back = L.Ether(src=nas[1], dst=me[1]) / L.IP(src=nas[0], dst=me[0])
        self._emit(out / L.TCP(sport=sp, dport=445, flags="S", seq=100,
                               window=64240, options=syn_opts))
        self._emit(back / L.TCP(sport=445, dport=sp, flags="SA", seq=900,
                                ack=101, window=65160, options=syn_opts))
        self._emit(out / L.TCP(sport=sp, dport=445, flags="A", seq=101,
                               ack=901, options=b"\x01\x01\x05\x0a" +
                               struct.pack("!II", 2000, 3000)))
        name = "media.example.com"
        rrs = [L.DNSRR(rrname=name, type="CNAME", rdata="cdn.example.net",
                       ttl=60),
               L.DNSRR(rrname="cdn.example.net", type="AAAA",
                       rdata=self.V6_PREFIX + "::80", ttl=60)]
        srv = L.DNSRR(rrname="_sip._tcp.example.com", type=33, ttl=300,
                      rdata=struct.pack("!HHH", 10, 5, 5060) +
                      b"\x03sip\x07example\x03com\x00")
        self._emit(L.Ether(src=gw[1], dst=me[1]) / L.IP(src=gw[0], dst=me[0])
                   / L.UDP(sport=53, dport=self._next_port()) /
                   L.DNS(id=77, qr=1, ra=1, qd=L.DNSQR(qname=name,
                                                       qtype="AAAA"),
                         an=rrs, ar=srv))
        src6, dst6 = self.V6_PREFIX + "::10", "2001:db8::53"
        udp = bytes(L.IPv6(src=src6, dst=dst6) /
                    L.UDP(sport=53000, dport=53) /
                    L.DNS(id=78, qd=L.DNSQR(qname="example.com",
                                            qtype="AAAA")))[40:]
        hbh = bytes([44, 0, 1, 4, 0, 0, 0, 0])          # → fragment hdr
        frag = bytes([17, 0, 0, 0]) + struct.pack("!I", 0x1234)
        self._emit(L.Ether(src=me[1], dst=gw[1]) /
                   L.IPv6(src=src6, dst=dst6, nh=0) /
                   L.Raw(hbh + frag + udp))
        sll = struct.pack("!HHH", 0, 1, 6) + _pk_mac(me[1]) + b"\x00\x00" + \
            struct.pack("!H", 0x0800)
        ip = bytes(L.IP(src=me[0], dst=gw[0]) / L.UDP(sport=53001, dport=53)
                   / L.DNS(id=79, qd=L.DNSQR(qname="example.org")))
        self.t += 0.01
        self.frames.append((sll + ip, round(self.t, 6), 113))
        return self.frames

    def _tcp_talk(self, client, server_ip, server_mac, sport, dport, turns,
                  dt=0.004):
        """A TCP conversation: handshake, then (direction, bytes) turns,
        then FIN both ways. Direction 0 = client speaks."""
        L = self.L
        cip, cmac = client[0], client[1]
        out = L.Ether(src=cmac, dst=server_mac) / L.IP(src=cip, dst=server_ip)
        back = L.Ether(src=server_mac, dst=cmac) / L.IP(src=server_ip,
                                                         dst=cip, ttl=58)
        c, s = 1000, 5000
        self._emit(out / L.TCP(sport=sport, dport=dport, flags="S", seq=c),
                   dt)
        self._emit(back / L.TCP(sport=dport, dport=sport, flags="SA", seq=s,
                                ack=c + 1), dt)
        c, s = c + 1, s + 1
        for direction, data in turns:
            if direction == 0:
                self._emit(out / L.TCP(sport=sport, dport=dport, flags="PA",
                                       seq=c, ack=s) / L.Raw(data), dt)
                c += len(data)
            else:
                self._emit(back / L.TCP(sport=dport, dport=sport, flags="PA",
                                        seq=s, ack=c) / L.Raw(data), dt)
                s += len(data)
        self._emit(out / L.TCP(sport=sport, dport=dport, flags="FA", seq=c,
                               ack=s), dt)
        self._emit(back / L.TCP(sport=dport, dport=sport, flags="FA", seq=s,
                                ack=c + 1), dt)

    def protocol_exchanges(self):
        """Request/response pairs for every protocol M5 follows."""
        L = self.L
        me, gw, nas, tv = self.ME, self.GW, self.NAS, self.TV
        up = L.Ether(src=me[1], dst=gw[1]) / L.IP(src=me[0], dst=gw[0])
        down = L.Ether(src=gw[1], dst=me[1]) / L.IP(src=gw[0], dst=me[0])
        # DNS: answered, retried then answered, never answered, NXDOMAIN
        self._emit(up / L.UDP(sport=50100, dport=53) /
                   L.DNS(id=11, qd=L.DNSQR(qname="a.example.com")))
        self._emit(down / L.UDP(sport=53, dport=50100) /
                   L.DNS(id=11, qr=1, ra=1, qd=L.DNSQR(qname="a.example.com"),
                         an=L.DNSRR(rrname="a.example.com",
                                    rdata="93.184.215.14", ttl=60)),
                   dt=0.025)
        self._emit(up / L.UDP(sport=50101, dport=53) /
                   L.DNS(id=12, qd=L.DNSQR(qname="slow.example.com")))
        self._emit(up / L.UDP(sport=50102, dport=53) /
                   L.DNS(id=13, qd=L.DNSQR(qname="slow.example.com")),
                   dt=1.0)
        self._emit(down / L.UDP(sport=53, dport=50102) /
                   L.DNS(id=13, qr=1, qd=L.DNSQR(qname="slow.example.com"),
                         an=L.DNSRR(rrname="slow.example.com",
                                    rdata="93.184.215.15", ttl=60)),
                   dt=0.2)
        self._emit(up / L.UDP(sport=50103, dport=53) /
                   L.DNS(id=14, qd=L.DNSQR(qname="lost.example.com")))
        self._emit(up / L.UDP(sport=50104, dport=53) /
                   L.DNS(id=15, qd=L.DNSQR(qname="nope.example.com")))
        self._emit(down / L.UDP(sport=53, dport=50104) /
                   L.DNS(id=15, qr=1, rcode=3,
                         qd=L.DNSQR(qname="nope.example.com")), dt=0.03)
        # DHCP: full four-step exchange, plus an offer from a second server
        mac = tv[1]
        ch = bytes.fromhex(mac.replace(":", ""))
        bc = L.Ether(src=mac, dst="ff:ff:ff:ff:ff:ff") / \
            L.IP(src="0.0.0.0", dst="255.255.255.255") / L.UDP(sport=68,
                                                               dport=67)
        for mt, extra in (("discover", []), ("request",
                                             [("requested_addr", tv[0])])):
            self._emit(bc / L.BOOTP(chaddr=ch, xid=4242) /
                       L.DHCP(options=[("message-type", mt),
                                       ("hostname", b"Living-Room-TV")] +
                              extra + ["end"]), dt=0.01)
            reply = "offer" if mt == "discover" else "ack"
            self._emit(L.Ether(src=gw[1], dst=mac) /
                       L.IP(src=gw[0], dst=tv[0]) / L.UDP(sport=67, dport=68)
                       / L.BOOTP(op=2, yiaddr=tv[0], chaddr=ch, xid=4242) /
                       L.DHCP(options=[("message-type", reply),
                                       ("server_id", gw[0]),
                                       ("lease_time", 7200), "end"]),
                       dt=0.012)
        self._emit(L.Ether(src="02:00:00:00:66:66", dst=mac) /
                   L.IP(src="192.168.1.66", dst=tv[0]) /
                   L.UDP(sport=67, dport=68) /
                   L.BOOTP(op=2, yiaddr="192.168.1.199", chaddr=ch, xid=999) /
                   L.DHCP(options=[("message-type", "offer"),
                                   ("server_id", "192.168.1.66"), "end"]))
        # TLS: hello and server hello on one connection
        sh_body = (b"\x03\x03" + bytes(32) + b"\x00" + b"\x13\x01" + b"\x00" +
                   struct.pack("!H", 6) + struct.pack("!HHH", 43, 2, 0x0304))
        server_hello = b"\x16\x03\x03" + struct.pack(
            "!H", len(sh_body) + 4) + b"\x02" + struct.pack(
            "!I", len(sh_body))[1:] + sh_body
        self._tcp_talk(me, "93.184.215.14", gw[1], 41443, 443, [
            (0, build_client_hello("www.example.com", rnd=bytes(32))),
            (1, server_hello)])
        # HTTP: two requests, two answers (one partial-free), RTSP, SSH
        self._tcp_talk(me, "34.117.59.81", gw[1], 41080, 80, [
            (0, b"GET /index.html?session=SECRET HTTP/1.1\r\n"
                b"Host: plain.example.org\r\nCookie: id=SECRET\r\n\r\n"),
            (1, b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello"),
            (0, b"GET /missing HTTP/1.1\r\nHost: plain.example.org\r\n\r\n"),
            (1, b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n")])
        self._tcp_talk(me, tv[0], tv[1], 41554, 554, [
            (0, b"OPTIONS rtsp://tv/ RTSP/1.0\r\nCSeq: 1\r\n\r\n"),
            (1, b"RTSP/1.0 200 OK\r\nCSeq: 1\r\n\r\n")])
        self._tcp_talk(me, nas[0], nas[1], 41022, 22, [
            (0, b"SSH-2.0-OpenSSH_9.6\r\n"),
            (1, b"SSH-2.0-dropbear_2022.83\r\n")])
        # SMB2 negotiate (dialect 3.1.1) and an SMB1 negotiate
        hdr = b"\xfeSMB" + struct.pack("<HHIHHI", 64, 0, 0, 0, 0, 1) + \
            bytes(64 - 20)
        body = struct.pack("<HHH", 65, 0, 0x0311) + bytes(58)
        smb2 = hdr + body
        smb1 = b"\xffSMB" + bytes(60)
        nb = lambda b: b"\x00" + struct.pack("!I", len(b))[1:] + b
        self._tcp_talk(me, nas[0], nas[1], 41445, 445, [
            (0, nb(b"\xfeSMB" + bytes(60) + bytes(8))), (1, nb(smb2))])
        self._tcp_talk(me, "192.168.1.80", "02:00:00:00:00:80", 41446, 445,
                       [(0, nb(smb1)), (1, nb(smb1))])
        # MQTT: connect refused
        connect = b"\x10" + bytes([12]) + b"\x00\x04MQTT\x04\x02\x00\x3c" + \
            b"\x00\x00"
        self._tcp_talk(me, nas[0], nas[1], 41883, 1883, [
            (0, connect), (1, b"\x20\x02\x00\x05")])
        # NTP: client request and server reply (offset about +50 ms)
        t1 = self.t + 0.001
        frac = lambda t: struct.pack("!II", int(t) + 2208988800,
                                     int((t % 1) * 2 ** 32))
        req = bytes([0x23]) + bytes(39) + frac(t1)
        self._emit(up / L.UDP(sport=50123, dport=123) / L.Raw(req),
                   dt=0.001)
        rep = bytes([0x24, 2]) + bytes(22) + frac(t1) + frac(t1 + 0.06) + \
            frac(t1 + 0.0601)
        self._emit(down / L.UDP(sport=123, dport=50123) / L.Raw(rep),
                   dt=0.020)
        # SIP over UDP: INVITE and Busy Here
        self._emit(up / L.UDP(sport=5060, dport=5060) /
                   L.Raw(b"INVITE sip:bob@example.com SIP/2.0\r\n"
                         b"Content-Length: 0\r\n\r\n"))
        self._emit(down / L.UDP(sport=5060, dport=5060) /
                   L.Raw(b"SIP/2.0 486 Busy Here\r\nContent-Length: 0"
                         b"\r\n\r\n"), dt=0.05)
        return self.frames

    CANARY = "CANARY-7f3a"

    def mail_sessions(self):
        """Fictional mail sessions (SMTP, IMAP, POP3, implicit TLS,
        webmail) carrying the canary secret in every place a password, an
        address, a subject or a body could leak from."""
        me, srv_mac = self.ME, self.GW[1]
        c = self.CANARY.encode()
        b64 = base64.b64encode(b"\x00alex\x00" + c)
        smtp = "198.51.100.25"
        self._tcp_talk(me, smtp, srv_mac, 42025, 25, [
            (1, b"220 mx.example.net ESMTP ready\r\n"),
            (0, b"EHLO laptop\r\n"),
            (1, b"250-mx.example.net\r\n250-STARTTLS\r\n"
                b"250 AUTH PLAIN LOGIN\r\n"),
            (0, b"AUTH PLAIN " + b64 + b"\r\n"),
            (1, b"535 5.7.8 Authentication failed\r\n"),
            (0, b"AUTH LOGIN\r\n"), (1, b"334 VXNlcm5hbWU6\r\n"),
            (0, base64.b64encode(c) + b"\r\n"), (1, b"334 UGFzc3dvcmQ6\r\n"),
            (0, base64.b64encode(c) + b"\r\n"),
            (1, b"535 5.7.8 Authentication failed\r\n"),
            (0, b"AUTH PLAIN " + b64 + b"\r\n"),
            (1, b"535 5.7.8 Authentication failed\r\n"),
            (0, b"MAIL FROM:<" + c + b"@example.com>\r\n"),
            (1, b"250 OK\r\n"),
            (0, b"RCPT TO:<" + c + b"@example.org>\r\n"), (1, b"250 OK\r\n"),
            (0, b"RCPT TO:<bob@example.org>\r\n"), (1, b"250 OK\r\n"),
            (0, b"DATA\r\n"), (1, b"354 go ahead\r\n"),
            (0, b"Subject: " + c + b"\r\n\r\nHello " + c + b"\r\n.\r\n"),
            (1, b"250 queued\r\n"), (0, b"QUIT\r\n"), (1, b"221 bye\r\n")])
        self._tcp_talk(me, smtp, srv_mac, 42587, 587, [
            (1, b"220 smtp.example.net ESMTP\r\n"), (0, b"EHLO laptop\r\n"),
            (1, b"250-smtp.example.net\r\n250 STARTTLS\r\n"),
            (0, b"STARTTLS\r\n"), (1, b"220 go ahead\r\n"),
            (0, build_client_hello("smtp.example.net", rnd=bytes(32))),
            (1, tls_app_record(300)),
            (0, tls_app_record(120) + c)])
        imap = "198.51.100.143"
        self._tcp_talk(me, imap, srv_mac, 42143, 143, [
            (1, b"* OK [CAPABILITY IMAP4rev1 STARTTLS AUTH=PLAIN] ready\r\n"),
            (0, b"a1 LOGIN alex " + c + b"\r\n"),
            (1, b"a1 NO [AUTHENTICATIONFAILED] Invalid credentials\r\n"),
            (0, b"a2 LOGIN alex {11}\r\n"), (1, b"+ go\r\n"),
            (0, c + b"\r\n"), (1, b"a2 OK LOGIN completed\r\n"),
            (0, b"a3 SELECT INBOX\r\n"),
            (1, b"* 3 EXISTS\r\na3 OK [READ-WRITE] SELECT completed\r\n"),
            (0, b"a4 FETCH 1 (BODY[])\r\n"),
            (1, b"* 1 FETCH (BODY[] {28}\r\nSubject: " + c +
             b"\r\n\r\nhi\r\n)\r\na4 OK FETCH completed\r\n"),
            (0, b"a5 LOGOUT\r\n"), (1, b"* BYE\r\na5 OK LOGOUT\r\n")])
        pop = "198.51.100.110"
        self._tcp_talk(me, pop, srv_mac, 42110, 110, [
            (1, b"+OK POP3 server ready\r\n"), (0, b"USER alex\r\n"),
            (1, b"+OK\r\n"), (0, b"PASS " + c + b"\r\n"),
            (1, b"-ERR invalid password\r\n"), (0, b"USER alex\r\n"),
            (1, b"+OK\r\n"), (0, b"PASS " + c + b"x\r\n"),
            (1, b"+OK logged in\r\n"), (0, b"RETR 1\r\n"),
            (1, b"+OK 40 octets\r\nSubject: " + c + b"\r\n\r\nbody\r\n.\r\n"),
            (0, b"QUIT\r\n"), (1, b"+OK bye\r\n")])
        self._tcp_talk(me, "198.51.100.93", srv_mac, 42993, 993, [
            (0, build_client_hello("imap.example.net", rnd=bytes(32))),
            (1, tls_app_record(800)), (0, tls_app_record(200))])
        self._tcp_talk(me, "142.250.80.5", srv_mac, 42444, 443, [
            (0, build_client_hello("mail.google.com", rnd=bytes(32))),
            (1, tls_app_record(500))])
        self._tcp_talk(me, "203.0.113.7", srv_mac, 42526, 2526, [
            (1, b"220 relay.example.org ESMTP Postfix\r\n"),
            (0, b"EHLO laptop\r\n"), (1, b"250 relay.example.org\r\n"),
            (0, b"QUIT\r\n"), (1, b"221 bye\r\n")])
        return self.frames

    def bulk_streams(self, n=50000, flows=200, size=300):
        """Many long TLS downloads with correct sequence numbers (the deep
        pass benchmark: every segment is new data to reassemble)."""
        L = self.L
        out = []
        st = []
        for i in range(flows):
            mac = f"00:16:3e:01:{i // 256:02x}:{i % 256:02x}"
            ip = f"192.168.1.{100 + i % 120}"
            rip = f"34.{i % 250}.{i % 7}.{(i * 13) % 251 + 1}"
            st.append([mac, ip, rip, 41000 + i, 1000, 9000])
        t = self.t
        for k in range(n):
            f = st[k % flows]
            mac, ip, rip, sp, cseq, sseq = f
            t += 0.00002
            if k < flows:
                p = L.Ether(src=mac, dst=self.GW[1]) / L.IP(src=ip, dst=rip) \
                    / L.TCP(sport=sp, dport=443, flags="S", seq=cseq)
                f[4] += 1
            else:
                rec = tls_app_record(size)
                p = L.Ether(src=self.GW[1], dst=mac) / \
                    L.IP(src=rip, dst=ip, ttl=55) / \
                    L.TCP(sport=443, dport=sp, flags="A", seq=sseq,
                          ack=cseq) / L.Raw(rec)
                f[5] += len(rec)
            out.append((bytes(p), round(t, 6), 1))
        return out

    def busy_mix(self, n=20000, seed=3):
        """Many short flows from many devices (benchmarks)."""
        rng = random.Random(seed)
        frames = []
        t = self.t
        tmpl = []
        for i in range(64):
            mac = f"00:16:3e:00:{i // 256:02x}:{i % 256:02x}"
            ip = f"192.168.1.{100 + i % 120}"
            rip = f"34.{i}.{i % 7}.{(i * 13) % 251 + 1}"
            tmpl.append(bytes(self.L.Ether(src=mac, dst=self.GW[1]) /
                              self.L.IP(src=ip, dst=rip) /
                              self.L.TCP(sport=40000 + i, dport=443, flags="PA") /
                              self.L.Raw(tls_app_record(3 + rng.choice(
                                  (60, 300, 1200))))))
            tmpl.append(bytes(self.L.Ether(src=self.GW[1], dst=mac) /
                              self.L.IP(src=rip, dst=ip, ttl=55) /
                              self.L.TCP(sport=443, dport=40000 + i, flags="A") /
                              self.L.Raw(tls_app_record(1383))))
        for k in range(n):
            t += 0.00005
            frames.append((tmpl[k % len(tmpl)], round(t, 6), 1))
        return frames


def scenario_identity():
    """(gateway, my_ips, my_macs, local_nets) of the scripted network."""
    return (ScenarioBuilder.GW[0], {ScenarioBuilder.ME[0]},
            {ScenarioBuilder.ME[1]},
            [ipaddress.ip_network("192.168.1.0/24")])


def scenario_model(config, frames=None, decoder=None):
    """Replay frames through decoder + model exactly like an import."""
    gw, ips, macs, nets = scenario_identity()
    m = NetworkModel(config, gw, ips, macs)
    m.set_identity(local_nets=nets)
    m.use_packet_clock = True
    frames = frames if frames is not None else \
        ScenarioBuilder().home_network()
    replay_frames(m, frames, decoder=decoder)
    return m


def replay_frames(model, frames, decoder=None, tick_every=500):
    dec = decoder or default_frame_decoder(model)
    for i, (raw, ts, lt) in enumerate(frames):
        d = dec(raw, ts, lt)
        if d is None:
            continue
        model.count_frames = getattr(model, "count_frames", 0) + 1
        d["no"] = model.count_frames
        learn_names_from(model.cache, d)
        model.ingest(d)
        if tick_every and i % tick_every == tick_every - 1:
            model.tick()
    model.tick()
    model._announce_created(flush=True)
    return model


def fast_frame_decoder(model):
    """The capture path's own decoder (no scapy needed)."""
    reasm = TlsReassembler()

    def dec(raw, ts, lt=1):
        return fast_decode(raw, ts, lt, reasm, model.gateway_ip,
                           model.my_ips)
    return dec


def default_frame_decoder(model):
    """scapy's reference decoder when it is there, else the fast one."""
    if Ether is None:
        return fast_frame_decoder(model)
    reasm = TlsReassembler()

    def dec(raw, ts, lt=1):
        pkt = Ether(raw) if lt == 1 else Raw(raw)
        pkt.time = ts
        d = decode_packet(pkt, model.gateway_ip, model.my_ips, reasm)
        d["time"] = ts
        return d
    return dec


def golden_checks(model):
    """Semantic expectations for ScenarioBuilder.home_network(). Returns a
    list of human-readable failures (empty = all good)."""
    fails = []
    S = ScenarioBuilder
    reg = model.registry

    def dev_by_mac(mac):
        return reg.by_key.get(reg.resolve(mac)) if hasattr(reg, "resolve") \
            else reg.by_key.get(mac)

    def check(cond, msg):
        if not cond:
            fails.append(msg)

    for dv in reg.by_key.values():
        check(not (dv.ip and is_public_ip(dv.ip)),
              f"public address became a device: {dv.ip}")
        for a in dv.ipv4s:
            check(not is_public_ip(a), f"device {dv.key} holds public {a}")
    phone = dev_by_mac(S.PHONE[1])
    check(phone is not None, "phone not discovered")
    if phone is not None:
        check(phone.dhcp_hostname == "Alex-iPhone",
              f"phone hostname={phone.dhcp_hostname!r}")
        check(any(a.startswith(S.V6_PREFIX) for a in phone.ipv6),
              f"phone IPv6 missing: {sorted(phone.ipv6)}")
    tv = dev_by_mac(S.TV[1])
    check(tv is not None and tv.device_class in ("Smart TV",
                                                 "Streaming device"),
          f"tv class={getattr(tv, 'device_class', None)}")
    pr = dev_by_mac(S.PRINTER[1])
    check(pr is not None and pr.device_class == "Printer",
          f"printer class={getattr(pr, 'device_class', None)}")
    lap = dev_by_mac(S.LAPTOP[1])
    check(lap is not None and lap.device_class == "Windows PC",
          f"laptop class={getattr(lap, 'device_class', None)}")
    check(lap is not None and pr is not None and lap.key != pr.key,
          "printer and laptop merged (IP reuse)")
    gwd = dev_by_mac(S.GW[1])
    check(gwd is not None and gwd.device_class == "Router",
          f"router class={getattr(gwd, 'device_class', None)}")
    w = model.websites
    check("www.example.com" in w and "TLS SNI" in w["www.example.com"].sources,
          "www.example.com not seen via TLS SNI")
    check("tracker.example.net" in w and
          w["tracker.example.net"].connections == 0,
          "lookup-only domain counted as a connection")
    check("plain.example.org" in w and
          "HTTP Host" in w["plain.example.org"].sources,
          "HTTP Host not recorded")
    check("93.184.215.14" in model.remote_hosts, "remote host missing")
    check("93.184.215.14" not in reg.ip_to_key,
          "remote host address mapped to a device")
    kinds = {a.kind for a in model.alerts.alerts.values()}
    check("cleartext" in kinds, f"no cleartext alert (kinds={sorted(kinds)})")
    check(model.dns.encrypted_seen, "encrypted DNS not noticed")
    check(len(model.flows.all_flows()) >= 10,
          f"too few flows: {len(model.flows.all_flows())}")
    check(any(f.domain == "files.example.org"
              for f in model.flows.all_flows()),
          "connection not named from its lookup")
    for extra in GOLDEN_EXTRA:
        msg = extra(model)
        if msg:
            fails.append(msg)
    return fails


GOLDEN_EXTRA = []       # later milestones append (model) -> str|None checks


def _golden_ties(model):
    S = ScenarioBuilder
    w = model.websites
    want = [("www.example.com", S.ME[1], AS_CONNECTED),
            ("tracker.example.net", S.PHONE[1], AS_LOOKUP_ONLY),
            ("video.example.net", S.PHONE[1], AS_CONNECTED),
            ("files.example.org", S.TV[1], AS_CONNECTED_LOOKUP),
            ("www.example.com", S.LAPTOP[1], AS_CONNECTED)]
    bad = []
    for dom, dev, assoc in want:
        rec = w.get(dom)
        got = rec.ties.get(dev, [""])[0] if rec else "(no site)"
        if got != assoc:
            bad.append(f"{dom}/{dev}: {got!r} != {assoc!r}")
    f = [fl for fl in model.flows.all_flows()
         if fl.domain == "files.example.org"]
    if not f or f[0].assoc != AS_CONNECTED_LOOKUP:
        bad.append("TV flow not correlated with its lookup")
    if bad:
        return "site ties: " + "; ".join(bad)
    obs = model.observations_for(S.PHONE[1], kinds=("dhcp_ack",))
    if not obs or obs[-1][5] is None:
        return "phone DHCP lease has no packet-backed observation"
    if not model.observations_for("site:www.example.com"):
        return "no observations for www.example.com"
    return None


GOLDEN_EXTRA.append(_golden_ties)


# ============================================================================
#  20b.  Self-tests  —  python miniwireshark.py --self-test
#
#  No administrator rights and no packet capture needed. Packet-based tests
#  build synthetic packets with scapy and are skipped if it's missing.
# ============================================================================
class _FakeClock:
    def __init__(self, t=1_700_000_000.0):
        self.t = t

    def __call__(self):
        return self.t


def run_self_tests(verbose=True):
    results = []
    tmp = tempfile.mkdtemp(prefix="mw_selftest_")

    def cfg(extra=None):
        c = AppConfig(path=os.path.join(tmp, f"cfg_{uuid.uuid4().hex}.json"))
        for k, v in (extra or {}).items():
            c.set(k, v)
        return c

    def test(fn):
        name = fn.__name__[2:].replace("_", " ")
        t0 = time.perf_counter()
        try:
            r = fn()
            status = "SKIP" if r == "skip" else "PASS"
            msg = "" if status == "PASS" else "not available here"
        except Exception as e:                       # noqa: BLE001
            status, msg = "FAIL", f"{type(e).__name__}: {e}\n" + \
                traceback.format_exc(limit=12)
        results.append((status, name, msg, time.perf_counter() - t0))
        if verbose:
            print(f"  [{status}] {name} ({(time.perf_counter() - t0) * 1000:.0f}"
                  f" ms){(' — ' + msg.splitlines()[0]) if msg else ''}")

    scapy_ok = True
    try:
        load_scapy()
    except Exception:                                # noqa: BLE001
        scapy_ok = False

    def need_scapy():
        return not scapy_ok

    # ---- configuration --------------------------------------------------------
    def t_config_migration():
        p = os.path.join(tmp, "old.json")
        with open(p, "w") as f:
            json.dump({"config_version": 1, "performance":
                       {"cpu_friendly_mode": True},
                       "appearance": {"theme": "Dark"},
                       "shortcuts": {"start": "<Control-g>"}}, f)
        c = AppConfig(path=p)
        assert c.get("performance.mode") == "Low CPU"
        assert c.get("appearance.theme") == "Dark"
        assert c.get("shortcuts.start") == "<Control-g>"
        assert c.get("shortcuts.stop") == DEFAULT_SHORTCUTS["stop"]
        assert c.get("history.enabled") is False
        assert c.data["config_version"] == CONFIG_SCHEMA_VERSION
        with open(p, "w") as f:
            f.write("{broken")
        c2 = AppConfig(path=p)
        assert c2.warning and c2.get("appearance.theme") == "Light"
        assert os.path.exists(p + ".damaged")

    def t_settings_schema_has_defaults():
        flat = config_defaults_flat()
        for key in settings_schema_keys():
            assert key in flat, f"settings control without default: {key}"
        for page in SETTINGS_PAGES:
            for sec in page["sections"]:
                for c in sec["controls"]:
                    if c.get("type") == "action":
                        for _label, name in c["actions"]:
                            assert name, "empty action"
        msgs = settings_conflicts({"health.active_checks": True,
                                   "mode.active_scanning": False})
        assert msgs and "Quiet" in msgs[0]

    def t_theme_mappings():
        for name, table in PALETTES.items():
            vals = list(table.values())
            assert len(vals) == len(set(vals)), f"{name} not one-to-one"
        keys = set(THEME_LIGHT)
        for name, th in THEMES.items():
            assert set(th) == keys, f"theme {name} missing tokens"
            for k, v in th.items():
                assert re.match(r"^#[0-9a-f]{6}$", v), f"{name}.{k}={v}"
        assert _CANON[LIGHT_TO_DARK_HEX["#ffffff"]] == "#ffffff"

    def t_confidence_scoring():
        d = DeviceRecord(key="aa:bb:cc:00:00:01")
        assert d.confidence == CONFIDENCE_UNCONFIRMED
        d.add_evidence("local_traffic", "x")
        d.add_evidence("local_traffic", "y")
        assert d.score == 10 and d.confidence == CONFIDENCE_LOW
        d.add_evidence("mac_local", "z")
        assert d.score == 50 and d.confidence == CONFIDENCE_MEDIUM
        d.add_evidence("arp_reply", "a")
        assert d.score == 75 and d.confidence == CONFIDENCE_HIGH
        for _ in range(200):
            d.add_evidence("local_traffic", "spam")
            d.add_evidence("rdns", "spam")
        assert d.score == 77, d.score       # strong evidence never pushed out

    def t_mac_randomization():
        assert is_randomized_mac("da:a1:19:23:45:67")
        assert is_randomized_mac("02:00:00:00:00:01")
        assert not is_randomized_mac("00:11:22:33:44:55")
        assert not is_unicast_mac("01:00:5e:00:00:fb")
        assert not is_unicast_mac("ff:ff:ff:ff:ff:ff")
        assert is_unicast_mac("00:11:22:33:44:55")
        assert mac_vendor("da:a1:19:23:45:67") == ""

    def t_device_lifecycle():
        clk = _FakeClock()
        c = cfg({"devices.idle_minutes": 2, "devices.inactive_minutes": 10,
                 "devices.expire_minutes": 60})
        reg = DeviceRegistry("192.168.1.1", [], c, clk)
        reg.local_nets = [ipaddress.ip_network("192.168.1.0/24")]
        d = reg.touch("192.168.1.5", "00:11:22:33:44:55", "mac_local", "x")
        assert d.state == STATE_ACTIVE and d.presence[-1][1] is None
        clk.t += 180
        reg.tick_lifecycle()
        assert d.state == STATE_IDLE
        clk.t += 600
        inact, _ = reg.tick_lifecycle()
        assert d.state == STATE_INACTIVE and inact == [d]
        assert d.presence[-1][1] is not None
        clk.t += 60
        reg.touch("192.168.1.5", "00:11:22:33:44:55", "arp_reply", "y")
        assert d.state == STATE_ACTIVE and d.reactivated_now
        assert len(d.presence) == 2 and d.presence[-1][1] is None
        clk.t += 4000
        _, exp = reg.tick_lifecycle()
        assert d.state == STATE_EXPIRED and exp == [d]
        # lease expiry
        reg.note_dhcp_lease("192.168.1.9", "00:11:22:33:44:66", "pc", 100)
        clk.t += 200
        reg.tick_lifecycle()
        assert "192.168.1.9" not in reg.dhcp_leases

    def t_public_ip_never_a_device():
        c = cfg()
        m = NetworkModel(c, "192.168.1.1", ["192.168.1.20"],
                         ["00:00:00:00:00:20"], now_fn=_FakeClock())
        m.set_identity(local_nets=[ipaddress.ip_network("192.168.1.0/24")])
        reg = m.registry
        dev = reg.touch("8.8.8.8", "00:11:22:33:44:01", "mac_local", "x")
        assert dev is not None and dev.ip == "" and \
            "8.8.8.8" not in reg.ip_to_key
        assert reg.touch("224.0.0.251", None, "mac_local", "x") is None
        assert reg.touch(None, "01:00:5e:00:00:fb", "mac_local", "x") is None
        assert not reg.eligible_ip("192.168.1.255")
        assert reg.eligible_ip("fe80::1")
        assert not reg.eligible_ip("2001:4860::1")
        reg.v6_prefixes = [ipaddress.ip_network("2a01:4f8:1::/64")]
        assert reg.eligible_ip("2a01:4f8:1::5")
        if not scapy_ok:
            return
        p = Ether(src="00:11:22:33:44:01", dst="00:00:00:00:00:20") / \
            IP(src="93.184.215.14", dst="192.168.1.20") / \
            TCP(sport=443, dport=5555, flags="A")
        d = decode_packet(Ether(bytes(p)))
        m.ingest(d)
        assert all(not (dv.ip and is_public_ip(dv.ip))
                   for dv in reg.by_key.values())
        assert "93.184.215.14" in m.remote_hosts
        assert "93.184.215.14" not in reg.ip_to_key

    def t_device_merge_rules():
        clk = _FakeClock()
        c = cfg()
        reg = DeviceRegistry("", [], c, clk)
        a = reg.touch("192.168.1.30", "da:00:00:00:00:01", "mac_local", "x")
        reg._set_dhcp_hostname(a, "Alexs-MacBook-Pro", clk.t)
        clk.t += 100
        a.state = STATE_INACTIVE
        a.presence_close(clk.t)
        clk.t += 900
        b = reg.touch("192.168.1.31", "da:00:00:00:00:02", "mac_local", "x")
        reg._set_dhcp_hostname(b, "Alexs-MacBook-Pro", clk.t)
        assert reg.merge_candidates(b)
        merged = reg.auto_merge_pass()
        assert merged == [(b.key, a.key)], merged
        assert a.key not in reg.by_key and b.merge_history
        restored = reg.split(b.key, 0)
        assert restored is not None and restored.key in reg.by_key
        assert restored.key in b.never_merge
        assert reg.auto_merge_pass() == []          # never re-merged
        # overlapping activity → never auto-merged
        c2 = cfg()
        reg2 = DeviceRegistry("", [], c2, clk)
        x = reg2.touch("192.168.1.40", "da:00:00:00:00:03", "mac_local", "x")
        y = reg2.touch("192.168.1.41", "da:00:00:00:00:04", "mac_local", "x")
        clk.t += 300
        for dv in (x, y):
            reg2.touch(dv.ip, dv.mac, "mac_local", "again")
            reg2._set_dhcp_hostname(dv, "kitchen-tablet-7", clk.t)
        x.state = STATE_INACTIVE
        x.presence_close(clk.t)
        clk.t += 600
        assert reg2.auto_merge_pass() == []
        # generic names never merge
        reg3 = DeviceRegistry("", [], cfg(), clk)
        g1 = reg3.touch("10.0.0.2", "da:00:00:00:00:05", "mac_local", "x")
        reg3._set_dhcp_hostname(g1, "iPhone", clk.t)
        g1.state = STATE_INACTIVE
        g1.presence_close(clk.t)
        clk.t += 500
        g2 = reg3.touch("10.0.0.3", "da:00:00:00:00:06", "mac_local", "x")
        reg3._set_dhcp_hostname(g2, "iPhone", clk.t)
        assert reg3.auto_merge_pass() == []
        # 5.1.2: the name/alias index finds exactly what the full scan finds
        reg4 = DeviceRegistry("", [], cfg(), clk)
        devs = []
        for i in range(40):
            d = reg4.touch(f"10.1.0.{i + 2}", "da:00:00:00:01:%02x" % i,
                           "mac_local", "x")
            if i % 3 == 0:
                reg4._set_dhcp_hostname(d, f"living-room-tv-{i % 4}", clk.t)
            if i % 5 == 0:
                d.alias = f"Kid laptop {i % 2}"
            d.state = STATE_INACTIVE
            d.presence_close(clk.t)
            clk.t += 50
            devs.append(d)
        pool = reg4.merge_pool()
        for d in devs:
            full = [(o.key, cf, r) for o, cf, r in reg4.merge_candidates(d)]
            fast = [(o.key, cf, r) for o, cf, r in
                    reg4.merge_candidates(d, pool(d))]
            assert full == fast, (d.key, full, fast)
        assert any(reg4.merge_candidates(d) for d in devs)

    def t_explain_registry():
        """5.1.2 F7: nothing that can be shown is left unexplained."""
        for kind in ALERT_TYPES:
            assert explain("alert", kind), f"alert {kind} has no EXPLAIN"
            assert ALERT_CHECKLIST.get(kind), f"alert {kind}: no checklist"
        for st in (STATE_ACTIVE, STATE_IDLE, STATE_INACTIVE, STATE_EXPIRED):
            assert explain("state", st), st
        for lv in LEVEL_WORD:
            assert explain("level", lv), lv
        for c in CONFIDENCE_ORDER:
            assert explain("confidence", c), c
        # Help: one topic per title, the 5.0.2 text kept, every topic and
        # tour named in all three languages
        titles = [tp["title"] for tp in help_topics()]
        assert len(titles) == len(set(titles)) >= 40
        for term, defn in GLOSSARY:
            assert term in titles and defn in str(next(
                tp["body"] for tp in help_topics() if tp["title"] == term))
        for lang in ("fr", "es"):
            for t in titles + [v[0] for v in TOURS.values()]:
                assert _i18n_lookup(t, I18N[lang], lang) is not None, \
                    (lang, t)

    def t_registrable_domain():
        assert registrable_domain("www.example.co.uk") == "example.co.uk"
        assert registrable_domain("a.b.example.com") == "example.com"
        assert registrable_domain("example.com") == "example.com"
        p = os.path.join(tmp, "psl.dat")
        with open(p, "w") as f:
            f.write("// ===BEGIN ICANN DOMAINS===\ncom\nuk\nco.uk\n*.ck\n"
                    "!www.ck\ngithub.io\n")
        psl = load_psl(p)
        assert psl.registrable("x.y.example.co.uk") == "example.co.uk"
        assert psl.registrable("foo.bar.ck") == "foo.bar.ck"
        assert psl.registrable("a.www.ck") == "www.ck"
        assert psl.registrable("me.github.io") == "me.github.io"
        assert psl.registrable("cdn.me.github.io") == "me.github.io"

    def t_dns_parsing():
        if need_scapy():
            return "skip"
        q = Ether(bytes(Ether() / IP(src="192.168.1.5", dst="192.168.1.1") /
                        UDP(sport=5000, dport=53) /
                        DNS(id=7, rd=1, qd=DNSQR(qname="www.example.com"))))
        d = decode_packet(q)
        assert d["proto"] == "DNS" and d["dns"]["qr"] == 0 and \
            d["dns"]["qname"] == "www.example.com"
        r = Ether(bytes(Ether() / IP(src="192.168.1.1", dst="192.168.1.5") /
                        UDP(sport=53, dport=5000) /
                        DNS(id=7, qr=1, qd=DNSQR(qname="www.example.com"),
                            an=[DNSRR(rrname="www.example.com",
                                      type="CNAME", rdata="edge.example.net"),
                                DNSRR(rrname="edge.example.net",
                                      rdata="93.184.215.14")])))
        d = decode_packet(r)
        assert d["dns"]["answers"] == ["93.184.215.14"], d["dns"]
        assert ("93.184.215.14", "www.example.com") in d["learns"]
        nx = Ether(bytes(Ether() / IP() / UDP(sport=53, dport=5000) /
                         DNS(id=8, qr=1, rcode=3,
                             qd=DNSQR(qname="nope.example"))))
        assert "does not exist" in decode_packet(nx)["text"]
        t = Ether(bytes(Ether() / IP(src="192.168.1.5", dst="9.9.9.9") /
                        TCP(sport=5001, dport=53, flags="PA") /
                        Raw(b"\x00\x1d" + bytes(DNS(rd=1, qd=DNSQR(
                            qname="example.com"))))))
        d = decode_packet(t)
        assert d["proto"] == "DNS" and d["dns"]["transport"] == "TCP"
        md = Ether(bytes(Ether(src="00:11:22:33:44:66",
                               dst="01:00:5e:00:00:fb") /
                         IP(src="192.168.1.60", dst="224.0.0.251") /
                         UDP(sport=5353, dport=5353) /
                         DNS(qr=1, qd=None,
                             an=DNSRR(rrname="_googlecast._tcp.local",
                                      type="PTR",
                                      rdata="TV._googlecast._tcp.local"),
                             ar=DNSRR(rrname="TV._googlecast._tcp.local",
                                      type="TXT", rdata=[b"md=Chromecast"]))))
        d = decode_packet(md)
        assert d["mdns"] and "_googlecast._tcp" in d["mdns"]["services"]
        assert d["mdns"]["txt"].get("md") == "Chromecast"
        assert "TV" in d["mdns"]["names"]

    def t_tls_sni_parser():
        ch = build_client_hello("secure.example.com", pad=1400)
        info = parse_tls_hello(ch)
        assert info["sni"] == "secure.example.com"
        assert info["version"] == "TLS 1.3" and "h2" in info["alpn"]
        assert _try_tls_sni(ch) == "secure.example.com"
        r = TlsReassembler()
        key = ("1.1.1.1", 1, "2.2.2.2", 443)
        assert r.feed(key, 1000, ch[:700], 0.0) is None
        assert r.feed(key, 1700, ch[700:1400], 0.1) is None
        full = r.feed(key, 2400, ch[1400:], 0.2)
        assert full == ch and parse_tls_hello(full)["sni"] == \
            "secure.example.com"
        assert parse_tls_hello(b"\x17\x03\x03\x00\x05hello") is None
        assert parse_tls_hello(ch[:60]) is not None   # truncated: no crash
        if need_scapy():
            return
        base = Ether() / IP(src="192.168.1.5", dst="93.184.215.14")
        rs = TlsReassembler()
        p1 = Ether(bytes(base / TCP(sport=4000, dport=443, flags="PA",
                                    seq=10) / Raw(ch[:1000])))
        p2 = Ether(bytes(base / TCP(sport=4000, dport=443, flags="PA",
                                    seq=1010) / Raw(ch[1000:])))
        assert decode_packet(p1, reasm=rs)["tls"] is None
        d2 = decode_packet(p2, reasm=rs)
        assert d2["tls"]["sni"] == "secure.example.com", d2["tls"]

    def t_flow_aggregation():
        if need_scapy():
            return "skip"
        clk = _FakeClock(1000.0)
        c = cfg()
        m = NetworkModel(c, "192.168.1.1", ["192.168.1.20"], [], clk)
        m.set_identity(local_nets=[ipaddress.ip_network("192.168.1.0/24")])
        L, R = ("192.168.1.20", "00:00:00:00:00:20"), ("8.8.4.4", "00:00:"
                                                       "00:00:00:01")
        seq = [0]

        def pkt(out, flags, payload=b"", s=None):
            src, dst = (L, R) if out else (R, L)
            p = Ether(src=src[1] if out else R[1], dst=R[1] if out else L[1]) \
                / IP(src=src[0], dst=dst[0]) / \
                TCP(sport=5555 if out else 443, dport=443 if out else 5555,
                    flags=flags, seq=s if s is not None else 1)
            if payload:
                p = p / Raw(payload)
            d = decode_packet(Ether(bytes(p)))
            seq[0] += 1
            d["time"] = 1000.0 + seq[0]
            clk.t = d["time"]
            m.ingest(d)
            return d
        pkt(True, "S", s=100)
        pkt(False, "SA", s=900)
        pkt(True, "PA", b"x" * 100, s=101)
        pkt(False, "A", b"y" * 1000, s=901)
        pkt(False, "A", b"y" * 1000, s=901)            # retransmission
        f = next(iter(m.flows.active.values()))
        assert f.local_ip == L[0] and f.remote_port == 443
        assert f.packets_out == 2 and f.packets_in == 3
        assert f.bytes_in > f.bytes_out and f.retrans == 1
        assert f.status_text() == "Open" and f.initiator == "local"
        dev = m.device_for(L[0])
        assert dev.bytes_up > 0 and dev.bytes_down > dev.bytes_up
        assert m.metrics.totals["bytes_down"] > m.metrics.totals["bytes_up"]
        pkt(True, "R", s=201)
        assert f.rst and f.status_text().startswith("Reset")
        clk.t += 100
        m.flows.expire(clk.t)
        assert f.closed and not m.flows.active and f in m.flows.archive

    def t_alert_debounce():
        clk = _FakeClock()
        c = cfg()
        ae = AlertEngine(c, clk)
        dev = DeviceRecord(key="00:11:22:33:44:55", ip="192.168.1.9")
        a1 = ae.new_device(dev)
        a2 = ae.new_device(dev)
        assert a1 is a2 and a1.count == 2 and len(ae.order) == 1
        assert ae.gateway_change("192.168.1.1", 2) is not None
        assert ae.gateway_change("192.168.1.1", 2) is None     # debounced
        clk.t += 200
        assert ae.gateway_change("192.168.1.1", 3) is not None
        c.set("alerts.muted_devices", [f"new_device|{dev.key}"])
        a1.acknowledged = True
        assert ae.new_device(dev) is None
        c.set("alerts.chatty_device", False)
        assert ae.chatty_device(dev) is None
        dev.expected = True
        assert AlertEngine(cfg(), clk).new_device(dev) is None

    def t_m6_corrections():
        """5.1.2 M6: a category correction applies, is journaled, said on
        the timeline, kept in a saved session and undone; the story
        templates refuse a claim stronger than its evidence."""
        clk = _FakeClock()
        c = cfg()
        m = NetworkModel(c, "192.168.1.1", ["192.168.1.20"], [], clk)
        d = m.registry.touch("192.168.1.5", "00:11:22:33:44:55",
                             "arp_reply", "x")
        m.register_website("ads.example.com", "93.184.215.14", d, "DNS")
        m.register_website("www.example.com", "93.184.215.14", d, "DNS")
        saved = dict(CATEGORY_OVERRIDES)
        try:
            CATEGORY_OVERRIDES.clear()
            assert m.correct_category("www.example.com", "Advertising") == \
                ["example.com"]
            for dom in ("ads.example.com", "www.example.com"):
                w = m.websites[dom]
                assert (w.category, w.category_source) == (
                    "Advertising", CAT_YOURS), (w.category,
                                                w.category_source)
            assert c.get("websites.category_overrides") == {
                "example.com": "Advertising"}
            assert m.timeline[-1]["text"].startswith(
                "You set the category of example.com")
            # a new name of the same site gets it too
            m.register_website("cdn.example.com", "93.184.215.15", d, "DNS")
            assert m.websites["cdn.example.com"].category == "Advertising"
            payload = json.loads(json.dumps(SessionCodec.serialize(m),
                                            default=str))
            m2 = NetworkModel(c)
            SessionCodec.load(payload, m2)
            assert m2.websites["www.example.com"].category == "Advertising"
            assert m.undo_correction() == []
            assert "example.com" not in CATEGORY_OVERRIDES
            assert not m.websites["www.example.com"].category
            assert m.timeline[-1]["text"].startswith("You undid")
            # place and owner
            assert m.correct_tags(d.key, "Kitchen", "Sam") == [d.key]
            assert (d.place, d.owner) == ("Kitchen", "Sam")
            m.undo_correction()
            assert (d.place, d.owner) == ("", "")
        finally:
            CATEGORY_OVERRIDES.clear()
            CATEGORY_OVERRIDES.update(saved)
        for key, claims in (
                ("top_sites", {"sites": C("example.com", LV_UNKNOWN)}),
                ("first_seen", {"when": C("today", LV_INFERRED),
                                "span": C("this session", LV_OBSERVED)}),
                ("usual_hours", {"hours": C("07:00–23:00", LV_OBSERVED),
                                 "basis": C("40 minutes", LV_OBSERVED)})):
            try:
                narrate(key, **claims)
            except NarrativeRefused:
                continue
            raise AssertionError(f"{key} stated more than its evidence")
        line = narrate("top_sites", sites=C("example.com", LV_CORRELATED))
        assert line.startswith("◎ Appears to talk"), line

    def t_m7_asof_and_builder():
        """5.1.2 M7: "as of" answers are exact for what is kept; the
        filter builder writes what DisplayFilter already reads."""
        clk = _FakeClock()
        c = cfg()
        reg = DeviceRegistry("", [], c, clk)
        d = reg.touch("192.168.1.30", "da:00:00:00:00:31", "mac_local", "x")
        base = 36000.0                       # 10:00 on the fake day
        d.first_seen = base
        d.presence = [[base, base + 300], [base + 1200, None]]
        assert device_online_at(d, base + 60)
        assert not device_online_at(d, base + 600)       # 10:10: away
        assert device_online_at(d, base + 1260)          # 10:21: back
        assert not device_online_at(d, base - 60)        # before it came
        w = WebsiteRecord(domain="later.example", first_seen=base + 900)
        assert not website_known_at(w, base + 600)
        assert website_known_at(w, base + 900)
        cases = [
            ([("and", "Protocol", "is", "dns")], "proto:dns"),
            ([("and", "Protocol", "is not", "arp")], "-proto:arp"),
            ([("and", "Port", "is", "443"), ("or", "Port", "is", "853")],
             "port:443 or port:853"),
            ([("and", "Device", "is", "Living Room TV")],
             'device:"Living Room TV"'),
            ([("and", "Direction", "is", "up")], "dir:up"),
            ([("and", "Severity", "is", "warning")], "sev:warning"),
            ([("and", "Length", "greater than", "1000")], "len>1000"),
            ([("and", "Length", "less than", "60")], "len<60"),
            ([("and", "Website", "is", "example.com"),
              ("and", "Direction", "is", "down")],
             "site:example.com dir:down"),
            ([("and", "Address", "is", "192.168.1.0/24"),
              ("and", "Protocol", "is not", "arp")],
             "ip:192.168.1.0/24 -proto:arp"),
            ([("and", "Source", "is", "192.168.1.5")], "src:192.168.1.5"),
            ([("and", "Destination", "is", "8.8.8.8")], "dst:8.8.8.8"),
            ([("and", "Connection", "is", "12")], "stream:12"),
            ([("and", "Text", "is", "hello")], "text:hello"),
            ([("and", "Device", "is", "@mine"),
              ("or", "Device", "is", "@guest")],
             "device:@mine or device:@guest"),
            ([("and", "Protocol", "is", "tls"), ("and", "Port", "is not",
                                                  "443")],
             "proto:tls -port:443"),
            ([("and", "Port", "is", "53"), ("or", "Port", "is", "853"),
              ("or", "Protocol", "is", "mdns")],
             "port:53 or port:853 or proto:mdns"),
            ([("and", "Severity", "is", "danger"),
              ("and", "Direction", "is", "lan")], "sev:danger dir:lan"),
            ([("and", "Website", "is not", "ads.example")],
             "-site:ads.example"),
            ([("and", "Length", "greater than", "1400"),
              ("and", "Protocol", "is", "udp")], "len>1400 proto:udp"),
        ]
        assert len(cases) == 20
        for rows, hand in cases:
            got = builder_expression(rows)
            assert DisplayFilter.compile(got) == \
                DisplayFilter.compile(hand), (got, hand)
            back = builder_rows(got)
            assert back is not None and [r[1:] for r in back] == \
                [r[1:] for r in rows], (got, back)
        for text in ("(ip.src == 1.2.3.4)", "tcp.port == 443", "foo bar"):
            assert builder_rows(text) is None, text

    def t_m9_bootstrap():
        """5.1.2 M9: a broken download resumes and still passes its
        fingerprint; the Tk check warns and never blocks; an unattended
        start skips the pre-flight wait."""
        import http.server
        import socketserver
        payload = os.urandom(300_000)
        sha = hashlib.sha256(payload).hexdigest()

        class H(http.server.BaseHTTPRequestHandler):
            def do_GET(self):
                rng = self.headers.get("Range", "")
                m = re.match(r"bytes=(\d+)-", rng)
                start = int(m.group(1)) if m else 0
                body = payload[start:]
                self.send_response(206 if start else 200)
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def log_message(self, *a):
                pass
        srv = socketserver.TCPServer(("127.0.0.1", 0), H)
        th = threading.Thread(target=srv.serve_forever, daemon=True)
        th.start()
        old_np = os.environ.get("no_proxy"), os.environ.get("NO_PROXY")
        os.environ["no_proxy"] = os.environ["NO_PROXY"] = "127.0.0.1"
        try:
            dest = os.path.join(tmp, "dl", "pkg.whl")
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            with open(dest + ".part", "wb") as f:      # cut at 50 %
                f.write(payload[:150_000])
            seen = []
            got = fetch_to_file(f"http://127.0.0.1:{srv.server_address[1]}"
                                f"/pkg.whl", dest, sha,
                                progress=lambda *a: seen.append(a[2]))
            assert got == dest and sha256_file(dest) == sha
            assert any("Resuming from 0.1 MB" in x for x in seen), seen
            assert not os.path.exists(dest + ".part")
        finally:
            srv.shutdown()
            srv.server_close()
            for k, v in zip(("no_proxy", "NO_PROXY"), old_np):
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
        assert tk_version_note(8.5) and "8.6" in tk_version_note(8.5)
        assert tk_version_note(8.6) == ""
        assert preflight_unattended()                 # a test run
        assert "Preparing the capture driver" in CAPTURE_ONLY_STEPS
        assert SCRIPT_VERSION == "5.2.3"

