@self_test()
def t_job_runner(ctx):
    """Jobs run one at a time off the caller's thread, report back through
    the results queue, refuse a second job of the same kind, and can be
    cancelled; pieces_under_gate gives the gate back between pieces."""
    class FakeApp:
        def __init__(self):
            self._async_results = queue.Queue()
            self.banners = []

        def _set_banner(self, text, kind="info"):
            self.banners.append(text)
    app = FakeApp()
    jobs = JobRunner(app)
    seen = {}
    started = threading.Event()
    release = threading.Event()

    def slow(job):
        started.set()
        release.wait(5)
        return threading.current_thread().name

    def drain(timeout=5.0):
        t_end = time.time() + timeout
        while jobs.busy() and time.time() < t_end:
            try:
                app._async_results.get(timeout=0.05)()
            except queue.Empty:
                pass
    jobs.submit("a", "Test", slow, lambda r: seen.update(done=r))
    assert started.wait(5)
    assert jobs.submit("a", "Test", slow) is None and app.banners
    release.set()
    drain()
    assert seen.get("done") == "jobs", seen

    def endless(job):
        while True:
            job.progress(0.5)
            time.sleep(0.01)
    jobs.submit("b", "Test", endless, None,
                lambda e: seen.update(failed=type(e).__name__))
    time.sleep(0.05)
    jobs.cancel_all()
    drain()
    assert seen.get("failed") == "JobCancelled", seen
    gate = GuiGate()
    job = Job("c", "", None)
    assert job.pieces_under_gate(gate, iter("abc")) == ["a", "b", "c"]
    assert not gate.held() and gate._count == 0
    jobs.stop()


@self_test()
def t_perf_probe(ctx):
    """The window perf probe separates waiting for the GuiGate from work,
    names only slow callbacks, names an after() callback by what it calls,
    and is off unless asked for."""
    class CW:
        pass

    def handler():
        return None

    def make_callit(fn):
        def callit():          # how tkinter wraps an after() callback
            fn()
        return callit
    cw = CW()
    cw.func = handler
    p = PerfProbe()
    p.record(cw, 0.0, 0.001, 0.003)          # 3 ms: counted, not named
    p.record(cw, 1.0, 1.2, 1.25)             # 200 ms waiting, 50 working
    sm = p.summary()
    assert sm["callbacks"] == 2 and sm["over_100ms"] == 1, sm
    assert sm["max_wait_ms"] == 200.0 and sm["max_work_ms"] == 50.0, sm
    assert "handler" in sm["max_name"], sm
    assert len(p.slow) == 1 and "waiting for the gate" in p.slow_lines()[0]
    cw2 = CW()
    cw2.func = make_callit(handler)
    assert callback_name(cw2) == "after:" + handler.__qualname__
    assert PERF[0] is None
    assert bench_check({"S1": {"import.max_ms": 50.0}},
                       {"S1": {"import.max_ms": 100,
                               "theme.max_ms": 10}}) == [
        ("S1", "import.max_ms", 50.0, 100, True)]


