@self_test()
def t_store_roundtrip(ctx):
    st = Store(ctx.path("s.sqlite3"), session_id=42)
    assert st.schema_version() == STORE_SCHEMA_VERSION, st.error
    obs = [(1, 100.0, "dns_answer", "aa:bb", {"domain": "x.example",
                                              "ip": "93.184.215.14"}, 7),
           (2, 101.0, "tls_sni", "aa:bb", {"domain": "x.example"}, 9)]
    assert st.write_observations(obs)
    assert st.write_resolutions([(100.0, "aa:bb", "x.example",
                                  "93.184.215.14")])
    f = FlowRecord(5, ("TCP",), "TCP", "192.168.1.5", 4000,
                   "93.184.215.14", 443, 100.5)
    f.device_key, f.domain, f.assoc = "aa:bb", "x.example", AS_CONNECTED
    assert st.write_flows([f])
    assert st.write_site_ties([("aa:bb", "x.example",
                                [AS_CONNECTED, 100.0, 101.0, 2])])
    assert st.write_events([{"when": 102.0, "kind": "website",
                             "severity": "INFO", "text": "First visit",
                             "ref": ("website", "x.example"),
                             "device": "aa:bb"}])
    assert st.flush_now(10)
    got = st.observations("aa:bb")
    assert [o[1] for o in got] == ["tls_sni", "dns_answer"], got
    assert got[1][2]["ip"] == "93.184.215.14" and got[1][3] == 7
    c = st.counts()
    assert c["observations"] == 2 and c["flows"] == 1 and \
        c["site_ties"] == 1 and c["events"] == 1 and c["sessions"] >= 1, c
    r = st.query("SELECT assoc, domain FROM flows WHERE device=?",
                 ("aa:bb",))
    assert r == [(AS_CONNECTED, "x.example")]
    try:
        st.query("DELETE FROM flows")
        raise AssertionError("write through query()")
    except ValueError:
        pass
    st.prune(1)          # everything above is from 1970: pruned
    assert st.flush_now(10)
    assert st.counts()["observations"] == 0
    st.stop(5)


@self_test()
def t_m1b_history_delete_all(ctx):
    """5.3.4 (LG-13, CO-10): "Delete ALL history" leaves no row and no
    copy (backup, pre-upgrade backup, -wal); "Session only" history is
    cleared on close and again at the next open, so a crash keeps nothing
    either."""
    path = ctx.path("h.sqlite3")
    st = Store(path, session_id=7)
    assert st.write_observations([(1, time.time(), "dns_answer", "aa:bb",
                                   {"domain": "secret-clinic.example"}, 7)])
    assert st.flush_now(10)
    for extra in (".bak", ".v1.bak", ".corrupt-1"):
        shutil.copyfile(path, path + extra)
    assert st.clear()
    assert st.flush_now(30)
    assert st.counts()["observations"] == 0
    left = [f for f in os.listdir(os.path.dirname(path))
            if f.startswith("h.sqlite3") and f not in (
                "h.sqlite3", "h.sqlite3-wal", "h.sqlite3-shm")]
    assert left == [], left
    with contextlib.suppress(OSError):
        assert os.path.getsize(path + "-wal") == 0
    with open(path, "rb") as f:
        assert b"secret-clinic" not in f.read()
    st.stop(5)
    # the close, as CO-10's repro drives it: snapshot, then forget
    cfg = ctx.cfg({"history.enabled": True,
                   "history.retention": "Session only"})
    gw, ips, macs, nets = scenario_identity()
    m = NetworkModel(cfg, gw, ips, macs)
    m.set_identity(local_nets=nets)
    m.use_packet_clock = True
    replay_frames(m, ScenarioBuilder().home_network(),
                  decoder=fast_frame_decoder(m), tick_every=500)
    for dev in m.registry.by_key.values():
        dev.live = True
    path = ctx.path("h2.sqlite3")
    st = Store(path, session_id=8)
    win = types.SimpleNamespace(history=st, config=cfg, model=m)
    win._history_pieces = lambda: MiniWireshark._history_pieces(win)
    win._session_only_history = \
        lambda: MiniWireshark._session_only_history(win)
    # (review) the saved packets go too, not only the database rows
    ring = PacketRing(ctx.path("packets"), 20, st, 8)
    ring.put(1, b"\x00" * 60 + b"password=LGCANARY", time.time(), 1)
    assert ring.flush(5)
    assert [f for f in os.listdir(ctx.path("packets"))
            if f.startswith("seg-")]
    win.packet_ring = ring
    win._wipe_packets = lambda: MiniWireshark._wipe_packets(win)
    st.write_observations([(1, time.time(), "dns_answer", "aa:bb",
                            {"domain": "secret-clinic.example"}, 7)])
    MiniWireshark._write_history(win)
    assert st.flush_now(10)
    assert st.query("SELECT COUNT(*) FROM devices")[0][0] > 0
    MiniWireshark._forget_session_history(win)
    st.stop(5)
    ring.stop()
    assert not [f for f in os.listdir(ctx.path("packets"))
                if f.startswith("seg-")]
    con = sqlite3.connect(path)
    try:
        for t in ("devices", "presence", "traffic", "domains",
                  "observations"):
            n = con.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
            assert n == 0, (t, n)
    finally:
        con.close()
    assert "_forget_session_history" in inspect.getsource(
        MiniWireshark._on_close)
    assert "st.clear()" in inspect.getsource(MiniWireshark._open_store)


@self_test()
def t_m1b_npcap_signature_path(ctx):
    """5.3.4 (OS-03): the installer's path reaches PowerShell (in
    MW_SIGNED_FILE, read by the script), not as text after -Command."""
    seen = {}

    def fake(cmd, **kw):
        seen["cmd"], seen["env"] = cmd, kw.get("env") or {}
        return subprocess.CompletedProcess(
            cmd, 0, "Valid\nCN=Nmap Software LLC, O=Nmap Software LLC\n", "")
    path = ctx.path("npcap 1.80 (Krystel's).exe")
    st, who = _authenticode_info(path, run=fake)
    assert (st, who) == ("Valid", "CN=Nmap Software LLC, O=Nmap Software LLC")
    assert seen["cmd"][-2] == "-Command" and path not in " ".join(
        seen["cmd"])
    assert "$env:MW_SIGNED_FILE" in seen["cmd"][-1]
    assert seen["env"]["MW_SIGNED_FILE"] == os.path.abspath(path)
    assert signer_matches(who, "Nmap Software LLC")


@self_test()
def t_bf001_reputation_ranges(ctx):
    """5.3.4 (BF-001): an address inside a big range is found even when a
    smaller range starts later inside it; IPv6 ranges are kept; a list
    naming a private range is ignored there."""
    rl = ReputationList("test")
    rl.set_ranges([
        (int(ipaddress.ip_address("10.0.0.0")),
         int(ipaddress.ip_address("10.255.255.255")), "big"),
        (int(ipaddress.ip_address("10.1.1.0")),
         int(ipaddress.ip_address("10.1.1.255")), "small"),
        (int(ipaddress.ip_address("2001:db8::")),
         int(ipaddress.ip_address("2001:db8::ffff")), "six", 6)])
    assert rl.lookup("10.200.0.1") == "big"
    assert rl.lookup("10.1.1.9") in ("big", "small")
    assert rl.lookup("11.0.0.1") == "" and rl.lookup("9.255.255.255") == ""
    assert rl.lookup("2001:db8::5") == "six"
    assert rl.lookup("2001:db9::5") == "" and len(rl) == 3
    old = ReputationList("old way")          # filled like 5.2.3 did
    for a, b, i in ((1, 100, "a"), (5, 6, "b")):
        old.starts.append(a)
        old.ends.append(b)
        old.ids.append(i)
    assert old.lookup("0.0.0.50") == "a"
    path = ctx.path("drop.json")
    with open(path, "w", encoding="utf-8") as f:
        f.write('{"type": "metadata", "timestamp": 1700000000}\n')
        for cidr, sbl in (("1.10.16.0/20", "SBL1"), ("1.10.20.0/24", "SBL2"),
                          ("2a06:e480::/29", "SBL3"),
                          ("192.168.0.0/16", "SBL4")):
            f.write(json.dumps({"cidr": cidr, "sblid": sbl}) + "\n")
    rl = load_drop(path)
    assert rl.lookup("1.10.30.1").startswith("SBL1")
    assert rl.lookup("2a06:e480::1").startswith("SBL3")
    assert rl.lookup("192.168.1.10") == "" and rl.skipped == 1
    ok, msg = validate_drop(path)
    assert "1 of them IPv6" in msg and "1 private" in msg, msg


@self_test()
def t_bf002_wifi_location_hidden(ctx):
    """5.3.4 (BF-002): Windows 11 24H2's "needs Location" answer is told
    apart from a real reading and said plainly, never read as "not on
    Wi-Fi"; normal readings in three languages are not mistaken for it."""
    msg = ("Network shell commands need location permission to access "
           "WLAN information. Turn on Location services on the Location "
           "page in Privacy & security settings.\n\nHere is the URI for "
           "the Location page in the Settings app:\n"
           "ms-settings:privacy-location\n")
    assert netsh_location_hidden(msg)
    for good in (NETSH_EN, NETSH_FR, NETSH_ES, ""):
        assert not netsh_location_hidden(good)
    p = WifiProbe()
    real_win, real_cmd = IS_WINDOWS, WifiProbe._cmd
    try:
        globals()["IS_WINDOWS"] = True
        WifiProbe._cmd = staticmethod(lambda cmd, timeout=10: msg)
        assert p.read() is None and p.hidden == WIFI_LOCATION_NOTE
        WifiProbe._cmd = staticmethod(lambda cmd, timeout=10: NETSH_EN)
        assert p.read() and p.hidden == ""
    finally:
        globals()["IS_WINDOWS"] = real_win
        WifiProbe._cmd = real_cmd
    hyps = investigate_slow({"wifi": None, "wifi_hidden": WIFI_LOCATION_NOTE})
    w = [h for h in hyps if h["key"] == "wifi"]
    assert w and w[0]["status"] == "Can't tell", hyps


