@self_test()
def t_co01_co02_router_impersonation(ctx):
    """5.3.4 (CO-02): a device answering for the router's address every
    second while the router answers every 30 s is ARP spoofing (DANGER);
    it never becomes "the Router" nor gets its IPv6 announcements
    excused. (CO-01): an RA from anyone but the router, or for a huge
    prefix, never makes Internet addresses "local"."""
    S = ScenarioBuilder
    ATT = ("192.168.1.66", "02:66:66:66:66:66")

    def arp(b, ip, mac, dt):
        b._emit(PK.Ether(src=mac, dst=S.PHONE[1]) /
                PK.ARP(op=2, psrc=ip, hwsrc=mac, pdst=S.PHONE[0],
                       hwdst=S.PHONE[1]), dt=dt)
    gw, ips, macs, nets = scenario_identity()
    m = NetworkModel(ctx.cfg({}), gw, ips, macs)
    m.set_identity(local_nets=nets)
    m.use_packet_clock = True
    b = S()
    b.home_network()
    replay_frames(m, b.frames, decoder=fast_frame_decoder(m))
    b.frames = []
    arp(b, ATT[0], ATT[1], 1)
    for sec in range(300):
        arp(b, S.GW[0], ATT[1], 1.0)
        if sec % 30 == 0:
            arp(b, S.GW[0], S.GW[1], 0.01)
    replay_frames(m, b.frames, decoder=fast_frame_decoder(m), tick_every=20)
    reg = m.registry
    spoof = [a for a in m.alerts.alerts.values() if a.kind == "arp_spoof"]
    assert spoof and spoof[0].severity == "DANGER"
    assert reg.gw_macs == {S.GW[1].lower()} and \
        ATT[1] in reg.gw_candidates, (reg.gw_macs, reg.gw_candidates)
    att = reg.by_key[ATT[1]]
    m._classify_dirty.add(att.key)
    m._classify()
    assert att.device_class != "Router", att.class_reasons
    assert reg.ip_to_key.get(S.GW[0]) == S.GW[1].lower()
    b.frames = []
    b._emit(PK.Ether(src=ATT[1], dst="33:33:00:00:00:01") /
            PK.IPv6(src="fe80::66", dst="ff02::1") /
            PK.ICMPv6ND_RA(routerlifetime=0) /
            PK.ICMPv6NDOptPrefixInfo(prefix="2000::", prefixlen=3) /
            PK.ICMPv6NDOptSrcLLAddr(lladdr=ATT[1]))
    replay_frames(m, b.frames, decoder=fast_frame_decoder(m))
    assert all(str(p) != "2000::/3" for p in m.v6_prefixes), m.v6_prefixes
    assert not reg.eligible_ip("2606:4700::6810:84e5")
    assert [a for a in m.alerts.alerts.values() if a.kind == "rogue_ra"]
    # a router replaced for good: the new one is trusted once the old one
    # has been quiet for 5 minutes
    reg2 = DeviceRegistry("192.168.1.1", set(), ctx.cfg({}),
                          now_fn=lambda: 1000.0)
    reg2.note_arp_reply("192.168.1.1", "00:11:22:00:00:01", 100.0)
    reg2.note_arp_reply("192.168.1.1", "00:11:22:00:00:02", 1000.0)
    assert "00:11:22:00:00:02" in reg2.gw_macs, reg2.gw_candidates
    # (review) the router answers ARP once, then only forwards traffic;
    # the attacker answers every second for 6 minutes: still DANGER, and
    # the attacker never gets the router's address
    m3 = NetworkModel(ctx.cfg({}), gw, ips, macs)
    m3.set_identity(local_nets=nets)
    m3.use_packet_clock = True
    b = S()
    b.home_network()
    replay_frames(m3, b.frames, decoder=fast_frame_decoder(m3))
    b.frames = []
    arp(b, S.GW[0], S.GW[1], 1)
    for sec in range(360):
        arp(b, S.GW[0], ATT[1], 0.5)
        b._emit(PK.Ether(src=S.GW[1], dst=S.ME[1]) /
                PK.IP(src="93.184.215.14", dst=S.ME[0]) /
                PK.UDP(sport=443, dport=50000) / PK.Raw(b"x" * 40), dt=0.5)
    replay_frames(m3, b.frames, decoder=fast_frame_decoder(m3),
                  tick_every=20)
    reg3 = m3.registry
    assert [a for a in m3.alerts.alerts.values()
            if a.kind == "arp_spoof" and a.severity == "DANGER"]
    assert ATT[1] not in reg3.gw_macs, reg3.gw_macs
    assert reg3.ip_to_key.get(S.GW[0]) == S.GW[1].lower()


@self_test()
def t_ip001_snooze_and_co13_clock_step(ctx):
    """5.3.4 (IP-001): a snoozed alert type stays quiet until the snooze
    ends, then shows again; a DANGER snooze is a day at most; what was
    held back is counted. (CO-13): a clock that steps back doesn't silence
    debounced detections; another program on a known port is reported."""
    cfg = ctx.cfg({})
    clock = [1761600000.0]
    eng = AlertEngine(cfg, now_fn=lambda: clock[0])
    app = types.SimpleNamespace(config=cfg, _set_banner=lambda *a, **k: 0)
    first = eng.arp_spoof("192.168.1.1", 2, 5, True)
    assert first is not None and first.severity == "DANGER"
    real_time = time.time
    try:
        time.time = lambda: clock[0]
        MiniWireshark.alert_snooze(app, first, 7 * 86400, whole_type=True)
        until = eng.snoozed_until("arp_spoof")
        assert until - clock[0] == 86400, until - clock[0]   # capped
        clock[0] += 3600
        eng._debounce.clear()
        assert eng.arp_spoof("192.168.1.1", 2, 5, True) is None
        assert eng.suppressed == 1
        clock[0] += 86400                         # the snooze is over
        eng._debounce.clear()
        again = eng.arp_spoof("192.168.1.1", 2, 5, True)
        assert again is not None
    finally:
        time.time = real_time
    # CO-13 (b): the clock steps back 3 hours; a new detection is not
    # held back by the old timestamp
    eng2 = AlertEngine(ctx.cfg({}), now_fn=lambda: clock[0])
    assert not eng2._debounced("k", 120)
    clock[0] -= 3 * 3600
    assert not eng2._debounced("k", 120)
    assert eng2._debounced("k", 120)
    # CO-13 (a)
    lw = ListenWatch(ctx.path("listening.json"))
    lw.check({("TCP", "0.0.0.0", 8080): (10, "python")})
    assert not lw.check({("TCP", "0.0.0.0", 8080): (11, "python")})
    got = lw.check({("TCP", "0.0.0.0", 8080): (12, "nc")})
    assert len(got) == 1 and "nc" in got[0][4], got


@self_test()
def t_lg03_credentials_hidden_on_the_way_out(ctx):
    """5.3.4 (LG-03, RT-03): a password in a URL, a query string or an
    Authorization header never reaches the info text, a CSV file or the
    clipboard; CSV cells still can't start a formula."""
    canary = "LGCANARYpw9"
    for text in (f"GET /login?user=alex&password={canary}&token={canary} "
                 f"HTTP/1.1",
                 f"Unsecured web request: POST /a?pwd={canary} HTTP/1.0",
                 f"Authorization: Basic {canary}==",
                 f"Host: x\r\nCookie: sid={canary}\r\n",
                 f"see http://alex:{canary}@cam.local/live",
                 f"https://x.example/cb?code={canary}&state=1",
                 f"DESCRIBE rtsp://cam/s?token={canary} RTSP/1.0"):
        out = hide_credentials(text)
        assert canary not in out, out
    assert hide_credentials("GET /index.html HTTP/1.1") == \
        "GET /index.html HTTP/1.1"
    assert hide_credentials("192.168.1.5 → example.com") == \
        "192.168.1.5 → example.com"
    buf = io.StringIO()
    w = safe_csv_writer(buf)
    w.writerow(["=HYPERLINK(1)", f"GET /?password={canary} HTTP/1.1", 3])
    got = buf.getvalue()
    assert canary not in got and got.startswith("'=HYPERLINK"), got
    d = {"dns_names": [], "learns": [], "dst_ip": "", "seq": None}
    _decode_tcp_payload(d, f"GET /login?password={canary} HTTP/1.1\r\n"
                           f"Host: a.example\r\n\r\n".encode(), None)
    assert canary not in d.get("text", "") and "query hidden" in d["text"]


@self_test()
def t_lg02_saved_streams_hold_no_password(ctx):
    """5.3.4 (LG-02): the redacted stream (what Save as… writes, text or
    hex) holds no password for an HTTP form, telnet, MQTT, a header split
    over two segments, or HTTP on a port outside the usual list."""
    C = b"LGCANARYpw9"
    auth = b"Authorization: Basic " + base64.b64encode(b"alex:" + C)
    cases = (
        (80, [(0, b"POST /signin HTTP/1.1\r\nHost: a.example\r\n"
                 b"Content-Length: 30\r\n\r\nuser=alex&password=" + C),
              (1, b"HTTP/1.1 302 Found\r\n\r\n")]),
        (23, [(1, b"login: "), (0, b"alex\r\n"), (1, b"Password: "),
              (0, C + b"\r\n"), (1, b"$ ")]),
        (1883, [(0, b"\x10\x25\x00\x04MQTT\x04\xc2\x00\x3c\x00\x04dev1"
                   b"\x00\x04alex\x00\x0b" + C), (1, b"\x20\x02\x00\x00")]),
        (80, [(0, b"GET / HTTP/1.1\r\nHost: a.example\r\n" + auth[:24]),
              (0, auth[24:] + b"\r\n\r\n"),
              (1, b"HTTP/1.1 200 OK\r\n\r\n")]),
        (8000, [(0, b"GET / HTTP/1.1\r\nHost: a.example\r\n" + auth +
                 b"\r\nCookie: sid=" + C + b"\r\n\r\n"),
                (1, b"HTTP/1.1 200 OK\r\n\r\n")]),
        # (review) Expect: 100-continue puts the form in a piece of its own
        (80, [(0, b"POST /signin HTTP/1.1\r\nHost: a.example\r\n"
                 b"Expect: 100-continue\r\nContent-Length: 30\r\n\r\n"),
              (1, b"HTTP/1.1 100 Continue\r\n\r\n"),
              (0, b"user=alex&password=" + C),
              (1, b"HTTP/1.1 302 Found\r\n\r\n")]))
    forms = [C, base64.b64encode(b"alex:" + C), auth[24:].strip()]
    for port, turns in cases:
        sb = ScenarioBuilder()
        sb._tcp_talk(sb.ME, "198.51.100.80", sb.GW[1], 43100, port, turns)
        rows = []
        for i, (raw, ts, lt) in enumerate(sb.frames):
            d = fast_decode(raw, ts, lt)
            d.update(no=i + 1, raw=raw, linktype=lt, flow_id=1)
            rows.append(d)
        res = follow_stream(rows, 1)
        assert res.sensitive(), port
        for hexmode in (False, True):
            txt = stream_text(res, True, hexmode)
            blob = txt.encode()
            if hexmode:
                blob = b"".join(bytes.fromhex(m.group(1).replace(" ", ""))
                                for m in (re.match(
                                    r"^[0-9a-f]{4,8}  ((?:[0-9a-f]{2} )*"
                                    r"[0-9a-f]{2})", ln)
                                    for ln in txt.splitlines()) if m)
            assert not any(f in blob for f in forms), (port, txt)
        assert any(f in b"".join(c[2] or b"" for c in res.chunks)
                   for f in forms)        # the raw view still has them


@self_test()
def t_lg08_roaming_reidentifies(ctx):
    """5.3.4 (LG-08): a new router or Wi-Fi name under a running capture
    stops scanning and identifies the network again; the scanner asks
    before every sweep; no /24 guess when the subnet is unknown."""
    calls = []
    app = types.SimpleNamespace(
        network_fp="abc", data_mode="live", wifi=types.SimpleNamespace(
            last={"ssid": "Home"}),
        model=types.SimpleNamespace(gateway_ip="192.168.1.1"),
        _stop_lan_scanner=lambda: calls.append("stop"),
        _identify_network_async=lambda: calls.append("identify"),
        active_mode=lambda: True)
    reg = types.SimpleNamespace(by_key={}, ip_to_key={})
    app.model.registry = reg
    for name in ("_network_signature", "_check_roam", "_scan_still_allowed"):
        setattr(app, name, types.MethodType(getattr(MiniWireshark, name),
                                            app))
    app._net_signature = ("", "Home")
    assert not app._check_roam(1000.0) and calls == []
    app.wifi.last = {"ssid": "Airport-Free-WiFi"}
    assert app._check_roam(1001.0) and calls == ["stop", "identify"]
    assert not app._scan_still_allowed()          # paused until known
    assert not app._check_roam(1002.0)            # once, not every tick
    sc = LanScanner("lo", "192.0.2.10", allowed=lambda: False)
    sc._sweep()
    assert sc.sweeps == 0
    real = conf.route.routes if conf is not None else None
    try:
        if conf is not None:
            conf.route.routes = []
        assert local_subnet_for("eth9", "10.9.8.7") is None
    finally:
        if conf is not None:
            conf.route.routes = real


@self_test()
def t_m2_history_two_copies_and_clock(ctx):
    """5.3.4: a locked history file is busy, not damaged (CO-08); two
    runs never share a session id (CO-09); a clock that jumps a year
    ahead during a run doesn't prune everything (CO-15)."""
    path = ctx.path("lock.sqlite3")
    st = Store(path, session_id=1)
    assert st.write_observations([(1, time.time(), "dns_answer", "a", {}, 1)])
    assert st.flush_now(10)
    st.stop(5)
    other = sqlite3.connect(path, timeout=1, isolation_level=None)
    other.execute("PRAGMA journal_mode=DELETE")
    other.execute("BEGIN EXCLUSIVE")
    try:
        probe = Store.__new__(Store)
        probe.path, probe.recovered = path, ""
        real = sqlite3.connect
        sqlite3.connect = lambda p, timeout=5, **kw: real(p, timeout=0.2,
                                                           **kw)
        try:
            probe._check_integrity()
        finally:
            sqlite3.connect = real
        assert probe.recovered == "", probe.recovered
        assert not [f for f in os.listdir(os.path.dirname(path))
                    if ".corrupt-" in f and f.startswith("lock.")]
    finally:
        other.execute("ROLLBACK")
        other.close()
    real_pid, real_time = os.getpid, time.time
    try:
        time.time = lambda: 1761600000.25      # the same millisecond
        os.getpid = lambda: 4242
        a = new_session_id()
        os.getpid = lambda: 4243
        b = new_session_id()
    finally:
        os.getpid, time.time = real_pid, real_time
    assert a != b and a // 1000 == b // 1000 == 1761600000250, (a, b)
    st = Store(ctx.path("clock.sqlite3"), session_id=5)
    assert st.write_observations([(1, time.time(), "dns_answer", "a", {}, 1)])
    assert st.flush_now(10)
    st._wall0 -= 365 * 86400               # the clock jumped a year ahead
    assert st.prune(30) is False
    assert st.counts()["observations"] == 1
    st._wall0 += 365 * 86400
    st.stop(5)
    # (review) the clock is already a year ahead when the next run starts
    real_time = time.time
    try:
        time.time = lambda: real_time() + 365 * 86400
        st2 = Store(ctx.path("clock.sqlite3"), session_id=6)
        st2.prune(30)
        assert st2.flush_now(10)
    finally:
        time.time = real_time
    assert st2.counts()["observations"] == 1, st2.counts()
    st2.stop(5)


@self_test()
def t_m2_settings_and_stores_survive_damage(ctx):
    """5.3.4 (CO-06, CO-07): a settings file that can't be opened is left
    alone (not replaced by defaults); a damaged one is only reset when the
    .damaged copy really exists. A damaged labels or networks file loads
    its backup and is kept aside; the next save doesn't erase the rest."""
    path = ctx.path("cfg-locked.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump({"appearance": {"theme": "Dark"}}, f)
    real_open = open

    def locked(p, *a, **kw):
        if p == path:
            raise PermissionError(13, "locked by another program")
        return real_open(p, *a, **kw)
    builtins = __builtins__ if isinstance(__builtins__, dict) else \
        __builtins__.__dict__
    builtins["open"] = locked
    try:
        c = AppConfig(path=path)
    finally:
        builtins["open"] = real_open
    assert c.read_only and "couldn't be read" in c.warning
    assert c.save() is False
    assert read_json(path)["appearance"]["theme"] == "Dark"
    bad = ctx.path("cfg-bad.json")
    with open(bad, "w", encoding="utf-8") as f:
        f.write('{"appearance": {"theme": "Da')
    c = AppConfig(path=bad)
    assert os.path.exists(bad + ".damaged") and "copy was kept" in c.warning
    kd = ctx.path("known.json")
    k = KnownDevicesStore(kd)
    for i in range(30):
        k.data[f"aa:bb:cc:00:00:{i:02x}"] = {"alias": f"Device {i}"}
    k.save()
    k.data["aa:bb:cc:00:00:00"]["alias"] = "Renamed"
    k.save()                                   # .bak holds the 30 labels
    with open(kd, "r+", encoding="utf-8") as f:
        f.truncate(40)
    k2 = KnownDevicesStore(kd)
    assert k2.problem == "restored" and len(k2.data) == 30, len(k2.data)
    assert [f for f in os.listdir(os.path.dirname(kd))
            if f.startswith("known.json.damaged-")]
    k2.data["aa:bb:cc:00:00:01"]["alias"] = "One change"
    k2.save()
    assert len(read_json(kd)) == 30
    assert store_problem_text("restored", "x") and \
        not store_problem_text("", "x")


@self_test()
def t_os07_second_copy_keeps_off_the_journal(ctx):
    """5.3.4 (OS-07): a journal whose writer is still running (alive and
    beating in the last 2 minutes, even idle) is not claimed as
    "interrupted" by a second copy; once the writer is gone it is."""
    folder = ctx.path("os07")
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, "journal.mwsession.json")
    other = os.getppid() or 1
    with open(path, "w", encoding="utf-8") as f:
        f.write("{}")
    atomic_write_json(path + ".sha256", {"journal": 2, "pid": other,
                                         "saved_at": time.time()})
    old = time.time() - 600
    os.utime(path, (old, old))
    assert journal_owner(path) == other
    assert claim_interrupted_journal(path) == ""
    assert os.path.exists(path)
    os.utime(path + ".sha256", (old, old))     # it stopped beating
    got = claim_interrupted_journal(path)
    assert got and got != path and not os.path.exists(path), got


