def bench_components():
    """Components Center costs: load time and memory for each list at its
    real-world size (synthetic contents, no network), lookup speed, and
    the teach-once matcher at its 300-entry cap."""
    import tracemalloc
    out = {}
    tmp = tempfile.mkdtemp(prefix="mw-bench-cc-")
    rnd = random.Random(7)

    def pub_ip():
        while True:
            ip = ".".join(str(rnd.randint(1, 223)) if i == 0 else
                          str(rnd.randint(0, 255)) for i in range(4))
            if is_public_ip(ip):
                return ip
    feodo = os.path.join(tmp, "feodo.txt")
    with open(feodo, "w", encoding="utf-8") as f:
        f.write("################\n# abuse.ch Feodo Tracker\n"
                "# Last updated: 2026-10-19 00:00:00 UTC\n#\n")
        for _ in range(1000):
            f.write(pub_ip() + "\n")
    drop = os.path.join(tmp, "drop.json")
    with open(drop, "w", encoding="utf-8") as f:
        seen = set()
        while len(seen) < 1500:
            net = ipaddress.ip_network(pub_ip() + "/" +
                                       str(rnd.randint(16, 24)), strict=False)
            seen.add(net)
        nets = sorted(seen)
        # DROP ranges do not overlap: keep only the first of nested ones
        kept, end = [], -1
        for n in nets:
            if int(n.network_address) > end:
                kept.append(n)
                end = int(n.broadcast_address)
        for i, n in enumerate(kept):
            f.write(json.dumps({"cidr": str(n), "sblid": f"SBL{i}",
                                "rir": "x"}) + "\n")
        f.write(json.dumps({"type": "metadata", "timestamp": 1760000000,
                            "size": len(kept)}) + "\n")
    for key, fn, path in (("feodo", load_feodo, feodo),
                          ("drop", load_drop, drop)):
        tracemalloc.start()
        t0 = time.perf_counter()
        rl = fn(path)
        out[f"cc_{key}_load_ms"] = (time.perf_counter() - t0) * 1000
        out[f"cc_{key}_entries"] = len(rl)
        out[f"cc_{key}_mem_kb"] = tracemalloc.get_traced_memory()[0] / 1024
        tracemalloc.stop()
        probes = [pub_ip() for _ in range(20000)]
        t0 = time.perf_counter()
        for ip in probes:
            rl.lookup(ip)
        out[f"cc_{key}_lookup_us"] = (time.perf_counter() - t0) / \
            len(probes) * 1e6
    t0 = time.perf_counter()
    for i in range(20000):
        explain_port(1 + (i * 7919) % 65535)
    out["cc_port_explain_us"] = (time.perf_counter() - t0) / 20000 * 1e6
    lt = LearnedTypes(path=os.path.join(tmp, "learned.json"))
    lt.save = lambda: None
    for i in range(LearnedTypes.MAX):
        lt.learn(DeviceRecord(key=f"k{i}", mac=f"00:1b:{i // 256:02x}:"
                                               f"{i % 256:02x}:00:01",
                              dhcp_params=f"1,3,6,{i % 40}",
                              services={f"_svc{i % 25}._tcp"}), "Printer")
    probe = DeviceRecord(key="probe", mac="00:1b:00:07:00:02",
                         dhcp_params="1,3,6,7", services={"_svc7._tcp"})
    t0 = time.perf_counter()
    for _ in range(500):
        lt.match(probe)
    out["cc_learned_match_us"] = (time.perf_counter() - t0) / 500 * 1e6
    shutil.rmtree(tmp, ignore_errors=True)
    return out


BENCH_EXTRA.append(bench_components)


def bench_dissect():
    """Own dissector and stream reassembly speed on the scripted corpus."""
    frames = ScenarioBuilder().home_network() + \
        ScenarioBuilder(t0=SCENARIO_T0 + 5000).protocol_tour()
    t0 = time.perf_counter()
    n = 0
    while time.perf_counter() - t0 < 1.0:
        for raw, _ts, lt in frames:
            dissect(raw, lt)
        n += len(frames)
    out = {"dissect_us_per_pkt": (time.perf_counter() - t0) / n * 1e6}
    corpus = _stream_corpus() * 1
    t0 = time.perf_counter()
    k = 0
    while time.perf_counter() - t0 < 1.0:
        tr, _df = reassemble_frames(corpus)
        tr.flush()
        k += len(corpus)
    out["reassembly_us_per_pkt"] = (time.perf_counter() - t0) / k * 1e6
    built = 0
    t0 = time.perf_counter()
    while time.perf_counter() - t0 < 0.5:
        built += len(ScenarioBuilder().home_network())
    out["builder_frames_per_s"] = built / (time.perf_counter() - t0)
    return out


BENCH_EXTRA.append(bench_dissect)


def bench_deep(n=None):
    """Full Power throughput: the same replay through the deep pass in a
    thread and in worker processes (the plan ships processes only if they
    beat the thread by at least 30 %)."""
    n = n or int(os.environ.get("MW_BENCH_DEEP", "40000"))
    frames = ScenarioBuilder().bulk_streams(n)
    rows = []
    for i, (raw, ts, lt) in enumerate(frames):
        rows.append({"no": i + 1, "time": ts, "linktype": lt, "raw": raw,
                     "transport": "TCP", "tcp_flags": 0x10,
                     "payload_len": len(raw) - 54, "src_ip": "", "dst_ip": "",
                     "sport": i % 200, "dport": 443})
    out = {}
    runners = [("thread", False)]
    if (os.cpu_count() or 1) > 1:
        runners.append(("process", True))
    for name, proc in runners:
        e = DeepEngine()
        e.QUEUE_CAP = len(rows) + 1
        e.configure("Full Power", cores=max(1, (os.cpu_count() or 2) - 1),
                    policy="Off", prefer_process=proc)
        e._ensure_backend()
        t0 = time.perf_counter()
        for d in rows:
            e.offer(d, d["no"])
        e.drain(600)
        out[f"deep_{name}_pkts_per_s"] = e.done / (time.perf_counter() - t0)
        e.stop()
    if "deep_process_pkts_per_s" in out:
        out["deep_process_gain_pct"] = 100.0 * (
            out["deep_process_pkts_per_s"] /
            out["deep_thread_pkts_per_s"] - 1)
    return out


BENCH_EXTRA.append(bench_deep)

