@self_test()
def t_upnp_audit_fake_router(ctx):
    """The router check against a fake router on this computer: finds the
    forwarding rules, and every request it made is in the ledger."""
    import http.server
    rules = [("TCP", "32400", "192.168.1.70", "32400", "Plex"),
             ("TCP", "3389", "192.168.1.50", "3389", "RDP")]
    holder = {}

    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def do_GET(self):
            body = ("<?xml version='1.0'?><root xmlns='urn:schemas-upnp-org"
                    ":device-1-0'><device><serviceList><service><serviceType>"
                    "urn:schemas-upnp-org:service:WANIPConnection:1"
                    "</serviceType><controlURL>/ctl</controlURL></service>"
                    "</serviceList></device></root>").encode()
            self.send_response(200)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            data = self.rfile.read(int(self.headers["Content-Length"]))
            i = int(re.search(rb"<NewPortMappingIndex>(\d+)<", data).group(1))
            holder.setdefault("posts", []).append(i)
            if i >= len(rules):
                self.send_response(500)
                self.end_headers()
                return
            pr, ext, cl, inn, desc = rules[i]
            body = (f"<s:Envelope xmlns:s='x'><s:Body><u:R xmlns:u='y'>"
                    f"<NewProtocol>{pr}</NewProtocol><NewExternalPort>{ext}"
                    f"</NewExternalPort><NewInternalClient>{cl}"
                    f"</NewInternalClient><NewInternalPort>{inn}"
                    f"</NewInternalPort><NewEnabled>1</NewEnabled>"
                    f"<NewPortMappingDescription>{desc}"
                    f"</NewPortMappingDescription></u:R></s:Body>"
                    f"</s:Envelope>").encode()
            self.send_response(200)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
    httpd = http.server.HTTPServer(("127.0.0.1", 0), H)
    hport = httpd.server_address[1]
    threading.Thread(target=httpd.serve_forever, daemon=True).start()
    udp = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
    udp.bind(("127.0.0.1", 0))
    uport = udp.getsockname()[1]

    def responder():
        try:
            data, addr = udp.recvfrom(2048)
            holder["msearch"] = data
            udp.sendto((f"HTTP/1.1 200 OK\r\nLOCATION: http://127.0.0.1:"
                        f"{hport}/desc.xml\r\nST: x\r\n\r\n").encode(), addr)
        except OSError:
            pass
    threading.Thread(target=responder, daemon=True).start()
    n0 = len(LEDGER.snapshot("upnp"))
    try:
        res = upnp_audit("127.0.0.1", timeout=2.0, port=uport)
    finally:
        httpd.shutdown()
        udp.close()
    assert not res.get("error"), res
    maps = res["mappings"]
    assert [(m_["ExternalPort"], m_["InternalClient"]) for m_ in maps] == \
        [("32400", "192.168.1.70"), ("3389", "192.168.1.50")], maps
    assert b"InternetGatewayDevice" in holder["msearch"]
    sent = LEDGER.snapshot("upnp")[n0:]
    kinds = [e["kind"] for e in sent]
    # exactly: 1 discovery, 1 description, one per rule + the final "no
    # more" answer — nothing else
    assert kinds.count("ssdp") == 1 and len(sent) == 1 + 1 + 3, kinds
    assert all(e["dest"] == "127.0.0.1" or e["dest"].startswith(
        "127.0.0.1:") for e in sent), sent
    # an answer that points away from the router is not followed
    bad = upnp_parse_description("<root/>", "http://127.0.0.1/")
    assert bad is None


def _fake_helper(kind, password="s3cret-Pw!", user="admin"):
    """A recorded-fixture Pi-hole v6 / AdGuard Home on 127.0.0.1."""
    import http.server
    S = ScenarioBuilder
    t0 = time.time() - 120
    calls = []
    lookups = [(t0 + 1, S.PHONE[0], "Alex-iPhone.lan", "news.example.org",
                "FORWARDED"),
               (t0 + 2, S.PHONE[0], "Alex-iPhone.lan", "ads.example.net",
                "GRAVITY"),
               (t0 + 3, S.TV[0], "tv.lan", "video.example.net", "CACHE"),
               (t0 + 4, "192.168.1.199", "", "hidden.example.com",
                "FORWARDED")]

    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def _send(self, code, obj=None):
            body = json.dumps(obj).encode() if obj is not None else b""
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _authed(self):
            if kind == "pihole":
                return self.headers.get("X-FTL-SID") == "SID-123"
            want = "Basic " + base64.b64encode(
                f"{user}:{password}".encode()).decode()
            return self.headers.get("Authorization") == want

        def do_POST(self):
            calls.append(("POST", self.path))
            n = int(self.headers.get("Content-Length") or 0)
            data = json.loads(self.rfile.read(n) or b"{}")
            if self.path == "/api/auth" and kind == "pihole":
                if data.get("password") == password:
                    return self._send(200, {"session": {
                        "valid": True, "totp": False, "sid": "SID-123",
                        "csrf": "x", "validity": 1800}, "took": 0.01})
                return self._send(401, {"error": {"key": "unauthorized"}})
            self._send(404, {})

        def do_DELETE(self):
            calls.append(("DELETE", self.path))
            self._send(204)

        def do_GET(self):
            calls.append(("GET", self.path))
            if not self._authed():
                return self._send(401, {"error": {"key": "unauthorized"}})
            p = self.path
            if kind == "pihole" and p.startswith("/api/info/version"):
                return self._send(200, {"version": {"core": {"local": {
                    "version": "v6.1"}}}})
            if kind == "pihole" and p.startswith("/api/queries"):
                q = urllib.parse.parse_qs(urllib.parse.urlsplit(p).query)
                frm = float(q.get("from", ["0"])[0])
                rows = [{"id": i, "time": ts, "type": "A", "domain": dom,
                         "status": st, "client": {"ip": ip, "name": nm},
                         "reply": {"type": "IP", "time": 0.012},
                         "dnssec": "UNKNOWN", "upstream": "1.1.1.1#53"}
                        for i, (ts, ip, nm, dom, st) in enumerate(lookups)
                        if ts >= frm]
                return self._send(200, {"queries": rows[::-1],
                                        "cursor": None,
                                        "recordsTotal": len(rows)})
            if kind == "pihole" and p.startswith("/api/network/devices"):
                return self._send(200, {"devices": [{
                    "id": 1, "hwaddr": S.TV[1], "interface": "eth0",
                    "firstSeen": 1, "lastQuery": int(t0), "numQueries": 9,
                    "macVendor": "Google", "ips": [{"ip": S.TV[0],
                                                    "name": "livingroom-tv",
                                                    "lastSeen": 1,
                                                    "nameUpdated": 1}]}]})
            if kind == "adguard" and p.startswith("/control/status"):
                return self._send(200, {"version": "v0.107.52",
                                        "running": True})
            if kind == "adguard" and p.startswith("/control/querylog"):
                rows = [{"client": ip, "client_info": {"name": nm,
                                                       "whois": {},
                                                       "disallowed": False,
                                                       "disallowed_rule": ""},
                         "elapsedMs": "12.5",
                         "question": {"class": "IN", "name": dom,
                                      "type": "A"},
                         "reason": "FilteredBlackList" if st == "GRAVITY"
                         else "NotFilteredNotFound", "status": "NOERROR",
                         "time": time.strftime("%Y-%m-%dT%H:%M:%S",
                                               time.gmtime(ts)) + ".5Z"}
                        for ts, ip, nm, dom, st in lookups][::-1]
                return self._send(200, {"data": rows, "oldest": ""})
            if kind == "adguard" and p.startswith("/control/clients"):
                return self._send(200, {"clients": [{
                    "name": "livingroom-tv", "ids": [S.TV[0]]}]})
            self._send(404, {})
    httpd = http.server.HTTPServer(("127.0.0.1", 0), H)
    threading.Thread(target=httpd.serve_forever, daemon=True).start()
    return httpd, f"http://127.0.0.1:{httpd.server_address[1]}", calls, t0


@self_test()
def t_connectors_fixtures(ctx):
    """Pi-hole v6 and AdGuard Home against recorded API answers: login,
    read-only requests, Reported evidence beside observed, secrets never
    shown."""
    if not ctx.scapy_ok:
        return "skip"
    vault = CredentialVault(ctx.path(f"vault_{uuid.uuid4().hex[:6]}.json"))
    vault.backend = "file"
    pw = "s3cret-Pw!"
    for kind in ("pihole", "adguard"):
        httpd, url, calls, t0 = _fake_helper(kind, pw)
        try:
            cid = f"c-{kind}"
            spec = {"id": cid, "kind": kind, "name": CONNECTOR_KINDS[
                kind].title, "url": url, "username": "admin"}
            vault.set(cid, "wrong-password")
            c = CONNECTOR_KINDS[kind](spec, vault)
            try:
                c.test()
                raise AssertionError("a wrong password was accepted")
            except ConnectorError as e:
                assert e.kind == "auth", e
            vault.set(cid, pw)
            c = CONNECTOR_KINDS[kind](spec, vault)
            assert "Connected" in c.test()
            res = c.fetch(t0 - 10)
            c.close()
            assert len(res["lookups"]) == 4, res["lookups"]
            blocked = [x for x in res["lookups"] if x["blocked"]]
            assert [x["domain"] for x in blocked] == ["ads.example.net"]
            # read-only: nothing but logins, GETs and the logout
            assert all(m_ == "GET" or (m_, p_) in (("POST", "/api/auth"),
                                                    ("DELETE", "/api/auth"))
                       for m_, p_ in calls), calls
            m = scenario_model(ctx.cfg(), ctx.frames())
            obs_lookups = m.dns.queries
            rep = m.apply_reported(c.name, res)
            S = ScenarioBuilder
            ph = m.device_for(S.PHONE[0], S.PHONE[1])
            w = m.websites.get("news.example.org")
            assert w and w.ties[ph.key][0] == AS_REPORTED, w and w.ties
            assert c.name in w.sources
            assert "ads.example.net" not in m.websites    # blocked ≠ visit
            assert rep["blocked"] == 1 and "192.168.1.199" in \
                rep["unseen_clients"]
            # an observed connection stays stronger than a report
            vid = m.websites.get("video.example.net")
            tv = m.device_for(S.TV[0], S.TV[1])
            assert ASSOC_RANK[vid.ties[tv.key][0]] >= \
                ASSOC_RANK[AS_REPORTED]
            assert m.dns.queries == obs_lookups    # never summed
            rows = coverage_rows(m)
            row = next(r for r in rows if r[0].startswith("Lookups reported"))
            assert "devices (Reported)" in row[1] and row[2] == LV_REPORTED
            if kind == "pihole":
                assert tv.hostname == "livingroom-tv" and \
                    tv.hostname_source == "connector"
                dv = m.registry.touch("192.168.1.150", "02:aa:bb:cc:dd:ee",
                                      "arp_reply", "test")
                m.apply_reported(c.name, {"devices": [{
                    "ips": ["192.168.1.150"], "names": ["quiet-box"]}]})
                claims = dict((cl[0], cl) for cl in device_claims(m, dv))
                assert dv.display_name() == "quiet-box"
                assert claims["Name"][2] == LV_REPORTED, claims["Name"]
        finally:
            httpd.shutdown()
    # secrets never appear in logs, copied details or bundles
    assert pw in _SECRETS
    assert pw not in mask_sensitive(f"password={pw} 192.168.1.5")
    assert pw not in scrub_secrets(f"oops {pw}")
    rec = logging.LogRecord("x", logging.INFO, "f", 1, "pw %s", (pw,), None)
    _SecretFilter().filter(rec)
    assert pw not in rec.getMessage()
    raw = open(vault.path, encoding="utf-8").read()
    assert pw not in raw                      # not stored as plain text
    if not IS_WINDOWS:
        assert os.stat(vault.path).st_mode & 0o077 == 0
    vault.delete("c-pihole")
    assert vault.get("c-pihole") is None


@self_test()
def t_connector_manager_and_kill_switch(ctx):
    httpd, url, _calls, t0 = _fake_helper("pihole")
    try:
        vault = CredentialVault(ctx.path(f"v_{uuid.uuid4().hex[:6]}.json"))
        vault.backend = "file"
        vault.set("c1", "s3cret-Pw!")
        got = []
        mgr = ConnectorManager([{"id": "c1", "kind": "pihole", "url": url,
                                 "name": "Pi-hole"}], vault,
                               lambda c, r: got.append(r))
        res = mgr.poll_once("c1")
        assert res and got and mgr.status["c1"]["state"] == "ok"
        assert mgr.cursor["c1"] > t0
        again = mgr.poll_once("c1")              # only what's new
        assert again is not None and again["lookups"] == []
        was = LEDGER.killed
        LEDGER.killed = True
        try:
            mgr.cursor.pop("c1")
            assert mgr.poll_once("c1") is None
            assert mgr.status["c1"]["state"] == "refused"
        finally:
            LEDGER.killed = was
        n = sum(1 for e in LEDGER.snapshot("connector"))
        assert n >= 3
        mgr.stop()
    finally:
        httpd.shutdown()


@self_test()
def t_narratives_cannot_overclaim(ctx):
    """The M11 gate: a sentence never states a claim above its evidence
    level, and a sentence with missing data is not written at all."""
    t = narrate("connections", device=C("TV", LV_OBSERVED),
                count=C(14, LV_OBSERVED),
                destination=C("video.example.net", LV_OBSERVED),
                duration=C("2 minutes", LV_OBSERVED))
    assert t == "◉ TV made 14 connections to video.example.net over " \
                "2 minutes.", t
    t = narrate("connections", device=C("TV", LV_OBSERVED),
                count=C(14, LV_OBSERVED),
                destination=C("video.example.net", LV_CORRELATED),
                duration=C("2 minutes", LV_OBSERVED))
    assert t.startswith("◎ TV appears to have made"), t
    t = narrate("connections", device=C("TV", LV_REPORTED),
                count=C(3, LV_REPORTED), destination=C("x.example",
                                                      LV_REPORTED),
                duration=C("1 hour", LV_OBSERVED))
    assert "was reported to make" in t and t.startswith("◈"), t
    # an Inferred claim in a slot that only takes Observed/Reported facts
    for key, slot in (("connections", "count"), ("program", "program"),
                      ("periodic", "repeats"), ("bandwidth", "amount")):
        tpl = NARRATIVES[key]
        claims = {s_: C("x", next(iter(lv))) for s_, lv in
                  tpl.slots.items()}
        claims[slot] = C("x", LV_INFERRED)
        try:
            tpl.render(**claims)
            raise AssertionError(f"{key}.{slot} accepted an Inferred claim")
        except NarrativeRefused:
            pass
    assert narrate("connections", device=C("TV", LV_OBSERVED),
                   count=C(None, LV_OBSERVED),
                   destination=C("x", LV_OBSERVED),
                   duration=C("1 s", LV_OBSERVED)) is None
    try:
        narrate("shape", shape=C("streaming", LV_OBSERVED),
                detail=C("6 Mbit/s", LV_OBSERVED))
        raise AssertionError("a flow-shape guess was stated as observed")
    except NarrativeRefused:
        pass
    assert narrate("shape", shape=C("streaming", LV_INFERRED),
                   detail=C("6 Mbit/s", LV_OBSERVED)).startswith("◌")


@self_test()
def t_periodicity_and_episodes(ctx):
    rng = random.Random(4)
    starts = [1000 + i * 60 + rng.uniform(-2, 2) for i in range(15)]
    got = detect_periodic(starts)
    assert got and 55 < got[0] < 65 and got[1] == 14, got
    assert detect_periodic([1000 + rng.uniform(0, 3000) for _ in
                            range(15)]) is None
    assert detect_periodic(starts[:8]) is None             # too few
    assert human_period(60) == "60 s" and human_period(300) == "5 min"
    if ctx.scapy_ok:
        S = ScenarioBuilder
        b = S()
        b.t = ctx.frames()[-1][1] + 5
        for i in range(13):                 # the plug phones home each 60 s
            b.t += 60
            b.tls(S.PLUG, "cloud.example.net", "52.1.2.3", size=600)
        m = scenario_model(ctx.cfg(), ctx.frames() + b.frames)
        per = periodic_findings(m)
        plug = m.device_for(S.PLUG[0], S.PLUG[1])
        mine = [r for r in per if r[0] == plug.key]
        assert mine and "about every 60 s" in mine[0][4], per
        assert mine[0][4].startswith("◎")        # Correlated, not Observed
    ev = ([{"when": 100 + i, "kind": "device back", "text": f"d{i} back",
            "severity": "INFO"} for i in range(4)] +
          [{"when": 1000, "kind": "website", "text": "First visit",
            "severity": "INFO", "device": "a"}] +
          [{"when": 3000 + i * 5, "kind": "device left",
            "text": f"x{i} left", "severity": "INFO"} for i in range(3)])
    eps = build_episodes(ev)
    assert [e["rule"] for e in eps] == ["reconnect_wave", "drop_wave"], eps
    assert "4 devices (re)joined" in eps[0]["headline"]
    assert eps[0]["level"] == LV_INFERRED and "router" in eps[0]["cause"]


@self_test()
def t_investigations_reach_planted_cause(ctx):
    base = {"vantage": "endpoint", "dns_n": 40, "dns_median_ms": 20,
            "dns_fail_rate": 0.0, "rtt_n": 20, "rtt_median_ms": 25,
            "tcp_packets": 5000, "retrans_pct": 0.005,
            "health": {"gateway_ok": True, "gateway_ms": 3},
            "wifi": {"rssi": -52}}

    def top(**over):
        f = dict(base, **over)
        return investigate_slow(f)[0]
    h = top(wifi={"rssi": -80}, retrans_pct=0.09)
    assert h["key"] == "wifi" and h["status"] == "Likely", h
    h = top(dns_median_ms=1200)
    assert h["key"] == "dns" and h["status"] == "Likely", h
    h = top(health={"gateway_ok": False})
    assert h["key"] == "router", h
    h = top(rtt_median_ms=340)
    assert h["key"] == "isp" and h["status"] == "Likely", h
    h = top(this_pc_top=[("steam.exe (pid 9)", 9e6)])
    assert h["key"] == "local_hog" and "steam.exe" in h["title"], h
    h = top()
    assert h["key"] == "cant_tell", h          # nothing visible explains it
    # 5.3.4 (IP-002): the capture's own drops are not blamed on the path
    h = top(retrans_pct=0.09, capture_drop_pct=0.05)
    assert not (h["key"] == "loss" and h["status"] == "Likely"), h
    hyps = investigate_slow(dict(base, retrans_pct=0.09,
                                 capture_drop_pct=0.05))
    assert [x["status"] for x in hyps if x["key"] == "loss"] == \
        ["Can't tell"], hyps
    assert top(retrans_pct=0.09)["key"] == "loss"
    hyps = investigate_slow(dict(base, zero_win=12))
    assert any(x["key"] == "slow_reader" and "slow to read" in x["title"]
               for x in hyps), hyps
    hyps = investigate_slow(dict(base))
    assert any(x["key"] == "other_hog" and x["status"] == "Can't tell"
               for x in hyps)                  # blind spot stated
    # evidence lines that use narratives carry their level glyph
    h = top(this_pc_top=[("steam.exe (pid 9)", 9e6)])
    assert h["for"][0].startswith("◉")
    # bandwidth: honest about the vantage point
    bw = investigate_bandwidth({"devices": [("Laptop", 9e6, LV_OBSERVED)],
                                "vantage": "endpoint", "unattributed": 0})
    assert "Can't tell from here" in bw["conclusion"]
    bw = investigate_bandwidth({"devices": [("TV", 90e6, LV_OBSERVED),
                                            ("Phone", 5e6, LV_OBSERVED)],
                                "vantage": "mirror", "unattributed": 30e6,
                                "window_text": "10 min"})
    assert bw["conclusion"].startswith("TV is using the most"), bw
    assert "couldn't be tied" in bw["conclusion"]
    assert bw["rows"][0].startswith("◉ TV used")
    # on a scripted replay: slow DNS answers are the planted cause
    if not ctx.scapy_ok:
        return
    S = ScenarioBuilder
    fr = []
    t = ctx.frames()[-1][1] + 5
    for i in range(12):
        q = Ether(src=S.ME[1], dst=S.GW[1]) / IP(src=S.ME[0],
                                                  dst=S.GW[0]) / \
            UDP(sport=50000 + i, dport=53) / DNS(id=900 + i, rd=1, qd=DNSQR(
                qname=f"s{i}.example.com"))
        a = Ether(src=S.GW[1], dst=S.ME[1]) / IP(src=S.GW[0], dst=S.ME[0]) \
            / UDP(sport=53, dport=50000 + i) / DNS(
                id=900 + i, qr=1, qd=DNSQR(qname=f"s{i}.example.com"),
                an=DNSRR(rrname=f"s{i}.example.com", rdata="93.184.215.14"))
        fr += [(bytes(q), t + i * 2, 1), (bytes(a), t + i * 2 + 1.3, 1)]
    m = scenario_model(ctx.cfg(), ctx.frames() + fr)
    f = slow_facts(m, wifi={"rssi": -50},
                   health={"gateway_ok": True, "gateway_ms": 2})
    h = investigate_slow(f)[0]
    assert h["key"] == "dns" and h["status"] == "Likely", (h, f["dns_median_ms"])


@self_test()
def t_colorblind_modes(ctx):
    """Each colour-blind mode keeps good / warning / danger far apart for
    that kind of vision (simulated) and for normal vision, keeps text
    readable, and palettes stay one-to-one so switching is lossless."""
    for (mode, dark), trip in CVD_TRIPLES.items():
        base = "Dark" if dark else "Light"
        for hc in (False, True):
            th = THEMES[palette_name(base, hc, mode)]
            cols = [th["good_fg"], th["warn_fg"], th["danger_fg"]]
            assert cols == list(trip) or hc, (mode, dark, cols)
            for vision in (mode, ""):
                worst = min(cvd_delta(a, b, vision) for i, a in
                            enumerate(cols) for b in cols[i + 1:])
                assert worst >= 25, (mode, dark, hc, vision, worst)
            for c in cols:
                assert wcag_contrast(c, th["tab_bg"]) >= 4.5, \
                    (mode, dark, hc, c, th["tab_bg"])
    # the default palette is the problem being solved: red/green collide
    light = THEMES["Light"]
    assert cvd_delta(light["warn_fg"], light["danger_fg"], "deutan") < 15
    for name, tbl in PALETTES.items():
        vals = list(tbl.values())
        assert len(vals) == len(set(vals)), f"{name} is not one-to-one"
    keys = set(THEMES["Light"])
    for name, th in THEMES.items():
        assert set(th) == keys, name
    assert set_colorblind_mode("Red-green — protanopia") == "protan"
    assert palette_name("Dark", True) == "Dark HC protan"
    assert set_colorblind_mode("Off") == "" and palette_name(
        "Light", False) == "Light"


@self_test()
def t_redaction_no_leaks(ctx):
    """Every original address, hardware address and name is replaced,
    consistently, and the pseudonyms come from documentation ranges."""
    if not ctx.scapy_ok:
        return "skip"
    m = scenario_model(ctx.cfg(), ctx.frames())
    S = ScenarioBuilder
    d = m.device_for(S.PHONE[0], S.PHONE[1])
    d.alias, d.notes = "Kid's phone", "bought in May"
    rows = inventory_rows(m)
    text = "\n".join(" | ".join(str(v) for v in r.values()) for r in rows)
    text += "\nDNS answer 93.184.215.14 for www.example.com; " \
            "fe80::21e:58ff:feaa:1; network “HomeNet”."
    red = Redactor(m)
    red._add_name("HomeNet", "networks")
    out = red.text(text)
    originals = set()
    for dev in m.registry.by_key.values():
        originals |= {dev.ip, dev.mac, dev.alias, dev.notes, dev.hostname,
                      dev.dhcp_hostname, dev.mdns_name}
        originals |= set(dev.ipv6)
    originals |= {"93.184.215.14", "HomeNet", "fe80::21e:58ff:feaa:1"}
    leaks = sorted(o for o in originals if o and len(o) >= 3 and
                   o.lower() in out.lower())
    assert not leaks, leaks
    assert "Kid's phone" not in out and "Device " in out
    # consistent: the same original always gets the same pseudonym
    assert red.text(S.PHONE[0]) == red.text(S.PHONE[0])
    assert red.text(S.PHONE[0]).startswith("192.0.2.")
    assert red.text("93.184.215.14").startswith("198.51.100.")
    assert red.text(S.PHONE[1]).startswith("02:00:00:00:")
    assert "www.example.com" in out                  # public names kept…
    red2 = Redactor(m, {"sites": True})
    assert "www.example.com" not in red2.text(text)  # …unless asked
    # turning an option off keeps that kind of data
    keep = Redactor(m, {"addresses": False}).text(S.PHONE[0])
    assert keep == S.PHONE[0]
    html_doc = inventory_html(rows)
    assert html_doc.startswith("<!doctype html>") and "@media print" in \
        html_doc and len(rows) == len(m.registry.by_key)
    assert S.PHONE[0] in html_to_preview_text(html_doc)


@self_test()
def t_ed25519_rfc8032(ctx):
    """RFC 8032 §7.1 test vectors 1 and 2, pure Python and library."""
    for sk, msg, pk, sig in (
            ("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
             b"", "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
             "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e0652249015"
             "55fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b"),
            ("4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
             b"\x72",
             "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c",
             "92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69d"
             "a085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00")):
        sk, pk, sig = bytes.fromhex(sk), bytes.fromhex(pk), bytes.fromhex(sig)
        assert ed25519_public_key(sk) == pk
        assert ed25519_sign(sk, msg) == sig
        assert _ed25519_verify_py(pk, msg, sig) and ed25519_verify(pk, msg,
                                                                  sig)
        bad = sig[:10] + bytes([sig[10] ^ 1]) + sig[11:]
        assert not _ed25519_verify_py(pk, msg, bad)
        assert not ed25519_verify(pk, msg + b"x", sig)


@self_test()
def t_signed_updates_and_packs(ctx):
    k_old, k_new, k_evil = os.urandom(32), os.urandom(32), os.urandom(32)
    trusted = {"new": ed25519_public_key(k_new).hex()}
    script = ("# MiniWireshark\nSCRIPT_VERSION = \"9.9.9\"\n"
              "def main():\n    pass\n" + "#" * 60000).encode()
    man = make_release_manifest(script, "9.9.9", {"old": k_old,
                                                  "new": k_new})
    # key rotation: signed by old + new, only the new one is trusted
    assert check_release(man, script, "4.0.0", trusted)["version"] == "9.9.9"

    def refused(fn, word):
        try:
            fn()
        except UpdateRefused as e:
            assert word in str(e), (word, str(e))
            return
        raise AssertionError(f"accepted ({word})")
    evil = make_release_manifest(script, "9.9.9", {"new": k_evil})
    refused(lambda: check_release(evil, script, "4.0.0", trusted),
            "isn't signed")
    refused(lambda: check_release(man, script[:-100], "4.0.0", trusted),
            "incomplete")
    tampered = script[:-1] + b"!"
    refused(lambda: check_release(man, tampered, "4.0.0", trusted),
            "fingerprint")
    old = make_release_manifest(script, "3.9.0", {"new": k_new})
    refused(lambda: check_release(old, script, "4.0.0", trusted),
            "downgrades")
    forged = dict(man, version="10.0.0")
    refused(lambda: check_release(forged, script, "4.0.0", trusted),
            "isn't signed")
    refused(lambda: check_release(man, script, "4.0.0", {}), "check-only")
    # data packs: signed ones apply, unsigned ones don't
    pack = sign_manifest({"kind": "datapack", "pack": "services",
                          "version": "1", "data": {"40404": "Test svc"}},
                         {"new": k_new})
    had = PORT_SERVICES.get(40404)
    try:
        assert apply_data_pack(pack, trusted) == 1
        assert PORT_SERVICES[40404] == "Test svc"
    finally:
        if had is None:
            PORT_SERVICES.pop(40404, None)
        else:
            PORT_SERVICES[40404] = had
    unsigned = dict(pack, signatures=[])
    refused(lambda: apply_data_pack(unsigned, trusted), "isn't signed")
    refused(lambda: apply_data_pack(man, trusted), "Not a MiniWireshark")
    # install + automatic rollback after starts that never confirm
    d = ctx.path(f"upd_{uuid.uuid4().hex[:6]}")
    os.makedirs(d)
    cur = os.path.join(d, "miniwireshark.py")
    with open(cur, "wb") as f:
        f.write(b"# MiniWireshark old\ndef main():\n    pass\n" + b"#" * 60000)
    marker = os.path.join(d, "marker.json")
    apply_self_update(script, "9.9.9", cur, marker)
    assert open(cur, "rb").read() == script and os.path.exists(marker)
    assert rollback_update_if_needed(script_path=cur, marker_path=marker) \
        == ""                                     # 1st start: wait
    rollback_update_if_needed(script_path=cur, marker_path=marker)
    msg = rollback_update_if_needed(script_path=cur, marker_path=marker)
    assert "restored" in msg and b"old" in open(cur, "rb").read()
    assert not os.path.exists(marker)
    # release tooling end to end
    kf = os.path.join(d, "release.key")
    with contextlib.redirect_stdout(io.StringIO()):
        assert release_tool(["--make-release-key", kf, "--key-id",
                             "t1"]) == 0
        assert release_tool(["--sign-release", cur, "--key", kf,
                             "--version", "9.9.10"]) == 0
    kd = json.load(open(kf))
    man2 = read_json(os.path.join(d, MANIFEST_NAME))
    body = verify_manifest(man2, {"t1": ed25519_public_key(
        bytes.fromhex(kd["secret"])).hex()})
    assert body["sha256"] == hashlib.sha256(open(cur, "rb").read()) \
        .hexdigest()


@self_test(slow=False)
def test_i18n_catalog(ctx):
    """Languages: the catalog parses cleanly and covers every fixed string
    of the setup window, Welcome Center, Settings, tour and banners."""
    assert _i18n_load() == [], _i18n_load()
    assert len(I18N["fr"]) == len(I18N["es"]) >= 700, len(I18N["fr"])
    must = []
    for p in SETTINGS_PAGES:
        must += [p.get("title"), p.get("blurb")]
        for sec in p.get("sections", []):
            must.append(sec.get("title"))
            for c in sec.get("controls", []):
                must += [c.get("label"), c.get("help")]
                if isinstance(c.get("choices"), (list, tuple)):
                    must += list(c["choices"])
    must += list(STRINGS["en"].values())
    for q in QUICK_START:
        must += [q[0], q[1], q[3]]
    for _icon, title, text in LoaderWindow.WHATS_NEW:
        must += [title, text]
    must += list(RuntimeManager.STAGES) + [v for _k, v in REPAIR_STEPS]
    must += list(DATA_MODE_TEXT.values())
    tech = {"DNS", "MB", "ms", "MiniWireshark"}
    for loc in ("fr", "es"):
        missing = sorted({s for s in must if isinstance(s, str) and s and
                          re.sub(r"^[^A-Za-z]+", "", s).strip() not in tech and
                          re.search(r"[A-Za-z]{2}", s) and
                          _i18n_lookup(s, I18N[loc], loc) is None})
        assert not missing, (loc, missing[:8])
    # icons and punctuation around a label survive; numbers are kept
    assert translate_text("▶  Start watching", "fr") == \
        "▶  Commencer à observer"
    assert translate_text("Network card:", "es") == "Tarjeta de red:"
    assert translate_text("1,204 shown", "fr") == "1,204 affichés"
    assert translate_text("3. The Dashboard", "es") == "3. El panel"
    assert translate_text("For: ◉ Signal -80 dBm (weak)", "fr") == \
        "Pour : ◉ Signal -80 dBm (faible)"
    assert translate_text("Start watching", "en") == "Start watching"
    assert translate_text("my-laptop", "fr") == "my-laptop"   # data stays
    assert untranslate_text(translate_text("Devices", "fr")) == "Devices"
    try:
        assert set_locale("Español") == "es" and CURRENT_LOCALE == "es"
        assert set_locale("fr") == "fr"
        assert set_locale("Klingon") == "en"
    finally:
        set_locale("English")
    assert set(LOCALE_NAMES) == set(I18N_LOCALES)


@self_test(slow=False)
def test_boot_receipts_and_crash_loop(ctx):
    """V5 startup: every start leaves a receipt; two failed starts in a row
    turn on Safe Mode; a closed Welcome Center or a hand-off is no
    failure; receipts are pruned to the newest ten."""
    d = ctx.path("boot")
    r = BootReceipt(directory=d, argv=["--demo", READY_ARG + "x"])
    r.step("window", True, "Tk 8.6")
    r.step("capture engine", False, error=ImportError("no scapy"))
    data = read_json(r.path)
    assert data["argv"] == ["--demo"], data["argv"]
    assert data["steps"][1]["error"].startswith("ImportError"), data
    assert "failed at: capture engine" in BootReceipt.summary(data)
    r.mark(outcome="closed", reached_main_window=True)
    assert read_json(r.path)["outcome"] == "closed"

    def fake(name, outcome, main=False, pid=999999999, age=0):
        p = os.path.join(d, f"boot-{name}.json")
        atomic_write_json(p, {"kind": "start", "outcome": outcome,
                              "reached_main_window": main, "pid": pid,
                              "steps": [{"name": "window", "ok": True}],
                              "started": time.time() - age})
        t = time.time() - age
        os.utime(p, (t, t))
        return p
    shutil.rmtree(d)
    os.makedirs(d)
    fake("a", "closed", True, age=30)
    fake("b", "crashed", age=20)
    cur = fake("c", "running", pid=os.getpid(), age=0)
    assert not crash_loop_detected(BootReceipt.recent(d), cur)
    fake("d", "running", age=10)               # died without a word
    assert crash_loop_detected(BootReceipt.recent(d), cur)
    fake("e", "user_exit", age=5)              # closed the Welcome Center
    assert not crash_loop_detected(BootReceipt.recent(d), cur)
    fake("f", "running", pid=os.getpid(), age=4)   # still running here
    fake("g", "fatal", age=3)
    assert not crash_loop_detected(BootReceipt.recent(d), cur)
    for i in range(14):
        fake(f"z{i:02d}", "closed", True, age=100 + i)
    BootReceipt(directory=d).prune()
    assert len(BootReceipt.files(d)) == BootReceipt.KEEP


@self_test(slow=False)
def test_b31_archived_copies_cannot_hurt_each_other(ctx):
    """5.2.3 (B-31/B-32/B-33/B-34/B-35/B-36): copies of MiniWireshark that
    share one data folder (the archive of old versions) no longer roll an
    update back over each other, erase each other's settings, overwrite an
    interrupted session, write into a newer history file or put each other
    into Safe Mode."""
    d = ctx.path(f"arch_{uuid.uuid4().hex[:6]}")
    os.makedirs(d)
    body = b"# MiniWireshark\ndef main():\n    pass\n" + b"#" * 60000
    a = os.path.join(d, "miniwireshark-5.2.3.py")
    b = os.path.join(d, "miniwireshark-5.1.2.py")
    for p_ in (a, b):
        with open(p_, "wb") as f:
            f.write(b"# MiniWireshark old " + os.path.basename(p_).encode() +
                    b"\ndef main():\n    pass\n" + b"#" * 60000)
    b_before = open(b, "rb").read()
    marker = os.path.join(d, "update_pending.json")
    apply_self_update(body, "9.9.9", a, marker)
    # B-31: the other copy neither counts attempts nor restores over itself
    for _ in range(4):
        assert rollback_update_if_needed(script_path=b,
                                         marker_path=marker) == ""
    assert rollback_update_if_needed(force=True, script_path=b,
                                     marker_path=marker) == ""
    assert open(b, "rb").read() == b_before
    assert read_json(marker)["attempts"] == 0
    # leaving at the Welcome Center doesn't count either
    assert rollback_update_if_needed(script_path=a, marker_path=marker) == ""
    update_start_not_counted(a, marker)
    assert read_json(marker)["attempts"] == 0
    # a 5.1.2-style marker (no "script") is judged by its backup's name
    legacy = dict(read_json(marker))
    legacy.pop("script")
    legacy.pop("sha256")
    atomic_write_json(marker, legacy)
    assert update_marker_for(b, marker) is None
    assert update_marker_for(a, marker) is not None
    # the file was replaced since (copied over by hand): marker dropped
    apply_self_update(body, "9.9.9", a, marker)
    with open(a, "ab") as f:
        f.write(b"# edited\n")
    assert update_marker_for(a, marker) is None
    assert not os.path.exists(marker)
    # B-32: settings this version doesn't know survive a load and save
    cp = os.path.join(d, "cfg.json")
    with open(cp, "w", encoding="utf-8") as f:
        json.dump({"config_version": 9, "connectors": {"list": [1]},
                   "zzz_future": {"x": 1}, "general": {"zzz_key": 2}}, f)
    c = AppConfig(path=cp)
    c.set("general.language", "English")
    assert c.save()
    back = read_json(cp)
    assert back["zzz_future"] == {"x": 1}, back
    assert back["connectors"].get("list") == [1], back
    assert back["general"]["zzz_key"] == 2
    assert back["config_version"] == 9
    # B-33: an interrupted session is moved aside before anything else
    jp = os.path.join(d, "journal.mwsession.json")
    with open(jp, "w", encoding="utf-8") as f:
        f.write("{}")
    atomic_write_json(jp + ".sha256", {"journal": 2})
    old = time.time() - 600
    os.utime(jp, (old, old))
    os.utime(jp + ".sha256", (old - 100, old - 100))   # left by 5.1.2
    assert claim_interrupted_journal(jp, now=old + 30) == ""   # still live
    moved = claim_interrupted_journal(jp)
    assert moved and os.path.exists(moved) and not os.path.exists(jp)
    assert not os.path.exists(moved + ".sha256"), "stale fingerprint kept"
    assert not os.path.exists(jp + ".sha256")
    for i in range(5):
        p_ = os.path.join(d, f"journal-interrupted-2000010{i}-000000-1."
                             f"mwsession.json")
        with open(p_, "w") as f:
            f.write("{}")
    with open(jp, "w") as f:
        f.write("{}")
    os.utime(jp, (old, old))
    claim_interrupted_journal(jp)
    left = [n for n in os.listdir(d) if n.startswith("journal-interrupted-")
            and n.endswith(".json")]
    assert len(left) == 3, left
    # B-34: a history file from a newer version is left alone
    hp = os.path.join(d, "h.sqlite3")
    con = sqlite3.connect(hp)
    con.execute("CREATE TABLE meta(k TEXT PRIMARY KEY, v TEXT)")
    con.execute("INSERT INTO meta VALUES('schema', ?)",
                (str(STORE_SCHEMA_VERSION + 1),))
    con.commit()
    con.close()
    st = Store(hp)
    st._ready.wait(10)
    assert "newer" in st.error, st.error
    st.stop()
    # B-35/B-36: other files' failed starts and a Welcome Center left
    # open don't make a crash loop
    other = {"kind": "start", "outcome": "crashed", "script": b,
             "reached_main_window": False, "pid": 999999999}
    mine = dict(other, script=a)
    assert crash_loop_detected([other, other], script=a) is False
    assert crash_loop_detected([mine, mine], script=a) is True
    waiting = dict(mine, outcome="running", on_welcome=True)
    assert crash_loop_detected([waiting, mine], script=a) is False
    old_ver = {"kind": "start", "outcome": "fatal", "version": "5.0.2",
               "reached_main_window": False}
    assert crash_loop_detected([old_ver, old_ver], script=a) is False


@self_test(slow=False, needs_source=True)
def test_v5_handoff_policy_and_handshake(ctx):
    """The managed Python is used only when chosen or needed, and only
    after its window reports back; a child that crashes or hangs is
    stopped, remembered, and this Python carries on."""
    assert system_python_suitable((3, 7), True)[0] is False
    assert system_python_suitable((3, 12), False) == \
        (False, "this Python has no graphical toolkit (Tk)")
    assert system_python_suitable((3, 12), True) == (True, "")
    # handshake outcomes, with real child processes
    rf = ctx.path("ready-ok")
    p = subprocess.Popen([sys.executable, "-c",
                          f"import time; time.sleep(0.2); "
                          f"open({rf!r}, 'w').write('READY'); "
                          f"time.sleep(0.5)"])
    assert wait_for_handshake(p, rf, timeout=10)[0] == "ready"
    p.wait(5)
    p = subprocess.Popen([sys.executable, "-c", "import sys; sys.exit(3)"])
    assert wait_for_handshake(p, ctx.path("never"), timeout=10) == \
        ("exited", 3)
    p = subprocess.Popen([sys.executable, "-c", "import time; "
                                               "time.sleep(30)"])
    t0 = time.monotonic()
    res = wait_for_handshake(p, ctx.path("never2"), timeout=0.6)
    assert res == ("timeout", None) and time.monotonic() - t0 < 5, res
    p.kill()
    p.wait(5)
    # a child that exits 0 (handed to an elevated copy) gets more time
    rf2 = ctx.path("ready-late")
    p = subprocess.Popen([sys.executable, "-c", "pass"])
    threading.Timer(0.8, lambda: open(rf2, "w").write("READY")).start()
    assert wait_for_handshake(p, rf2, timeout=0.3,
                              elevation_timeout=10)[0] == "ready"
    # the whole hand-off with a fake managed Python that crashes
    old = _with_runtime_dir(ctx)
    old_boot = globals()["BOOT_DIR"]
    globals()["BOOT_DIR"] = ctx.path("bootdir")
    try:
        crash = ctx.path("crash_python.py")
        with open(crash, "w") as f:
            f.write("import sys; print('boom: no Tk here'); sys.exit(5)\n")
        launcher = ctx.path("fake_python")
        if IS_WINDOWS:
            launcher = sys.executable
        else:
            with open(launcher, "w") as f:
                f.write(f"#!/bin/sh\nexec {shlex.quote(sys.executable)} "
                        f"{shlex.quote(crash)}\n")
            os.chmod(launcher, 0o755)
        runtime_state_write({"current": "a", "prefer": "managed", "envs": {
            "a": {"python": launcher, "selftest_ok": True,
                  "version": "3.14.2"}}})
        HANDOFF_NOTE[0] = ""
        if not IS_WINDOWS:
            assert runtime_handoff([], {}, True, suitable=(True, ""),
                                   timeout=10) is None
            st = runtime_state_read()
            assert st["envs"]["a"].get("handshake_failed"), st
            assert "stopped with code 5" in HANDOFF_NOTE[0], HANDOFF_NOTE
            assert not runtime_healthy(runtime_env(st))
            # remembered: the next start does not try again
            assert runtime_handoff([], {}, False, suitable=(True, "")) \
                is None
        # policy: a healthy managed Python is skipped when this Python
        # works and you did not choose it
        runtime_state_write({"current": "b", "envs": {
            "b": {"python": launcher, "selftest_ok": True}}})
        assert runtime_handoff([], {}, False, suitable=(True, "")) is None
        assert runtime_handoff(["--x"], {}, False,
                               suitable=(False, "no Tk"))[:5] == \
            [launcher, "-c", CACHED_RUN, SCRIPT_PATH, "--x"]
    finally:
        HANDOFF_NOTE[0] = ""
        globals()["BOOT_DIR"] = old_boot
        _restore_runtime_dir(old)


def _fake_wheel(path, name, version, files):
    import zipfile
    with zipfile.ZipFile(path, "w") as zf:
        for rel, body in files.items():
            zf.writestr(rel, body)
        zf.writestr(f"{name}-{version}.dist-info/METADATA",
                    f"Name: {name}\nVersion: {version}\n")
        zf.writestr(f"{name}-{version}.dist-info/RECORD", "")
    return path


@self_test(slow=False, needs_source=True)
def test_private_packages_folder(ctx):
    """Packages go into MiniWireshark's own folder: swapped in atomically,
    importable, removable, and never through the system Python's pip."""
    root = ctx.path("site")
    pp = PrivatePackages(root=root, cache=ctx.path("wheels"))
    w1 = _fake_wheel(ctx.path("mwfakepkg-1.0-py3-none-any.whl"),
                     "mwfakepkg", "1.0",
                     {"mwfakepkg/__init__.py": "VERSION = '1.0'\n"})
    assert pp.install_wheel_file(w1) == ("mwfakepkg", "1.0")
    assert pp.activate() and root in sys.path
    try:
        mwfakepkg = importlib.import_module("mwfakepkg")
        assert mwfakepkg.VERSION == "1.0"
        w2 = _fake_wheel(ctx.path("mwfakepkg-2.0-py3-none-any.whl"),
                         "mwfakepkg", "2.0",
                         {"mwfakepkg/__init__.py": "VERSION = '2.0'\n",
                          "mwfakepkg/extra.py": "X = 1\n"})
        pp.install_wheel_file(w2)
        assert pp.installed()["mwfakepkg"]["version"] == "2.0"
        assert sorted(pp.installed()["mwfakepkg"]["entries"]) == \
            ["mwfakepkg", "mwfakepkg-2.0.dist-info"]
        assert not os.path.exists(os.path.join(
            root, "mwfakepkg-1.0.dist-info")), os.listdir(root)
        assert pp.verify() == []
        shutil.rmtree(os.path.join(root, "mwfakepkg"))
        assert pp.verify() == ["mwfakepkg"]
        assert pp.remove("mwfakepkg") and pp.installed() == {}
        bad = _fake_wheel(ctx.path("evil-1.0-py3-none-any.whl"), "evil",
                          "1.0", {"../escape.py": "x = 1\n"})
        try:
            pp.install_wheel_file(bad)
            raise AssertionError("unsafe wheel accepted")
        except RuntimeError_:
            pass
        assert not os.path.exists(ctx.path("escape.py"))
        assert not [n for n in os.listdir(root) if n.startswith(".")]
    finally:
        sys.modules.pop("mwfakepkg", None)
        with contextlib.suppress(ValueError):
            sys.path.remove(root)
    # the pip command: own folder only, binary wheels, never --user
    cmd = pp.pip_command(["psutil==7.2.2"], ctx.path("stage"))
    joined = " ".join(cmd)
    assert "--target" in cmd and "--only-binary=:all:" in cmd, cmd
    assert "--user" not in cmd and "break-system" not in joined, cmd
    src = inspect.getsource(PrivatePackages) + \
        inspect.getsource(step_dependencies)
    assert "break-system" not in src and '"--user"' not in src
    assert pypi_file_url("scapy-2.8.0-py3-none-any.whl") == (
        "https://files.pythonhosted.org/packages/py3/s/scapy/"
        "scapy-2.8.0-py3-none-any.whl")
    assert abi_tag((3, 12), "win-amd64") == "cp312-win_amd64"
    assert abi_tag((3, 9), "macosx-11.0-arm64") == "cp39-macosx_11_0_arm64"
    assert optional_version("cryptography", (3, 8)) == "46.0.3"
    assert optional_version("cryptography", (3, 13)) == "50.0.2"
    # a fingerprint mismatch never leaves a file behind
    srcf = ctx.path("blob.bin")
    with open(srcf, "wb") as f:
        f.write(b"x" * 1000)
    try:
        fetch_to_file("file://" + urllib.request.pathname2url(srcf),
                      ctx.path("dl/blob.bin"), "0" * 64, "packages")
        raise AssertionError("bad fingerprint accepted")
    except RuntimeError_ as e:
        assert e.kind == "fingerprint", e.kind
    assert not os.path.exists(ctx.path("dl/blob.bin"))
    ok = fetch_to_file("file://" + urllib.request.pathname2url(srcf),
                       ctx.path("dl/blob2.bin"), sha256_file(srcf),
                       "packages")
    assert os.path.getsize(ok) == 1000
    try:
        fetch_to_file("file://" + urllib.request.pathname2url(srcf),
                      ctx.path("dl/blob3.bin"), None, "packages",
                      max_bytes=100)
        raise AssertionError("size cap ignored")
    except RuntimeError_:
        pass


