@self_test(slow=False)
def test_components_parsers(ctx):
    """Components Center parsers: IANA ports, DNS stamps, minisign
    (prehashed and legacy), abuse.ch and Spamhaus lists, two-source
    reputation."""
    p = ctx.path("iana.csv")
    with open(p, "w") as f:
        f.write(IANA_SAMPLE)
    db = load_iana_services(p)
    assert db.lookup(1883) == ("ibm-mqisdp", "IBM MQSeries SCADA")
    assert db.lookup(6002) == ("x11", "X Window System")
    assert db.lookup(0) is None and db.lookup(5000) is None
    assert db.lookup(1883, "udp") is None
    s = parse_dns_stamp(_stamp(0x02, "9.9.9.9:443", "dns.example-doh.net",
                               "/dns-query"))
    assert s == {"proto": "DoH", "addr": "9.9.9.9",
                 "host": "dns.example-doh.net", "path": "/dns-query"}, s
    s = parse_dns_stamp(_stamp(0x03, "[2001:db8::53]:853", "dot.example",
                               hashes=(b"\x02" * 32, b"\x03" * 32)))
    assert s["proto"] == "DoT" and s["addr"] == "2001:db8::53" and \
        s["host"] == "dot.example", s
    assert parse_dns_stamp("sdns://AA") is None
    assert parse_dns_stamp("https://x") is None
    md = ctx.path("resolvers.md")
    with open(md, "w") as f:
        f.write("# public-resolvers\n\n## example-doh\nA test.\n" +
                _stamp(0x02, "192.0.2.53", "doh.example.org", "/q") +
                "\n\n## plain\n" + _stamp(0x00, "192.0.2.1") + "\n")
    rdb = load_dnscrypt_list(md)
    assert rdb.lookup("doh.example.org") == ("example-doh", "DoH")
    assert rdb.lookup("192.0.2.53") == ("example-doh", "DoH")
    assert rdb.lookup("192.0.2.1") is None and len(rdb) == 1
    secret, pub, kid = _minisign_pair()
    data = b"resolver list body\n"
    for pre in (True, False):
        sig = _minisign_sign(secret, kid, data, prehash=pre)
        assert minisign_verify(data, sig, pub) == (True,
                                                   "timestamp:1\tfile:x")
        assert minisign_verify(data + b"!", sig, pub)[0] is False
    sig = _minisign_sign(secret, kid, data)
    bad_tc = sig.replace("timestamp:1", "timestamp:2")
    assert minisign_verify(data, bad_tc, pub) == \
        (False, "the trusted comment was altered")
    _s2, pub2, _k2 = _minisign_pair(b"\x08" * 32, b"OTHERKEY")
    assert minisign_verify(data, sig, pub2)[1] == "signed with a different key"
    assert minisign_verify(data, "garbage", pub)[0] is False
    fp = ctx.path("feodo.txt")
    with open(fp, "w") as f:
        f.write(FEODO_SAMPLE)
    assert validate_feodo(fp) == (True, "2 listed addresses")
    feodo = load_feodo(fp)
    assert feodo.lookup("50.16.16.211") and not feodo.lookup("10.0.0.1")
    assert feodo.updated.startswith("2026-10-18")
    dp = ctx.path("drop.json")
    with open(dp, "w") as f:
        f.write(DROP_SAMPLE)
    drop = load_drop(dp)
    assert len(drop) == 151 and drop.updated
    assert drop.lookup("203.0.42.7") == "SBL1042 203.0.42.0/24"
    assert drop.lookup("198.51.100.1") == ""
    rep = ReputationDB([feodo, drop])
    hits = rep.lookup("93.184.215.14")
    assert sorted(h[0] for h in hits) == ["Spamhaus DROP",
                                          "abuse.ch Feodo Tracker"], hits
    assert rep.lookup("192.168.1.5") == [] and rep.lookup("") == []
    txt = reputation_text(hits)
    assert "listed by abuse.ch Feodo Tracker" in txt and "SBL9" in txt
    assert "malicious" not in txt and "hacked" not in txt
    e = explain_port_text(3389)
    assert "Remote Desktop" in e and "ransomware" in e, e
    assert "ephemeral" in explain_port_text(51515)


@self_test(slow=False)
def test_components_manager_lifecycle(ctx):
    """Download (file:// stands in for HTTPS), signature check, previous
    copy kept, the pack doctor falls back to it, roll back, delete,
    baseline reset, offline packs that respect licenses, min interval."""
    cache = ctx.path("cc_lifecycle")
    os.makedirs(cache)
    cfg = ctx.cfg({"components.feodo": True, "components.drop": True,
                   "components.doh": True})
    dm = DataManager(cache, cfg)
    src = ctx.path("cc_srv")
    os.makedirs(src)

    def url(name):
        return "file://" + urllib.request.pathname2url(
            os.path.join(src, name))
    with open(os.path.join(src, "feodo.txt"), "w") as f:
        f.write(FEODO_SAMPLE)
    feodo_r = dataclasses.replace(dm.resource("feodo"), url=url(
        "feodo.txt"), min_interval=0)
    drop_r = dataclasses.replace(dm.resource("drop"), url=url("drop.json"),
                                 min_interval=0)
    with open(os.path.join(src, "drop.json"), "w") as f:
        f.write(DROP_SAMPLE)
    secret, pub, kid = _minisign_pair()
    body = ("# public-resolvers\n" + "".join(
        f"\n## r{i}\n" + _stamp(0x02, f"192.0.2.{i}", f"doh{i}.example",
                                "/q") + "\n" for i in range(60))).encode()
    with open(os.path.join(src, "res.md"), "wb") as f:
        f.write(body)
    with open(os.path.join(src, "res.md.minisig"), "w") as f:
        f.write(_minisign_sign(secret, kid, body))
    doh_r = dataclasses.replace(dm.resource("doh"), url=url("res.md"),
                                sig_url=url("res.md.minisig"),
                                minisign_key=pub, min_interval=0)
    assert dm._download(feodo_r) and dm._verify_and_load(feodo_r)
    assert dm.get("feodo").lookup("50.16.16.211")
    assert dm._download(doh_r) and dm._verify_and_load(doh_r)
    assert dm.meta("doh")["signature"] == "minisign ok"
    assert dm.get("doh").lookup("doh7.example") == ("r7", "DoH")
    # a tampered list is refused, the good copy stays
    with open(os.path.join(src, "res.md"), "ab") as f:
        f.write(b"\n## evil\n")
    assert dm._download(doh_r) is False
    assert "signature check failed" in dm.meta("doh")["last_error"]
    assert dm.get("doh") is not None
    # second download keeps the previous copy; a damaged copy falls back
    assert dm._download(drop_r) and dm._verify_and_load(drop_r)
    assert dm._download(drop_r)
    path, meta = dm._paths(drop_r)
    assert os.path.exists(path + ".prev")
    with open(path, "a") as f:
        f.write("tampered\n")
    with dm.lock:
        dm.objects.pop("drop", None)
    assert dm._verify_and_load(drop_r)
    assert "previous copy" in dm.doctor["drop"], dm.doctor
    assert dm.get("drop").lookup("203.0.1.1")
    # the shrink guard keeps a list that suddenly lost most entries
    small = "".join(json.dumps({"cidr": f"198.18.{i}.0/24"}) + "\n"
                    for i in range(101))
    atomic_write_json(meta, dict(read_json(meta), summary="5000 blocks"))
    with open(os.path.join(src, "drop.json"), "w") as f:
        f.write(small)
    assert dm._download(drop_r) is False
    assert "less than half" in dm.meta("drop")["last_error"]
    # min interval: a fresh copy is not fetched again
    quick = dataclasses.replace(feodo_r, min_interval=3600)
    assert dm._download(quick) is False
    # offline pack: CC0 Feodo goes in; DROP and DNSCrypt never do
    pack = ctx.path("data.mwpack")
    keys, skipped = dm.export_pack(pack)
    assert keys == ["feodo"], keys
    import zipfile
    with zipfile.ZipFile(pack) as z:
        notice = z.read("NOTICE.txt").decode()
    assert "abuse.ch Feodo Tracker" in notice and "CC0" in notice and \
        "creativecommons.org" in notice, notice      # LG-14
    assert "Hijacked address blocks" in skipped and \
        "Encrypted-DNS resolvers" in skipped, skipped
    cache2 = ctx.path("cc_lifecycle2")
    os.makedirs(cache2)
    cfg2 = ctx.cfg()
    dm2 = DataManager(cache2, cfg2)
    done, problems = dm2.import_pack(pack)
    assert done == ["feodo"] and not problems, (done, problems)
    assert cfg2.get("components.feodo") is True
    assert dm2.get("feodo").lookup("50.16.16.211")
    assert dm2.meta("feodo")["via"] == "offline pack"
    import zipfile
    bad = ctx.path("bad.mwpack")
    with zipfile.ZipFile(pack) as zin, zipfile.ZipFile(bad, "w") as zout:
        for n in zin.namelist():
            data = zin.read(n)
            if n.endswith(".txt"):
                data += b"203.0.113.9\n"
            zout.writestr(n, data)
    os.makedirs(ctx.path("cc_lifecycle3"))
    done, problems = DataManager(ctx.path("cc_lifecycle3"),
                                 ctx.cfg()).import_pack(bad)
    assert not done and "fingerprint mismatch" in problems[0], problems
    # roll back, delete, return to baseline
    assert dm.rollback("drop") or True
    dm.delete("feodo")
    assert dm.get("feodo") is None and not cfg.get("components.feodo")
    assert not os.path.exists(dm._paths(feodo_r)[0])
    dm.reset_all()
    assert all(not dm.enabled(r) for r in dm.resources())
    assert sum(dm.disk_usage().values()) == 0


@self_test()
def test_reputation_alerts_and_reenrich(ctx):
    """A device contacting a listed address raises a cautious alert; two
    independent lists make it stronger; turning a list on later and
    re-labelling the session finds earlier contacts too."""
    if not ctx.scapy_ok:
        return "skip"
    cache = ctx.path("rep")
    os.makedirs(cache)
    cfg = ctx.cfg({"components.feodo": True, "components.drop": False})
    dm = DataManager(cache, cfg)
    for key, body in (("feodo", FEODO_SAMPLE), ("drop", DROP_SAMPLE)):
        r = dm.resource(key)
        tmp = os.path.join(cache, f"{key}.tmp")
        with open(tmp, "w") as f:
            f.write(body)
        dm._install_file(r, tmp, "test", "test")
    dm._verify_and_load(dm.resource("feodo"))
    old = globals()["DATA"]
    globals()["DATA"] = dm
    _REP_GEN[0] += 1
    try:
        m = scenario_model(cfg, ctx.frames())
        reps = [a for a in m.alerts.alerts.values() if a.kind ==
                "reputation"]
        assert reps, "no reputation alert"
        a = reps[0]
        assert a.severity == "WARNING" and "93.184.215.14" in a.observed
        assert "Feodo" in a.observed and "hacked" not in a.observed.lower()
        assert m.remote_hosts["93.184.215.14"].reputation
        # now the second list: re-labelling finds the same host again
        cfg.set("components.drop", True)
        dm._verify_and_load(dm.resource("drop"))
        for x in reps:
            m.alerts.acknowledge(x.id)
        m.alerts._debounce.clear()
        n = m.reenrich()
        assert n["remote"] >= 1, n
        strong = [x for x in m.alerts.alerts.values()
                  if x.kind == "reputation" and x.severity == "DANGER"]
        assert strong, [x.severity for x in m.alerts.alerts.values()
                        if x.kind == "reputation"]
        assert "two public blocklists" in strong[0].reason
    finally:
        globals()["DATA"] = old
        _REP_GEN[0] += 1


@self_test(slow=False)
def test_teach_once_fingerprints(ctx):
    """Setting a device's type remembers its fingerprint on this computer;
    a look-alike needs two matching signals before it gets a suggestion,
    and the suggestion says where it was learned."""
    lt = LearnedTypes(path=ctx.path("learned.json"))
    a = DeviceRecord(key="00:1b:a9:00:00:01", mac="00:1b:a9:00:00:01",
                     dhcp_params="1,3,6,15,51", dhcp_hostname="NPI6A1B2C")
    b = DeviceRecord(key="00:1b:a9:00:00:02", mac="00:1b:a9:00:00:02",
                     dhcp_params="1,3,6,15,51")
    c = DeviceRecord(key="00:1b:a9:00:00:03", mac="00:1b:a9:00:00:03")
    r = DeviceRecord(key="ip:10.0.0.9", ip="10.0.0.9")
    assert lt.learn(a, "Printer")
    assert not lt.learn(r, "Printer"), "no signals: nothing to learn"
    hit = lt.match(b)
    assert hit and hit["cls"] == "Printer" and hit["score"] == 5, hit
    assert "same DHCP request list" in hit["why"]
    assert lt.match(c) is None, "one signal (maker block) is not enough"
    assert lt.match(a) is None, "a device never matches itself"
    again = LearnedTypes(path=ctx.path("learned.json"))
    assert again.match(b)["cls"] == "Printer", "saved to disk"
    lt.forget(a.key)
    assert lt.match(b) is None
    assert LearnedTypes(path=ctx.path("learned.json")).items == []
    assert _name_pattern("ESP_6A1B2C") == "esp_*"
    assert _name_pattern("Krystel's laptop") == ""
    lt2 = LearnedTypes(path=ctx.path("learned2.json"))
    for i in range(LearnedTypes.MAX + 20):
        lt2.learn(DeviceRecord(key=f"k{i}", mac=f"00:1b:a9:00:{i // 256:02x}:"
                                               f"{i % 256:02x}",
                               dhcp_params="1,3"), "Camera")
    assert len(lt2.items) == LearnedTypes.MAX, "bounded"


@self_test()
def test_set_device_type_model_and_undo(ctx):
    """'Set device type' overrides detection, says so, is journalled with
    a readable description, survives as a saved label, and undoes back to
    the detected type."""
    if not ctx.scapy_ok:
        return "skip"
    old = LEARNED[0]
    LEARNED[0] = LearnedTypes(path=ctx.path("learned-m.json"))
    try:
        m = scenario_model(ctx.cfg(), ctx.frames())
        dev = next(d for d in m.registry.by_key.values()
                   if d.mac and d.device_class not in ("Printer",
                                                       "This computer"))
        before = (dev.device_class, dev.class_confidence)
        assert m.correct_type(dev.key, "Printer") == [dev.key]
        assert dev.user_class == "Printer" and dev.device_class == "Printer"
        assert dev.class_confidence == "" and \
            dev.class_reasons[0] == "You set this type"
        assert m.correct_type(dev.key, "Printer") == [], "no-op"
        assert m.correct_type(dev.key, "Spaceship") == [], "unknown type"
        e = m.journal.last_undoable()
        assert e["op"] == "type"
        text = m.journal.describe(e)
        assert "detected → Printer" in text, text
        store = KnownDevicesStore(ctx.path("known.json"))
        store.update_from(dev)
        assert store.data[dev.key]["user_class"] == "Printer"
        m.undo_correction()
        assert dev.user_class == "" and \
            (dev.device_class, dev.class_confidence) == before
        assert "user_class" in DEVICE_SAVE_FIELDS
    finally:
        LEARNED[0] = old


@self_test(slow=False)
def test_raw_ring_v2_threads_and_waits(ctx):
    """Several producers and one consumer: the byte count never drifts,
    every offered frame is either accepted or counted as dropped, and a
    lossless producer is woken as soon as the worker makes room (no
    polling)."""
    r = RawRing(max_frames=500, max_bytes=40_000)
    offered = [0]
    consumed = []
    stop = threading.Event()

    def producer(seed):
        rnd = random.Random(seed)
        for i in range(5000):
            r.put(b"x" * rnd.randint(20, 200), i, 1, 1)
        offered[0] += 5000

    def consumer():
        while not stop.is_set() or len(r):
            for item in r.drain(64, timeout=0.02):
                consumed.append(len(item[0]))
    c = threading.Thread(target=consumer)
    c.start()
    ps = [threading.Thread(target=producer, args=(s,)) for s in range(4)]
    for p in ps:
        p.start()
    for p in ps:
        p.join()
    stop.set()
    c.join(5)
    st = r.stats()
    assert st["accepted"] + st["dropped"] == 20000, st
    assert st["accepted"] == len(consumed), (st, len(consumed))
    assert st["bytes"] == 0 and st["queued"] == 0, st
    assert st["peak"] <= 500 and st["peak_bytes"] <= 40_000 + 200, st
    # lossless producer waits on the condition and wakes quickly
    r2 = RawRing(max_frames=2)
    r2.put(b"a", 0, 1, 1)
    r2.put(b"b", 0, 1, 1)
    woke = []

    def waiter():
        t0 = time.perf_counter()
        r2.put_wait(b"c", 0, 1, 1)
        woke.append(time.perf_counter() - t0)
    t = threading.Thread(target=waiter)
    t.start()
    time.sleep(0.1)
    assert not woke, "put_wait did not wait"
    t1 = time.perf_counter()
    r2.drain(1)
    t.join(2)
    assert woke and woke[0] < 2, woke
    assert time.perf_counter() - t1 < 0.2, "producer woke late"
    cancelled = RawRing(max_frames=1)
    cancelled.put(b"a", 0, 1, 1)
    assert cancelled.put_wait(b"b", 0, 1, 1, lambda: True) is False
    # the consumer sleeps on the condition and wakes on a put
    r3 = RawRing()
    got = []
    t = threading.Thread(target=lambda: got.append(
        (time.perf_counter(), r3.drain(5, timeout=2.0))))
    t.start()
    time.sleep(0.05)
    t_put = time.perf_counter()
    for i in range(RawRing.NOTIFY_AT):
        r3.put(b"z", i, 1, 1)
    t.join(3)
    assert got and len(got[0][1]) == 5 and got[0][0] - t_put < 0.2, got
    r3.reset_counters()
    assert r3.stats()["accepted"] == 0


@self_test(slow=False)
def test_capture_fault_classifier(ctx):
    """Each capture failure gets a plain title, a fix, a retry decision,
    and keeps the original error text."""
    cases = [
        (PermissionError(1, "Operation not permitted"), "permission", False),
        (OSError("Npcap/WinPcap is not installed"), "driver", False),
        (OSError("syntax error in filter expression"), "bad_filter", False),
        (OSError(19, "No such device"), "adapter_gone", True),
        (RuntimeError("adapter disappeared"), "adapter_gone", True),
        (RuntimeError("resumed from sleep"), "sleep", True),
        (OSError(105, "No buffer space available"), "overflow", True),
        (ValueError("Interface 'xyz' not found"), "wrong_adapter", True),
        (struct.error("unpack requires a buffer"), "parse", True),
        (RuntimeError("weird"), "unknown", True),
        (None, "unknown", True),
        # 5.2.3 (B-02/B-03): a refused promiscuous mode is not a bad
        # filter, and Npcap's "Error opening adapter" is not a card gone
        (OSError("failed to set hardware filter to promiscuous mode"),
         "wrong_adapter", True),
        (OSError("Error opening adapter: The system cannot find the "
                 "device specified. (20)"), "wrong_adapter", True),
    ]
    for exc, kind, retry in cases:
        k, title, fix, rt, orig = classify_capture_fault(exc)
        assert (k, rt) == (kind, retry), (exc, k, rt)
        assert title and fix
        if exc is not None:
            assert str(exc) in orig and type(exc).__name__ in orig


@self_test(slow=False)
def test_b02_promisc_refused_and_probe_order(ctx):
    """5.2.3 (B-01/B-02): a card that refuses promiscuous mode is opened
    without it (raw socket and scapy sniffer) instead of failing as a
    "bad filter"; other errors still surface; cards are probed in order,
    stopping at the first that opens, and a cancel stops the probing."""
    refusal = OSError("failed to set hardware filter to promiscuous mode")
    calls = []

    def l2listen(**kw):
        calls.append(kw.get("promisc", "default"))
        if kw.get("promisc", True):
            raise refusal
        return "sock"

    def broken(**_kw):
        raise OSError("No such device")

    class FakeSniffer:
        def __init__(self, **kw):
            self.kw = kw
            self.exception = None

        def start(self):
            if self.kw.get("promisc", True):
                raise refusal

        def stop(self):
            pass

    class Src:
        def stop(self):
            pass
    tried = []

    def fake_start(iface, _bpf, _promisc, _sink):
        tried.append(iface)
        if iface == "c":
            return Src(), None
        return None, OSError("Error opening adapter (20)")
    g = globals()
    old = {k: g.get(k) for k in ("conf", "AsyncSniffer", "probe_l2_socket",
                                 "start_capture_source")}
    try:
        g["conf"] = types.SimpleNamespace(L2listen=l2listen)
        rc = RawCapture("eth9", None, True, lambda *a: None)
        assert rc._open() == "sock" and rc.promisc_refused
        assert calls == [True, False], calls
        calls.clear()
        rc = RawCapture("eth9", None, False, lambda *a: None)
        assert rc._open() == "sock" and not rc.promisc_refused
        assert calls == [False], calls
        g["conf"] = types.SimpleNamespace(L2listen=broken)
        try:
            RawCapture("eth9", None, True, lambda *a: None)._open()
        except OSError as e:
            assert "No such device" in str(e)
        else:
            raise AssertionError("a real open error was swallowed")
        g["AsyncSniffer"] = FakeSniffer
        g["probe_l2_socket"] = lambda: {"snaplen": True, "promisc": True,
                                        "found": "test"}
        s, err = build_sniffer("eth9", lambda p: None, None, True)
        assert err is None and s.kw.get("promisc") is False, (s, err)
        assert s.mw_promisc_refused
        assert SnifferCapture(s).promisc_refused
        g["start_capture_source"] = fake_start
        cands = [("A", "a"), ("B", "b"), ("C", "c"), ("D", "d")]
        src, err, used = probe_capture_sources(cands, None, True, None)
        assert used == "C" and isinstance(src, Src) and err is None
        assert tried == ["a", "b", "c"], tried
        tried.clear()
        src, err, used = probe_capture_sources(
            cands, None, True, None, cancelled=lambda: len(tried) >= 1)
        assert src is None and used is None and tried == ["a"], tried
    finally:
        for k, v in old.items():
            g[k] = v


@self_test(slow=False)
def test_m8_frozen_seams(ctx):
    """5.2.3 (M8): in a frozen build the program starts itself as
    [exe, *args] (no script path, no compiled-copy loader), keeps its data
    next to the exe, never loads private packages over its bundled ones,
    and refuses a .py self-update."""
    g = globals()
    saved = {k: g[k] for k in ("FROZEN",)}
    try:
        g["FROZEN"] = True
        exe = sys.executable
        assert self_cmd("--demo") == [exe, "--demo"]
        assert cached_cmd(exe, SCRIPT_PATH, ["--mw-worker"]) == \
            [exe, "--mw-worker"]
        assert "MW_CACHED" not in cached_env({"A": "1"})
        assert runtime_handoff(argv=[], environ={}, execute=False) is None
        assert PRIVATE_PACKAGES.activate() is False
        try:
            apply_self_update(b"x" * 60000, "v9")
            raise AssertionError("a frozen build must refuse .py updates")
        except UpdateRefused:
            pass
    finally:
        g.update(saved)
    assert self_cmd("--demo")[-2:] == [SCRIPT_PATH, "--demo"]


@self_test(slow=False)
def test_b10_atomic_write_retries_a_busy_target(ctx):
    """5.2.3 (B-10): on Windows an antivirus holding the target for a
    moment made os.replace fail and the save was lost, leaving a .tmp
    file behind. The replace is retried briefly; on a real failure the
    temporary file is removed and the error still reaches the caller."""
    target = ctx.path("b10.json")
    atomic_write_text(target, "old")
    real, calls = os.replace, []

    def flaky(a, b):
        calls.append(a)
        if len(calls) < 3:
            raise PermissionError(13, "in use")
        real(a, b)
    os.replace = flaky
    try:
        atomic_write_text(target, "new")
        assert len(calls) == 3
        with open(target, encoding="utf-8") as f:
            assert f.read() == "new"

        def never(a, b):
            raise PermissionError(13, "in use")
        os.replace = never
        try:
            atomic_write_bytes(target, b"lost")
            raise AssertionError("the failure must reach the caller")
        except PermissionError:
            pass
    finally:
        os.replace = real
    left = [n for n in os.listdir(os.path.dirname(target))
            if n.startswith("b10.json.tmp")]
    assert not left, left
    with open(target, encoding="utf-8") as f:
        assert f.read() == "new"


@self_test(slow=False)
def test_b11_identity_on_multi_adapter_pcs(ctx):
    """5.2.3 (B-11..B-20): a PC with Wi-Fi, ZeroTier, VMware and Tailscale
    adapters. Only the captured card's private subnet is "the LAN"; CGNAT
    addresses are not local; a DNS answer never names a local device; a
    routed private host never moves the router; ARP entries of virtual
    switches are not reported as devices; process names don't outlive
    their process number."""
    def r(net, mask, iface, addr="x"):
        return (int(ipaddress.ip_address(net)),
                int(ipaddress.ip_address(mask)), "0.0.0.0", iface, addr, 1)
    routes = [r("172.25.0.0", "255.255.240.0", "vEthernet (WSL)"),
              r("203.0.113.0", "255.255.255.0", "ZeroTier One"),
              r("100.64.0.0", "255.192.0.0", "Tailscale"),
              r("192.168.1.0", "255.255.255.0", "Wi-Fi"),
              r("192.168.1.0", "255.255.255.0", "Wi-Fi"),
              r("0.0.0.0", "0.0.0.0", "Wi-Fi"),
              ("bad",)]
    lan = ipaddress.ip_network("192.168.1.0/24")
    wsl = ipaddress.ip_network("172.25.0.0/20")
    assert local_nets_from_routes(routes, "Wi-Fi") == [lan]
    assert local_nets_from_routes(routes) == [wsl, lan]
    assert local_nets_from_routes(routes, "eth9") == [wsl, lan]
    assert not is_private_ip("100.64.1.2") and is_private_ip("10.1.2.3")
    if not ctx.scapy_ok:
        return
    sb = ScenarioBuilder()
    me, gw = sb.ME, sb.GW
    # before the router's MAC is known: replies from a host beyond it
    sb.tls(me, "intranet.example", "10.20.0.5", size=2000)
    sb.dns(me, "ads.doubleclick.example", "192.168.1.53")
    sb.arp_announce(me)
    m = scenario_model(ctx.cfg(), frames=sb.frames)
    assert m.cache.get("192.168.1.53") in ("", None), \
        m.cache.get("192.168.1.53")
    key = m.registry.ip_to_key.get("10.20.0.5")
    gdev = m.registry.by_key.get(m.registry.ip_to_key.get(gw[0]))
    assert gdev is None or gdev.ip == gw[0], gdev.ip
    assert key is None or key != getattr(gdev, "key", None)
    # ARP cache: the WSL switch's neighbour is not a device on this LAN
    app = types.SimpleNamespace(model=m, arp_cache=[
        ("192.168.1.77", "02:00:00:00:00:77", "Wi-Fi"),
        ("172.25.0.9", "02:00:00:00:00:09", "vEthernet (WSL)")])
    got = MiniWireshark.arp_cache_only(app)
    assert ("192.168.1.77", "02:00:00:00:00:77") in got, got
    assert all(ip != "172.25.0.9" for ip, _m in got), got


@self_test(slow=False, needs_source=True)
def test_b09_console_text_and_small_fixes(ctx):
    """5.2.3: console output in any code page decodes without raising
    (B-09); a stored secret keeps its last letters and loses only its
    newline (B-41); the 6 GHz band's low end has the right channels
    (B-19)."""
    assert console_decode("Wi-Fi \u00e9") == "Wi-Fi \u00e9"
    assert console_decode(None) == ""
    for raw in ("R\u00e9seau sans fil".encode("cp850"),
                "\u0421\u0435\u0442\u044c".encode("cp866"),
                b"\xff\xfe\x81\x8d"):
        assert isinstance(console_decode(raw), str)
    r = run_console([sys.executable, "-c", "print('ok')"], timeout=30)
    assert r.returncode == 0 and r.stdout.strip() == "ok"
    assert _one_line_end("token\\n\n") == "token\\n"
    assert _one_line_end("passwordn\n") == "passwordn"
    assert _one_line_end("x\r\n") == "x" and _one_line_end("y") == "y"
    assert wifi_channel_from_mhz(5935) == (2, "6 GHz")
    assert wifi_channel_from_mhz(5955) == (1, "6 GHz")
    assert wifi_channel_from_mhz(7115) == (233, "6 GHz")
    assert wifi_channel_from_mhz(5945) == (None, "")
    assert abi_tag((3, 13), "win-amd64", "t") == "cp313t-win_amd64"
    assert abi_tag((3, 12), "linux-x86_64", "") == "cp312-linux_x86_64"
    # B-40: several versions in one folder are told they share data
    arch = ctx.path("b40archive")
    os.makedirs(arch, exist_ok=True)
    for name in ("miniwireshark V3.0.0.py", "miniwireshark-5.1.2.py"):
        with open(os.path.join(arch, name), "w", encoding="utf-8") as f:
            f.write("#\n")
    shared = os.path.join(arch, "miniwireshark_data")
    assert "2 MiniWireshark versions" in shared_data_note(arch, shared)
    assert shared_data_note(arch, ctx.path("elsewhere")) == ""
    # B-07: no Npcap on Windows does not elevate the whole window
    g = globals()
    saved = {k: g[k] for k in ("IS_WINDOWS", "is_admin",
                               "_npcap_present_early", "_npcap_admin_only")}
    try:
        g.update(IS_WINDOWS=True, is_admin=lambda: False,
                 _npcap_present_early=lambda: False,
                 _npcap_admin_only=lambda: True)
        assert not needs_elevation()
        g["_npcap_present_early"] = lambda: True
        assert needs_elevation()                # admin-only Npcap mode
    finally:
        g.update(saved)
    # B-39: a runtime whose base Python folder vanished is not healthy
    venv = ctx.path("b39env")
    os.makedirs(os.path.join(venv, "Scripts"), exist_ok=True)
    exe = os.path.join(venv, "Scripts", "python.exe")
    with open(exe, "wb") as f:
        f.write(b"x")
    env = {"python": exe, "selftest_ok": True}
    assert runtime_healthy(env)                 # no pyvenv.cfg: trusted
    with open(os.path.join(venv, "pyvenv.cfg"), "w", encoding="utf-8") as f:
        f.write("home = " + ctx.path("gone-store-python") + "\n")
    assert not runtime_healthy(env)
    with open(os.path.join(venv, "pyvenv.cfg"), "w", encoding="utf-8") as f:
        f.write("home = " + os.path.dirname(sys.executable) + "\n")
    assert runtime_healthy(env)
    # C-01: a keychain secret never appears on a command line
    real, seen = subprocess.run, []

    def fake(args, **kw):
        seen.append((list(args), kw.get("input") or b""))
        return types.SimpleNamespace(returncode=0, stdout=b"", stderr=b"")
    vault = CredentialVault.__new__(CredentialVault)
    vault.backend = "keychain"
    subprocess.run = fake
    try:
        for secret in ('c01-pa"ss\\word\u00e9-Zq7', "c01-Plain-Zq7"):
            assert vault.set("c1", secret)
            args, data = seen[-2]
            assert args == ["security", "-i"], args
            assert _keychain_quote(secret).encode() in data
            assert seen[-1][0][:2] == ["security", "find-generic-password"]
            assert "-w" not in seen[-1][0]
            assert all(secret not in a for c, _d in seen for a in c)
    finally:
        subprocess.run = real
    assert not _keychain_quotable("two\nlines")
    assert _keychain_quote('a"b\\c') == '"a\\"b\\\\c"'


@self_test(slow=False)
def test_b24_first_visit_once_and_bounded_maps(ctx):
    """5.2.3 (B-24/B-27): "First visit to …" is said once per site, even
    when 3,000+ other websites came in between (it was said again, and
    every new website scanned the last 3,000); the alert engine's
    debounce and open-alert maps stay bounded."""
    t = [100000.0]
    m = NetworkModel(ctx.cfg(), now_fn=lambda: t[0])
    m.capture_started = t[0] - 100000
    said = []
    m.push_timeline = lambda kind, sev, text, *a, **k: said.append(text)
    m.register_website("www.google.com", None, None, "DNS")
    for i in range(3200):
        m.register_website(f"host{i}.site{i}.example", None, None, "DNS")
    m.register_website("mail.google.com", None, None, "DNS")
    assert sum("google.com" in s for s in said) == 1, \
        [s for s in said if "google" in s]
    assert sum("site7.example" in s for s in said) == 1
    ae = m.alerts
    for i in range(ae.DEBOUNCE_KEEP + 50):
        t[0] += 1
        ae._debounced(f"dnschg:{i}", 600)
    assert len(ae._debounce) <= ae.DEBOUNCE_KEEP
    assert ae._debounced(f"dnschg:{ae.DEBOUNCE_KEEP + 49}", 600)
    for i in range(600):
        ae._add("test_kind", "INFO", "", f"r{i}", "", "", [],
                subject=f"s{i}")
    assert len(ae.order) == 500 and len(ae._open) == 500, len(ae._open)


@self_test(slow=False)
def test_kernel_counters_and_coverage(ctx):
    """Kernel drops are summed when the OS reports them and shown as "not
    reported" (never as zero) when it doesn't. Coverage puts every packet
    in one bucket and says so in one sentence."""
    kc = KernelCounters()
    assert kc.poll(object()) is False and kc.supported is False
    assert kc.text() == "not reported by this capture method"
    if sys.platform.startswith("linux"):
        try:
            s = _socket.socket(_socket.AF_PACKET, _socket.SOCK_RAW,
                               _socket.htons(3))
        except (OSError, AttributeError):
            s = None
        if s is not None:
            try:
                s.bind(("lo", 0))
                src = types.SimpleNamespace(sock=types.SimpleNamespace(
                    ins=s))
                k2 = KernelCounters()
                assert k2.poll(src) and k2.supported
                assert k2.text() == "0" or k2.dropped >= 0
            finally:
                s.close()
    ring = RawRing(max_frames=3)
    for i in range(5):
        ring.put(b"x" * 10, i, 1, 1)
    w = types.SimpleNamespace(decoded=2, errors=0, stale=0)
    cov = pipeline_coverage(ring, w, kc, 0, [(10.0, 70.0, "asleep")])
    assert cov["received"] == 5 and cov["dropped_app"] == 2
    assert cov["in_flight"] == 3 and cov["kernel_dropped"] is None
    assert cov["gaps"] == 1 and cov["gap_seconds"] == 60
    txt, lvl = coverage_summary(cov)
    assert "2 dropped because analysis fell behind" in txt and \
        "1 capture gap" in txt and lvl == LV_UNKNOWN, txt
    clean = pipeline_coverage(RawRing(), types.SimpleNamespace(
        decoded=0, errors=0, stale=0), kc)
    txt, lvl = coverage_summary(clean)
    assert txt.startswith("Every packet received was analysed") and \
        "not reported" not in txt


@self_test(slow=False)
def test_pipeline_watchdog(ctx):
    """A stage holding work without progress for 10 s is reported once;
    it clears when it moves; idle stages are never 'stuck'."""
    wd = PipelineWatchdog()
    assert wd.check(0.0, {"analysis": (5, True), "window": (1, False)}) \
        == []
    assert wd.check(9.0, {"analysis": (5, True), "window": (1, False)}) \
        == []
    assert wd.check(10.5, {"analysis": (5, True),
                           "window": (1, False)}) == ["analysis"]
    assert wd.check(12.0, {"analysis": (5, True),
                           "window": (1, False)}) == [], "reported twice"
    assert "analysis stuck" in wd.text()
    assert wd.check(13.0, {"analysis": (9, True), "window": (1, False)}) \
        == []
    assert wd.text() == "all stages moving"
    assert wd.check(40.0, {"analysis": (9, False),
                           "window": (1, False)}) == [], "idle is fine"
    wd.beat = time.monotonic() - 30
    assert wd.window_frozen() >= 29
    wd.beat = time.monotonic()
    assert wd.window_frozen() == 0


@self_test()
def test_capture_gaps_presence_and_lifecycle(ctx):
    """Sleep or a capture restart becomes a visible gap: presence stops
    at the last sighting, the gap doesn't make devices 'leave', a device
    seen again gets a new presence stretch, and sessions keep the
    epochs."""
    cfg = ctx.cfg({"devices.idle_minutes": 2, "devices.inactive_minutes": 10,
                   "devices.expire_minutes": 60})
    clk = _FakeClock(100.0)
    m = NetworkModel(cfg, "192.168.1.1", {"192.168.1.2"}, set(),
                     now_fn=clk)
    m.set_identity(local_nets=[ipaddress.ip_network("192.168.1.0/24")])
    m.registry.now = clk
    m.epoch_open(100.0, "capture started")
    d = m.registry.touch("192.168.1.5", "00:11:22:33:44:55", "mac_local",
                         "x")
    assert d.presence[-1][1] is None
    entry = m.note_gap(200.0, 4000.0, "the computer was asleep")
    assert entry and "Capture gap" in entry["text"] and \
        "nothing was observed" in entry["text"]
    assert d.presence[-1][1] == 100.0, d.presence
    assert m.capture_gaps() == [(200.0, 4000.0, "the computer was asleep")]
    assert m.epochs[-1][1] is None and m.epochs[-1][0] == 4000.0
    clk.t = 4100.0
    inact, _ = m.registry.tick_lifecycle(4100.0)
    assert d not in inact and d.state != STATE_INACTIVE, \
        "sleep time counted as the device leaving"
    clk.t = 4150.0
    m.registry.touch("192.168.1.5", "00:11:22:33:44:55", "mac_local", "x")
    assert d.presence[-1] == [4150.0, None], d.presence
    assert m.note_gap(5000.0, 5000.5, "blip") is None, "sub-second gap"
    if ctx.scapy_ok:
        payload = json.loads(json.dumps(SessionCodec.serialize(m),
                                        default=str))
        m2 = NetworkModel(ctx.cfg())
        SessionCodec.load(payload, m2)
        assert m2.capture_gaps() == m.capture_gaps()


@self_test(needs_source=True)
def test_scenarios_and_demo_without_scapy(ctx):
    """With scapy blocked: the scripted network builds, decodes and passes
    every golden check through the fast decoder, and Demo Mode's
    generator produces frames that all decode. With scapy present: every
    scripted frame is byte-identical to scapy's own build."""
    code = r'''
import sys, importlib.abc, importlib.util, os, tempfile, time
class Block(importlib.abc.MetaPathFinder):
    def find_spec(self, name, path, target=None):
        if name == "scapy" or name.startswith("scapy."):
            raise ImportError("blocked for the test")
sys.meta_path.insert(0, Block())
sys.argv = ["x", "--bench"]
spec = importlib.util.spec_from_file_location("mw", os.environ["MW_FILE"])
mw = importlib.util.module_from_spec(spec)
sys.modules["mw"] = mw
spec.loader.exec_module(mw)
assert mw.Ether is None
cfg = mw.AppConfig(path=os.path.join(tempfile.mkdtemp(), "c.json"))
m = mw.scenario_model(cfg, mw.ScenarioBuilder().home_network())
fails = mw.golden_checks(m)
assert not fails, fails
got = []
def sink(raw, ts, lt, cancelled=lambda: False):
    got.append((raw, ts, lt))
    return True
g = mw.DemoGenerator(sink)
g.start()
t_end = time.time() + 20
while len(got) < 60 and time.time() < t_end:
    time.sleep(0.05)
g.stop()
assert len(got) >= 60, len(got)
reasm = mw.TlsReassembler()
for raw, ts, lt in got:
    mw.fast_decode(raw, ts, lt, reasm)
print("OK", len(m.registry.by_key), len(got))
'''
    env = dict(os.environ, MW_FILE=os.path.abspath(__file__),
               MINIWIRESHARK_DATA=ctx.path("noscapy-data"))
    r = subprocess.run([sys.executable, "-I", "-c", code], env=env,
                       capture_output=True, text=True, timeout=120)
    assert r.returncode == 0 and "OK" in r.stdout, (r.stdout[-500:],
                                                    r.stderr[-1500:])
    if ctx.scapy_ok:
        import scapy.all as _sa

        class _Scapy:
            pass
        for n in [k for k in dir(PK) if not k.startswith("_")]:
            setattr(_Scapy, n, getattr(_sa, n))
        ours = ScenarioBuilder().home_network() + \
            ScenarioBuilder().vlan_ping()
        theirs = ScenarioBuilder(layers=_Scapy).home_network() + \
            ScenarioBuilder(layers=_Scapy).vlan_ping()
        diff = [i for i, (a, b) in enumerate(zip(ours, theirs))
                if a[0] != b[0]]
        assert len(ours) == len(theirs) and not diff, diff[:5]


def _dissect_corpus():
    return ScenarioBuilder().home_network() + \
        ScenarioBuilder(t0=SCENARIO_T0 + 5000).protocol_tour()


@self_test(slow=False)
def test_dissector_registry_and_corpus(ctx):
    """Every field the dissectors declare appears in the corpus; every
    field's bytes lie inside its frame; checksums verify; nothing in the
    corpus is flagged as malformed."""
    seen = set()
    for raw, ts, lt in _dissect_corpus():
        d = dissect(raw, lt)
        assert not d.warnings(), (d.warnings(), d.text()[:400])
        seen |= d.keys()
        for f in d.all_fields():
            assert 0 <= f.offset and f.offset + f.length <= len(raw), f
            assert f.key in FIELD_REGISTRY, f.key
            if f.key.endswith("checksum.status"):
                assert f.raw_value in ("correct", "none (allowed for UDP "
                                       "over IPv4)"), (f, d.text()[:300])
    missing = sorted(set(FIELD_REGISTRY) - seen)
    assert not missing, f"declared but never seen: {missing}"
    tour = ScenarioBuilder(t0=SCENARIO_T0).protocol_tour()
    d = dissect(tour[0][0])
    assert d.get("vlan.id") == 20 and d.get("icmp.type") == 8
    syn = dissect(tour[3][0])
    assert syn.get("tcp.options.mss_val") == 1460 and \
        syn.get("tcp.options.wscale.shift") == 7
    sll = dissect(tour[-1][0], 113)
    assert sll.get("dns.qry.name") == "example.org"
    home = ScenarioBuilder().home_network()
    names = {dissect(r).get("tls.handshake.extensions_server_name")
             for r, _t, _l in home} - {None}
    assert {"www.example.com", "video.example.net", "dns.google"} <= names
    hosts = {dissect(r).get("dhcp.option.hostname") for r, _t, _l in home}
    assert "Alex-iPhone" in hosts and "ESP_6A1B2C" in hosts


@self_test(slow=False)
def test_dissector_never_raises(ctx):
    """Every prefix of a frame and thousands of mutated frames dissect
    without an exception; a frame cut inside a header says so."""
    rnd = random.Random(11)
    corpus = _dissect_corpus()
    for raw, ts, lt in corpus[:60:7]:
        for n in range(0, len(raw), max(1, len(raw) // 40)):
            dissect(raw[:n], lt)
    cut = dissect(corpus[40][0][:30])
    assert any("truncated" in w for _t, w in cut.warnings()), cut.warnings()
    for i in range(3000):
        raw, ts, lt = corpus[rnd.randrange(len(corpus))]
        b = bytearray(raw)
        for _ in range(rnd.randint(1, 6)):
            b[rnd.randrange(len(b))] = rnd.randrange(256)
        if rnd.random() < 0.3:
            b = b[:rnd.randrange(len(b) + 1)]
        dissect(bytes(b), lt)
    for n in range(200):
        dissect(bytes(rnd.randrange(256) for _ in range(rnd.randint(0, 120))),
                rnd.choice((1, 101, 113, 0)))


