@self_test()
def t_json_pieces_and_fast_switch(ctx):
    """Reading a session in pieces gives exactly json.loads' result (and
    its errors); the 1 ms switch interval is held while anyone needs it
    and given back after."""
    cases = [{}, [], "s", 3, None, [[], [[]], {}],
             {"a": [1, 2, {"b": []}], "c": "x\\\"y", "d": None,
              "e": {"f": {"g": [1.5, -2e3, True]}}, "é": "ü"}]
    for c in cases:
        for text in (json.dumps(c), json.dumps(c, indent=2),
                     json.dumps(c, ensure_ascii=False)):
            assert json_loads_pieces(text) == json.loads(text), text
    for bad in ("{", "[1,", '{"a" 1}', "[1 2]", "{} x", "", '{"a":1,}'):
        try:
            json_loads_pieces(bad)
        except ValueError:
            continue
        raise AssertionError(f"accepted {bad!r}")
    m = scenario_model(ctx.cfg(), ctx.frames())
    text = json.dumps(SessionCodec.serialize(m), separators=(",", ":"))
    assert json_loads_pieces(text) == json.loads(text)
    p = ctx.path("s.mwsession.json")
    atomic_write_text(p, text)
    assert read_session_payload(p) == json.loads(text)
    before = sys.getswitchinterval()
    try:
        fast_switch("t1", True)
        fast_switch("t2", True)
        assert abs(sys.getswitchinterval() - 0.001) < 1e-6
        fast_switch("t1", False)
        assert abs(sys.getswitchinterval() - 0.001) < 1e-6
        fast_switch("t2", False)
        assert abs(sys.getswitchinterval() - _NORMAL_SWITCH[0]) < 1e-6
    finally:
        _FAST_SWITCH_USERS.discard("t1")
        _FAST_SWITCH_USERS.discard("t2")
        sys.setswitchinterval(before)


@self_test()
def t_capture_over_bytes(ctx):
    """Counting a capture's packets from the record headers in memory:
    pcap (both byte orders) and pcapng, at the limit, over it, and a
    file cut short."""
    def pcap(n, big=False):
        e = ">" if big else "<"
        out = struct.pack(e + "IHHiIII", 0xa1b2c3d4, 2, 4, 0, 0, 65535, 1)
        for i in range(n):
            data = bytes(60 + i % 7)
            out += struct.pack(e + "IIII", i, 0, len(data), len(data)) + data
        return out

    def pcapng(n):
        shb = struct.pack("<IIIHHqI", 0x0A0D0D0A, 28, 0x1A2B3C4D, 1, 0, -1,
                          28)
        idb = struct.pack("<IIHHII", 1, 20, 1, 0, 65535, 20)
        out = shb + idb
        for i in range(n):
            data = bytes(61 + i % 5)
            pad = (-len(data)) % 4
            blen = 32 + len(data) + pad
            out += struct.pack("<IIIIIII", 6, blen, 0, 0, i, len(data),
                               len(data)) + data + bytes(pad) + \
                struct.pack("<I", blen)
        return out
    for make in (pcap, lambda n: pcap(n, True), pcapng):
        for n, limit, want in ((10, 10, False), (11, 10, True),
                               (0, 0, False), (500, 3, True)):
            b = make(n)
            assert capture_over_bytes(b, len(b), limit) is want, (n, limit)
        b = make(30)
        assert capture_over_bytes(b[:-7], len(b) - 7, 100) is False
    assert capture_over_bytes(b"nope", 4, 3) is None
    p = ctx.path("c.pcap")
    with open(p, "wb") as f:
        f.write(pcap(12))
    class _A:
        pass
    a = _A()
    assert MiniWireshark.capture_over(a, p, 11) is True
    assert MiniWireshark.capture_over(a, p, 12) is False


@self_test()
def t_big_file_flush_parts(ctx):
    """A table refresh takes at most FLUSH_MAX changed rows and leaves the
    rest for the next tick (none lost, none twice); the cycle collector's
    full pass is rarer while packets pour in and normal again after."""
    class M:
        pass
    m = M()
    m.dirty_devices = set(range(600))
    seen = set()
    while m.dirty_devices:
        part = MiniWireshark._take_dirty(m, "dirty_devices")
        assert len(part) <= MiniWireshark.FLUSH_MAX
        assert not (part & seen)
        seen |= part
    assert seen == set(range(600))
    m.dirty_devices = {1, 2}
    assert MiniWireshark._take_dirty(m, "dirty_devices") == {1, 2}
    assert m.dirty_devices == set()
    t0 = gc.get_threshold()
    try:
        busy_gc(True)
        if FEATURES.get("gc_freeze", True):
            assert gc.get_threshold()[2] >= 50
        busy_gc(False)
        assert gc.get_threshold() == (_GC_NORMAL[0] or t0)
    finally:
        gc.set_threshold(*t0)


@self_test()
def t_text_widths_remembered(ctx):
    """rc.11: interface text widths are kept between starts per font and
    screen setup; another font under the same name (probe width differs)
    or another screen setup starts afresh; data texts are never written;
    off with the warm_start switch."""
    class FakeFont:
        def __init__(self, family="Sans", k=7):
            self.family, self.k, self.calls = family, k, 0

        def actual(self):
            return {"family": self.family, "size": 10, "weight": "normal",
                    "slant": "roman"}

        def measure(self, text):
            self.calls += 1
            return len(text) * self.k
    path = ctx.path("tw.json")
    tw = TextWidths(path)
    tw.loaded, tw.env = True, "scaling|x11|8.6|linux"
    f = FakeFont()
    assert tw.width(f, "Device") == 42
    assert tw.width(f, "Device") == 42 and f.calls == 2     # probe + one
    assert tw.width(f, "nas-kitchen.local", keep=False) == 17 * 7
    assert tw.save() and not tw.save()              # only when changed
    data = read_json(path, {})
    kept = next(iter(data["fonts"].values()))["w"]
    assert "Device" in kept and "nas-kitchen.local" not in kept
    # the next start: no measuring but the probe
    tw2 = TextWidths(path)
    tw2.env_key = lambda widget=None: "scaling|x11|8.6|linux"
    assert tw2.load() == 1
    f2 = FakeFont()
    assert tw2.width(f2, "Device") == 42 and f2.calls == 1
    assert tw2.hits == 1 and tw2.misses == 0
    # same name, different font: thrown away and measured again
    tw3 = TextWidths(path)
    tw3.env_key = lambda widget=None: "scaling|x11|8.6|linux"
    tw3.load()
    f3 = FakeFont(k=8)
    assert tw3.width(f3, "Device") == 48 and tw3.misses == 1
    # another screen setup: nothing is used
    tw4 = TextWidths(path)
    tw4.env_key = lambda widget=None: "2.0|win32|8.6|win32"
    assert tw4.load() == 0
    # broken file: ignored
    with open(path, "w") as fh:
        fh.write("{not json")
    tw5 = TextWidths(path)
    tw5.env_key = lambda widget=None: "scaling|x11|8.6|linux"
    assert tw5.load() == 0 and tw5.width(FakeFont(), "Ab") == 14
    # switched off: plain measuring, nothing written
    old = FEATURES["warm_start"]
    try:
        FEATURES["warm_start"] = False
        tw6 = TextWidths(ctx.path("tw6.json"))
        f6 = FakeFont()
        assert tw6.width(f6, "Device") == 42 and f6.calls == 1
        tw6.dirty = True
        assert not tw6.save() and not os.path.exists(ctx.path("tw6.json"))
    finally:
        FEATURES["warm_start"] = old


@self_test()
def t_warm_up_on_the_loading_screen(ctx):
    """rc.11: the first start measures the computer's speed on the loading
    screen (not 6 s into the window); later starts do not, unless the
    number of cores changed; the capture start no longer sleeps 0.2 s."""
    class FakeLoader:
        def __init__(self):
            self.steps, self.health, self.pumps = [], None, 0

        def warm_step(self, text, pct=None, live=True):
            self.steps.append(text)

        def pump(self):
            self.pumps += 1

        def post_progress(self, p):
            pass

        def post_health(self, kind):
            self.health = kind
    cfg = AppConfig(path=ctx.path("warm.json"))
    assert needs_calibration(cfg)
    real = globals()["calibrate"]
    ran = []

    def fake(seconds=1.5):
        ran.append(seconds)
        time.sleep(0.05)
        return 12345.0
    globals()["calibrate"] = fake
    real_tw = globals()["TEXT_WIDTHS"]
    globals()["TEXT_WIDTHS"] = TextWidths(ctx.path("tw.json"))
    real_prep = globals()["prepare_compiled_copy"]
    globals()["prepare_compiled_copy"] = lambda popen=None, cfg=None: None
    try:
        ld = FakeLoader()
        done = warm_up_before_window(ld, cfg)
        assert ran == [1.5] and done.get("calibration_pps") == 12345
        assert any("speed" in (t or "") for t in ld.steps), ld.steps
        assert ld.pumps >= 1 and ld.health in ("healthy", "degraded")
        cal = cfg.get("performance.calibration")
        assert cal["pps"] == 12345 and cal["cores"] == (os.cpu_count() or 1)
        assert not needs_calibration(cfg)
        assert read_json(ctx.path("warm.json"), {})["performance"][
            "calibration"]["pps"] == 12345            # saved
        warm_up_before_window(FakeLoader(), cfg)
        assert ran == [1.5]                            # not again
        cfg.set("performance.calibration", dict(cal, cores=999))
        assert needs_calibration(cfg)                  # another computer
        old = FEATURES["warm_start"]
        try:
            FEATURES["warm_start"] = False
            assert warm_up_before_window(FakeLoader(), cfg) == {}
            assert ran == [1.5]
        finally:
            FEATURES["warm_start"] = old
    finally:
        globals()["calibrate"] = real
        globals()["TEXT_WIDTHS"] = real_tw
        globals()["prepare_compiled_copy"] = real_prep
    assert not store_calibration(cfg, 0)
    # the compiled copy for helpers: written by a helper only when missing
    started = []
    real_path = globals()["compiled_copy_path"]
    try:
        globals()["compiled_copy_path"] = lambda: ctx.path("none.pyc")
        if not compiled_copy_trusted():
            # root (or a shared folder) never keeps one: no helper either
            assert prepare_compiled_copy(
                popen=lambda cmd, **kw: started.append(cmd)) is None
            assert not started
            raise _NoCopyHere
        assert prepare_compiled_copy(
            popen=lambda cmd, **kw: started.append((cmd, kw)) or "proc") \
            == "proc"
        assert WORKER_FLAG in started[0][0]
        assert started[0][1]["env"]["MW_CACHED"] == "1"
        assert started[0][1]["stdin"] == subprocess.DEVNULL
        fresh = ctx.path("fresh.pyc")
        keep_compiled_copy(compile("x = 1\n", SCRIPT_PATH, "exec"), fresh)
        globals()["compiled_copy_path"] = lambda: fresh
        assert prepare_compiled_copy(
            popen=lambda cmd, **kw: started.append(cmd)) is None
        assert len(started) == 1
        # with the settings: one try per version of the file, not per start
        globals()["compiled_copy_path"] = lambda: ctx.path("none2.pyc")
        c2 = AppConfig(path=ctx.path("tried.json"))
        fake = lambda cmd, **kw: started.append(cmd) or "proc"   # noqa: E731
        assert prepare_compiled_copy(popen=fake, cfg=c2) == "proc"
        assert prepare_compiled_copy(popen=fake, cfg=c2) is None
        assert len(started) == 2
    except _NoCopyHere:
        pass
    finally:
        globals()["compiled_copy_path"] = real_path
    # the capture start: the first quiet wait ends it, not a 0.2 s sleep
    if not ctx.scapy_ok or conf is None:
        return

    class QuietSock:
        closed = False

        @staticmethod
        def select(socks, timeout):
            time.sleep(min(timeout, 0.02))
            return []

        def recv_raw(self, n):
            return None

        def close(self):
            self.closed = True

    class BadSock(QuietSock):
        @staticmethod
        def select(socks, timeout):
            raise OSError("adapter went away")
    real_listen = conf.L2listen
    try:
        conf.L2listen = lambda **kw: QuietSock()
        t0 = time.perf_counter()
        src, err = start_capture_source("lo", None, False, lambda *a: None)
        took = time.perf_counter() - t0
        assert src is not None and err is None
        assert took < 0.15, took
        src.stop()
        rc = RawCapture("lo", None, False, lambda *a: None)
        conf.L2listen = lambda **kw: BadSock()
        rc.start()
        assert rc.first_cycle.wait(2.0)
        assert isinstance(rc.exception, OSError)
        rc.stop()
    finally:
        conf.L2listen = real_listen


class _NoCopyHere(Exception):
    pass


def _cached_run(script, pyc, key):
    """Run CACHED_RUN on `script` with this copy and key -> its output."""
    env = dict(os.environ, MW_PYC=pyc, MW_KEY=key)
    r = _run_hidden([sys.executable, "-c", CACHED_RUN, script],
                       capture_output=True, env=env, timeout=60)
    return r.stdout.decode().strip()


@self_test()
def t_rt01_compiled_copy_forgery(ctx):
    """5.3.4 (RT-01): a planted compiled copy with the right header but no
    valid HMAC runs nothing: the source runs instead. So does a copy in a
    folder others can write, a key others can read, and any copy at all
    when the start is root. A copy MiniWireshark made itself still loads."""
    if IS_WINDOWS:
        return
    import hmac
    import importlib._bootstrap_external as be
    folder = ctx.path("rt01")
    os.makedirs(folder, mode=0o700, exist_ok=True)
    os.chmod(folder, 0o700)
    script = os.path.join(folder, "s.py")
    with open(script, "w", encoding="utf-8") as f:
        f.write("print('source')\n")
    key_path = os.path.join(folder, "k")
    key = os.urandom(32)
    fd = os.open(key_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "wb") as f:
        f.write(key)
    st = os.stat(script)
    data = be._code_to_timestamp_pyc(
        compile("print('cached')", script, "exec"), st.st_mtime, st.st_size)
    head, body = bytes(data[:16]), bytes(data[16:])
    good = os.path.join(folder, "good.pyc")
    forged = os.path.join(folder, "forged.pyc")
    with open(good, "wb") as f:
        f.write(head + hmac.new(key, body, hashlib.sha256).digest() + body)
    with open(forged, "wb") as f:
        f.write(head + bytes(32) + body)
    if os.geteuid() == 0:
        assert _cached_run(script, good, key_path) == "source"
        return
    assert _cached_run(script, good, key_path) == "cached"
    assert _cached_run(script, forged, key_path) == "source"
    os.chmod(key_path, 0o644)
    assert _cached_run(script, good, key_path) == "source"
    os.chmod(key_path, 0o600)
    os.chmod(folder, 0o770)
    try:
        assert _cached_run(script, good, key_path) == "source"
        assert not compiled_copy_trusted(good)
    finally:
        os.chmod(folder, 0o700)
    assert compiled_copy_trusted(good)


@self_test()
def t_m1a_data_trust(ctx):
    """5.3.4 M1a: a data, packages or cache folder someone else owns or
    can write to is refused (OS-04, LG-10, RT-06); a rollback copies only
    the backup this install wrote, under an authentic marker (RT-02)."""
    if IS_WINDOWS:
        return
    mine = ctx.path("m1a-mine")
    os.makedirs(mine, exist_ok=True)
    os.chmod(mine, 0o777)
    assert not private_dir_ok(mine)
    assert private_dir_ok(mine, fix=True)
    assert os.stat(mine).st_mode & 0o777 == 0o700
    assert not private_dir_ok(ctx.path("m1a-missing"))
    if os.geteuid() == 0:
        theirs = ctx.path("m1a-theirs")
        os.makedirs(theirs, exist_ok=True)
        os.chown(theirs, 65534, 65534)
        assert not private_dir_ok(theirs, fix=True)
        os.environ["MINIWIRESHARK_DATA"], old = theirs, \
            os.environ.get("MINIWIRESHARK_DATA")
        try:
            p = AppPaths()
            assert p.data != theirs and theirs in p.skipped
        finally:
            if old is None:
                os.environ.pop("MINIWIRESHARK_DATA", None)
            else:
                os.environ["MINIWIRESHARK_DATA"] = old
    # RT-06: packages from a folder whose parent others can write: unused
    parent = ctx.path("m1a-site")
    root = os.path.join(parent, "tag")
    os.makedirs(root, exist_ok=True)
    os.chmod(parent, 0o777)
    before = list(sys.path)
    try:
        assert PrivatePackages(root=root).activate() is False
        assert root not in sys.path
        os.chmod(parent, 0o700)
        assert PrivatePackages(root=root).activate() is True
        assert sys.path[-1] == root and sys.path[:len(before)] == before
    finally:
        sys.path[:] = before
        os.chmod(parent, 0o700)
    # RT-02
    script = ctx.path("m1a-mw.py")
    with open(script, "w", encoding="utf-8") as f:
        f.write("new\n")
    backup = f"{script}.v1.0.0.bak"
    with open(backup, "w", encoding="utf-8") as f:
        f.write("old\n")
    evil = ctx.path("m1a-evil.py")
    with open(evil, "w", encoding="utf-8") as f:
        f.write("evil\n")
    m = {"script": script, "from": "1.0.0", "version": "2.0.0",
         "backup": backup, "sha256": sha256_file(script),
         "backup_sha256": sha256_file(backup)}
    m["mac"] = update_marker_mac(m)
    assert m["mac"] and rollback_source_ok(m, script)[0]
    assert not rollback_source_ok(dict(m, backup=evil), script)[0]
    assert not rollback_source_ok(dict(m, version="6.6.6"), script)[0]
    assert not rollback_source_ok(dict(m, mac="0" * 64), script)[0]
    legacy = {k: v for k, v in m.items() if k not in ("mac",
                                                       "backup_sha256")}
    # (review) without an HMAC only an older release updating to this
    # very version: never a marker naming another version
    assert not rollback_source_ok(legacy, script)[0]
    legacy["version"] = SCRIPT_VERSION
    assert rollback_source_ok(legacy, script)[0]
    assert not rollback_source_ok(dict(legacy, **{"from": "5.3.4"}),
                                  script)[0]
    assert not rollback_source_ok(dict(legacy, backup=evil), script)[0]
    with open(backup, "a", encoding="utf-8") as f:
        f.write("planted\n")
    assert not rollback_source_ok(m, script)[0]
    os.chmod(backup, 0o666)
    assert not rollback_source_ok(legacy, script)[0]


@self_test()
def t_m1a_elevation(ctx):
    """5.3.4 (LG-09): Linux and macOS ask for root only when a capture is
    about to start; with the capture capability not at all; a refused
    password carries on (False) instead of closing the program, and asks
    once; a copy that really started ends this one with its code."""
    assert wants_capture("monitor", ctx.cfg({}))
    assert not wants_capture("demo", ctx.cfg({}))
    assert not wants_capture("guide", ctx.cfg({}))
    assert wants_capture(None, ctx.cfg({"general.auto_start_capture":
                                        True})) != START_IN_DEMO
    assert not wants_capture(None, ctx.cfg({"general.auto_start_capture":
                                            False}))
    if IS_WINDOWS or IS_MAC:
        return
    assert isinstance(has_capture_rights(), bool)
    assert needs_elevation() is (not has_capture_rights())
    if os.geteuid() == 0:
        assert has_capture_rights()
    calls = []
    real_which, real_call = shutil.which, subprocess.call

    def refused(cmd, *a, **kw):
        calls.append(cmd)
        return 126

    def accepted(cmd, *a, **kw):
        calls.append(cmd)
        flag = next(x for x in cmd if x.startswith(ELEV_FLAG_ARG))
        assert DATA_ARG + PATHS.data in cmd and START_ARG + "monitor" in cmd
        with open(flag[len(ELEV_FLAG_ARG):], "w", encoding="utf-8") as f:
            f.write("1")
        return 3
    try:
        shutil.which = lambda n: "/usr/bin/" + n if n in (
            "pkexec", "sudo") else None
        subprocess.call = refused
        assert _relaunch_elevated((START_ARG + "monitor",)) is False
        assert len(calls) == 1 and calls[0][0] == "pkexec"
        # a launcher that ran but didn't start the program: no second
        # password prompt
        calls.clear()
        subprocess.call = lambda cmd, *a, **k: calls.append(cmd) or 1
        assert _relaunch_elevated((START_ARG + "monitor",)) is False
        assert len(calls) == 1, calls
        subprocess.call = accepted
        try:
            _relaunch_elevated((START_ARG + "monitor",))
            raise AssertionError("did not end after the elevated copy")
        except SystemExit as e:
            assert e.code == 3
        assert not [f for f in os.listdir(tempfile.gettempdir())
                    if f.startswith(ELEV_DIR_PREFIX)]
        # the elevated copy creates its flag only in such a folder
        d = tempfile.mkdtemp(prefix=ELEV_DIR_PREFIX)
        assert elev_flag_ok(os.path.join(d, "started"))
        assert not elev_flag_ok(os.path.join(d, "other"))
        assert not elev_flag_ok(os.path.join(PATHS.data, "started"))
        assert not elev_flag_ok("/etc/" + ELEV_DIR_PREFIX + "x/started")
        if os.geteuid() != 0:
            assert not elev_flag_ok("/" + "started")
        os.rmdir(d)
    finally:
        shutil.which, subprocess.call = real_which, real_call


@self_test()
def t_m1b_pin_and_applescript(ctx):
    """5.3.4 (RT-04): a pinned helper whose certificate changed gets
    nothing, not even the request line, let alone the password.
    (RT-07, OS-05): the macOS password prompt never pastes the program's
    path into AppleScript, so quotes and apostrophes are just text."""
    import http.client
    sent = []

    class Sock:
        @staticmethod
        def getpeercert(binary_form=False):
            return b"the attacker's certificate"

    class FakeConn:
        def __init__(self, *a, **kw):
            self.sock = None

        def connect(self):
            self.sock = Sock()

        def request(self, *a, **kw):
            sent.append((a, kw))

        def close(self):
            pass
    real = http.client.HTTPSConnection
    try:
        http.client.HTTPSConnection = FakeConn
        try:
            connector_http("POST", "https://192.168.1.2/api/auth",
                           body=b'{"password": "secret"}', pin="ab" * 32)
            raise AssertionError("a changed certificate was accepted")
        except ConnectorError as e:
            assert e.kind == "tls", (e.kind, e)
    finally:
        http.client.HTTPSConnection = real
    assert sent == [], sent
    path = '/Users/k/Krystel\'s "Mac"/a" & (do shell script "x") & "'
    cmd = mac_admin_cmd(["/usr/bin/python3", path, "--x"])
    assert cmd[:7] == ["osascript", "-e", "on run argv", "-e",
                       "do shell script (item 1 of argv) with "
                       "administrator privileges", "-e", "end run"]
    assert len(cmd) == 8 and shlex.split(cmd[7]) == [
        "/usr/bin/python3", path, "--x"]


