@self_test()
def test_deep_worker_process_and_mode_switching(ctx):
    """A real worker process gives the same findings as the thread; and
    switching Normal ↔ Full Power 50 times during a replay leaves the
    model exactly as a single-mode run (depth never changes the model)."""
    frames = ScenarioBuilder().home_network()
    rows = _deep_rows(frames)
    res = {}
    runners = [False] + ([True] if (os.cpu_count() or 1) > 1 else [])
    for proc in runners:
        e = DeepEngine()
        e.configure("Full Power", cores=1, prefer_process=proc)
        e._ensure_backend()
        assert e.backend == ("process" if proc else "thread"), e.last_error
        for d in rows:
            e.offer(d, d["no"])
        assert e.drain(30), e.status_text()
        res[proc] = sorted(e.store.findings)
        e.stop()
    if len(res) == 2:
        assert res[True] == res[False]

    def summary(m):
        return (sorted((d.key, d.device_class, d.ip) for d in
                       m.registry.by_key.values()),
                sorted(m.websites), len(m.flows.all_flows()),
                sorted(a.kind for a in m.alerts.alerts.values()))

    def run(toggle):
        gw, ips, macs, nets = scenario_identity()
        m = NetworkModel(ctx.cfg(), gw, ips, macs)
        m.set_identity(local_nets=nets)
        m.use_packet_clock = True
        h = _PipelineHarness(m)
        h.deep = DeepEngine()
        flip = [0]

        def sync():
            flip[0] += 1
            mode = ("Full Power" if flip[0] % 2 else "Normal") if toggle \
                else "Normal"
            h.deep.configure(mode, cores=1, prefer_process=False)
            if h.deep.active():
                h.deep._ensure_backend()
        h.sync_deep = sync
        w = AnalysisWorker(h, GuiGate())
        w.BATCH = max(1, len(frames) // 55)
        w.start()
        sink = h.sink()
        for raw, ts, lt in frames:
            sink(raw, ts, lt)
        t_end = time.time() + 60
        while (len(h.ring) or w.busy or h.count < len(frames)) and \
                time.time() < t_end:
            time.sleep(0.01)
        w.stop_flag = True
        w.join(2)
        m.tick()
        m._announce_created(flush=True)
        e = h.deep
        e.drain(10)
        assert e.offered == e.done + e.shed + e.lost + e.in_flight()
        e.stop()
        return summary(m), flip[0], e.offered
    plain, _n, off0 = run(False)
    mixed, flips, off1 = run(True)
    assert off0 == 0 and off1 > 0 and flips >= 50, (off0, off1, flips)
    assert mixed == plain


@self_test(slow=False)
def test_protocol_exchanges(ctx):
    """M5: requests are paired with replies (with latency), retries and
    unanswered lookups are counted, handshakes are followed, and nothing
    private leaves the tracker."""
    fr = ScenarioBuilder().protocol_exchanges()
    an = DeepAnalyzer(my_ips={ScenarioBuilder.ME[0]})
    tx, fs = [], []
    for i, (raw, ts, lt) in enumerate(fr):
        f, _m, t = an.process(i + 1, ts, lt, raw)
        tx += t
        fs += f
    _m, t, f = an.flush(fr[-1][1], True)
    tx += t
    fs += f
    by = defaultdict(list)
    for t in tx:
        by[t["kind"]].append(t)
        marshal.dumps(t)                   # must cross the worker pipe
    dns = {t["name"]: t for t in by["dns"]}
    assert dns["a.example.com"]["latency_ms"] == 25.0
    assert dns["slow.example.com"]["tries"] == 2
    assert dns["lost.example.com"]["result"] == "no answer"
    assert dns["nope.example.com"]["result"] == "no such name"
    d = by["dhcp"][0]
    assert d["steps"] == "Discover → Offer → Request → ACK" and \
        d["lease_s"] == 7200 and d["host"] == "Living-Room-TV"
    tls = by["tls"][0]
    assert tls["version"] == "TLS 1.3" and tls["name"] == "www.example.com"
    http = sorted((t["path"], t["status"]) for t in by["http"])
    assert http == [("/index.html", 200), ("/missing", 404)], http
    assert by["ssh"][0]["server_banner"].startswith("SSH-2.0-dropbear")
    assert sorted(t["dialect"] for t in by["smb"]) == ["1 (obsolete)",
                                                       "3.1.1"]
    assert by["mqtt"][0]["result"] == "refused: not authorized"
    assert abs(by["ntp"][0]["offset_ms"] - 50.0) < 1.0
    assert {t.get("status") or t.get("method") for t in by["sip"]} == \
        {"INVITE", 486}
    assert len(by["rtsp"]) == 2
    text = repr(tx) + repr(fs)
    assert "SECRET" not in text and "session=" not in text
    groups = " | ".join(f[4] for f in fs)
    for want in ("More than one DHCP server", "SMB version 1",
                 "MQTT broker", "SIP 486"):
        assert want in groups, (want, groups)
    assert sum(1 for f in fs if "SMB version 1" in f[4]) == 1


@self_test(slow=False)
def test_mail_sessions_metadata_only(ctx):
    """M6: SMTP, IMAP and POP3 sessions are followed (logins counted,
    STARTTLS noticed, failures and risky logins flagged) while no content,
    password or address ever leaves the parser."""
    fr = ScenarioBuilder().mail_sessions()
    an = DeepAnalyzer(my_ips={ScenarioBuilder.ME[0]})
    tx, fs, ms = [], [], []
    for i, (raw, ts, lt) in enumerate(fr):
        f, m, t = an.process(i + 1, ts, lt, raw)
        tx += t
        fs += f
        ms += m
    m, t, f = an.flush(fr[-1][1], True)
    tx, fs, ms = tx + t, fs + f, ms + m
    mail = {(t["proto"], t.get("port")): t for t in tx
            if t["kind"] == "mail"}
    smtp = mail[("SMTP", 25)]
    assert smtp["auth_attempts"] == 3 and smtp["auth_failures"] == 3
    assert smtp["rcpt"] == 2 and smtp["messages"] == 1 and \
        smtp["auth_before_tls"] and smtp["starttls_offered"]
    assert mail[("SMTP", 587)]["encryption"].startswith("upgraded")
    imap = mail[("IMAP", 143)]
    assert imap["auth_ok"] == 1 and imap["auth_failures"] == 1 and \
        imap["commands"].get("SELECT") == 1
    pop = mail[("POP3", 110)]
    assert pop["auth_ok"] == 1 and pop["auth_failures"] == 1
    assert mail[("IMAP", 993)]["encryption"] == "encrypted from the start"
    assert mail[("webmail", 443)]["result"] == "contacted"
    assert mail[("SMTP", 2526)]["proto"] == "SMTP", "found by its greeting"
    text = " | ".join(f[4] for f in fs)
    for want in ("SMTP login to 198.51.100.25 before encryption",
                 "failed to log in to the mail server 198.51.100.25 3",
                 "offered encryption (STARTTLS) but"):
        assert want in text, (want, text)
    blob = repr(tx) + repr(fs) + repr(ms)
    assert ScenarioBuilder.CANARY not in blob, "secret leaked from parser"
    assert "example.com>" not in blob and "@example" not in blob
    for raw, ts, lt in fr:
        assert ScenarioBuilder.CANARY not in dissect(raw, lt).text()

class _FilterCtx:
    """Just enough of FilterContext for filter tests."""

    def __init__(self, findings=None):
        self._f = findings or {}

    def dissection(self, d):
        return dissect(d["raw"], d.get("linktype", 1))

    def expert_severities(self, d):
        return [x if isinstance(x, str) else x[0]
                for x in self._f.get(d["no"], [])]

    def expert_info(self, d, i):
        return [x[i] for x in self._f.get(d["no"], [])
                if not isinstance(x, str)]

    def time_zero(self):
        return SCENARIO_T0


@self_test(slow=False)
def test_field_filter_language(ctx):
    """M8: field expressions with the registry's names, combined with
    and/or/not and parentheses; bad expressions fail at compile time with
    a helpful message; the friendly V4 tokens still work."""
    frames = ScenarioBuilder().home_network() + \
        ScenarioBuilder(t0=SCENARIO_T0 + 9000).protocol_exchanges()
    rows = _deep_rows(frames)
    c = _FilterCtx({rows[0]["no"]: ["warn"], rows[1]["no"]: ["chat"]})

    def count(expr):
        f = FieldFilter(expr)
        return sum(1 for d in rows if f.match(d, c))
    n_dns = sum(1 for d in rows if 53 in (d["sport"], d["dport"]))
    assert count("udp.port == 53 or tcp.port == 53") == n_dns
    assert count("ip.src == 192.168.1.23") == sum(
        1 for d in rows if d["src_ip"] == "192.168.1.23")
    assert count("ip.addr == 192.168.1.0/24") > 0
    assert count('dns.qry.name contains "example"') > 0
    assert count('tls.handshake.extensions_server_name == '
                 '"www.example.com"') >= 1
    assert count("frame.len > 1000 and not tcp") == sum(
        1 for d in rows if d["length"] > 1000 and d["transport"] != "TCP")
    assert count("smtp") == 0 and count("ssh") > 0
    assert count("(tcp.flags.syn == 1) && !(tcp.flags.ack == yes)") == sum(
        1 for d in rows if d["tcp_flags"] is not None and
        d["tcp_flags"] & 2 and not d["tcp_flags"] & 16)
    assert count("expert.severity >= warning") == 1
    assert count("dhcp.option.hostname") > 0
    assert count("http.response.code == 404") == 1
    for bad, msg in (("ip.src ==", "needs a value"),
                     ("frame.len > big", "needs a number"),
                     ("nosuch.field == 1", "Unknown field"),
                     ("(tcp", "not closed"), ("tcp.port == 1 )", "Unexpected"),
                     ("expert.severity > loud", "chat, note")):
        try:
            FieldFilter(bad)
        except ValueError as e:
            assert msg in str(e), (bad, str(e))
        else:
            raise AssertionError(f"accepted: {bad}")
    assert FieldFilter.looks_like("dns and not mdns")
    assert not FieldFilter.looks_like("proto:tls site:example.com")
    assert not FieldFilter.looks_like("example")
    df = DisplayFilter(expr="tcp.port == 443")
    assert df.field is not None and df.active()
    assert DisplayFilter(expr="port:53").field is None

@self_test(slow=False)
def test_follow_stream_and_explain(ctx):
    """M7: a connection is rebuilt from the packets in memory with its
    gaps; mail and web streams are redacted by default; every packet gets
    a plain-language sentence; the protocol hierarchy adds up."""
    frames = ScenarioBuilder().protocol_exchanges() + \
        ScenarioBuilder(t0=SCENARIO_T0 + 99).mail_sessions()
    rows = _deep_rows(frames)
    key_of = {}
    fid = 0
    for d in rows:
        if d.get("sport") is None:
            continue
        k = tuple(sorted([(d["src_ip"], d["sport"]),
                          (d["dst_ip"], d["dport"])]))
        if k not in key_of:
            fid += 1
            key_of[k] = fid
        d["flow_id"] = key_of[k]
    http = next(v for k, v in key_of.items() if k[1][1] == 80 or
                k[0][1] == 80)
    r = follow_stream(rows, http)
    text = b"".join(c[2] for c in r.chunks if c[2] is not None)
    assert b"GET /index.html" in text and b"HTTP/1.1 404" in text
    assert r.client[1] == 41080 and r.server[1] == 80 and r.sensitive()
    red = "".join(redact_stream_line(line, r) for c in r.chunks if c[2]
                  for line in c[2].splitlines(True))
    assert "Cookie: (hidden)" in red and "SECRET" not in red.split(
        "GET /index.html?")[0]
    smtp = next(v for k, v in key_of.items() if 25 in (k[0][1], k[1][1]))
    r2 = follow_stream(rows, smtp)
    red2 = "".join(redact_stream_line(line, r2) for c in r2.chunks if c[2]
                   for line in c[2].splitlines(True))
    assert ScenarioBuilder.CANARY not in red2 and "command AUTH" in red2
    # a lost segment shows as a gap
    lost = [d for d in rows if d["flow_id"] != http or
            b"/missing" not in d["raw"]]
    r3 = follow_stream(lost, http)
    assert any(c[2] is None for c in r3.chunks), "gap not marked"
    udp = next(d["flow_id"] for d in rows if d["transport"] == "UDP" and
               d.get("flow_id"))
    assert follow_stream(rows, udp).transport == "UDP"
    for d in rows[:60]:
        s = explain_packet(dissect(d["raw"]))
        assert s and s.endswith((".", ")")), s
    arp = explain_packet(dissect(ScenarioBuilder().home_network()[0][0]))
    assert "asked the local network who has" in arp
    h = StatisticsView.hierarchy(rows)
    assert h[("Frame",)][0] == len(rows)
    assert h[("Frame", "Ethernet")][0] == len(rows)
    tcp = sum(v[0] for k, v in h.items() if len(k) == 4 and k[3] == "TCP")
    assert tcp == sum(1 for d in rows if d["transport"] == "TCP")

