def bench_capture(devices, flows, sites):
    """Frames of a synthetic network: `devices` hosts announce themselves
    and take a DHCP lease, then make `flows` TLS connections to `sites`
    websites (the first 2 x sites with a DNS lookup first)."""
    b = ScenarioBuilder()
    hosts = []
    for i in range(devices):
        hosts.append((f"192.168.{1 + i // 250}.{2 + i % 250}",
                      "02:00:%02x:%02x:07:09" % (i >> 8 & 255, i & 255),
                      f"host-{i:04d}"))
    for h in hosts:
        b.arp_announce(h)
        b.dhcp(h)
    names = [(f"s{j}.site{j % 400}.example{j % 7}.com",
              f"{20 + j // 62500}.{(j // 250) % 250}.{j % 250 + 1}."
              f"{7 + j % 3}") for j in range(sites)]
    for k in range(flows):
        h = hosts[k % devices]
        name, rip = names[(k * 7) % sites]
        if k < sites * 2:
            b.dns(h, name, rip)
        b.tls(h, name, rip, size=1400 * (1 + k % 3))
        if b.port > 64000:         # source ports wrap, as they do for real
            b.port = 30000
    return b.frames


def _rss_mb():
    """Resident memory of this process in MB (0 when unknown)."""
    with contextlib.suppress(OSError, ValueError):
        with open("/proc/self/status", encoding="utf-8") as f:
            for line in f:
                if line.startswith("VmRSS"):
                    return int(line.split()[1]) / 1024
    with contextlib.suppress(Exception):
        import resource
        r = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
        return r / (1024 * 1024) if sys.platform == "darwin" else r / 1024
    return 0.0


def _bench_child(sid, out_path, pcap):
    """One scenario, in this process (started by bench_gui), reading the
    capture file the parent built (so building it does not count)."""
    spec = BENCH_SCENARIOS[sid]
    setup_logging()
    load_scapy()
    _patch_dialogs_for_tests()
    tmp = tempfile.mkdtemp(prefix="mw_bench_")
    res = {"scenario": sid, "title": spec["title"],
           "version": SCRIPT_VERSION, "python": platform.python_version(),
           "platform": platform.platform(), "tk": str(tk.TkVersion),
           "features": dict(FEATURES)}
    frames = list(iter_raw_capture(pcap)) if spec.get("replay_pps") \
        else None
    res["capture"] = {"bytes": os.path.getsize(pcap)}
    cfg = AppConfig(path=os.path.join(tmp, "config.json"))
    for key, val in (("general.auto_start_capture", False),
                     ("general.show_welcome", False),
                     ("appearance.beginner_mode", False),
                     ("appearance.inspector", True),
                     ("general.language", spec["language"]),
                     ("appearance.text_size", spec["text_size"])):
        cfg.set(key, val)
    set_locale(spec["language"])
    install_gui_gate()
    probe = perf_start()
    root = tk.Tk()
    root.geometry(spec["geometry"])
    rss0 = _rss_mb()
    t0 = time.perf_counter()
    app = MiniWireshark(root, "", set(), set(), "", config=cfg)
    warm_heading_widths(root)        # what a real start does (rc.11)
    freeze_startup_objects()
    _gui_pump(root, 0.5)
    res["window_ready_s"] = round(time.perf_counter() - t0, 2)
    res["rss_start_mb"] = round(rss0, 1)
    res["rss_empty_mb"] = round(_rss_mb(), 1)

    def busy():
        jobs = getattr(app, "jobs", None)
        return bool(app.importer is not None or len(app.ring) or
                    app.pending_rows or (app.worker and app.worker.busy) or
                    (jobs is not None and jobs.busy()))

    beat = {"on": False, "last": 0.0, "gaps": []}

    def heartbeat():
        now = time.perf_counter()
        beat["gaps"].append(now - beat["last"])
        beat["last"] = now
        if beat["on"]:
            root.after(10, heartbeat)

    def beat_start():
        beat["gaps"] = []
        beat["last"] = time.perf_counter()
        if not beat["on"]:
            beat["on"] = True
            root.after(10, heartbeat)

    def beat_stall():
        """Longest time the window could not run a 10 ms timer: callbacks
        plus Tk's own redraw and geometry work after them."""
        beat["on"] = False
        gaps = beat["gaps"] or [0.0]
        return round(max(gaps) * 1000, 1)

    def measure(name, action, until=None, settle=0.3, timeout=120.0):
        """Run `action` as a Tk callback and wait until it is done.
        stall_ms = the longest the window was unresponsive meanwhile;
        max_ms = the longest single Python callback (work + gate wait)."""
        _gui_pump(root, 0.05)
        probe.reset()
        probe.phase = name
        beat_start()
        t_start = time.perf_counter()
        root.after(0, action)
        _gui_pump(root, settle, until, timeout)
        elapsed = time.perf_counter() - t_start
        sm = probe.summary()
        return {"stall_ms": beat_stall(),
                "elapsed_ms": round(elapsed * 1000, 1),
                "max_ms": sm["max_ms"], "max_name": sm["max_name"],
                "max_wait_ms": sm["max_wait_ms"], "p99_ms": sm["p99_ms"],
                "over_100ms": sm["over_100ms"]}

    def cpu_s():
        t = os.times()
        return t.user + t.system

    if spec.get("replay_pps"):
        app._select_tab("dash")
        _gui_pump(root, 1)
        sink, pps = app.live_sink(), spec["replay_pps"]
        dropped0 = app.ring.dropped
        stop = threading.Event()

        def replay():
            t_begin = time.perf_counter()
            for i, (raw, ts, lt) in enumerate(frames):
                if stop.is_set():
                    break
                sink(raw, ts, lt)
                due = t_begin + (i + 1) / pps
                lag = due - time.perf_counter()
                if lag > 0:
                    time.sleep(lag)
        th = threading.Thread(target=replay, daemon=True, name="replay")
        probe.reset()
        probe.phase = "replay"
        c0 = cpu_s()
        beat_start()
        th.start()
        _gui_pump(root, float(spec.get("replay_seconds", 15)))
        stop.set()
        th.join(5)
        res["replay"] = dict(probe.summary(), stall_ms=beat_stall(),
                             cpu_pct=round(
            (cpu_s() - c0) / float(spec.get("replay_seconds", 15)) * 100,
            1), ring_dropped=app.ring.dropped - dropped0)
    else:
        app._select_tab("packets")
        _gui_pump(root, 0.5)
        probe.reset()
        probe.phase = "import"
        c0 = cpu_s()
        beat_start()
        t_start = time.perf_counter()
        app.import_pcap_path(pcap)
        _gui_pump(root, 2, until=lambda: not busy(), timeout=1800)
        _gui_pump(root, 3)
        res["import"] = dict(probe.summary(), stall_ms=beat_stall(),
                             seconds=round(time.perf_counter() - t_start, 1),
                             cpu_s=round(cpu_s() - c0, 1))
    m = app.model
    res["model"] = {"devices": len(m.registry.by_key),
                    "websites": len(m.websites),
                    "connections": len(list(m.flows.all_flows())),
                    "remote_hosts": len(m.remote_hosts),
                    "alerts": len(m.alerts.alerts),
                    "packet_rows": len(app.all_rows)}
    res["rss_loaded_mb"] = round(_rss_mb(), 1)

    sw = {}
    for name in list(app.tabs):
        sw[name] = measure("switch:" + name,
                           lambda n=name: app._select_tab(n), settle=0.6)
    res["switch"] = sw
    res["switch.stall_ms"] = max(v["stall_ms"] for v in sw.values())
    reb = {}
    for name in ("devices", "websites", "connections", "remote", "timeline",
                 "alerts"):
        app._select_tab(name)
        _gui_pump(root, 0.3)
        reb[name] = measure("rebuild:" + name, app.tabs[name].rebuild)
    res["rebuild"] = reb
    # 5.3.4 (M7): Story mode, written by a job and drawn on the Tk thread
    tl = app._select_tab("timeline")
    _gui_pump(root, 0.3)
    res["story"] = measure("story", lambda: tl.set_story(True),
                           until=lambda: tl._story_shown is not None and
                           "story" not in app.jobs.active)
    res["story.stall_ms"] = res["story"]["stall_ms"]
    tl.set_story(False)

    def flush_all():
        m.dirty_devices |= set(m.registry.by_key)
        m.dirty_websites |= set(m.websites)
        m.dirty_remotes |= set(m.remote_hosts)
        m.flows.dirty |= {f.fid for f in m.flows.all_flows()}
        for part in (app._flush_events, app._flush_devices,
                     app._flush_websites, app._flush_remotes,
                     app._flush_flows):
            part(m)
    app._select_tab("dash")
    _gui_pump(root, 0.5)
    res["flush_all_dirty"] = measure("flush_all_dirty", flush_all)
    res["dashboard_refresh"] = measure(
        "dashboard_refresh", lambda: app.tabs["dash"].refresh(force=True))
    tick_done = threading.Event()
    res["model_tick"] = measure(
        "model_tick", lambda: app.tick_model_stepped(tick_done.set),
        until=tick_done.is_set)
    res["model_tick.stall_ms"] = res["model_tick"]["stall_ms"]
    res["layout_pass"] = measure("layout_pass", app._layout_pass)

    def set_theme(name):
        app.config.set("appearance.theme", name)
        app.theme_name = name
        app._apply_theme()
    th = [measure("theme", lambda: set_theme("Dark"), settle=0.5),
          measure("theme", lambda: set_theme("Light"), settle=0.5)]
    res["theme"] = th[0]
    res["theme.stall_ms"] = max(x["stall_ms"] for x in th)
    other = "Normal" if spec["text_size"] != "Normal" else "Large"

    def set_size(name):
        app.config.set("appearance.text_size", name)
        app._apply_text_size()
    ts = [measure("text_size", lambda: set_size(other), settle=0.5),
          measure("text_size", lambda: set_size(spec["text_size"]),
                  settle=0.5)]
    res["text_size"] = ts[0]
    res["text_size.stall_ms"] = max(x["stall_ms"] for x in ts)

    xs = []
    for _ in range(3):
        t = time.perf_counter()
        app.search_results("host-01")
        xs.append(time.perf_counter() - t)
    res["search_ms"] = round(statistics.median(xs) * 1000, 1)

    def palette():
        pal = app.open_palette()
        root.update_idletasks()
        with contextlib.suppress(Exception):
            pal.win.destroy()
    res["palette"] = measure("palette", palette)

    # 5.2.3 (B-23): the benchmark's own reference kept the imported data
    # alive through the reload, so "memory after reload" counted it twice
    m = None
    sess = os.path.join(tmp, "bench.mwsession.json")
    filedialog.asksaveasfilename = lambda *a, **k: sess
    res["session_save"] = measure(
        "session_save", app._save_session,
        until=lambda: os.path.exists(sess) and not busy(), settle=0.3)
    with contextlib.suppress(OSError):
        res["session_save"]["bytes"] = os.path.getsize(sess)
    res["session_save.stall_ms"] = res["session_save"]["stall_ms"]
    res["session_load"] = measure(
        "session_load", lambda: app._load_session(sess),
        until=lambda: app.data_mode == "session" and not busy(),
        settle=1.0)
    res["session_load.stall_ms"] = res["session_load"]["stall_ms"]
    res["rss_after_reload_mb"] = round(_rss_mb(), 1)
    csvp = os.path.join(tmp, "flows.csv")
    app._ask_save = lambda *a, **k: csvp
    res["export_flows_csv"] = measure(
        "export_flows_csv", app._export_flows_csv,
        until=lambda: os.path.exists(csvp) and not busy())
    for name, key in (("dash", "idle_cpu_dash_pct"),
                      ("devices", "idle_cpu_devices_pct")):
        app._select_tab(name)
        _gui_pump(root, 1)
        probe.reset()
        probe.phase = "idle:" + name
        c0 = cpu_s()
        _gui_pump(root, 8)
        res[key] = round((cpu_s() - c0) / 8 * 100, 1)
        res["idle_" + name] = probe.summary()
    res["import.stall_ms"] = res.get("import", {}).get("stall_ms")
    res["import.p99_ms"] = res.get("import", {}).get("p99_ms")
    res["replay.stall_ms"] = res.get("replay", {}).get("stall_ms")
    res["rss_end_mb"] = round(_rss_mb(), 1)
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(res, f, indent=1)
    with contextlib.suppress(Exception):
        app._on_close()
    shutil.rmtree(tmp, ignore_errors=True)
    return 0


BENCH_SUMMARY_KEYS = (
    ("import.stall_ms", "Longest freeze while reading the capture (ms)"),
    ("import.p99_ms", "  p99 callback while reading (ms)"),
    ("replay.stall_ms", "Longest freeze during paced replay (ms)"),
    ("session_load.stall_ms", "Longest freeze loading a session (ms)"),
    ("session_save.stall_ms", "Longest freeze saving a session (ms)"),
    ("text_size.stall_ms", "Longest freeze changing text size (ms)"),
    ("theme.stall_ms", "Longest freeze changing theme (ms)"),
    ("switch.stall_ms", "Slowest tab switch (ms)"),
    ("model_tick.stall_ms", "Longest freeze in model upkeep (ms)"),
    ("idle_cpu_dash_pct", "Idle CPU, Dashboard (% of a core)"),
    ("idle_cpu_devices_pct", "Idle CPU, Devices (% of a core)"),
    ("rss_loaded_mb", "Memory with data loaded (MB)"),
    ("rss_after_reload_mb", "Memory after save and reload (MB)"),
    ("search_ms", "Global search (ms)"),
    ("story.stall_ms", "Longest freeze writing the story (ms)"),
    ("window_ready_s", "Window ready (s)"),
)


def bench_check(results, table=None, label="limit"):
    """[(scenario, metric, value, limit, ok)] for every metric that has a
    limit in `table` and was measured."""
    table = BENCH_LIMITS if table is None else table
    out = []
    for sid, res in results.items():
        for key, lim in (table.get(sid) or {}).items():
            val = res.get(key)
            if val is None:
                continue
            out.append((sid, key, val, lim, val <= lim))
    return out


def bench_gui(argv):
    """python miniwireshark.py --bench-gui [S1 S2 S3 S4 | all] [--check]
    [--targets] [--out FILE]. Needs a display (Linux: inside xvfb-run)."""
    if "--child" in argv:
        i = argv.index("--child")
        return _bench_child(argv[i + 1], argv[argv.index("--out") + 1],
                            argv[argv.index("--pcap") + 1])
    if sys.platform.startswith("linux") and not os.environ.get("DISPLAY") \
            and not os.environ.get("WAYLAND_DISPLAY"):
        print("--bench-gui opens the real window and needs a display. On a "
              "server, run it inside xvfb-run.")
        return 2
    wanted = [a.upper() for a in argv if a.upper() in BENCH_SCENARIOS]
    if "all" in argv:
        wanted = list(BENCH_SCENARIOS)
    wanted = wanted or ["S1"]
    out_path = argv[argv.index("--out") + 1] if "--out" in argv else \
        os.path.join(PATHS.data, time.strftime("bench-gui-%Y%m%d-%H%M.json"))
    results = OrderedDict()
    work = tempfile.mkdtemp(prefix="mw_bench_")
    captures = {}
    for sid in wanted:
        spec = BENCH_SCENARIOS[sid]
        print(f"{sid} {spec['title']}: {spec['devices']} devices, "
              f"{spec['flows']} connection attempts, {spec['sites']} "
              f"websites ...", flush=True)
        size = (spec["devices"], spec["flows"], spec["sites"])
        if size not in captures:
            load_scapy()
            frames = bench_capture(*size)
            captures[size] = os.path.join(work, "%d-%d-%d.pcap" % size)
            write_raw_pcap(captures[size], frames)
            print(f"  capture: {len(frames):,} packets", flush=True)
            del frames
        part = os.path.join(work, f"{sid}.json")
        env = dict(os.environ)
        env["MINIWIRESHARK_DATA"] = tempfile.mkdtemp(prefix="mw_benchdata_")
        t0 = time.time()
        try:
            rc = _run_hidden(self_cmd("--bench-gui",
                                         "--child", sid, "--out", part,
                                         "--pcap", captures[size]), env=env,
                                timeout=3600).returncode
        except subprocess.TimeoutExpired:
            rc = -1
        if rc != 0 or not os.path.exists(part):
            print(f"  {sid} did not finish (exit code {rc}).")
            results[sid] = {"error": f"exit code {rc}"}
            continue
        with open(part, encoding="utf-8") as f:
            results[sid] = json.load(f)
        print(f"  done in {time.time() - t0:.0f} s", flush=True)
    print()
    print(f"{'':44s}" + "".join(f"{sid:>10s}" for sid in results))
    for key, label in BENCH_SUMMARY_KEYS:
        vals = [results[sid].get(key) for sid in results]
        if all(v is None for v in vals):
            continue
        print(f"{label:44s}" + "".join(
            f"{'—' if v is None else v:>10}" for v in vals))
    for sid, res in results.items():
        rp = res.get("replay")
        if rp:
            print(f"{sid} replay: longest stall {rp['max_ms']} ms, ring "
                  f"drops {rp['ring_dropped']}, CPU {rp['cpu_pct']} %")
    atomic_write_json(out_path, results)
    shutil.rmtree(work, ignore_errors=True)
    print(f"\nFull results: {out_path}")
    rc = 0
    for flag, table, word in (("--check", BENCH_LIMITS, "limit"),
                              ("--targets", BENCH_TARGETS, "5.1.2 target")):
        if flag not in argv:
            continue
        rows = bench_check(results, table)
        print(f"\nAgainst each {word}"
              + (" (provisional limits)" if flag == "--check" and
                 BENCH_LIMITS_PROVISIONAL else "") + ":")
        for sid, key, val, lim, ok in rows:
            print(f"  [{'PASS' if ok else 'FAIL'}] {sid} {key}: {val} "
                  f"(<= {lim})")
        if flag == "--check" and not all(r[4] for r in rows):
            rc = 1
    if any("error" in r for r in results.values()):
        rc = rc or 1
    return rc

# ---- release gate on another machine (--release-gate) ---------------------
# The gates the Linux test environment can't close (the reference laptop,
# Windows and macOS) in one command: every check runs in its own process,
# the window is photographed tab by tab, and one folder comes back with a
# summary. Nothing is sent anywhere; nothing is installed.
GATE_SHOT_TABS = ("dash", "feed", "timeline", "devices", "map", "health",
                  "alerts", "websites", "connections", "remote", "packets",
                  "security", "sources", "help")


def grab_window(root, path):
    """A PNG of the window (what the person sees), with the platform's
    own tool: screencapture on macOS, PowerShell on Windows, ImageMagick
    `import` on Linux. -> (ok, how or why not)."""
    path = os.path.abspath(path)       # .NET resolves its own way
    try:
        root.update_idletasks()
        x, y = root.winfo_rootx(), root.winfo_rooty()
        w, h = root.winfo_width(), root.winfo_height()
    except tk.TclError as e:
        return False, str(e)
    try:
        if sys.platform == "darwin":
            if not shutil.which("screencapture"):
                return False, "screencapture not found"
            r = subprocess.run(["screencapture", "-x", "-R",
                                f"{x},{y},{w},{h}", path],
                               capture_output=True, timeout=30)
            ok = r.returncode == 0 and os.path.exists(path)
            return ok, ("screencapture" if ok else
                        "screencapture failed (System Settings → Privacy → "
                        "Screen Recording must allow the terminal)")
        if IS_WINDOWS:
            ps = shutil.which("powershell") or shutil.which("pwsh")
            if not ps:
                return False, "PowerShell not found"
            script = (
                "Add-Type -AssemblyName System.Windows.Forms,System.Drawing;"
                "Add-Type -Name D -Namespace W -MemberDefinition "
                "'[DllImport(\"user32.dll\")] public static extern bool "
                "SetProcessDPIAware();';[W.D]::SetProcessDPIAware()|Out-Null;"
                f"$b=New-Object System.Drawing.Bitmap({w},{h});"
                "$g=[System.Drawing.Graphics]::FromImage($b);"
                f"$g.CopyFromScreen({x},{y},0,0,$b.Size);"
                "$b.Save('" + path.replace("'", "''") +
                "',[System.Drawing.Imaging.ImageFormat]::Png)")
            # -EncodedCommand: Windows PowerShell drops the double quotes
            # of a script passed as a plain argument
            enc = base64.b64encode(script.encode("utf-16-le")).decode()
            r = subprocess.run([ps, "-NoProfile", "-NonInteractive",
                                "-EncodedCommand", enc], capture_output=True,
                               timeout=60, creationflags=NO_WINDOW)
            ok = r.returncode == 0 and os.path.exists(path)
            return ok, "PowerShell" if ok else (
                "PowerShell: " + r.stderr.decode("utf-8", "replace")[:200])
        if shutil.which("import"):
            r = subprocess.run(["import", "-window", str(root.winfo_id()),
                                path], capture_output=True, timeout=30)
            ok = r.returncode == 0 and os.path.exists(path)
            return ok, "ImageMagick import" if ok else "import failed"
        return False, "no screenshot tool (install ImageMagick for `import`)"
    except (OSError, subprocess.SubprocessError) as e:
        return False, str(e)


def platform_facts(root=None):
    """What the machine is, for the gate summary."""
    facts = OrderedDict()
    facts["MiniWireshark"] = SCRIPT_VERSION
    facts["Operating system"] = platform.platform()
    facts["Python"] = f"{platform.python_version()} ({sys.executable})"
    facts["Processors"] = str(os.cpu_count() or "?")
    if root is not None:
        with contextlib.suppress(tk.TclError):
            facts["Tk"] = str(root.tk.call("info", "patchlevel"))
            facts["Tk scaling"] = "%.2f pixels per point" % float(
                root.tk.call("tk", "scaling"))
            facts["Screen"] = (f"{root.winfo_screenwidth()}x"
                               f"{root.winfo_screenheight()}")
            facts["Interface scale"] = "%d %%" % round(UI_SCALE[0] * 100)
    return facts


def gui_shots(out_dir, quick=False):
    """--gui-shots DIR: a small synthetic network read through the normal
    path, then every tab photographed and checked by layout_audit in
    English Light, English Dark, French Light and (when the screen is big
    enough) English at 150 %. Writes DIR/audit.txt and DIR/*.png."""
    global PATHS
    os.makedirs(out_dir, exist_ok=True)
    tmp = tempfile.mkdtemp(prefix="mw_shots_")
    os.environ["MINIWIRESHARK_DATA"] = tmp
    PATHS = AppPaths()
    setup_logging()
    load_scapy()
    _patch_dialogs_for_tests()
    install_gui_gate()
    cfg = AppConfig(path=os.path.join(tmp, "config.json"))
    for k, v in (("general.auto_start_capture", False),
                 ("general.show_welcome", False),
                 ("updates.check_automatically", False),
                 ("privacy.auto_download_reference", False),
                 ("appearance.beginner_mode", False)):
        cfg.set(k, v)
    cfg.save()
    root = tk.Tk()
    app = MiniWireshark(root, "", set(), set(), "", config=cfg)
    app._apply_runtime_settings()
    pcap = os.path.join(tmp, "shots.pcap")
    frames = bench_capture(60, 900, 300)
    write_raw_pcap(pcap, frames)
    app.import_pcap_path(pcap)
    _gui_pump(root, 0.5, lambda: app.importer is None and
              app.model.count >= len(frames), timeout=300)
    _gui_pump(root, 2.0)
    lines = [f"{k:18s} {v}" for k, v in platform_facts(root).items()]
    lines.append("")
    shots, problems, tool = 0, 0, ""
    passes = [("en-light", "English", "Light", None),
              ("en-dark", "English", "Dark", None),
              ("fr-light", "Français", "Light", None)]
    if not quick and root.winfo_screenwidth() >= 2049 and \
            root.winfo_screenheight() >= 1152:
        passes.append(("en-150", "English", "Light", "150 %"))
    elif not quick:
        lines.append("150 %: skipped, the screen is smaller than "
                     "2049x1152 (1366x768 at 150 %)")
    sc0 = float(root.tk.call("tk", "scaling"))
    for tag, lang, theme, scale in passes:
        app.config.set("general.language", lang)
        app._apply_runtime_settings()
        app._apply_theme(theme)
        if scale:
            apply_ui_scale(root, scale)
            app._apply_text_size(defer=False)
        root.geometry(px_geo("1366x768") + "+0+0")
        _gui_pump(root, 1.0)
        lines.append(f"[{tag}] {lang}, {theme}" +
                     (f", {scale}" if scale else "") + ", window " +
                     f"{root.winfo_width()}x{root.winfo_height()}")
        for name in (GATE_SHOT_TABS if not quick else GATE_SHOT_TABS[:4]):
            if name not in app.tabs:
                continue
            app._select_tab(name)
            _gui_pump(root, 0.8)
            audit = layout_audit(root)
            found = [x for x in audit
                     if x[0] in ("canvas-text-overlap", "overlap", "cut-x",
                                 "cut-y")]
            # a heading within 10 pixels of its column's edge: listed to
            # look at in the picture, not counted (it is usually whole)
            tight = [x[2] for x in audit if x[0] == "heading-cut"]
            problems += len(found)
            path = os.path.join(out_dir, f"{tag}-{name}.png")
            ok, how = grab_window(root, path)
            shots += ok
            tool = tool or (how if ok else "")
            lines.append(f"  {name:12s} " + (
                "picture saved" if ok else f"no picture ({how})") +
                f"; {len(found)} layout problem(s)")
            for kind, wpath, detail in found[:8]:
                lines.append(f"      {kind}: {detail} ({wpath})")
            if tight:
                lines.append("      tight headings (check the picture): " +
                             ", ".join(tight[:8]))
        if scale:
            root.tk.call("tk", "scaling", sc0)
            apply_ui_scale(root, "Automatic")
            app._apply_text_size(defer=False)
    lines.append("")
    lines.append(f"Pictures: {shots} ({tool or 'none'}); layout problems: "
                 f"{problems}")
    atomic_write_text(os.path.join(out_dir, "audit.txt"),
                      "\n".join(lines) + "\n")
    print("\n".join(lines))
    with contextlib.suppress(Exception):
        app._on_close()
    with contextlib.suppress(Exception):
        root.destroy()
    shutil.rmtree(tmp, ignore_errors=True)
    return 0 if problems == 0 else 1


def _gate_run(out_dir, name, args, timeout):
    """One gate step in its own process; output to DIR/<name>.txt."""
    path = os.path.join(out_dir, f"{name}.txt")
    t0 = time.time()
    env = dict(os.environ)
    env["MW_UNATTENDED"] = "1"
    try:
        r = subprocess.run(self_cmd(*args),
                           stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                           timeout=timeout, env=env,
                           creationflags=NO_WINDOW)
        rc, text = r.returncode, r.stdout.decode("utf-8", "replace")
    except subprocess.TimeoutExpired as e:
        rc = -1
        text = (e.stdout or b"").decode("utf-8", "replace") + \
            f"\n(stopped after {timeout} s)"
    except OSError as e:
        rc, text = -1, str(e)
    atomic_write_text(path, text)
    return rc, time.time() - t0, text


def start_check(out=print):
    """`--start-check` (rc.11): two real starts with a fresh data folder
    and settings (the first measures the computer's speed on the loading
    screen, the second uses what the first remembered); each window runs
    3 s, watching nothing, then closes. Needs a display."""
    tmp = tempfile.mkdtemp(prefix="mw_startcheck_")
    cfgp = os.path.join(tmp, "settings.json")
    atomic_write_text(cfgp, json.dumps({"general": {
        "show_welcome": False, "welcome_version": SCRIPT_VERSION,
        "auto_start_capture": False}}))
    env = dict(os.environ, MINIWIRESHARK_DATA=tmp,
               MINIWIRESHARK_CONFIG=cfgp, MW_START_AND_EXIT="3", MW_PERF="1")
    ok, got = True, []
    try:
        for label in ("First start", "Next start"):
            t0 = time.perf_counter()
            try:
                r = subprocess.run(self_cmd(), env=env,
                                   capture_output=True, text=True,
                                   timeout=300, creationflags=NO_WINDOW)
                text = r.stdout
            except (OSError, subprocess.SubprocessError) as e:
                text = f"could not start: {e}"
            wall = time.perf_counter() - t0
            line = next((x for x in text.splitlines()
                         if x.startswith("START_OK")), "")
            perf = next((x for x in text.splitlines()
                         if x.startswith("START_PERF")), "")
            out(f"  {label}: {line or 'FAILED'}")
            if perf:
                out(f"    {perf}")
            if not line or "loader_gone=True" not in line:
                ok = False
                out("    " + text[-800:].replace("\n", "\n    "))
                continue
            win = line.split("window=")[1].split("s")[0]
            longest = perf.split("longest=")[1].split(" ")[0] if perf \
                else "?"
            got.append(f"{label.lower()} {win} s (process {wall:.1f} s), "
                       f"longest freeze {longest} ms")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    out("Result: " + ("; ".join(got) if ok else "a start failed"))
    return 0 if ok else 1


def release_gate(argv):
    """python miniwireshark.py --release-gate [--out DIR] [--runs N]
    [--quick]. Runs the boot check, self-test, GUI test, the S1 window
    benchmark N times (median against the limits), the tab pictures and
    the release check, each in its own process, and writes DIR/summary.txt.
    Needs a display. Sends nothing; installs nothing."""
    quick = "--quick" in argv
    runs = 1 if quick else 3
    if "--runs" in argv:
        with contextlib.suppress(ValueError, IndexError):
            runs = max(1, min(9, int(argv[argv.index("--runs") + 1])))
    sysname = {"win32": "windows", "darwin": "macos"}.get(
        sys.platform, "linux")
    out_dir = argv[argv.index("--out") + 1] if "--out" in argv else \
        os.path.abspath(time.strftime(f"mw-gate-{sysname}-%Y%m%d-%H%M"))
    os.makedirs(out_dir, exist_ok=True)
    print(f"MiniWireshark {SCRIPT_VERSION} release gate -> {out_dir}")
    print("Leave the computer alone while it runs (windows open and close "
          "by themselves); about " + ("10" if quick else "45") +
          " minutes.", flush=True)
    rows = []

    def step(name, args, timeout, label):
        print(f"  {label}…", end=" ", flush=True)
        rc, secs, text = _gate_run(out_dir, name, args, timeout)
        last = [ln for ln in text.strip().splitlines() if ln.strip()]
        rows.append((label, rc == 0, secs, last[-1][:100] if last else ""))
        print(("PASS" if rc == 0 else "FAIL") + f" ({secs:.0f} s)",
              flush=True)
        return rc
    step("boot", ["--boot-check"], 600, "Boot check")
    step("selftest", ["--self-test"], 2400, "Self-test")
    if not quick:
        step("guitest", ["--gui-test"], 3000, "GUI test")
    bench = []
    for i in range(runs):
        part = os.path.join(out_dir, f"bench-S1-{i + 1}.json")
        step(f"bench-{i + 1}", ["--bench-gui", "S1", "--out", part], 3600,
             f"Window benchmark S1, run {i + 1} of {runs}")
        with contextlib.suppress(OSError, ValueError):
            with open(part, encoding="utf-8") as f:
                bench.append(json.load(f))
    step("shots", ["--gui-shots", os.path.join(out_dir, "shots")] +
         (["--quick"] if quick else []), 1800, "Tab pictures and layout check")
    step("start", ["--start-check"], 900, "Real start, twice")
    step("release", ["--release-check"], 900, "Release check")
    lines = [f"MiniWireshark {SCRIPT_VERSION} release gate, "
             f"{time.strftime('%Y-%m-%d %H:%M')}", ""]
    head = []
    with contextlib.suppress(OSError):
        with open(os.path.join(out_dir, "shots", "audit.txt"),
                  encoding="utf-8") as f:
            for ln in f:
                if not ln.strip():
                    break
                head.append(ln.rstrip("\n"))
    lines += head or [f"{k:18s} {v}" for k, v in platform_facts().items()]
    lines += ["", "Steps:"]
    for label, ok, secs, last in rows:
        lines.append(f"  [{'PASS' if ok else 'FAIL'}] {label} "
                     f"({secs:.0f} s) {last}")
    if bench:
        lines += ["", f"S1 freezes, median of {len(bench)} (limit):"]
        per = OrderedDict()
        for res in bench:
            for sid, key, val, lim, _ok in bench_check(res, BENCH_LIMITS):
                if isinstance(val, (int, float)):
                    per.setdefault((sid, key, lim), []).append(float(val))
        for (sid, key, lim), vals in per.items():
            med = statistics.median(vals)
            lines.append(f"  [{'PASS' if med <= lim else 'FAIL'}] {sid} "
                         f"{key}: {med:.1f} (<= {lim}) runs "
                         + ", ".join(f"{v:.0f}" for v in vals))
    lines += ["", "Send this whole folder back (zip it): the pictures are "
                  "in shots/, every step's full output is next to this "
                  "file. It contains no captured traffic from your network: "
                  "every test uses made-up data."]
    text = "\n".join(lines) + "\n"
    atomic_write_text(os.path.join(out_dir, "summary.txt"), text)
    print()
    print(text)
    return 0 if all(r[1] for r in rows) and all(
        "[FAIL]" not in ln for ln in lines) else 1


# ============================================================================
#  20c.  GUI test — drives the real window under a (virtual) display
#
#  python miniwireshark.py --gui-test   (Linux: run it inside xvfb-run)
#  It imports the scripted capture through the normal PCAP path, visits
#  every tab in every theme and mode, opens the detail views and settings,
#  checks Dark mode for light-coloured leaks, and shuts down cleanly.
# ============================================================================
GUI_TEST_STEPS = []           # later milestones append (name, fn(app, ctx))


def gui_test_step(name):
    def deco(fn):
        GUI_TEST_STEPS.append((name, fn))
        return fn
    return deco


def _gui_pump(root, seconds=0.0, until=None, timeout=30.0):
    t_end = time.time() + timeout
    t_min = time.time() + seconds
    while True:
        drain_deferred_tk()
        try:
            root.update()
        except tk.TclError:
            return False
        now = time.time()
        if now >= t_min and (until is None or until()):
            return True
        if now > t_end:
            return False
        time.sleep(0.01)


def _patch_dialogs_for_tests():
    """No modal dialog may block an unattended test run."""
    messagebox.askyesno = lambda *a, **k: True
    messagebox.askokcancel = lambda *a, **k: True
    messagebox.askyesnocancel = lambda *a, **k: True
    messagebox.showinfo = lambda *a, **k: "ok"
    messagebox.showwarning = lambda *a, **k: "ok"
    messagebox.showerror = lambda *a, **k: "ok"
    filedialog.askopenfilename = lambda *a, **k: ""
    filedialog.asksaveasfilename = lambda *a, **k: ""
    filedialog.askdirectory = lambda *a, **k: ""


def _luminance(hexcol):
    try:
        return _hex_lum(hexcol)
    except (ValueError, TypeError, IndexError):
        return None


def dark_theme_leaks(root):
    """Widgets that still paint a light background in Dark mode."""
    leaks = []

    def walk(w):
        try:
            if isinstance(w, (tk.Frame, tk.Label, tk.Text, tk.Canvas,
                              tk.Listbox, tk.Button, tk.Checkbutton,
                              tk.Radiobutton, tk.Entry, tk.Toplevel,
                              tk.LabelFrame, tk.Message)):
                bg = str(w.cget("bg"))
                if bg.startswith("#") and len(bg) == 7:
                    lum = _luminance(bg)
                    if lum is not None and lum > 0.82 and \
                            not getattr(w, "_mw_light_ok", False):
                        leaks.append(f"{w.winfo_class()} {w} bg={bg}")
        except tk.TclError:
            pass
        for c in w.winfo_children():
            walk(c)
    walk(root)
    return leaks


@gui_test_step("stress: 30k frames while the window stays responsive")
def _gs_stress(app, ctx):
    root = app.root
    app.stop()
    app._leave_nonlive()
    ident = scenario_identity()
    m = app._new_model(identity=ident[:3])
    m.set_identity(local_nets=ident[3])
    app.replace_model(m)
    app.data_mode = "live"            # behave like a live capture
    app._select_tab("packets")
    frames = ScenarioBuilder().busy_mix(30000)
    sink = app.lossless_sink()
    feeder = threading.Thread(
        target=lambda: [sink(r, time.time(), lt) for r, _t, lt in frames],
        daemon=True)
    stalls = []
    last = [time.perf_counter()]

    def beat():
        now = time.perf_counter()
        stalls.append(now - last[0])
        last[0] = now
        if feeder.is_alive() or len(app.ring) or app.worker.busy:
            root.after(10, beat)
    t0 = time.perf_counter()
    feeder.start()
    root.after(10, beat)
    ok = _gui_pump(root, 0.5, lambda: not feeder.is_alive() and
                   not len(app.ring) and not app.worker.busy and
                   app.count >= len(frames), timeout=120)
    dt = time.perf_counter() - t0
    worst = max(stalls) if stalls else 0
    print(f"      ({len(frames)} frames in {dt:.1f}s, worst UI stall "
          f"{worst * 1000:.0f} ms, ring peak {app.ring.peak})")
    assert ok, f"pipeline stalled at {app.count}/{len(frames)}"
    assert worst < 0.6, f"UI froze for {worst * 1000:.0f} ms"
    app.data_mode = "idle"
    _gui_pump(root, 0.3)
    assert len(app.tabs["packets"].tree.get_children()) > 0


@gui_test_step("live capture starts and stops (only with --live)")
def _gs_live(app, ctx):
    if "--live" not in sys.argv:
        return
    app.start(auto=True)
    _gui_pump(app.root, 3.0)
    assert app.sniffer is not None, "capture did not start"
    assert app.sniffer.exception is None, app.sniffer.exception
    with contextlib.suppress(OSError):
        _socket.getaddrinfo("example.com", 443)
    _gui_pump(app.root, 1.5)
    kind = getattr(app.sniffer, "kind", "?")
    app._check_pipeline(time.monotonic())
    if sys.platform.startswith("linux") and kind == "raw socket":
        assert app.kernel.supported, "Linux raw socket drops not read"
    epochs = len(app.model.epochs)
    assert epochs and app.model.epochs[-1][1] is None
    app.stop()
    _gui_pump(app.root, 0.5)
    assert app.sniffer is None and app.data_mode == "idle"
    assert app.model.epochs[-1][1] is not None and \
        app.model.epochs[-1][3] == "stopped by you"
    print(f"      (source: {kind}, {app.count} packets, OS drops "
          f"{app.kernel.text()})")


@gui_test_step("starting capture never blocks the window (5.2.3, B-01)")
def _gs_capture_start_async(app, ctx):
    g = globals()
    old = g["start_capture_source"]
    saved_fault = app.last_fault

    def slow_fail(_iface, _bpf, _promisc, _sink):
        time.sleep(0.3)
        return None, OSError("Error opening adapter (20)")
    g["start_capture_source"] = slow_fail
    try:
        labels = (list(app.iface_map)[:1] or ["Default"]) * 5
        t0 = time.perf_counter()
        assert app._start_capture(labels)
        dt = time.perf_counter() - t0
        assert dt < 0.15, f"starting capture blocked {dt * 1000:.0f} ms"
        assert app._capture_starting
        app.start()                        # a second click is ignored
        assert _gui_pump(app.root, 0, lambda: not app._capture_starting,
                         timeout=15), "the start never finished"
        assert app.sniffer is None
        assert app.last_fault[0] in ("wrong_adapter", "driver"), \
            app.last_fault
        assert str(app.start_btn.cget("state")) == "normal"
        # a stop while the cards are tried cancels the start
        assert app._start_capture(labels)
        app.stop()
        assert not app._capture_starting
        _gui_pump(app.root, 1.0)
        assert app.sniffer is None and not app._capture_starting
    finally:
        g["start_capture_source"] = old
        app.last_fault = saved_fault


@gui_test_step("minimised window keeps memory bounded (5.2.3, B-21/B-22)")
def _gs_minimised_trim(app, ctx):
    m = app.model
    saved = (set(m.flows.dirty), list(m.ev_alerts), list(m.ev_banner))
    try:
        m.flows.dirty = set(range(10 ** 7, 10 ** 7 + app.MINIMIZED_KEEP + 5))
        m.flows.closed_now.extend([object()] * 50)
        m.ev_alerts.extend([object()] * (app.MINIMIZED_KEEP + 5))
        m.ev_banner.extend([("a", "info"), ("b", "info")])
        app._trim_while_minimized(m)
        assert not m.flows.dirty and not m.flows.closed_now
        assert len(m.ev_alerts) == app.MINIMIZED_KEEP
        assert m.ev_banner == [("b", "info")]
        assert app.tabs["connections"]._pending
        # a backlog bigger than the table is one sliced refill
        m.flows.dirty = set(range(10 ** 7, 10 ** 7 + app.FLOW_BACKLOG + 5))
        app._flow_rebuild_at = 0.0
        t0 = time.perf_counter()
        app._flush_flows(m)
        assert not m.flows.dirty
        assert time.perf_counter() - t0 < 0.25
        # a small one goes in pieces of at most FLUSH_MAX
        m.flows.dirty = set(range(10 ** 7, 10 ** 7 + app.FLUSH_MAX + 7))
        app._flow_rebuild_at = time.monotonic()
        app._flush_flows(m)
        assert len(m.flows.dirty) == 7
        _gui_pump(app.root, 0.5)
    finally:
        m.flows.dirty, m.ev_alerts[:], m.ev_banner[:] = saved
        m.flows.dirty = set()


@gui_test_step("history store records live evidence (and survives reopen)")
def _gs_history(app, ctx):
    root = app.root
    assert app.history is not None, "history should be on in the GUI test"
    ident = scenario_identity()
    m = app._new_model(identity=ident[:3])
    m.set_identity(local_nets=ident[3])
    app.replace_model(m)
    app.data_mode = "live"
    app._pump_store(reschedule=False)      # what the 1 s tick does
    assert m.obs_sink
    sink = app.lossless_sink()
    for raw, _ts, lt in ctx.frames():
        sink(raw, time.time(), lt)
    _gui_pump(root, 0.3, lambda: not len(app.ring) and not app.worker.busy,
              timeout=30)
    app._pump_store(reschedule=False)
    assert app.history.flush_now(10)
    c = app.history.counts()
    assert c["observations"] > 20 and c["site_ties"] >= 4 and \
        c["events"] > 0, c
    # a second, independent connection sees the same data (crash-safe)
    other = Store(PATHS.history_db, session_id=999)
    c2 = other.counts()
    other.stop(5)
    assert c2["observations"] >= c["observations"], (c, c2)
    app.data_mode = "idle"


@gui_test_step("packet history, virtual table, saved timeline, compare")
def _gs_history_v2(app, ctx):
    root = app.root
    S = ScenarioBuilder
    old_max = app.config.get("capture.max_stored_events", 5000)
    app.config.set("capture.max_stored_events", 500)
    app.config.set("history.packet_ring", True)
    app._apply_runtime_settings()
    assert app.max_rows == 500 and app.packet_ring is not None
    ident = scenario_identity()
    m = app._new_model(identity=ident[:3])
    m.set_identity(local_nets=ident[3])
    app.replace_model(m)
    app.data_mode = "live"
    app._pump_store(reschedule=False)
    app.mode_ui_var.set("Advanced")
    app._on_ui_mode_change()
    tab = app._select_tab("packets")
    frames = S().busy_mix(1500)
    sink = app.lossless_sink()
    for raw, _ts, lt in frames:
        sink(raw, time.time(), lt)
    assert _gui_pump(root, 0.3, lambda: not len(app.ring) and
                     not app.worker.busy and app.count >= len(frames),
                     timeout=60), app.count
    _gui_pump(root, 0.2)
    assert len(app.all_rows) == 500
    # ---- virtual table: only the visible rows are Treeview items
    tab.rebuild()
    _gui_pump(root, 0.1)
    n = tab._nslots()
    kids = tab.tree.get_children()
    assert len(tab.matched) == 500, len(tab.matched)
    assert 0 < len(kids) <= n + 1 < 120, (len(kids), n)
    first_in_mem = app.all_rows[0]["no"]
    target = app.all_rows[200]["no"]
    assert tab.select_no(target) and tab._selected_row()["no"] == target
    assert not tab.follow_var.get()

    class Ev:
        def __init__(self, keysym="", num=0, delta=0):
            self.keysym, self.num, self.delta = keysym, num, delta
    tab._key(Ev("Down"))
    assert tab.sel_no == app.all_rows[201]["no"], (tab.sel_no, target)
    tab._key(Ev("End"))
    assert tab.sel_no == app.all_rows[-1]["no"]
    vis = {tab.slot_rows[i]["no"] for i in tab.tree.get_children()}
    assert tab.sel_no in vis
    tab._key(Ev("Home"))
    assert tab.top == 0 and tab.sel_no == first_in_mem
    top0 = tab.top
    tab._wheel(Ev(num=5))
    assert tab.top == top0 + 3, tab.top
    tab._yscroll("moveto", "0.5")
    assert abs(tab.top - 250) <= n, tab.top
    tab._yscroll("scroll", "1", "pages")
    lo, hi = tab.vbar.get()
    assert 0 < lo < hi <= 1.0
    tab._sort_by("length")
    lens = [d["length"] for d in tab.matched]
    assert lens == sorted(lens)
    tab._sort_by("length")
    assert [d["length"] for d in tab.matched] == sorted(lens, reverse=True)
    tab._sort_by("no")
    assert tab.sort_col is None
    nos = [d["no"] for d in tab.matched]
    assert nos == sorted(nos)
    tab.set_expression("proto:arp")
    assert not tab.matched and not tab.tree.get_children()
    assert tab.vbar.get() == (0.0, 1.0)
    tab.set_expression("proto:tls")
    assert len(tab.matched) == 500 and tab.tree.get_children()
    tab.clear_filter()
    assert len(tab.matched) == 500
    # ---- the proof behind a claim, after it left memory: from disk
    assert app.packet_ring.flush()
    before = {str(w) for w in root.winfo_children()}
    assert app.jump_to_packet(10), "packet #10 should come from disk"
    _gui_pump(root, 0.1)
    new = [w for w in root.winfo_children() if str(w) not in before and
           isinstance(w, tk.Toplevel)]
    assert new and "Packet #10" in new[0].title(), [w.title() for w in new]
    for w in new:
        w.destroy()
    got = app.packet_ring.find(10)
    assert got is not None and got[0] == frames[9][0]
    assert app.jump_to_packet(target) and tab._selected_row()["no"] == target
    # ---- the saved timeline (SQL-backed, paged)
    app._pump_store(reschedule=False)
    assert app.history.flush_now(10)
    tl = app._select_tab("timeline")
    tl.source_var.set("Saved history")
    tl._on_source()
    _gui_pump(root, 0.1)
    assert tl.history_mode() and tl.tree.get_children(), \
        tl.status_lbl.cget("text")
    assert "saved events" in tl.status_lbl.cget("text")
    assert tl.zoom_var.get() in tl.HISTORY_ZOOMS
    tl.type_var.set("Websites")
    tl.rebuild()
    for iid in tl.tree.get_children()[:20]:
        assert tl.tree.set(iid, "kind") in ("website",), tl.tree.set(iid)
    tl.type_var.set("All types")
    tl.rebuild()
    tl.tree.selection_set(tl.tree.get_children()[0])
    tl._on_double()
    _gui_pump(root, 0.1)
    tl.load_older()
    tl.source_var.set("This session")
    tl._on_source()
    assert not tl.history_mode() and tl.zoom_var.get() in tl.LIVE_ZOOMS
    # ---- compare two sessions
    other = Store(PATHS.history_db, session_id=app.session_id - 3600,
                  meta={"source": "live"})
    other.write_observations([(1, time.time() - 3600, "dhcp_request",
                               "02:00:00:00:00:77", {"hostname": "Old-TV"},
                               1)])
    assert other.flush_now(10)
    other.stop(5)
    w = app.open_compare()
    assert w is not None
    _gui_pump(root, 0.1)
    w.destroy()
    ss = store_sessions(app.history)
    mine = next(x for x in ss if x["id"] == app.session_id)
    older = next(x for x in ss if x["id"] == app.session_id - 3600)
    res = app.show_compare(older, mine)
    assert "02:00:00:00:00:77" in res["gone_devices"], res["gone_devices"]
    assert res["new_devices"], res
    _gui_pump(root, 0.1)
    for w in root.winfo_children():
        if isinstance(w, tk.Toplevel):
            w.destroy()
    # ---- export of the current view uses the virtual table's rows
    assert len(tab.matched) == 500
    # ---- turn things back off
    app.config.set("history.packet_ring", False)
    app.config.set("capture.max_stored_events", old_max)
    app._apply_runtime_settings()
    assert app.packet_ring is None
    app.mode_ui_var.set("Beginner")
    app._on_ui_mode_change()
    app.data_mode = "idle"


