def _all_widgets(root):
    out, stack = [], [root]
    while stack:
        w = stack.pop()
        out.append(w)
        with contextlib.suppress(tk.TclError):
            stack.extend(w.winfo_children())
    return out


@gui_test_step("languages: switch to French and Spanish and back")
def _gs_languages(app, ctx):
    tab = app.tabs["dash"]
    english = app.nb.tab(tab.frame, "text")
    mode = app.mode_ui_var.get()
    try:
        app.config.set("general.language", "Français")
        app._apply_runtime_settings()
        _gui_pump(app.root, 0.3)
        fr = app.nb.tab(tab.frame, "text")
        assert "Tableau de bord" in fr, fr
        assert app.start_btn.cget("text").endswith("Commencer à observer")
        # a drop-down shows French while the program keeps English values
        assert app.mode_ui_var.get() == mode
        boxes = [w for w in _all_widgets(app.root)
                 if getattr(w, "_mw_i18n", None) and
                 w._mw_i18n["var"] is app.mode_ui_var]
        if boxes:
            assert boxes[0].get() == translate_text(mode, "fr"), \
                boxes[0].get()
        else:
            # 5.1.2: two buttons, each named in French
            btns = [str(w.cget("text")) for w in _all_widgets(app.root)
                    if isinstance(w, ttk.Radiobutton) and
                    str(w.cget("variable")) == str(app.mode_ui_var)]
            assert translate_text(mode, "fr") in btns, btns
        # a status line set later is shown in French too
        app.status_var.set("Ready. Click “Start watching” when you'd like "
                           "to begin.")
        assert app.status_var.get().startswith("Prêt."), \
            app.status_var.get()
        app.config.set("general.language", "Español")
        app._apply_runtime_settings()
        _gui_pump(app.root, 0.3)
        assert "Panel" in app.nb.tab(tab.frame, "text")

        def shown():
            if boxes:
                return [boxes[0].get()]
            return [str(w.cget("text")) for w in _all_widgets(app.root)
                    if isinstance(w, ttk.Radiobutton) and
                    str(w.cget("variable")) == str(app.mode_ui_var)]
        assert translate_text(mode, "es") in shown(), shown()
    finally:
        app.config.set("general.language", "English")
        app._apply_runtime_settings()
        _gui_pump(app.root, 0.3)
    assert app.nb.tab(tab.frame, "text") == english
    assert mode in shown() and app.mode_ui_var.get() == mode
    assert CURRENT_LOCALE == "en"


@gui_test_step("V5 startup: notice, startup history, managed-Python choice")
def _gs_v5_startup(app, ctx):
    root = app.root
    win = tk.Toplevel(root)
    lw = LoaderWindow(win, app.config)
    lw.pack(fill="both", expand=True)
    # MC2: every Ready? line fills from its probe while the window runs,
    # with the same answer --boot-check prints
    seen = {}

    def peek():
        seen.update({k: v for k, v in lw.ready_results.items()})
        if len(seen) == len(READY_PROBES) and not lw.ready_rows:
            lw._choose("exit")
        else:
            win.after(50, peek)
    win.after(50, peek)
    win.after(20000, lambda: lw._choose("exit"))
    t0 = time.perf_counter()
    choice = lw.show_welcome("summary", "degraded", False,
                             notice="⚠ test notice")
    assert choice == "exit", choice
    assert time.perf_counter() - t0 < 19, "Ready? lines never filled"
    assert lw.notice_lbl.cget("text") == "⚠ test notice"
    report = {k: (st, tx) for k, _t, st, tx, _f in ready_report(app.config)}
    for k, (st, tx, _f) in seen.items():
        if k not in ("network", "outbound"):       # these may change
            assert report[k][0] == st, (k, report[k], st)
    lines = []
    boot_check(out=lines.append)
    assert any(x.strip() == "Ready?" for x in lines), lines
    win.destroy()
    old = globals()["BOOT_DIR"]
    globals()["BOOT_DIR"] = ctx.path("boot_hist")
    try:
        r = BootReceipt()
        r.step("window", True, "Tk")
        r.step("main window", False, error=ValueError("boom"))
        r.mark(outcome="fatal")
        w = app.open_boot_history()
        _gui_pump(root, 0.2)
        assert "boom" in w._mw_text and "fatal" in w._mw_text, w._mw_text
        w.destroy()
        assert "Startup history" in app.debug_bundle_text()
    finally:
        globals()["BOOT_DIR"] = old
    rm = app.open_runtime_manager()
    _gui_pump(root, 0.3)
    assert app._rm_pref.get() is False
    rm.destroy()
    assert "Private packages folder" in app.runtime_status_text()


