def run_gui_test(live=False):
    """Returns 0 on success. Prints a step-by-step report."""
    global PATHS
    tmp = tempfile.mkdtemp(prefix="mw_guitest_")
    os.environ["MINIWIRESHARK_DATA"] = tmp
    PATHS = AppPaths()
    setup_logging()
    load_scapy()
    _patch_dialogs_for_tests()
    results = []
    ctx = TestContext(tmp, True)
    cfg = ctx.cfg({"general.auto_start_capture": False,
                   "updates.check_automatically": False,
                   "privacy.auto_download_reference": False,
                   "history.enabled": True,
                   "history.retention": "7 days"})
    cfg.save()
    root = tk.Tk()
    gw, ips, macs, nets = scenario_identity()
    app = MiniWireshark(root, "", set(), set(), "", config=cfg)

    def step(name, fn):
        t0 = time.perf_counter()
        try:
            fn()
            results.append(("PASS", name, ""))
        except Exception as e:                       # noqa: BLE001
            results.append(("FAIL", name, f"{type(e).__name__}: {e}\n" +
                            traceback.format_exc(limit=6)))
        print(f"  [{results[-1][0]}] {name} "
              f"({(time.perf_counter() - t0) * 1000:.0f} ms)", flush=True)

    frames = ctx.frames()
    pcap = ctx.path("scenario.pcap")
    write_raw_pcap(pcap, frames)

    def s_import():
        app.import_pcap_path(pcap)
        ok = _gui_pump(root, 0.5, lambda: app.importer is None and
                       app.data_mode == "offline" and
                       app.model.count >= len(frames), timeout=60)
        assert ok, f"import stalled at {app.model.count}/{len(frames)}"
        _gui_pump(root, 2.2)
        fails = golden_checks(app.model)
        assert not fails, "; ".join(fails)

    def s_tabs():
        for name, tab in app.tabs.items():
            app._select_tab(name)
            _gui_pump(root, 0.05)
            tab.refresh()

    def s_modes_and_themes():
        for mode in ("Advanced", "Beginner", "Advanced"):
            app.mode_ui_var.set(mode)
            app._on_ui_mode_change()
            _gui_pump(root, 0.05)
        for theme, hc in (("Dark", False), ("Dark", True), ("Light", True),
                          ("Light", False), ("Dark", False)):
            app._apply_theme(theme, hc)
            for name in app.tabs:
                app._select_tab(name)
                _gui_pump(root, 0.02)
        leaks = dark_theme_leaks(root)
        for mode in ("deutan", "protan", "tritan", ""):
            set_colorblind_mode(mode)
            app._apply_theme("Dark", False)
            _gui_pump(root, 0.05)
            leaks += dark_theme_leaks(root)
            assert app.theme["good_fg"] == (CVD_TRIPLES[(mode, True)][0]
                                            if mode else
                                            THEMES["Dark"]["good_fg"])
        app._apply_theme("Light", False)
        assert not leaks, f"{len(leaks)} light widgets in Dark: " + \
            "; ".join(leaks[:6])

    def s_details():
        m = app.model
        for key in list(m.registry.by_key)[:12]:
            app.show_device(key)
        for dom in list(m.websites)[:6]:
            app.show_website(dom)
        for ip in list(m.remote_hosts)[:4]:
            app.show_remote(ip)
        for f in list(m.flows.all_flows())[:4]:
            app.show_flow(f.fid)
        for aid in list(m.alerts.order)[:4]:
            app.show_alert(aid)
        _gui_pump(root, 0.2)
        for w in root.winfo_children():
            if isinstance(w, tk.Toplevel):
                w.destroy()

    def s_settings():
        app._open_settings()
        _gui_pump(root, 0.2)
        sw = app._settings_win
        for page in SETTINGS_PAGES:
            sw.show_page(page["id"])
            _gui_pump(root, 0.02)
        sw.win.destroy()
        app.open_diagnostics()
        _gui_pump(root, 0.3)
        app._diag_win.win.destroy()

    def s_search():
        for q in ("example", "ip:192.168.1.23", "port:443", "device:tv",
                  "alert:cleartext"):
            res = app.search_results(q)
            assert isinstance(res, (list, dict))

    def s_demo():
        app.start_demo()
        _gui_pump(root, 2.5)
        assert app.data_mode == "demo" and app.model.demo
        app.stop_demo()
        _gui_pump(root, 0.3)
        assert not any(d.ip.startswith("192.168.50.") for d in
                       app.model.registry.by_key.values() if d.ip)

    for name, fn in (("import scenario capture (golden checks)", s_import),
                     ("visit every tab", s_tabs),
                     ("modes and themes (dark leak audit)",
                      s_modes_and_themes),
                     ("detail views", s_details),
                     ("settings and diagnostics", s_settings),
                     ("global search", s_search)):
        step(name, fn)
    only = os.environ.get("MW_GUI_ONLY", "")     # developers: one step
    for name, fn in GUI_TEST_STEPS:
        if only and not any(o in name for o in only.split("|")):
            continue
        step(name, lambda fn=fn: fn(app, ctx))
    step("demo mode starts and leaves no trace", s_demo)

    def s_close():
        app._on_close()
        time.sleep(0.5)
        bad = [t.name for t in threading.enumerate()
               if t is not threading.main_thread() and not t.daemon]
        assert not bad, f"non-daemon threads left: {bad}"
    step("clean shutdown", s_close)
    failed = [r for r in results if r[0] == "FAIL"]
    print(f"  (timers cancelled with their widget: "
          f"{AFTER_GUARD['cancelled']})")
    print(f"\nGUI test: {len(results) - len(failed)} passed / "
          f"{len(failed)} failed")
    for _s, name, msg in failed:
        print(f"\nFAILED: {name}\n{msg}")
    shutil.rmtree(tmp, ignore_errors=True)
    return 1 if failed else 0


def write_raw_pcap(path, frames):
    """Write (raw, ts, linktype) frames to a classic pcap file (stdlib)."""
    lt = frames[0][2] if frames else 1
    with open(path, "wb") as f:
        f.write(struct.pack("<IHHiIII", 0xa1b2c3d4, 2, 4, 0, 0, 262144, lt))
        for raw, ts, _lt in frames:
            sec = int(ts)
            usec = int(round((ts - sec) * 1e6)) % 1000000
            f.write(struct.pack("<IIII", sec, usec, len(raw), len(raw)))
            f.write(raw)


def startup_sanity_checks():
    """Cheap checks at GUI start (the full suite is --self-test)."""
    problems = []
    flat = config_defaults_flat()
    for key in settings_schema_keys():
        if key not in flat:
            problems.append(f"setting without default: {key}")
    for name, table in PALETTES.items():
        if len(set(table.values())) != len(table):
            problems.append(f"palette {name} is not one-to-one")
    for p in problems:
        LOG.warning("sanity: %s", p)
    return problems



@gui_test_step("5.1.2 M2: background save and load, journal v2, upkeep steps, fonts")
def gt_m2_background(app, ctx):
    root = app.root
    m = app.model
    n_dev = len(m.registry.by_key)
    assert n_dev, "the scenario should have devices"
    # save in the background: the window keeps running meanwhile
    path = ctx.path("bg.mwsession.json")
    beats = []
    root.after(0, lambda: app.save_session_to(path))
    t_end = time.time() + 30
    while time.time() < t_end:
        beats.append(time.perf_counter())
        _gui_pump(root, 0.0)
        if os.path.exists(path) and not app.jobs.busy():
            break
    assert os.path.exists(path) and not app.jobs.busy()
    with open(path, encoding="utf-8") as f:
        saved = json.load(f)
    assert len(saved["devices"]) == n_dev
    # a second save of the same kind while one runs is refused
    assert app.save_session_to(path) is not None
    assert app.save_session_to(path) is None
    _gui_pump(root, 0.2, until=lambda: not app.jobs.busy(), timeout=30)
    # load in the background, tables refilled step by step
    app._load_session(path)
    _gui_pump(root, 0.3, until=lambda: not app.jobs.busy() and
              app.data_mode == "session", timeout=30)
    _gui_pump(root, 0.3)
    assert app.data_mode == "session"
    assert len(app.model.registry.by_key) == n_dev
    dev_rows = len(app.tabs["devices"].tree.get_children())
    assert dev_rows, "the Devices table was not refilled"
    # journal v2: compact text + fingerprint, restorable; v1 still restores
    jp = app.write_journal(ctx.path("j2.json"))
    side = read_json(jp + ".sha256")
    assert side and side["journal"] == 2
    with open(jp, "rb") as f:
        assert hashlib.sha256(f.read()).hexdigest() == side["sha256"]
    # upkeep in steps reaches the end and calls back
    done = []
    app.tick_model_stepped(lambda: done.append(1))
    _gui_pump(root, 0.1, until=lambda: done, timeout=10)
    assert done, "stepped model upkeep did not finish"
    # shared fonts look exactly like the tuples they replaced
    app._apply_text_size("Normal")
    _gui_pump(root, 0.1, until=lambda: app._text_size_job is None, timeout=5)
    for name, (size, style) in MW_FONTS.items():
        a = tkfont.nametofont(name).actual()
        b = tkfont.Font(font=("TkDefaultFont", size) + style).actual()
        assert a == b, (name, a, b)
    assert len(MW_FONTS) >= 8, sorted(MW_FONTS)
    app._apply_text_size("Large")
    _gui_pump(root, 0.1, until=lambda: app._text_size_job is None, timeout=5)
    # the size asked for (a Tk without scalable fonts, such as a build
    # without Xft, draws every size with the same fixed font)
    big = int(tkfont.nametofont(mw_font(11, "bold")).cget("size"))
    app._apply_text_size("Normal")
    _gui_pump(root, 0.1, until=lambda: app._text_size_job is None, timeout=5)
    assert abs(big) > 11, big
    # nothing is drawn while minimised; drawing resumes afterwards
    app.minimized = lambda: True
    try:
        before = app.model.dirty_devices
        app.model.dirty_devices = set(app.model.registry.by_key)
        app._flush_ui()
        assert app.model.dirty_devices, "flushed while minimised"
    finally:
        del app.minimized
        app.model.dirty_devices = before
    # back to the scenario capture for the steps that follow (a session
    # has no packets)
    frames = ctx.frames()
    app.import_pcap_path(ctx.path("scenario.pcap"))
    assert _gui_pump(root, 0.5, lambda: app.importer is None and
                     app.data_mode == "offline" and
                     app.model.count >= len(frames), timeout=60)
    _gui_pump(root, 1.0)


@gui_test_step("5.1.2 M3: table kit (sort that holds, columns, menus, empty "
               "states, export, new rows)")
def gt_m3_table_kit(app, ctx):
    root = app.root
    reg = app.model.registry
    dt = app.tabs["devices"]
    app._select_tab("devices")
    dt.show_inactive_var.set(True)
    dt.show_expired_var.set(True)
    dt._vis_changed()
    _gui_pump(root, 0.3)
    kit = dt.kit
    kit.clear_sort()
    rnd = random.Random(7)
    # sorted by traffic (descending) while 300 updates arrive: stays sorted
    kit.sort_by("traffic")
    kit.sort_by("traffic")
    assert kit.sort_col == "traffic" and kit.sort_desc
    keys = list(dt.iids)
    assert len(keys) >= 3, keys
    dt.tree.selection_set(())

    def traffic_order():
        return [kit._raw_key(key_for_iid(dt.iids, i), None, "traffic")
                for i in dt.tree.get_children("")]
    for _ in range(300):
        k = keys[rnd.randrange(len(keys))]
        reg.by_key[k].bytes_down += rnd.randrange(0, 5000000)
        dt.update_keys([k])
    got = traffic_order()
    assert got == sorted(got, reverse=True), "the sorted list fell out of order"
    # the selected row stays where you are looking; "order changed" shows
    last = dt.tree.get_children("")[-1]
    dt.tree.selection_set(last)
    reg.by_key[key_for_iid(dt.iids, last)].bytes_down += 10 ** 13
    dt.update_keys([key_for_iid(dt.iids, last)])
    assert dt.tree.get_children("")[-1] == last, "the selected row moved"
    _gui_pump(root, 0.1)
    assert kit.stale and kit.stale_lbl.winfo_manager(), "no re-sort line"
    kit.resort()
    assert dt.tree.get_children("")[0] == last and not kit.stale
    dt.tree.selection_set(())
    # hide two columns, "restart": still hidden (and the sort is kept);
    # Reset columns gives the defaults back
    kit.set_column_shown("vendor", False)
    kit.set_column_shown("mac", False)
    kit.save()
    saved = AppConfig(path=app.config.path).get("appearance.tables")
    assert "vendor" not in saved["devices"]["cols"], saved
    kit._cols_override = "unset"
    kit.sort_col = None
    kit.load()
    shown = list(dt.tree["displaycolumns"])
    assert "vendor" not in shown and "mac" not in shown, shown
    assert kit.sort_col == "traffic" and kit.sort_desc
    kit.reset_columns()
    assert list(dt.tree["displaycolumns"]) == dt.default_cols()
    # the switch off is 5.0.2: no remembered columns or sort
    kit.set_column_shown("vendor", False)
    FEATURES["sticky_sort"] = False
    try:
        kit._cols_override = "unset"
        assert kit.user_cols is None
    finally:
        FEATURES["sticky_sort"] = True
    kit.reset_columns()
    # every main table's menu: Open, Copy, Filter to this, in that order
    app.mode_ui_var.set("Advanced")
    app._on_ui_mode_change()
    for name in ("devices", "websites", "connections", "remote", "alerts",
                 "timeline"):
        tab = app.tabs[name]
        app._select_tab(name)
        tab.rebuild()
        _gui_pump(root, 0.1)
        kids = tab.tree.get_children("")
        assert kids, f"{name}: no rows to test the menu on"
        labels = kit_menu_labels(tab.kit.row_items(kids[0], None))
        assert labels[:3] == ["Open", "Copy", "Filter to this"], \
            (name, labels)
    # a heading's menu: columns, reset, export
    hl = kit_menu_labels(kit.header_items())
    assert hl[:2] == ["Columns", "Reset columns"] and \
        "Export this table…" in hl, hl
    # 300 upserts into a sorted 1,500-row table
    top = tk.Toplevel(root)
    try:
        wrap, tree = make_tree(top, [("name", "Name", 120, "w", True),
                                     ("n", "Number", 80, "e", False)])
        wrap.pack(fill="both", expand=True)
        fake = types.SimpleNamespace(app=app, name="(test)",
                                     is_visible=lambda: False)
        iids = IidMap()
        k2 = TableKit(fake, tree, wrap, "(test)",
                      key_of=lambda i: key_for_iid(iids, i))
        k2.save_soon = lambda: None
        for i in range(1500):
            tree_upsert(tree, iids, i, (f"row {i}", rnd.randrange(10 ** 6)),
                        kit=k2)
        k2.sort_by("n")
        t0 = time.perf_counter()
        for _ in range(300):
            i = rnd.randrange(1500)
            tree_upsert(tree, iids, i, (f"row {i}", rnd.randrange(10 ** 6)),
                        kit=k2)
        took = (time.perf_counter() - t0) * 1000
        vals = [int(tree.set(x, "n")) for x in tree.get_children("")]
        assert vals == sorted(vals), "bisect placement broke the order"
        print(f"      300 sorted upserts into 1,500 rows: {took:.1f} ms",
              flush=True)
        slack = float(os.environ.get("MW_SLOW", "1") or 1)
        assert took < 30 * slack, f"{took:.1f} ms for 300 upserts"
        app.kits.remove(k2)
    finally:
        top.destroy()
    # empty states
    app._select_tab("devices")
    _gui_pump(root, 0.3)
    dt.filter_var.set("zzz-no-such-device")
    dt.rebuild()
    _gui_pump(root, 0.3, until=lambda: "No rows match" in kit.empty_text(),
              timeout=5)
    assert "No rows match" in kit.empty_text(), kit.empty_text()
    dt.filter_var.set("")
    dt.rebuild()
    _gui_pump(root, 0.3)
    assert kit.empty_text() == ""
    # export this table: the rows as shown, clock times
    path = ctx.path("devices.csv")
    done = []
    assert kit.export(path, done=done.append) is not None
    _gui_pump(root, 0.1, until=lambda: done, timeout=30)
    with open(path, encoding="utf-8") as f:
        rows = list(csv.reader(f))
    assert rows[0] == kit.header_row(), rows[0]
    assert len(rows) == 1 + len(kit.all_iids()), len(rows)
    # new since you last looked; "just now" while live
    mode = app.data_mode
    app.data_mode = "live"
    try:
        kit.on_hide()
        new = reg.touch("192.168.1.250", "da:00:00:00:99:01", "mac_local",
                        "test")
        dt.update_keys([new.key])
        iid = dt.iids.get(new.key)
        assert iid and str(dt.tree.set(iid, "name")).startswith(ROW_DOT)
        assert kit.fresh_count() == 1
        rel = str(dt.tree.set(iid, "last"))
        assert rel == relative_age(new.last_seen, time.time()), rel
        assert kit.cell_text(iid, "last") == fmt_clock(new.last_seen, True)
        kit.on_hide()
        assert not str(dt.tree.set(iid, "name")).startswith(ROW_DOT)
    finally:
        kit.forget_snapshot()
        app.data_mode = mode
    kit.clear_sort()
    kit.reset_columns()
    # the feed holds still under the pointer
    ft = app.tabs["feed"]
    ft._set_hover(True)
    ft.push([{"tag": "other", "who": "test", "did": "something",
              "when": "now"}])
    ft.flush()
    assert ft.buffer and ft.hover_var.get(), "the feed did not hold"
    ft._set_hover(False)
    ft.flush()
    assert not ft.buffer


@gui_test_step("5.1.2 M4: back/forward, tab groups, state line, cards, "
               "Clear with undo")
def gt_m4_shell(app, ctx):
    root = app.root
    reg = app.model.registry
    app.mode_ui_var.set("Advanced")
    app._on_ui_mode_change()
    _gui_pump(root, 0.2)
    # back and forward return to the same view, filter included
    dt = app.tabs["devices"]
    app._select_tab("devices")
    _gui_pump(root, 1.2)
    dt.filter_var.set("192.168")
    dt.rebuild()
    app._select_tab("websites")
    _gui_pump(root, 1.2)
    app.router.back()
    _gui_pump(root, 0.3)
    assert app.current_tab_name() == "devices", app.current_tab_name()
    assert dt.filter_var.get() == "192.168"
    app.router.forward()
    _gui_pump(root, 0.3)
    assert app.current_tab_name() == "websites"
    dt.filter_var.set("")
    dt.rebuild()
    # Ctrl+1..4 go to a tab of that group
    for i in range(len(TAB_GROUPS)):
        app.select_group(i)
        _gui_pump(root, 0.1)
        assert app.current_tab_name() in TAB_GROUPS[i][1]
    # no group split across rows at 1366 px, in all three languages
    old_geo = root.geometry()
    old_lang = app.config.get("general.language", "English")
    try:
        for lang in ("English", "Français", "Español"):
            app.config.set("general.language", lang)
            app._apply_runtime_settings()
            root.geometry(px_geo("1366x768"))
            _gui_pump(root, 0.6)
            ts = app.tabstrip
            ts.relayout()
            rows = ts.group_rows(ts.frame.winfo_width(),
                                 captions=ts.show_captions)
            where = {}
            for ri, r in enumerate(rows):
                for gi, _tids, _c in r:
                    assert gi not in where, (lang, "group split", rows)
                    where[gi] = ri
            assert len(rows) <= 2, (lang, rows)
    finally:
        app.config.set("general.language", old_lang)
        app._apply_runtime_settings()
        root.geometry(old_geo)
        _gui_pump(root, 0.3)
    # the state line: shown and truthful in seven states
    saved_mode, saved_prof = app.data_mode, app.network_profile
    saved_kill = LEDGER.killed
    expect = {"idle": "not capturing live", "live": None,
              "offline": "OFFLINE CAPTURE", "session": "SAVED SESSION",
              "demo": "DEMO DATA", "kill": "KILL SWITCH",
              "untrusted": "CafeWiFi"}
    try:
        for state, words in expect.items():
            LEDGER.killed = state == "kill"
            app.network_profile = {"name": "CafeWiFi", "trusted": False} \
                if state == "untrusted" else None
            app.data_mode = state if state in (
                "idle", "live", "offline", "session", "demo") else "live"
            app._restyle_mode_banner()
            _gui_pump(root, 0.05)
            assert app.mode_banner.winfo_manager(), state
            text = str(app.mode_lbl.cget("text"))
            if words:
                assert words in text, (state, text)
            btn = str(app.mode_toggle_btn.cget("text"))
            if state == "kill":
                assert "kill switch off" in btn, btn
            elif state in ("offline", "session"):
                assert "Return to live" in btn, btn
            elif state == "demo":
                assert "Exit demo" in btn, btn
            elif state == "untrusted":
                assert "Trust this network" in btn, btn
        app.toggle_state_panel(True)
        _gui_pump(root, 0.1)
        assert app.state_panel is not None and \
            app.state_panel.winfo_manager()
        assert any("CafeWiFi" in x for x in app.state_panel_lines())
        app.toggle_state_panel(False)
        assert app.state_panel is None
    finally:
        LEDGER.killed = saved_kill
        app.network_profile = saved_prof
        app.data_mode = saved_mode
        app._restyle_mode_banner()
    # cards: 20 devices opened, one window; a kept window stays
    keys = list(reg.by_key)
    assert keys
    for i in range(20):
        app.show_device(keys[i % len(keys)])
    _gui_pump(root, 0.3)
    cards = [d for d in app._card_wins if d.alive() and
             d.card[0] == "device"]
    assert len(cards) == 1, len(cards)
    first = cards[0]
    first.pin_var.set(True)
    first.pin_toggle()
    second = app.show_device(keys[0])
    _gui_pump(root, 0.2)
    assert first.alive() and second.alive() and first is not second
    # a toggle in a card is journaled: Ctrl+Z undoes it
    dev = reg.by_key[keys[0]]
    before = dev.mine
    box = [w for w in _walk_class(second.win, ttk.Checkbutton)
           if "mine" in str(w.cget("text"))]
    assert box, "no 'This is mine' box in the card"
    box[0].invoke()
    assert dev.mine != before, "the toggle did nothing"
    app.undo_last_correction()
    assert reg.by_key[keys[0]].mine == before, "Ctrl+Z did not undo it"
    for d in list(app._card_wins):
        with contextlib.suppress(tk.TclError):
            d.win.destroy()
    # messages are kept for the ✉ button
    app._set_banner("M4 test message")
    assert app.messages and app.messages[-1][2] == "M4 test message"
    # Clear, then Undo: everything back, exactly (a file's data is not
    # kept: Clear leaves the file; here the data counts as this session's)
    app.data_mode = "idle"
    counts = (len(reg.by_key), len(app.model.websites),
              len(app.model.alerts.alerts))
    app.clear()
    assert len(app.model.registry.by_key) < counts[0] or not counts[0]
    assert app.banner_action_shown()
    assert app.undo_clear()
    m = app.model
    assert (len(m.registry.by_key), len(m.websites),
            len(m.alerts.alerts)) == counts
    # the Undo goes after its time, and the old data with it
    app.UNDO_CLEAR_S = 1
    try:
        app.clear()
        _gui_pump(root, 2.5)
        assert app._clear_undo is None
        assert not app.banner_action_shown()
    finally:
        app.UNDO_CLEAR_S = 30
    # the window's size, place and tab are remembered
    app._remember_window()
    assert app.config.get("appearance.window")
    # back to the scenario capture for the steps that follow
    frames = ctx.frames()
    app.import_pcap_path(ctx.path("scenario.pcap"))
    assert _gui_pump(root, 0.5, lambda: app.importer is None and
                     app.data_mode == "offline" and
                     app.model.count >= len(frames), timeout=60)
    _gui_pump(root, 1.0)


@gui_test_step("5.1.2 M5: explain inline, search as you type, Ctrl+K, "
               "workspaces, Help topics, Show me, tours, folds")
def gt_m5_find(app, ctx):
    root = app.root
    app.mode_ui_var.set("Advanced")
    app._on_ui_mode_change()
    _gui_pump(root, 0.3)
    # Explain inline: the Dashboard's lines and the Inspector's come and go
    dash = app._select_tab("dash")
    _gui_pump(root, 0.8)
    app.set_explain(True)
    _gui_pump(root, 0.3)
    assert any(lbl.winfo_ismapped() for lbl, _t in dash.explain_lbls)
    dev = next(iter(app.model.registry.by_key))
    app.toggle_inspector(True)
    app.inspect("device", dev)
    _gui_pump(root, 0.3)
    assert app.inspector.txt.tag_ranges("explain")
    app.set_explain(False)
    _gui_pump(root, 0.3)
    assert not any(lbl.winfo_ismapped()
                   for lbl, _t in dash.explain_lbls)
    app.inspect("device", dev)
    assert not app.inspector.txt.tag_ranges("explain")
    app.toggle_inspector(False)
    # search as you type: grouped, fast, Down + Enter opens
    drop = app.search_drop
    t0 = time.perf_counter()
    for q in ("br", "bro", "brot", "broth"):
        drop.results(q)
    per_key = (time.perf_counter() - t0) * 1000 / 4
    assert per_key < 10, f"search {per_key:.1f} ms per key"
    app.global_search_var.set("192.168.1")
    drop.update()
    _gui_pump(root, 0.2)
    assert drop.frame is not None and drop.frame.winfo_ismapped()
    assert any("192.168.1" in t for t in drop.shown())
    drop.move(1)
    app._search_enter()
    _gui_pump(root, 0.5)
    assert drop.frame is None
    with contextlib.suppress(tk.TclError):
        for w in list(getattr(app, "_card_wins", [])):
            if w.alive():
                w.win.destroy()
    groups = dict(drop.results("ask before"))
    assert any("Ask before clearing data" in t for t, _a in
               groups.get("Settings", [])), groups
    app.global_search_var.set("")
    # Ctrl+K: settings, websites, help; a setting opens found
    items = app.palette_items()
    cats = {c for _l, c, _f in items}
    assert {"setting", "help", "website"} <= cats, cats
    assert app.palette_key("Start watching")
    assert app.palette_key("Clear and start fresh…") == "Ctrl+L"
    assert app.palette_key("Back") == "Alt+Left"
    assert _pretty_seq("<Control-Key-1>") == "Ctrl+1"
    win = app.open_setting("general.confirm_before_clear")
    _gui_pump(root, 0.4)
    assert "Ask before clearing data" in win.search_var.get() or \
        translate_text("Ask before clearing data") in win.search_var.get()
    before = set(win.changed_keys())
    var = win.vars["general.confirm_before_clear"]
    var.set(not var.get())
    win._on_change("general.confirm_before_clear")
    assert "general.confirm_before_clear" in set(win.changed_keys()) ^ before
    win.show_changed()
    _gui_pump(root, 0.2)
    win._reset_key("general.confirm_before_clear")
    assert set(win.changed_keys()) == before
    win.win.destroy()
    # a workspace keeps the view: sort and filter come back
    ct = app._select_tab("connections")
    _gui_pump(root, 1.2)
    col = ct.kit.shown_cols()[1]
    ct.kit.sort_by(col)
    ct.kit.sort_by(col)
    _gui_pump(root, 0.5)
    rows = list(ct.tree.get_children())[:20]
    app.save_workspace("M5 test")
    ct.kit.clear_sort()
    app._select_tab("dash")
    _gui_pump(root, 0.5)
    app.run_workspace("M5 test")
    _gui_pump(root, 1.5)
    assert app.current_tab_name() == "connections"
    assert (ct.kit.sort_col, ct.kit.sort_desc) == (col, True), \
        (ct.kit.sort_col, ct.kit.sort_desc)
    assert list(ct.tree.get_children())[:20] == rows
    assert app.rename_workspace("M5 test", "M5 renamed") == "M5 renamed"
    saved = app.config.get("workspaces.saved")
    assert "M5 renamed" in saved and "M5 test" not in saved
    # Help: search in three languages; every Show me reaches a widget
    lang = app.config.get("general.language", "English")
    try:
        for name in ("English", "Français", "Español"):
            app.config.set("general.language", name)
            app._apply_runtime_settings()
            _gui_pump(root, 0.2)
            assert app.help_matches("quiet")[0] == "Quiet and Active", \
                (name, app.help_matches("quiet")[:3])
    finally:
        app.config.set("general.language", lang)
        app._apply_runtime_settings()
        _gui_pump(root, 0.2)
    ht = app.open_help("Evidence marks")
    _gui_pump(root, 0.5)
    assert len(ht.shown_titles()) >= 40
    assert "Evidence marks" in ht.txt.get("1.0", "2.0")
    ht.q_var.set("passwords")
    ht.refill()
    assert ht.shown_titles()
    ht.q_var.set("")
    ht.refill()
    targets = [(tab, attr) for tp in help_topics()
               for _l, tab, attr in tp["show"] if tab not in ("tour", "do")]
    targets += [(st[2], st[3]) for _t, _o, steps in TOURS.values()
                for st in steps]
    targets += list(QUICK_START_SPOT.values())
    for tab, attr in targets:
        w = app.show_me(tab, attr)
        _gui_pump(root, 0.05)
        assert w is not None and w.winfo_ismapped(), (tab, attr)
        assert app._spot[1] and all(f.winfo_ismapped()
                                    for f in app._spot[1])
    app._spot_off()
    # glossary words: underlined, and a click shows a note
    ht.open_topic("ARP")
    assert ht.txt.tag_ranges("gloss")
    note = app.gloss_note(ht.txt, "MAC address")
    _gui_pump(root, 0.2)
    assert note.winfo_ismapped()
    app._gloss_off()
    # tours: each offered once; Skip marks one done
    app.config.set("general.tours_done", [])
    assert app.offer_tour("device") and not app.offer_tour("device")
    tw = app.run_tour("alert")
    _gui_pump(root, 0.3)
    tw.go(1)
    _gui_pump(root, 0.2)
    tw.skip()
    assert set(app.config.get("general.tours_done")) == {"device", "alert"}
    app._hide_banner()
    # a card folds its long part; the choice is kept per kind
    app.config.set("appearance.folds", {})
    card = app.show_device(dev)
    _gui_pump(root, 0.3)
    if len(card.sections) > card.FOLD_KEEP + 1:
        was = card.folded
        n = card.txt.get("1.0", "end").count("\n")
        card.toggle_fold()
        assert card.folded != was
        assert card.txt.get("1.0", "end").count("\n") != n
        assert app.config.get("appearance.folds")["device"] == (
            "closed" if card.folded else "open")
    card.win.destroy()
    # Beginner <-> Advanced keeps the tab when both views have it
    app._select_tab("alerts")
    for _ in range(20):
        for v in ("Beginner", "Advanced"):
            app.mode_ui_var.set(v)
            app._on_ui_mode_change()
    _gui_pump(root, 0.3)
    assert app.current_tab_name() == "alerts", app.current_tab_name()


@gui_test_step("5.1.2 M6: answer cards, while you were away, device story, "
               "tags, category corrections, review mode, rules, chart data")
def gt_m6_understand(app, ctx):
    root = app.root
    m = app.model
    dash = app._select_tab("dash")
    _gui_pump(root, 1.0)
    got = app.dashboard_answers(force=True)
    assert set(got) == {"wrong", "usage", "new"}
    for key, (text, _kind, show) in got.items():
        assert text and show is not None, key
    assert dash.answer_lbls["wrong"].winfo_ismapped()
    assert not dash.state_lbl.winfo_ismapped()
    assert app.honesty_line().startswith(translate_text("From here"))
    # endpoint vantage: the usage card names no other device
    orig = m.vantage.classify
    try:
        m.vantage.classify = lambda offline=False: "endpoint"
        text = app.answer_usage()[0]
    finally:
        m.vantage.classify = orig
    assert "not visible" in text, text
    others = [app.device_label(d) for d in m.registry.by_key.values()
              if d.key != m.my_device_key()]
    assert not any(n in text for n in others if len(n) > 3), text
    # while you were away: exactly one line after 31 minutes
    n0 = len(app.messages)
    mode = app.data_mode
    app.note_focus_lost(now=10000.0)
    assert app.note_focus_back(now=10000.0 + 31 * 60) is None  # a file
    app.data_mode = "live"
    try:
        app.note_focus_lost(now=10000.0)
        line = app.note_focus_back(now=10000.0 + 31 * 60)
        assert line and "background" in line, line
        assert app.note_focus_back(now=10000.0 + 40 * 60) is None
        assert len(app.messages) == n0 + 1
        app.note_focus_lost(now=20000.0)
        assert app.note_focus_back(now=20000.0 + 10 * 60) is None
    finally:
        app.data_mode = mode
    app._hide_banner()
    # the story of the phone: marks, still learning, links
    phone = next(d for d in m.registry.by_key.values()
                 if "iPhone" in app.device_label(d))
    story = app.device_story(phone)
    assert story and all(s[0][:1] in "◉◎◌?⚠" for s in story), story
    assert any("still learning" in s[0] for s in story), story
    assert any(link for _s, link in story)
    card = app.show_device(phone.key)
    _gui_pump(root, 0.3)
    body = card.txt.get("1.0", "end")
    assert "Its story" in body and "This is wrong" in body
    card.win.destroy()
    # place and owner: a column next to the name, kept, undone
    app.set_device_tags(phone.key, place="Kitchen", owner="Sam")
    dt = app.tabs["devices"]
    assert dt.kit.shown_cols()[2] == "tags", dt.kit.shown_cols()
    assert app.known.get(phone.key)["place"] == "Kitchen"
    assert "Kitchen" in str(dict(app.search_drop.results("kitchen")))
    app.undo_last_correction()
    assert not phone.place and not (app.known.get(phone.key) or {}).get(
        "place")
    # a category you correct: applied, on the timeline, kept, undone
    w = next(iter(m.websites.values()))
    reg = w.registrable or w.domain
    assert app.set_website_category(w.domain, choice="Social")
    assert w.category == "Social" and w.category_source == CAT_YOURS
    assert m.timeline[-1]["text"].startswith("You set the category")
    CATEGORY_OVERRIDES.clear()
    app._apply_runtime_settings()            # as after a restart
    assert CATEGORY_OVERRIDES.get(reg) == "Social"
    sec = dict(app.website_report(w))
    assert "your correction" in sec["Category (informational)"]
    app.undo_last_correction()
    assert reg not in CATEGORY_OVERRIDES and w.category != "Social"
    # Review mode: Expected stores one rule, Settings lists it, Remove
    # deletes it and that alert can fire again
    app.config.set("alerts.expected", [])
    win = app.review_alerts()
    _gui_pump(root, 0.2)
    if win is not None:
        a = win.queue[0]
        win.expected()
        rules = app.alert_rules()
        assert len(rules) == 1 and rules[0][0] == "alerts.expected"
        sw = app._open_settings("alerts")
        _gui_pump(root, 0.4)
        texts = [str(x.cget("text")) for x in _walk_class(sw.win, tk.Label)]
        assert any(rules[0][2] in t for t in texts), rules[0][2]
        app.remove_alert_rule(*rules[0][:2])
        sw._rerender()
        _gui_pump(root, 0.2)
        assert not app.alert_rules()
        assert not m.alerts.is_muted(a.kind, a.device_key,
                                     a.subject or a.device_key)
        sw.win.destroy()
        win.destroy()
    # Quiet Mode / not live: Why slow sends nothing
    sent = len(LEDGER.entries)
    if not app.health_checks_allowed():
        app.prober.run_now.clear()
        iw = app.investigate("slow")
        _gui_pump(root, 0.3)
        assert not app.prober.run_now.is_set()
        assert len(LEDGER.entries) == sent
        iw.destroy()
    # a chart's numbers
    app._select_tab("dash")
    _gui_pump(root, 0.8)
    text = Charts.chart_text(dash.canvas)
    assert translate_text("Internet traffic") in text
    assert "," in Charts.chart_text(dash.canvas, True)


@gui_test_step("5.1.2 M7: compressed sessions with bookmarks, network sheet, "
               "panes, pin and compare, as of, field columns, builder")
def gt_m7_expert(app, ctx):
    root = app.root
    m = app.model
    # a compressed session keeps the bookmarks
    app.bookmarks.update({2, 4})
    path = ctx.path("m7.mwsession.json.gz")
    app.save_session_to(path)
    assert _gui_pump(root, 0.2, until=lambda: not app.jobs.busy(),
                     timeout=60)
    assert session_is_gz(path)
    payload = read_session_payload(path)
    assert payload["session"]["bookmarks"] == [2, 4]
    assert payload["devices"]
    # the big-capture notice counts records only up to the limit
    assert app.capture_over(ctx.path("scenario.pcap"), 3) is True
    assert app.capture_over(ctx.path("scenario.pcap"), 10 ** 6) is False
    # the network sheet: health lines, alerts, what could be seen, tags
    phone = next(d for d in m.registry.by_key.values()
                 if "iPhone" in app.device_label(d))
    m.correct_tags(phone.key, "Kitchen", "")
    sheet = app.sheet_document()
    for word in ("Network sheet", "Router", "Open alerts",
                 "What this computer could see", "Place / owner",
                 "Kitchen"):
        assert word in sheet, word
    m.correct_tags(phone.key, "", "")
    # Packets: a field as a column, kept, sortable; the column picker
    pt = app._select_tab("packets")
    pt.show_subview("Packets")
    _gui_pump(root, 1.0)
    assert pt.add_field_column("ip.src")
    assert "f1" in pt.shown_cols()
    _gui_pump(root, 0.3)
    for iid in pt.slots[:30]:
        d = pt.slot_rows.get(iid)
        if d is None:
            continue
        want = ", ".join(str(v) for v in pt.field_values(d, "ip.src"))
        assert str(pt.tree.set(iid, "f1")) == want[:80], (want, iid)
    pt.custom = []
    pt.apply_columns()                      # as after a restart
    assert pt.custom == ["ip.src"]
    pt._sort_by("f1")
    assert _gui_pump(root, 0.2, until=lambda: not app.jobs.busy(),
                     timeout=30)
    _gui_pump(root, 0.3)
    assert pt.sort_col == "f1"
    pt.set_column("time", False)
    assert "time" not in pt.shown_cols()
    pt.reset_columns()
    assert pt.shown_cols() == list(pt.BASE_COLS)
    # remembered panes
    vert = pt.vert_pane
    total = vert.winfo_height()
    if total > 100:
        vert.sashpos(0, int(total * 0.4))
        pt._pane_moved(vert, "packets.list")
        frac = app.config.get("appearance.panes")["packets.list"]
        assert 0.35 <= frac <= 0.45, frac
    # the filter builder: two-way on simple expressions
    pt.set_expression("port:443 or port:853")
    b = pt.toggle_builder(True)
    assert len(b.rows) == 2 and not b.text_only
    b.rows[1]["value"].set("53")
    assert b.write() == "port:443 or port:53"
    assert pt.expr_var.get() == "port:443 or port:53"
    pt.toggle_builder(False)
    pt.set_expression("(ip.src == 192.168.1.5)")
    b = pt.toggle_builder(True)
    assert b.text_only
    pt.toggle_builder(False)
    pt.clear_filter()
    assert pt.suggest.matches("dns.q")
    # pin and compare: two at a time, a third replaces the oldest
    keys = [k for k in m.registry.by_key][:3]
    app._pins = []
    app.pin_device(keys[0])
    win = app.pin_device(keys[1])
    _gui_pump(root, 0.2)
    assert win is not None and len(win.devs) == 2
    if app.history is None:
        assert "disabled" in win.days_btn.state()
    win.destroy()
    app.pin_device(keys[2])
    assert app.pins == [keys[1], keys[2]]
    with contextlib.suppress(tk.TclError):
        app._compare_win.destroy()
    # as of: Timeline, Devices and Websites follow; the others say so
    tl = app._select_tab("timeline")
    _gui_pump(root, 0.5)
    start, end = tl.strip_span()
    t = start + (end - start) / 4
    assert end - t >= 30, (start, end, m.now())
    if True:
        app.set_asof(t)
        _gui_pump(root, 0.4)
        assert app.asof is not None
        app._select_tab("devices")
        _gui_pump(root, 0.6)
        dt = app.tabs["devices"]
        assert dt.asof_bar.frame.winfo_ismapped()
        shown = {key_for_iid(dt.iids, i) for i in dt.tree.get_children()}
        for k in shown:
            assert device_online_at(m.registry.by_key[k], app.asof), k
        wt = app.tabs["websites"]
        assert all(website_known_at(w, app.asof)
                   for w in m.websites.values() if wt._match(w, None))
        app._select_tab("connections")
        _gui_pump(root, 0.4)
        assert app.tabs["connections"]._asof_note.winfo_ismapped()
        app.set_asof(None)
        _gui_pump(root, 0.3)
        assert not dt.asof_bar.frame.winfo_ismapped()
        assert not app.tabs["connections"]._asof_note.winfo_ismapped()


_KB_CONTROLS = (ttk.Button, ttk.Entry, ttk.Combobox, ttk.Checkbutton,
                ttk.Radiobutton, ttk.Treeview, ttk.Menubutton, tk.Button,
                tk.Entry, tk.Text, tk.Listbox)


def keyboard_walk(app):
    """{tab: [controls Tab can't reach]} for the view shown (5.1.2 M8):
    every visible, enabled control and every tab label must be reached
    by Tab from the header search box."""
    root = app.root
    out = {}
    for name, tab in app.tabs.items():
        if app.beginner_mode and tab.advanced:
            continue
        app._select_tab(name)
        _gui_pump(root, 0.4)
        seen, w = set(), app.search_entry
        for _ in range(4000):
            w = w.tk_focusNext()
            if w is None or w in seen:
                break
            seen.add(w)
        miss = []
        for x in _all_widgets(root):
            if not isinstance(x, _KB_CONTROLS):
                continue
            try:
                if not x.winfo_viewable() or x.winfo_toplevel() is not root:
                    continue
                if isinstance(x, ttk.Widget) and x.instate(["disabled"]):
                    continue
                if not isinstance(x, ttk.Widget) and \
                        str(x.cget("state")) == "disabled":
                    continue
            except tk.TclError:
                continue
            if x not in seen:
                miss.append(str(x))
        for _o, _b, lbl in app.tabstrip.tabs.values():
            with contextlib.suppress(tk.TclError):
                if lbl.winfo_viewable() and lbl not in seen:
                    miss.append(str(lbl))
        if miss:
            out[name] = miss
    return out


@gui_test_step("5.1.2 M8: keyboard walk, focus rings, dialog contract, "
               "reduce motion, interface scale, System theme, colour "
               "never alone")
def gt_m8_access(app, ctx):
    root = app.root
    mode = app.mode_ui_var.get()
    try:
        for view in ("Advanced", "Beginner"):
            app.mode_ui_var.set(view)
            app._on_ui_mode_change()
            _gui_pump(root, 0.3)
            miss = keyboard_walk(app)
            assert not miss, (view, {k: v[:4] for k, v in miss.items()})
    finally:
        app.mode_ui_var.set(mode)
        app._on_ui_mode_change()
    # a tab label shows the focus without growing
    _o, _b, lbl = next(iter(app.tabstrip.tabs.values()))
    w0 = lbl.winfo_reqwidth()
    lbl.focus_force()
    _gui_pump(root, 0.2)
    assert int(lbl.cget("highlightthickness")) == 2
    assert abs(lbl.winfo_reqwidth() - w0) <= 1
    app.search_entry.focus_force()
    _gui_pump(root, 0.1)
    assert int(lbl.cget("highlightthickness")) == 0
    # dialogs: Escape closes, Enter runs the main button
    q = app.open_quick_start()
    _gui_pump(root, 0.5)
    assert q.bind("<Escape>") and q.bind("<Return>")
    title = [x for x in _walk_class(q, tk.Label)
             if "1." in str(x.cget("text"))]
    q.focus_force()
    _gui_pump(root, 0.1)
    q.event_generate("<Return>")
    _gui_pump(root, 0.2)
    assert not title or "2." in str(title[0].cget("text"))
    q.event_generate("<Escape>")
    _gui_pump(root, 0.2)
    assert not q.winfo_exists()
    # reduce motion: nothing moves by itself
    app.config.set("appearance.reduce_motion", True)
    try:
        app.apply_reduce_motion()
        assert app.tabs["feed"].speed == "🐢 Calm"
        assert not app.tabs["packets"].follow_var.get()
        assert all(getattr(k, "quiet", False) for k in app.kits)
        app._set_banner("M8 still message")
        assert not getattr(app, "_banner_job", None)
        app.show_me("devices", "tree")
        assert getattr(app, "_spot_job", None) is None and app._spot[1]
        app._spot_off()
        root.unbind_all("<Button-1>")
    finally:
        app.config.set("appearance.reduce_motion", False)
        app.apply_reduce_motion()
        app.tabs["packets"].follow_var.set(
            app.config.get("capture.follow_newest", True))
    app._hide_banner()
    # interface scale
    old = UI_SCALE[0]
    try:
        UI_SCALE[0] = 1.5
        assert px(100) == 150 and px_geo("560x620") == "840x930"
        assert px_geo("560x620+10+20") == "840x930+10+20"
    finally:
        UI_SCALE[0] = old
    assert px_geo("560x620") == px_geo("560x620")
    # the window at 150 %: nothing cut off or drawn over (the Linux stand-in
    # for the Windows 125-200 % check, which needs a Windows machine)
    sc0 = float(root.tk.call("tk", "scaling"))
    geo0 = root.geometry()
    found = []
    try:
        apply_ui_scale(root, "150 %")
        root.geometry(px_geo("1366x768"))
        app._apply_text_size(defer=False)
        _gui_pump(root, 0.8)
        for name in ("dash", "devices", "health", "alerts", "map"):
            app._select_tab(name)
            _gui_pump(root, 0.6)
            found += [(name,) + x for x in layout_audit(root)
                      if x[0] in ("canvas-text-overlap", "overlap")]
    finally:
        root.tk.call("tk", "scaling", sc0)
        UI_SCALE[0] = old
        root.geometry(geo0)
        app._apply_text_size(defer=False)
        _gui_pump(root, 0.5)
    assert not found, found[:5]
    # System theme: resolved to Light or Dark, never a palette of its own
    assert resolve_theme("System") in ("Light", "Dark")
    assert palette_name("System", False) in PALETTES
    # colour never alone: status cells carry a word or a symbol in every
    # colour-blind mode
    cvd = CVD_STATE["mode"]
    try:
        for label in CVD_LABELS:
            set_colorblind_mode(label)
            for name, cols in (("alerts", ("sev",)),
                               ("devices", ("conf", "status",
                                            "evidence"))):
                tree = app.tabs[name].tree
                for iid in tree.get_children()[:50]:
                    for c in cols:
                        v = str(tree.set(iid, c)).strip()
                        assert re.search(r"[A-Za-z◉◈◎◌?●○✔⚠‼ℹ]", v), \
                            (label, name, c, v)
    finally:
        set_colorblind_mode(cvd or "Off")


@gui_test_step("5.1.2 M9: pre-flight card, recovery card, What's new")
def gt_m9_loader(app, ctx):
    root = app.root
    top = tk.Toplevel(root)
    try:
        lw = LoaderWindow(top, app.config)
        lw.pack(fill="both", expand=True)
        item = {"name": "Packet capture engine", "version": "2.8.0",
                "size": "2.8 MB", "host": "files.pythonhosted.org",
                "check": "fingerprint-checked (SHA-256)",
                "where": "MiniWireshark's own packages folder", "note": ""}
        # 5.3.4 (LG-12): nobody answers, nothing is downloaded
        ev, box = threading.Event(), [None]
        lw._show_question("preflight", {"items": [item], "wait": 1}, ev,
                          box)
        _gui_pump(root, 0.2)
        texts = [str(x.cget("text")) for x in _walk_class(top, tk.Label)]
        assert any("files.pythonhosted.org" in t and "fingerprint" in t
                   for t in texts), texts
        assert not _gui_pump(root, 0.2, until=ev.is_set, timeout=2.5)
        assert box[0] is None
        b = [x for x in _walk_class(top, ttk.Button)
             if "Download" in str(x.cget("text"))]
        b[-1].invoke()
        assert box[0] == "continue" and ev.is_set()
        # Start without live capture is one click
        ev, box = threading.Event(), [None]
        lw._show_question("preflight", {"items": [item], "wait": 60}, ev,
                          box)
        _gui_pump(root, 0.2)
        b = [x for x in _walk_class(top, ttk.Button)
             if "without" in str(x.cget("text"))]
        assert b
        b[0].invoke()
        assert box[0] == "without" and ev.is_set()
        # the recovery card: Try again / Start without live capture
        root.after(400, lambda: lw.fatal_choice.update(v="retry"))
        got = lw.show_fatal("The capture driver isn't present. timed out",
                            can_skip=True, wait=True)
        assert got == "retry", got
        texts = [str(x.cget("text")) for x in _walk_class(top, tk.Label)]
        del texts
        # What's new is short enough for the Welcome Center
        assert len(LoaderWindow.WHATS_NEW) <= 5
    finally:
        with contextlib.suppress(tk.TclError):
            top.destroy()



@gui_test_step("5.1.2 rc.2: theme walk in Tcl, folds, Why slow docked")
def gt_rc2_polish(app, ctx):
    root = app.root
    opts = ("background", "foreground", "activebackground",
            "selectbackground", "insertbackground", "highlightbackground")

    def snap():
        d = {}
        for w in _all_widgets(root):
            for o in opts:
                with contextlib.suppress(Exception):
                    d[(str(w), o)] = str(w.cget(o)).lower()
        return d
    theme0 = app.theme_name
    # the Tcl walk gives what the Python walk gave, both ways
    try:
        for name in ("Dark", "Light"):
            app._apply_theme(name)
            _gui_pump(root, 0.2)
            tcl = snap()
            other = "Light" if name == "Dark" else "Dark"
            app._apply_theme(other)
            real = app._retheme_widget_tree
            app._retheme_widget_tree = app._retheme_widget_tree_py
            try:
                app._apply_theme(name)
            finally:
                del app._retheme_widget_tree
            assert app._retheme_widget_tree == real
            _gui_pump(root, 0.2)
            py = snap()
            diff = [k for k in set(tcl) | set(py) if tcl.get(k) != py.get(k)]
            assert not diff, diff[:5]
        assert getattr(app, "_retheme_tcl_ok", False)
    finally:
        app._apply_theme(theme0)
    # a timer goes with its widget (its command name can't be reused)
    fr = tk.Frame(root)
    ran = []
    aid = fr.after(150, lambda: ran.append(1))
    assert aid in root.tk.splitlist(root.tk.call("after", "info"))
    fr.destroy()
    assert aid not in root.tk.splitlist(root.tk.call("after", "info"))
    _gui_pump(root, 0.3)
    assert not ran
    # chart text widths are remembered and forgotten with the text size
    c = tk.Canvas(root)
    f = Charts.font(c, ("TkDefaultFont", 8))
    w1 = f.measure("Router 123 ms")
    assert f._w.get("Router 123 ms") == w1
    Charts.forget_fonts()
    assert not f._w
    c.destroy()
    # Health: the fine, non-core checks fold away in Beginner
    folds0 = dict(app.config.get("appearance.folds", {}) or {})
    try:
        app.config.set("appearance.folds", {})
        beg0 = app.beginner_mode
        app.beginner_mode = True
        app._select_tab("health")
        _gui_pump(root, 0.3)
        ht = app.tabs["health"]
        ht.refresh()
        hidden = ht.folded_keys(app.health_summary())
        assert hidden and not (hidden & set(ht.CORE)), hidden
        packed = {k for k, (_s, _e, row) in ht.rows.items()
                  if row.winfo_manager()}
        assert not (packed & hidden) and set(ht.CORE) <= packed, packed
        assert "(" in str(ht.fold_btn.cget("text"))
        ht.fold_btn.invoke()
        _gui_pump(root, 0.2)
        packed = {k for k, (_s, _e, row) in ht.rows.items()
                  if row.winfo_manager()}
        assert packed == set(ht.rows), packed
        assert app.config.get("appearance.folds")["health"] == "open"
        order = [k for k, _t in ht.CHECKS]
        shown = sorted(ht.rows, key=lambda k: ht.rows[k][2].winfo_y())
        assert shown == order, shown
        # Security: calm sections one line each under Nothing to report
        app.config.set("appearance.folds", {})
        app._select_tab("security")
        _gui_pump(root, 0.3)
        st = app.tabs["security"]
        st.refresh()
        text = st.text.get("1.0", "end")
        assert st.folded_titles, text[:300]
        assert translate_text("Nothing to report") in text
        assert text.index(translate_text("Nothing to report")) > \
            text.index("What is this?")
        st.fold_btn.invoke()
        _gui_pump(root, 0.2)
        text = st.text.get("1.0", "end")
        assert not st.folded_titles
        assert translate_text("Nothing to report") not in text
        assert app.config.get("appearance.folds")["security"] == "open"
    finally:
        app.beginner_mode = beg0
        app.config.set("appearance.folds", folds0)
    # the Inspector and the device card tell the same facts: every claim
    # the Inspector shows is in the card's copied text, with its value
    reg = app.model.registry
    for key in list(reg.by_key)[:8]:
        dev = reg.by_key[key]
        card = app.show_device(key)
        _gui_pump(root, 0.1)
        # the card's plain-text export (Copy report), folded or not
        text = "\n".join(sec[0] + "\n" + card.section_text(sec[1])
                         for sec in card.sections)
        missing = [(lab, val) for lab, val, _lv, _w, _k in
                   device_claims(app.model, dev)
                   if str(val) not in text]
        assert not missing, (dev.display_name(), missing)
        with contextlib.suppress(tk.TclError):
            card.win.destroy()
    # a narrow window lends the Inspector's room to the tabs, and gives
    # it back; the setting is not touched
    geo0 = root.geometry()
    vis_before = app.inspector_visible
    try:
        app.toggle_inspector(True)
        root.geometry(px_geo("1400x800"))
        _gui_pump(root, 0.5)
        assert app.inspector_visible
        root.geometry(px_geo("1000x700"))
        _gui_pump(root, 0.6)
        assert not app.inspector_visible, "Inspector kept at 1000 wide"
        assert app.config.get("appearance.inspector") is True
        root.geometry(px_geo("1400x800"))
        _gui_pump(root, 0.6)
        assert app.inspector_visible, "Inspector not given back"
        assert app.inspector.frame.winfo_width() >= px(200), \
            app.inspector.frame.winfo_width()
        # hidden by the person: stays hidden through a resize
        app.toggle_inspector(False)
        root.geometry(px_geo("1000x700"))
        _gui_pump(root, 0.4)
        root.geometry(px_geo("1400x800"))
        _gui_pump(root, 0.6)
        assert not app.inspector_visible
    finally:
        root.geometry(geo0)
        _gui_pump(root, 0.4)
        app.toggle_inspector(vis_before)
    # Why slow: the window's ranking docks in the Inspector
    vis0 = app.inspector_visible
    win = app.investigate("slow")
    try:
        _gui_pump(root, 0.3, until=lambda: not getattr(
            win, "_mw_checking", False), timeout=12)
        win._mw_dock()
        _gui_pump(root, 0.2)
        assert not win.winfo_exists()
        assert app.inspector_visible
        assert app.inspector.current == ("slow", "")
        want = min(px(Inspector.WIDTH), app.body.winfo_width() // 3)
        _gui_pump(root, 0.3, until=lambda: app.inspector.frame.winfo_width()
                  >= min(px(Inspector.WIDTH), app.body.winfo_width() // 3)
                  - 30, timeout=5)
        want = min(px(Inspector.WIDTH), app.body.winfo_width() // 3)
        assert app.inspector.frame.winfo_width() >= want - 30, (
            app.inspector.frame.winfo_width(), want)
        body = app.inspector.txt.get("1.0", "end")
        assert translate_text("Check again") in body, body[:300]
        hyps = investigate_slow(app.collect_slow_facts())
        assert translate_text(hyps[0]["title"]) in body
        app.inspector._slow_again()
        _gui_pump(root, 0.3, until=lambda: app.inspector.title_var.get()
                  == translate_text("Why is it slow?"), timeout=12)
        assert app.inspector.title_var.get() == \
            translate_text("Why is it slow?")
    finally:
        with contextlib.suppress(tk.TclError):
            win.destroy()
        app.inspector.show("none", "")
        app.toggle_inspector(vis0)


